begin;

-- Kaliganj Travels: NEW, EMPTY database only. No data dump or remote reads.
-- This guard deliberately refuses both populated and empty existing app tables.
do $fresh$
begin
  if exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'f')) then
    raise exception 'FRESH_INSTALL_REQUIRES_EMPTY_PUBLIC_SCHEMA';
  end if;
end $fresh$;

create table public.company_settings (
  id boolean primary key default true check (id),
  display_name text not null check (length(btrim(display_name)) > 0),
  license_number text,
  phone text,
  email text,
  address text
);
alter table public.company_settings enable row level security;
revoke all on public.company_settings from public, anon, authenticated;
grant select, insert, update on public.company_settings to service_role;
insert into public.company_settings (display_name) values ('Kaliganj Travels');

create table public.company_admin_sms_recipients (
  phone text primary key check (phone ~ '^[1-9][0-9]{7,14}$'),
  enabled boolean not null default true
);
alter table public.company_admin_sms_recipients enable row level security;
revoke all on public.company_admin_sms_recipients from public, anon, authenticated;
grant select, insert, update, delete on public.company_admin_sms_recipients to service_role;
-- No phone, email, licence, address, user or payment-account values are invented.


-- SOURCE: 0001_users_and_profiles.sql
-- Kaliganj Travels — user registry + dashboard profiles.
-- Applied with `supabase db push --linked` (project ljzoizsogbirlvlsrwzi).
-- Safe to re-run: every statement is idempotent.
--
-- Access model: no client ever queries these tables. RLS is enabled with NO
-- policies, which denies anon and authenticated outright; the server's
-- service-role key bypasses RLS and is the only way in. Clerk stays the
-- authority on identity and role — app_users mirrors it so the dashboard can
-- list and filter people without paging the Clerk API.

-- ── Shared updated_at trigger ────────────────────────────────────────────
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ── Registry: one row per person who has opened the dashboard ────────────
create table if not exists public.app_users (
  clerk_id     text primary key,
  email        text,
  first_name   text,
  last_name    text,
  -- Mirror of Clerk publicMetadata.role. Never written from the dev role
  -- switcher, so previewing as another role cannot rewrite the real one.
  role         text not null default 'customer',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  last_seen_at timestamptz not null default now()
);

create index if not exists app_users_role_idx on public.app_users (role);
create index if not exists app_users_email_idx on public.app_users (email);

drop trigger if exists app_users_touch_updated_at on public.app_users;
create trigger app_users_touch_updated_at
  before update on public.app_users
  for each row execute function public.touch_updated_at();

-- ── Profiles: the dashboard form, one row per user ───────────────────────
-- Column names are the snake_case of the field names in lib/profile.ts, and
-- lib/db/profiles.ts converts between them mechanically. Renaming a field
-- there means renaming the column here.
--
-- Everything is nullable: a profile is filled in over time, and a half-filled
-- form still saves. Blank inputs are stored as NULL, never ''.
create table if not exists public.user_profiles (
  clerk_id       text primary key
                 references public.app_users (clerk_id) on delete cascade,

  -- Personal
  given_name     text,
  surname        text,
  gender         text,
  date_of_birth  date,
  address        text,

  -- Passport
  nationality    text,
  passport_no    text,
  passport_expiry date,

  -- Contact
  mobile         text,
  email          text,

  -- Business info (B2B)
  agency_name    text,
  agency_address text,
  agency_email   text,
  agency_mobile  text,
  website        text,
  facebook_page  text,

  -- Bank account (B2B + customers)
  bank_name      text,
  account_name   text,
  account_number text,
  routing_number text,
  swift_code     text,
  branch_code    text,

  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

drop trigger if exists user_profiles_touch_updated_at on public.user_profiles;
create trigger user_profiles_touch_updated_at
  before update on public.user_profiles
  for each row execute function public.touch_updated_at();

-- Business documents (trade license, TIN, agency license, NID, agency logo)
-- are deliberately absent — they are files, and land with the upload slice as
-- <name>_path columns pointing into a private Storage bucket.

-- ── Lock both tables down ────────────────────────────────────────────────
alter table public.app_users enable row level security;
alter table public.user_profiles enable row level security;


-- SOURCE: 0002_agencies_and_sub_users.sql
-- Kaliganj Travels — agencies and their sub users.
-- Applied with `supabase db push --linked` (project ljzoizsogbirlvlsrwzi).
-- Safe to re-run: every statement is idempotent.
--
-- A B2B partner is the *owner* of an agency; a Sub User is a *member* of one.
-- The agency is the durable record and `agency_code` is its identity — a
-- branded, human-readable string that can be quoted to support, printed on a
-- report and kept through a change of authentication provider. Nothing here
-- names Clerk, deliberately: `owner_user_id` and `app_users.clerk_id` hold
-- whatever the current provider calls a user id, and the relationship between
-- an agency and its people is expressed entirely in these two tables.
--
-- **This is the source of truth for the parent-agency relationship.** The
-- provider's user metadata may mirror `agency_code` for convenience — an
-- invitation has to carry it before any row exists — but every authorization
-- decision reads the database, never the mirror.

-- ── Agencies ─────────────────────────────────────────────────────────────
-- The code is the primary key, so uniqueness is enforced by Postgres rather
-- than by a check-then-insert in application code, which would race. The
-- generator inserts a candidate and retries on 23505; see lib/db/agencies.ts.
--
-- The format is pinned here as well as in lib/agency.ts. A code that does not
-- match cannot be stored at all, whatever wrote it.
create table if not exists public.agencies (
  agency_code   text primary key
                check (agency_code ~ '^ST-B2B[0-9]{6}$'),

  -- The B2B partner who owns the agency. Nullable and `set null` on delete:
  -- an agency outlives the person who opened it, because its sub users and
  -- its bookings still point at it. An unowned agency is simply one nobody
  -- can administer — every ownership check below fails closed on NULL.
  owner_user_id text unique
                references public.app_users (clerk_id) on delete set null,

  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

drop trigger if exists agencies_touch_updated_at on public.agencies;
create trigger agencies_touch_updated_at
  before update on public.agencies
  for each row execute function public.touch_updated_at();

-- ── Membership ───────────────────────────────────────────────────────────
-- Which agency a person belongs to. Set for both roles: an owner belongs to
-- their own agency, so "everyone in agency X" is one predicate rather than a
-- union of the owner and the members.
--
-- `set null` on delete for the same reason as above — losing the agency row
-- must not delete the people in it.
alter table public.app_users
  add column if not exists agency_code text;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'app_users_agency_code_fkey'
  ) then
    alter table public.app_users
      add constraint app_users_agency_code_fkey
      foreign key (agency_code) references public.agencies (agency_code)
      on delete set null;
  end if;
end $$;

-- Listing an agency's sub users filters on both columns together.
create index if not exists app_users_agency_code_idx
  on public.app_users (agency_code, role);

-- ── Lock it down ─────────────────────────────────────────────────────────
-- Same access model as 0001: RLS on, no policies, which denies anon and
-- authenticated outright. Only the server's service-role key gets in.
alter table public.agencies enable row level security;


-- SOURCE: 0003_staff_details.sql
-- Kaliganj Travels — staff records for agency sub users.
-- Applied with `supabase db push --linked` (project ljzoizsogbirlvlsrwzi).
-- Safe to re-run: every statement is idempotent.
--
-- Deliberately **its own table, not columns on `user_profiles`**. Staff details
-- are employment facts about a person inside an agency; the profile is that
-- person's own travel identity, and the two are not the same record even where
-- a field name repeats. Keeping them apart means:
--
--   * staff fields never reach the company/business sections or the profile
--     completion meter, which counts `user_profiles` columns;
--   * a staff record can be deleted — the point of "remove this person's staff
--     details" — without touching their passport, bank account or login;
--   * `saveProfileAction`, which writes only the session user's own row, stays
--     exactly as strict as it is. Editing someone else's staff record is a
--     different action with its own ownership check, not a loosening of that.
--
-- There is intentionally **no `agency_code` column here.** Which agency a
-- person belongs to is already answered by `app_users.agency_code`, and that is
-- the authority; a copy on this table would be a second answer free to drift
-- from it. Listing an agency's staff joins through `app_users` instead.

create table if not exists public.staff_details (
  -- One record per person. Cascades with the account: deleting a sub user
  -- should not leave their employment details behind.
  user_id           text primary key
                    references public.app_users (clerk_id) on delete cascade,

  designation       text,
  email             text,
  phone             text,
  alternative_phone text,
  address           text,
  qualification     text,

  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

drop trigger if exists staff_details_touch_updated_at on public.staff_details;
create trigger staff_details_touch_updated_at
  before update on public.staff_details
  for each row execute function public.touch_updated_at();

-- Same access model as every other table here: RLS on, no policies, which
-- denies anon and authenticated outright. Only the server's service-role key
-- gets in, and it checks agency ownership before reading or writing a row.
alter table public.staff_details enable row level security;


-- SOURCE: 0004_upgrade_requests.sql
-- Kaliganj Travels — customer → B2B upgrade requests.
-- Applied with `supabase db push --linked` (project ljzoizsogbirlvlsrwzi).
-- Safe to re-run: every statement is idempotent.
--
-- A customer asks to become a B2B partner from the sidebar's "Upgrade to
-- Business" button; an admin accepts or rejects it in Users & Roles. This table
-- is the request, and nothing else: **it never decides anybody's role.** The
-- role still lives in Clerk and `app_users.role`, and an accepted request is a
-- record of the decision, not the mechanism.
--
-- Deliberately **its own table, not columns on `user_profiles`**, for the same
-- reason `staff_details` is:
--
--   * an application is a moment in time — who applied, what they claimed, who
--     decided and when. A profile is current truth, edited freely by its owner.
--     Storing an application in an editable profile would let the applicant
--     change what an admin is reviewing;
--   * these fields never reach the profile completion meter, which counts
--     `user_profiles` columns;
--   * a decided request can be kept for the audit trail long after the profile
--     it seeded has moved on.
--
-- **One row per user, not one per attempt.** A rejected request is resubmitted
-- over the top, which is what makes "does this person have something waiting?"
-- a primary-key lookup rather than a max-by-date over a history. Keeping every
-- attempt is a later migration if it is ever wanted; the reviewer columns below
-- already carry the outcome of the last one.

create table if not exists public.upgrade_requests (
  -- Cascades with the account: deleting someone should not leave their
  -- application behind for an admin to review.
  user_id           text primary key
                    references public.app_users (clerk_id) on delete cascade,

  -- Business info. Required at submission time — `lib/upgrade.ts` is the
  -- contract and the server action enforces it — but nullable here, because a
  -- not-null constraint would make a future "save a draft" a migration.
  agency_name       text,
  business_mobile   text,
  business_email    text,
  business_address  text,

  -- Personal info.
  full_name         text,
  -- Proprietor or Partner. Checked rather than free text: it is a closed set
  -- the reviewer reads at a glance, and a typo would be invisible.
  business_type     text check (business_type in ('proprietor', 'partner')),
  personal_mobile   text,
  personal_address  text,

  -- Supporting documents are deliberately absent, the same way `user_profiles`
  -- leaves out the five B2B uploads: they are files, and they arrive with the
  -- **Cloudinary** slice as a column of provider references. Adding a column
  -- now would be guessing at the shape Cloudinary hands back.

  status            text not null default 'pending'
                    check (status in ('pending', 'accepted', 'rejected')),
  -- Who decided, and when. Null while pending. Not a foreign key: the decision
  -- should outlive the admin's account.
  reviewed_by       text,
  reviewed_at       timestamptz,
  -- The reviewer's note on a rejection, shown to the applicant.
  review_note       text,

  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

-- The roster asks one question of this table — "which of these people have
-- something waiting?" — so the index is on status.
create index if not exists upgrade_requests_status_idx
  on public.upgrade_requests (status);

drop trigger if exists upgrade_requests_touch_updated_at on public.upgrade_requests;
create trigger upgrade_requests_touch_updated_at
  before update on public.upgrade_requests
  for each row execute function public.touch_updated_at();

-- Same access model as every other table here: RLS on, no policies, which
-- denies anon and authenticated outright. Only the server's service-role key
-- gets in, and it checks the role before reading or writing a row.
alter table public.upgrade_requests enable row level security;


-- SOURCE: 0005_document_uploads.sql
-- Kaliganj Travels — file uploads land, backed by Cloudinary.
-- Applied with `supabase db push --linked` (project ljzoizsogbirlvlsrwzi).
-- Safe to re-run: every statement is idempotent.
--
-- This is the slice `0001` and `0004` both deferred to. Two places needed it:
-- a B2B partner's business documents on their company profile, and the
-- attachments on a customer's upgrade application.
--
-- **What is stored is a handle, never a URL.** Each entry is a Cloudinary
-- `public_id` plus the `format` needed to sign a link for it. A stored URL
-- would be one of two wrong things: a public one (these are trade licences,
-- TIN certificates and NID cards) or an expiring one, and an expiring URL in a
-- database is a value that is false for most of its life. Links are minted per
-- view — see `lib/cloudinary.ts`.
--
-- **`jsonb`, not a column pair per document.** The alternative was
-- `trade_license_public_id` + `trade_license_format` and so on: ten columns for
-- the profile, and a migration every time a document type is added or renamed.
-- The set of documents is a product decision that lives in `lib/profile.ts`,
-- and this keeps the schema from having an opinion about it. Nothing is
-- queried *by* document — they are read as a unit with the row that owns them —
-- so there is no index to lose.

-- ── The B2B business documents, on the company profile ───────────────────
--
-- Shape: an object keyed by the file field names in lib/profile.ts, e.g.
--   { "tradeLicense": { "publicId": "...", "format": "pdf", "uploadedAt": "..." } }
-- Absent key means never uploaded. `lib/documents.ts` is the contract.
alter table public.user_profiles
  add column if not exists documents jsonb not null default '{}'::jsonb;

-- ── The upgrade application's attachments ────────────────────────────────
--
-- Shape: an array, because these are unnamed supporting files rather than
-- named slots — the applicant attaches what they have.
--   [ { "publicId": "...", "format": "pdf", "uploadedAt": "..." } ]
alter table public.upgrade_requests
  add column if not exists documents jsonb not null default '[]'::jsonb;

-- Both tables already have RLS enabled with no policies, and adding a column
-- does not change that: anon and authenticated stay denied outright, and the
-- server's service-role key remains the only way in.


-- SOURCE: 0006_markup_rules.sql
-- Kaliganj Travels — Super Admin fare-markup rules.
-- Applied with `supabase db push --linked` (project ljzoizsogbirlvlsrwzi).
--
-- Rules are private commercial data. Browsers never query this table: RLS is
-- enabled with no policies and only the server-side service-role client reads
-- or writes it.

create table if not exists public.markup_rules (
  id              uuid primary key default gen_random_uuid(),
  audience        text not null
                  check (audience in ('b2c', 'agency')),
  agency_code     text
                  references public.agencies (agency_code) on delete cascade,
  airline_code    text not null
                  check (airline_code ~ '^[A-Z0-9]{2}$'),
  origin          text
                  check (origin is null or origin ~ '^[A-Z]{3}$'),
  destination     text
                  check (destination is null or destination ~ '^[A-Z]{3}$'),
  bidirectional   boolean not null default false,
  markup_type     text not null
                  check (markup_type in ('fixed', 'percentage')),
  value           numeric(12, 2) not null,
  active          boolean not null default true,
  created_by      text
                  references public.app_users (clerk_id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  -- B2C rules never name an agency; agency rules always do.
  constraint markup_rules_audience_target_check check (
    (audience = 'b2c' and agency_code is null) or
    (audience = 'agency' and agency_code is not null)
  ),

  -- Airline-only rules leave both route fields empty. Route rules need both.
  constraint markup_rules_route_pair_check check (
    (origin is null and destination is null and bidirectional = false) or
    (origin is not null and destination is not null and origin <> destination)
  ),

  -- A percentage is intentionally capped; a fixed amount is bounded against
  -- accidental extra zeroes while remaining well above a plausible fare.
  constraint markup_rules_value_check check (
    (markup_type = 'percentage' and value > 0 and value <= 100) or
    (markup_type = 'fixed' and value > 0 and value <= 1000000)
  )
);

drop trigger if exists markup_rules_touch_updated_at on public.markup_rules;
create trigger markup_rules_touch_updated_at
  before update on public.markup_rules
  for each row execute function public.touch_updated_at();

-- PostgreSQL treats NULLs as distinct in ordinary unique indexes. Coalescing
-- the nullable target fields makes "B2C + BG" or "Agent X + BG + DAC→CXB"
-- genuinely unique, so two active-looking rows cannot compete silently.
create unique index if not exists markup_rules_scope_unique_idx
  on public.markup_rules (
    audience,
    coalesce(agency_code, ''),
    airline_code,
    coalesce(origin, ''),
    coalesce(destination, ''),
    bidirectional
  );

create index if not exists markup_rules_lookup_idx
  on public.markup_rules (audience, agency_code, airline_code, active);

alter table public.markup_rules enable row level security;


-- SOURCE: 0007_capped_and_lcc_markup.sql
-- Gross-capped normal markup plus an explicit LCC service-margin exception.
--
-- A normal rule can never spend more than the supplier-to-gross margin.
-- `lcc_service_margin = true` is the deliberate, auditable exception that may
-- add a fixed or base-percentage service margin above gross.

alter table public.markup_rules
  add column if not exists lcc_service_margin boolean not null default false;

alter table public.markup_rules
  drop constraint if exists markup_rules_markup_type_check;

alter table public.markup_rules
  add constraint markup_rules_markup_type_check check (
    markup_type in ('fixed', 'percentage', 'margin_share')
  );

alter table public.markup_rules
  drop constraint if exists markup_rules_value_check;

alter table public.markup_rules
  add constraint markup_rules_value_check check (
    (markup_type = 'percentage' and value > 0 and value <= 100) or
    (markup_type = 'fixed' and value > 0 and value <= 1000000) or
    (markup_type = 'margin_share' and value >= 0 and value <= 100)
  );

alter table public.markup_rules
  drop constraint if exists markup_rules_lcc_mode_check;

alter table public.markup_rules
  add constraint markup_rules_lcc_mode_check check (
    lcc_service_margin = false or markup_type in ('fixed', 'percentage')
  );

comment on column public.markup_rules.lcc_service_margin is
  'Explicit LCC-only exception: add this rule above gross as a visible service margin.';


-- SOURCE: 0008_flight_search_quotes.sql
-- Durable, private Search references for the RePrice and Booking pipeline.
--
-- Browser clients receive only the random row id (`searchId`) and our own
-- itinerary ids. Supplier transaction/item/segment/price references and the
-- commercial pricing snapshot stay inside `itinerary_refs`.

create table if not exists public.flight_search_quotes (
  id               uuid primary key,
  unique_trans_id  text not null
                   check (char_length(unique_trans_id) between 1 and 512),
  itinerary_refs   jsonb not null
                   check (jsonb_typeof(itinerary_refs) = 'object'),
  expires_at       timestamptz not null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

drop trigger if exists flight_search_quotes_touch_updated_at
  on public.flight_search_quotes;
create trigger flight_search_quotes_touch_updated_at
  before update on public.flight_search_quotes
  for each row execute function public.touch_updated_at();

create index if not exists flight_search_quotes_expires_at_idx
  on public.flight_search_quotes (expires_at);

alter table public.flight_search_quotes enable row level security;

-- Defense in depth in addition to RLS-with-no-policies. Only the service-role
-- server client may read or mutate supplier references.
revoke all on table public.flight_search_quotes from anon, authenticated;

comment on table public.flight_search_quotes is
  'Private, expiring Triplover Search/RePrice references and pricing snapshots.';


-- SOURCE: 0009_flight_bookings.sql
-- Private booking drafts and the irreversible Triplover Book outcome.

create table if not exists public.flight_bookings (
  id                     uuid primary key,
  access_token_hash      text not null unique
                         check (access_token_hash ~ '^[a-f0-9]{64}$'),
  user_id                text references public.app_users (clerk_id) on delete set null,
  audience               text not null check (audience in ('b2c', 'agency', 'superadmin')),
  agency_code            text,
  search_id              uuid not null,
  itinerary_id           text not null,
  status                 text not null default 'draft'
                         check (status in ('draft', 'submitting', 'held', 'ticketed', 'failed', 'unknown')),
  currency               text not null default 'BDT',
  pricing_snapshot       jsonb not null check (jsonb_typeof(pricing_snapshot) = 'object'),
  passenger_counts       jsonb not null check (jsonb_typeof(passenger_counts) = 'object'),
  travel_date            date not null,
  direct_ticketing       boolean not null default false,
  supplier_refs          jsonb not null check (jsonb_typeof(supplier_refs) = 'object'),
  repriced_at            timestamptz not null,
  accepted_at            timestamptz not null,
  expires_at             timestamptz not null,
  passengers             jsonb,
  pnr                    text,
  airlines_pnr           jsonb,
  booking_ref_number     text,
  booking_status         text,
  ticketing_time_limit   text,
  booking_code_ref       text,
  ticket_code_ref        text,
  ticket_numbers         jsonb,
  warnings               jsonb,
  supplier_message       text,
  error_code             text,
  submission_started_at  timestamptz,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);

drop trigger if exists flight_bookings_touch_updated_at
  on public.flight_bookings;
create trigger flight_bookings_touch_updated_at
  before update on public.flight_bookings
  for each row execute function public.touch_updated_at();

create index if not exists flight_bookings_user_created_idx
  on public.flight_bookings (user_id, created_at desc);
create index if not exists flight_bookings_status_idx
  on public.flight_bookings (status, updated_at desc);
create index if not exists flight_bookings_expires_idx
  on public.flight_bookings (expires_at);

alter table public.flight_bookings enable row level security;
revoke all on table public.flight_bookings from anon, authenticated;

comment on table public.flight_bookings is
  'Private traveller drafts, Triplover Book references, and held/direct-ticket outcomes.';


-- SOURCE: 0010_all_airlines_markup.sql
-- Allow a markup rule to act as the audience-wide fallback for every airline.
-- Existing airline and route rules remain unchanged and take precedence in
-- application code.

alter table public.markup_rules
  alter column airline_code drop not null;

alter table public.markup_rules
  drop constraint if exists markup_rules_airline_code_check;

alter table public.markup_rules
  add constraint markup_rules_airline_code_check check (
    airline_code is null or airline_code ~ '^[A-Z0-9]{2}$'
  );

-- A route exception must still name the airline it belongs to. A null airline
-- is deliberately limited to the all-airlines, all-routes fallback.
alter table public.markup_rules
  drop constraint if exists markup_rules_airline_scope_check;

alter table public.markup_rules
  add constraint markup_rules_airline_scope_check check (
    airline_code is not null or (
      origin is null and
      destination is null and
      bidirectional = false and
      lcc_service_margin = false
    )
  );

-- Include the nullable airline target in uniqueness. Without COALESCE,
-- PostgreSQL would allow several identical global rules because NULL values
-- are distinct in a conventional unique index.
drop index if exists public.markup_rules_scope_unique_idx;

create unique index markup_rules_scope_unique_idx
  on public.markup_rules (
    audience,
    coalesce(agency_code, ''),
    coalesce(airline_code, ''),
    coalesce(origin, ''),
    coalesce(destination, ''),
    bidirectional
  );

comment on column public.markup_rules.airline_code is
  'Two-character airline code, or NULL for an all-airlines and all-routes fallback.';


-- SOURCE: 0011_all_airlines_route_markup.sql
-- Extend all-airlines markup from the global fallback to optional route
-- coverage. The existing route-pair constraint still requires both airport
-- codes and prevents identical origins and destinations.

alter table public.markup_rules
  drop constraint if exists markup_rules_airline_scope_check;

-- Above-gross LCC exceptions remain tied to a named airline. Normal capped
-- markup may target every airline globally or on a specific route.
alter table public.markup_rules
  add constraint markup_rules_airline_scope_check check (
    airline_code is not null or lcc_service_margin = false
  );

comment on column public.markup_rules.airline_code is
  'Two-character airline code, or NULL to target every airline globally or on a specific route.';


-- SOURCE: 0012_all_b2b_markup_audience.sql
-- Add an all-B2B audience for rules shared by every agency and its sub-users.
-- Agency-specific rules remain separate and take precedence in application
-- code when both audiences match.

alter table public.markup_rules
  drop constraint if exists markup_rules_audience_check;

alter table public.markup_rules
  add constraint markup_rules_audience_check check (
    audience in ('b2c', 'b2b', 'agency')
  );

alter table public.markup_rules
  drop constraint if exists markup_rules_audience_target_check;

alter table public.markup_rules
  add constraint markup_rules_audience_target_check check (
    (audience in ('b2c', 'b2b') and agency_code is null) or
    (audience = 'agency' and agency_code is not null)
  );

comment on column public.markup_rules.audience is
  'b2c for public customers, b2b for every agency and sub-user, or agency for one named agency.';


-- SOURCE: 0013_negative_markup_discounts.sql
-- Permit Super Admins to configure bounded discounts with negative fixed or
-- base-percentage values. Margin share remains a 0–100% selector, and the
-- explicit LCC above-gross exception remains positive-only.

alter table public.markup_rules
  drop constraint if exists markup_rules_value_check;

alter table public.markup_rules
  add constraint markup_rules_value_check check (
    (
      markup_type = 'percentage' and
      value <> 0 and
      value >= -100 and
      value <= 100
    ) or
    (
      markup_type = 'fixed' and
      value <> 0 and
      value >= -1000000 and
      value <= 1000000
    ) or
    (
      markup_type = 'margin_share' and
      value >= 0 and
      value <= 100
    )
  );

alter table public.markup_rules
  drop constraint if exists markup_rules_lcc_mode_check;

alter table public.markup_rules
  add constraint markup_rules_lcc_mode_check check (
    lcc_service_margin = false or (
      markup_type in ('fixed', 'percentage') and
      value > 0
    )
  );

comment on column public.markup_rules.value is
  'Positive markup or negative discount for fixed/percentage rules; 0–100 for margin share.';


-- SOURCE: 0014_prevent_overlapping_markup_routes.sql
-- Prevent route rules whose directionality makes them compete for the same
-- itinerary. Opposite one-way rules are valid; a bidirectional rule conflicts
-- with either one-way direction for the same audience and airline scope.

do $$
begin
  if exists (
    select 1
    from public.markup_rules first_rule
    join public.markup_rules second_rule
      on first_rule.id::text < second_rule.id::text
     and first_rule.audience = second_rule.audience
     and first_rule.agency_code is not distinct from second_rule.agency_code
     and first_rule.airline_code is not distinct from second_rule.airline_code
     and first_rule.origin is not null
     and second_rule.origin is not null
     and (
       (
         first_rule.origin = second_rule.origin and
         first_rule.destination = second_rule.destination
       ) or (
         (first_rule.bidirectional or second_rule.bidirectional) and
         first_rule.origin = second_rule.destination and
         first_rule.destination = second_rule.origin
       )
     )
  ) then
    raise exception
      'Existing markup rules contain overlapping route scopes. Resolve them before applying migration 0014.';
  end if;
end
$$;

create or replace function public.prevent_overlapping_markup_routes()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.origin is null then
    return new;
  end if;

  if exists (
    select 1
    from public.markup_rules existing
    where existing.id is distinct from new.id
      and existing.audience = new.audience
      and existing.agency_code is not distinct from new.agency_code
      and existing.airline_code is not distinct from new.airline_code
      and existing.origin is not null
      and (
        (
          existing.origin = new.origin and
          existing.destination = new.destination
        ) or (
          (existing.bidirectional or new.bidirectional) and
          existing.origin = new.destination and
          existing.destination = new.origin
        )
      )
  ) then
    raise exception using
      errcode = '23505',
      constraint = 'markup_rules_route_overlap_check',
      message =
        'A markup rule already overlaps this audience, airline, and route.';
  end if;

  return new;
end
$$;

drop trigger if exists markup_rules_prevent_route_overlap
  on public.markup_rules;

create trigger markup_rules_prevent_route_overlap
  before insert or update on public.markup_rules
  for each row execute function public.prevent_overlapping_markup_routes();

comment on function public.prevent_overlapping_markup_routes() is
  'Rejects duplicate or bidirectionally overlapping markup route scopes while allowing opposite one-way rules.';


-- SOURCE: 0015_booking_itinerary_snapshot.sql
-- Checkout renders the flights, the per-passenger money and the passport rule
-- from the draft alone, so none of it may depend on the Search results page
-- still being open (or on the 20-minute quote row still existing).
--
-- All three are nullable: drafts created before this migration keep working,
-- and the checkout page degrades to the totals it already had.

alter table public.flight_bookings
  add column if not exists itinerary jsonb
    check (itinerary is null or jsonb_typeof(itinerary) = 'object');

alter table public.flight_bookings
  add column if not exists fares jsonb
    check (fares is null or jsonb_typeof(fares) = 'array');

-- Null means "unknown, ask for a passport" — the safe default for any row
-- written before the country rule existed.
alter table public.flight_bookings
  add column if not exists passport_required boolean;


-- SOURCE: 0016_booking_attempts.sql
-- The operational layer: one row per fare selection that may become a booking.
--
-- This table exists for reliability, not for business reporting. It records
-- everything needed to recover from a lost supplier answer — the reference
-- chain in particular, which per the supplier contract cannot be re-derived —
-- and it is written *before* the irreversible Book call so that an orphaned
-- PNR is always traceable.
--
-- Step 1 of BOOKING_ARCHITECTURE.md. Nothing reads this table yet: the current
-- flow still treats `flight_bookings` as authoritative and mirrors into here.
-- During that window an attempt shares the id of the draft it mirrors, so the
-- two are trivially correlated; from step 2 the attempt id stands alone.

create table if not exists public.booking_attempts (
  id                 uuid primary key,
  -- The checkout capability, same scheme as flight_bookings today.
  access_token_hash  text not null unique
                     check (access_token_hash ~ '^[a-f0-9]{64}$'),
  user_id            text references public.app_users (clerk_id) on delete set null,
  audience           text not null
                     check (audience in ('b2c', 'agency', 'superadmin')),
  agency_code        text,
  supplier           text not null default 'triplover',
  state              text not null default 'draft'
                     check (state in ('draft', 'submitting', 'succeeded', 'failed', 'unknown')),

  search_id          uuid not null,
  itinerary_id       text not null,

  -- Recovery keys. Present from the moment the attempt is created; the last
  -- two arrive only with a successful Book response.
  unique_trans_id    text not null,
  item_code_ref      text not null,
  price_code_ref     text not null,
  booking_code_ref   text,
  pnr                text,

  -- Self-sufficient copies: flight_search_quotes expires in 20 minutes and the
  -- attempt has to stay meaningful long after that.
  offer_snapshot     jsonb not null check (jsonb_typeof(offer_snapshot) = 'object'),
  passenger_snapshot jsonb,

  error_code         text,
  supplier_message   text,
  warnings           jsonb,

  -- Quote expiry. Bounds `draft` only; a submitted attempt is not released.
  expires_at         timestamptz not null,
  submitted_at       timestamptz,
  resolved_at        timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

drop trigger if exists booking_attempts_touch_updated_at
  on public.booking_attempts;
create trigger booking_attempts_touch_updated_at
  before update on public.booking_attempts
  for each row execute function public.touch_updated_at();

create index if not exists booking_attempts_user_created_idx
  on public.booking_attempts (user_id, created_at desc);
create index if not exists booking_attempts_state_idx
  on public.booking_attempts (state, updated_at desc);
-- The orphan sweep: attempts that went to the supplier and never came back.
create index if not exists booking_attempts_in_flight_idx
  on public.booking_attempts (submitted_at)
  where state = 'submitting';
-- Reconciliation against the supplier is keyed on the transaction id.
create index if not exists booking_attempts_unique_trans_idx
  on public.booking_attempts (unique_trans_id);

alter table public.booking_attempts enable row level security;
revoke all on table public.booking_attempts from anon, authenticated;

comment on table public.booking_attempts is
  'Durable record of every fare selection sent, or about to be sent, to a supplier. Audit and recovery only — never a business booking.';
comment on column public.booking_attempts.state is
  'draft | submitting | succeeded | failed | unknown. Never a business booking status.';
comment on column public.booking_attempts.offer_snapshot is
  'Itinerary, fares, pricing, passenger counts and flags as they stood when the fare was selected.';


-- SOURCE: 0017_booking_lifecycle.sql
-- The business lifecycle, public references, and atomic booking finalization.
--
-- This is the additive half of Step 3. Legacy operational rows are copied to
-- booking_attempts and retained in flight_bookings with legacy_operational =
-- true. They are excluded from business reads and removed only by a later,
-- separately approved cleanup migration after production verification.

-- 1. Public reference series -------------------------------------------------

create table if not exists public.booking_ref_counters (
  ref_date   date primary key,
  last_value integer not null default 0 check (last_value >= 0),
  updated_at timestamptz not null default now()
);

alter table public.booking_ref_counters enable row level security;
revoke all on table public.booking_ref_counters from anon, authenticated;
grant select, insert, update on table public.booking_ref_counters
  to service_role;

comment on table public.booking_ref_counters is
  'One row per Dhaka day holding the last public booking reference issued.';

create or replace function public.allocate_booking_ref_for(p_date date)
returns text
language plpgsql
as $$
declare
  v_next integer;
begin
  insert into public.booking_ref_counters as c (ref_date, last_value)
  values (p_date, 1)
  on conflict (ref_date) do update
    set last_value = c.last_value + 1,
        updated_at = now()
  returning c.last_value into v_next;

  return 'STR' || to_char(p_date, 'YYMMDD') || lpad(v_next::text, 6, '0');
end;
$$;

create or replace function public.allocate_booking_ref()
returns text
language sql
as $$
  select public.allocate_booking_ref_for(
    (now() at time zone 'Asia/Dhaka')::date
  );
$$;

revoke execute on function public.allocate_booking_ref_for(date)
  from public, anon, authenticated;
revoke execute on function public.allocate_booking_ref()
  from public, anon, authenticated;
grant execute on function public.allocate_booking_ref_for(date)
  to service_role;
grant execute on function public.allocate_booking_ref()
  to service_role;

-- Triplover Booking returns DD/MM/YYYY HH24:MI:SS in production. The ISO
-- branch preserves compatibility with older fixtures and imported rows.
create or replace function public.parse_triplover_booking_deadline(p_value text)
returns timestamptz
language plpgsql
stable
as $$
declare
  v_value text := nullif(trim(p_value), '');
  v_match text[];
begin
  if v_value is null then
    return null;
  end if;

  v_match := regexp_match(
    v_value,
    '^([0-9]{2})/([0-9]{2})/([0-9]{4}) ([0-9]{2}):([0-9]{2}):([0-9]{2})$'
  );
  if v_match is not null then
    return make_timestamptz(
      v_match[3]::integer,
      v_match[2]::integer,
      v_match[1]::integer,
      v_match[4]::integer,
      v_match[5]::integer,
      v_match[6]::double precision,
      'Asia/Dhaka'
    );
  end if;

  v_match := regexp_match(
    v_value,
    '^([0-9]{4})-([0-9]{2})-([0-9]{2})[ T]([0-9]{2}):([0-9]{2}):([0-9]{2})$'
  );
  if v_match is not null then
    return make_timestamptz(
      v_match[1]::integer,
      v_match[2]::integer,
      v_match[3]::integer,
      v_match[4]::integer,
      v_match[5]::integer,
      v_match[6]::double precision,
      'Asia/Dhaka'
    );
  end if;

  return null;
end;
$$;

revoke execute on function public.parse_triplover_booking_deadline(text)
  from public, anon, authenticated;
grant execute on function public.parse_triplover_booking_deadline(text)
  to service_role;

-- 2. Additive lifecycle columns ---------------------------------------------

alter table public.flight_bookings
  add column if not exists public_ref text,
  add column if not exists attempt_id uuid references public.booking_attempts (id),
  add column if not exists supplier text not null default 'triplover',
  add column if not exists ticketing_deadline_at timestamptz,
  add column if not exists deadline_source text
    check (deadline_source in ('supplier', 'pnr_call', 'assumed')),
  add column if not exists issued_at timestamptz,
  add column if not exists cancelled_at timestamptz,
  add column if not exists cancelled_by text,
  add column if not exists cancel_reason text,
  add column if not exists synced_at timestamptz,
  -- Defaults true for the short database-first rollout window: the pre-Step-3
  -- application can still insert old draft rows safely. The Step-3 RPC always
  -- writes false explicitly.
  add column if not exists legacy_operational boolean not null default true;

-- New business rows no longer carry either value, but retained legacy rows do.
-- Drop only NOT NULL; the columns themselves remain until verified cleanup.
alter table public.flight_bookings
  alter column access_token_hash drop not null,
  alter column expires_at drop not null;

-- Preserve the historical updated_at values while the migration backfills
-- structural columns. Normal writes resume trigger maintenance afterwards.
alter table public.flight_bookings
  disable trigger flight_bookings_touch_updated_at;

-- 3. Copy legacy operational rows without deleting them ---------------------

insert into public.booking_attempts (
  id, access_token_hash, user_id, audience, agency_code, supplier, state,
  search_id, itinerary_id, unique_trans_id, item_code_ref, price_code_ref,
  booking_code_ref, pnr, offer_snapshot, passenger_snapshot, error_code,
  expires_at, submitted_at, resolved_at, created_at
)
select
  fb.id,
  fb.access_token_hash,
  fb.user_id,
  fb.audience,
  fb.agency_code,
  'triplover',
  case fb.status
    when 'draft' then 'draft'
    when 'submitting' then 'submitting'
    when 'failed' then 'failed'
    else 'unknown'
  end,
  fb.search_id,
  fb.itinerary_id,
  coalesce(fb.supplier_refs->>'uniqueTransId', ''),
  coalesce(fb.supplier_refs->>'itemCodeRef', ''),
  coalesce(fb.supplier_refs->>'priceCodeRef', ''),
  fb.booking_code_ref,
  fb.pnr,
  jsonb_build_object(
    'itinerary', fb.itinerary,
    'fares', coalesce(fb.fares, '[]'::jsonb),
    'currency', fb.currency,
    'pricing', fb.pricing_snapshot,
    'passengerCounts', fb.passenger_counts,
    'travelDate', fb.travel_date::text,
    'directTicketing', fb.direct_ticketing,
    'passportRequired', coalesce(fb.passport_required, true),
    'repricedAt', fb.repriced_at::text
  ),
  fb.passengers,
  fb.error_code,
  fb.expires_at,
  fb.submission_started_at,
  case when fb.status in ('failed', 'unknown') then fb.updated_at end,
  fb.created_at
from public.flight_bookings fb
where fb.status in ('draft', 'submitting', 'failed', 'unknown');

do $$
begin
  if exists (
    select 1
      from public.flight_bookings fb
      left join public.booking_attempts ba
        on ba.id = fb.id
       and ba.access_token_hash = fb.access_token_hash
     where fb.status in ('draft', 'submitting', 'failed', 'unknown')
       and ba.id is null
  ) then
    raise exception 'legacy booking attempt copy verification failed';
  end if;
end;
$$;

-- 4. Give the five existing business bookings synthetic attempts ------------

insert into public.booking_attempts (
  id, access_token_hash, user_id, audience, agency_code, supplier, state,
  search_id, itinerary_id, unique_trans_id, item_code_ref, price_code_ref,
  booking_code_ref, pnr, offer_snapshot, passenger_snapshot,
  expires_at, submitted_at, resolved_at, created_at
)
select
  gen_random_uuid(),
  fb.access_token_hash,
  fb.user_id,
  fb.audience,
  fb.agency_code,
  'triplover',
  'succeeded',
  fb.search_id,
  fb.itinerary_id,
  coalesce(fb.supplier_refs->>'uniqueTransId', ''),
  coalesce(fb.supplier_refs->>'itemCodeRef', ''),
  coalesce(fb.supplier_refs->>'priceCodeRef', ''),
  fb.booking_code_ref,
  fb.pnr,
  jsonb_build_object(
    'itinerary', fb.itinerary,
    'fares', coalesce(fb.fares, '[]'::jsonb),
    'currency', fb.currency,
    'pricing', fb.pricing_snapshot,
    'passengerCounts', fb.passenger_counts,
    'travelDate', fb.travel_date::text,
    'directTicketing', fb.direct_ticketing,
    'passportRequired', coalesce(fb.passport_required, true),
    'repricedAt', fb.repriced_at::text
  ),
  fb.passengers,
  fb.expires_at,
  fb.submission_started_at,
  fb.updated_at,
  fb.created_at
from public.flight_bookings fb
where fb.status in ('held', 'ticketed')
  and fb.attempt_id is null;

update public.flight_bookings fb
   set attempt_id = ba.id
  from public.booking_attempts ba
 where ba.access_token_hash = fb.access_token_hash
   and ba.state = 'succeeded'
   and fb.status in ('held', 'ticketed')
   and fb.attempt_id is null;

do $$
begin
  if exists (
    select 1
      from public.flight_bookings
     where status in ('held', 'ticketed')
       and attempt_id is null
  ) then
    raise exception 'business booking attempt backfill verification failed';
  end if;
end;
$$;

-- Allocate historical references in deterministic creation order.
do $$
declare
  r record;
begin
  for r in
    select id, (created_at at time zone 'Asia/Dhaka')::date as ref_date
      from public.flight_bookings
     where status in ('held', 'ticketed')
       and public_ref is null
     order by created_at, id
  loop
    update public.flight_bookings
       set public_ref = public.allocate_booking_ref_for(r.ref_date)
     where id = r.id;
  end loop;
end;
$$;

-- Refuse to continue if Triplover supplied a non-empty deadline format this
-- migration does not understand.
do $$
begin
  if exists (
    select 1
      from public.flight_bookings
     where status in ('held', 'ticketed')
       and nullif(trim(ticketing_time_limit), '') is not null
       and public.parse_triplover_booking_deadline(ticketing_time_limit) is null
  ) then
    raise exception 'unrecognised Triplover ticketing_time_limit format';
  end if;
end;
$$;

-- Remove the old six-value constraint before writing the new vocabulary. The
-- replacement transitional constraint is installed immediately afterwards in
-- the same migration transaction.
alter table public.flight_bookings
  drop constraint if exists flight_bookings_status_check;

update public.flight_bookings
   set status = case
                  when status = 'ticketed' then 'confirmed'
                  else 'on-hold'
                end,
       legacy_operational = false,
       issued_at = case when status = 'ticketed' then updated_at end,
       ticketing_deadline_at =
         public.parse_triplover_booking_deadline(ticketing_time_limit),
       deadline_source = case
         when nullif(trim(ticketing_time_limit), '') is not null then 'supplier'
         else null
       end
 where status in ('held', 'ticketed');

-- 5. Transitional constraints and indexes ----------------------------------

alter table public.flight_bookings
  add constraint flight_bookings_status_check
  check (
    (
      legacy_operational
      and status in ('draft', 'submitting', 'held', 'ticketed', 'failed', 'unknown')
    )
    or
    (
      not legacy_operational
      and status in ('on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled')
    )
  );

-- A business booking is always complete. Retained legacy rows are the only
-- rows allowed to omit the new relationship and public reference.
alter table public.flight_bookings
  add constraint flight_bookings_business_identity_check
  check (
    legacy_operational
    or (public_ref is not null and attempt_id is not null)
  );

alter table public.flight_bookings
  add constraint flight_bookings_public_ref_format_check
  check (public_ref is null or public_ref ~ '^STR[0-9]{12}$');

create unique index if not exists flight_bookings_public_ref_key
  on public.flight_bookings (public_ref);
create unique index if not exists flight_bookings_attempt_id_key
  on public.flight_bookings (attempt_id);
create index if not exists flight_bookings_deadline_idx
  on public.flight_bookings (ticketing_deadline_at)
  where status = 'on-hold' and not legacy_operational;
create index if not exists flight_bookings_business_created_idx
  on public.flight_bookings (created_at desc)
  where not legacy_operational;

comment on column public.flight_bookings.public_ref is
  'Customer-facing reference, STRYYMMDD###### (e.g. STR260801000001).';
comment on column public.flight_bookings.status is
  'Business state for non-legacy rows. Expired and Unconfirmed are computed.';
comment on column public.flight_bookings.legacy_operational is
  'True only for retained pre-attempt operational rows pending verified cleanup.';

alter table public.flight_bookings
  enable trigger flight_bookings_touch_updated_at;

-- 6. Atomic, validated, idempotent success path -----------------------------

create or replace function public.create_booking_from_attempt(
  p_attempt_id uuid,
  p_outcome jsonb
)
returns public.flight_bookings
language plpgsql
as $$
declare
  v_attempt public.booking_attempts;
  v_offer jsonb;
  v_booking public.flight_bookings;
  v_status text;
  v_pnr text;
  v_booking_code_ref text;
  v_ticket_code_ref text;
  v_ttl text;
  v_deadline timestamptz;
begin
  -- Lock by id first, then decide whether this is a new finalization or an
  -- idempotent replay. A concurrent replay waits here until the first call has
  -- either committed or rolled back.
  select * into v_attempt
    from public.booking_attempts
   where id = p_attempt_id
   for update;

  if not found then
    raise exception 'booking attempt % does not exist', p_attempt_id
      using errcode = 'P0002';
  end if;

  select * into v_booking
    from public.flight_bookings
   where attempt_id = p_attempt_id
     and not legacy_operational;

  if found then
    if v_attempt.state = 'submitting' then
      update public.booking_attempts
         set state = 'succeeded',
             pnr = coalesce(v_attempt.pnr, v_booking.pnr),
             booking_code_ref = coalesce(
               v_attempt.booking_code_ref,
               v_booking.booking_code_ref
             ),
             resolved_at = coalesce(v_attempt.resolved_at, now())
       where id = p_attempt_id;
    elsif v_attempt.state <> 'succeeded' then
      raise exception 'booking attempt % conflicts with an existing booking',
        p_attempt_id using errcode = '23514';
    end if;
    return v_booking;
  end if;

  if v_attempt.state <> 'submitting' then
    raise exception 'booking attempt % is not awaiting an outcome', p_attempt_id
      using errcode = 'P0002';
  end if;

  if p_outcome is null or jsonb_typeof(p_outcome) <> 'object' then
    raise exception 'supplier outcome must be a JSON object'
      using errcode = '22023';
  end if;

  v_status := nullif(trim(p_outcome->>'status'), '');
  v_pnr := nullif(trim(p_outcome->>'pnr'), '');
  v_booking_code_ref := nullif(trim(p_outcome->>'bookingCodeRef'), '');
  v_ticket_code_ref := nullif(trim(p_outcome->>'ticketCodeRef'), '');
  v_ttl := nullif(trim(p_outcome->>'ticketingTimeLimit'), '');

  if v_status is null or v_status not in ('held', 'ticketed') then
    raise exception 'supplier outcome has invalid status %', v_status
      using errcode = '22023';
  end if;
  if v_pnr is null then
    raise exception 'supplier outcome has no PNR' using errcode = '22023';
  end if;
  if v_booking_code_ref is null then
    raise exception 'supplier outcome has no bookingCodeRef'
      using errcode = '22023';
  end if;
  if v_status = 'ticketed' and v_ticket_code_ref is null then
    raise exception 'ticketed supplier outcome has no ticketCodeRef'
      using errcode = '22023';
  end if;
  if nullif(trim(v_attempt.unique_trans_id), '') is null
     or nullif(trim(v_attempt.item_code_ref), '') is null
     or nullif(trim(v_attempt.price_code_ref), '') is null then
    raise exception 'booking attempt is missing required supplier references'
      using errcode = '22023';
  end if;
  if p_outcome ? 'airlinesPnr'
     and jsonb_typeof(p_outcome->'airlinesPnr') <> 'array' then
    raise exception 'supplier outcome airlinesPnr must be an array'
      using errcode = '22023';
  end if;
  if p_outcome ? 'ticketNumbers'
     and jsonb_typeof(p_outcome->'ticketNumbers') <> 'array' then
    raise exception 'supplier outcome ticketNumbers must be an array'
      using errcode = '22023';
  end if;
  if p_outcome ? 'warnings'
     and jsonb_typeof(p_outcome->'warnings') <> 'array' then
    raise exception 'supplier outcome warnings must be an array'
      using errcode = '22023';
  end if;

  v_deadline := public.parse_triplover_booking_deadline(v_ttl);
  if v_ttl is not null and v_deadline is null then
    raise exception 'unrecognised Triplover ticketingTimeLimit format: %', v_ttl
      using errcode = '22007';
  end if;

  v_offer := v_attempt.offer_snapshot;

  insert into public.flight_bookings (
    id, public_ref, attempt_id, supplier, user_id, audience, agency_code,
    search_id, itinerary_id, status, currency, pricing_snapshot,
    passenger_counts, travel_date, direct_ticketing, itinerary, fares,
    passport_required, supplier_refs, repriced_at, accepted_at, passengers,
    pnr, airlines_pnr, booking_ref_number, booking_status, ticketing_time_limit,
    ticketing_deadline_at, deadline_source, booking_code_ref, ticket_code_ref,
    ticket_numbers, warnings, supplier_message, issued_at,
    submission_started_at, legacy_operational
  )
  values (
    gen_random_uuid(),
    public.allocate_booking_ref(),
    v_attempt.id,
    v_attempt.supplier,
    v_attempt.user_id,
    v_attempt.audience,
    v_attempt.agency_code,
    v_attempt.search_id,
    v_attempt.itinerary_id,
    case when v_status = 'ticketed' then 'confirmed' else 'on-hold' end,
    v_offer->>'currency',
    v_offer->'pricing',
    v_offer->'passengerCounts',
    (v_offer->>'travelDate')::date,
    coalesce((v_offer->>'directTicketing')::boolean, false),
    nullif(v_offer->'itinerary', 'null'::jsonb),
    coalesce(nullif(v_offer->'fares', 'null'::jsonb), '[]'::jsonb),
    coalesce((v_offer->>'passportRequired')::boolean, true),
    jsonb_build_object(
      'uniqueTransId', v_attempt.unique_trans_id,
      'itemCodeRef', v_attempt.item_code_ref,
      'priceCodeRef', v_attempt.price_code_ref
    ),
    (v_offer->>'repricedAt')::timestamptz,
    v_attempt.created_at,
    v_attempt.passenger_snapshot,
    v_pnr,
    coalesce(p_outcome->'airlinesPnr', '[]'::jsonb),
    p_outcome->>'bookingRefNumber',
    p_outcome->>'bookingStatus',
    v_ttl,
    v_deadline,
    case when v_deadline is not null then 'supplier' else null end,
    v_booking_code_ref,
    v_ticket_code_ref,
    coalesce(p_outcome->'ticketNumbers', '[]'::jsonb),
    coalesce(p_outcome->'warnings', '[]'::jsonb),
    p_outcome->>'message',
    case when v_status = 'ticketed' then now() end,
    coalesce(v_attempt.submitted_at, now()),
    false
  )
  returning * into v_booking;

  update public.booking_attempts
     set state = 'succeeded',
         pnr = v_pnr,
         booking_code_ref = v_booking_code_ref,
         supplier_message = p_outcome->>'message',
         warnings = coalesce(p_outcome->'warnings', '[]'::jsonb),
         resolved_at = now()
   where id = p_attempt_id;

  return v_booking;
end;
$$;

revoke execute on function public.create_booking_from_attempt(uuid, jsonb)
  from public, anon, authenticated;
grant execute on function public.create_booking_from_attempt(uuid, jsonb)
  to service_role;

comment on function public.create_booking_from_attempt(uuid, jsonb) is
  'Validates supplier success, atomically creates a booking, and returns the existing row on replay.';


-- SOURCE: 0018_security_hardening.sql
-- Shared security primitives for route and dashboard hardening.

-- 1. Atomic, deployment-wide rate limits -----------------------------------

create table if not exists public.security_rate_limits (
  key        text primary key check (char_length(key) between 1 and 512),
  count      integer not null check (count >= 1),
  reset_at   timestamptz not null,
  updated_at timestamptz not null default now()
);

create index if not exists security_rate_limits_reset_at_idx
  on public.security_rate_limits (reset_at);

alter table public.security_rate_limits enable row level security;
revoke all on table public.security_rate_limits from public, anon, authenticated;
grant select, insert, update, delete on table public.security_rate_limits
  to service_role;

create or replace function public.consume_security_rate_limit(
  p_key text,
  p_limit integer,
  p_window_ms bigint
)
returns table (allowed boolean, retry_after_seconds integer)
language plpgsql
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_count integer;
  v_reset_at timestamptz;
begin
  if p_key is null or char_length(p_key) not between 1 and 512 then
    raise exception 'rate-limit key is invalid' using errcode = '22023';
  end if;
  if p_limit < 1 or p_window_ms < 1000 then
    raise exception 'rate-limit policy is invalid' using errcode = '22023';
  end if;

  -- The indexed delete bounds cardinality even when public callers continually
  -- introduce new address keys and no booking-retention pass happens that day.
  delete from public.security_rate_limits
   where reset_at < v_now - interval '1 day';

  insert into public.security_rate_limits as limits (
    key, count, reset_at, updated_at
  )
  values (
    p_key,
    1,
    v_now + make_interval(secs => p_window_ms::double precision / 1000),
    v_now
  )
  on conflict (key) do update
    set count = case
          when limits.reset_at <= v_now then 1
          else limits.count + 1
        end,
        reset_at = case
          when limits.reset_at <= v_now
            then v_now + make_interval(
              secs => p_window_ms::double precision / 1000
            )
          else limits.reset_at
        end,
        updated_at = v_now
  returning count, reset_at into v_count, v_reset_at;

  allowed := v_count <= p_limit;
  retry_after_seconds := greatest(
    1,
    ceil(extract(epoch from (v_reset_at - v_now)))::integer
  );
  return next;
end;
$$;

revoke execute on function public.consume_security_rate_limit(text, integer, bigint)
  from public, anon, authenticated;
grant execute on function public.consume_security_rate_limit(text, integer, bigint)
  to service_role;

comment on function public.consume_security_rate_limit(text, integer, bigint) is
  'Atomically consumes one deployment-wide allowance and returns its retry window.';

-- 2. Cross-instance lock for privileged identity mutations -----------------

create table if not exists public.security_operation_locks (
  name         text primary key check (char_length(name) between 1 and 100),
  holder       uuid not null,
  locked_until timestamptz not null,
  updated_at   timestamptz not null default now()
);

alter table public.security_operation_locks enable row level security;
revoke all on table public.security_operation_locks
  from public, anon, authenticated;
grant select, insert, update, delete on table public.security_operation_locks
  to service_role;

create or replace function public.try_acquire_security_lock(
  p_name text,
  p_holder uuid,
  p_lease_seconds integer default 60
)
returns boolean
language plpgsql
as $$
declare
  v_acquired boolean := false;
  v_now timestamptz := clock_timestamp();
begin
  if p_name is null or char_length(p_name) not between 1 and 100 then
    raise exception 'security lock name is invalid' using errcode = '22023';
  end if;
  if p_holder is null or p_lease_seconds not between 5 and 300 then
    raise exception 'security lock lease is invalid' using errcode = '22023';
  end if;

  insert into public.security_operation_locks as locks (
    name, holder, locked_until, updated_at
  )
  values (
    p_name,
    p_holder,
    v_now + make_interval(secs => p_lease_seconds),
    v_now
  )
  on conflict (name) do update
    set holder = excluded.holder,
        locked_until = excluded.locked_until,
        updated_at = excluded.updated_at
    where locks.locked_until <= v_now
       or locks.holder = p_holder
  returning true into v_acquired;

  return coalesce(v_acquired, false);
end;
$$;

create or replace function public.release_security_lock(
  p_name text,
  p_holder uuid
)
returns boolean
language plpgsql
as $$
declare
  v_row_count bigint;
begin
  delete from public.security_operation_locks
   where name = p_name
     and holder = p_holder;
  get diagnostics v_row_count = row_count;
  return v_row_count > 0;
end;
$$;

revoke execute on function public.try_acquire_security_lock(text, uuid, integer)
  from public, anon, authenticated;
revoke execute on function public.release_security_lock(text, uuid)
  from public, anon, authenticated;
grant execute on function public.try_acquire_security_lock(text, uuid, integer)
  to service_role;
grant execute on function public.release_security_lock(text, uuid)
  to service_role;

-- 3. Durable security audit trail ------------------------------------------

create table if not exists public.security_audit_events (
  id            uuid primary key default gen_random_uuid(),
  actor_user_id text not null check (char_length(actor_user_id) between 1 and 255),
  actor_role    text not null check (char_length(actor_role) between 1 and 50),
  action        text not null check (char_length(action) between 1 and 100),
  target_type   text not null check (char_length(target_type) between 1 and 50),
  target_id     text check (target_id is null or char_length(target_id) <= 512),
  outcome       text not null default 'succeeded'
                check (outcome in ('attempted', 'succeeded', 'failed', 'denied')),
  metadata      jsonb not null default '{}'::jsonb
                check (jsonb_typeof(metadata) = 'object'),
  created_at    timestamptz not null default now()
);

create index if not exists security_audit_events_actor_created_idx
  on public.security_audit_events (actor_user_id, created_at desc);
create index if not exists security_audit_events_target_created_idx
  on public.security_audit_events (target_type, target_id, created_at desc);

alter table public.security_audit_events enable row level security;
revoke all on table public.security_audit_events
  from public, anon, authenticated;
grant insert, select on table public.security_audit_events to service_role;

comment on table public.security_audit_events is
  'Append-only server-side trail of privileged identity and sensitive-data operations.';

-- 4. Booking-attempt sensitive-data retention ------------------------------

create or replace function public.clear_succeeded_attempt_passengers()
returns trigger
language plpgsql
as $$
begin
  if new.state = 'succeeded' then
    new.passenger_snapshot := null;
  end if;
  return new;
end;
$$;

drop trigger if exists booking_attempts_clear_succeeded_passengers
  on public.booking_attempts;
create trigger booking_attempts_clear_succeeded_passengers
  before insert or update of state, passenger_snapshot
  on public.booking_attempts
  for each row execute function public.clear_succeeded_attempt_passengers();

create or replace function public.enforce_security_retention()
returns jsonb
language plpgsql
as $$
declare
  v_drafts bigint;
  v_failed bigint;
  v_snapshots bigint;
  v_rate_limits bigint;
  v_locks bigint;
begin
  delete from public.booking_attempts
   where state = 'draft'
     and created_at < now() - interval '7 days';
  get diagnostics v_drafts = row_count;

  delete from public.booking_attempts
   where state = 'failed'
     and coalesce(resolved_at, created_at) < now() - interval '90 days';
  get diagnostics v_failed = row_count;

  update public.booking_attempts
     set passenger_snapshot = null
   where passenger_snapshot is not null
     and (
       state = 'succeeded'
       or (
         state = 'unknown'
         and coalesce(resolved_at, created_at) < now() - interval '90 days'
       )
     );
  get diagnostics v_snapshots = row_count;

  delete from public.security_rate_limits
   where reset_at < now() - interval '1 day';
  get diagnostics v_rate_limits = row_count;

  delete from public.security_operation_locks
   where locked_until < now();
  get diagnostics v_locks = row_count;

  return jsonb_build_object(
    'draftsDeleted', v_drafts,
    'failedDeleted', v_failed,
    'passengerSnapshotsCleared', v_snapshots,
    'rateLimitsDeleted', v_rate_limits,
    'locksDeleted', v_locks
  );
end;
$$;

revoke execute on function public.enforce_security_retention()
  from public, anon, authenticated;
grant execute on function public.enforce_security_retention()
  to service_role;

comment on function public.enforce_security_retention() is
  'Prunes expired operational rows and removes passenger PII no longer needed for reconciliation.';


-- SOURCE: 0019_wallet_core.sql
-- Kaliganj Travels — authoritative wallet and payment ledger.
--
-- Money is stored in integer minor units. Every mutation locks the affected
-- currency account, changes its balances and appends an immutable ledger row
-- in the same transaction. The service role is the only database principal
-- allowed to use this module; application routes add the role/ownership gates.

-- 1. Wallet ownership and currency accounts ---------------------------------

create table if not exists public.wallets (
  id          uuid primary key default gen_random_uuid(),
  owner_type  text not null check (owner_type in ('user', 'agency')),
  -- Durable external owner key: Clerk user id or agencies.agency_code. It is
  -- intentionally not a foreign key so financial history survives deletion
  -- or replacement of an identity-provider record.
  owner_key   text not null check (char_length(owner_key) between 1 and 255),
  status      text not null default 'active'
              check (status in ('active', 'frozen')),
  frozen_at   timestamptz,
  frozen_by   text,
  freeze_reason text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (owner_type, owner_key)
);

create table if not exists public.wallet_accounts (
  id                uuid primary key default gen_random_uuid(),
  wallet_id         uuid not null references public.wallets (id) on delete restrict,
  currency          text not null check (currency ~ '^[A-Z]{3}$'),
  available_balance bigint not null default 0 check (available_balance >= 0),
  hold_balance      bigint not null default 0 check (hold_balance >= 0),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (wallet_id, currency)
);

create index if not exists wallets_status_idx
  on public.wallets (status, updated_at desc);
create index if not exists wallet_accounts_wallet_idx
  on public.wallet_accounts (wallet_id, currency);

drop trigger if exists wallets_touch_updated_at on public.wallets;
create trigger wallets_touch_updated_at
  before update on public.wallets
  for each row execute function public.touch_updated_at();

drop trigger if exists wallet_accounts_touch_updated_at on public.wallet_accounts;
create trigger wallet_accounts_touch_updated_at
  before update on public.wallet_accounts
  for each row execute function public.touch_updated_at();

-- 2. Booking ownership and payment state ------------------------------------

alter table public.flight_bookings
  add column if not exists booking_owner_type text
    check (booking_owner_type in ('user', 'agency')),
  add column if not exists booking_owner_key text,
  add column if not exists booked_by_user_id text,
  add column if not exists issued_by_user_id text,
  add column if not exists charged_wallet_account_id uuid
    references public.wallet_accounts (id) on delete restrict,
  add column if not exists payment_state text not null default 'unpaid'
    check (payment_state in (
      'unpaid', 'held', 'captured', 'released', 'reconciliation',
      'partially-refunded', 'refunded'
    )),
  add column if not exists payment_amount bigint,
  add column if not exists captured_amount bigint not null default 0
    check (captured_amount >= 0),
  add column if not exists refunded_amount bigint not null default 0
    check (refunded_amount >= 0 and refunded_amount <= captured_amount);

create index if not exists flight_bookings_wallet_account_idx
  on public.flight_bookings (charged_wallet_account_id, created_at desc);
create index if not exists flight_bookings_owner_idx
  on public.flight_bookings (booking_owner_type, booking_owner_key, created_at desc);

-- Existing rows used user_id as the creator. Agency rows belong financially
-- to the agency; B2C rows belong to that user. Legacy Super Admin rows are left
-- ownerless and therefore cannot be charged until explicitly reconciled.
update public.flight_bookings
   set booked_by_user_id = coalesce(booked_by_user_id, user_id),
       booking_owner_type = coalesce(
         booking_owner_type,
         case
           when audience = 'agency' and agency_code is not null then 'agency'
           when audience = 'b2c' and user_id is not null then 'user'
         end
       ),
       booking_owner_key = coalesce(
         booking_owner_key,
         case
           when audience = 'agency' and agency_code is not null then agency_code
           when audience = 'b2c' and user_id is not null then user_id
         end
       )
 where booked_by_user_id is null
    or booking_owner_type is null
    or booking_owner_key is null;

create or replace function public.set_booking_wallet_ownership()
returns trigger
language plpgsql
as $$
begin
  new.booked_by_user_id := coalesce(new.booked_by_user_id, new.user_id);
  if new.booking_owner_type is null or new.booking_owner_key is null then
    if new.audience = 'agency' and new.agency_code is not null then
      new.booking_owner_type := 'agency';
      new.booking_owner_key := new.agency_code;
    elsif new.audience = 'b2c' and new.user_id is not null then
      new.booking_owner_type := 'user';
      new.booking_owner_key := new.user_id;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists flight_bookings_set_wallet_ownership
  on public.flight_bookings;
create trigger flight_bookings_set_wallet_ownership
  before insert or update of audience, agency_code, user_id,
    booking_owner_type, booking_owner_key, booked_by_user_id
  on public.flight_bookings
  for each row execute function public.set_booking_wallet_ownership();

-- 3. Reservations and immutable ledger --------------------------------------

create table if not exists public.wallet_reservations (
  id                       uuid primary key default gen_random_uuid(),
  wallet_account_id        uuid not null
                            references public.wallet_accounts (id) on delete restrict,
  booking_id               uuid references public.flight_bookings (id) on delete restrict,
  booking_attempt_id       uuid references public.booking_attempts (id) on delete restrict,
  amount                   bigint not null check (amount > 0),
  currency                 text not null check (currency ~ '^[A-Z]{3}$'),
  state                    text not null default 'active'
                           check (state in ('active', 'captured', 'released', 'reconciliation')),
  cycle                    integer not null default 1 check (cycle > 0),
  requested_by_user_id     text not null,
  issued_by_user_id        text,
  supplier_call_started_at timestamptz,
  captured_at              timestamptz,
  released_at              timestamptz,
  reconciliation_at        timestamptz,
  reconciliation_reason    text,
  release_reason           text,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  check ((booking_id is not null)::integer +
         (booking_attempt_id is not null)::integer = 1)
);

create unique index if not exists wallet_reservations_booking_key
  on public.wallet_reservations (booking_id) where booking_id is not null;
create unique index if not exists wallet_reservations_attempt_key
  on public.wallet_reservations (booking_attempt_id)
  where booking_attempt_id is not null;
create index if not exists wallet_reservations_state_idx
  on public.wallet_reservations (state, updated_at desc);

drop trigger if exists wallet_reservations_touch_updated_at
  on public.wallet_reservations;
create trigger wallet_reservations_touch_updated_at
  before update on public.wallet_reservations
  for each row execute function public.touch_updated_at();

create table if not exists public.wallet_ledger_entries (
  id               uuid primary key default gen_random_uuid(),
  wallet_account_id uuid not null
                    references public.wallet_accounts (id) on delete restrict,
  transaction_type text not null check (transaction_type in (
    'deposit', 'booking_hold', 'booking_confirm', 'hold_release', 'refund',
    'manual_credit', 'manual_debit', 'adjustment', 'reversal'
  )),
  amount           bigint not null check (amount > 0),
  currency         text not null check (currency ~ '^[A-Z]{3}$'),
  available_before bigint not null check (available_before >= 0),
  available_after  bigint not null check (available_after >= 0),
  hold_before      bigint not null check (hold_before >= 0),
  hold_after       bigint not null check (hold_after >= 0),
  booking_id       uuid references public.flight_bookings (id) on delete restrict,
  booking_reference text,
  reservation_id   uuid references public.wallet_reservations (id) on delete restrict,
  related_entry_id uuid references public.wallet_ledger_entries (id) on delete restrict,
  idempotency_key  text not null unique
                   check (char_length(idempotency_key) between 1 and 255),
  created_by_user_id text not null,
  created_by_role  text not null,
  remarks          text,
  metadata         jsonb not null default '{}'::jsonb
                   check (jsonb_typeof(metadata) = 'object'),
  created_at       timestamptz not null default now()
);

create index if not exists wallet_ledger_account_created_idx
  on public.wallet_ledger_entries (wallet_account_id, created_at desc);
create index if not exists wallet_ledger_booking_created_idx
  on public.wallet_ledger_entries (booking_id, created_at desc);
create index if not exists wallet_ledger_type_created_idx
  on public.wallet_ledger_entries (transaction_type, created_at desc);

create or replace function public.prevent_wallet_ledger_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception 'wallet ledger entries are immutable' using errcode = '55000';
end;
$$;

drop trigger if exists wallet_ledger_immutable on public.wallet_ledger_entries;
create trigger wallet_ledger_immutable
  before update or delete on public.wallet_ledger_entries
  for each row execute function public.prevent_wallet_ledger_mutation();

-- 4. Deposit and maker-checker adjustment workflows ------------------------

create table if not exists public.wallet_deposit_requests (
  id                 uuid primary key default gen_random_uuid(),
  wallet_account_id  uuid not null
                     references public.wallet_accounts (id) on delete restrict,
  amount             bigint not null check (amount > 0),
  currency           text not null check (currency ~ '^[A-Z]{3}$'),
  method             text not null check (method in ('cash', 'bank', 'mobile')),
  reference_number   text,
  remarks            text,
  status             text not null default 'pending'
                     check (status in ('pending', 'approved', 'rejected')),
  requested_by_user_id text not null,
  reviewed_by_user_id  text,
  review_remarks       text,
  ledger_entry_id      uuid references public.wallet_ledger_entries (id) on delete restrict,
  requested_at         timestamptz not null default now(),
  reviewed_at          timestamptz,
  updated_at           timestamptz not null default now()
);

create table if not exists public.wallet_adjustment_requests (
  id                  uuid primary key default gen_random_uuid(),
  wallet_account_id   uuid not null
                      references public.wallet_accounts (id) on delete restrict,
  adjustment_type     text not null check (adjustment_type in ('credit', 'debit')),
  amount              bigint not null check (amount > 0),
  currency            text not null check (currency ~ '^[A-Z]{3}$'),
  reason              text not null check (char_length(trim(reason)) between 1 and 1000),
  status              text not null default 'pending'
                      check (status in ('pending', 'approved', 'rejected')),
  requested_by_user_id text not null,
  requested_by_role   text not null,
  reviewed_by_user_id text,
  review_remarks      text,
  ledger_entry_id     uuid references public.wallet_ledger_entries (id) on delete restrict,
  requested_at        timestamptz not null default now(),
  reviewed_at         timestamptz,
  updated_at          timestamptz not null default now()
);

create index if not exists wallet_deposit_queue_idx
  on public.wallet_deposit_requests (status, requested_at desc);
create index if not exists wallet_adjustment_queue_idx
  on public.wallet_adjustment_requests (status, requested_at desc);

drop trigger if exists wallet_deposits_touch_updated_at
  on public.wallet_deposit_requests;
create trigger wallet_deposits_touch_updated_at
  before update on public.wallet_deposit_requests
  for each row execute function public.touch_updated_at();

drop trigger if exists wallet_adjustments_touch_updated_at
  on public.wallet_adjustment_requests;
create trigger wallet_adjustments_touch_updated_at
  before update on public.wallet_adjustment_requests
  for each row execute function public.touch_updated_at();

-- 5. Shared account resolver ------------------------------------------------

create or replace function public.wallet_ensure_account(
  p_owner_type text,
  p_owner_key text,
  p_currency text default 'BDT'
)
returns public.wallet_accounts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_currency text := upper(trim(p_currency));
begin
  if p_owner_type not in ('user', 'agency')
     or nullif(trim(p_owner_key), '') is null
     or v_currency !~ '^[A-Z]{3}$' then
    raise exception 'invalid wallet owner or currency' using errcode = '22023';
  end if;

  insert into public.wallets (owner_type, owner_key)
  values (p_owner_type, trim(p_owner_key))
  on conflict (owner_type, owner_key) do nothing;

  select * into strict v_wallet
    from public.wallets
   where owner_type = p_owner_type
     and owner_key = trim(p_owner_key);

  insert into public.wallet_accounts (wallet_id, currency)
  values (v_wallet.id, v_currency)
  on conflict (wallet_id, currency) do nothing;

  select * into strict v_account
    from public.wallet_accounts
   where wallet_id = v_wallet.id and currency = v_currency;
  return v_account;
end;
$$;

-- 6. Atomic reservation helpers --------------------------------------------

create or replace function public.wallet_reserve_amount(
  p_booking_id uuid,
  p_booking_attempt_id uuid,
  p_owner_type text,
  p_owner_key text,
  p_amount bigint,
  p_currency text,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text,
  p_booking_reference text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_account public.wallet_accounts;
  v_wallet public.wallets;
  v_reservation public.wallet_reservations;
  v_available_before bigint;
  v_hold_before bigint;
  v_currency text := upper(trim(p_currency));
begin
  if (p_booking_id is null) = (p_booking_attempt_id is null)
     or p_amount is null or p_amount <= 0
     or v_currency !~ '^[A-Z]{3}$'
     or nullif(trim(p_actor_user_id), '') is null
     or nullif(trim(p_idempotency_key), '') is null then
    raise exception 'invalid wallet reservation request' using errcode = '22023';
  end if;

  if p_booking_id is not null then
    select * into v_reservation
      from public.wallet_reservations
     where booking_id = p_booking_id
     for update;
  else
    select * into v_reservation
      from public.wallet_reservations
     where booking_attempt_id = p_booking_attempt_id
     for update;
  end if;

  if found and v_reservation.state = 'captured' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  elsif found and v_reservation.state = 'reconciliation' then
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  elsif found and v_reservation.state = 'active' then
    return jsonb_build_object('ok', false, 'code', 'ISSUE_IN_PROGRESS');
  end if;

  v_account := public.wallet_ensure_account(
    p_owner_type, p_owner_key, v_currency
  );

  -- PostgreSQL cannot assign two composite rows in one INTO target list.
  -- Lock the wallet first, then its currency account, consistently across
  -- balance-changing functions.
  select w.* into strict v_wallet
    from public.wallets w
    join public.wallet_accounts wa on wa.wallet_id = w.id
   where wa.id = v_account.id
   for update of w;
  select * into strict v_account
    from public.wallet_accounts
   where id = v_account.id
   for update;

  if v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_account.available_balance < p_amount then
    return jsonb_build_object(
      'ok', false,
      'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance,
      'required', p_amount,
      'currency', v_currency
    );
  end if;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts
     set available_balance = available_balance - p_amount,
         hold_balance = hold_balance + p_amount
   where id = v_account.id;

  if v_reservation.id is null then
    insert into public.wallet_reservations (
      wallet_account_id, booking_id, booking_attempt_id, amount, currency,
      requested_by_user_id, supplier_call_started_at
    ) values (
      v_account.id, p_booking_id, p_booking_attempt_id, p_amount, v_currency,
      p_actor_user_id, now()
    ) returning * into v_reservation;
  else
    update public.wallet_reservations
       set wallet_account_id = v_account.id,
           amount = p_amount,
           currency = v_currency,
           state = 'active',
           cycle = cycle + 1,
           requested_by_user_id = p_actor_user_id,
           issued_by_user_id = null,
           supplier_call_started_at = now(),
           captured_at = null,
           released_at = null,
           reconciliation_at = null,
           reconciliation_reason = null,
           release_reason = null
     where id = v_reservation.id
     returning * into v_reservation;
  end if;

  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks
  ) values (
    v_account.id, 'booking_hold', p_amount, v_currency,
    v_available_before, v_available_before - p_amount,
    v_hold_before, v_hold_before + p_amount,
    p_booking_id, p_booking_reference, v_reservation.id,
    p_idempotency_key || ':hold', p_actor_user_id, p_actor_role,
    'Funds reserved before supplier ticket issuance'
  );

  if p_booking_id is not null then
    update public.flight_bookings
       set charged_wallet_account_id = v_account.id,
           payment_state = 'held',
           payment_amount = p_amount
     where id = p_booking_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'reservationId', v_reservation.id,
    'accountId', v_account.id,
    'amount', p_amount,
    'currency', v_currency,
    'availableBalance', v_available_before - p_amount,
    'holdBalance', v_hold_before + p_amount
  );
end;
$$;

create or replace function public.wallet_begin_booking_issue(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_amount bigint;
begin
  select * into v_booking
    from public.flight_bookings
   where id = p_booking_id and not legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  if v_booking.status = 'confirmed' or v_booking.payment_state = 'captured' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;
  if v_booking.status <> 'on-hold' then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if v_booking.ticketing_deadline_at is not null
     and v_booking.ticketing_deadline_at <= now() then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
  end if;
  if v_booking.booking_owner_type is null or v_booking.booking_owner_key is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_OWNER_REQUIRED');
  end if;

  begin
    v_amount := round(
      (v_booking.pricing_snapshot->>'sellingPrice')::numeric * 100
    )::bigint;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end;

  return public.wallet_reserve_amount(
    v_booking.id, null, v_booking.booking_owner_type,
    v_booking.booking_owner_key, v_amount, v_booking.currency,
    p_actor_user_id, p_actor_role, p_idempotency_key,
    v_booking.public_ref
  );
end;
$$;

create or replace function public.wallet_begin_direct_ticket(
  p_attempt_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_attempt public.booking_attempts;
  v_owner_type text;
  v_owner_key text;
  v_amount bigint;
  v_currency text;
begin
  select * into v_attempt
    from public.booking_attempts
   where id = p_attempt_id
   for update;
  if not found or v_attempt.state <> 'submitting' then
    return jsonb_build_object('ok', false, 'code', 'ATTEMPT_NOT_CLAIMED');
  end if;
  if coalesce((v_attempt.offer_snapshot->>'directTicketing')::boolean, false) is not true then
    return jsonb_build_object('ok', false, 'code', 'NOT_DIRECT_TICKETING');
  end if;
  if v_attempt.audience = 'agency' and v_attempt.agency_code is not null then
    v_owner_type := 'agency';
    v_owner_key := v_attempt.agency_code;
  elsif v_attempt.audience = 'b2c' and v_attempt.user_id is not null then
    v_owner_type := 'user';
    v_owner_key := v_attempt.user_id;
  else
    return jsonb_build_object('ok', false, 'code', 'BOOKING_OWNER_REQUIRED');
  end if;

  begin
    v_amount := round(
      (v_attempt.offer_snapshot->'pricing'->>'sellingPrice')::numeric * 100
    )::bigint;
    v_currency := upper(v_attempt.offer_snapshot->>'currency');
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end;

  return public.wallet_reserve_amount(
    null, v_attempt.id, v_owner_type, v_owner_key, v_amount, v_currency,
    p_actor_user_id, p_actor_role, p_idempotency_key, null
  );
end;
$$;

-- 7. Capture, release and reconciliation ------------------------------------

create or replace function public.wallet_capture_reservation(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text,
  p_supplier_outcome jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_reservation public.wallet_reservations;
  v_account public.wallet_accounts;
  v_available_before bigint;
  v_hold_before bigint;
begin
  select * into v_booking
    from public.flight_bookings
   where id = p_booking_id and not legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  select * into v_reservation
    from public.wallet_reservations
   where booking_id = p_booking_id
      or (booking_id is null and booking_attempt_id = v_booking.attempt_id)
   order by booking_id nulls last
   limit 1
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'RESERVATION_NOT_FOUND');
  end if;
  if v_reservation.state = 'captured' then
    return jsonb_build_object('ok', true, 'replay', true,
      'reservationId', v_reservation.id);
  end if;
  if v_reservation.state = 'released' then
    return jsonb_build_object('ok', false, 'code', 'RESERVATION_RELEASED');
  end if;

  select * into strict v_account
    from public.wallet_accounts
   where id = v_reservation.wallet_account_id
   for update;
  if v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'HOLD_BALANCE_MISMATCH');
  end if;
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;

  update public.wallet_accounts
     set hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;

  update public.wallet_reservations
     set booking_id = p_booking_id,
         booking_attempt_id = null,
         state = 'captured',
         issued_by_user_id = p_actor_user_id,
         captured_at = now(),
         reconciliation_at = null,
         reconciliation_reason = null
   where id = v_reservation.id;

  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks
  ) values (
    v_account.id, 'booking_confirm', v_reservation.amount,
    v_reservation.currency, v_available_before, v_available_before,
    v_hold_before, v_hold_before - v_reservation.amount,
    v_booking.id, v_booking.public_ref, v_reservation.id,
    p_idempotency_key || ':capture', p_actor_user_id, p_actor_role,
    'Supplier confirmed ticket issuance'
  );

  update public.flight_bookings
     set charged_wallet_account_id = v_account.id,
         payment_state = 'captured',
         payment_amount = v_reservation.amount,
         captured_amount = v_reservation.amount,
         status = 'confirmed',
         issued_by_user_id = p_actor_user_id,
         issued_at = coalesce(issued_at, now()),
         pnr = coalesce(nullif(trim(p_supplier_outcome->>'pnr'), ''), pnr),
         booking_status = coalesce(
           nullif(trim(p_supplier_outcome->>'bookingStatus'), ''),
           booking_status,
           'Confirmed'
         ),
         ticket_code_ref = coalesce(
           nullif(trim(p_supplier_outcome->>'ticketCodeRef'), ''),
           ticket_code_ref
         ),
         ticket_numbers = case
           when jsonb_typeof(p_supplier_outcome->'ticketNumbers') = 'array'
             then p_supplier_outcome->'ticketNumbers'
           else ticket_numbers
         end,
         warnings = case
           when jsonb_typeof(p_supplier_outcome->'warnings') = 'array'
             then p_supplier_outcome->'warnings'
           else warnings
         end,
         supplier_message = coalesce(
           nullif(trim(p_supplier_outcome->>'message'), ''), supplier_message
         )
   where id = v_booking.id;

  return jsonb_build_object(
    'ok', true,
    'reservationId', v_reservation.id,
    'availableBalance', v_available_before,
    'holdBalance', v_hold_before - v_reservation.amount
  );
end;
$$;

create or replace function public.wallet_release_reservation(
  p_booking_id uuid,
  p_booking_attempt_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_reservation public.wallet_reservations;
  v_account public.wallet_accounts;
  v_booking_ref text;
  v_available_before bigint;
  v_hold_before bigint;
begin
  if (p_booking_id is null) = (p_booking_attempt_id is null) then
    raise exception 'exactly one reservation subject is required' using errcode = '22023';
  end if;
  select * into v_reservation
    from public.wallet_reservations
   where (p_booking_id is not null and booking_id = p_booking_id)
      or (p_booking_attempt_id is not null and booking_attempt_id = p_booking_attempt_id)
   for update;
  if not found then
    return jsonb_build_object('ok', true, 'replay', true);
  end if;
  if v_reservation.state = 'released' then
    return jsonb_build_object('ok', true, 'replay', true,
      'reservationId', v_reservation.id);
  end if;
  if v_reservation.state = 'captured' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;

  select * into strict v_account
    from public.wallet_accounts
   where id = v_reservation.wallet_account_id
   for update;
  if v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'HOLD_BALANCE_MISMATCH');
  end if;
  if p_booking_id is not null then
    select public_ref into v_booking_ref
      from public.flight_bookings where id = p_booking_id;
  end if;
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;

  update public.wallet_accounts
     set available_balance = available_balance + v_reservation.amount,
         hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;
  update public.wallet_reservations
     set state = 'released',
         released_at = now(),
         release_reason = left(coalesce(p_reason, 'Supplier declined issuance'), 1000)
   where id = v_reservation.id;

  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks
  ) values (
    v_account.id, 'hold_release', v_reservation.amount,
    v_reservation.currency, v_available_before,
    v_available_before + v_reservation.amount,
    v_hold_before, v_hold_before - v_reservation.amount,
    p_booking_id, v_booking_ref, v_reservation.id,
    p_idempotency_key || ':release', p_actor_user_id, p_actor_role,
    left(coalesce(p_reason, 'Supplier declined issuance'), 1000)
  );

  if p_booking_id is not null then
    update public.flight_bookings
       set payment_state = 'released'
     where id = p_booking_id and payment_state <> 'captured';
  end if;
  return jsonb_build_object(
    'ok', true,
    'reservationId', v_reservation.id,
    'availableBalance', v_available_before + v_reservation.amount,
    'holdBalance', v_hold_before - v_reservation.amount
  );
end;
$$;

create or replace function public.wallet_mark_reconciliation(
  p_booking_id uuid,
  p_booking_attempt_id uuid,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if (p_booking_id is null) = (p_booking_attempt_id is null) then
    raise exception 'exactly one reservation subject is required' using errcode = '22023';
  end if;
  update public.wallet_reservations
     set state = 'reconciliation',
         reconciliation_at = now(),
         reconciliation_reason = left(coalesce(p_reason, 'Supplier outcome unknown'), 1000)
   where ((p_booking_id is not null and booking_id = p_booking_id)
       or (p_booking_attempt_id is not null and booking_attempt_id = p_booking_attempt_id))
     and state = 'active'
  returning id into v_id;
  if p_booking_id is not null then
    update public.flight_bookings
       set payment_state = 'reconciliation', status = 'in-progress'
     where id = p_booking_id and payment_state = 'held';
  end if;
  return jsonb_build_object('ok', v_id is not null, 'reservationId', v_id);
end;
$$;

-- 8. Deposit, adjustment and refund settlement -----------------------------

create or replace function public.wallet_review_deposit(
  p_request_id uuid,
  p_decision text,
  p_actor_user_id text,
  p_actor_role text,
  p_review_remarks text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request public.wallet_deposit_requests;
  v_account public.wallet_accounts;
  v_entry_id uuid;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'invalid deposit decision' using errcode = '22023';
  end if;
  select * into v_request from public.wallet_deposit_requests
   where id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_request.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_REVIEWED');
  end if;
  if v_request.requested_by_user_id = p_actor_user_id then
    return jsonb_build_object('ok', false, 'code', 'SELF_APPROVAL_FORBIDDEN');
  end if;
  if p_decision = 'rejected' then
    update public.wallet_deposit_requests set
      status = 'rejected', reviewed_by_user_id = p_actor_user_id,
      review_remarks = p_review_remarks, reviewed_at = now()
    where id = p_request_id;
    return jsonb_build_object('ok', true, 'status', 'rejected');
  end if;

  select * into strict v_account from public.wallet_accounts
   where id = v_request.wallet_account_id for update;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    idempotency_key, created_by_user_id, created_by_role, remarks
  ) values (
    v_account.id, 'deposit', v_request.amount, v_request.currency,
    v_account.available_balance, v_account.available_balance + v_request.amount,
    v_account.hold_balance, v_account.hold_balance,
    'deposit:' || v_request.id, p_actor_user_id, p_actor_role,
    coalesce(p_review_remarks, v_request.remarks)
  ) returning id into v_entry_id;
  update public.wallet_accounts set
    available_balance = available_balance + v_request.amount
  where id = v_account.id;
  update public.wallet_deposit_requests set
    status = 'approved', reviewed_by_user_id = p_actor_user_id,
    review_remarks = p_review_remarks, reviewed_at = now(),
    ledger_entry_id = v_entry_id
  where id = p_request_id;
  return jsonb_build_object('ok', true, 'status', 'approved',
    'availableBalance', v_account.available_balance + v_request.amount);
end;
$$;

create or replace function public.wallet_review_adjustment(
  p_request_id uuid,
  p_decision text,
  p_actor_user_id text,
  p_actor_role text,
  p_review_remarks text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request public.wallet_adjustment_requests;
  v_account public.wallet_accounts;
  v_wallet public.wallets;
  v_entry_id uuid;
  v_after bigint;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'invalid adjustment decision' using errcode = '22023';
  end if;
  select * into v_request from public.wallet_adjustment_requests
   where id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_request.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_REVIEWED');
  end if;
  if v_request.requested_by_user_id = p_actor_user_id then
    return jsonb_build_object('ok', false, 'code', 'SELF_APPROVAL_FORBIDDEN');
  end if;
  if p_decision = 'rejected' then
    update public.wallet_adjustment_requests set
      status = 'rejected', reviewed_by_user_id = p_actor_user_id,
      review_remarks = p_review_remarks, reviewed_at = now()
    where id = p_request_id;
    return jsonb_build_object('ok', true, 'status', 'rejected');
  end if;

  select w.* into strict v_wallet
    from public.wallets w
    join public.wallet_accounts wa on wa.wallet_id = w.id
   where wa.id = v_request.wallet_account_id
   for update of w;
  select * into strict v_account
    from public.wallet_accounts
   where id = v_request.wallet_account_id
   for update;
  if v_request.adjustment_type = 'debit' and v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_request.adjustment_type = 'debit'
     and v_account.available_balance < v_request.amount then
    return jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance, 'required', v_request.amount);
  end if;
  v_after := v_account.available_balance +
    case when v_request.adjustment_type = 'credit'
      then v_request.amount else -v_request.amount end;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    idempotency_key, created_by_user_id, created_by_role, remarks,
    metadata
  ) values (
    v_account.id,
    case when v_request.adjustment_type = 'credit'
      then 'manual_credit' else 'manual_debit' end,
    v_request.amount, v_request.currency,
    v_account.available_balance, v_after,
    v_account.hold_balance, v_account.hold_balance,
    'adjustment:' || v_request.id, p_actor_user_id, p_actor_role,
    v_request.reason,
    jsonb_build_object('requestedBy', v_request.requested_by_user_id)
  ) returning id into v_entry_id;
  update public.wallet_accounts set available_balance = v_after
   where id = v_account.id;
  update public.wallet_adjustment_requests set
    status = 'approved', reviewed_by_user_id = p_actor_user_id,
    review_remarks = p_review_remarks, reviewed_at = now(),
    ledger_entry_id = v_entry_id
  where id = p_request_id;
  return jsonb_build_object('ok', true, 'status', 'approved',
    'availableBalance', v_after);
end;
$$;

create or replace function public.wallet_refund_booking(
  p_booking_id uuid,
  p_amount bigint,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text,
  p_remarks text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_account public.wallet_accounts;
  v_existing public.wallet_ledger_entries;
  v_outstanding bigint;
begin
  if p_amount is null or p_amount <= 0
     or nullif(trim(p_actor_user_id), '') is null
     or nullif(trim(p_idempotency_key), '') is null then
    raise exception 'invalid refund request' using errcode = '22023';
  end if;
  select * into v_booking from public.flight_bookings
   where id = p_booking_id and not legacy_operational for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND'); end if;
  select * into v_existing
    from public.wallet_ledger_entries
   where idempotency_key = p_idempotency_key || ':refund';
  if found then
    return jsonb_build_object(
      'ok', true,
      'replay', true,
      'availableBalance', v_existing.available_after,
      'refundedAmount', v_booking.refunded_amount
    );
  end if;
  v_outstanding := v_booking.captured_amount - v_booking.refunded_amount;
  if v_booking.payment_state not in ('captured', 'partially-refunded')
     or p_amount > v_outstanding then
    return jsonb_build_object('ok', false, 'code', 'REFUND_EXCEEDS_CAPTURE',
      'refundable', greatest(v_outstanding, 0));
  end if;
  select * into strict v_account from public.wallet_accounts
   where id = v_booking.charged_wallet_account_id for update;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, idempotency_key,
    created_by_user_id, created_by_role, remarks
  ) values (
    v_account.id, 'refund', p_amount, v_account.currency,
    v_account.available_balance, v_account.available_balance + p_amount,
    v_account.hold_balance, v_account.hold_balance,
    v_booking.id, v_booking.public_ref, p_idempotency_key || ':refund',
    p_actor_user_id, p_actor_role, p_remarks
  );
  update public.wallet_accounts set
    available_balance = available_balance + p_amount where id = v_account.id;
  update public.flight_bookings set
    refunded_amount = refunded_amount + p_amount,
    payment_state = case when refunded_amount + p_amount = captured_amount
      then 'refunded' else 'partially-refunded' end
  where id = v_booking.id;
  return jsonb_build_object('ok', true,
    'availableBalance', v_account.available_balance + p_amount,
    'refundedAmount', v_booking.refunded_amount + p_amount);
end;
$$;

-- 9. Reporting views --------------------------------------------------------

create or replace view public.wallet_report_v as
select
  w.id as wallet_id,
  w.owner_type,
  w.owner_key,
  w.status,
  wa.id as wallet_account_id,
  wa.currency,
  wa.available_balance,
  wa.hold_balance,
  wa.available_balance + wa.hold_balance as total_balance,
  wa.updated_at
from public.wallets w
join public.wallet_accounts wa on wa.wallet_id = w.id;

create or replace view public.wallet_transaction_report_v as
select
  le.*,
  w.owner_type,
  w.owner_key,
  fb.public_ref as joined_booking_reference
from public.wallet_ledger_entries le
join public.wallet_accounts wa on wa.id = le.wallet_account_id
join public.wallets w on w.id = wa.wallet_id
left join public.flight_bookings fb on fb.id = le.booking_id;

create or replace view public.booking_payment_report_v as
select
  fb.id as booking_id,
  fb.public_ref,
  fb.booking_owner_type,
  fb.booking_owner_key,
  fb.booked_by_user_id,
  fb.issued_by_user_id,
  fb.charged_wallet_account_id,
  fb.payment_state,
  fb.payment_amount,
  fb.captured_amount,
  fb.refunded_amount,
  fb.currency,
  fb.status as booking_status,
  fb.created_at,
  fb.issued_at
from public.flight_bookings fb
where not fb.legacy_operational;

