-- SOURCE: 0035_confirmed_email_retry_safety.sql
-- Confirmed ticket email claims need a retry lease: a PDF/SMTP failure must not
-- permanently suppress the customer's issued-ticket notification.
-- This migration changes email-delivery metadata only; it never touches the
-- booking lifecycle, supplier, wallet, ticket, refund, or ledger state.

alter table public.flight_bookings
  add column if not exists confirmed_email_attempt_count integer not null default 0,
  add column if not exists confirmed_email_last_error text;

create or replace function public.claim_confirmed_booking_email(p_booking_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
begin
  select * into v_booking
    from public.flight_bookings
   where id = p_booking_id
     and not legacy_operational
   for update;

  if not found
     or v_booking.status <> 'confirmed'
     or v_booking.issued_at is null
     or v_booking.confirmed_email_sent_at is not null
     or (
       v_booking.confirmed_email_claimed_at is not null
       and v_booking.confirmed_email_claimed_at > now() - interval '15 minutes'
     ) then
    return false;
  end if;

  update public.flight_bookings
     set confirmed_email_claimed_at = now(),
         confirmed_email_attempt_count = confirmed_email_attempt_count + 1,
         confirmed_email_last_error = null
   where id = v_booking.id;
  return true;
end;
$$;

create or replace function public.mark_confirmed_booking_email_sent(p_booking_id uuid)
returns void
language sql
security definer
set search_path = public
as $$
  update public.flight_bookings
     set confirmed_email_sent_at = now(),
         confirmed_email_last_error = null
   where id = p_booking_id
     and confirmed_email_claimed_at is not null
     and confirmed_email_sent_at is null;
$$;

create or replace function public.fail_confirmed_booking_email(
  p_booking_id uuid,
  p_error text
)
returns void
language sql
security definer
set search_path = public
as $$
  update public.flight_bookings
     set confirmed_email_claimed_at = null,
         confirmed_email_last_error = left(
           coalesce(nullif(trim(p_error), ''), 'Confirmed email delivery failed.'),
           500
         )
   where id = p_booking_id
     and confirmed_email_sent_at is null;
$$;

revoke all on function public.claim_confirmed_booking_email(uuid),
  public.mark_confirmed_booking_email_sent(uuid),
  public.fail_confirmed_booking_email(uuid,text)
  from public, anon, authenticated;
grant execute on function public.claim_confirmed_booking_email(uuid),
  public.mark_confirmed_booking_email_sent(uuid),
  public.fail_confirmed_booking_email(uuid,text)
  to service_role;

-- Preserve the known failed attempt as auditable metadata. The stale lease is
-- intentionally left in place; the claim function itself decides retry safety.
-- Historical email error record omitted.

comment on function public.claim_confirmed_booking_email(uuid) is
  'Row-locking 15-minute lease for retry-safe confirmed-ticket email delivery.';


-- SOURCE: 0036_correct_ambiguous_pnr_deadline_by_booking_time.sql
-- Historical booking-only repair omitted: there are no previous bookings.


-- SOURCE: 0037_impexp_booking_imports.sql
-- Privileged external-booking imports (IMP/EXP).
-- The supplier response is normalized by the application; this transaction
-- creates the synthetic operational attempt and real business booking together.

alter table public.flight_bookings
  add column if not exists import_source text,
  add column if not exists imported_by_user_id text
    references public.app_users (clerk_id) on delete set null,
  add column if not exists import_metadata jsonb;

alter table public.flight_bookings
  drop constraint if exists flight_bookings_import_source_check;
alter table public.flight_bookings
  add constraint flight_bookings_import_source_check
  check (import_source is null or import_source = 'IMP_EXP');

create unique index if not exists flight_bookings_impexp_supplier_reference_key
  on public.flight_bookings (supplier, booking_ref_number)
  where import_source = 'IMP_EXP' and booking_ref_number is not null;

create index if not exists flight_bookings_impexp_created_idx
  on public.flight_bookings (created_at desc)
  where import_source = 'IMP_EXP';

create or replace function public.create_impexp_booking(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_data jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_target_user_id text;
  v_target_role text;
  v_agency_code text;
  v_audience text;
  v_supplier text;
  v_supplier_ref text;
  v_status text;
  v_lifecycle_status text;
  v_old_lifecycle text;
  v_new_lifecycle text;
  v_imported_at timestamptz;
  v_attempt_id uuid := gen_random_uuid();
  v_search_id uuid := gen_random_uuid();
  v_access_hash text;
  v_offer jsonb;
  v_existing public.flight_bookings;
  v_booking public.flight_bookings;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' then
    raise exception 'import payload must be an object' using errcode = '22023';
  end if;

  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    raise exception 'IMP/EXP access is forbidden' using errcode = '42501';
  end if;

  v_supplier := nullif(trim(p_data->>'provider'), '');
  v_supplier_ref := nullif(trim(p_data->>'supplierReference'), '');
  if v_supplier not in ('US_BANGLA', 'AIR_ASTRA', 'NOVOAIR')
     or v_supplier_ref is null then
    raise exception 'invalid supplier import identity' using errcode = '22023';
  end if;

  v_target_user_id := nullif(trim(p_assigned_user_id), '');
  if v_target_user_id is not null then
    select role, agency_code into v_target_role, v_agency_code
      from public.app_users
     where clerk_id = v_target_user_id;
    if not found or v_target_role not in ('b2b', 'b2b_sub', 'customer') then
      raise exception 'assigned user is not eligible for IMP/EXP' using errcode = '22023';
    end if;
    if v_target_role in ('b2b', 'b2b_sub') then
      if nullif(trim(v_agency_code), '') is null then
        raise exception 'assigned agency user has no agency' using errcode = '22023';
      end if;
      v_audience := 'agency';
    else
      v_audience := 'b2c';
      v_agency_code := null;
    end if;
  else
    v_target_user_id := p_actor_user_id;
    v_target_role := v_actor_role;
    v_agency_code := null;
    v_audience := 'superadmin';
  end if;

  v_status := p_data->>'storedStatus';
  v_lifecycle_status := p_data->>'lifecycleStatus';
  if v_status is null
     or v_lifecycle_status is null
     or v_status not in ('on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled')
     or v_lifecycle_status not in (
       'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
       'unconfirmed', 'cancelled'
     )
     or (v_lifecycle_status in ('expired', 'unconfirmed') and v_status <> 'on-hold')
     or (v_lifecycle_status not in ('expired', 'unconfirmed') and v_lifecycle_status <> v_status) then
    raise exception 'invalid imported booking status' using errcode = '22023';
  end if;
  if coalesce(p_data->>'travelDate', '') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'invalid imported travel date' using errcode = '22007';
  end if;
  if jsonb_typeof(p_data->'passengerCounts') <> 'object'
     or jsonb_typeof(p_data->'itinerary') <> 'object'
     or jsonb_typeof(p_data->'fares') <> 'array'
     or jsonb_typeof(p_data->'passengers') <> 'object'
     or jsonb_typeof(p_data->'airlinesPnr') <> 'array'
     or jsonb_typeof(p_data->'ticketNumbers') <> 'array' then
    raise exception 'invalid normalized import payload' using errcode = '22023';
  end if;

  v_imported_at := coalesce(
    nullif(p_data->>'importedAt', '')::timestamptz,
    now()
  );
  v_offer := jsonb_build_object(
    'itinerary', p_data->'itinerary',
    'fares', p_data->'fares',
    'currency', coalesce(nullif(p_data->>'currency', ''), 'BDT'),
    'pricing', jsonb_build_object(
      'audience', v_audience,
      'agencyCode', v_agency_code,
      'sellingPrice', greatest(0, coalesce((p_data->>'totalPrice')::numeric, 0)),
      'supplierTotalPrice', greatest(0, coalesce((p_data->>'totalPrice')::numeric, 0)),
      'grossPrice', greatest(0, coalesce((p_data->>'totalPrice')::numeric, 0)),
      'serviceMarginAmount', 0,
      'ruleId', null,
      'basis', 'supplier'
    ),
    'passengerCounts', p_data->'passengerCounts',
    'travelDate', p_data->>'travelDate',
    'directTicketing', v_status = 'confirmed',
    'passportRequired', coalesce((p_data->>'passportRequired')::boolean, true),
    'repricedAt', v_imported_at
  );
  v_access_hash := md5(v_attempt_id::text || clock_timestamp()::text)
    || md5(v_search_id::text || random()::text);

  -- A repeated import is a supplier status refresh, not a duplicate booking.
  -- Reuse the STR reference and append a lifecycle event only when its public
  -- status actually changes.
  select * into v_existing
    from public.flight_bookings
   where import_source = 'IMP_EXP'
     and supplier = v_supplier
     and booking_ref_number = v_supplier_ref
   limit 1
   for update;
  if found then
    v_old_lifecycle := public.resolve_booking_lifecycle(
      v_existing.status,
      v_existing.airlines_pnr,
      v_existing.ticketing_deadline_at,
      v_existing.operation_kind
    );

    update public.booking_attempts
       set user_id = v_target_user_id,
           audience = v_audience,
           agency_code = v_agency_code,
           supplier = v_supplier,
           offer_snapshot = v_offer,
           passenger_snapshot = p_data->'passengers',
           pnr = coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
           resolved_at = v_imported_at
     where id = v_existing.attempt_id;

    update public.flight_bookings
       set user_id = v_target_user_id,
           audience = v_audience,
           agency_code = v_agency_code,
           booking_owner_type = null,
           booking_owner_key = null,
           status = v_status,
           operation_kind = case when v_status = 'in-progress'
             then 'reconciliation' else null end,
           operation_reason = case when v_status = 'in-progress'
             then 'legacy_reconciliation' else null end,
           operation_request_id = null,
           operation_actor_user_id = null,
           operation_started_at = case when v_status = 'in-progress'
             then v_imported_at else null end,
           operation_prior_status = null,
           currency = coalesce(nullif(p_data->>'currency', ''), 'BDT'),
           pricing_snapshot = v_offer->'pricing',
           passenger_counts = p_data->'passengerCounts',
           travel_date = (p_data->>'travelDate')::date,
           direct_ticketing = v_status = 'confirmed',
           itinerary = p_data->'itinerary',
           fares = p_data->'fares',
           passport_required = coalesce(
             (p_data->>'passportRequired')::boolean,
             true
           ),
           supplier_refs = jsonb_strip_nulls(
             coalesce(v_existing.supplier_refs, '{}'::jsonb)
             || jsonb_build_object(
               'originalReference', nullif(p_data->>'originalReference', '')
             )
           ),
           repriced_at = v_imported_at,
           accepted_at = v_imported_at,
           passengers = p_data->'passengers',
           pnr = coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
           airlines_pnr = p_data->'airlinesPnr',
           booking_status = p_data->>'orderStatus',
           ticketing_time_limit = nullif(p_data->>'ticketingTimeLimit', ''),
           ticketing_deadline_at = nullif(
             p_data->>'ticketingDeadlineAt',
             ''
           )::timestamptz,
           deadline_source = case
             when nullif(p_data->>'ticketingDeadlineAt', '') is not null
               then 'supplier'
             else null
           end,
           ticket_numbers = p_data->'ticketNumbers',
           supplier_message = nullif(p_data->>'supplierMessage', ''),
           issued_at = case when v_status = 'confirmed'
             then coalesce(v_existing.issued_at, v_imported_at) else null end,
           cancelled_at = case when v_status = 'cancelled'
             then coalesce(v_existing.cancelled_at, v_imported_at) else null end,
           booked_by_user_id = p_actor_user_id,
           imported_by_user_id = p_actor_user_id,
           import_metadata = jsonb_build_object(
             'provider', v_supplier,
             'supplierReference', v_supplier_ref,
             'originalReference', nullif(p_data->>'originalReference', ''),
             'orderStatus', p_data->>'orderStatus',
             'lifecycleStatus', v_lifecycle_status,
             'lastSyncedAt', v_imported_at
           )
     where id = v_existing.id
     returning * into v_booking;

    v_new_lifecycle := public.resolve_booking_lifecycle(
      v_booking.status,
      v_booking.airlines_pnr,
      v_booking.ticketing_deadline_at,
      v_booking.operation_kind
    );
    if v_old_lifecycle is distinct from v_new_lifecycle then
      insert into public.booking_status_events (
        booking_id, from_lifecycle_status, to_lifecycle_status,
        stored_status_before, stored_status_after, operation_kind,
        operation_reason, actor_user_id, supplier_operation,
        supplier_evidence
      ) values (
        v_booking.id, v_old_lifecycle, v_new_lifecycle,
        v_existing.status, v_booking.status, v_booking.operation_kind,
        v_booking.operation_reason, p_actor_user_id, 'ImportSync',
        jsonb_build_object(
          'provider', v_supplier,
          'supplierStatus', p_data->>'orderStatus',
          'lifecycleStatus', v_lifecycle_status,
          'airlinesPnr', p_data->'airlinesPnr',
          'ticketNumbers', p_data->'ticketNumbers'
        )
      );
    end if;
    return v_booking;
  end if;

  insert into public.booking_attempts (
    id, access_token_hash, user_id, audience, agency_code, supplier, state,
    search_id, itinerary_id, unique_trans_id, item_code_ref, price_code_ref,
    booking_code_ref, pnr, offer_snapshot, passenger_snapshot,
    expires_at, submitted_at, resolved_at, created_at
  ) values (
    v_attempt_id, v_access_hash, v_target_user_id, v_audience, v_agency_code,
    v_supplier, 'succeeded', v_search_id,
    'impexp:' || lower(v_supplier) || ':' || v_supplier_ref,
    v_supplier_ref, v_supplier_ref, v_supplier_ref,
    'impexp:' || v_supplier_ref,
    coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
    v_offer, p_data->'passengers', v_imported_at, v_imported_at,
    v_imported_at, v_imported_at
  );

  insert into public.flight_bookings (
    id, public_ref, attempt_id, supplier, user_id, audience, agency_code,
    search_id, itinerary_id, status, operation_kind, operation_reason,
    operation_started_at, currency, pricing_snapshot,
    passenger_counts, travel_date, direct_ticketing, itinerary, fares,
    passport_required, supplier_refs, repriced_at, accepted_at, passengers,
    pnr, airlines_pnr, booking_ref_number, booking_status, ticketing_time_limit,
    ticketing_deadline_at, deadline_source, booking_code_ref, ticket_numbers,
    warnings, supplier_message, issued_at, cancelled_at, submission_started_at,
    legacy_operational, booked_by_user_id, import_source, imported_by_user_id,
    import_metadata, created_at
  ) values (
    gen_random_uuid(), public.allocate_booking_ref(), v_attempt_id, v_supplier,
    v_target_user_id, v_audience, v_agency_code, v_search_id,
    'impexp:' || lower(v_supplier) || ':' || v_supplier_ref,
    v_status,
    case when v_status = 'in-progress' then 'reconciliation' else null end,
    case when v_status = 'in-progress' then 'legacy_reconciliation' else null end,
    case when v_status = 'in-progress' then v_imported_at else null end,
    coalesce(nullif(p_data->>'currency', ''), 'BDT'),
    v_offer->'pricing', p_data->'passengerCounts',
    (p_data->>'travelDate')::date, v_status = 'confirmed',
    p_data->'itinerary', p_data->'fares',
    coalesce((p_data->>'passportRequired')::boolean, true),
    jsonb_strip_nulls(jsonb_build_object(
      'uniqueTransId', v_supplier_ref,
      'itemCodeRef', v_supplier_ref,
      'priceCodeRef', v_supplier_ref,
      'externalImport', true,
      'originalReference', nullif(p_data->>'originalReference', '')
    )),
    v_imported_at, v_imported_at, p_data->'passengers',
    coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
    p_data->'airlinesPnr', v_supplier_ref, p_data->>'orderStatus',
    nullif(p_data->>'ticketingTimeLimit', ''),
    nullif(p_data->>'ticketingDeadlineAt', '')::timestamptz,
    case when nullif(p_data->>'ticketingDeadlineAt', '') is not null
      then 'supplier' else null end,
    'impexp:' || v_supplier_ref, p_data->'ticketNumbers', '[]'::jsonb,
    nullif(p_data->>'supplierMessage', ''),
    case when v_status = 'confirmed' then v_imported_at end,
    case when v_status = 'cancelled' then v_imported_at end,
    v_imported_at, false, p_actor_user_id, 'IMP_EXP', p_actor_user_id,
    jsonb_build_object(
      'provider', v_supplier,
      'supplierReference', v_supplier_ref,
      'originalReference', nullif(p_data->>'originalReference', ''),
      'orderStatus', p_data->>'orderStatus',
      'lifecycleStatus', v_lifecycle_status,
      'lastSyncedAt', v_imported_at
    ),
    v_imported_at
  ) returning * into v_booking;

  return v_booking;
exception
  when unique_violation then
    select * into v_existing
      from public.flight_bookings
     where import_source = 'IMP_EXP'
       and supplier = v_supplier
       and booking_ref_number = v_supplier_ref
     limit 1;
    if found then return v_existing; end if;
    raise;
end;
$$;

revoke all on function public.create_impexp_booking(text,text,jsonb)
  from public, anon, authenticated;
grant execute on function public.create_impexp_booking(text,text,jsonb)
  to service_role;

comment on column public.flight_bookings.import_source is
  'IMP_EXP for bookings retrieved from an external supplier by privileged staff.';


-- SOURCE: 0038_impexp_passenger_details.sql
-- Preserve optional supplier/original references and passenger supplements
-- for IMP/EXP imports after the initial import migration has already shipped.

create or replace function public.create_impexp_booking(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_data jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_target_user_id text;
  v_target_role text;
  v_agency_code text;
  v_audience text;
  v_supplier text;
  v_supplier_ref text;
  v_status text;
  v_lifecycle_status text;
  v_old_lifecycle text;
  v_new_lifecycle text;
  v_imported_at timestamptz;
  v_attempt_id uuid := gen_random_uuid();
  v_search_id uuid := gen_random_uuid();
  v_access_hash text;
  v_offer jsonb;
  v_existing public.flight_bookings;
  v_booking public.flight_bookings;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' then
    raise exception 'import payload must be an object' using errcode = '22023';
  end if;

  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    raise exception 'IMP/EXP access is forbidden' using errcode = '42501';
  end if;

  v_supplier := nullif(trim(p_data->>'provider'), '');
  v_supplier_ref := nullif(trim(p_data->>'supplierReference'), '');
  if v_supplier not in ('US_BANGLA', 'AIR_ASTRA', 'NOVOAIR')
     or v_supplier_ref is null then
    raise exception 'invalid supplier import identity' using errcode = '22023';
  end if;

  v_target_user_id := nullif(trim(p_assigned_user_id), '');
  if v_target_user_id is not null then
    select role, agency_code into v_target_role, v_agency_code
      from public.app_users
     where clerk_id = v_target_user_id;
    if not found or v_target_role not in ('b2b', 'b2b_sub', 'customer') then
      raise exception 'assigned user is not eligible for IMP/EXP' using errcode = '22023';
    end if;
    if v_target_role in ('b2b', 'b2b_sub') then
      if nullif(trim(v_agency_code), '') is null then
        raise exception 'assigned agency user has no agency' using errcode = '22023';
      end if;
      v_audience := 'agency';
    else
      v_audience := 'b2c';
      v_agency_code := null;
    end if;
  else
    v_target_user_id := p_actor_user_id;
    v_target_role := v_actor_role;
    v_agency_code := null;
    v_audience := 'superadmin';
  end if;

  v_status := p_data->>'storedStatus';
  v_lifecycle_status := p_data->>'lifecycleStatus';
  if v_status is null
     or v_lifecycle_status is null
     or v_status not in ('on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled')
     or v_lifecycle_status not in (
       'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
       'unconfirmed', 'cancelled'
     )
     or (v_lifecycle_status in ('expired', 'unconfirmed') and v_status <> 'on-hold')
     or (v_lifecycle_status not in ('expired', 'unconfirmed') and v_lifecycle_status <> v_status) then
    raise exception 'invalid imported booking status' using errcode = '22023';
  end if;
  if coalesce(p_data->>'travelDate', '') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'invalid imported travel date' using errcode = '22007';
  end if;
  if jsonb_typeof(p_data->'passengerCounts') <> 'object'
     or jsonb_typeof(p_data->'itinerary') <> 'object'
     or jsonb_typeof(p_data->'fares') <> 'array'
     or jsonb_typeof(p_data->'passengers') <> 'object'
     or jsonb_typeof(p_data->'airlinesPnr') <> 'array'
     or jsonb_typeof(p_data->'ticketNumbers') <> 'array' then
    raise exception 'invalid normalized import payload' using errcode = '22023';
  end if;

  v_imported_at := coalesce(
    nullif(p_data->>'importedAt', '')::timestamptz,
    now()
  );
  v_offer := jsonb_build_object(
    'itinerary', p_data->'itinerary',
    'fares', p_data->'fares',
    'currency', coalesce(nullif(p_data->>'currency', ''), 'BDT'),
    'pricing', jsonb_build_object(
      'audience', v_audience,
      'agencyCode', v_agency_code,
      'sellingPrice', greatest(0, coalesce((p_data->>'totalPrice')::numeric, 0)),
      'supplierTotalPrice', greatest(0, coalesce((p_data->>'totalPrice')::numeric, 0)),
      'grossPrice', greatest(0, coalesce((p_data->>'totalPrice')::numeric, 0)),
      'serviceMarginAmount', 0,
      'ruleId', null,
      'basis', 'supplier'
    ),
    'passengerCounts', p_data->'passengerCounts',
    'travelDate', p_data->>'travelDate',
    'directTicketing', v_status = 'confirmed',
    'passportRequired', coalesce((p_data->>'passportRequired')::boolean, true),
    'repricedAt', v_imported_at
  );
  v_access_hash := md5(v_attempt_id::text || clock_timestamp()::text)
    || md5(v_search_id::text || random()::text);

  -- A repeated import is a supplier status refresh, not a duplicate booking.
  -- Reuse the STR reference and append a lifecycle event only when its public
  -- status actually changes.
  select * into v_existing
    from public.flight_bookings
   where import_source = 'IMP_EXP'
     and supplier = v_supplier
     and booking_ref_number = v_supplier_ref
   limit 1
   for update;
  if found then
    v_old_lifecycle := public.resolve_booking_lifecycle(
      v_existing.status,
      v_existing.airlines_pnr,
      v_existing.ticketing_deadline_at,
      v_existing.operation_kind
    );

    update public.booking_attempts
       set user_id = v_target_user_id,
           audience = v_audience,
           agency_code = v_agency_code,
           supplier = v_supplier,
           offer_snapshot = v_offer,
           passenger_snapshot = p_data->'passengers',
           pnr = coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
           resolved_at = v_imported_at
     where id = v_existing.attempt_id;

    update public.flight_bookings
       set user_id = v_target_user_id,
           audience = v_audience,
           agency_code = v_agency_code,
           booking_owner_type = null,
           booking_owner_key = null,
           status = v_status,
           operation_kind = case when v_status = 'in-progress'
             then 'reconciliation' else null end,
           operation_reason = case when v_status = 'in-progress'
             then 'legacy_reconciliation' else null end,
           operation_request_id = null,
           operation_actor_user_id = null,
           operation_started_at = case when v_status = 'in-progress'
             then v_imported_at else null end,
           operation_prior_status = null,
           currency = coalesce(nullif(p_data->>'currency', ''), 'BDT'),
           pricing_snapshot = v_offer->'pricing',
           passenger_counts = p_data->'passengerCounts',
           travel_date = (p_data->>'travelDate')::date,
           direct_ticketing = v_status = 'confirmed',
           itinerary = p_data->'itinerary',
           fares = p_data->'fares',
           passport_required = coalesce(
             (p_data->>'passportRequired')::boolean,
             true
           ),
           supplier_refs = jsonb_strip_nulls(
             coalesce(v_existing.supplier_refs, '{}'::jsonb)
             || jsonb_build_object(
               'originalReference', nullif(p_data->>'originalReference', '')
             )
           ),
           repriced_at = v_imported_at,
           accepted_at = v_imported_at,
           passengers = p_data->'passengers',
           pnr = coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
           airlines_pnr = p_data->'airlinesPnr',
           booking_status = p_data->>'orderStatus',
           ticketing_time_limit = nullif(p_data->>'ticketingTimeLimit', ''),
           ticketing_deadline_at = nullif(
             p_data->>'ticketingDeadlineAt',
             ''
           )::timestamptz,
           deadline_source = case
             when nullif(p_data->>'ticketingDeadlineAt', '') is not null
               then 'supplier'
             else null
           end,
           ticket_numbers = p_data->'ticketNumbers',
           supplier_message = nullif(p_data->>'supplierMessage', ''),
           issued_at = case when v_status = 'confirmed'
             then coalesce(v_existing.issued_at, v_imported_at) else null end,
           cancelled_at = case when v_status = 'cancelled'
             then coalesce(v_existing.cancelled_at, v_imported_at) else null end,
           booked_by_user_id = p_actor_user_id,
           imported_by_user_id = p_actor_user_id,
           import_metadata = jsonb_build_object(
             'provider', v_supplier,
             'supplierReference', v_supplier_ref,
             'originalReference', nullif(p_data->>'originalReference', ''),
             'orderStatus', p_data->>'orderStatus',
             'lifecycleStatus', v_lifecycle_status,
             'lastSyncedAt', v_imported_at
           )
     where id = v_existing.id
     returning * into v_booking;

    v_new_lifecycle := public.resolve_booking_lifecycle(
      v_booking.status,
      v_booking.airlines_pnr,
      v_booking.ticketing_deadline_at,
      v_booking.operation_kind
    );
    if v_old_lifecycle is distinct from v_new_lifecycle then
      insert into public.booking_status_events (
        booking_id, from_lifecycle_status, to_lifecycle_status,
        stored_status_before, stored_status_after, operation_kind,
        operation_reason, actor_user_id, supplier_operation,
        supplier_evidence
      ) values (
        v_booking.id, v_old_lifecycle, v_new_lifecycle,
        v_existing.status, v_booking.status, v_booking.operation_kind,
        v_booking.operation_reason, p_actor_user_id, 'ImportSync',
        jsonb_build_object(
          'provider', v_supplier,
          'supplierStatus', p_data->>'orderStatus',
          'lifecycleStatus', v_lifecycle_status,
          'airlinesPnr', p_data->'airlinesPnr',
          'ticketNumbers', p_data->'ticketNumbers'
        )
      );
    end if;
    return v_booking;
  end if;

  insert into public.booking_attempts (
    id, access_token_hash, user_id, audience, agency_code, supplier, state,
    search_id, itinerary_id, unique_trans_id, item_code_ref, price_code_ref,
    booking_code_ref, pnr, offer_snapshot, passenger_snapshot,
    expires_at, submitted_at, resolved_at, created_at
  ) values (
    v_attempt_id, v_access_hash, v_target_user_id, v_audience, v_agency_code,
    v_supplier, 'succeeded', v_search_id,
    'impexp:' || lower(v_supplier) || ':' || v_supplier_ref,
    v_supplier_ref, v_supplier_ref, v_supplier_ref,
    'impexp:' || v_supplier_ref,
    coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
    v_offer, p_data->'passengers', v_imported_at, v_imported_at,
    v_imported_at, v_imported_at
  );

  insert into public.flight_bookings (
    id, public_ref, attempt_id, supplier, user_id, audience, agency_code,
    search_id, itinerary_id, status, operation_kind, operation_reason,
    operation_started_at, currency, pricing_snapshot,
    passenger_counts, travel_date, direct_ticketing, itinerary, fares,
    passport_required, supplier_refs, repriced_at, accepted_at, passengers,
    pnr, airlines_pnr, booking_ref_number, booking_status, ticketing_time_limit,
    ticketing_deadline_at, deadline_source, booking_code_ref, ticket_numbers,
    warnings, supplier_message, issued_at, cancelled_at, submission_started_at,
    legacy_operational, booked_by_user_id, import_source, imported_by_user_id,
    import_metadata, created_at
  ) values (
    gen_random_uuid(), public.allocate_booking_ref(), v_attempt_id, v_supplier,
    v_target_user_id, v_audience, v_agency_code, v_search_id,
    'impexp:' || lower(v_supplier) || ':' || v_supplier_ref,
    v_status,
    case when v_status = 'in-progress' then 'reconciliation' else null end,
    case when v_status = 'in-progress' then 'legacy_reconciliation' else null end,
    case when v_status = 'in-progress' then v_imported_at else null end,
    coalesce(nullif(p_data->>'currency', ''), 'BDT'),
    v_offer->'pricing', p_data->'passengerCounts',
    (p_data->>'travelDate')::date, v_status = 'confirmed',
    p_data->'itinerary', p_data->'fares',
    coalesce((p_data->>'passportRequired')::boolean, true),
    jsonb_strip_nulls(jsonb_build_object(
      'uniqueTransId', v_supplier_ref,
      'itemCodeRef', v_supplier_ref,
      'priceCodeRef', v_supplier_ref,
      'externalImport', true,
      'originalReference', nullif(p_data->>'originalReference', '')
    )),
    v_imported_at, v_imported_at, p_data->'passengers',
    coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
    p_data->'airlinesPnr', v_supplier_ref, p_data->>'orderStatus',
    nullif(p_data->>'ticketingTimeLimit', ''),
    nullif(p_data->>'ticketingDeadlineAt', '')::timestamptz,
    case when nullif(p_data->>'ticketingDeadlineAt', '') is not null
      then 'supplier' else null end,
    'impexp:' || v_supplier_ref, p_data->'ticketNumbers', '[]'::jsonb,
    nullif(p_data->>'supplierMessage', ''),
    case when v_status = 'confirmed' then v_imported_at end,
    case when v_status = 'cancelled' then v_imported_at end,
    v_imported_at, false, p_actor_user_id, 'IMP_EXP', p_actor_user_id,
    jsonb_build_object(
      'provider', v_supplier,
      'supplierReference', v_supplier_ref,
      'originalReference', nullif(p_data->>'originalReference', ''),
      'orderStatus', p_data->>'orderStatus',
      'lifecycleStatus', v_lifecycle_status,
      'lastSyncedAt', v_imported_at
    ),
    v_imported_at
  ) returning * into v_booking;

  return v_booking;
exception
  when unique_violation then
    select * into v_existing
      from public.flight_bookings
     where import_source = 'IMP_EXP'
       and supplier = v_supplier
       and booking_ref_number = v_supplier_ref
     limit 1;
    if found then return v_existing; end if;
    raise;
end;
$$;

revoke all on function public.create_impexp_booking(text,text,jsonb)
  from public, anon, authenticated;
grant execute on function public.create_impexp_booking(text,text,jsonb)
  to service_role;


-- SOURCE: 0039_fix_us_bangla_pnr_month_day_deadlines.sql
-- Historical booking-only repair omitted: there are no previous bookings.


-- SOURCE: 0040_impexp_wallet_and_sync.sql
-- Imported-booking commercial pricing, controlled wallet capture, and
-- supplier synchronization. Imported bookings continue to use the shared
-- wallet, reservation, ledger, payment, ownership, and lifecycle tables.

alter table public.flight_bookings
  add column if not exists supplier_gross_amount bigint
    check (supplier_gross_amount is null or supplier_gross_amount >= 0),
  add column if not exists user_payable_amount bigint
    check (user_payable_amount is null or user_payable_amount > 0);

comment on column public.flight_bookings.supplier_gross_amount is
  'Supplier/reference gross in integer minor units. Never used as an imported customer wallet debit.';
comment on column public.flight_bookings.user_payable_amount is
  'Locally agreed customer/agency payable in integer minor units. The only amount an imported booking may charge.';

-- PostgreSQL expands `fb.*` when a view is created. Rebuild the lifecycle view
-- so columns added by IMP/EXP migrations (including import_source and the two
-- prices above) are available to the normal booking read path.
drop view if exists public.booking_payment_report_v;
drop view if exists public.booking_lifecycle_v;
create view public.booking_lifecycle_v
with (security_invoker = true)
as
select
  fb.*,
  public.resolve_booking_lifecycle(
    fb.status, fb.airlines_pnr, fb.ticketing_deadline_at, fb.operation_kind
  ) as lifecycle_status
from public.flight_bookings fb
where not fb.legacy_operational;

create view public.booking_payment_report_v
with (security_invoker = true)
as
select
  fb.id as booking_id,
  fb.public_ref,
  fb.booking_owner_type,
  fb.booking_owner_key,
  fb.booked_by_user_id,
  fb.issued_by_user_id,
  fb.charged_wallet_account_id,
  fb.payment_state,
  fb.payment_amount,
  fb.captured_amount,
  fb.refunded_amount,
  fb.currency,
  fb.lifecycle_status as booking_status,
  fb.created_at,
  fb.issued_at
from public.booking_lifecycle_v fb;

revoke all on table public.booking_lifecycle_v from public, anon, authenticated;
revoke all on table public.booking_payment_report_v from public, anon, authenticated;
grant select on table public.booking_lifecycle_v to service_role;
grant select on table public.booking_payment_report_v to service_role;

comment on view public.booking_lifecycle_v is
  'Canonical seven-state booking lifecycle projection, including current IMP/EXP columns.';
comment on view public.booking_payment_report_v is
  'One payment-state summary row per non-legacy business booking.';

-- A paid imported hold is intentionally waiting for manual external
-- ticketing, not for an application-side supplier call.
alter table public.flight_bookings
  drop constraint if exists flight_bookings_operation_reason_check;
alter table public.flight_bookings
  add constraint flight_bookings_operation_reason_check
  check (operation_reason is null or operation_reason in (
    'ticketing',
    'supplier_balance_insufficient',
    'ticketing_reconciliation',
    'cancellation',
    'cancellation_reconciliation',
    'terminal_state_conflict',
    'direct_ticket_payment_reconciliation',
    'legacy_reconciliation',
    'imported_manual_ticketing'
  ));

-- Supplier synchronization is deliberately non-financial. It updates only
-- supplier-controlled snapshots and safe lifecycle state. In particular it
-- never writes wallet tables, payment fields, the wallet owner, or the local
-- user payable.
create or replace function public.sync_impexp_booking(
  p_actor_user_id text,
  p_booking_id uuid,
  p_supplier_gross_amount bigint,
  p_data jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_updated public.flight_bookings;
  v_supplier text;
  v_supplier_ref text;
  v_supplier_status text;
  v_supplier_lifecycle text;
  v_old_lifecycle text;
  v_new_status text;
  v_new_operation_kind text;
  v_new_operation_reason text;
  v_sync_at timestamptz;
  v_supplier_gross_major numeric;
  v_pricing jsonb;
  v_offer jsonb;
begin
  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'IMPEXP_FORBIDDEN');
  end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object'
     or p_supplier_gross_amount is null or p_supplier_gross_amount < 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end if;

  select * into v_booking
    from public.flight_bookings
   where id = p_booking_id and import_source = 'IMP_EXP'
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  if v_booking.user_payable_amount is null
     or v_booking.booking_owner_type is null
     or v_booking.booking_owner_key is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'HISTORICAL_IMPORT_RECONCILIATION_REQUIRED'
    );
  end if;

  v_supplier := nullif(trim(p_data->>'provider'), '');
  v_supplier_ref := nullif(trim(p_data->>'supplierReference'), '');
  if v_supplier is distinct from v_booking.supplier
     or v_supplier_ref is distinct from v_booking.booking_ref_number then
    return jsonb_build_object('ok', false, 'code', 'IMPORT_IDENTITY_MISMATCH');
  end if;
  if jsonb_typeof(p_data->'passengerCounts') <> 'object'
     or jsonb_typeof(p_data->'itinerary') <> 'object'
     or jsonb_typeof(p_data->'fares') <> 'array'
     or jsonb_typeof(p_data->'passengers') <> 'object'
     or jsonb_typeof(p_data->'airlinesPnr') <> 'array'
     or jsonb_typeof(p_data->'ticketNumbers') <> 'array' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end if;

  v_supplier_status := p_data->>'storedStatus';
  v_supplier_lifecycle := p_data->>'lifecycleStatus';
  if v_supplier_status not in (
       'on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled'
     ) or v_supplier_lifecycle not in (
       'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
       'unconfirmed', 'cancelled'
     ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_STATUS');
  end if;

  v_old_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status,
    v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at,
    v_booking.operation_kind
  );
  v_sync_at := coalesce(nullif(p_data->>'importedAt', '')::timestamptz, now());
  v_supplier_gross_major := p_supplier_gross_amount::numeric / 100;
  v_pricing := coalesce(v_booking.pricing_snapshot, '{}'::jsonb)
    || jsonb_build_object(
      'supplierTotalPrice', v_supplier_gross_major,
      'grossPrice', v_supplier_gross_major
    );
  select offer_snapshot into v_offer
    from public.booking_attempts
   where id = v_booking.attempt_id;
  v_offer := coalesce(v_offer, '{}'::jsonb)
    || jsonb_build_object(
      'itinerary', p_data->'itinerary',
      'fares', p_data->'fares',
      'currency', v_booking.currency,
      'pricing', coalesce(v_offer->'pricing', v_pricing) || jsonb_build_object(
        'supplierTotalPrice', v_supplier_gross_major,
        'grossPrice', v_supplier_gross_major,
        'sellingPrice', v_booking.user_payable_amount::numeric / 100
      ),
      'passengerCounts', p_data->'passengerCounts',
      'travelDate', p_data->>'travelDate',
      'passportRequired', coalesce((p_data->>'passportRequired')::boolean, true),
      'repricedAt', v_sync_at
    );

  -- Captured In Progress rows only become Confirmed on authoritative supplier
  -- confirmation. A held response leaves the manual-ticketing state intact.
  if v_booking.payment_state = 'captured' then
    if v_booking.status = 'in-progress' and v_supplier_lifecycle = 'confirmed' then
      v_new_status := 'confirmed';
      v_new_operation_kind := null;
      v_new_operation_reason := null;
    elsif v_booking.status = 'in-progress' then
      v_new_status := 'in-progress';
      if v_supplier_lifecycle in ('cancelled', 'expired', 'unconfirmed') then
        v_new_operation_kind := 'reconciliation';
        v_new_operation_reason := 'ticketing_reconciliation';
      else
        v_new_operation_kind := coalesce(v_booking.operation_kind, 'ticketing');
        v_new_operation_reason := coalesce(
          v_booking.operation_reason,
          'imported_manual_ticketing'
        );
      end if;
    elsif v_booking.status = 'confirmed' then
      v_new_status := 'confirmed';
      if v_supplier_lifecycle in ('cancelled', 'expired', 'unconfirmed') then
        v_new_operation_kind := 'reconciliation';
        v_new_operation_reason := 'terminal_state_conflict';
      else
        v_new_operation_kind := null;
        v_new_operation_reason := null;
      end if;
    else
      v_new_status := 'in-progress';
      v_new_operation_kind := 'reconciliation';
      v_new_operation_reason := 'ticketing_reconciliation';
    end if;
  else
    -- Sync never turns an unpaid supplier confirmation into a paid booking.
    if v_supplier_lifecycle = 'confirmed' then
      v_new_status := 'in-progress';
      v_new_operation_kind := 'reconciliation';
      v_new_operation_reason := 'ticketing_reconciliation';
    else
      v_new_status := v_supplier_status;
      v_new_operation_kind := case when v_supplier_status = 'in-progress'
        then 'reconciliation' else null end;
      v_new_operation_reason := case when v_supplier_status = 'in-progress'
        then 'ticketing_reconciliation' else null end;
    end if;
  end if;

  update public.booking_attempts
     set supplier = v_supplier,
         offer_snapshot = v_offer,
         passenger_snapshot = p_data->'passengers',
         pnr = coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
         resolved_at = v_sync_at
   where id = v_booking.attempt_id;

  update public.flight_bookings
     set status = v_new_status,
         operation_kind = v_new_operation_kind,
         operation_reason = v_new_operation_reason,
         operation_request_id = case when v_new_operation_kind is null
           then null else operation_request_id end,
         operation_actor_user_id = case when v_new_operation_kind is null
           then null else coalesce(operation_actor_user_id, p_actor_user_id) end,
         operation_started_at = case when v_new_operation_kind is null
           then null else coalesce(operation_started_at, v_sync_at) end,
         operation_prior_status = case when v_new_operation_kind is null
           then null else coalesce(operation_prior_status, 'on-hold') end,
         pricing_snapshot = v_pricing,
         supplier_gross_amount = p_supplier_gross_amount,
         passenger_counts = p_data->'passengerCounts',
         travel_date = (p_data->>'travelDate')::date,
         direct_ticketing = v_new_status = 'confirmed',
         itinerary = p_data->'itinerary',
         fares = p_data->'fares',
         passport_required = coalesce((p_data->>'passportRequired')::boolean, true),
         supplier_refs = jsonb_strip_nulls(
           coalesce(supplier_refs, '{}'::jsonb)
           || jsonb_build_object(
             'originalReference', nullif(p_data->>'originalReference', '')
           )
         ),
         repriced_at = v_sync_at,
         passengers = p_data->'passengers',
         pnr = coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
         airlines_pnr = p_data->'airlinesPnr',
         booking_status = p_data->>'orderStatus',
         ticketing_time_limit = nullif(p_data->>'ticketingTimeLimit', ''),
         ticketing_deadline_at = nullif(p_data->>'ticketingDeadlineAt', '')::timestamptz,
         deadline_source = case
           when nullif(p_data->>'ticketingDeadlineAt', '') is not null
             then 'supplier'
           else null
         end,
         ticket_numbers = p_data->'ticketNumbers',
         supplier_message = nullif(p_data->>'supplierMessage', ''),
         issued_at = case when v_new_status = 'confirmed'
           then coalesce(issued_at, v_sync_at) else issued_at end,
         cancelled_at = case
           when v_booking.payment_state <> 'captured' and v_new_status = 'cancelled'
             then coalesce(cancelled_at, v_sync_at)
           else cancelled_at
         end,
         import_metadata = coalesce(import_metadata, '{}'::jsonb)
           || jsonb_strip_nulls(jsonb_build_object(
             'provider', v_supplier,
             'supplierReference', v_supplier_ref,
             'originalReference', nullif(p_data->>'originalReference', ''),
             'orderStatus', p_data->>'orderStatus',
             'lifecycleStatus', v_supplier_lifecycle,
             'lastSyncedAt', v_sync_at,
             'lastSyncedBy', p_actor_user_id
           ))
   where id = v_booking.id
   returning * into v_updated;

  if v_old_lifecycle is distinct from public.resolve_booking_lifecycle(
       v_updated.status,
       v_updated.airlines_pnr,
       v_updated.ticketing_deadline_at,
       v_updated.operation_kind
     ) then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation, supplier_evidence
    ) values (
      v_updated.id,
      v_old_lifecycle,
      public.resolve_booking_lifecycle(
        v_updated.status,
        v_updated.airlines_pnr,
        v_updated.ticketing_deadline_at,
        v_updated.operation_kind
      ),
      v_booking.status,
      v_updated.status,
      v_updated.operation_kind,
      v_updated.operation_reason,
      p_actor_user_id,
      'ImportSync',
      jsonb_build_object(
        'provider', v_supplier,
        'supplierStatus', p_data->>'orderStatus',
        'lifecycleStatus', v_supplier_lifecycle,
        'airlinesPnr', p_data->'airlinesPnr',
        'ticketNumbers', p_data->'ticketNumbers',
        'walletMutation', false
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'booking', to_jsonb(v_updated),
    'walletCharged', false,
    'status', public.resolve_booking_lifecycle(
      v_updated.status,
      v_updated.airlines_pnr,
      v_updated.ticketing_deadline_at,
      v_updated.operation_kind
    )
  );
end;
$$;

-- A customer or agency user confirms an imported hold without calling a
-- supplier ticket API. The payable capture, ledger row, payment attribution,
-- and On Hold -> In Progress transition share this one transaction.
create or replace function public.wallet_confirm_impexp_booking(
  p_booking_id uuid,
  p_actor_user_id text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
  v_actor_agency text;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_reservation public.wallet_reservations;
  v_available_before bigint;
  v_hold_before bigint;
  v_ledger_key text;
begin
  if nullif(trim(p_actor_user_id), '') is null
     or nullif(trim(p_idempotency_key), '') is null then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CONFIRM_REQUEST');
  end if;
  select role, agency_code into v_actor_role, v_actor_agency
    from public.app_users
   where clerk_id = p_actor_user_id;
  if not found or v_actor_role not in ('customer', 'b2b', 'b2b_sub') then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_CONFIRM_FORBIDDEN');
  end if;

  select * into v_booking
    from public.flight_bookings
   where id = p_booking_id and import_source = 'IMP_EXP'
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  if not (
    (v_actor_role = 'customer'
      and v_booking.booking_owner_type = 'user'
      and v_booking.booking_owner_key = p_actor_user_id)
    or
    (v_actor_role in ('b2b', 'b2b_sub')
      and nullif(trim(v_actor_agency), '') is not null
      and v_booking.booking_owner_type = 'agency'
      and v_booking.booking_owner_key = v_actor_agency)
  ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_CONFIRM_FORBIDDEN');
  end if;

  if v_booking.payment_state = 'captured' then
    return jsonb_build_object(
      'ok', true,
      'replay', true,
      'status', public.resolve_booking_lifecycle(
        v_booking.status,
        v_booking.airlines_pnr,
        v_booking.ticketing_deadline_at,
        v_booking.operation_kind
      ),
      'accountId', v_booking.charged_wallet_account_id,
      'amount', v_booking.captured_amount
    );
  end if;
  if v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.payment_state <> 'unpaid'
     or public.resolve_booking_lifecycle(
       v_booking.status,
       v_booking.airlines_pnr,
       v_booking.ticketing_deadline_at,
       v_booking.operation_kind
     ) <> 'on-hold' then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if v_booking.user_payable_amount is null or v_booking.user_payable_amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end if;

  select * into v_wallet
    from public.wallets
   where owner_type = v_booking.booking_owner_type
     and owner_key = v_booking.booking_owner_key
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select * into v_account
    from public.wallet_accounts
   where wallet_id = v_wallet.id and currency = upper(v_booking.currency)
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_account.available_balance < v_booking.user_payable_amount then
    return jsonb_build_object(
      'ok', false,
      'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance,
      'required', v_booking.user_payable_amount,
      'currency', v_account.currency
    );
  end if;
  if exists (
    select 1 from public.wallet_reservations where booking_id = v_booking.id
  ) then
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  end if;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  v_ledger_key := 'impexp-payment:' || v_booking.id::text;

  update public.wallet_accounts
     set available_balance = available_balance - v_booking.user_payable_amount
   where id = v_account.id;
  insert into public.wallet_reservations (
    wallet_account_id, booking_id, amount, currency, state,
    requested_by_user_id, issued_by_user_id, captured_at
  ) values (
    v_account.id, v_booking.id, v_booking.user_payable_amount,
    v_account.currency, 'captured', p_actor_user_id, p_actor_user_id, now()
  ) returning * into v_reservation;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks, metadata
  ) values (
    v_account.id, 'booking_confirm', v_booking.user_payable_amount,
    v_account.currency, v_available_before,
    v_available_before - v_booking.user_payable_amount,
    v_hold_before, v_hold_before, v_booking.id, v_booking.public_ref,
    v_reservation.id, v_ledger_key, p_actor_user_id, v_actor_role,
    'Customer confirmed imported booking for manual external ticketing',
    jsonb_build_object(
      'importSource', 'IMP_EXP',
      'supplierGrossAmount', v_booking.supplier_gross_amount,
      'userPayableAmount', v_booking.user_payable_amount,
      'requestId', p_idempotency_key
    )
  );
  update public.flight_bookings
     set charged_wallet_account_id = v_account.id,
         payment_state = 'captured',
         payment_amount = user_payable_amount,
         captured_amount = user_payable_amount,
         status = 'in-progress',
         operation_kind = 'ticketing',
         operation_reason = 'imported_manual_ticketing',
         operation_request_id = p_idempotency_key,
         operation_actor_user_id = p_actor_user_id,
         operation_started_at = now(),
         operation_prior_status = 'on-hold'
   where id = v_booking.id;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key
  ) values (
    v_booking.id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'ticketing', 'imported_manual_ticketing', p_actor_user_id,
    'ImportCustomerConfirm',
    jsonb_build_object(
      'walletCaptured', true,
      'supplierApiCalled', false,
      'userPayableAmount', v_booking.user_payable_amount
    ),
    v_ledger_key || ':in-progress'
  ) on conflict do nothing;

  return jsonb_build_object(
    'ok', true,
    'status', 'in-progress',
    'reservationId', v_reservation.id,
    'accountId', v_account.id,
    'amount', v_booking.user_payable_amount,
    'currency', v_account.currency,
    'availableBalance', v_available_before - v_booking.user_payable_amount,
    'holdBalance', v_hold_before
  );
end;
$$;

drop function if exists public.create_impexp_booking(text,text,jsonb);

-- Initial import and direct-confirmed capture are serialized by stable supplier
-- identity. A retry/re-import sees the existing row before any possible debit.
create or replace function public.create_impexp_booking(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_data jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_target_role text;
  v_agency_code text;
  v_audience text;
  v_owner_type text;
  v_owner_key text;
  v_supplier text;
  v_supplier_ref text;
  v_currency text;
  v_status text;
  v_lifecycle_status text;
  v_imported_at timestamptz;
  v_attempt_id uuid := gen_random_uuid();
  v_search_id uuid := gen_random_uuid();
  v_access_hash text;
  v_offer jsonb;
  v_existing public.flight_bookings;
  v_booking public.flight_bookings;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_reservation public.wallet_reservations;
  v_available_before bigint;
  v_hold_before bigint;
  v_ledger_key text;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object'
     or nullif(trim(p_assigned_user_id), '') is null
     or p_user_payable_amount is null or p_user_payable_amount <= 0
     or p_supplier_gross_amount is null or p_supplier_gross_amount < 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end if;
  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'IMPEXP_FORBIDDEN');
  end if;

  v_supplier := nullif(trim(p_data->>'provider'), '');
  v_supplier_ref := nullif(trim(p_data->>'supplierReference'), '');
  v_currency := upper(coalesce(nullif(trim(p_data->>'currency'), ''), 'BDT'));
  if v_supplier not in ('US_BANGLA', 'AIR_ASTRA', 'NOVOAIR')
     or v_supplier_ref is null or v_currency !~ '^[A-Z]{3}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_IDENTITY');
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended('IMP_EXP:' || v_supplier || ':' || v_supplier_ref, 0)
  );

  select role, agency_code into v_target_role, v_agency_code
    from public.app_users
   where clerk_id = p_assigned_user_id;
  if not found or v_target_role not in ('b2b', 'b2b_sub', 'customer') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_ASSIGNEE');
  end if;
  if v_target_role in ('b2b', 'b2b_sub') then
    if nullif(trim(v_agency_code), '') is null then
      return jsonb_build_object('ok', false, 'code', 'ASSIGNEE_AGENCY_REQUIRED');
    end if;
    v_audience := 'agency';
    v_owner_type := 'agency';
    v_owner_key := v_agency_code;
  else
    v_audience := 'b2c';
    v_agency_code := null;
    v_owner_type := 'user';
    v_owner_key := p_assigned_user_id;
  end if;

  v_status := p_data->>'storedStatus';
  v_lifecycle_status := p_data->>'lifecycleStatus';
  if v_status not in ('on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled')
     or v_lifecycle_status not in (
       'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
       'unconfirmed', 'cancelled'
     )
     or (v_lifecycle_status in ('expired', 'unconfirmed') and v_status <> 'on-hold')
     or (v_lifecycle_status not in ('expired', 'unconfirmed')
       and v_lifecycle_status <> v_status)
     or coalesce(p_data->>'travelDate', '') !~ '^\d{4}-\d{2}-\d{2}$'
     or jsonb_typeof(p_data->'passengerCounts') <> 'object'
     or jsonb_typeof(p_data->'itinerary') <> 'object'
     or jsonb_typeof(p_data->'fares') <> 'array'
     or jsonb_typeof(p_data->'passengers') <> 'object'
     or jsonb_typeof(p_data->'airlinesPnr') <> 'array'
     or jsonb_typeof(p_data->'ticketNumbers') <> 'array' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end if;

  select * into v_existing
    from public.flight_bookings
   where import_source = 'IMP_EXP'
     and supplier = v_supplier
     and booking_ref_number = v_supplier_ref
   limit 1
   for update;
  if found then
    if v_existing.user_payable_amount is null
       or v_existing.booking_owner_type is null
       or v_existing.booking_owner_key is null then
      return jsonb_build_object(
        'ok', false,
        'code', 'HISTORICAL_IMPORT_RECONCILIATION_REQUIRED'
      );
    end if;
    if v_existing.user_id is distinct from p_assigned_user_id
       or v_existing.booking_owner_type is distinct from v_owner_type
       or v_existing.booking_owner_key is distinct from v_owner_key then
      return jsonb_build_object('ok', false, 'code', 'IMPORT_ASSIGNEE_MISMATCH');
    end if;
    if v_existing.user_payable_amount <> p_user_payable_amount then
      return jsonb_build_object('ok', false, 'code', 'IMPORT_PAYABLE_MISMATCH');
    end if;
    if v_existing.payment_state <> 'captured'
       and v_lifecycle_status = 'confirmed' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REIMPORT_CONFIRMATION_REQUIRES_RECONCILIATION'
      );
    end if;
    return public.sync_impexp_booking(
      p_actor_user_id,
      v_existing.id,
      p_supplier_gross_amount,
      p_data
    ) || jsonb_build_object('reimport', true, 'walletCharged', false);
  end if;

  -- Assignment is required to resolve to an already-existing wallet account.
  -- On Hold imports do not require funds yet, but they may not be ownerless.
  select * into v_wallet
    from public.wallets
   where owner_type = v_owner_type and owner_key = v_owner_key;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select * into v_account
    from public.wallet_accounts
   where wallet_id = v_wallet.id and currency = v_currency;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if v_status = 'confirmed' then
    select * into strict v_wallet
      from public.wallets where id = v_wallet.id for update;
    select * into strict v_account
      from public.wallet_accounts where id = v_account.id for update;
    if v_wallet.status <> 'active' then
      return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
    end if;
    if v_account.available_balance < p_user_payable_amount then
      return jsonb_build_object(
        'ok', false,
        'code', 'INSUFFICIENT_FUNDS',
        'available', v_account.available_balance,
        'required', p_user_payable_amount,
        'currency', v_currency
      );
    end if;
  end if;

  v_imported_at := coalesce(nullif(p_data->>'importedAt', '')::timestamptz, now());
  v_offer := jsonb_build_object(
    'itinerary', p_data->'itinerary',
    'fares', p_data->'fares',
    'currency', v_currency,
    'pricing', jsonb_build_object(
      'audience', v_audience,
      'agencyCode', v_agency_code,
      'sellingPrice', p_user_payable_amount::numeric / 100,
      'supplierTotalPrice', p_supplier_gross_amount::numeric / 100,
      'grossPrice', p_supplier_gross_amount::numeric / 100,
      'serviceMarginAmount', 0,
      'ruleId', null,
      'basis', 'supplier'
    ),
    'passengerCounts', p_data->'passengerCounts',
    'travelDate', p_data->>'travelDate',
    'directTicketing', v_status = 'confirmed',
    'passportRequired', coalesce((p_data->>'passportRequired')::boolean, true),
    'repricedAt', v_imported_at
  );
  v_access_hash := md5(v_attempt_id::text || clock_timestamp()::text)
    || md5(v_search_id::text || random()::text);

  insert into public.booking_attempts (
    id, access_token_hash, user_id, audience, agency_code, supplier, state,
    search_id, itinerary_id, unique_trans_id, item_code_ref, price_code_ref,
    booking_code_ref, pnr, offer_snapshot, passenger_snapshot,
    expires_at, submitted_at, resolved_at, created_at
  ) values (
    v_attempt_id, v_access_hash, p_assigned_user_id, v_audience, v_agency_code,
    v_supplier, 'succeeded', v_search_id,
    'impexp:' || lower(v_supplier) || ':' || v_supplier_ref,
    v_supplier_ref, v_supplier_ref, v_supplier_ref,
    'impexp:' || v_supplier_ref,
    coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
    v_offer, p_data->'passengers', v_imported_at, v_imported_at,
    v_imported_at, v_imported_at
  );

  insert into public.flight_bookings (
    id, public_ref, attempt_id, supplier, user_id, audience, agency_code,
    search_id, itinerary_id, status, operation_kind, operation_reason,
    operation_actor_user_id, operation_started_at, operation_prior_status,
    currency, pricing_snapshot, supplier_gross_amount, user_payable_amount,
    passenger_counts, travel_date, direct_ticketing, itinerary, fares,
    passport_required, supplier_refs, repriced_at, accepted_at, passengers,
    pnr, airlines_pnr, booking_ref_number, booking_status, ticketing_time_limit,
    ticketing_deadline_at, deadline_source, booking_code_ref, ticket_numbers,
    warnings, supplier_message, issued_at, cancelled_at, submission_started_at,
    legacy_operational, booked_by_user_id, issued_by_user_id,
    charged_wallet_account_id, payment_state, payment_amount, captured_amount,
    import_source, imported_by_user_id, import_metadata, created_at
  ) values (
    gen_random_uuid(), public.allocate_booking_ref(), v_attempt_id, v_supplier,
    p_assigned_user_id, v_audience, v_agency_code, v_search_id,
    'impexp:' || lower(v_supplier) || ':' || v_supplier_ref,
    v_status,
    case when v_status = 'in-progress' then 'reconciliation' else null end,
    case when v_status = 'in-progress' then 'ticketing_reconciliation' else null end,
    case when v_status = 'in-progress' then p_actor_user_id else null end,
    case when v_status = 'in-progress' then v_imported_at else null end,
    case when v_status = 'in-progress' then 'on-hold' else null end,
    v_currency, v_offer->'pricing', p_supplier_gross_amount,
    p_user_payable_amount, p_data->'passengerCounts',
    (p_data->>'travelDate')::date, v_status = 'confirmed',
    p_data->'itinerary', p_data->'fares',
    coalesce((p_data->>'passportRequired')::boolean, true),
    jsonb_strip_nulls(jsonb_build_object(
      'uniqueTransId', v_supplier_ref,
      'itemCodeRef', v_supplier_ref,
      'priceCodeRef', v_supplier_ref,
      'externalImport', true,
      'originalReference', nullif(p_data->>'originalReference', '')
    )),
    v_imported_at, v_imported_at, p_data->'passengers',
    coalesce(nullif(p_data->>'pnr', ''), v_supplier_ref),
    p_data->'airlinesPnr', v_supplier_ref, p_data->>'orderStatus',
    nullif(p_data->>'ticketingTimeLimit', ''),
    nullif(p_data->>'ticketingDeadlineAt', '')::timestamptz,
    case when nullif(p_data->>'ticketingDeadlineAt', '') is not null
      then 'supplier' else null end,
    'impexp:' || v_supplier_ref, p_data->'ticketNumbers', '[]'::jsonb,
    nullif(p_data->>'supplierMessage', ''),
    case when v_status = 'confirmed' then v_imported_at end,
    case when v_status = 'cancelled' then v_imported_at end,
    v_imported_at, false, p_actor_user_id,
    case when v_status = 'confirmed' then p_actor_user_id end,
    case when v_status = 'confirmed' then v_account.id end,
    case when v_status = 'confirmed' then 'captured' else 'unpaid' end,
    case when v_status = 'confirmed' then p_user_payable_amount end,
    case when v_status = 'confirmed' then p_user_payable_amount else 0 end,
    'IMP_EXP', p_actor_user_id,
    jsonb_strip_nulls(jsonb_build_object(
      'provider', v_supplier,
      'supplierReference', v_supplier_ref,
      'originalReference', nullif(p_data->>'originalReference', ''),
      'lookupLastName', nullif(p_data->>'lookupLastName', ''),
      'orderStatus', p_data->>'orderStatus',
      'lifecycleStatus', v_lifecycle_status,
      'lastSyncedAt', v_imported_at
    )),
    v_imported_at
  ) returning * into v_booking;

  if v_status = 'confirmed' then
    v_available_before := v_account.available_balance;
    v_hold_before := v_account.hold_balance;
    v_ledger_key := 'impexp-payment:' || v_booking.id::text;
    update public.wallet_accounts
       set available_balance = available_balance - p_user_payable_amount
     where id = v_account.id;
    insert into public.wallet_reservations (
      wallet_account_id, booking_id, amount, currency, state,
      requested_by_user_id, issued_by_user_id, captured_at
    ) values (
      v_account.id, v_booking.id, p_user_payable_amount, v_currency,
      'captured', p_actor_user_id, p_actor_user_id, v_imported_at
    ) returning * into v_reservation;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'booking_confirm', p_user_payable_amount, v_currency,
      v_available_before, v_available_before - p_user_payable_amount,
      v_hold_before, v_hold_before, v_booking.id, v_booking.public_ref,
      v_reservation.id, v_ledger_key, p_actor_user_id, v_actor_role,
      'Confirmed imported booking payment',
      jsonb_build_object(
        'importSource', 'IMP_EXP',
        'supplierGrossAmount', p_supplier_gross_amount,
        'userPayableAmount', p_user_payable_amount,
        'directConfirmedImport', true
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'booking', to_jsonb(v_booking),
    'walletCharged', v_status = 'confirmed',
    'amount', case when v_status = 'confirmed' then p_user_payable_amount else 0 end,
    'accountId', case when v_status = 'confirmed' then v_account.id else null end,
    'status', v_lifecycle_status
  );
end;
$$;

revoke all on function public.sync_impexp_booking(text,uuid,bigint,jsonb)
  from public, anon, authenticated;
revoke all on function public.wallet_confirm_impexp_booking(uuid,text,text)
  from public, anon, authenticated;
revoke all on function public.create_impexp_booking(text,text,bigint,bigint,jsonb)
  from public, anon, authenticated;
grant execute on function public.sync_impexp_booking(text,uuid,bigint,jsonb)
  to service_role;
grant execute on function public.wallet_confirm_impexp_booking(uuid,text,text)
  to service_role;
grant execute on function public.create_impexp_booking(text,text,bigint,bigint,jsonb)
  to service_role;


-- SOURCE: 0041_booking_status_emails.sql
-- One durable, retry-safe delivery claim for every public booking status.
-- Existing lifecycle history is baselined to prevent a deployment-time email
-- flood; only status observations created after this migration are delivered.

create table if not exists public.booking_status_email_deliveries (
  booking_id uuid not null references public.flight_bookings(id) on delete cascade,
  lifecycle_status text not null check (lifecycle_status in (
    'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
    'unconfirmed', 'cancelled'
  )),
  claimed_at timestamptz,
  completed_at timestamptz,
  outcome text check (outcome in ('sent', 'baseline')),
  attempt_count integer not null default 0 check (attempt_count >= 0),
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (booking_id, lifecycle_status)
);

alter table public.booking_status_email_deliveries enable row level security;

-- Mark every status already observed before rollout as historical. A repeated
-- status is intentionally sent once per booking, not once per operation.
insert into public.booking_status_email_deliveries (
  booking_id, lifecycle_status, completed_at, outcome
)
select distinct booking_id, to_lifecycle_status, now(), 'baseline'
from public.booking_status_events
where to_lifecycle_status in (
  'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
  'unconfirmed', 'cancelled'
)
on conflict (booking_id, lifecycle_status) do nothing;

-- Some retained rows predate complete lifecycle-event history.
insert into public.booking_status_email_deliveries (
  booking_id, lifecycle_status, completed_at, outcome
)
select id, lifecycle_status, now(), 'baseline'
from public.booking_lifecycle_v
on conflict (booking_id, lifecycle_status) do nothing;

-- Preserve the stronger evidence from the two legacy delivery columns.
update public.booking_status_email_deliveries d
set completed_at = fb.on_hold_email_sent_at,
    outcome = 'sent',
    updated_at = now()
from public.flight_bookings fb
where d.booking_id = fb.id
  and d.lifecycle_status = 'on-hold'
  and fb.on_hold_email_sent_at is not null;

update public.booking_status_email_deliveries d
set completed_at = fb.confirmed_email_sent_at,
    outcome = 'sent',
    updated_at = now()
from public.flight_bookings fb
where d.booking_id = fb.id
  and d.lifecycle_status = 'confirmed'
  and fb.confirmed_email_sent_at is not null;

create or replace function public.claim_booking_status_email(
  p_booking_id uuid,
  p_lifecycle_status text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings%rowtype;
  v_delivery public.booking_status_email_deliveries%rowtype;
  v_current_status text;
begin
  if p_lifecycle_status not in (
    'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
    'unconfirmed', 'cancelled'
  ) then
    return false;
  end if;

  select * into v_booking
  from public.flight_bookings
  where id = p_booking_id and not legacy_operational
  for update;
  if not found then return false; end if;

  v_current_status := public.resolve_booking_lifecycle(
    v_booking.status,
    v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at,
    v_booking.operation_kind
  );

  -- A fast operation may already have moved on from In Progress by the time
  -- the worker sends it, so retained lifecycle evidence is also authoritative.
  if v_current_status <> p_lifecycle_status and not exists (
    select 1 from public.booking_status_events e
    where e.booking_id = p_booking_id
      and e.to_lifecycle_status = p_lifecycle_status
  ) then
    return false;
  end if;

  insert into public.booking_status_email_deliveries (
    booking_id, lifecycle_status
  ) values (p_booking_id, p_lifecycle_status)
  on conflict (booking_id, lifecycle_status) do nothing;

  select * into v_delivery
  from public.booking_status_email_deliveries
  where booking_id = p_booking_id
    and lifecycle_status = p_lifecycle_status
  for update;

  if v_delivery.completed_at is not null
     or (
       v_delivery.claimed_at is not null
       and v_delivery.claimed_at > now() - interval '15 minutes'
     ) then
    return false;
  end if;

  update public.booking_status_email_deliveries
  set claimed_at = now(),
      attempt_count = attempt_count + 1,
      last_error = null,
      updated_at = now()
  where booking_id = p_booking_id
    and lifecycle_status = p_lifecycle_status;
  return true;
end;
$$;

create or replace function public.mark_booking_status_email_sent(
  p_booking_id uuid,
  p_lifecycle_status text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.booking_status_email_deliveries
  set claimed_at = null,
      completed_at = now(),
      outcome = 'sent',
      last_error = null,
      updated_at = now()
  where booking_id = p_booking_id
    and lifecycle_status = p_lifecycle_status;

  -- Keep legacy observability compatible during the transition.
  if p_lifecycle_status = 'on-hold' then
    update public.flight_bookings
    set on_hold_email_claimed_at = null,
        on_hold_email_sent_at = coalesce(on_hold_email_sent_at, now())
    where id = p_booking_id;
  elsif p_lifecycle_status = 'confirmed' then
    update public.flight_bookings
    set confirmed_email_claimed_at = null,
        confirmed_email_sent_at = coalesce(confirmed_email_sent_at, now()),
        confirmed_email_last_error = null
    where id = p_booking_id;
  end if;
end;
$$;

create or replace function public.fail_booking_status_email(
  p_booking_id uuid,
  p_lifecycle_status text,
  p_error text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.booking_status_email_deliveries
  set claimed_at = null,
      last_error = left(coalesce(p_error, 'Booking status email failed.'), 500),
      updated_at = now()
  where booking_id = p_booking_id
    and lifecycle_status = p_lifecycle_status;

  if p_lifecycle_status = 'confirmed' then
    update public.flight_bookings
    set confirmed_email_claimed_at = null,
        confirmed_email_attempt_count = confirmed_email_attempt_count + 1,
        confirmed_email_last_error = left(coalesce(p_error, 'Booking status email failed.'), 500)
    where id = p_booking_id;
  end if;
end;
$$;

create or replace function public.pending_booking_status_email_jobs(
  p_limit integer default 100,
  p_booking_id uuid default null
)
returns table (booking_id uuid, lifecycle_status text)
language sql
security definer
set search_path = public
as $$
  with observed as (
    select e.booking_id, e.to_lifecycle_status as lifecycle_status,
      min(e.created_at) as observed_at
    from public.booking_status_events e
    where e.to_lifecycle_status in (
      'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
      'unconfirmed', 'cancelled'
    )
      and (p_booking_id is null or e.booking_id = p_booking_id)
    group by e.booking_id, e.to_lifecycle_status
    union all
    select v.id, v.lifecycle_status, v.created_at
    from public.booking_lifecycle_v v
    where (p_booking_id is null or v.id = p_booking_id)
      and not exists (
        select 1 from public.booking_status_events e
        where e.booking_id = v.id
          and e.to_lifecycle_status = v.lifecycle_status
      )
  )
  select o.booking_id, o.lifecycle_status
  from observed o
  left join public.booking_status_email_deliveries d
    on d.booking_id = o.booking_id
   and d.lifecycle_status = o.lifecycle_status
  where d.completed_at is null
    and (d.claimed_at is null or d.claimed_at <= now() - interval '15 minutes')
  order by o.observed_at, o.booking_id, o.lifecycle_status
  limit greatest(1, least(coalesce(p_limit, 100), 500));
$$;

revoke all on public.booking_status_email_deliveries from public, anon, authenticated;
revoke all on function public.claim_booking_status_email(uuid,text),
  public.mark_booking_status_email_sent(uuid,text),
  public.fail_booking_status_email(uuid,text,text),
  public.pending_booking_status_email_jobs(integer,uuid)
from public, anon, authenticated;

grant select, insert, update on public.booking_status_email_deliveries to service_role;
grant execute on function public.claim_booking_status_email(uuid,text),
  public.mark_booking_status_email_sent(uuid,text),
  public.fail_booking_status_email(uuid,text,text),
  public.pending_booking_status_email_jobs(integer,uuid)
to service_role;

comment on table public.booking_status_email_deliveries is
  'Retry-safe, once-per-booking lifecycle email delivery ledger.';


-- SOURCE: 0042_supabase_booking_status_email_cron.sql
-- Platform cron/Vault setup deferred; see fresh-install README.


-- SOURCE: 0043_booking_lifecycle_internal_model.sql
-- Additive internal lifecycle model.
--
-- This migration deliberately does not change the seven public booking
-- statuses, existing lifecycle projection, current writers, wallet behavior,
-- or email worker. Later migrations will backfill and activate each path behind
-- independently reversible application gates.

-- 1. Durable booking operations --------------------------------------------

create table if not exists public.booking_operations (
  id                            uuid primary key default gen_random_uuid(),
  booking_id                    uuid not null
                                references public.flight_bookings (id)
                                on delete restrict,
  kind                          text not null,
  state                         text not null,
  reason_code                   text not null,
  reason_detail                 text,
  request_key                   text not null,
  request_payload_hash          text not null,
  actor_user_id                 text not null,
  actor_role                    text not null,
  source                        text not null,
  prior_stored_status           text,
  prior_lifecycle_status        text,
  supplier                     text,
  supplier_operation            text,
  supplier_unique_trans_id      text,
  supplier_booking_code_ref     text,
  supplier_pnr                  text,
  supplier_evidence             jsonb not null default '{}'::jsonb,
  error_code                    text,
  error_message                 text,
  policy_version                integer not null default 1,
  claimed_at                    timestamptz not null default now(),
  supplier_call_started_at      timestamptz,
  supplier_response_received_at timestamptz,
  external_action_due_at        timestamptz,
  reconciliation_required_at    timestamptz,
  completed_at                  timestamptz,
  created_at                    timestamptz not null default now(),
  updated_at                    timestamptz not null default now()
);

drop trigger if exists booking_operations_touch_updated_at
  on public.booking_operations;
create trigger booking_operations_touch_updated_at
  before update on public.booking_operations
  for each row execute function public.touch_updated_at();

alter table public.booking_operations
  add constraint booking_operations_kind_check
  check (kind in (
    'ticketing',
    'cancellation',
    'imported_manual_ticketing'
  ));

alter table public.booking_operations
  add constraint booking_operations_state_check
  check (state in (
    'claimed',
    'supplier_call_started',
    'awaiting_external_action',
    'needs_reconciliation',
    'succeeded',
    'failed'
  ));

create unique index if not exists booking_operations_one_active_per_booking_idx
  on public.booking_operations (booking_id)
  where state in (
    'claimed',
    'supplier_call_started',
    'awaiting_external_action',
    'needs_reconciliation'
  );

alter table public.flight_bookings
  add column if not exists active_operation_id uuid;

alter table public.flight_bookings
  add constraint flight_bookings_active_operation_fk
  foreign key (active_operation_id)
  references public.booking_operations (id)
  on delete set null
  not valid;

-- 2. Owned reconciliation cases --------------------------------------------

create table if not exists public.booking_reconciliation_cases (
  id                         uuid primary key default gen_random_uuid(),
  subject_booking_id         uuid
                             references public.flight_bookings (id)
                             on delete restrict,
  subject_booking_attempt_id uuid
                             references public.booking_attempts (id)
                             on delete restrict,
  operation_id               uuid
                             references public.booking_operations (id)
                             on delete restrict,
  case_type                  text not null,
  state                      text not null default 'open',
  reason_code                text not null,
  reason_detail              text,
  opened_source              text not null,
  opened_by_user_id          text not null,
  opened_by_role             text not null,
  opened_at                  timestamptz not null default now(),
  policy_version             integer not null default 1,
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  constraint booking_reconciliation_cases_one_subject_check
    check (num_nonnulls(subject_booking_id, subject_booking_attempt_id) = 1)
);

drop trigger if exists booking_reconciliation_cases_touch_updated_at
  on public.booking_reconciliation_cases;
create trigger booking_reconciliation_cases_touch_updated_at
  before update on public.booking_reconciliation_cases
  for each row execute function public.touch_updated_at();

alter table public.booking_reconciliation_cases
  add constraint booking_reconciliation_cases_type_check
  check (case_type in (
    'ticketing_uncertainty',
    'cancellation_uncertainty',
    'legacy_review',
    'terminal_conflict',
    'direct_ticket_payment_failure',
    'imported_manual_ticketing',
    'imported_payment_conflict',
    'attempt_uncertainty',
    'historical_inconsistency'
  ));

alter table public.booking_reconciliation_cases
  add constraint booking_reconciliation_cases_state_check
  check (state in (
    'open',
    'assigned',
    'awaiting_supplier',
    'awaiting_finance',
    'awaiting_approval',
    'resolved',
    'closed_no_change'
  ));

alter table public.booking_reconciliation_cases
  add column assigned_team text,
  add column assignee_user_id text,
  add column assigned_at timestamptz,
  add column severity text not null default 'medium',
  add column priority smallint not null default 50,
  add column due_at timestamptz,
  add column escalated_at timestamptz,
  add column escalation_level smallint not null default 0,
  add column escalation_reason text,
  add column evidence jsonb not null default '[]'::jsonb,
  add column evidence_latest_at timestamptz,
  add column evidence_normalizer_version integer,
  add column proposed_outcome text,
  add column proposal jsonb not null default '{}'::jsonb,
  add column proposal_hash text,
  add column proposed_by_user_id text,
  add column proposed_at timestamptz,
  add column approved_by_user_id text,
  add column approved_at timestamptz,
  add column rejected_by_user_id text,
  add column rejected_at timestamptz,
  add column rejection_reason text,
  add column resolution_outcome text,
  add column resolution jsonb not null default '{}'::jsonb,
  add column resolution_reason text,
  add column resolved_by_user_id text,
  add column resolved_at timestamptz,
  add column closed_at timestamptz,
  add column version integer not null default 1;

alter table public.booking_reconciliation_cases
  add column financial_disposition text not null default 'none',
  add column financial_amount bigint,
  add column financial_currency text,
  add column external_settlement_reference text,
  add constraint booking_reconciliation_cases_financial_disposition_check
    check (financial_disposition in (
      'none',
      'capture_existing_hold',
      'release_existing_hold',
      'full_refund',
      'partial_refund',
      'no_refund_due',
      'externally_settled',
      'manual_adjustment_required'
    ));

create unique index if not exists
  booking_reconciliation_cases_one_open_booking_type_idx
  on public.booking_reconciliation_cases (subject_booking_id, case_type)
  where subject_booking_id is not null
    and state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    );

create unique index if not exists
  booking_reconciliation_cases_one_open_attempt_type_idx
  on public.booking_reconciliation_cases (subject_booking_attempt_id, case_type)
  where subject_booking_attempt_id is not null
    and state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    );

-- 3. Occurrence-aware lifecycle history ------------------------------------

alter table public.booking_status_events
  add column if not exists operation_id uuid,
  add column if not exists reconciliation_case_id uuid,
  add column if not exists occurrence_id uuid not null default gen_random_uuid(),
  add column if not exists occurrence_number integer,
  add column if not exists effective_at timestamptz,
  add column if not exists observed_at timestamptz,
  add column if not exists event_snapshot jsonb not null default '{}'::jsonb,
  add column if not exists event_version integer not null default 1;

alter table public.booking_status_events
  add constraint booking_status_events_operation_fk
  foreign key (operation_id)
  references public.booking_operations (id)
  on delete restrict
  not valid;

alter table public.booking_status_events
  add constraint booking_status_events_reconciliation_case_fk
  foreign key (reconciliation_case_id)
  references public.booking_reconciliation_cases (id)
  on delete restrict
  not valid;

create unique index if not exists booking_status_events_occurrence_id_idx
  on public.booking_status_events (occurrence_id);

-- 4. Transactional notification outbox -------------------------------------

create table if not exists public.booking_notification_outbox (
  id                       uuid primary key default gen_random_uuid(),
  lifecycle_event_id       bigint not null
                           references public.booking_status_events (id)
                           on delete restrict,
  booking_id               uuid not null
                           references public.flight_bookings (id)
                           on delete restrict,
  notification_kind        text not null default 'booking_status',
  lifecycle_status         text not null,
  event_snapshot           jsonb not null,
  delivery_policy          text not null default 'send',
  state                    text not null default 'pending',
  policy_version           integer not null default 1,
  available_at             timestamptz not null default now(),
  grace_expires_at         timestamptz,
  claimed_at               timestamptz,
  claim_token              uuid,
  attempt_count            integer not null default 0,
  max_attempts             integer not null default 8,
  last_error               text,
  suppression_reason       text,
  superseded_by_outbox_id  uuid
                           references public.booking_notification_outbox (id)
                           on delete restrict,
  completed_at             timestamptz,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  constraint booking_notification_outbox_event_kind_key
    unique (lifecycle_event_id, notification_kind),
  constraint booking_notification_outbox_kind_check
    check (notification_kind = 'booking_status'),
  constraint booking_notification_outbox_status_check
    check (lifecycle_status in (
      'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
      'unconfirmed', 'cancelled'
    )),
  constraint booking_notification_outbox_delivery_policy_check
    check (delivery_policy in ('send', 'grace', 'suppress')),
  constraint booking_notification_outbox_state_check
    check (state in (
      'pending', 'processing', 'sent', 'suppressed', 'superseded',
      'dead_letter'
    ))
);

drop trigger if exists booking_notification_outbox_touch_updated_at
  on public.booking_notification_outbox;
create trigger booking_notification_outbox_touch_updated_at
  before update on public.booking_notification_outbox
  for each row execute function public.touch_updated_at();

create table if not exists public.booking_notification_deliveries (
  id                     uuid primary key default gen_random_uuid(),
  outbox_id              uuid not null
                          references public.booking_notification_outbox (id)
                          on delete restrict,
  recipient_kind         text not null,
  recipient_address      text not null,
  recipient_address_hash text not null,
  is_hidden_copy         boolean not null default false,
  channel                text not null default 'email',
  state                  text not null default 'pending',
  rendered_content       jsonb,
  attempt_count          integer not null default 0,
  max_attempts           integer not null default 8,
  next_attempt_at        timestamptz not null default now(),
  claimed_at             timestamptz,
  claim_token            uuid,
  last_attempt_at        timestamptz,
  sent_at                timestamptz,
  completed_at           timestamptz,
  provider_message_id    text,
  last_error             text,
  suppression_reason     text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint booking_notification_deliveries_recipient_key
    unique (outbox_id, channel, recipient_address_hash),
  constraint booking_notification_deliveries_recipient_kind_check
    check (recipient_kind in (
      'customer_contact', 'booking_user', 'agency_user', 'system_copy'
    )),
  constraint booking_notification_deliveries_channel_check
    check (channel = 'email'),
  constraint booking_notification_deliveries_state_check
    check (state in (
      'pending', 'processing', 'retry', 'sent', 'failed', 'suppressed',
      'superseded', 'dead_letter'
    ))
);

drop trigger if exists booking_notification_deliveries_touch_updated_at
  on public.booking_notification_deliveries;
create trigger booking_notification_deliveries_touch_updated_at
  before update on public.booking_notification_deliveries
  for each row execute function public.touch_updated_at();

-- 5. Additive safety constraints -------------------------------------------

alter table public.booking_operations
  add constraint booking_operations_reason_code_check
    check (reason_code ~ '^[a-z][a-z0-9_]{0,99}$'),
  add constraint booking_operations_request_key_check
    check (char_length(request_key) between 1 and 255),
  add constraint booking_operations_payload_hash_check
    check (request_payload_hash ~ '^[a-f0-9]{64}$'),
  add constraint booking_operations_source_check
    check (source in (
      'customer', 'staff', 'system', 'import', 'backfill', 'reconciliation'
    )),
  add constraint booking_operations_prior_stored_status_check
    check (prior_stored_status is null or prior_stored_status in (
      'on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled'
    )),
  add constraint booking_operations_prior_lifecycle_status_check
    check (prior_lifecycle_status is null or prior_lifecycle_status in (
      'on-hold', 'pending', 'in-progress', 'confirmed', 'expired',
      'unconfirmed', 'cancelled'
    )),
  add constraint booking_operations_supplier_evidence_check
    check (jsonb_typeof(supplier_evidence) = 'object'),
  add constraint booking_operations_policy_version_check
    check (policy_version > 0),
  add constraint booking_operations_timestamp_order_check
    check (
      (supplier_call_started_at is null
        or supplier_call_started_at >= claimed_at)
      and (supplier_response_received_at is null
        or (supplier_call_started_at is not null
          and supplier_response_received_at >= supplier_call_started_at))
      and (reconciliation_required_at is null
        or reconciliation_required_at >= claimed_at)
      and (completed_at is null or completed_at >= claimed_at)
    ),
  add constraint booking_operations_completion_state_check
    check (
      (state in ('succeeded', 'failed') and completed_at is not null)
      or (state not in ('succeeded', 'failed') and completed_at is null)
    );

alter table public.booking_reconciliation_cases
  add constraint booking_reconciliation_cases_reason_code_check
    check (reason_code ~ '^[a-z][a-z0-9_]{0,99}$'),
  add constraint booking_reconciliation_cases_opened_source_check
    check (opened_source in (
      'system', 'staff', 'backfill', 'supplier_sync', 'operation',
      'historical_remediation'
    )),
  add constraint booking_reconciliation_cases_opened_actor_check
    check (
      nullif(btrim(opened_by_user_id), '') is not null
      and nullif(btrim(opened_by_role), '') is not null
    ),
  add constraint booking_reconciliation_cases_assigned_team_check
    check (assigned_team is null or assigned_team in (
      'support', 'accounts', 'admin'
    )),
  add constraint booking_reconciliation_cases_severity_check
    check (severity in ('low', 'medium', 'high', 'critical')),
  add constraint booking_reconciliation_cases_priority_check
    check (priority between 0 and 100),
  add constraint booking_reconciliation_cases_escalation_level_check
    check (escalation_level between 0 and 2),
  add constraint booking_reconciliation_cases_evidence_check
    check (jsonb_typeof(evidence) = 'array'),
  add constraint booking_reconciliation_cases_proposal_check
    check (jsonb_typeof(proposal) = 'object'),
  add constraint booking_reconciliation_cases_resolution_check
    check (jsonb_typeof(resolution) = 'object'),
  add constraint booking_reconciliation_cases_proposal_hash_check
    check (proposal_hash is null or proposal_hash ~ '^[a-f0-9]{64}$'),
  add constraint booking_reconciliation_cases_version_check
    check (version > 0 and policy_version > 0),
  add constraint booking_reconciliation_cases_financial_amount_check
    check (financial_amount is null or financial_amount > 0),
  add constraint booking_reconciliation_cases_financial_currency_check
    check (financial_currency is null or financial_currency ~ '^[A-Z]{3}$'),
  add constraint booking_reconciliation_cases_partial_refund_check
    check (
      financial_disposition <> 'partial_refund'
      or (financial_amount is not null and financial_currency is not null)
    ),
  add constraint booking_reconciliation_cases_external_settlement_check
    check (
      financial_disposition <> 'externally_settled'
      or nullif(btrim(external_settlement_reference), '') is not null
    ),
  add constraint booking_reconciliation_cases_maker_checker_check
    check (
      approved_by_user_id is null
      or (proposed_by_user_id is not null
        and approved_by_user_id <> proposed_by_user_id)
    ),
  add constraint booking_reconciliation_cases_resolution_state_check
    check (
      (state in ('resolved', 'closed_no_change') and resolved_at is not null)
      or (state not in ('resolved', 'closed_no_change') and resolved_at is null)
    );

alter table public.booking_status_events
  add constraint booking_status_events_occurrence_number_check
    check (occurrence_number is null or occurrence_number > 0) not valid,
  add constraint booking_status_events_snapshot_check
    check (jsonb_typeof(event_snapshot) = 'object') not valid,
  add constraint booking_status_events_version_check
    check (event_version > 0) not valid,
  add constraint booking_status_events_effective_observed_check
    check (
      effective_at is null or observed_at is null or observed_at >= effective_at
    ) not valid;

alter table public.booking_notification_outbox
  add constraint booking_notification_outbox_snapshot_check
    check (jsonb_typeof(event_snapshot) = 'object'),
  add constraint booking_notification_outbox_attempts_check
    check (
      attempt_count >= 0 and max_attempts > 0
      and attempt_count <= max_attempts
    ),
  add constraint booking_notification_outbox_policy_version_check
    check (policy_version > 0),
  add constraint booking_notification_outbox_grace_check
    check (
      delivery_policy <> 'grace' or grace_expires_at is not null
    ),
  add constraint booking_notification_outbox_completion_check
    check (
      (state in ('sent', 'suppressed', 'superseded', 'dead_letter')
        and completed_at is not null)
      or (state in ('pending', 'processing') and completed_at is null)
    ),
  add constraint booking_notification_outbox_superseded_check
    check (
      state <> 'superseded' or superseded_by_outbox_id is not null
    );

alter table public.booking_notification_deliveries
  add constraint booking_notification_deliveries_address_check
    check (nullif(btrim(recipient_address), '') is not null),
  add constraint booking_notification_deliveries_address_hash_check
    check (recipient_address_hash ~ '^[a-f0-9]{64}$'),
  add constraint booking_notification_deliveries_hidden_copy_check
    check (is_hidden_copy = (recipient_kind = 'system_copy')),
  add constraint booking_notification_deliveries_rendered_content_check
    check (
      rendered_content is null or jsonb_typeof(rendered_content) = 'object'
    ),
  add constraint booking_notification_deliveries_attempts_check
    check (
      attempt_count >= 0 and max_attempts > 0
      and attempt_count <= max_attempts
    ),
  add constraint booking_notification_deliveries_completion_check
    check (
      (state in (
        'sent', 'failed', 'suppressed', 'superseded', 'dead_letter'
      ) and completed_at is not null)
      or (state in ('pending', 'processing', 'retry')
        and completed_at is null)
    );

-- 6. Operational indexes ----------------------------------------------------

create unique index if not exists booking_operations_request_key_idx
  on public.booking_operations (request_key);

create index if not exists booking_operations_booking_created_idx
  on public.booking_operations (booking_id, created_at desc, id);

create index if not exists booking_operations_watchdog_idx
  on public.booking_operations (supplier_call_started_at, id)
  where state = 'supplier_call_started';

create index if not exists booking_operations_external_due_idx
  on public.booking_operations (external_action_due_at, id)
  where state = 'awaiting_external_action';

create index if not exists flight_bookings_active_operation_id_idx
  on public.flight_bookings (active_operation_id)
  where active_operation_id is not null;

create index if not exists booking_reconciliation_cases_open_queue_idx
  on public.booking_reconciliation_cases (
    assigned_team, severity, priority, due_at, created_at, id
  )
  where state in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  );

create index if not exists booking_reconciliation_cases_due_idx
  on public.booking_reconciliation_cases (due_at, id)
  where state in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  ) and due_at is not null;

create index if not exists booking_reconciliation_cases_operation_idx
  on public.booking_reconciliation_cases (operation_id)
  where operation_id is not null;

create unique index if not exists
  booking_status_events_occurrence_number_idx
  on public.booking_status_events (
    booking_id, to_lifecycle_status, occurrence_number
  )
  where occurrence_number is not null;

create index if not exists booking_status_events_operation_created_idx
  on public.booking_status_events (operation_id, created_at, id)
  where operation_id is not null;

create index if not exists booking_status_events_case_created_idx
  on public.booking_status_events (reconciliation_case_id, created_at, id)
  where reconciliation_case_id is not null;

create index if not exists booking_notification_outbox_claim_idx
  on public.booking_notification_outbox (available_at, created_at, id)
  where state = 'pending';

create index if not exists booking_notification_outbox_booking_created_idx
  on public.booking_notification_outbox (booking_id, created_at desc, id);

create index if not exists booking_notification_deliveries_claim_idx
  on public.booking_notification_deliveries (next_attempt_at, created_at, id)
  where state in ('pending', 'retry');

create index if not exists booking_notification_deliveries_outbox_state_idx
  on public.booking_notification_deliveries (outbox_id, state, created_at, id);

-- 7. Least privilege and schema documentation ------------------------------

alter table public.booking_operations enable row level security;
alter table public.booking_reconciliation_cases enable row level security;
alter table public.booking_notification_outbox enable row level security;
alter table public.booking_notification_deliveries enable row level security;

revoke all on table public.booking_operations
  from public, anon, authenticated, service_role;
revoke all on table public.booking_reconciliation_cases
  from public, anon, authenticated, service_role;
revoke all on table public.booking_notification_outbox
  from public, anon, authenticated, service_role;
revoke all on table public.booking_notification_deliveries
  from public, anon, authenticated, service_role;

grant select, insert, update on table public.booking_operations
  to service_role;
grant select, insert, update on table public.booking_reconciliation_cases
  to service_role;
grant select, insert, update on table public.booking_notification_outbox
  to service_role;
grant select, insert, update on table public.booking_notification_deliveries
  to service_role;

comment on table public.booking_operations is
  'Durable internal supplier/manual operation identity and timing. Separate from the seven public booking statuses.';
comment on column public.booking_operations.request_key is
  'Server-generated idempotency identity. Reuse is valid only with the same payload hash and operation subject.';
comment on column public.booking_operations.reason_code is
  'Stable internal subtype explaining the operation without expanding the seven public status values.';
comment on column public.booking_operations.supplier_call_started_at is
  'Authoritative instant immediately before the irreversible supplier HTTP call; never derived from booking creation time.';
comment on column public.booking_operations.supplier_evidence is
  'Protected normalized supplier evidence/identifiers. Passenger-safe rendering uses lifecycle event snapshots instead.';

comment on column public.flight_bookings.active_operation_id is
  'Nullable rolling-deployment pointer to the current internal operation. Existing operation_* columns remain compatibility fields until Phase 10.';

comment on table public.booking_reconciliation_cases is
  'Owned, SLA-bound, evidence-backed workflow for booking or attempt uncertainty and financial/terminal conflicts.';
comment on column public.booking_reconciliation_cases.reason_code is
  'Stable reason the case was opened; reason_detail may add bounded human context but never replaces this code.';
comment on column public.booking_reconciliation_cases.opened_source is
  'Immutable origin of the case: system, staff, backfill, supplier sync, operation, or historical remediation.';
comment on column public.booking_reconciliation_cases.financial_disposition is
  'Explicit case outcome for wallet/settlement handling; never authorizes money movement without an approved case-bound RPC.';
comment on column public.booking_reconciliation_cases.version is
  'Optimistic concurrency version checked by every proposal, approval, assignment, and resolution mutation.';

comment on column public.booking_status_events.occurrence_id is
  'Stable identity for this lifecycle occurrence, including status re-entry.';
comment on column public.booking_status_events.effective_at is
  'Business-effective status instant when authoritatively known.';
comment on column public.booking_status_events.observed_at is
  'Instant this system observed and persisted the authoritative status fact.';
comment on column public.booking_status_events.event_snapshot is
  'Versioned render-safe snapshot used by notifications so later booking edits cannot alter historical email meaning.';

comment on table public.booking_notification_outbox is
  'Transactional lifecycle-event notification intent with grace, suppression, supersession, retry, and dead-letter state.';
comment on table public.booking_notification_deliveries is
  'Independent recipient delivery outcomes, including the hidden system-copy recipient, keyed by normalized address hash.';
comment on column public.booking_notification_deliveries.recipient_address is
  'Protected delivery address. Never expose system_copy rows or addresses through customer DTOs.';

comment on table public.booking_status_email_deliveries is
  'Legacy once-per-booking/status delivery evidence retained during occurrence-outbox migration. Do not reset or resend baseline rows.';


-- SOURCE: 0044_booking_lifecycle_observability.sql
-- Idempotent internal observability backfill and staff-only read model.
--
-- This migration creates no customer notification, performs no supplier call,
-- and changes no existing booking, lifecycle, payment, wallet, reservation, or
-- ledger row. Ambiguous history becomes a case in later statements instead of
-- being invented as an operation.

-- 1. Backfill only operations whose compatibility metadata identifies the
-- action unambiguously.
with candidates as (
  select
    fb.id as booking_id,
    case
      when fb.operation_reason = 'imported_manual_ticketing'
        then 'imported_manual_ticketing'
      when fb.operation_kind = 'cancellation'
        or fb.operation_reason = 'cancellation_reconciliation'
        then 'cancellation'
      else 'ticketing'
    end as kind,
    case
      when fb.operation_reason = 'imported_manual_ticketing'
        then 'awaiting_external_action'
      when fb.operation_kind = 'reconciliation'
        or coalesce(fb.operation_started_at, fb.updated_at, fb.created_at)
          <= now() - interval '3 minutes'
        then 'needs_reconciliation'
      else 'claimed'
    end as state,
    fb.operation_reason as reason_code,
    'Backfilled from authoritative compatibility operation metadata.'::text
      as reason_detail,
    'backfill:0044:operation:' || fb.id::text as request_key,
    fb.id::text || ':' || fb.operation_kind || ':' ||
      fb.operation_reason || ':v1' as payload_seed,
    coalesce(
      nullif(btrim(fb.operation_actor_user_id), ''),
      'system:backfill-0044'
    ) as actor_user_id,
    fb.operation_prior_status,
    case
      when fb.operation_prior_status is null then null
      else public.resolve_booking_lifecycle(
        fb.operation_prior_status,
        fb.airlines_pnr,
        fb.ticketing_deadline_at,
        null
      )
    end as prior_lifecycle_status,
    fb.supplier,
    case
      when fb.operation_reason = 'imported_manual_ticketing'
        then 'ManualTicketing'
      when fb.operation_kind = 'cancellation'
        or fb.operation_reason = 'cancellation_reconciliation'
        then 'Cancel'
      when fb.direct_ticketing then 'Book'
      else 'NewTicket'
    end as supplier_operation,
    nullif(btrim(fb.supplier_refs->>'uniqueTransId'), '')
      as supplier_unique_trans_id,
    fb.booking_code_ref as supplier_booking_code_ref,
    fb.pnr as supplier_pnr,
    jsonb_build_object(
      'backfillVersion', 1,
      'source', 'flight_bookings.operation_*',
      'legacyOperationKind', fb.operation_kind,
      'legacyOperationReason', fb.operation_reason,
      'supplierCallStartedAtKnown', false
    ) as supplier_evidence,
    coalesce(fb.operation_started_at, fb.updated_at, fb.created_at)
      as claimed_at,
    case
      when fb.operation_reason = 'imported_manual_ticketing' then least(
        coalesce(fb.operation_started_at, fb.updated_at, fb.created_at)
          + interval '2 hours',
        fb.ticketing_deadline_at - interval '1 hour'
      )
      else null
    end as external_action_due_at,
    case
      when fb.operation_kind = 'reconciliation'
        or coalesce(fb.operation_started_at, fb.updated_at, fb.created_at)
          <= now() - interval '3 minutes'
        then coalesce(fb.operation_started_at, fb.updated_at, fb.created_at)
      else null
    end as reconciliation_required_at
  from public.booking_lifecycle_v fb
  where fb.operation_reason is not null
    and (
      fb.operation_kind in ('ticketing', 'cancellation')
      or (
        fb.operation_kind = 'reconciliation'
        and fb.operation_reason in (
          'ticketing_reconciliation',
          'cancellation_reconciliation'
        )
      )
    )
)
insert into public.booking_operations (
  booking_id,
  kind,
  state,
  reason_code,
  reason_detail,
  request_key,
  request_payload_hash,
  actor_user_id,
  actor_role,
  source,
  prior_stored_status,
  prior_lifecycle_status,
  supplier,
  supplier_operation,
  supplier_unique_trans_id,
  supplier_booking_code_ref,
  supplier_pnr,
  supplier_evidence,
  policy_version,
  claimed_at,
  supplier_call_started_at,
  external_action_due_at,
  reconciliation_required_at
)
select
  booking_id,
  kind,
  state,
  reason_code,
  reason_detail,
  request_key,
  md5(payload_seed) || md5('second:' || payload_seed),
  actor_user_id,
  'backfill',
  'backfill',
  operation_prior_status,
  prior_lifecycle_status,
  supplier,
  supplier_operation,
  supplier_unique_trans_id,
  supplier_booking_code_ref,
  supplier_pnr,
  supplier_evidence,
  1,
  claimed_at,
  null,
  external_action_due_at,
  reconciliation_required_at
from candidates
on conflict (request_key) do nothing;

-- 2. Give every backfilled unresolved operation an owned case. No evidence is
-- fabricated: the evidence entry records only the source link and classifier.
insert into public.booking_reconciliation_cases (
  subject_booking_id,
  operation_id,
  case_type,
  state,
  reason_code,
  reason_detail,
  opened_source,
  opened_by_user_id,
  opened_by_role,
  opened_at,
  assigned_team,
  severity,
  priority,
  due_at,
  evidence,
  policy_version
)
select
  operation.booking_id,
  operation.id,
  case
    when operation.kind = 'cancellation' then 'cancellation_uncertainty'
    when operation.kind = 'imported_manual_ticketing'
      then 'imported_manual_ticketing'
    else 'ticketing_uncertainty'
  end,
  'open',
  operation.reason_code,
  'Backfilled unresolved operation requires controlled staff resolution.',
  'backfill',
  'system:backfill-0044',
  'backfill',
  now(),
  'support',
  'high',
  case when operation.kind = 'imported_manual_ticketing' then 30 else 20 end,
  case
    when operation.kind = 'imported_manual_ticketing'
      then coalesce(operation.external_action_due_at, now() + interval '2 hours')
    else now() + interval '30 minutes'
  end,
  jsonb_build_array(jsonb_build_object(
    'type', 'backfill_operation_link',
    'operationId', operation.id,
    'operationState', operation.state,
    'supplierEvidenceInvented', false
  )),
  1
from public.booking_operations operation
where operation.state in (
  'needs_reconciliation', 'awaiting_external_action'
)
on conflict do nothing;

-- 3. Compatibility reconciliation metadata whose original action is not
-- certain becomes a case without an invented operation row.
insert into public.booking_reconciliation_cases (
  subject_booking_id,
  case_type,
  state,
  reason_code,
  reason_detail,
  opened_source,
  opened_by_user_id,
  opened_by_role,
  opened_at,
  assigned_team,
  severity,
  priority,
  due_at,
  evidence,
  policy_version
)
select
  booking.id,
  case booking.operation_reason
    when 'legacy_reconciliation' then 'legacy_review'
    when 'terminal_state_conflict' then 'terminal_conflict'
    when 'direct_ticket_payment_reconciliation'
      then 'direct_ticket_payment_failure'
    when 'cancellation_reconciliation' then 'cancellation_uncertainty'
    else 'ticketing_uncertainty'
  end,
  'open',
  booking.operation_reason,
  'Compatibility metadata is insufficient to reconstruct a trustworthy operation.',
  'backfill',
  'system:backfill-0044',
  'backfill',
  now(),
  case
    when booking.operation_reason in (
      'legacy_reconciliation',
      'terminal_state_conflict',
      'direct_ticket_payment_reconciliation'
    ) then 'admin'
    else 'support'
  end,
  case
    when booking.operation_reason in (
      'terminal_state_conflict',
      'direct_ticket_payment_reconciliation'
    ) then 'critical'
    else 'high'
  end,
  case
    when booking.operation_reason in (
      'terminal_state_conflict',
      'direct_ticket_payment_reconciliation'
    ) then 0
    when booking.operation_reason = 'legacy_reconciliation' then 40
    else 20
  end,
  case
    when booking.operation_reason in (
      'terminal_state_conflict',
      'direct_ticket_payment_reconciliation'
    ) then now() + interval '1 hour'
    when booking.operation_reason = 'legacy_reconciliation'
      then now() + interval '1 day'
    else now() + interval '30 minutes'
  end,
  jsonb_build_array(jsonb_build_object(
    'type', 'compatibility_metadata',
    'legacyOperationKind', booking.operation_kind,
    'legacyOperationReason', booking.operation_reason,
    'operationReconstructed', false,
    'supplierEvidenceInvented', false
  )),
  1
from public.booking_lifecycle_v booking
where booking.operation_kind = 'reconciliation'
  and booking.operation_reason is not null
  and not exists (
    select 1
    from public.booking_operations operation
    where operation.booking_id = booking.id
      and operation.state in (
        'claimed', 'supplier_call_started', 'awaiting_external_action',
        'needs_reconciliation'
      )
  )
on conflict do nothing;

-- 4. Attempts are operational subjects, not public bookings. Aged uncertainty
-- is visible to Support without creating a business booking or public status.
insert into public.booking_reconciliation_cases (
  subject_booking_attempt_id,
  case_type,
  state,
  reason_code,
  reason_detail,
  opened_source,
  opened_by_user_id,
  opened_by_role,
  opened_at,
  assigned_team,
  severity,
  priority,
  due_at,
  evidence,
  policy_version
)
select
  attempt.id,
  'attempt_uncertainty',
  'open',
  case
    when attempt.state = 'unknown' then 'unknown_supplier_outcome'
    else 'aged_submitting_attempt'
  end,
  'Supplier-submitted attempt has no controlled local resolution.',
  'backfill',
  'system:backfill-0044',
  'backfill',
  now(),
  'support',
  'high',
  10,
  now() + interval '15 minutes',
  jsonb_build_array(jsonb_build_object(
    'type', 'attempt_state',
    'state', attempt.state,
    'submittedAt', attempt.submitted_at,
    'resolvedAt', attempt.resolved_at,
    'supplierEvidenceInvented', false
  )),
  1
from public.booking_attempts attempt
where attempt.state in ('submitting', 'unknown')
  and coalesce(attempt.submitted_at, attempt.updated_at)
    <= now() - interval '15 minutes'
on conflict do nothing;

-- 5. Objective lifecycle/financial contradictions become owned cases only;
-- this backfill never chooses their final status or financial disposition.
insert into public.booking_reconciliation_cases (
  subject_booking_id, case_type, state, reason_code, reason_detail,
  opened_source, opened_by_user_id, opened_by_role, opened_at,
  assigned_team, severity, priority, due_at, evidence, policy_version
)
select
  booking.id,
  'historical_inconsistency',
  'open',
  'cancelled_missing_authoritative_timestamp',
  'Cancelled booking has no authoritative cancellation timestamp.',
  'backfill', 'system:backfill-0044', 'backfill', now(),
  'admin', 'medium', 50, now() + interval '1 day',
  jsonb_build_array(jsonb_build_object(
    'type', 'objective_invariant',
    'storedStatus', booking.status,
    'cancelledAtPresent', false,
    'supplierEvidenceInvented', false
  )),
  1
from public.booking_lifecycle_v booking
where booking.status = 'cancelled'
  and booking.cancelled_at is null
on conflict do nothing;

insert into public.booking_reconciliation_cases (
  subject_booking_id, case_type, state, reason_code, reason_detail,
  opened_source, opened_by_user_id, opened_by_role, opened_at,
  assigned_team, severity, priority, due_at, evidence, policy_version
)
select
  booking.id,
  'terminal_conflict',
  'open',
  'cancelled_with_outstanding_captured_funds',
  'Cancelled booking retains captured funds without a complete refund disposition.',
  'backfill', 'system:backfill-0044', 'backfill', now(),
  'admin', 'critical', 0, now() + interval '1 hour',
  jsonb_build_array(jsonb_build_object(
    'type', 'objective_financial_invariant',
    'paymentState', booking.payment_state,
    'capturedAmount', booking.captured_amount,
    'refundedAmount', booking.refunded_amount,
    'financialDispositionChosen', false,
    'supplierEvidenceInvented', false
  )),
  1
from public.booking_lifecycle_v booking
where booking.status = 'cancelled'
  and booking.captured_amount > booking.refunded_amount
on conflict do nothing;

insert into public.booking_reconciliation_cases (
  subject_booking_id, case_type, state, reason_code, reason_detail,
  opened_source, opened_by_user_id, opened_by_role, opened_at,
  assigned_team, severity, priority, due_at, evidence, policy_version
)
select
  booking.id,
  case
    when booking.import_source = 'IMP_EXP' then 'imported_payment_conflict'
    else 'direct_ticket_payment_failure'
  end,
  'open',
  case
    when booking.import_source = 'IMP_EXP' then 'imported_confirmed_unpaid'
    else 'confirmed_without_captured_payment'
  end,
  'Confirmed ticket truth has no matching captured or externally settled payment.',
  'backfill', 'system:backfill-0044', 'backfill', now(),
  case when booking.import_source = 'IMP_EXP' then 'accounts' else 'admin' end,
  'critical', 0, now() + interval '1 hour',
  jsonb_build_array(jsonb_build_object(
    'type', 'objective_financial_invariant',
    'importSource', booking.import_source,
    'paymentState', booking.payment_state,
    'capturedAmount', booking.captured_amount,
    'financialDispositionChosen', false,
    'supplierEvidenceInvented', false
  )),
  1
from public.booking_lifecycle_v booking
where booking.status = 'confirmed'
  and booking.payment_state = 'unpaid'
on conflict do nothing;

-- 6. Staff-only lifecycle truth. Deliberately excludes passenger/contact data,
-- raw supplier evidence, proposal bodies, and recipient addresses.
create or replace view public.booking_lifecycle_staff_v
with (security_invoker = true)
as
select
  booking.id as booking_id,
  booking.public_ref,
  booking.supplier,
  booking.import_source,
  booking.status as stored_status,
  booking.lifecycle_status,
  booking.created_at as booked_at,
  booking.updated_at as booking_updated_at,
  booking.ticketing_deadline_at,
  booking.issued_at,
  booking.cancelled_at,
  booking.payment_state,
  booking.payment_amount,
  booking.captured_amount,
  booking.refunded_amount,
  booking.currency,
  booking.operation_kind as compatibility_operation_kind,
  booking.operation_reason as compatibility_operation_reason,
  booking.operation_started_at as compatibility_operation_started_at,
  internal_booking.active_operation_id,
  operation.id as operation_id,
  operation.kind as operation_kind,
  operation.state as operation_state,
  operation.reason_code as operation_reason_code,
  operation.reason_detail as operation_reason_detail,
  operation.source as operation_source,
  operation.actor_user_id as operation_actor_user_id,
  operation.actor_role as operation_actor_role,
  operation.claimed_at as operation_claimed_at,
  operation.supplier_call_started_at,
  operation.supplier_response_received_at,
  operation.external_action_due_at,
  operation.reconciliation_required_at,
  operation.completed_at as operation_completed_at,
  case
    when operation.claimed_at is null then null
    else greatest(
      0,
      extract(epoch from (coalesce(operation.completed_at, now())
        - operation.claimed_at))::bigint
    )
  end as operation_elapsed_seconds,
  (
    internal_booking.active_operation_id is not null
    and internal_booking.active_operation_id is distinct from operation.id
  ) as operation_pointer_mismatch,
  reservation.id as reservation_id,
  reservation.state as reservation_state,
  reservation.amount as reservation_amount,
  reservation.currency as reservation_currency,
  reservation.supplier_call_started_at as reservation_supplier_call_started_at,
  reservation.reconciliation_at as reservation_reconciliation_at,
  reservation.reconciliation_reason as reservation_reconciliation_reason,
  primary_case.id as primary_case_id,
  primary_case.case_type as primary_case_type,
  primary_case.state as primary_case_state,
  primary_case.reason_code as primary_case_reason_code,
  primary_case.reason_detail as primary_case_reason_detail,
  primary_case.assigned_team as primary_case_assigned_team,
  primary_case.assignee_user_id as primary_case_assignee_user_id,
  primary_case.severity as primary_case_severity,
  primary_case.priority as primary_case_priority,
  primary_case.due_at as primary_case_due_at,
  primary_case.escalation_level as primary_case_escalation_level,
  primary_case.evidence_latest_at as primary_case_evidence_latest_at,
  case
    when primary_case.evidence_latest_at is null then false
    else primary_case.evidence_latest_at >= now() - interval '5 minutes'
  end as primary_case_evidence_is_fresh,
  primary_case.financial_disposition,
  primary_case.version as primary_case_version,
  coalesce(primary_case.open_case_count, 0)::integer as open_case_count,
  (
    primary_case.due_at is not null
    and primary_case.due_at <= now()
  ) as case_sla_breached,
  case
    when booking.status = 'confirmed' and booking.payment_state = 'unpaid'
      then 'confirmed_unpaid'
    when booking.status = 'cancelled'
      and booking.captured_amount > booking.refunded_amount
      then 'cancelled_outstanding_capture'
    when booking.payment_state = 'held'
      and coalesce(reservation.state, 'missing') <> 'active'
      then 'held_without_active_reservation'
    when reservation.state = 'reconciliation'
      then 'reservation_reconciliation'
    else null
  end as payment_conflict_code,
  (
    primary_case.case_type = 'terminal_conflict'
    or booking.operation_reason = 'terminal_state_conflict'
  ) as terminal_conflict_visible,
  (
    primary_case.id is not null
    or operation.state in (
      'needs_reconciliation', 'awaiting_external_action'
    )
    or (
      booking.status = 'confirmed' and booking.payment_state = 'unpaid'
    )
    or (
      booking.status = 'cancelled'
      and booking.captured_amount > booking.refunded_amount
    )
  ) as staff_attention_required
from public.booking_lifecycle_v booking
join public.flight_bookings internal_booking
  on internal_booking.id = booking.id
left join lateral (
  select candidate.*
  from public.booking_operations candidate
  where candidate.booking_id = booking.id
    and candidate.state in (
      'claimed', 'supplier_call_started', 'awaiting_external_action',
      'needs_reconciliation'
    )
  order by
    (candidate.id = internal_booking.active_operation_id) desc,
    candidate.claimed_at desc,
    candidate.id desc
  limit 1
) operation on true
left join public.wallet_reservations reservation
  on reservation.booking_id = booking.id
left join lateral (
  select candidate.*,
    count(*) over () as open_case_count
  from public.booking_reconciliation_cases candidate
  where candidate.subject_booking_id = booking.id
    and candidate.state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    )
  order by
    candidate.priority,
    candidate.due_at nulls last,
    candidate.created_at,
    candidate.id
  limit 1
) primary_case on true;

revoke all on table public.booking_lifecycle_staff_v
  from public, anon, authenticated;
grant select on table public.booking_lifecycle_staff_v to service_role;

comment on view public.booking_lifecycle_staff_v is
  'Staff-only public lifecycle plus internal operation, primary open case, reservation, evidence freshness, SLA, and payment-conflict metadata. Contains no passenger/contact or raw evidence payload.';

-- 7. Bounded aggregate health signals for staff dashboards and alerts. The
-- thresholds match policy version 1: three minutes for a supplier operation,
-- fifteen minutes for an unresolved submission, and case-specific due_at for
-- all longer-running/manual work.
create or replace view public.booking_lifecycle_metrics_v
with (security_invoker = true)
as
with open_cases as (
  select candidate.*
  from public.booking_reconciliation_cases candidate
  where candidate.state in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  )
),
aged_operations as (
  select operation.*
  from public.booking_operations operation
  where (
    operation.state in ('claimed', 'supplier_call_started')
    and coalesce(
      operation.supplier_call_started_at,
      operation.claimed_at
    ) <= now() - interval '3 minutes'
  ) or (
    operation.state = 'awaiting_external_action'
    and operation.external_action_due_at is not null
    and operation.external_action_due_at <= now()
  ) or (
    operation.state = 'needs_reconciliation'
    and coalesce(
      operation.reconciliation_required_at,
      operation.claimed_at
    ) <= now() - interval '30 minutes'
  )
),
aged_attempts as (
  select attempt.*
  from public.booking_attempts attempt
  where attempt.state in ('submitting', 'unknown')
    and coalesce(attempt.submitted_at, attempt.created_at)
      <= now() - interval '15 minutes'
),
terminal_conflict_bookings as (
  select booking.id
  from public.booking_lifecycle_v booking
  where (
    booking.status = 'confirmed'
    and booking.payment_state = 'unpaid'
  ) or (
    booking.status = 'cancelled'
    and booking.captured_amount > booking.refunded_amount
  ) or exists (
    select 1
    from open_cases candidate
    where candidate.subject_booking_id = booking.id
      and candidate.case_type = 'terminal_conflict'
  )
),
wallet_inconsistent_bookings as (
  select staff.booking_id
  from public.booking_lifecycle_staff_v staff
  where staff.payment_conflict_code is not null
    or staff.reservation_state = 'reconciliation'
)
select
  now() as observed_at,
  (select count(*) from open_cases)::bigint as open_case_count,
  (select min(opened_at) from open_cases) as oldest_open_case_at,
  (select count(*) from aged_operations)::bigint as aged_operation_count,
  (select min(claimed_at) from aged_operations) as oldest_aged_operation_at,
  (select count(*) from aged_attempts)::bigint as aged_attempt_count,
  (
    select min(coalesce(submitted_at, created_at))
    from aged_attempts
  ) as oldest_aged_attempt_at,
  (
    select count(*) from open_cases where due_at <= now()
  )::bigint as sla_breach_count,
  (
    select min(due_at) from open_cases where due_at <= now()
  ) as oldest_sla_breach_at,
  (
    select count(distinct id) from terminal_conflict_bookings
  )::bigint as terminal_conflict_count,
  (
    select count(distinct booking_id) from wallet_inconsistent_bookings
  )::bigint as wallet_inconsistency_count;

revoke all on table public.booking_lifecycle_metrics_v
  from public, anon, authenticated;
grant select on table public.booking_lifecycle_metrics_v to service_role;

comment on view public.booking_lifecycle_metrics_v is
  'Staff-only aggregate lifecycle health metrics. Contains counts and oldest timestamps only; no booking, passenger, supplier-evidence, or financial amount detail.';


-- SOURCE: 0045_booking_operation_claims.sql
-- Payload-bound, replay-safe supplier-operation identity. This migration adds
-- no worker and changes no existing route until the versioned claim wrappers
-- below are adopted by the application.

create or replace function public.claim_booking_operation_identity(
  p_booking_id uuid,
  p_kind text,
  p_reason_code text,
  p_reason_detail text,
  p_request_key text,
  p_request_payload_hash text,
  p_actor_user_id text,
  p_actor_role text,
  p_source text,
  p_supplier_operation text,
  p_external_action_due_at timestamptz default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_existing public.booking_operations;
  v_active public.booking_operations;
  v_created public.booking_operations;
  v_prior_lifecycle text;
begin
  if p_kind not in ('ticketing', 'cancellation', 'imported_manual_ticketing')
     or nullif(btrim(p_reason_code), '') is null
     or nullif(btrim(p_request_key), '') is null
     or p_request_payload_hash !~ '^[a-f0-9]{64}$'
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_actor_role), '') is null
     or p_source not in (
       'customer', 'staff', 'system', 'import', 'backfill', 'reconciliation'
     ) then
    raise exception 'invalid booking operation identity'
      using errcode = '22023';
  end if;

  -- A request key is global. Serialize even when a malicious/buggy replay
  -- changes the booking id so the second transaction cannot race the unique
  -- index and accidentally receive an unclassified constraint error.
  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));

  select * into v_existing
  from public.booking_operations
  where request_key = p_request_key
  for update;
  if found then
    if v_existing.booking_id is distinct from p_booking_id
       or v_existing.kind is distinct from p_kind
       or v_existing.request_payload_hash is distinct from p_request_payload_hash
       or v_existing.actor_user_id is distinct from p_actor_user_id
       or v_existing.actor_role is distinct from p_actor_role then
      raise exception 'operation request key was reused with different intent'
        using errcode = '22023';
    end if;
    return jsonb_build_object(
      'ok', true,
      'replay', true,
      'operationId', v_existing.id,
      'state', v_existing.state,
      'result', v_existing.supplier_evidence,
      'errorCode', v_existing.error_code
    );
  end if;

  select * into v_booking
  from public.flight_bookings
  where id = p_booking_id and not legacy_operational
  for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  select * into v_active
  from public.booking_operations
  where booking_id = p_booking_id
    and state in (
      'claimed', 'supplier_call_started', 'awaiting_external_action',
      'needs_reconciliation'
    )
  order by claimed_at desc, id desc
  limit 1
  for update;
  if found then
    return jsonb_build_object(
      'ok', false,
      'code', 'OPERATION_ALREADY_ACTIVE',
      'operationId', v_active.id,
      'state', v_active.state
    );
  end if;

  v_prior_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status,
    v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at,
    v_booking.operation_kind
  );

  insert into public.booking_operations (
    booking_id, kind, state, reason_code, reason_detail,
    request_key, request_payload_hash,
    actor_user_id, actor_role, source,
    prior_stored_status, prior_lifecycle_status,
    supplier, supplier_operation, supplier_unique_trans_id,
    supplier_booking_code_ref, supplier_pnr,
    external_action_due_at, policy_version, claimed_at
  ) values (
    v_booking.id, p_kind, 'claimed', p_reason_code,
    nullif(btrim(p_reason_detail), ''),
    p_request_key, p_request_payload_hash,
    p_actor_user_id, p_actor_role, p_source,
    v_booking.status, v_prior_lifecycle,
    v_booking.supplier, nullif(btrim(p_supplier_operation), ''),
    v_booking.supplier_refs->>'uniqueTransId',
    v_booking.booking_code_ref,
    coalesce(v_booking.booking_ref_number, v_booking.pnr),
    p_external_action_due_at, 1, now()
  ) returning * into v_created;

  return jsonb_build_object(
    'ok', true,
    'replay', false,
    'operationId', v_created.id,
    'state', v_created.state,
    'result', v_created.supplier_evidence,
    'errorCode', v_created.error_code
  );
end;
$$;

revoke all on function public.claim_booking_operation_identity(
  uuid, text, text, text, text, text, text, text, text, text, timestamptz
) from public, anon, authenticated;
grant execute on function public.claim_booking_operation_identity(
  uuid, text, text, text, text, text, text, text, text, text, timestamptz
) to service_role;

comment on function public.claim_booking_operation_identity(
  uuid, text, text, text, text, text, text, text, text, text, timestamptz
) is
  'Internal replay boundary. An exact request-key replay returns its existing operation/result; any booking/kind/payload/actor mismatch raises 22023. Does not call the supplier.';

create or replace function public.booking_operation_replay_response(
  p_claim jsonb
)
returns jsonb
language sql
immutable
set search_path = public
as $$
  select case
    when coalesce((p_claim->>'replay')::boolean, false) is not true then null
    when p_claim->>'state' = 'succeeded' then
      jsonb_build_object(
        'ok', true, 'replay', true,
        'operationId', p_claim->>'operationId',
        'operationState', p_claim->>'state',
        'operationResult', p_claim->'result'
      )
    when p_claim->>'state' = 'failed' then
      jsonb_build_object(
        'ok', false, 'replay', true,
        'code', coalesce(p_claim->>'errorCode', 'OPERATION_FAILED'),
        'operationId', p_claim->>'operationId',
        'operationState', p_claim->>'state'
      )
    when p_claim->>'state' in (
      'needs_reconciliation', 'awaiting_external_action'
    ) then
      jsonb_build_object(
        'ok', false, 'replay', true,
        'code', 'RECONCILIATION_REQUIRED',
        'operationId', p_claim->>'operationId',
        'operationState', p_claim->>'state'
      )
    else
      jsonb_build_object(
        'ok', false, 'replay', true,
        'code', 'OPERATION_IN_PROGRESS',
        'operationId', p_claim->>'operationId',
        'operationState', p_claim->>'state'
      )
  end
$$;

revoke all on function public.booking_operation_replay_response(jsonb)
  from public, anon, authenticated;
grant execute on function public.booking_operation_replay_response(jsonb)
  to service_role;

-- NewTicket claim: operation identity, wallet hold, compatibility state, event,
-- and active pointer commit or roll back as one transaction.
create or replace function public.wallet_begin_booking_issue_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text,
  p_request_payload_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_claim jsonb;
  v_replay jsonb;
  v_result jsonb;
  v_operation_id uuid;
begin
  v_claim := public.claim_booking_operation_identity(
    p_booking_id, 'ticketing', 'ticketing', null,
    p_request_key, p_request_payload_hash,
    p_actor_user_id, p_actor_role, 'staff', 'NewTicket', null
  );
  if coalesce((v_claim->>'ok')::boolean, false) is not true then
    return v_claim;
  end if;
  v_replay := public.booking_operation_replay_response(v_claim);
  if v_replay is not null then return v_replay; end if;
  v_operation_id := (v_claim->>'operationId')::uuid;

  v_result := public.wallet_begin_booking_issue(
    p_booking_id, p_actor_user_id, p_actor_role, p_request_key
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    update public.booking_operations
       set state = 'failed', completed_at = now(),
           error_code = coalesce(v_result->>'code', 'CLAIM_FAILED'),
           supplier_evidence = jsonb_build_object(
             'phase', 'local_claim',
             'resultCode', v_result->>'code'
           )
     where id = v_operation_id and state = 'claimed';
    return v_result || jsonb_build_object(
      'operationId', v_operation_id,
      'operationState', 'failed'
    );
  end if;

  update public.flight_bookings
     set active_operation_id = v_operation_id
   where id = p_booking_id;
  update public.booking_status_events
     set operation_id = v_operation_id
   where booking_id = p_booking_id
     and idempotency_key = p_request_key || ':ticketing-start';
  return v_result || jsonb_build_object(
    'replay', false,
    'operationId', v_operation_id,
    'operationState', 'claimed'
  );
end;
$$;

-- Compatibility Pending claim. No new workflow may create Pending; this exists
-- only to make a retained legacy retry owned and replay-safe.
create or replace function public.wallet_begin_legacy_manual_issue_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text,
  p_request_payload_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_claim jsonb;
  v_replay jsonb;
  v_result jsonb;
  v_operation_id uuid;
begin
  v_claim := public.claim_booking_operation_identity(
    p_booking_id, 'ticketing', 'legacy_reconciliation',
    'Compatibility Pending manual ticketing claim',
    p_request_key, p_request_payload_hash,
    p_actor_user_id, p_actor_role, 'reconciliation', 'NewTicket', null
  );
  if coalesce((v_claim->>'ok')::boolean, false) is not true then
    return v_claim;
  end if;
  v_replay := public.booking_operation_replay_response(v_claim);
  if v_replay is not null then return v_replay; end if;
  v_operation_id := (v_claim->>'operationId')::uuid;

  v_result := public.wallet_begin_legacy_manual_issue(
    p_booking_id, p_actor_user_id, p_request_key
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    update public.booking_operations
       set state = 'failed', completed_at = now(),
           error_code = coalesce(v_result->>'code', 'CLAIM_FAILED'),
           supplier_evidence = jsonb_build_object(
             'phase', 'local_claim',
             'resultCode', v_result->>'code'
           )
     where id = v_operation_id and state = 'claimed';
    return v_result || jsonb_build_object(
      'operationId', v_operation_id,
      'operationState', 'failed'
    );
  end if;

  update public.flight_bookings
     set active_operation_id = v_operation_id
   where id = p_booking_id;
  update public.booking_status_events
     set operation_id = v_operation_id
   where booking_id = p_booking_id
     and idempotency_key = p_request_key || ':legacy-ticketing-start';
  return v_result || jsonb_build_object(
    'replay', false,
    'operationId', v_operation_id,
    'operationState', 'claimed'
  );
end;
$$;

-- Cancel claim: booking row, compatibility status, immutable event, and durable
-- cancellation operation are protected by the same transaction and row lock.
create or replace function public.begin_booking_cancellation_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text,
  p_request_payload_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_claim jsonb;
  v_replay jsonb;
  v_result jsonb;
  v_operation_id uuid;
begin
  v_claim := public.claim_booking_operation_identity(
    p_booking_id, 'cancellation', 'cancellation', null,
    p_request_key, p_request_payload_hash,
    p_actor_user_id, p_actor_role, 'staff', 'Cancel', null
  );
  if coalesce((v_claim->>'ok')::boolean, false) is not true then
    return v_claim;
  end if;
  v_replay := public.booking_operation_replay_response(v_claim);
  if v_replay is not null then return v_replay; end if;
  v_operation_id := (v_claim->>'operationId')::uuid;

  v_result := public.begin_booking_cancellation(
    p_booking_id, p_actor_user_id, p_request_key
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    update public.booking_operations
       set state = 'failed', completed_at = now(),
           error_code = coalesce(v_result->>'code', 'CLAIM_FAILED'),
           supplier_evidence = jsonb_build_object(
             'phase', 'local_claim',
             'resultCode', v_result->>'code'
           )
     where id = v_operation_id and state = 'claimed';
    return v_result || jsonb_build_object(
      'operationId', v_operation_id,
      'operationState', 'failed'
    );
  end if;

  update public.flight_bookings
     set active_operation_id = v_operation_id
   where id = p_booking_id;
  update public.booking_status_events
     set operation_id = v_operation_id
   where booking_id = p_booking_id
     and idempotency_key = p_request_key || ':cancellation-start';
  return v_result || jsonb_build_object(
    'replay', false,
    'operationId', v_operation_id,
    'operationState', 'claimed'
  );
end;
$$;

