-- A claim can be abandoned before authentication completes, so it also needs
-- an indexed ownerless-work scan even though no supplier call was started.
create index if not exists booking_operations_claim_watchdog_idx
  on public.booking_operations (claimed_at, id)
  where state = 'claimed';

-- Bounded, concurrency-safe watchdog. It never calls a supplier endpoint and
-- never releases/captures funds. Instead it preserves the financial position,
-- moves the operation to reconciliation, and creates one SLA-owned case.
create or replace function public.process_booking_operation_watchdog(
  p_limit integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_operation public.booking_operations;
  v_case_id uuid;
  v_case_type text;
  v_reason_code text;
  v_reason_detail text;
  v_wallet_result jsonb;
  v_processed integer := 0;
  v_cases_created integer := 0;
  v_cutoff timestamptz := now() - interval '3 minutes';
begin
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception 'watchdog limit must be between 1 and 500'
      using errcode = '22023';
  end if;

  for v_operation in
    select operation.*
      from public.booking_operations operation
     where (
       operation.state = 'supplier_call_started'
       and operation.supplier_call_started_at <= v_cutoff
     ) or (
       operation.state = 'claimed'
       and operation.claimed_at <= v_cutoff
     )
     order by coalesce(
       operation.supplier_call_started_at,
       operation.claimed_at
     ), operation.id
     limit p_limit
     for update skip locked
  loop
    v_case_type := case
      when v_operation.reason_code = 'legacy_reconciliation'
        then 'legacy_review'
      when v_operation.kind = 'cancellation'
        then 'cancellation_uncertainty'
      else 'ticketing_uncertainty'
    end;
    v_reason_code := case
      when v_operation.state = 'supplier_call_started'
        then 'supplier_call_watchdog_timeout'
      else 'local_claim_watchdog_timeout'
    end;
    v_reason_detail := case
      when v_operation.state = 'supplier_call_started' then
        'Supplier write exceeded the three-minute operation watchdog; outcome must be read and reconciled without replay.'
      else
        'Operation claim exceeded the three-minute watchdog before the supplier-call boundary was recorded.'
    end;

    v_wallet_result := public.wallet_mark_reconciliation(
      v_operation.booking_id,
      null,
      v_reason_detail
    );

    update public.booking_operations
       set state = 'needs_reconciliation',
           reconciliation_required_at = coalesce(
             reconciliation_required_at, now()
           ),
           error_code = upper(v_reason_code),
           error_message = v_reason_detail,
           supplier_evidence = supplier_evidence || jsonb_build_object(
             'watchdog', jsonb_build_object(
               'policyVersion', 1,
               'thresholdSeconds', 180,
               'detectedAt', now(),
               'supplierCallStarted',
                 v_operation.supplier_call_started_at is not null,
               'supplierResponseRecorded',
                 v_operation.supplier_response_received_at is not null,
               'walletPositionProtected', coalesce(
                 (v_wallet_result->>'ok')::boolean, false
               ),
               'automaticSupplierReplay', false
             )
           )
     where id = v_operation.id;

    update public.flight_bookings
       set active_operation_id = v_operation.id
     where id = v_operation.booking_id;

    v_case_id := null;
    insert into public.booking_reconciliation_cases (
      subject_booking_id, operation_id, case_type, state,
      reason_code, reason_detail, opened_source,
      opened_by_user_id, opened_by_role, opened_at,
      assigned_team, severity, priority, due_at,
      escalated_at, escalation_level, escalation_reason,
      evidence, evidence_latest_at, evidence_normalizer_version,
      policy_version
    ) values (
      v_operation.booking_id, v_operation.id, v_case_type, 'open',
      v_reason_code, v_reason_detail, 'operation',
      'system:lifecycle-watchdog', 'system', now(),
      'support', 'high', 90, now() + interval '30 minutes',
      now(), 1, 'Active supplier operation watchdog threshold exceeded',
      jsonb_build_array(jsonb_build_object(
        'kind', 'operation_watchdog_observation',
        'observedAt', now(),
        'operationStateBefore', v_operation.state,
        'supplierCallStartedAt', v_operation.supplier_call_started_at,
        'supplierResponseRecorded',
          v_operation.supplier_response_received_at is not null,
        'automaticSupplierReplay', false
      )),
      now(), 1, 1
    ) on conflict do nothing
    returning id into v_case_id;

    v_processed := v_processed + 1;
    if v_case_id is not null then
      v_cases_created := v_cases_created + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'processed', v_processed,
    'casesCreated', v_cases_created,
    'thresholdSeconds', 180,
    'limit', p_limit,
    'automaticSupplierReplay', false
  );
end;
$$;

revoke all on function public.process_booking_operation_watchdog(integer)
  from public, anon, authenticated;
grant execute on function public.process_booking_operation_watchdog(integer)
  to service_role;

comment on function public.process_booking_operation_watchdog(integer) is
  'Moves stale claimed/supplier-call-started booking operations to owned reconciliation after three minutes. Uses SKIP LOCKED, preserves funds, and never calls or replays a supplier write.';

create index if not exists booking_attempts_reconciliation_watchdog_idx
  on public.booking_attempts (
    state, supplier_call_started_at, submitted_at, resolved_at, updated_at, id
  )
  where state in ('submitting', 'unknown')
    and operation_request_key is not null;

-- Only operation-identified attempts are eligible. This deliberately leaves
-- pre-0045 historical null-identity attempts unchanged for the separately
-- approved historical-remediation phase.
create or replace function public.process_booking_attempt_watchdog(
  p_limit integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_attempt public.booking_attempts;
  v_state_before text;
  v_reason_code text;
  v_reason_detail text;
  v_wallet_result jsonb;
  v_case_id uuid;
  v_processed integer := 0;
  v_cases_created integer := 0;
  v_cutoff timestamptz := now() - interval '3 minutes';
begin
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception 'attempt watchdog limit must be between 1 and 500'
      using errcode = '22023';
  end if;

  for v_attempt in
    select attempt.*
      from public.booking_attempts attempt
     where attempt.state in ('submitting', 'unknown')
       and attempt.operation_request_key is not null
       and coalesce(
         attempt.supplier_call_started_at,
         attempt.submitted_at,
         attempt.resolved_at,
         attempt.updated_at
       ) <= v_cutoff
       and not exists (
         select 1
           from public.booking_reconciliation_cases open_case
          where open_case.subject_booking_attempt_id = attempt.id
            and open_case.case_type = 'attempt_uncertainty'
            and open_case.state in (
              'open', 'assigned', 'awaiting_supplier',
              'awaiting_finance', 'awaiting_approval'
            )
       )
     order by coalesce(
       attempt.supplier_call_started_at,
       attempt.submitted_at,
       attempt.resolved_at,
       attempt.updated_at
     ), attempt.id
     limit p_limit
     for update skip locked
  loop
    v_state_before := v_attempt.state;
    v_reason_code := case
      when v_attempt.supplier_call_started_at is not null
        then 'book_supplier_call_watchdog_timeout'
      else 'book_local_claim_watchdog_timeout'
    end;
    v_reason_detail := case
      when v_attempt.supplier_call_started_at is not null then
        'Book supplier write exceeded the three-minute watchdog; reconcile by authoritative read and never replay the write.'
      else
        'Book attempt claim exceeded the three-minute watchdog before the supplier-call boundary was recorded.'
    end;

    v_wallet_result := public.wallet_mark_reconciliation(
      null,
      v_attempt.id,
      v_reason_detail
    );

    update public.booking_attempts
       set state = 'unknown',
           error_code = upper(v_reason_code),
           supplier_message = coalesce(supplier_message, v_reason_detail),
           resolved_at = coalesce(resolved_at, now())
     where id = v_attempt.id;

    v_case_id := null;
    insert into public.booking_reconciliation_cases (
      subject_booking_attempt_id, case_type, state,
      reason_code, reason_detail, opened_source,
      opened_by_user_id, opened_by_role, opened_at,
      assigned_team, severity, priority, due_at,
      evidence, evidence_latest_at, evidence_normalizer_version,
      policy_version
    ) values (
      v_attempt.id, 'attempt_uncertainty', 'open',
      v_reason_code, v_reason_detail, 'operation',
      'system:attempt-watchdog', 'system', now(),
      'support', 'high', 85, now() + interval '15 minutes',
      jsonb_build_array(jsonb_build_object(
        'kind', 'attempt_watchdog_observation',
        'observedAt', now(),
        'attemptStateBefore', v_state_before,
        'supplierCallStartedAt', v_attempt.supplier_call_started_at,
        'supplierResponseRecorded',
          v_attempt.supplier_response_received_at is not null,
        'walletPositionProtected', coalesce(
          (v_wallet_result->>'ok')::boolean, false
        ),
        'automaticSupplierReplay', false
      )),
      now(), 1, 1
    ) on conflict do nothing
    returning id into v_case_id;

    v_processed := v_processed + 1;
    if v_case_id is not null then
      v_cases_created := v_cases_created + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'processed', v_processed,
    'casesCreated', v_cases_created,
    'thresholdSeconds', 180,
    'caseDueSeconds', 900,
    'limit', p_limit,
    'historicalNullIdentityExcluded', true,
    'automaticSupplierReplay', false
  );
end;
$$;

revoke all on function public.process_booking_attempt_watchdog(integer)
  from public, anon, authenticated;
grant execute on function public.process_booking_attempt_watchdog(integer)
  to service_role;

comment on function public.process_booking_attempt_watchdog(integer) is
  'Owns stale operation-identified Book attempts as attempt_uncertainty cases. Preserves direct-ticket holds, excludes historical null-identity attempts, and never replays Book.';

-- 10. Controlled attempt-reconciliation queue -----------------------------
-- This queue exposes only the durable identifiers and operational/financial
-- posture needed to choose a safe read. It deliberately does not select the
-- passenger snapshot or raw case evidence. AirTicketingDetails can prove an
-- issued/cancelled/refunded report but cannot, by absence, prove that a held
-- booking does not exist; an inconclusive read therefore requires the supplier
-- portal instead of another Book call.
create index if not exists
  booking_reconciliation_cases_attempt_queue_idx
  on public.booking_reconciliation_cases (
    priority, due_at, opened_at, id, subject_booking_attempt_id
  )
  where case_type = 'attempt_uncertainty'
    and subject_booking_attempt_id is not null
    and state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    );

create or replace view public.booking_attempt_reconciliation_queue_v
with (security_invoker = true)
as
select
  reconciliation.id as reconciliation_case_id,
  reconciliation.state as reconciliation_state,
  reconciliation.reason_code,
  reconciliation.reason_detail,
  reconciliation.assigned_team,
  reconciliation.assignee_user_id,
  reconciliation.severity,
  reconciliation.priority,
  reconciliation.opened_at,
  reconciliation.due_at,
  reconciliation.escalation_level,
  reconciliation.evidence_latest_at,
  reconciliation.version as reconciliation_version,
  attempt.id as booking_attempt_id,
  attempt.supplier,
  attempt.state as attempt_state,
  attempt.created_at as attempt_created_at,
  attempt.submitted_at,
  attempt.resolved_at,
  attempt.supplier_call_started_at,
  attempt.supplier_response_received_at,
  attempt.supplier_response_http_status,
  attempt.operation_request_key is not null as operation_identity_present,
  attempt.unique_trans_id,
  attempt.pnr,
  attempt.booking_code_ref,
  coalesce(
    nullif(trim(attempt.unique_trans_id), '') is not null,
    false
  ) as air_ticketing_details_eligible,
  (
    nullif(trim(attempt.unique_trans_id), '') is not null
    and nullif(trim(attempt.item_code_ref), '') is not null
    and nullif(trim(attempt.price_code_ref), '') is not null
    and nullif(trim(attempt.booking_code_ref), '') is not null
    and nullif(trim(attempt.pnr), '') is not null
  ) as pnr_lookup_eligible,
  case
    when nullif(trim(attempt.unique_trans_id), '') is null then
      'manual_supplier_portal_only'
    when nullif(trim(attempt.item_code_ref), '') is not null
      and nullif(trim(attempt.price_code_ref), '') is not null
      and nullif(trim(attempt.booking_code_ref), '') is not null
      and nullif(trim(attempt.pnr), '') is not null then
      'pnr_then_air_ticketing_details'
    else 'air_ticketing_details_then_manual_portal'
  end as supplier_read_strategy,
  'unique_transaction_id'::text as supplier_identity_kind,
  false as destructive_replay_allowed,
  false as automatic_resolution_allowed,
  true as manual_portal_required_if_inconclusive,
  case
    when lower(coalesce(attempt.offer_snapshot->>'directTicketing', 'false'))
      = 'true' then true
    else false
  end as direct_ticketing,
  reservation.id as reservation_id,
  reservation.state as reservation_state,
  reservation.amount as reservation_amount,
  reservation.currency as reservation_currency,
  recovered.id as recovered_booking_id,
  recovered.public_ref as recovered_booking_public_ref
from public.booking_reconciliation_cases reconciliation
join public.booking_attempts attempt
  on attempt.id = reconciliation.subject_booking_attempt_id
left join public.wallet_reservations reservation
  on reservation.booking_attempt_id = attempt.id
left join public.flight_bookings recovered
  on recovered.attempt_id = attempt.id
where reconciliation.case_type = 'attempt_uncertainty'
  and reconciliation.state in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  );

revoke all on table public.booking_attempt_reconciliation_queue_v
  from public, anon, authenticated;
grant select on table public.booking_attempt_reconciliation_queue_v
  to service_role;

comment on view public.booking_attempt_reconciliation_queue_v is
  'Staff-only unresolved Book-attempt queue. Plans safe PNR/AirTicketingDetails reads by durable supplier identity, exposes no passenger/contact/raw evidence, and never authorizes Book replay or automatic resolution.';

-- 11. Deduplicated cases with append-only observation history --------------
create table if not exists public.booking_reconciliation_observations (
  id                     uuid primary key default gen_random_uuid(),
  reconciliation_case_id uuid not null
                         references public.booking_reconciliation_cases (id)
                         on delete restrict,
  observation_key        text not null,
  observation_kind       text not null,
  observation_source     text not null,
  actor_user_id          text not null,
  actor_role             text not null,
  normalized_facts       jsonb not null,
  normalized_facts_hash  text not null,
  observed_at            timestamptz not null,
  created_at             timestamptz not null default now(),
  constraint booking_reconciliation_observations_key_check
    check (char_length(observation_key) between 1 and 255),
  constraint booking_reconciliation_observations_kind_check
    check (observation_kind in (
      'supplier_write_uncertainty', 'supplier_read',
      'watchdog', 'staff_evidence', 'historical_snapshot'
    )),
  constraint booking_reconciliation_observations_source_check
    check (observation_source in (
      'operation', 'watchdog', 'supplier_read',
      'staff', 'historical_remediation'
    )),
  constraint booking_reconciliation_observations_actor_check
    check (
      nullif(btrim(actor_user_id), '') is not null
      and nullif(btrim(actor_role), '') is not null
    ),
  constraint booking_reconciliation_observations_facts_check
    check (jsonb_typeof(normalized_facts) = 'object'),
  constraint booking_reconciliation_observations_hash_check
    check (normalized_facts_hash ~ '^[a-f0-9]{64}$'),
  constraint booking_reconciliation_observations_time_check
    check (observed_at <= created_at + interval '5 minutes'),
  unique (reconciliation_case_id, observation_key)
);

create index if not exists
  booking_reconciliation_observations_case_timeline_idx
  on public.booking_reconciliation_observations (
    reconciliation_case_id, observed_at desc, id desc
  );

create or replace function public.prevent_reconciliation_observation_mutation()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  raise exception 'booking reconciliation observations are immutable'
    using errcode = '55000';
end;
$$;

drop trigger if exists booking_reconciliation_observations_immutable
  on public.booking_reconciliation_observations;
create trigger booking_reconciliation_observations_immutable
  before update or delete on public.booking_reconciliation_observations
  for each row execute function public.prevent_reconciliation_observation_mutation();

alter table public.booking_reconciliation_observations enable row level security;
revoke all on table public.booking_reconciliation_observations
  from public, anon, authenticated, service_role;
grant select, insert on table public.booking_reconciliation_observations
  to service_role;

comment on table public.booking_reconciliation_observations is
  'Append-only normalized evidence occurrences for a reconciliation case. The case is deduplicated, while distinct reads/conflicts retain immutable history.';
comment on column public.booking_reconciliation_observations.observation_key is
  'Occurrence idempotency key. Replaying one application/database request returns the same observation; a later supplier read uses a new key.';
comment on column public.booking_reconciliation_observations.normalized_facts is
  'Protected normalized facts only. Raw supplier payload retention and hashing are introduced by the evidence phase.';

create or replace function public.record_supplier_write_uncertainty_v2(
  p_booking_id uuid,
  p_booking_attempt_id uuid,
  p_operation_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text,
  p_request_payload_hash text,
  p_failure_reason_code text,
  p_http_status integer,
  p_response_observed boolean,
  p_response_recorded boolean,
  p_normalized_facts jsonb,
  p_normalized_facts_hash text,
  p_error_message text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_operation public.booking_operations;
  v_attempt public.booking_attempts;
  v_case_type text;
  v_reason_detail text;
  v_case_id uuid;
  v_observation_id uuid;
  v_observation_created boolean := false;
  v_wallet_result jsonb;
  v_observation_key text;
begin
  if (p_booking_id is null) = (p_booking_attempt_id is null)
     or (p_booking_id is null) <> (p_operation_id is null)
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or nullif(btrim(coalesce(p_actor_role, '')), '') is null
     or nullif(btrim(coalesce(p_request_key, '')), '') is null
     or p_request_payload_hash !~ '^[a-f0-9]{64}$'
     or p_normalized_facts_hash !~ '^[a-f0-9]{64}$'
     or jsonb_typeof(coalesce(p_normalized_facts, '{}'::jsonb)) <> 'object'
     or p_failure_reason_code not in (
       'local_response_boundary_failed', 'network_after_write',
       'incomplete_response', 'protocol_response',
       'supplier_upstream_failure', 'supplier_http_200_failure',
       'unexpected_after_write'
     )
     or coalesce(p_normalized_facts->>'failureClass', '') <> 'uncertain'
     or coalesce((p_normalized_facts->>'automaticReplayAllowed')::boolean, true)
        is not false
     or p_http_status is not null and (p_http_status < 100 or p_http_status > 599)
     or p_response_recorded and not p_response_observed then
    raise exception 'invalid supplier uncertainty observation'
      using errcode = '22023';
  end if;

  v_reason_detail := left(coalesce(
    nullif(btrim(p_error_message), ''),
    'Supplier write outcome requires authoritative read reconciliation'
  ), 1000);
  v_observation_key := p_request_key || ':supplier-uncertainty';

  if p_booking_id is not null then
    select * into v_operation
      from public.booking_operations
     where id = p_operation_id
       and booking_id = p_booking_id
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_FOUND');
    end if;
    if v_operation.request_key is distinct from p_request_key
       or v_operation.request_payload_hash
         is distinct from p_request_payload_hash then
      raise exception 'supplier uncertainty operation identity mismatch'
        using errcode = '22023';
    end if;
    if v_operation.supplier_call_started_at is null then
      return jsonb_build_object(
        'ok', false, 'code', 'SUPPLIER_CALL_NOT_STARTED'
      );
    end if;
    if v_operation.state in ('succeeded', 'failed') then
      return jsonb_build_object(
        'ok', false, 'code', 'OPERATION_ALREADY_TERMINAL'
      );
    end if;

    v_case_type := case
      when v_operation.kind = 'cancellation' then 'cancellation_uncertainty'
      when v_operation.reason_code = 'legacy_reconciliation' then 'legacy_review'
      else 'ticketing_uncertainty'
    end;
    v_wallet_result := public.wallet_mark_reconciliation(
      p_booking_id, null, v_reason_detail
    );
    update public.booking_operations
       set state = 'needs_reconciliation',
           reconciliation_required_at = coalesce(
             reconciliation_required_at, now()
           ),
           error_code = upper(p_failure_reason_code),
           error_message = v_reason_detail
     where id = v_operation.id;
  else
    select * into v_attempt
      from public.booking_attempts
     where id = p_booking_attempt_id
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'ATTEMPT_NOT_FOUND');
    end if;
    if v_attempt.operation_request_key is distinct from p_request_key
       or v_attempt.operation_request_payload_hash
         is distinct from p_request_payload_hash then
      raise exception 'supplier uncertainty attempt identity mismatch'
        using errcode = '22023';
    end if;
    if v_attempt.supplier_call_started_at is null then
      return jsonb_build_object(
        'ok', false, 'code', 'SUPPLIER_CALL_NOT_STARTED'
      );
    end if;
    if v_attempt.state not in ('submitting', 'unknown') then
      return jsonb_build_object(
        'ok', false, 'code', 'ATTEMPT_ALREADY_TERMINAL'
      );
    end if;

    v_case_type := 'attempt_uncertainty';
    v_wallet_result := public.wallet_mark_reconciliation(
      null, p_booking_attempt_id, v_reason_detail
    );
    update public.booking_attempts
       set state = 'unknown',
           error_code = upper(p_failure_reason_code),
           supplier_message = v_reason_detail,
           resolved_at = coalesce(resolved_at, now())
     where id = v_attempt.id;
  end if;

  insert into public.booking_reconciliation_cases (
    subject_booking_id, subject_booking_attempt_id, operation_id,
    case_type, state, reason_code, reason_detail,
    opened_source, opened_by_user_id, opened_by_role, opened_at,
    assigned_team, severity, priority, due_at,
    evidence, evidence_latest_at, evidence_normalizer_version,
    policy_version
  ) values (
    p_booking_id, p_booking_attempt_id, p_operation_id,
    v_case_type, 'open', p_failure_reason_code, v_reason_detail,
    'operation', p_actor_user_id, p_actor_role, now(),
    'support', 'high', 10,
    now() + case
      when v_case_type = 'attempt_uncertainty' then interval '15 minutes'
      else interval '30 minutes'
    end,
    '[]'::jsonb, null, 1, 1
  ) on conflict do nothing
  returning id into v_case_id;

  if v_case_id is null then
    select id into v_case_id
      from public.booking_reconciliation_cases
     where case_type = v_case_type
       and (
         (p_booking_id is not null and subject_booking_id = p_booking_id)
         or (
           p_booking_attempt_id is not null
           and subject_booking_attempt_id = p_booking_attempt_id
         )
       )
       and state in (
         'open', 'assigned', 'awaiting_supplier',
         'awaiting_finance', 'awaiting_approval'
       )
     order by opened_at, id
     limit 1
     for update;
  end if;
  if v_case_id is null then
    raise exception 'supplier uncertainty case could not be owned'
      using errcode = 'P0001';
  end if;

  insert into public.booking_reconciliation_observations (
    reconciliation_case_id, observation_key,
    observation_kind, observation_source,
    actor_user_id, actor_role,
    normalized_facts, normalized_facts_hash,
    observed_at
  ) values (
    v_case_id, v_observation_key,
    'supplier_write_uncertainty', 'operation',
    p_actor_user_id, p_actor_role,
    p_normalized_facts, p_normalized_facts_hash,
    now()
  ) on conflict (reconciliation_case_id, observation_key) do nothing
  returning id into v_observation_id;

  if v_observation_id is not null then
    v_observation_created := true;
    update public.booking_reconciliation_cases
       set evidence_latest_at = now(),
           evidence_normalizer_version = 1,
           version = version + 1
     where id = v_case_id;
  else
    select id into v_observation_id
      from public.booking_reconciliation_observations
     where reconciliation_case_id = v_case_id
       and observation_key = v_observation_key;
  end if;

  return jsonb_build_object(
    'ok', true,
    'replay', not v_observation_created,
    'caseId', v_case_id,
    'caseType', v_case_type,
    'observationId', v_observation_id,
    'operationState', case
      when p_booking_id is not null then 'needs_reconciliation'
      else null
    end,
    'attemptState', case
      when p_booking_attempt_id is not null then 'unknown'
      else null
    end,
    'walletPositionProtected', coalesce(
      (v_wallet_result->>'ok')::boolean, false
    ),
    'automaticSupplierReplay', false
  );
end;
$$;

revoke all on function public.record_supplier_write_uncertainty_v2(
  uuid, uuid, uuid, text, text, text, text, text,
  integer, boolean, boolean, jsonb, text, text
) from public, anon, authenticated;
grant execute on function public.record_supplier_write_uncertainty_v2(
  uuid, uuid, uuid, text, text, text, text, text,
  integer, boolean, boolean, jsonb, text, text
) to service_role;

comment on function public.record_supplier_write_uncertainty_v2(
  uuid, uuid, uuid, text, text, text, text, text,
  integer, boolean, boolean, jsonb, text, text
) is
  'Atomically preserves wallet position, owns one open case, and appends one idempotent immutable observation for an ambiguous Book/NewTicket/Cancel outcome. Never replays a supplier write.';


-- SOURCE: 0046_booking_reconciliation_evidence_reads.sql
-- Controlled, idempotent staff supplier-evidence reads.
-- This migration records normalized read evidence against an existing open
-- reconciliation case. It never changes booking lifecycle truth, creates a
-- lifecycle event/outbox row, or reads/writes wallet balances or ledger rows.

create or replace function public.record_booking_reconciliation_evidence_read_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_observation_key text,
  p_normalized_facts jsonb,
  p_normalized_facts_hash text,
  p_observed_at timestamptz,
  p_evidence_observed_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_case public.booking_reconciliation_cases;
  v_observation public.booking_reconciliation_observations;
  v_existing_hash text;
  v_created boolean := false;
  v_case_version integer;
begin
  if p_booking_id is null
     or p_case_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_actor_role not in ('staff_support', 'admin', 'superadmin')
     or p_observation_key !~ '^evidence-read:v1:[a-f0-9]{64}$'
     or p_normalized_facts_hash !~ '^[a-f0-9]{64}$'
     or jsonb_typeof(coalesce(p_normalized_facts, '{}'::jsonb)) <> 'object'
     or coalesce(p_normalized_facts->>'version', '') <> '1'
     or coalesce(p_normalized_facts->>'action', '')
        <> 'supplier_evidence_read'
     or coalesce((p_normalized_facts->>'statusMutation')::boolean, true)
        is not false
     or coalesce((p_normalized_facts->>'walletMutation')::boolean, true)
        is not false
     or coalesce(
          (p_normalized_facts->>'destructiveSupplierCall')::boolean,
          true
        ) is not false
     or p_normalized_facts->>'bookingId' is distinct from p_booking_id::text
     or p_normalized_facts->>'caseId' is distinct from p_case_id::text
     or p_observed_at is null
     or p_observed_at > clock_timestamp() + interval '1 minute'
     or p_observed_at < clock_timestamp() - interval '5 minutes'
     or (
       p_evidence_observed_at is not null
       and (
         p_evidence_observed_at > p_observed_at + interval '1 minute'
         or p_evidence_observed_at < p_observed_at - interval '5 minutes'
       )
     ) then
    raise exception 'invalid reconciliation evidence-read observation'
      using errcode = '22023';
  end if;

  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;
  if v_case.state not in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  ) then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN');
  end if;
  if not exists (
    select 1 from public.flight_bookings booking
     where booking.id = p_booking_id
  ) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  insert into public.booking_reconciliation_observations (
    reconciliation_case_id,
    observation_key,
    observation_kind,
    observation_source,
    actor_user_id,
    actor_role,
    normalized_facts,
    normalized_facts_hash,
    observed_at
  ) values (
    p_case_id,
    p_observation_key,
    'staff_evidence',
    'supplier_read',
    p_actor_user_id,
    p_actor_role,
    p_normalized_facts,
    p_normalized_facts_hash,
    p_observed_at
  ) on conflict (reconciliation_case_id, observation_key) do nothing
  returning * into v_observation;

  if v_observation.id is null then
    select observation.normalized_facts_hash
      into v_existing_hash
      from public.booking_reconciliation_observations observation
     where observation.reconciliation_case_id = p_case_id
       and observation.observation_key = p_observation_key;
    if v_existing_hash is distinct from p_normalized_facts_hash then
      raise exception 'evidence-read request payload mismatch'
        using errcode = '22023';
    end if;
    select observation.* into v_observation
      from public.booking_reconciliation_observations observation
     where observation.reconciliation_case_id = p_case_id
       and observation.observation_key = p_observation_key;
  else
    v_created := true;
    update public.booking_reconciliation_cases
       set evidence_latest_at = case
             when p_evidence_observed_at is null then evidence_latest_at
             when evidence_latest_at is null then p_evidence_observed_at
             else greatest(evidence_latest_at, p_evidence_observed_at)
           end,
           evidence_normalizer_version = case
             when p_evidence_observed_at is null
               then evidence_normalizer_version
             else 1
           end,
           version = version + 1
     where id = p_case_id;
  end if;

  select version into v_case_version
    from public.booking_reconciliation_cases
   where id = p_case_id;

  return jsonb_build_object(
    'ok', true,
    'replay', not v_created,
    'caseId', p_case_id,
    'caseVersion', v_case_version,
    'observationId', v_observation.id,
    'evidenceLatestAt', case
      when p_evidence_observed_at is null then null
      else p_evidence_observed_at
    end,
    'statusMutation', false,
    'walletMutation', false,
    'destructiveSupplierCall', false
  );
end;
$$;

revoke all on function public.record_booking_reconciliation_evidence_read_v1(
  uuid, uuid, text, text, text, jsonb, text, timestamptz, timestamptz
) from public, anon, authenticated;
grant execute on function public.record_booking_reconciliation_evidence_read_v1(
  uuid, uuid, text, text, text, jsonb, text, timestamptz, timestamptz
) to service_role;

comment on function public.record_booking_reconciliation_evidence_read_v1(
  uuid, uuid, text, text, text, jsonb, text, timestamptz, timestamptz
) is
  'Appends one payload-bound, idempotent normalized staff evidence read to an existing open booking reconciliation case. Never changes booking status, lifecycle events, notifications, wallet balances, reservations, or ledger entries.';


-- SOURCE: 0047_booking_reconciliation_no_change_closure.sql
-- Narrow automatic closure for evidence that confirms existing terminal truth.
-- Lock order is booking -> operation -> case -> reservation. The function can
-- complete internal ownership metadata but cannot change lifecycle status,
-- wallet balances, reservations, ledger, lifecycle events, or notifications.

create or replace function public.close_booking_reconciliation_no_change_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_observation_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_observation public.booking_reconciliation_observations;
  v_operation_id uuid;
  v_expected_truth text;
  v_evidence_truth text;
  v_evidence_at timestamptz;
begin
  if p_booking_id is null or p_case_id is null or p_observation_id is null then
    raise exception 'invalid no-change closure request' using errcode = '22023';
  end if;

  -- Read the immutable operation reference first, then acquire every mutable
  -- row in the global lifecycle/financial lock order.
  select candidate.operation_id into v_operation_id
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  if v_operation_id is not null then
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_operation_id
       and operation.booking_id = p_booking_id
     for update;
  end if;

  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
   for update;
  if v_case.state = 'closed_no_change'
     and v_case.resolution_outcome = 'supplier_truth_unchanged'
     and v_case.resolution->>'observationId' = p_observation_id::text then
    return jsonb_build_object(
      'ok', true,
      'replay', true,
      'caseId', p_case_id,
      'observationId', p_observation_id,
      'statusMutation', false,
      'walletMutation', false
    );
  end if;
  if v_case.state not in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  ) then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN');
  end if;

  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = p_booking_id
   for update;

  select observation.* into v_observation
    from public.booking_reconciliation_observations observation
   where observation.id = p_observation_id
     and observation.reconciliation_case_id = p_case_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_NOT_FOUND');
  end if;

  if v_case.case_type not in (
       'ticketing_uncertainty', 'cancellation_uncertainty'
     )
     or v_case.proposed_outcome is not null
     or v_case.financial_disposition <> 'none'
     or v_case.operation_id is null
     or v_operation.id is null
     or v_operation.state <> 'needs_reconciliation'
     or v_booking.active_operation_id is not null
        and v_booking.active_operation_id <> v_operation.id
     or exists (
       select 1 from public.booking_reconciliation_cases other_case
        where other_case.subject_booking_id = p_booking_id
          and other_case.id <> p_case_id
          and other_case.state in (
            'open', 'assigned', 'awaiting_supplier',
            'awaiting_finance', 'awaiting_approval'
          )
     ) then
    return jsonb_build_object('ok', false, 'code', 'NO_CHANGE_CLOSURE_NOT_ELIGIBLE');
  end if;

  v_expected_truth := case v_booking.status
    when 'confirmed' then 'ticketed'
    when 'cancelled' then 'cancelled'
    else null
  end;
  v_evidence_truth := v_observation.normalized_facts
    #>> '{validation,authoritativeFor}';
  begin
    v_evidence_at := (
      v_observation.normalized_facts->>'evidenceObservedAt'
    )::timestamptz;
  exception when others then
    v_evidence_at := null;
  end;

  if v_expected_truth is null
     or v_evidence_truth is distinct from v_expected_truth
     or v_observation.observation_kind <> 'staff_evidence'
     or v_observation.observation_source <> 'supplier_read'
     or v_observation.normalized_facts->>'action'
        is distinct from 'supplier_evidence_read'
     or v_observation.normalized_facts->>'bookingId'
        is distinct from p_booking_id::text
     or v_observation.normalized_facts->>'caseId'
        is distinct from p_case_id::text
     or coalesce(
          (v_observation.normalized_facts #>> '{validation,valid}')::boolean,
          false
        ) is not true
     or coalesce(
          (v_observation.normalized_facts #>> '{validation,complete}')::boolean,
          false
        ) is not true
     or coalesce(
          (v_observation.normalized_facts #>> '{validation,fresh}')::boolean,
          false
        ) is not true
     or coalesce(
          (
            v_observation.normalized_facts
              #>> '{validation,identityMatches}'
          )::boolean,
          false
        ) is not true
     or v_evidence_at is null
     or v_evidence_at < clock_timestamp() - interval '5 minutes'
     or v_evidence_at > clock_timestamp() + interval '1 minute'
     or not (
       coalesce(
         v_observation.normalized_facts->'recordedSources', '[]'::jsonb
       ) @> '["pnr", "air-ticketing-details"]'::jsonb
     )
     or v_observation.normalized_facts #>> '{evidence,pnr,source}'
        is distinct from 'pnr'
     or v_observation.normalized_facts
          #>> '{evidence,airTicketing,source}'
        is distinct from 'air-ticketing-details'
     or upper(btrim(coalesce(
          v_observation.normalized_facts
            #>> '{expectedIdentity,uniqueTransId}',
          ''
        ))) is distinct from upper(btrim(coalesce(
          v_booking.supplier_refs->>'uniqueTransId',
          ''
        )))
     or upper(btrim(coalesce(
          v_observation.normalized_facts
            #>> '{expectedIdentity,bookingCodeRef}',
          ''
        ))) is distinct from upper(btrim(coalesce(
          v_booking.booking_code_ref,
          ''
        )))
     or v_observation.normalized_facts #>> '{localContext,storedStatus}'
        is distinct from v_booking.status
     or v_observation.normalized_facts #>> '{localContext,paymentState}'
        is distinct from v_booking.payment_state
     or (v_expected_truth = 'ticketed' and v_operation.kind <> 'ticketing')
     or (v_expected_truth = 'cancelled' and v_operation.kind <> 'cancellation')
     then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_NOT_AUTHORITATIVE');
  end if;

  if (
    v_booking.status = 'confirmed'
    and not (
      v_booking.payment_state = 'captured'
      and v_booking.captured_amount > 0
      and v_booking.refunded_amount = 0
      and v_booking.payment_amount = v_booking.captured_amount
      and v_reservation.id is not null
      and v_reservation.state = 'captured'
      and v_reservation.amount = v_booking.captured_amount
      and v_reservation.currency = v_booking.currency
    )
  ) or (
    v_booking.status = 'cancelled'
    and not (
      (
        v_booking.payment_state = 'unpaid'
        and v_booking.captured_amount = 0
        and v_booking.refunded_amount = 0
        and v_reservation.id is null
      )
      or (
        v_booking.payment_state = 'released'
        and v_booking.captured_amount = 0
        and v_booking.refunded_amount = 0
        and v_reservation.id is not null
        and v_reservation.state = 'released'
      )
      or (
        v_booking.payment_state = 'refunded'
        and v_booking.captured_amount > 0
        and v_booking.refunded_amount = v_booking.captured_amount
        and v_reservation.id is not null
        and v_reservation.state = 'captured'
      )
    )
  ) then
    return jsonb_build_object('ok', false, 'code', 'FINANCIAL_CONFLICT');
  end if;

  update public.booking_operations
     set state = 'succeeded',
         completed_at = coalesce(completed_at, clock_timestamp()),
         error_code = null,
         error_message = null,
         supplier_evidence = supplier_evidence || jsonb_build_object(
           'noChangeClosure', jsonb_build_object(
             'observationId', p_observation_id,
             'authoritativeFor', v_evidence_truth,
             'closedAt', clock_timestamp()
           )
         )
   where id = v_operation.id;

  update public.flight_bookings
     set active_operation_id = null,
         operation_kind = null,
         operation_reason = null,
         operation_request_id = null,
         operation_actor_user_id = null,
         operation_started_at = null,
         operation_prior_status = null
   where id = p_booking_id;

  update public.booking_reconciliation_cases
     set state = 'closed_no_change',
         resolution_outcome = 'supplier_truth_unchanged',
         resolution = jsonb_build_object(
           'observationId', p_observation_id,
           'authoritativeFor', v_evidence_truth,
           'statusMutation', false,
           'walletMutation', false
         ),
         resolution_reason =
           'Fresh complete supplier evidence confirms existing terminal truth and financial state is already consistent',
         resolved_by_user_id = 'system:evidence-no-change',
         resolved_at = clock_timestamp(),
         closed_at = clock_timestamp(),
         version = version + 1
   where id = p_case_id;

  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id, outcome, metadata
  ) values (
    'system:evidence-no-change',
    'system',
    'booking.reconciliation.closed_no_change',
    'flight_booking',
    p_booking_id::text,
    'succeeded',
    jsonb_build_object(
      'caseId', p_case_id,
      'operationId', v_operation.id,
      'observationId', p_observation_id,
      'authoritativeFor', v_evidence_truth,
      'statusMutation', false,
      'walletMutation', false
    )
  );

  return jsonb_build_object(
    'ok', true,
    'replay', false,
    'caseId', p_case_id,
    'operationId', v_operation.id,
    'observationId', p_observation_id,
    'closedNoChange', true,
    'statusMutation', false,
    'walletMutation', false
  );
end;
$$;

revoke all on function public.close_booking_reconciliation_no_change_v1(
  uuid, uuid, uuid
) from public, anon, authenticated;
grant execute on function public.close_booking_reconciliation_no_change_v1(
  uuid, uuid, uuid
) to service_role;

comment on function public.close_booking_reconciliation_no_change_v1(
  uuid, uuid, uuid
) is
  'Closes one ticketing/cancellation uncertainty case and completes its operation only when fresh complete PNR+AirTicketingDetails evidence matches the existing terminal status and the wallet/reservation state is already consistent. It creates no lifecycle event or notification and moves no money.';


-- SOURCE: 0048_booking_supplier_sync_protection.sql
-- Ordinary supplier synchronization is evidence acquisition, not a generic
-- lifecycle setter. Matching state may be enriched; a differing supplier
-- outcome is recorded in an owned case without changing protected local truth.

create or replace function public.record_booking_sync_case_v1(
  p_booking_id uuid,
  p_case_type text,
  p_reason_code text,
  p_reason_detail text,
  p_actor_user_id text,
  p_actor_role text,
  p_normalized_facts jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_case_id uuid;
  v_observation_id uuid;
  v_facts_hash text;
  v_observation_key text;
begin
  if p_booking_id is null
     or p_case_type not in (
       'ticketing_uncertainty', 'cancellation_uncertainty',
       'legacy_review', 'terminal_conflict',
       'imported_manual_ticketing', 'imported_payment_conflict'
     )
     or nullif(btrim(p_reason_code), '') is null
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_actor_role), '') is null
     or p_normalized_facts is null
     or jsonb_typeof(p_normalized_facts) <> 'object' then
    raise exception 'invalid supplier sync case request' using errcode = '22023';
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    raise exception 'booking not found' using errcode = 'P0002';
  end if;

  insert into public.booking_reconciliation_cases (
    subject_booking_id, operation_id, case_type, state,
    reason_code, reason_detail,
    opened_source, opened_by_user_id, opened_by_role, opened_at,
    assigned_team, severity, priority, due_at,
    evidence, evidence_normalizer_version, policy_version
  ) values (
    p_booking_id, v_booking.active_operation_id, p_case_type, 'open',
    p_reason_code, left(coalesce(p_reason_detail, p_reason_code), 1000),
    'supplier_sync', p_actor_user_id, p_actor_role, clock_timestamp(),
    case when p_case_type in ('terminal_conflict', 'imported_payment_conflict')
      then 'admin' else 'support' end,
    case when p_case_type in ('terminal_conflict', 'imported_payment_conflict')
      then 'critical' else 'high' end,
    case when p_case_type in ('terminal_conflict', 'imported_payment_conflict')
      then 0 else 20 end,
    clock_timestamp() + case
      when p_case_type in ('terminal_conflict', 'imported_payment_conflict')
        then interval '1 hour'
      else interval '30 minutes'
    end,
    '[]'::jsonb, 1, 1
  ) on conflict do nothing
  returning id into v_case_id;

  if v_case_id is null then
    select candidate.id into v_case_id
      from public.booking_reconciliation_cases candidate
     where candidate.subject_booking_id = p_booking_id
       and candidate.case_type = p_case_type
       and candidate.state in (
         'open', 'assigned', 'awaiting_supplier',
         'awaiting_finance', 'awaiting_approval'
       )
     order by candidate.opened_at, candidate.id
     limit 1
     for update;
  end if;
  if v_case_id is null then
    raise exception 'supplier sync case could not be owned' using errcode = 'P0001';
  end if;

  -- JSONB has a stable textual representation in PostgreSQL. Two MD5 domains
  -- provide the existing 64-hex payload binding used by migration-only rows;
  -- the supplier evidence itself retains its transport SHA-256 receipt.
  v_facts_hash := md5(p_normalized_facts::text)
    || md5('supplier-sync:v1:' || p_normalized_facts::text);
  v_observation_key := 'supplier-sync:v1:' || v_facts_hash;

  insert into public.booking_reconciliation_observations (
    reconciliation_case_id, observation_key,
    observation_kind, observation_source,
    actor_user_id, actor_role,
    normalized_facts, normalized_facts_hash,
    observed_at
  ) values (
    v_case_id, v_observation_key,
    'supplier_read', 'supplier_read',
    p_actor_user_id, p_actor_role,
    p_normalized_facts, v_facts_hash,
    clock_timestamp()
  ) on conflict (reconciliation_case_id, observation_key) do nothing
  returning id into v_observation_id;

  if v_observation_id is not null then
    update public.booking_reconciliation_cases
       set evidence_latest_at = clock_timestamp(),
           evidence_normalizer_version = 1,
           version = version + 1
     where id = v_case_id;
  end if;

  return v_case_id;
end;
$$;

revoke all on function public.record_booking_sync_case_v1(
  uuid, text, text, text, text, text, jsonb
) from public, anon, authenticated, service_role;

create or replace function public.record_booking_supplier_refresh_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_sync_source text,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticket_numbers jsonb,
  p_issued_at timestamptz,
  p_cancelled_at timestamptz,
  p_normalized_evidence jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_before public.flight_bookings;
  v_after public.flight_bookings;
  v_target text;
  v_case_type text;
  v_case_id uuid;
  v_conflict boolean;
  v_terminal boolean;
  v_before_lifecycle text;
  v_after_lifecycle text;
  v_facts jsonb;
begin
  if nullif(btrim(p_actor_user_id), '') is null
     or p_actor_role not in (
       'superadmin', 'admin', 'staff_support', 'staff_account',
       'customer', 'b2b', 'b2b_sub', 'system'
     )
     or p_sync_source not in (
       'ordinary_sync', 'cancellation_verification', 'compatibility_sync'
     ) then
    raise exception 'invalid supplier refresh actor' using errcode = '22023';
  end if;

  select booking.* into v_before
    from public.flight_bookings booking
   where booking.id = p_booking_id and not booking.legacy_operational
   for update;
  if not found then raise exception 'booking not found' using errcode = 'P0002'; end if;

  v_target := case lower(btrim(coalesce(p_supplier_status, '')))
    when 'issued' then 'confirmed'
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    else null
  end;
  v_terminal := v_before.status in ('confirmed', 'cancelled');
  v_conflict := case
    when v_terminal then v_target is distinct from v_before.status
    else v_target is not null and v_target <> v_before.status
  end;
  v_before_lifecycle := public.resolve_booking_lifecycle(
    v_before.status, v_before.airlines_pnr,
    v_before.ticketing_deadline_at, v_before.operation_kind
  );
  v_facts := jsonb_build_object(
    'version', 1,
    'action', 'ordinary_supplier_sync',
    'source', 'air-ticketing-details',
    'syncSource', p_sync_source,
    'bookingId', p_booking_id,
    'localStoredStatus', v_before.status,
    'localLifecycleStatus', v_before_lifecycle,
    'supplierStatus', p_supplier_status,
    'candidateLifecycleStatus', v_target,
    'protectedTerminal', v_terminal,
    'statusMutation', false,
    'walletMutation', false,
    'evidence', coalesce(p_normalized_evidence, '{}'::jsonb)
  );

  if v_conflict then
    -- Conflicting supplier truth is retained only in the immutable observation.
    -- Do not copy conflicting PNR/ticket/timestamps over local truth.
    update public.flight_bookings
       set synced_at = clock_timestamp(),
           booking_status = p_supplier_status
     where id = p_booking_id
     returning * into v_after;

    v_case_type := case
      when v_terminal then 'terminal_conflict'
      when v_target = 'cancelled' then 'cancellation_uncertainty'
      else 'ticketing_uncertainty'
    end;
    v_case_id := public.record_booking_sync_case_v1(
      p_booking_id,
      v_case_type,
      'supplier_sync_conflicts_with_local_truth',
      'Ordinary AirTicketingDetails Sync differs from local lifecycle truth and requires controlled resolution.',
      p_actor_user_id,
      p_actor_role,
      v_facts || jsonb_build_object('caseType', v_case_type)
    );
  else
    -- Matching terminal truth or non-terminal enrichment may update only the
    -- corresponding supplier snapshot. It does not set lifecycle status.
    update public.flight_bookings
       set synced_at = clock_timestamp(),
           booking_status = p_supplier_status,
           airlines_pnr = case
             when public.jsonb_is_nonempty_array(p_airlines_pnr)
               then p_airlines_pnr
             else airlines_pnr
           end,
           ticket_numbers = case
             when public.jsonb_is_nonempty_array(p_ticket_numbers)
               then p_ticket_numbers
             else ticket_numbers
           end,
           issued_at = case
             when status = 'confirmed' and v_target = 'confirmed'
               then coalesce(p_issued_at, issued_at)
             else issued_at
           end,
           cancelled_at = case
             when status = 'cancelled' and v_target = 'cancelled'
               then coalesce(p_cancelled_at, cancelled_at)
             else cancelled_at
           end
     where id = p_booking_id
     returning * into v_after;
  end if;

  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_after.status, v_after.airlines_pnr,
    v_after.ticketing_deadline_at, v_after.operation_kind
  );
  if v_after_lifecycle is distinct from v_before_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation,
      supplier_evidence
    ) values (
      p_booking_id, v_before_lifecycle, v_after_lifecycle,
      v_before.status, v_after.status, v_after.operation_kind,
      v_after.operation_reason, p_actor_user_id, 'SupplierRefreshV2',
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'statusMutation', false,
        'walletMutation', false
      )
    );
  end if;
  return v_after;
end;
$$;

create or replace function public.record_booking_pnr_refresh_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_sync_source text,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticketing_time_limit text,
  p_ticketing_deadline_at timestamptz,
  p_normalized_evidence jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_before public.flight_bookings;
  v_after public.flight_bookings;
  v_target text;
  v_case_type text;
  v_case_id uuid;
  v_conflict boolean;
  v_terminal boolean;
  v_before_lifecycle text;
  v_after_lifecycle text;
  v_facts jsonb;
begin
  if nullif(btrim(p_actor_user_id), '') is null
     or p_actor_role not in (
       'superadmin', 'admin', 'staff_support', 'staff_account',
       'customer', 'b2b', 'b2b_sub', 'system'
     )
     or p_sync_source not in (
       'ordinary_sync', 'cancellation_verification', 'compatibility_sync'
     ) then
    raise exception 'invalid PNR refresh actor' using errcode = '22023';
  end if;

  select booking.* into v_before
    from public.flight_bookings booking
   where booking.id = p_booking_id and not booking.legacy_operational
   for update;
  if not found then raise exception 'booking not found' using errcode = 'P0002'; end if;

  v_target := case lower(btrim(coalesce(p_supplier_status, '')))
    when 'issued' then 'confirmed'
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    when 'booked' then 'on-hold'
    when 'created' then 'on-hold'
    when 'held' then 'on-hold'
    else null
  end;
  v_terminal := v_before.status in ('confirmed', 'cancelled');
  v_conflict := case
    when v_terminal then v_target is distinct from v_before.status
    when p_sync_source = 'cancellation_verification'
      and v_before.status = 'in-progress' and v_target = 'on-hold' then false
    else v_target in ('confirmed', 'cancelled')
      or (v_target is not null and v_target <> v_before.status)
  end;
  v_before_lifecycle := public.resolve_booking_lifecycle(
    v_before.status, v_before.airlines_pnr,
    v_before.ticketing_deadline_at, v_before.operation_kind
  );
  v_facts := jsonb_build_object(
    'version', 1,
    'action', 'ordinary_supplier_sync',
    'source', 'pnr',
    'syncSource', p_sync_source,
    'bookingId', p_booking_id,
    'localStoredStatus', v_before.status,
    'localLifecycleStatus', v_before_lifecycle,
    'supplierStatus', p_supplier_status,
    'candidateLifecycleStatus', v_target,
    'protectedTerminal', v_terminal,
    'statusMutation', false,
    'walletMutation', false,
    'evidence', coalesce(p_normalized_evidence, '{}'::jsonb)
  );

  if v_conflict then
    update public.flight_bookings
       set synced_at = clock_timestamp(),
           booking_status = p_supplier_status
     where id = p_booking_id
     returning * into v_after;
    v_case_type := case
      when v_terminal then 'terminal_conflict'
      when v_target = 'cancelled' then 'cancellation_uncertainty'
      else 'ticketing_uncertainty'
    end;
    v_case_id := public.record_booking_sync_case_v1(
      p_booking_id,
      v_case_type,
      'pnr_sync_conflicts_with_local_truth',
      'Ordinary PNR Sync differs from local lifecycle truth and requires controlled resolution.',
      p_actor_user_id,
      p_actor_role,
      v_facts || jsonb_build_object('caseType', v_case_type)
    );
  else
    update public.flight_bookings
       set synced_at = clock_timestamp(),
           booking_status = p_supplier_status,
           airlines_pnr = case
             when public.jsonb_is_nonempty_array(p_airlines_pnr)
               then p_airlines_pnr
             else airlines_pnr
           end,
           ticketing_time_limit = case
             when p_ticketing_deadline_at is not null
               then p_ticketing_time_limit
             else ticketing_time_limit
           end,
           ticketing_deadline_at = coalesce(
             p_ticketing_deadline_at, ticketing_deadline_at
           ),
           deadline_source = case
             when p_ticketing_deadline_at is not null
               then 'pnr_call'
             else deadline_source
           end
     where id = p_booking_id
     returning * into v_after;
  end if;

  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_after.status, v_after.airlines_pnr,
    v_after.ticketing_deadline_at, v_after.operation_kind
  );
  if v_after_lifecycle is distinct from v_before_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation,
      supplier_evidence
    ) values (
      p_booking_id, v_before_lifecycle, v_after_lifecycle,
      v_before.status, v_after.status, v_after.operation_kind,
      v_after.operation_reason, p_actor_user_id, 'PnrRefreshV2',
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'airlinesPnr', p_airlines_pnr,
        'ticketingDeadlineAt', p_ticketing_deadline_at,
        'statusMutation', false,
        'walletMutation', false
      )
    );
  end if;
  return v_after;
end;
$$;

-- Keep the established RPC signatures safe during a rolling application
-- deployment. Compatibility callers receive the same protected behavior.
create or replace function public.record_booking_supplier_refresh(
  p_booking_id uuid,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticket_numbers jsonb,
  p_issued_at timestamptz,
  p_cancelled_at timestamptz
)
returns public.flight_bookings
language sql
security definer
set search_path = public
as $$
