-- SOURCE: 0049_booking_reconciliation_security_audit.sql
-- Reconciliation audit is a database invariant, not only an API convention.
-- Store transition metadata and immutable identifiers, never raw evidence,
-- passenger data, proposal bodies, or resolution bodies.

create or replace function public.deny_security_audit_event_mutation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'security audit events are immutable' using errcode = '55000';
end;
$$;

drop trigger if exists security_audit_events_deny_update_delete_v1
  on public.security_audit_events;
create trigger security_audit_events_deny_update_delete_v1
  before update or delete on public.security_audit_events
  for each row execute function public.deny_security_audit_event_mutation_v1();

create or replace function public.audit_reconciliation_observation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking_id uuid;
  v_attempt_id uuid;
begin
  select reconciliation_case.subject_booking_id,
         reconciliation_case.subject_booking_attempt_id
    into v_booking_id, v_attempt_id
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = new.reconciliation_case_id;

  insert into public.security_audit_events (
    actor_user_id, actor_role, action,
    target_type, target_id, outcome, metadata
  ) values (
    new.actor_user_id,
    new.actor_role,
    'booking.reconciliation.evidence_recorded',
    case when v_booking_id is not null
      then 'flight_booking' else 'booking_attempt' end,
    coalesce(v_booking_id::text, v_attempt_id::text),
    'succeeded',
    jsonb_build_object(
      'caseId', new.reconciliation_case_id,
      'observationId', new.id,
      'observationKind', new.observation_kind,
      'observationSource', new.observation_source,
      'factsHash', new.normalized_facts_hash,
      'rawEvidenceStored', false
    )
  );
  return new;
end;
$$;

drop trigger if exists booking_reconciliation_observation_audit_v1
  on public.booking_reconciliation_observations;
create trigger booking_reconciliation_observation_audit_v1
  after insert on public.booking_reconciliation_observations
  for each row execute function public.audit_reconciliation_observation_v1();

create or replace function public.reconciliation_audit_actor_role_v1(
  p_actor_user_id text
)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select app_user.role
       from public.app_users app_user
      where app_user.clerk_id = p_actor_user_id),
    case when p_actor_user_id like 'system:%' then 'system' else 'unknown' end
  );
$$;

create or replace function public.audit_reconciliation_case_transition_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_target_type text := case when new.subject_booking_id is not null
    then 'flight_booking' else 'booking_attempt' end;
  v_target_id text := coalesce(
    new.subject_booking_id::text,
    new.subject_booking_attempt_id::text
  );
begin
  if new.proposal_hash is not null
     and new.proposed_by_user_id is not null
     and (
       old.proposal_hash is distinct from new.proposal_hash
       or old.proposed_at is distinct from new.proposed_at
     ) then
    insert into public.security_audit_events (
      actor_user_id, actor_role, action,
      target_type, target_id, outcome, metadata
    ) values (
      new.proposed_by_user_id,
      public.reconciliation_audit_actor_role_v1(new.proposed_by_user_id),
      'booking.reconciliation.proposed',
      v_target_type, v_target_id, 'succeeded',
      jsonb_build_object(
        'caseId', new.id,
        'caseVersion', new.version,
        'proposalHash', new.proposal_hash,
        'proposedOutcome', new.proposed_outcome,
        'financialDisposition', new.financial_disposition,
        'proposalBodyStored', false
      )
    );
  end if;

  if new.rejected_at is not null
     and new.rejected_by_user_id is not null
     and old.rejected_at is distinct from new.rejected_at then
    insert into public.security_audit_events (
      actor_user_id, actor_role, action,
      target_type, target_id, outcome, metadata
    ) values (
      new.rejected_by_user_id,
      public.reconciliation_audit_actor_role_v1(new.rejected_by_user_id),
      'booking.reconciliation.rejected',
      v_target_type, v_target_id, 'succeeded',
      jsonb_build_object(
        'caseId', new.id,
        'caseVersion', new.version,
        'proposalHash', new.proposal_hash,
        'rejectionReasonRecorded', new.rejection_reason is not null
      )
    );
  end if;

  if new.approved_at is not null
     and new.approved_by_user_id is not null
     and old.approved_at is distinct from new.approved_at then
    insert into public.security_audit_events (
      actor_user_id, actor_role, action,
      target_type, target_id, outcome, metadata
    ) values (
      new.approved_by_user_id,
      public.reconciliation_audit_actor_role_v1(new.approved_by_user_id),
      'booking.reconciliation.approved',
      v_target_type, v_target_id, 'succeeded',
      jsonb_build_object(
        'caseId', new.id,
        'caseVersion', new.version,
        'proposalHash', new.proposal_hash,
        'makerCheckerSeparated',
          new.approved_by_user_id is distinct from new.proposed_by_user_id
      )
    );
  end if;

  if new.resolved_at is not null
     and new.resolved_by_user_id is not null
     and old.resolved_at is distinct from new.resolved_at
     and not (
       new.state = 'closed_no_change'
       and new.resolution_outcome = 'supplier_truth_unchanged'
       and new.resolved_by_user_id = 'system:evidence-no-change'
     ) then
    insert into public.security_audit_events (
      actor_user_id, actor_role, action,
      target_type, target_id, outcome, metadata
    ) values (
      new.resolved_by_user_id,
      public.reconciliation_audit_actor_role_v1(new.resolved_by_user_id),
      'booking.reconciliation.resolved',
      v_target_type, v_target_id, 'succeeded',
      jsonb_build_object(
        'caseId', new.id,
        'caseVersion', new.version,
        'proposalHash', new.proposal_hash,
        'resolutionOutcome', new.resolution_outcome,
        'financialDisposition', new.financial_disposition,
        'resolutionBodyStored', false
      )
    );
  end if;
  return new;
end;
$$;

drop trigger if exists booking_reconciliation_case_transition_audit_v1
  on public.booking_reconciliation_cases;
create trigger booking_reconciliation_case_transition_audit_v1
  after update on public.booking_reconciliation_cases
  for each row execute function public.audit_reconciliation_case_transition_v1();

revoke all on function public.deny_security_audit_event_mutation_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.audit_reconciliation_observation_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.reconciliation_audit_actor_role_v1(text)
  from public, anon, authenticated, service_role;
revoke all on function public.audit_reconciliation_case_transition_v1()
  from public, anon, authenticated, service_role;

comment on trigger booking_reconciliation_observation_audit_v1
  on public.booking_reconciliation_observations is
  'Atomically records a PII-minimized immutable security event for every newly stored reconciliation evidence observation.';
comment on trigger booking_reconciliation_case_transition_audit_v1
  on public.booking_reconciliation_cases is
  'Atomically audits proposal, rejection, approval, and resolution field transitions without copying proposal/resolution bodies.';


-- SOURCE: 0050_booking_reconciliation_maker_checker.sql
-- Durable proposal / approval / rejection controls. These functions do not
-- change booking status, operations, reservations, wallet balances, ledger,
-- lifecycle events, or notifications. Outcome execution is added separately.

alter table public.booking_reconciliation_cases
  add constraint booking_reconciliation_cases_proposal_shape_v1_check
  check (
    (proposal_hash is null
      and proposed_by_user_id is null
      and proposed_at is null)
    or (proposal_hash is not null
      and proposed_by_user_id is not null
      and proposed_at is not null
      and proposal->>'version' = '1'
      and nullif(proposal->>'requestKey', '') is not null
      and nullif(proposal->>'domain', '') is not null
      and jsonb_typeof(proposal->'riskFlags') = 'array'
      and jsonb_typeof(proposal->'confirmationCodes') = 'array'
      and jsonb_typeof(proposal->'evidenceObservationIds') = 'array')
  ) not valid,
  add constraint booking_reconciliation_cases_approval_shape_v1_check
  check (
    (approved_by_user_id is null and approved_at is null)
    or (approved_by_user_id is not null
      and approved_at is not null
      and proposal_hash is not null
      and coalesce((proposal->>'makerCheckerRequired')::boolean, false)
      and approved_by_user_id <> proposed_by_user_id)
  ) not valid,
  add constraint booking_reconciliation_cases_rejection_shape_v1_check
  check (
    (rejected_by_user_id is null and rejected_at is null)
    or (rejected_by_user_id is not null
      and rejected_at is not null
      and nullif(btrim(rejection_reason), '') is not null
      and proposal_hash is not null)
  ) not valid;

create or replace function public.propose_booking_reconciliation_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_request_key text,
  p_actor_user_id text,
  p_domain text,
  p_proposed_outcome text,
  p_financial_disposition text,
  p_financial_amount bigint,
  p_financial_currency text,
  p_external_settlement_reference text,
  p_evidence_observation_ids uuid[],
  p_confirmation_codes text[],
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_evidence_ids uuid[];
  v_confirmation_codes text[];
  v_risk_flags text[] := array[]::text[];
  v_required_codes text[] := array[]::text[];
  v_target_status text;
  v_has_identity_exception boolean;
  v_has_incomplete_exception boolean;
  v_maker_checker boolean;
  v_proposal jsonb;
  v_proposal_hash text;
begin
  if p_booking_id is null or p_case_id is null
     or p_expected_case_version is null or p_expected_case_version < 1
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 255
     or nullif(btrim(p_actor_user_id), '') is null
     or p_domain not in (
       'supplier_truth', 'financial', 'combined_supplier_financial'
     )
     or p_proposed_outcome not in (
       'ticketed', 'cancelled', 'held_not_ticketed',
       'financial_only', 'historical_repair'
     )
     or p_financial_disposition not in (
       'none', 'capture_existing_hold', 'release_existing_hold',
       'full_refund', 'partial_refund', 'no_refund_due',
       'externally_settled', 'manual_adjustment_required'
     )
     or nullif(btrim(p_reason), '') is null
     or char_length(p_reason) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_PROPOSAL');
  end if;

  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'ACTOR_NOT_FOUND');
  end if;
  if (p_domain = 'supplier_truth'
        and v_actor_role not in ('superadmin', 'admin', 'staff_support'))
     or (p_domain = 'financial'
        and v_actor_role not in ('superadmin', 'admin', 'staff_account'))
     or (p_domain = 'combined_supplier_financial'
        and v_actor_role not in ('superadmin', 'admin')) then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_FORBIDDEN');
  end if;

  if (p_domain = 'supplier_truth' and p_financial_disposition <> 'none')
     or (p_domain = 'financial'
       and (p_proposed_outcome <> 'financial_only'
         or p_financial_disposition = 'none'))
     or (p_domain = 'combined_supplier_financial'
       and (p_proposed_outcome = 'financial_only'
         or p_financial_disposition = 'none')) then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_DOMAIN_MISMATCH');
  end if;
  if p_financial_disposition = 'none' and (
       p_financial_amount is not null
       or p_financial_currency is not null
       or p_external_settlement_reference is not null
     ) then
    return jsonb_build_object('ok', false, 'code', 'UNEXPECTED_FINANCIAL_DETAIL');
  end if;
  if p_financial_disposition = 'partial_refund' and (
       p_financial_amount is null or p_financial_amount <= 0
       or upper(coalesce(p_financial_currency, '')) !~ '^[A-Z]{3}$'
     ) then
    return jsonb_build_object('ok', false, 'code', 'PARTIAL_REFUND_DETAIL_REQUIRED');
  end if;
  if p_financial_disposition in (
       'capture_existing_hold', 'release_existing_hold',
       'full_refund', 'no_refund_due', 'externally_settled'
     ) and (p_financial_amount is not null or p_financial_currency is not null) then
    return jsonb_build_object('ok', false, 'code', 'UNEXPECTED_FINANCIAL_AMOUNT');
  end if;
  if p_financial_disposition <> 'externally_settled'
     and p_external_settlement_reference is not null then
    return jsonb_build_object('ok', false, 'code', 'UNEXPECTED_SETTLEMENT_REFERENCE');
  end if;
  if p_financial_disposition = 'externally_settled'
     and nullif(btrim(p_external_settlement_reference), '') is null then
    return jsonb_build_object('ok', false, 'code', 'SETTLEMENT_REFERENCE_REQUIRED');
  end if;

  select array_agg(distinct observation_id order by observation_id)
    into v_evidence_ids
    from unnest(coalesce(p_evidence_observation_ids, array[]::uuid[]))
      as evidence_input(observation_id);
  if coalesce(cardinality(v_evidence_ids), 0) = 0 then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_REQUIRED');
  end if;
  select array_agg(distinct lower(btrim(code)) order by lower(btrim(code)))
    into v_confirmation_codes
    from unnest(coalesce(p_confirmation_codes, array[]::text[]))
      as confirmation_input(code)
   where nullif(btrim(code), '') is not null;
  v_confirmation_codes := coalesce(v_confirmation_codes, array[]::text[]);
  if exists (
    select 1 from unnest(v_confirmation_codes) as confirmation(code)
     where confirmation.code not in (
       'confirm_supplier_outcome',
       'confirm_held_nonissuance_basis',
       'confirm_terminal_correction',
       'confirm_supplier_identity_exception',
       'confirm_incomplete_evidence_exception',
       'confirm_legacy_review_path',
       'confirm_financial_disposition',
       'confirm_fee_or_no_refund',
       'confirm_external_settlement',
       'confirm_historical_repair',
       'confirm_manual_resolution_basis'
     )
  ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CONFIRMATION_CODE');
  end if;

  -- Global write lock order begins with booking, followed by case. Proposal
  -- writes no operation or money rows.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select reconciliation_case.* into v_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;
  if v_case.state not in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     ) then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN');
  end if;
  if v_case.approved_at is not null then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_PROPOSAL_LOCKED');
  end if;

  if (select count(*) from public.booking_reconciliation_observations observation
       where observation.reconciliation_case_id = p_case_id
         and observation.id = any(v_evidence_ids))
     <> cardinality(v_evidence_ids) then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_CASE_MISMATCH');
  end if;
  if not exists (
    select 1 from public.booking_reconciliation_observations observation
     where observation.reconciliation_case_id = p_case_id
       and observation.id = any(v_evidence_ids)
       and observation.observed_at >= clock_timestamp() - interval '5 minutes'
  ) then
    return jsonb_build_object('ok', false, 'code', 'FRESH_EVIDENCE_REQUIRED');
  end if;

  select
    coalesce(bool_or(
      coalesce((observation.normalized_facts
        #>> '{validation,identityMatches}')::boolean, false) is not true
    ) filter (where observation.normalized_facts->>'action'
      = 'supplier_evidence_read'), false),
    coalesce(bool_or(
      coalesce((observation.normalized_facts
        #>> '{validation,valid}')::boolean, false) is not true
      or coalesce((observation.normalized_facts
        #>> '{validation,complete}')::boolean, false) is not true
      or coalesce((observation.normalized_facts
        #>> '{validation,fresh}')::boolean, false) is not true
    ) filter (where observation.normalized_facts->>'action'
      = 'supplier_evidence_read'), false)
    into v_has_identity_exception, v_has_incomplete_exception
    from public.booking_reconciliation_observations observation
   where observation.reconciliation_case_id = p_case_id
     and observation.id = any(v_evidence_ids);

  v_target_status := case p_proposed_outcome
    when 'ticketed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'held_not_ticketed' then 'on-hold'
    else null
  end;
  if v_target_status is not null
     and v_booking.status in ('confirmed', 'cancelled')
     and v_target_status <> v_booking.status then
    v_risk_flags := array_append(v_risk_flags, 'terminal_correction');
    v_required_codes := array_append(
      v_required_codes, 'confirm_terminal_correction'
    );
  end if;
  if p_financial_disposition <> 'none' then
    v_risk_flags := array_append(v_risk_flags, 'money_movement');
    v_required_codes := array_append(
      v_required_codes, 'confirm_financial_disposition'
    );
  end if;
  if p_financial_disposition in ('partial_refund', 'no_refund_due') then
    v_risk_flags := array_append(v_risk_flags, 'fee_or_no_refund');
    v_required_codes := array_append(
      v_required_codes, 'confirm_fee_or_no_refund'
    );
  end if;
  if p_financial_disposition = 'externally_settled' then
    v_risk_flags := array_append(v_risk_flags, 'external_settlement');
    v_required_codes := array_append(
      v_required_codes, 'confirm_external_settlement'
    );
  end if;
  if v_case.case_type in ('legacy_review', 'historical_inconsistency')
     or p_proposed_outcome = 'historical_repair' then
    v_risk_flags := array_append(v_risk_flags, 'historical_repair');
    v_required_codes := array_append(
      v_required_codes, 'confirm_historical_repair'
    );
  end if;
  if p_domain in ('supplier_truth', 'combined_supplier_financial') then
    v_required_codes := array_append(
      v_required_codes, 'confirm_supplier_outcome'
    );
  end if;
  if p_proposed_outcome = 'held_not_ticketed' then
    v_required_codes := array_append(
      v_required_codes, 'confirm_held_nonissuance_basis'
    );
    v_required_codes := array_append(
      v_required_codes, 'confirm_manual_resolution_basis'
    );
  end if;
  if v_case.case_type = 'legacy_review' then
    v_required_codes := array_append(
      v_required_codes, 'confirm_legacy_review_path'
    );
  end if;
  if v_has_identity_exception then
    v_required_codes := array_append(
      v_required_codes, 'confirm_supplier_identity_exception'
    );
  end if;
  if v_has_incomplete_exception then
    v_required_codes := array_append(
      v_required_codes, 'confirm_incomplete_evidence_exception'
    );
  end if;
  select array_agg(distinct risk order by risk) into v_risk_flags
    from unnest(v_risk_flags) as risks(risk);
  select array_agg(distinct code order by code) into v_required_codes
    from unnest(v_required_codes) as required(code);
  v_risk_flags := coalesce(v_risk_flags, array[]::text[]);
  v_required_codes := coalesce(v_required_codes, array[]::text[]);
  if not (v_confirmation_codes @> v_required_codes) then
    return jsonb_build_object(
      'ok', false,
      'code', 'REQUIRED_CONFIRMATION_MISSING',
      'requiredConfirmationCodes', to_jsonb(v_required_codes)
    );
  end if;
  v_maker_checker := cardinality(v_risk_flags) > 0;

  v_proposal := jsonb_build_object(
    'version', 1,
    'requestKey', p_request_key,
    'domain', p_domain,
    'proposedOutcome', p_proposed_outcome,
    'riskFlags', to_jsonb(v_risk_flags),
    'makerCheckerRequired', v_maker_checker,
    'confirmationCodes', to_jsonb(v_confirmation_codes),
    'evidenceObservationIds', to_jsonb(v_evidence_ids),
    'expectedBookingStatus', v_booking.status,
    'expectedPaymentState', v_booking.payment_state,
    'financialDisposition', p_financial_disposition,
    'financialAmount', p_financial_amount,
    'financialCurrency', case when p_financial_currency is null
      then null else upper(p_financial_currency) end,
    'externalSettlementReference', p_external_settlement_reference,
    'reason', p_reason,
    'statusMutationAuthorized', false,
    'walletMutationAuthorized', false
  );
  v_proposal_hash := encode(
    sha256(convert_to(v_proposal::text, 'UTF8')),
    'hex'
  );

  if v_case.proposal->>'requestKey' = p_request_key then
    if v_case.proposal_hash = v_proposal_hash
       and v_case.proposed_by_user_id = p_actor_user_id then
      return jsonb_build_object(
        'ok', true, 'replay', true,
        'caseId', p_case_id,
        'caseVersion', v_case.version,
        'proposalHash', v_case.proposal_hash,
        'makerCheckerRequired', v_maker_checker,
        'statusMutation', false,
        'walletMutation', false
      );
    end if;
    raise exception 'proposal request identity mismatch' using errcode = '22023';
  end if;
  if v_case.version <> p_expected_case_version then
    return jsonb_build_object(
      'ok', false, 'code', 'CASE_VERSION_CONFLICT',
      'caseVersion', v_case.version
    );
  end if;

  update public.booking_reconciliation_cases
     set state = case when v_maker_checker
           then 'awaiting_approval' else 'assigned' end,
         proposed_outcome = p_proposed_outcome,
         proposal = v_proposal,
         proposal_hash = v_proposal_hash,
         proposed_by_user_id = p_actor_user_id,
         proposed_at = clock_timestamp(),
         approved_by_user_id = null,
         approved_at = null,
         rejected_by_user_id = null,
         rejected_at = null,
         rejection_reason = null,
         financial_disposition = p_financial_disposition,
         financial_amount = p_financial_amount,
         financial_currency = case when p_financial_currency is null
           then null else upper(p_financial_currency) end,
         external_settlement_reference = p_external_settlement_reference,
         version = version + 1
   where id = p_case_id
   returning version into p_expected_case_version;

  return jsonb_build_object(
    'ok', true, 'replay', false,
    'caseId', p_case_id,
    'caseVersion', p_expected_case_version,
    'proposalHash', v_proposal_hash,
    'riskFlags', to_jsonb(v_risk_flags),
    'makerCheckerRequired', v_maker_checker,
    'statusMutation', false,
    'walletMutation', false
  );
end;
$$;

create or replace function public.approve_booking_reconciliation_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_new_version integer;
begin
  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin') then
    return jsonb_build_object('ok', false, 'code', 'APPROVAL_FORBIDDEN');
  end if;
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select reconciliation_case.* into v_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;
  if v_case.approved_at is not null then
    if v_case.approved_by_user_id = p_actor_user_id
       and v_case.proposal_hash = p_proposal_hash then
      return jsonb_build_object(
        'ok', true, 'replay', true,
        'caseId', p_case_id,
        'caseVersion', v_case.version,
        'proposalHash', v_case.proposal_hash
      );
    end if;
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_ALREADY_APPROVED');
  end if;
  if v_case.state <> 'awaiting_approval'
     or v_case.proposal_hash is null
     or v_case.proposal_hash <> p_proposal_hash
     or coalesce((v_case.proposal->>'makerCheckerRequired')::boolean, false)
        is not true then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_NOT_APPROVABLE');
  end if;
  if v_case.version <> p_expected_case_version then
    return jsonb_build_object(
      'ok', false, 'code', 'CASE_VERSION_CONFLICT',
      'caseVersion', v_case.version
    );
  end if;
  if v_case.proposed_by_user_id = p_actor_user_id then
    return jsonb_build_object('ok', false, 'code', 'SELF_APPROVAL_FORBIDDEN');
  end if;

  update public.booking_reconciliation_cases
     set approved_by_user_id = p_actor_user_id,
         approved_at = clock_timestamp(),
         version = version + 1
   where id = p_case_id
   returning version into v_new_version;
  return jsonb_build_object(
    'ok', true, 'replay', false,
    'caseId', p_case_id,
    'caseVersion', v_new_version,
    'proposalHash', p_proposal_hash
  );
end;
$$;

create or replace function public.reject_booking_reconciliation_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_rejection_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_new_version integer;
begin
  if nullif(btrim(p_rejection_reason), '') is null
     or char_length(p_rejection_reason) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'REJECTION_REASON_REQUIRED');
  end if;
  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin') then
    return jsonb_build_object('ok', false, 'code', 'REJECTION_FORBIDDEN');
  end if;
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select reconciliation_case.* into v_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;
  if v_case.rejected_at is not null then
    if v_case.rejected_by_user_id = p_actor_user_id
       and v_case.proposal_hash = p_proposal_hash
       and v_case.rejection_reason = p_rejection_reason then
      return jsonb_build_object(
        'ok', true, 'replay', true,
        'caseId', p_case_id,
        'caseVersion', v_case.version,
        'proposalHash', v_case.proposal_hash
      );
    end if;
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_ALREADY_REJECTED');
  end if;
  if v_case.proposal_hash is null
     or v_case.proposal_hash <> p_proposal_hash
     or v_case.approved_at is not null then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_NOT_REJECTABLE');
  end if;
  if v_case.version <> p_expected_case_version then
    return jsonb_build_object(
      'ok', false, 'code', 'CASE_VERSION_CONFLICT',
      'caseVersion', v_case.version
    );
  end if;

  update public.booking_reconciliation_cases
     set state = 'assigned',
         rejected_by_user_id = p_actor_user_id,
         rejected_at = clock_timestamp(),
         rejection_reason = p_rejection_reason,
         approved_by_user_id = null,
         approved_at = null,
         version = version + 1
   where id = p_case_id
   returning version into v_new_version;
  return jsonb_build_object(
    'ok', true, 'replay', false,
    'caseId', p_case_id,
    'caseVersion', v_new_version,
    'proposalHash', p_proposal_hash
  );
end;
$$;

revoke all on function public.propose_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text, text, text,
  bigint, text, text, uuid[], text[], text
) from public, anon, authenticated;
revoke all on function public.approve_booking_reconciliation_v1(
  uuid, uuid, integer, text, text
) from public, anon, authenticated;
revoke all on function public.reject_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text
) from public, anon, authenticated;
grant execute on function public.propose_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text, text, text,
  bigint, text, text, uuid[], text[], text
) to service_role;
grant execute on function public.approve_booking_reconciliation_v1(
  uuid, uuid, integer, text, text
) to service_role;
grant execute on function public.reject_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.propose_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text, text, text,
  bigint, text, text, uuid[], text[], text
) is
  'Creates a case-bound, evidence-linked, payload-fingerprinted reconciliation proposal. High-risk flags and required confirmations are derived server-side; no status or money changes.';
comment on function public.approve_booking_reconciliation_v1(
  uuid, uuid, integer, text, text
) is
  'Approves an unchanged high-risk proposal only for a different Admin/Super Admin maker-checker actor. It does not execute the proposal.';
comment on function public.reject_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text
) is
  'Rejects an unchanged proposal with a recorded reason. It does not execute or mutate booking/wallet truth.';


-- SOURCE: 0051_booking_reconciliation_resolution_contracts.sql
-- Fail-closed, outcome-specific reconciliation execution contracts.
--
-- These RPCs deliberately validate an approved proposal but do not yet mutate
-- booking, operation, wallet, ledger, lifecycle-event, or notification state.
-- Later Phase 5 migrations replace each exact outcome body with its atomic
-- implementation. There is intentionally no generic status/resolution RPC.

create or replace function public.booking_reconciliation_resolution_contract_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_execution_request_key text,
  p_resolution_kind text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_case_operation_id uuid;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_maker_checker boolean;
  v_terminal_correction boolean;
  v_historical_repair boolean;
begin
  if p_booking_id is null or p_case_id is null
     or p_expected_case_version is null or p_expected_case_version < 1
     or p_proposal_hash !~ '^[a-f0-9]{64}$'
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_execution_request_key), '') is null
     or char_length(p_execution_request_key) > 220
     or p_resolution_kind not in (
       'ticketed', 'nonissuance', 'cancelled',
       'financial', 'terminal_correction', 'historical_repair'
     ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_RESOLUTION_CONTRACT');
  end if;

  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin') then
    return jsonb_build_object('ok', false, 'code', 'EXECUTION_FORBIDDEN');
  end if;

  -- Global reconciliation lock order is booking -> linked operation -> case
  -- -> reservation -> wallet owner -> currency account. The preliminary case
  -- read discovers the immutable operation identity without taking a lock;
  -- the locked case row must still contain that exact identity.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select reconciliation_case.operation_id into v_case_operation_id
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;
  if v_case_operation_id is not null then
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_case_operation_id
       and operation.booking_id = p_booking_id
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'CASE_OPERATION_MISMATCH');
    end if;
  end if;
  select reconciliation_case.* into v_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id
   for update;
  if v_case.operation_id is distinct from v_case_operation_id then
    return jsonb_build_object('ok', false, 'code', 'CASE_OPERATION_CHANGED');
  end if;
  if v_case.state in ('resolved', 'closed_no_change')
     or v_case.resolved_at is not null then
    if v_case.state = 'resolved'
       and v_case.proposal_hash = p_proposal_hash
       and v_case.resolution->>'executionRequestKey' = p_execution_request_key
       and v_case.resolution->>'resolutionKind' = p_resolution_kind then
      return coalesce(v_case.resolution->'result', '{}'::jsonb)
        || jsonb_build_object(
          'ok', true,
          'replay', true,
          'caseId', v_case.id,
          'caseVersion', v_case.version,
          'proposalHash', v_case.proposal_hash,
          'resolutionKind', p_resolution_kind
        );
    end if;
    return jsonb_build_object('ok', false, 'code', 'CASE_ALREADY_RESOLVED');
  end if;

  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = p_booking_id
      or (reservation.booking_id is null
        and reservation.booking_attempt_id = v_booking.attempt_id)
   order by reservation.booking_id nulls last
   limit 1
   for update;
  if found then
    select wallet.* into v_wallet
      from public.wallets wallet
      join public.wallet_accounts account on account.wallet_id = wallet.id
     where account.id = v_reservation.wallet_account_id
     for update of wallet;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
    end if;
    select account.* into v_account
      from public.wallet_accounts account
     where account.id = v_reservation.wallet_account_id
       and account.wallet_id = v_wallet.id
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
    end if;
  end if;

  if v_case.rejected_at is not null then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_REJECTED');
  end if;
  if v_case.version <> p_expected_case_version then
    return jsonb_build_object(
      'ok', false, 'code', 'CASE_VERSION_CONFLICT',
      'caseVersion', v_case.version
    );
  end if;
  if v_case.proposal_hash is null
     or v_case.proposal_hash <> p_proposal_hash
     or v_case.proposal->>'version' <> '1' then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_CHANGED');
  end if;
  if v_case.proposal->>'expectedBookingStatus' is distinct from v_booking.status
     or v_case.proposal->>'expectedPaymentState'
        is distinct from v_booking.payment_state then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_STATE_CHANGED');
  end if;

  v_maker_checker := coalesce(
    (v_case.proposal->>'makerCheckerRequired')::boolean,
    false
  );
  if v_maker_checker then
    if v_case.state <> 'awaiting_approval'
       or v_case.approved_by_user_id is null
       or v_case.approved_at is null
       or v_case.approved_by_user_id = v_case.proposed_by_user_id then
      return jsonb_build_object('ok', false, 'code', 'INDEPENDENT_APPROVAL_REQUIRED');
    end if;
  elsif v_case.state <> 'assigned' then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_NOT_EXECUTABLE');
  end if;

  if jsonb_typeof(v_case.proposal->'evidenceObservationIds') <> 'array'
     or jsonb_array_length(v_case.proposal->'evidenceObservationIds') = 0 then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_REQUIRED');
  end if;
  if exists (
    select 1
      from jsonb_array_elements_text(
        v_case.proposal->'evidenceObservationIds'
      ) evidence(observation_id)
      left join public.booking_reconciliation_observations observation
        on observation.id = evidence.observation_id::uuid
       and observation.reconciliation_case_id = v_case.id
     where observation.id is null
        or observation.observed_at < clock_timestamp() - interval '5 minutes'
  ) then
    return jsonb_build_object('ok', false, 'code', 'FRESH_CASE_EVIDENCE_REQUIRED');
  end if;

  v_terminal_correction := coalesce(
    v_case.proposal->'riskFlags' @> '["terminal_correction"]'::jsonb,
    false
  );
  v_historical_repair := coalesce(
    v_case.proposal->'riskFlags' @> '["historical_repair"]'::jsonb,
    false
  );
  if p_resolution_kind = 'ticketed'
     and (v_case.proposed_outcome <> 'ticketed'
       or v_terminal_correction or v_historical_repair) then
    return jsonb_build_object('ok', false, 'code', 'OUTCOME_CONTRACT_MISMATCH');
  elsif p_resolution_kind = 'nonissuance'
     and (v_case.proposed_outcome <> 'held_not_ticketed'
       or v_terminal_correction or v_historical_repair) then
    return jsonb_build_object('ok', false, 'code', 'OUTCOME_CONTRACT_MISMATCH');
  elsif p_resolution_kind = 'cancelled'
     and (v_case.proposed_outcome <> 'cancelled'
       or v_terminal_correction or v_historical_repair) then
    return jsonb_build_object('ok', false, 'code', 'OUTCOME_CONTRACT_MISMATCH');
  elsif p_resolution_kind = 'financial'
     and (v_case.proposed_outcome <> 'financial_only'
       or v_terminal_correction or v_historical_repair) then
    return jsonb_build_object('ok', false, 'code', 'OUTCOME_CONTRACT_MISMATCH');
  elsif p_resolution_kind = 'terminal_correction'
     and (not v_terminal_correction or v_historical_repair) then
    return jsonb_build_object('ok', false, 'code', 'OUTCOME_CONTRACT_MISMATCH');
  elsif p_resolution_kind = 'historical_repair'
     and not (
       v_historical_repair or v_case.proposed_outcome = 'historical_repair'
     ) then
    return jsonb_build_object('ok', false, 'code', 'OUTCOME_CONTRACT_MISMATCH');
  end if;
  if v_case.financial_disposition = 'manual_adjustment_required' then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_ADJUSTMENT_REQUIRED');
  end if;

  return jsonb_build_object(
    'ok', true,
    'contractValidated', true,
    'executionEnabled', false,
    'resolutionKind', p_resolution_kind,
    'executionRequestKey', p_execution_request_key,
    'actorRole', v_actor_role,
    'bookingId', v_booking.id,
    'caseId', v_case.id,
    'caseVersion', v_case.version,
    'operationId', v_case.operation_id,
    'reservationId', v_reservation.id,
    'walletId', v_wallet.id,
    'walletAccountId', v_account.id,
    'proposalHash', v_case.proposal_hash,
    'proposedOutcome', v_case.proposed_outcome,
    'financialDisposition', v_case.financial_disposition,
    'makerCheckerRequired', v_maker_checker
  );
end;
$$;

create or replace function public.resolve_booking_reconciliation_ticketed_v1(
  p_booking_id uuid, p_case_id uuid, p_expected_case_version integer,
  p_proposal_hash text, p_actor_user_id text, p_execution_request_key text
)
returns jsonb language sql security definer set search_path = public
as $$
  select case when coalesce((contract.result->>'ok')::boolean, false)
    then contract.result || jsonb_build_object(
      'ok', false, 'code', 'RESOLUTION_EXECUTION_NOT_ENABLED'
    )
    else contract.result
  end
  from (select public.booking_reconciliation_resolution_contract_v1(
    p_booking_id, p_case_id, p_expected_case_version, p_proposal_hash,
    p_actor_user_id, p_execution_request_key, 'ticketed'
  ) as result) contract;
$$;

