  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.execute_booking_captured_cancellation_v1(
  uuid, uuid, integer, text, text, text, text
) is
  'Private case-bound captured-cancellation engine. Only exact disposition wrappers can call it; service clients cannot select a generic mode.';
comment on function public.resolve_booking_reconciliation_cancelled_full_refund_v1(
  uuid, uuid, integer, text, text, text
) is 'Refunds the entire remaining captured cancellation balance through one approved, idempotent case resolution.';
comment on function public.resolve_booking_reconciliation_cancelled_partial_refund_v1(
  uuid, uuid, integer, text, text, text
) is 'Refunds the approved partial amount and records the retained fee through one approved, idempotent case resolution.';
comment on function public.resolve_booking_reconciliation_cancelled_no_refund_v1(
  uuid, uuid, integer, text, text, text
) is 'Closes an approved no-refund-due cancellation disposition without wallet mutation while preserving explicit captured financial truth.';
comment on function public.resolve_booking_reconciliation_cancelled_external_settlement_v1(
  uuid, uuid, integer, text, text, text
) is 'Closes an approved externally settled cancellation disposition without fabricating a wallet refund; the external reference remains case-bound.';


-- SOURCE: 0057_booking_reconciliation_terminal_corrections.sql
-- Terminal corrections are not generic status changes. A Confirmed ->
-- Cancelled correction reuses the four exact captured-cancellation financial
-- consequences after the private engine selects the terminal-correction
-- contract from the server-derived risk flag. This migration adds the reverse
-- Cancelled -> Confirmed branch for an already-consistent captured reservation.
-- It moves no money and rejects every unpaid, held, released, refunded, or
-- otherwise financially inconsistent booking.

create or replace function public.resolve_booking_reconciliation_terminal_confirmed_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_execution_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_contract jsonb;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_operation public.booking_operations;
  v_reservation public.wallet_reservations;
  v_account public.wallet_accounts;
  v_evidence public.booking_reconciliation_observations;
  v_ticket_code_ref text;
  v_ticket_numbers jsonb;
  v_supplier_pnr text;
  v_airlines_pnr jsonb;
  v_supplier_status text;
  v_issued_at timestamptz;
  v_event_id bigint;
  v_occurrence_number integer;
  v_from_lifecycle text;
  v_resolution_result jsonb;
begin
  v_contract := public.booking_reconciliation_resolution_contract_v1(
    p_booking_id, p_case_id, p_expected_case_version, p_proposal_hash,
    p_actor_user_id, p_execution_request_key, 'terminal_correction'
  );
  if coalesce((v_contract->>'ok')::boolean, false) is not true
     or coalesce((v_contract->>'replay')::boolean, false) then
    return v_contract;
  end if;

  select * into strict v_booking
    from public.flight_bookings where id = p_booking_id;
  select * into strict v_case
    from public.booking_reconciliation_cases where id = p_case_id;
  if v_case.proposed_outcome <> 'ticketed'
     or v_case.financial_disposition <> 'none' then
    return jsonb_build_object(
      'ok', false, 'code', 'TERMINAL_CONFIRMED_OUTCOME_MISMATCH'
    );
  end if;
  if v_booking.status <> 'cancelled'
     or v_booking.payment_state <> 'captured'
     or v_booking.captured_amount <= 0
     or v_booking.refunded_amount <> 0
     or v_booking.charged_wallet_account_id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'TERMINAL_CONFIRMED_CAPTURED_STATE_REQUIRED'
    );
  end if;
  if v_case.operation_id is not null then
    select * into v_operation
      from public.booking_operations where id = v_case.operation_id;
    if v_operation.state <> 'needs_reconciliation' then
      return jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_RECONCILING');
    end if;
  end if;
  select * into v_reservation
    from public.wallet_reservations
   where id = (v_contract->>'reservationId')::uuid;
  if not found
     or v_reservation.state <> 'captured'
     or v_reservation.booking_id is distinct from p_booking_id
     or v_reservation.amount <> v_booking.captured_amount
     or v_reservation.currency <> v_booking.currency then
    return jsonb_build_object(
      'ok', false, 'code', 'TERMINAL_CONFIRMED_RESERVATION_MISMATCH'
    );
  end if;
  select * into v_account
    from public.wallet_accounts where id = v_reservation.wallet_account_id;
  if not found
     or v_account.id is distinct from (v_contract->>'walletAccountId')::uuid
     or v_account.id is distinct from v_booking.charged_wallet_account_id
     or v_account.currency <> v_booking.currency then
    return jsonb_build_object(
      'ok', false, 'code', 'TERMINAL_CONFIRMED_ACCOUNT_MISMATCH'
    );
  end if;

  select observation.* into v_evidence
    from jsonb_array_elements_text(
      v_case.proposal->'evidenceObservationIds'
    ) evidence_id(id)
    join public.booking_reconciliation_observations observation
      on observation.id = evidence_id.id::uuid
     and observation.reconciliation_case_id = v_case.id
   where observation.normalized_facts->>'requestedPurpose' = 'ticketed'
     and observation.normalized_facts
       #>> '{validation,authoritativeFor}' = 'ticketed'
     and observation.normalized_facts #>> '{validation,valid}' = 'true'
     and observation.normalized_facts #>> '{validation,complete}' = 'true'
     and observation.normalized_facts #>> '{validation,fresh}' = 'true'
     and observation.normalized_facts
       #>> '{validation,identityMatches}' = 'true'
     and observation.normalized_facts
       #>> '{evidence,airTicketing,source}' = 'air-ticketing-details'
   order by observation.observed_at desc, observation.id desc
   limit 1;
  if not found then
    return jsonb_build_object(
      'ok', false, 'code', 'AUTHORITATIVE_TICKET_EVIDENCE_REQUIRED'
    );
  end if;

  v_ticket_code_ref := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,ticketCodeRef}'), '');
  v_ticket_numbers := v_evidence.normalized_facts
    #> '{evidence,airTicketing,facts,ticketNumbers}';
  if v_ticket_code_ref is null
     or jsonb_typeof(v_ticket_numbers) <> 'array'
     or jsonb_array_length(v_ticket_numbers) = 0
     or exists (
       select 1 from jsonb_array_elements(v_ticket_numbers) ticket(value)
        where jsonb_typeof(ticket.value) <> 'string'
           or nullif(btrim(ticket.value #>> '{}'), '') is null
     ) then
    return jsonb_build_object('ok', false, 'code', 'TICKET_EVIDENCE_INCOMPLETE');
  end if;
  v_supplier_pnr := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,pnr}'), '');
  v_airlines_pnr := v_evidence.normalized_facts
    #> '{evidence,airTicketing,facts,airlinesPnr}';
  v_supplier_status := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,supplierStatus}'), '');
  begin
    v_issued_at := nullif(v_evidence.normalized_facts
      #>> '{evidence,airTicketing,facts,issuedAt}', '')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ISSUED_TIMESTAMP');
  end;
  v_issued_at := coalesce(v_issued_at, v_evidence.observed_at);
  if v_issued_at > v_evidence.observed_at + interval '1 minute' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ISSUED_TIMESTAMP');
  end if;

  v_from_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  update public.flight_bookings
     set status = 'confirmed',
         issued_by_user_id = p_actor_user_id,
         issued_at = coalesce(issued_at, v_issued_at),
         pnr = coalesce(v_supplier_pnr, pnr),
         airlines_pnr = case
           when jsonb_typeof(v_airlines_pnr) = 'array'
             and jsonb_array_length(v_airlines_pnr) > 0
             then v_airlines_pnr else airlines_pnr end,
         booking_status = coalesce(v_supplier_status, 'Confirmed'),
         ticket_code_ref = v_ticket_code_ref,
         ticket_numbers = v_ticket_numbers,
         cancelled_at = null,
         cancelled_by = null,
         cancel_reason = null,
         active_operation_id = null,
         operation_kind = null,
         operation_reason = null,
         operation_request_id = null,
         operation_actor_user_id = null,
         operation_started_at = null,
         operation_prior_status = null
   where id = v_booking.id;
  if v_case.operation_id is not null then
    update public.booking_operations
       set state = 'succeeded',
           completed_at = clock_timestamp(),
           error_code = null,
           error_message = null,
           supplier_evidence = supplier_evidence || jsonb_build_object(
             'reconciliationResolution', jsonb_build_object(
               'caseId', v_case.id,
               'outcome', 'ticketed',
               'terminalCorrection', true,
               'evidenceObservationId', v_evidence.id
             )
           )
     where id = v_case.operation_id;
  end if;

  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'confirmed';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle, 'confirmed',
    v_booking.status, 'confirmed', v_booking.operation_kind,
    v_booking.operation_reason, p_actor_user_id,
    'TerminalCorrectionConfirmed',
    jsonb_build_object(
      'evidenceObservationId', v_evidence.id,
      'ticketCodeRefPresent', true,
      'ticketCount', jsonb_array_length(v_ticket_numbers)
    ),
    p_execution_request_key || ':terminal-confirmed', v_case.operation_id,
    v_case.id, v_occurrence_number, v_issued_at, clock_timestamp(),
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'confirmed',
      'paymentState', 'captured',
      'terminalCorrection', true,
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'reconciliationCaseId', v_case.id
    ), 1
  ) returning id into v_event_id;

  v_resolution_result := jsonb_build_object(
    'bookingStatus', 'confirmed',
    'paymentState', 'captured',
    'financialDisposition', 'none',
    'reservationId', v_reservation.id,
    'walletAccountId', v_account.id,
    'lifecycleEventId', v_event_id,
    'capturedAmount', v_booking.captured_amount,
    'currency', v_booking.currency,
    'previousCancelledAt', v_booking.cancelled_at,
    'previousCancelledBy', v_booking.cancelled_by,
    'previousCancelReason', v_booking.cancel_reason,
    'walletMutation', false,
    'reservationMutation', false,
    'ledgerMutation', false,
    'availableBalance', v_account.available_balance,
    'holdBalance', v_account.hold_balance
  );
  update public.booking_reconciliation_cases
     set state = 'resolved',
         resolution_outcome = 'terminal_corrected_confirmed',
         resolution = jsonb_build_object(
           'version', 1,
           'executionRequestKey', p_execution_request_key,
           'proposalHash', v_case.proposal_hash,
           'resolutionKind', 'terminal_correction',
           'financialDisposition', 'none',
           'executedByRole', v_contract->>'actorRole',
           'evidenceObservationIds', v_case.proposal->'evidenceObservationIds',
           'result', v_resolution_result
         ),
         resolution_reason = v_case.proposal->>'reason',
         resolved_by_user_id = p_actor_user_id,
         resolved_at = clock_timestamp(),
         closed_at = clock_timestamp(),
         version = version + 1
   where id = v_case.id;

  return v_resolution_result || jsonb_build_object(
    'ok', true, 'replay', false,
    'caseId', v_case.id,
    'caseVersion', v_case.version + 1,
    'resolutionKind', 'terminal_correction'
  );
end;
$$;

revoke all on function public.resolve_booking_reconciliation_terminal_confirmed_v1(
  uuid, uuid, integer, text, text, text
) from public, anon, authenticated;
grant execute on function public.resolve_booking_reconciliation_terminal_confirmed_v1(
  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.resolve_booking_reconciliation_terminal_confirmed_v1(
  uuid, uuid, integer, text, text, text
) is
  'Corrects Cancelled to Confirmed only when fresh authoritative ticket evidence and an already captured, unrefunded, identity-matching reservation agree. It moves no money and rejects every other financial state.';


-- SOURCE: 0058_wallet_reconciliation_release_guard.sql
-- The compatibility release RPC remains available for ordinary definitive
-- supplier failures, but it must never resolve an owned uncertainty. Exact
-- non-issuance/cancellation reconciliation RPCs perform their own approved,
-- case-bound releases and do not call this function.

create or replace function public.wallet_release_reservation(
  p_booking_id uuid,
  p_booking_attempt_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_attempt public.booking_attempts;
  v_operation public.booking_operations;
  v_case_id uuid;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_booking_ref text;
  v_available_before bigint;
  v_hold_before bigint;
begin
  if (p_booking_id is null) = (p_booking_attempt_id is null) then
    raise exception 'exactly one reservation subject is required'
      using errcode = '22023';
  end if;
  if nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_actor_role), '') is null
     or nullif(btrim(p_idempotency_key), '') is null
     or char_length(p_idempotency_key) > 220 then
    raise exception 'invalid wallet release request' using errcode = '22023';
  end if;

  -- Booking/attempt ownership is locked before case/reservation/wallet rows.
  -- This shares the reconciliation serialization prefix and closes the race
  -- between opening a case and a generic release.
  if p_booking_id is not null then
    select booking.* into v_booking
      from public.flight_bookings booking
     where booking.id = p_booking_id
     for update;
    if found then
      v_booking_ref := v_booking.public_ref;
      if v_booking.active_operation_id is not null then
        select operation.* into v_operation
          from public.booking_operations operation
         where operation.id = v_booking.active_operation_id
           and operation.booking_id = v_booking.id
         for update;
      end if;
      if v_booking.payment_state = 'reconciliation'
         or v_booking.operation_kind = 'reconciliation'
         or v_booking.operation_reason in (
           'ticketing_reconciliation', 'cancellation_reconciliation',
           'legacy_reconciliation', 'terminal_state_conflict',
           'supplier_outcome_unknown'
         )
         or v_operation.state = 'needs_reconciliation' then
        return jsonb_build_object(
          'ok', false, 'code', 'RECONCILIATION_REQUIRED'
        );
      end if;
    end if;
    select reconciliation_case.id into v_case_id
      from public.booking_reconciliation_cases reconciliation_case
     where reconciliation_case.subject_booking_id = p_booking_id
       and reconciliation_case.state not in ('resolved', 'closed_no_change')
     limit 1
     for update;
  else
    select attempt.* into v_attempt
      from public.booking_attempts attempt
     where attempt.id = p_booking_attempt_id
     for update;
    if found and v_attempt.state = 'unknown' then
      return jsonb_build_object(
        'ok', false, 'code', 'RECONCILIATION_REQUIRED'
      );
    end if;
    select reconciliation_case.id into v_case_id
      from public.booking_reconciliation_cases reconciliation_case
     where reconciliation_case.subject_booking_attempt_id = p_booking_attempt_id
       and reconciliation_case.state not in ('resolved', 'closed_no_change')
     limit 1
     for update;
  end if;
  if v_case_id is not null then
    return jsonb_build_object(
      'ok', false, 'code', 'RECONCILIATION_REQUIRED'
    );
  end if;

  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where (p_booking_id is not null and reservation.booking_id = p_booking_id)
      or (p_booking_attempt_id is not null
        and reservation.booking_attempt_id = p_booking_attempt_id)
   for update;
  if not found then
    return jsonb_build_object('ok', true, 'replay', true);
  end if;
  if v_reservation.state = 'released' then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'reservationId', v_reservation.id
    );
  end if;
  if v_reservation.state = 'captured' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;
  if v_reservation.state = 'reconciliation' then
    return jsonb_build_object(
      'ok', false, 'code', 'RECONCILIATION_REQUIRED'
    );
  end if;

  select wallet.* into v_wallet
    from public.wallets wallet
    join public.wallet_accounts account on account.wallet_id = wallet.id
   where account.id = v_reservation.wallet_account_id
   for update of wallet;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id
     and account.wallet_id = v_wallet.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if v_account.currency <> v_reservation.currency then
    return jsonb_build_object('ok', false, 'code', 'WALLET_CURRENCY_MISMATCH');
  end if;
  if v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'HOLD_BALANCE_MISMATCH');
  end if;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts
     set available_balance = available_balance + v_reservation.amount,
         hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;
  update public.wallet_reservations
     set state = 'released',
         released_at = clock_timestamp(),
         release_reason = left(
           coalesce(p_reason, 'Supplier declined issuance'), 1000
         )
   where id = v_reservation.id;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks
  ) values (
    v_account.id, 'hold_release', v_reservation.amount,
    v_reservation.currency, v_available_before,
    v_available_before + v_reservation.amount,
    v_hold_before, v_hold_before - v_reservation.amount,
    p_booking_id, v_booking_ref, v_reservation.id,
    p_idempotency_key || ':release', p_actor_user_id, p_actor_role,
    left(coalesce(p_reason, 'Supplier declined issuance'), 1000)
  );
  if p_booking_id is not null then
    update public.flight_bookings
       set payment_state = 'released'
     where id = p_booking_id and payment_state <> 'captured';
  end if;
  return jsonb_build_object(
    'ok', true,
    'reservationId', v_reservation.id,
    'availableBalance', v_available_before + v_reservation.amount,
    'holdBalance', v_hold_before - v_reservation.amount
  );
end;
$$;

revoke all on function public.wallet_release_reservation(
  uuid, uuid, text, text, text, text
) from public, anon, authenticated;
grant execute on function public.wallet_release_reservation(
  uuid, uuid, text, text, text, text
) to service_role;

comment on function public.wallet_release_reservation(
  uuid, uuid, text, text, text, text
) is
  'Compatibility release for ordinary definitive failures only. Reconciliation state, an unresolved case, an unknown attempt, or a needs-reconciliation operation must use an approved exact case outcome.';


-- SOURCE: 0059_wallet_reconciliation_refund_guard.sql
-- Generic refunds remain available for ordinary, non-reconciliation financial
-- work on an internally consistent captured booking. They cannot resolve a
-- Cancelled/Captured booking, an uncertain operation, or any unresolved case.
-- Those outcomes must use the exact approved case-bound reconciliation RPCs.

create or replace function public.wallet_refund_booking(
  p_booking_id uuid,
  p_amount bigint,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text,
  p_remarks text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case_id uuid;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing public.wallet_ledger_entries;
  v_outstanding bigint;
  v_payment_after text;
  v_event_id bigint;
  v_occurrence_number integer;
begin
  if p_booking_id is null
     or p_amount is null or p_amount <= 0
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_idempotency_key), '') is null
     or char_length(p_idempotency_key) > 220 then
    raise exception 'invalid refund request' using errcode = '22023';
  end if;
  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin', 'staff_account') then
    return jsonb_build_object('ok', false, 'code', 'REFUND_FORBIDDEN');
  end if;

  -- Global mutation order: booking -> operation -> case -> reservation ->
  -- wallet -> account. Ledger entries are immutable and are never locked.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
     and not booking.legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select ledger.* into v_existing
    from public.wallet_ledger_entries ledger
   where ledger.idempotency_key = p_idempotency_key || ':refund';
  if found then
    if v_existing.booking_id is distinct from p_booking_id
       or v_existing.amount <> p_amount
       or v_existing.transaction_type <> 'refund' then
      return jsonb_build_object(
        'ok', false, 'code', 'REFUND_IDEMPOTENCY_CONFLICT'
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'replay', true,
      'availableBalance', v_existing.available_after,
      'refundedAmount', v_booking.refunded_amount,
      'lifecycleEventId', (
        select event.id from public.booking_status_events event
         where event.idempotency_key = p_idempotency_key || ':refund-status'
      )
    );
  end if;
  if v_booking.active_operation_id is not null then
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_booking.active_operation_id
       and operation.booking_id = v_booking.id
     for update;
  end if;
  if v_booking.status <> 'confirmed'
     or v_booking.payment_state = 'reconciliation'
     or v_booking.operation_kind = 'reconciliation'
     or v_booking.operation_reason in (
       'ticketing_reconciliation', 'cancellation_reconciliation',
       'legacy_reconciliation', 'terminal_state_conflict',
       'supplier_outcome_unknown'
     )
     or v_operation.state = 'needs_reconciliation' then
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  end if;
  select reconciliation_case.id into v_case_id
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = p_booking_id
     and reconciliation_case.state not in ('resolved', 'closed_no_change')
   limit 1
   for update;
  if v_case_id is not null then
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  end if;

  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = p_booking_id
   for update;
  if not found
     or v_reservation.state <> 'captured'
     or v_reservation.amount <> v_booking.captured_amount
     or v_reservation.wallet_account_id
        is distinct from v_booking.charged_wallet_account_id
     or v_reservation.currency <> v_booking.currency then
    return jsonb_build_object(
      'ok', false, 'code', 'REFUND_RESERVATION_MISMATCH'
    );
  end if;
  select wallet.* into v_wallet
    from public.wallets wallet
    join public.wallet_accounts account on account.wallet_id = wallet.id
   where account.id = v_reservation.wallet_account_id
   for update of wallet;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id
     and account.wallet_id = v_wallet.id
   for update;
  if not found
     or v_account.currency <> v_reservation.currency then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;

  v_outstanding := v_booking.captured_amount - v_booking.refunded_amount;
  if v_booking.payment_state not in ('captured', 'partially-refunded')
     or p_amount > v_outstanding then
    return jsonb_build_object(
      'ok', false,
      'code', 'REFUND_EXCEEDS_CAPTURE',
      'refundable', greatest(v_outstanding, 0)
    );
  end if;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks
  ) values (
    v_account.id, 'refund', p_amount, v_account.currency,
    v_account.available_balance, v_account.available_balance + p_amount,
    v_account.hold_balance, v_account.hold_balance,
    v_booking.id, v_booking.public_ref, v_reservation.id,
    p_idempotency_key || ':refund', p_actor_user_id, v_actor_role, p_remarks
  );
  update public.wallet_accounts
     set available_balance = available_balance + p_amount
   where id = v_account.id;
  v_payment_after := case
    when v_booking.refunded_amount + p_amount = v_booking.captured_amount
      then 'refunded'
    else 'partially-refunded'
  end;
  update public.flight_bookings
     set refunded_amount = refunded_amount + p_amount,
         payment_state = v_payment_after
   where id = v_booking.id;
  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'confirmed';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, 'confirmed', 'confirmed',
    v_booking.status, v_booking.status, null, null,
    p_actor_user_id, 'WalletRefund',
    jsonb_build_object('refundAmount', p_amount),
    p_idempotency_key || ':refund-status', v_occurrence_number,
    clock_timestamp(), clock_timestamp(),
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'confirmed',
      'paymentState', v_payment_after,
      'financialEvent', 'refund',
      'refundAmount', p_amount,
      'refundedAmount', v_booking.refunded_amount + p_amount,
      'capturedAmount', v_booking.captured_amount,
      'currency', v_booking.currency
    ), 1
  ) returning id into v_event_id;
  return jsonb_build_object(
    'ok', true,
    'availableBalance', v_account.available_balance + p_amount,
    'refundedAmount', v_booking.refunded_amount + p_amount,
    'lifecycleEventId', v_event_id
  );
end;
$$;

revoke all on function public.wallet_refund_booking(
  uuid, bigint, text, text, text, text
) from public, anon, authenticated;
grant execute on function public.wallet_refund_booking(
  uuid, bigint, text, text, text, text
) to service_role;

comment on function public.wallet_refund_booking(
  uuid, bigint, text, text, text, text
) is
  'Ordinary non-reconciliation refund only. Current Accounts/Admin/Super Admin authority, captured reservation identity, and absence of terminal/reconciliation conflict are enforced in the database.';


-- SOURCE: 0060_booking_lifecycle_event_outbox.sql
-- Every new lifecycle occurrence owns one transactional notification intent.
-- The trigger runs inside the event-producing transaction, so a booking,
-- operation, case, wallet ledger, lifecycle event, and outbox either all
-- commit or all roll back. Recipient expansion and sending remain disabled
-- until the Phase 7 worker cutover.

create or replace function public.enqueue_booking_lifecycle_event_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_booking_ref text;
  v_payment_state text;
  v_policy text := 'send';
  v_available_at timestamptz;
  v_grace_expires_at timestamptz;
  v_snapshot jsonb;
begin
  if new.to_lifecycle_status not in (
    'on-hold', 'pending', 'in-progress', 'confirmed',
    'expired', 'unconfirmed', 'cancelled'
  ) then
    raise exception 'unsupported lifecycle notification status'
      using errcode = '23514';
  end if;
  select booking.public_ref, booking.payment_state
    into v_booking_ref, v_payment_state
    from public.flight_bookings booking
   where booking.id = new.booking_id;
  if not found then
    raise exception 'notification booking not found' using errcode = '23503';
  end if;

  -- Ordinary Triplover supplier writes receive the approved 120-second grace
  -- window. Imported manual ticketing and every terminal/financial occurrence
  -- are immediately eligible.
  if new.to_lifecycle_status = 'in-progress'
     and new.operation_kind in ('ticketing', 'cancellation')
     and coalesce(
       new.event_snapshot->>'operationSource',
       case when new.operation_kind = 'imported_manual_ticketing'
         then 'imported_manual_ticketing' else 'triplover' end
     ) <> 'imported_manual_ticketing' then
    v_policy := 'grace';
    v_grace_expires_at := v_now + interval '120 seconds';
    v_available_at := v_grace_expires_at;
  else
    v_available_at := v_now;
  end if;

  -- Enforced keys cannot be overridden by a caller-provided event snapshot.
  -- The snapshot remains render-safe and excludes passenger/contact addresses.
  v_snapshot := coalesce(new.event_snapshot, '{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'version', greatest(coalesce(new.event_version, 1), 1),
      'bookingReference', v_booking_ref,
      'lifecycleStatus', new.to_lifecycle_status,
      'paymentState', v_payment_state,
      'occurrenceId', new.occurrence_id,
      'occurrenceNumber', new.occurrence_number,
      'effectiveAt', new.effective_at,
      'observedAt', coalesce(new.observed_at, v_now)
    ));
  insert into public.booking_notification_outbox (
    lifecycle_event_id, booking_id, notification_kind,
    lifecycle_status, event_snapshot, delivery_policy,
    state, policy_version, available_at, grace_expires_at
  ) values (
    new.id, new.booking_id, 'booking_status',
    new.to_lifecycle_status, v_snapshot, v_policy,
    'pending', 1, v_available_at, v_grace_expires_at
  )
  on conflict (lifecycle_event_id, notification_kind) do nothing;
  return new;
end;
$$;

drop trigger if exists booking_status_events_enqueue_notification
  on public.booking_status_events;
create trigger booking_status_events_enqueue_notification
  after insert on public.booking_status_events
  for each row execute function public.enqueue_booking_lifecycle_event_v1();

revoke all on function public.enqueue_booking_lifecycle_event_v1()
  from public, anon, authenticated, service_role;

comment on function public.enqueue_booking_lifecycle_event_v1() is
  'Creates one render-safe occurrence outbox row in the lifecycle-event transaction. Ordinary Triplover In Progress receives a 120-second grace; other events are immediately eligible.';


-- SOURCE: 0061_impexp_on_hold_unpaid_invariant.sql
-- An imported supplier hold is only a payable offer. It has not been charged
-- until the wallet owner explicitly confirms. NOT VALID avoids rewriting or
-- silently repairing historical rows while enforcing the invariant for every
-- new/updated row immediately; historical validation belongs to Phase 9/10.

alter table public.flight_bookings
  add constraint flight_bookings_impexp_on_hold_unpaid_check
  check (
    import_source is distinct from 'IMP_EXP'
    or status <> 'on-hold'
    or (
      payment_state = 'unpaid'
      and charged_wallet_account_id is null
      and captured_amount = 0
      and refunded_amount = 0
    )
  ) not valid;

comment on constraint flight_bookings_impexp_on_hold_unpaid_check
  on public.flight_bookings is
  'An IMP_EXP On Hold row remains Unpaid with no charged account/capture/refund until an explicit owner confirmation atomically moves it out of On Hold.';


-- SOURCE: 0062_impexp_confirm_manual_ticket_operation.sql
-- Owner Confirm & Pay is one atomic business action: capture the protected
-- User Payable once, create the durable imported-manual-ticket operation and
-- Support-owned case, enter In Progress, and emit the occurrence/outbox.

create or replace function public.wallet_confirm_impexp_booking(
  p_booking_id uuid,
  p_actor_user_id text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
  v_actor_agency text;
  v_existing_operation public.booking_operations;
  v_existing_case public.booking_reconciliation_cases;
  v_existing_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_available_before bigint;
  v_hold_before bigint;
  v_ledger_key text;
  v_operation_request_key text;
  v_payload_hash text;
  v_now timestamptz := clock_timestamp();
  v_due_at timestamptz;
  v_event_id bigint;
  v_occurrence_number integer;
begin
  if p_booking_id is null
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_idempotency_key), '') is null
     or char_length(p_idempotency_key) > 220 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CONFIRM_REQUEST');
  end if;
  select app_user.role, app_user.agency_code
    into v_actor_role, v_actor_agency
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if not found or v_actor_role not in ('customer', 'b2b', 'b2b_sub') then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_CONFIRM_FORBIDDEN');
  end if;

  -- The booking is the serialization root for owner, payment, operation, case,
  -- and reservation identity.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
     and booking.import_source = 'IMP_EXP'
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  if not (
    (v_actor_role = 'customer'
      and v_booking.booking_owner_type = 'user'
      and v_booking.booking_owner_key = p_actor_user_id)
    or
    (v_actor_role in ('b2b', 'b2b_sub')
      and nullif(btrim(v_actor_agency), '') is not null
      and v_booking.booking_owner_type = 'agency'
      and v_booking.booking_owner_key = v_actor_agency)
  ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_CONFIRM_FORBIDDEN');
  end if;

  v_ledger_key := 'impexp-payment:' || v_booking.id::text;
  v_operation_request_key :=
    'impexp-manual-ticketing:' || v_booking.id::text;
  v_payload_hash := encode(sha256(convert_to(jsonb_build_object(
    'version', 1,
    'bookingId', v_booking.id,
    'ownerType', v_booking.booking_owner_type,
    'ownerKey', v_booking.booking_owner_key,
    'amount', v_booking.user_payable_amount,
    'currency', upper(v_booking.currency)
  )::text, 'UTF8')), 'hex');

  select operation.* into v_existing_operation
    from public.booking_operations operation
   where operation.booking_id = v_booking.id
     and operation.state in (
       'claimed', 'supplier_call_started', 'awaiting_external_action',
       'needs_reconciliation'
     )
   order by operation.claimed_at desc, operation.id desc
   limit 1
   for update;
  if found then
    select reconciliation_case.* into v_existing_case
      from public.booking_reconciliation_cases reconciliation_case
     where reconciliation_case.operation_id = v_existing_operation.id
       and reconciliation_case.subject_booking_id = v_booking.id
       and reconciliation_case.state not in ('resolved', 'closed_no_change')
     limit 1
     for update;
  else
    select reconciliation_case.* into v_existing_case
      from public.booking_reconciliation_cases reconciliation_case
     where reconciliation_case.subject_booking_id = v_booking.id
       and reconciliation_case.state not in ('resolved', 'closed_no_change')
     limit 1
     for update;
  end if;
  select reservation.* into v_existing_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
   for update;

  if v_booking.payment_state = 'captured' then
    if v_booking.status = 'in-progress'
       and v_booking.captured_amount = v_booking.user_payable_amount
       and v_booking.refunded_amount = 0
       and v_booking.active_operation_id = v_existing_operation.id
       and v_existing_operation.kind = 'imported_manual_ticketing'
       and v_existing_operation.request_key = v_operation_request_key
       and v_existing_operation.request_payload_hash = v_payload_hash
       and v_existing_operation.state = 'awaiting_external_action'
       and v_existing_case.case_type = 'imported_manual_ticketing'
       and v_existing_reservation.state = 'captured'
       and v_existing_reservation.amount = v_booking.user_payable_amount
       and v_existing_reservation.wallet_account_id
          = v_booking.charged_wallet_account_id
       and exists (
         select 1 from public.wallet_ledger_entries ledger
          where ledger.idempotency_key = v_ledger_key
            and ledger.booking_id = v_booking.id
            and ledger.amount = v_booking.user_payable_amount
       ) then
      return jsonb_build_object(
        'ok', true, 'replay', true,
        'status', 'in-progress',
        'operationId', v_existing_operation.id,
        'operationState', v_existing_operation.state,
        'reconciliationCaseId', v_existing_case.id,
        'reservationId', v_existing_reservation.id,
        'accountId', v_booking.charged_wallet_account_id,
        'amount', v_booking.captured_amount,
        'currency', v_booking.currency
      );
    end if;
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  end if;
  if v_existing_operation.id is not null
     or v_existing_case.id is not null
     or v_existing_reservation.id is not null then
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  end if;
  if v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.payment_state <> 'unpaid'
     or v_booking.charged_wallet_account_id is not null
     or v_booking.captured_amount <> 0
     or v_booking.refunded_amount <> 0
     or public.resolve_booking_lifecycle(
       v_booking.status, v_booking.airlines_pnr,
       v_booking.ticketing_deadline_at, v_booking.operation_kind
     ) <> 'on-hold' then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if v_booking.user_payable_amount is null
     or v_booking.user_payable_amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end if;

  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.owner_type = v_booking.booking_owner_type
     and wallet.owner_key = v_booking.booking_owner_key
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.wallet_id = v_wallet.id
     and account.currency = upper(v_booking.currency)
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_account.available_balance < v_booking.user_payable_amount then
    return jsonb_build_object(
      'ok', false, 'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance,
      'required', v_booking.user_payable_amount,
      'currency', v_account.currency
    );
  end if;

  v_due_at := case
    when v_booking.ticketing_deadline_at is null
      then v_now + interval '2 hours'
    else greatest(
      v_now,
      least(
        v_now + interval '2 hours',
        v_booking.ticketing_deadline_at - interval '1 hour'
      )
    )
  end;
  insert into public.booking_operations (
    booking_id, kind, state, reason_code, reason_detail,
    request_key, request_payload_hash, actor_user_id, actor_role,
    source, prior_stored_status, prior_lifecycle_status,
    supplier, supplier_operation, supplier_unique_trans_id,
    supplier_booking_code_ref, supplier_pnr, supplier_evidence,
    policy_version, claimed_at, external_action_due_at
  ) values (
    v_booking.id, 'imported_manual_ticketing', 'awaiting_external_action',
    'imported_manual_ticketing',
    'Owner payment captured; external manual ticketing is required.',
    v_operation_request_key, v_payload_hash,
    p_actor_user_id, v_actor_role, 'customer',
    'on-hold', 'on-hold', v_booking.supplier,
    'ManualExternalTicketing',
    v_booking.supplier_refs->>'uniqueTransId',
    v_booking.booking_code_ref, v_booking.pnr,
    jsonb_build_object(
      'paymentCaptured', true,
      'supplierApiCalled', false,
      'clientRequestId', p_idempotency_key,
      'userPayableAmount', v_booking.user_payable_amount,
      'currency', v_booking.currency,
      'externalActionDueAt', v_due_at,
      'slaPolicy', jsonb_build_object(
        'policyVersion', 1,
        'warnUnassignedAfterMinutes', 30,
        'adminEscalationAtDue', true,
        'superAdminAfterOverdueMinutes', 60
      )
    ), 1, v_now, v_due_at
  ) returning * into v_operation;
  insert into public.booking_reconciliation_cases (
    subject_booking_id, operation_id, case_type, state,
    reason_code, reason_detail, opened_source,
    opened_by_user_id, opened_by_role, opened_at,
    assigned_team, assigned_at, severity, priority, due_at,
    escalation_level,
    evidence, financial_disposition, policy_version
  ) values (
    v_booking.id, v_operation.id, 'imported_manual_ticketing', 'assigned',
    'manual_ticketing_required',
    'Payment received; verify and complete external supplier ticketing.',
    'operation', p_actor_user_id, v_actor_role, v_now,
    'support', v_now, 'high', 30, v_due_at, 0,
    jsonb_build_array(jsonb_build_object(
      'type', 'owner_payment_capture',
      'operationId', v_operation.id,
      'amount', v_booking.user_payable_amount,
      'currency', v_booking.currency,
      'supplierApiCalled', false,
      'externalActionDueAt', v_due_at,
      'slaPolicy', jsonb_build_object(
        'policyVersion', 1,
        'warnUnassignedAfterMinutes', 30,
        'adminEscalationAtDue', true,
        'superAdminAfterOverdueMinutes', 60
      ),
      'recordedAt', v_now
    )), 'none', 1
  ) returning * into v_case;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts
     set available_balance = available_balance - v_booking.user_payable_amount
   where id = v_account.id;
  insert into public.wallet_reservations (
    wallet_account_id, booking_id, amount, currency, state,
    requested_by_user_id, issued_by_user_id, captured_at
  ) values (
    v_account.id, v_booking.id, v_booking.user_payable_amount,
    v_account.currency, 'captured', p_actor_user_id, p_actor_user_id, v_now
  ) returning * into v_reservation;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks, metadata
  ) values (
    v_account.id, 'booking_confirm', v_booking.user_payable_amount,
    v_account.currency, v_available_before,
    v_available_before - v_booking.user_payable_amount,
    v_hold_before, v_hold_before, v_booking.id, v_booking.public_ref,
    v_reservation.id, v_ledger_key, p_actor_user_id, v_actor_role,
    'Owner confirmed imported booking for manual external ticketing',
    jsonb_build_object(
      'importSource', 'IMP_EXP',
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'supplierGrossAmount', v_booking.supplier_gross_amount,
      'userPayableAmount', v_booking.user_payable_amount
    )
  );
  update public.flight_bookings
     set charged_wallet_account_id = v_account.id,
         payment_state = 'captured',
         payment_amount = user_payable_amount,
         captured_amount = user_payable_amount,
         status = 'in-progress',
         active_operation_id = v_operation.id,
         operation_kind = 'ticketing',
         operation_reason = 'imported_manual_ticketing',
         operation_request_id = v_operation_request_key,
         operation_actor_user_id = p_actor_user_id,
         operation_started_at = v_now,
         operation_prior_status = 'on-hold'
   where id = v_booking.id;
  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'in-progress';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'ticketing', 'imported_manual_ticketing', p_actor_user_id,
    'ImportCustomerConfirm',
    jsonb_build_object(
      'walletCaptured', true,
      'supplierApiCalled', false,
      'userPayableAmount', v_booking.user_payable_amount
    ),
    v_ledger_key || ':in-progress', v_operation.id, v_case.id,
    v_occurrence_number, v_now, v_now,
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'in-progress',
      'paymentState', 'captured',
      'operationKind', 'imported_manual_ticketing',
      'operationSource', 'imported_manual_ticketing',
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'userPayableAmount', v_booking.user_payable_amount,
      'currency', v_booking.currency
    ), 1
  ) returning id into v_event_id;

  return jsonb_build_object(
    'ok', true, 'replay', false,
    'status', 'in-progress',
    'operationId', v_operation.id,
    'operationState', v_operation.state,
    'reconciliationCaseId', v_case.id,
    'reservationId', v_reservation.id,
    'accountId', v_account.id,
    'lifecycleEventId', v_event_id,
    'amount', v_booking.user_payable_amount,
    'currency', v_account.currency,
    'availableBalance', v_available_before - v_booking.user_payable_amount,
    'holdBalance', v_hold_before
  );
end;
$$;

revoke all on function public.wallet_confirm_impexp_booking(uuid,text,text)
  from public, anon, authenticated;
grant execute on function public.wallet_confirm_impexp_booking(uuid,text,text)
  to service_role;

comment on function public.wallet_confirm_impexp_booking(uuid,text,text) is
  'Atomically captures imported User Payable exactly once and creates the durable awaiting-external-action operation, Support-owned case, In Progress occurrence, and outbox intent. No supplier write occurs.';


-- SOURCE: 0063_impexp_manual_ticket_completion.sql
-- Imported manual-ticket completion is a non-financial terminal transition.
-- It consumes only fresh, complete, identity-matched airline Manage Booking
-- evidence and proves the original Confirm & Pay capture before confirming.

create or replace function public.complete_impexp_manual_ticketing_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_evidence_observation_id uuid,
  p_actor_user_id text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_operation_id uuid;
  v_wallet_id uuid;
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_evidence public.booking_reconciliation_observations;
  v_ticket_numbers jsonb;
  v_airlines_pnr jsonb;
  v_supplier_pnr text;
  v_supplier_status text;
  v_fresh_until timestamptz;
  v_traveller_count integer;
  v_capture_ledger_count integer;
  v_occurrence_number integer;
  v_event_id bigint;
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if p_booking_id is null
     or p_case_id is null
     or p_evidence_observation_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_request_key is null
     or p_request_key !~ '^impexp-manual-complete:v1:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_COMPLETION_REQUEST');
  end if;

  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'IMPEXP_COMPLETION_FORBIDDEN');
  end if;

  -- Read the immutable link first, then acquire the global mutation prefix:
  -- booking -> operation -> case -> reservation -> wallet -> account.
  select candidate.operation_id into v_operation_id
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id;
  if not found or v_operation_id is null then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_NOT_FOUND');
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  select operation.* into v_operation
    from public.booking_operations operation
   where operation.id = v_operation_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_OPERATION_NOT_FOUND');
  end if;
  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
     and candidate.operation_id = v_operation.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_MISMATCH');
  end if;

  if v_case.state = 'resolved' then
    if v_case.resolution->>'executionRequestKey' = p_request_key
       and v_case.resolution->>'resolutionKind'
          = 'imported_manual_ticketed' then
      return coalesce(v_case.resolution->'result', '{}'::jsonb)
        || jsonb_build_object(
          'ok', true,
          'replay', true,
          'caseId', v_case.id,
          'caseVersion', v_case.version,
          'resolutionKind', 'imported_manual_ticketed'
        );
    end if;
    return jsonb_build_object('ok', false, 'code', 'CASE_ALREADY_RESOLVED');
  end if;

  if v_booking.import_source is distinct from 'IMP_EXP'
     or v_booking.status <> 'in-progress'
     or v_booking.active_operation_id is distinct from v_operation.id
     or v_booking.operation_kind is distinct from 'ticketing'
     or v_booking.operation_reason is distinct from 'imported_manual_ticketing'
     or v_operation.booking_id is distinct from v_booking.id
     or v_operation.kind is distinct from 'imported_manual_ticketing'
     or v_operation.state is distinct from 'awaiting_external_action'
     or v_case.case_type is distinct from 'imported_manual_ticketing'
     or v_case.state not in ('open', 'assigned', 'awaiting_supplier') then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_NOT_COMPLETABLE');
  end if;
  if v_case.financial_disposition <> 'none' then
    return jsonb_build_object(
      'ok', false, 'code', 'MANUAL_TICKET_FINANCIAL_REVIEW_REQUIRED'
    );
  end if;

  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CAPTURED_RESERVATION_REQUIRED');
  end if;
  select account.wallet_id into v_wallet_id
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.id = v_wallet_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id
     and account.wallet_id = v_wallet.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;

  if v_booking.payment_state <> 'captured'
     or v_booking.user_payable_amount is null
     or v_booking.user_payable_amount <= 0
     or v_booking.payment_amount is distinct from v_booking.user_payable_amount
     or v_booking.captured_amount is distinct from v_booking.user_payable_amount
     or v_booking.refunded_amount <> 0
     or v_booking.charged_wallet_account_id is distinct from v_account.id
     or v_booking.currency is distinct from v_account.currency
     or v_reservation.state <> 'captured'
     or v_reservation.amount is distinct from v_booking.user_payable_amount
     or v_reservation.currency is distinct from v_booking.currency
     or v_reservation.captured_at is null then
    return jsonb_build_object('ok', false, 'code', 'CAPTURED_PAYMENT_MISMATCH');
  end if;
  select count(*)::integer into v_capture_ledger_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.reservation_id = v_reservation.id
     and ledger.wallet_account_id = v_account.id
     and ledger.transaction_type = 'booking_confirm'
     and ledger.amount = v_booking.user_payable_amount
     and ledger.currency = v_booking.currency;
  if v_capture_ledger_count <> 1 then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_LEDGER_MISMATCH');
  end if;

  select observation.* into v_evidence
    from public.booking_reconciliation_observations observation
   where observation.id = p_evidence_observation_id
     and observation.reconciliation_case_id = v_case.id;
  if not found
     or v_evidence.observation_kind is distinct from 'staff_evidence'
     or v_evidence.observation_source is distinct from 'supplier_read'
     or v_evidence.normalized_facts->>'action'
        is distinct from 'supplier_evidence_read'
     or v_evidence.normalized_facts->>'sourceKind'
        is distinct from 'imported_supplier_manage_booking'
     or v_evidence.normalized_facts->>'requestedPurpose'
        is distinct from 'ticketed'
     or v_evidence.normalized_facts->>'bookingId'
        is distinct from v_booking.id::text
     or v_evidence.normalized_facts->>'caseId'
        is distinct from v_case.id::text
     or coalesce((v_evidence.normalized_facts
       #>> '{validation,valid}')::boolean, false) is not true
     or coalesce((v_evidence.normalized_facts
       #>> '{validation,complete}')::boolean, false) is not true
     or coalesce((v_evidence.normalized_facts
       #>> '{validation,fresh}')::boolean, false) is not true
     or coalesce((v_evidence.normalized_facts
       #>> '{validation,identityMatches}')::boolean, false) is not true
     or v_evidence.normalized_facts
       #>> '{validation,authoritativeFor}' is distinct from 'ticketed'
     or v_evidence.normalized_facts
       #>> '{evidence,importedSupplier,source}'
          is distinct from 'airline-manage-booking'
     or v_evidence.normalized_facts
       #>> '{evidence,importedSupplier,provider}'
          is distinct from v_booking.supplier
     or v_evidence.normalized_facts
       #>> '{evidence,importedSupplier,identity,supplierReference}'
          is distinct from v_booking.booking_ref_number
     or v_evidence.observed_at < v_now - interval '5 minutes'
     or v_evidence.observed_at > v_now + interval '1 minute' then
    return jsonb_build_object(
      'ok', false, 'code', 'AUTHORITATIVE_IMPORTED_TICKET_EVIDENCE_REQUIRED'
    );
  end if;
  begin
    v_fresh_until := (v_evidence.normalized_facts
      #>> '{evidence,importedSupplier,freshUntil}')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    return jsonb_build_object(
      'ok', false, 'code', 'AUTHORITATIVE_IMPORTED_TICKET_EVIDENCE_REQUIRED'
    );
  end;
  if v_fresh_until is null or v_fresh_until < v_now then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_TICKET_EVIDENCE_STALE');
  end if;

  v_ticket_numbers := v_evidence.normalized_facts
    #> '{evidence,importedSupplier,facts,ticketNumbers}';
  v_airlines_pnr := v_evidence.normalized_facts
    #> '{evidence,importedSupplier,facts,airlinesPnr}';
  v_supplier_pnr := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,importedSupplier,facts,pnr}'), '');
  v_supplier_status := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,importedSupplier,facts,supplierStatus}'), '');
  v_traveller_count := case
    when jsonb_typeof(v_booking.passengers->'travellers') = 'array'
      then jsonb_array_length(v_booking.passengers->'travellers')
    else 0
  end;
  if v_traveller_count <= 0
     or jsonb_typeof(v_ticket_numbers) <> 'array'
     or jsonb_array_length(v_ticket_numbers) <> v_traveller_count
     or exists (
       select 1 from jsonb_array_elements(v_ticket_numbers) ticket(value)
        where jsonb_typeof(ticket.value) <> 'string'
           or nullif(btrim(ticket.value #>> '{}'), '') is null
     )
     or jsonb_typeof(v_airlines_pnr) <> 'array'
     or jsonb_array_length(v_airlines_pnr) = 0
     or v_supplier_pnr is null then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_TICKET_EVIDENCE_INCOMPLETE');
  end if;
  if public.jsonb_is_nonempty_array(v_booking.ticket_numbers)
     and not (
       v_booking.ticket_numbers @> v_ticket_numbers
       and v_ticket_numbers @> v_booking.ticket_numbers
     ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_TICKET_IDENTITY_CONFLICT');
  end if;
  if public.jsonb_is_nonempty_array(v_booking.airlines_pnr)
     and not (
       v_booking.airlines_pnr @> v_airlines_pnr
       and v_airlines_pnr @> v_booking.airlines_pnr
     ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_PNR_IDENTITY_CONFLICT');
  end if;
  if exists (
    select 1 from public.booking_status_events event
     where event.booking_id = v_booking.id
       and event.idempotency_key = p_request_key || ':confirmed'
       and event.to_lifecycle_status = 'confirmed'
  ) then
    return jsonb_build_object('ok', false, 'code', 'COMPLETION_IDEMPOTENCY_CONFLICT');
  end if;

  update public.flight_bookings
     set status = 'confirmed',
         issued_by_user_id = p_actor_user_id,
         issued_at = coalesce(issued_at, v_evidence.observed_at),
         pnr = coalesce(v_supplier_pnr, pnr),
         airlines_pnr = v_airlines_pnr,
         booking_status = coalesce(v_supplier_status, 'Confirmed'),
         ticket_numbers = v_ticket_numbers,
         synced_at = greatest(coalesce(synced_at, v_evidence.observed_at),
           v_evidence.observed_at),
         import_metadata = coalesce(import_metadata, '{}'::jsonb)
           || jsonb_build_object(
             'manualTicketCompletedAt', v_now,
             'manualTicketCompletedBy', p_actor_user_id,
             'completionEvidenceObservationId', v_evidence.id
           ),
         active_operation_id = null,
         operation_kind = null,
         operation_reason = null,
         operation_request_id = null,
         operation_actor_user_id = null,
         operation_started_at = null,
         operation_prior_status = null
   where id = v_booking.id;
  update public.booking_operations
     set state = 'succeeded',
         supplier_response_received_at = greatest(
           coalesce(supplier_response_received_at, v_evidence.observed_at),
           v_evidence.observed_at
         ),
         completed_at = v_now,
         error_code = null,
         error_message = null,
         supplier_pnr = coalesce(v_supplier_pnr, supplier_pnr),
         supplier_evidence = supplier_evidence || jsonb_build_object(
           'manualTicketCompletion', jsonb_build_object(
             'caseId', v_case.id,
             'evidenceObservationId', v_evidence.id,
             'ticketCount', jsonb_array_length(v_ticket_numbers),
             'completedAt', v_now
           )
         )
   where id = v_operation.id;

  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'confirmed';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, 'in-progress', 'confirmed',
    'in-progress', 'confirmed', 'ticketing',
    'imported_manual_ticketing', p_actor_user_id,
    'ImportedManualTicketCompletion',
    jsonb_build_object(
      'evidenceObservationId', v_evidence.id,
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'walletMutation', false,
      'additionalDebit', 0
    ),
    p_request_key || ':confirmed', v_operation.id, v_case.id,
    v_occurrence_number, v_evidence.observed_at, v_now,
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'confirmed',
      'paymentState', 'captured',
      'operationKind', 'imported_manual_ticketing',
      'operationSource', 'imported_manual_ticketing',
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'userPayableAmount', v_booking.user_payable_amount,
      'currency', v_booking.currency
    ), 1
  ) returning id into v_event_id;

  v_result := jsonb_build_object(
    'bookingStatus', 'confirmed',
    'paymentState', 'captured',
    'operationId', v_operation.id,
    'caseId', v_case.id,
    'reservationId', v_reservation.id,
    'walletAccountId', v_account.id,
    'evidenceObservationId', v_evidence.id,
    'lifecycleEventId', v_event_id,
    'ticketCount', jsonb_array_length(v_ticket_numbers),
    'capturedAmount', v_booking.captured_amount,
    'currency', v_booking.currency,
    'additionalDebit', 0,
    'walletMutation', false,
    'ledgerMutation', false
  );
  update public.booking_reconciliation_cases
     set state = 'resolved',
         resolution_outcome = 'ticketed',
         resolution = jsonb_build_object(
           'version', 1,
           'executionRequestKey', p_request_key,
           'resolutionKind', 'imported_manual_ticketed',
           'executedByRole', v_actor_role,
           'evidenceObservationIds', jsonb_build_array(v_evidence.id),
           'result', v_result
         ),
         resolution_reason = 'Fresh complete matching imported ticket evidence',
         resolved_by_user_id = p_actor_user_id,
         resolved_at = v_now,
         closed_at = v_now,
         version = version + 1
   where id = v_case.id;

  return v_result || jsonb_build_object(
    'ok', true,
    'replay', false,
    'caseVersion', v_case.version + 1,
    'resolutionKind', 'imported_manual_ticketed'
  );
end;
$$;

revoke all on function public.complete_impexp_manual_ticketing_v1(
  uuid, uuid, uuid, text, text
) from public, anon, authenticated;
grant execute on function public.complete_impexp_manual_ticketing_v1(
  uuid, uuid, uuid, text, text
) to service_role;

comment on function public.complete_impexp_manual_ticketing_v1(
  uuid, uuid, uuid, text, text
) is
  'Completes paid imported manual ticketing from fresh complete matching Manage Booking evidence. It confirms travel truth and closes the operation/case without changing wallet balances, reservations, or ledger entries.';


-- SOURCE: 0064_impexp_supplier_outcome_rules.sql
-- Classify each imported Manage Booking observation into one explicit,
-- non-financial operation/case rule. Supplier truth never directly changes
-- the public booking status here and captured funds are never moved.

create or replace function public.classify_impexp_manual_ticket_outcome_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_evidence_observation_id uuid,
  p_actor_user_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_operation_id uuid;
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_evidence public.booking_reconciliation_observations;
  v_classification text;
  v_lifecycle_status text;
  v_reason_code text;
  v_reason_detail text;
  v_required_action text;
  v_operation_state text;
  v_case_state text;
  v_assigned_team text;
  v_severity text;
  v_priority integer;
  v_financial_disposition_required boolean;
  v_due_at timestamptz;
  v_now timestamptz := clock_timestamp();
begin
  if p_booking_id is null
     or p_case_id is null
     or p_evidence_observation_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null then
    return jsonb_build_object('ok', false, 'code', 'INVALID_OUTCOME_REQUEST');
  end if;

  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'IMPEXP_OUTCOME_FORBIDDEN');
  end if;

  select candidate.operation_id into v_operation_id
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id;
  if not found or v_operation_id is null then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_NOT_FOUND');
  end if;

  -- Global mutation order: booking -> operation -> case. This action does not
  -- lock or mutate reservations, wallets, accounts, or ledger entries.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  select operation.* into v_operation
    from public.booking_operations operation
   where operation.id = v_operation_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_OPERATION_NOT_FOUND');
  end if;
  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
     and candidate.operation_id = v_operation.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_MISMATCH');
  end if;

  if v_booking.import_source is distinct from 'IMP_EXP'
     or v_booking.status <> 'in-progress'
     or v_booking.active_operation_id is distinct from v_operation.id
     or v_booking.operation_kind is distinct from 'ticketing'
     or v_booking.operation_reason is distinct from 'imported_manual_ticketing'
     or v_operation.booking_id is distinct from v_booking.id
     or v_operation.kind is distinct from 'imported_manual_ticketing'
     or v_operation.state not in ('awaiting_external_action', 'needs_reconciliation')
     or v_case.case_type is distinct from 'imported_manual_ticketing'
     or v_case.state not in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     ) then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_NOT_CLASSIFIABLE');
  end if;
  if v_booking.payment_state <> 'captured'
     or v_booking.user_payable_amount is null
     or v_booking.user_payable_amount <= 0
     or v_booking.payment_amount is distinct from v_booking.user_payable_amount
     or v_booking.captured_amount is distinct from v_booking.user_payable_amount
     or v_booking.refunded_amount <> 0
     or v_booking.charged_wallet_account_id is null then
    return jsonb_build_object(
      'ok', false, 'code', 'CAPTURED_PAYMENT_RECONCILIATION_REQUIRED'
    );
  end if;
  if v_case.financial_disposition <> 'none' then
    return jsonb_build_object(
      'ok', false, 'code', 'FINANCIAL_DISPOSITION_ALREADY_STARTED'
    );
  end if;

  select observation.* into v_evidence
    from public.booking_reconciliation_observations observation
   where observation.id = p_evidence_observation_id
     and observation.reconciliation_case_id = v_case.id;
  if not found
     or v_evidence.observation_kind is distinct from 'staff_evidence'
     or v_evidence.observation_source is distinct from 'supplier_read'
     or v_evidence.normalized_facts->>'action'
        is distinct from 'supplier_evidence_read'
     or v_evidence.normalized_facts->>'sourceKind'
        is distinct from 'imported_supplier_manage_booking'
     or v_evidence.normalized_facts->>'bookingId'
        is distinct from v_booking.id::text
     or v_evidence.normalized_facts->>'caseId'
        is distinct from v_case.id::text
     or v_evidence.normalized_facts
       #>> '{evidence,importedSupplier,source}'
        is distinct from 'airline-manage-booking'
     or v_evidence.observed_at < v_now - interval '5 minutes'
     or v_evidence.observed_at > v_now + interval '1 minute' then
    return jsonb_build_object(
      'ok', false, 'code', 'IMPORTED_SUPPLIER_EVIDENCE_REQUIRED'
    );
  end if;

  v_classification := v_evidence.normalized_facts
    #>> '{outcome,classification}';
  v_lifecycle_status := v_evidence.normalized_facts
    #>> '{evidence,importedSupplier,facts,lifecycleStatus}';
  if v_classification not in (
       'ticketed', 'held', 'cancelled', 'expired',
       'unconfirmed', 'conflicting'
     ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPPLIER_OUTCOME');
  end if;

  -- Defense in depth: a non-conflicting supplier outcome must be fresh and
  -- identity-matched. Ticketed additionally requires the full P6.6 contract.
  if v_classification <> 'conflicting'
     and (
       coalesce((v_evidence.normalized_facts
         #>> '{outcome,authoritative}')::boolean, false) is not true
       or coalesce((v_evidence.normalized_facts
         #>> '{validation,fresh}')::boolean, false) is not true
       or coalesce((v_evidence.normalized_facts
         #>> '{validation,identityMatches}')::boolean, false) is not true
     ) then
    return jsonb_build_object('ok', false, 'code', 'OUTCOME_IDENTITY_NOT_AUTHORITATIVE');
  end if;
  if v_classification = 'ticketed'
     and (
       v_lifecycle_status is distinct from 'confirmed'
       or coalesce((v_evidence.normalized_facts
         #>> '{validation,valid}')::boolean, false) is not true
       or v_evidence.normalized_facts
         #>> '{validation,authoritativeFor}' is distinct from 'ticketed'
     ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_TICKETED_OUTCOME');
  end if;
  if v_classification = 'held'
     and (
       v_lifecycle_status not in ('on-hold', 'pending', 'in-progress')
       or case
         when jsonb_typeof(v_evidence.normalized_facts
           #> '{evidence,importedSupplier,facts,ticketNumbers}') = 'array'
           then jsonb_array_length(v_evidence.normalized_facts
             #> '{evidence,importedSupplier,facts,ticketNumbers}')
         else -1
       end <> 0
     ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_HELD_OUTCOME');
  end if;
  if v_classification in ('cancelled', 'expired', 'unconfirmed')
     and v_lifecycle_status is distinct from v_classification then
    return jsonb_build_object('ok', false, 'code', 'INVALID_NEGATIVE_OUTCOME');
  end if;
  if v_classification = 'conflicting'
     and coalesce((v_evidence.normalized_facts
       #>> '{outcome,authoritative}')::boolean, true) is not false then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CONFLICT_OUTCOME');
  end if;

  select rule.reason_code, rule.reason_detail, rule.required_action,
         rule.operation_state, rule.case_state, rule.assigned_team,
         rule.severity, rule.priority, rule.financial_required
    into v_reason_code, v_reason_detail, v_required_action,
         v_operation_state, v_case_state, v_assigned_team,
         v_severity, v_priority, v_financial_disposition_required
    from (values
      ('ticketed', 'supplier_ticket_evidence_ready',
       'Fresh complete ticket evidence is ready for staff completion.',
       'complete_ticketing', 'awaiting_external_action', 'assigned',
       'support', 'high', 70, false),
      ('held', 'supplier_booking_still_held',
       'Supplier booking remains held; Support follow-up is still required.',
       'continue_supplier_follow_up', 'awaiting_external_action',
       'awaiting_supplier', 'support', 'high', 40, false),
      ('cancelled', 'supplier_booking_cancelled',
       'Supplier reports cancellation after payment capture; a financial disposition is required.',
       'financial_disposition_required', 'needs_reconciliation',
       'awaiting_finance', 'accounts', 'critical', 90, true),
      ('expired', 'supplier_booking_expired',
       'Supplier reports expiry after payment capture; a financial disposition is required.',
       'financial_disposition_required', 'needs_reconciliation',
       'awaiting_finance', 'accounts', 'critical', 90, true),
      ('unconfirmed', 'supplier_booking_unconfirmed',
       'Supplier reports an unconfirmed booking after payment capture; a financial disposition is required.',
       'financial_disposition_required', 'needs_reconciliation',
       'awaiting_finance', 'accounts', 'critical', 90, true),
      ('conflicting', 'supplier_evidence_conflicting',
       'Supplier evidence conflicts with booking identity or ticket completeness; Admin review is required.',
       'admin_review_required', 'needs_reconciliation', 'assigned',
       'admin', 'critical', 100, false)
    ) as rule(
      classification, reason_code, reason_detail, required_action,
      operation_state, case_state, assigned_team, severity, priority,
      financial_required
    )
   where rule.classification = v_classification;

  if v_operation.supplier_evidence
       #>> '{importedSupplierOutcome,evidenceObservationId}'
       = v_evidence.id::text then
    return jsonb_build_object(
      'ok', true, 'replay', true,
      'classification', v_classification,
      'requiredAction', v_required_action,
      'operationId', v_operation.id,
      'operationState', v_operation.state,
      'caseId', v_case.id,
      'caseState', v_case.state,
      'caseVersion', v_case.version,
      'assignedTeam', v_case.assigned_team,
      'financialDisposition', v_case.financial_disposition,
      'financialDispositionRequired', v_financial_disposition_required,
      'bookingStatusMutation', false,
      'walletMutation', false,
      'ledgerMutation', false
    );
  end if;

  v_due_at := case
    when v_classification = 'conflicting'
      then least(coalesce(v_case.due_at, v_now), v_now)
    when v_financial_disposition_required
      then least(coalesce(v_case.due_at, v_now + interval '30 minutes'),
                  v_now + interval '30 minutes')
    else v_case.due_at
  end;

  update public.booking_operations
     set state = v_operation_state,
         reason_code = v_reason_code,
         reason_detail = v_reason_detail,
         supplier_response_received_at = greatest(
           coalesce(supplier_response_received_at, v_evidence.observed_at),
           v_evidence.observed_at
         ),
         reconciliation_required_at = case
           when v_operation_state = 'needs_reconciliation'
             then coalesce(reconciliation_required_at, v_now)
           else reconciliation_required_at
         end,
         error_code = case
           when v_operation_state = 'needs_reconciliation'
             then upper(v_reason_code)
           else null
         end,
         error_message = case
           when v_operation_state = 'needs_reconciliation'
             then v_reason_detail
           else null
         end,
         supplier_evidence = supplier_evidence || jsonb_build_object(
           'importedSupplierOutcome', jsonb_build_object(
             'classification', v_classification,
             'reasonCode', v_reason_code,
             'requiredAction', v_required_action,
             'evidenceObservationId', v_evidence.id,
             'classifiedAt', v_now,
             'classifiedByUserId', p_actor_user_id,
             'classifiedByRole', v_actor_role,
             'bookingStatusMutation', false,
             'walletMutation', false
           )
         )
   where id = v_operation.id;

  update public.booking_reconciliation_cases
     set state = v_case_state,
         reason_code = v_reason_code,
         reason_detail = v_reason_detail,
         assignee_user_id = case
           when assigned_team is distinct from v_assigned_team then null
           else assignee_user_id
         end,
         assigned_at = case
           when assigned_team is distinct from v_assigned_team
             or assigned_at is null then v_now
           else assigned_at
         end,
         assigned_team = v_assigned_team,
         severity = v_severity,
         priority = v_priority,
         due_at = v_due_at,
         evidence = evidence || jsonb_build_array(jsonb_build_object(
           'type', 'imported_supplier_outcome',
           'classification', v_classification,
           'reasonCode', v_reason_code,
           'requiredAction', v_required_action,
           'evidenceObservationId', v_evidence.id,
           'financialDispositionRequired', v_financial_disposition_required,
           'bookingStatusMutation', false,
           'walletMutation', false,
           'recordedAt', v_now
         )),
         version = version + 1
   where id = v_case.id;

  return jsonb_build_object(
    'ok', true, 'replay', false,
    'classification', v_classification,
    'requiredAction', v_required_action,
    'operationId', v_operation.id,
    'operationState', v_operation_state,
    'caseId', v_case.id,
    'caseState', v_case_state,
    'caseVersion', v_case.version + 1,
    'assignedTeam', v_assigned_team,
    'financialDisposition', 'none',
    'financialDispositionRequired', v_financial_disposition_required,
    'bookingStatusMutation', false,
    'walletMutation', false,
    'ledgerMutation', false
  );
end;
$$;

revoke all on function public.classify_impexp_manual_ticket_outcome_v1(
  uuid, uuid, uuid, text
) from public, anon, authenticated;
grant execute on function public.classify_impexp_manual_ticket_outcome_v1(
  uuid, uuid, uuid, text
) to service_role;

comment on function public.classify_impexp_manual_ticket_outcome_v1(
  uuid, uuid, uuid, text
) is
  'Applies explicit imported ticketed, held, cancelled, expired, unconfirmed, or conflicting operation/case rules from immutable Manage Booking evidence. Never changes booking status or wallet/ledger state.';


-- SOURCE: 0065_impexp_manual_ticket_financial_disposition.sql
-- Captured imported manual-ticket failures require a case-bound financial
-- disposition. Proposal is non-mutating and always maker-checker. Execution
-- atomically records the terminal booking outcome, optional refund ledger,
-- operation failure, case resolution, lifecycle occurrence, and outbox intent.

create or replace function public.propose_impexp_manual_ticket_financial_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_actor_user_id text,
  p_request_key text,
  p_financial_disposition text,
  p_financial_amount bigint,
  p_financial_currency text,
  p_external_settlement_reference text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_operation_id uuid;
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_evidence public.booking_reconciliation_observations;
  v_supplier_outcome text;
  v_outstanding bigint;
  v_risk_flags jsonb;
  v_confirmation_codes jsonb;
  v_proposal jsonb;
  v_proposal_hash text;
begin
  if p_booking_id is null
     or p_case_id is null
     or p_expected_case_version is null
     or p_expected_case_version < 1
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_request_key is null
     or p_request_key !~ '^impexp-financial-proposal:v1:[0-9a-f-]{36}$'
     or p_financial_disposition not in (
       'full_refund', 'partial_refund', 'no_refund_due',
       'externally_settled', 'manual_adjustment_required'
     )
     or nullif(btrim(coalesce(p_reason, '')), '') is null
     or char_length(p_reason) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_FINANCIAL_PROPOSAL');
  end if;
  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINANCIAL_PROPOSAL_FORBIDDEN');
  end if;

  select candidate.operation_id into v_operation_id
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id;
  if not found or v_operation_id is null then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_NOT_FOUND');
  end if;

  -- Global mutation prefix: booking -> operation -> case. Proposal never locks
  -- or mutates reservation, wallet, account, ledger, event, or outbox rows.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  select operation.* into v_operation
    from public.booking_operations operation
   where operation.id = v_operation_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_OPERATION_NOT_FOUND');
  end if;
  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
     and candidate.operation_id = v_operation.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_MISMATCH');
  end if;

  if v_case.proposal->>'requestKey' = p_request_key then
    v_proposal := jsonb_build_object(
      'version', 1,
      'proposalKind', 'imported_manual_ticket_financial',
      'requestKey', p_request_key,
      'domain', 'financial',
      'proposedOutcome', 'cancelled',
      'supplierOutcome', v_case.proposal->>'supplierOutcome',
      'riskFlags', v_case.proposal->'riskFlags',
      'makerCheckerRequired', true,
      'confirmationCodes', v_case.proposal->'confirmationCodes',
      'evidenceObservationIds', v_case.proposal->'evidenceObservationIds',
      'expectedBookingStatus', v_booking.status,
      'expectedPaymentState', v_booking.payment_state,
      'expectedCapturedAmount', v_booking.captured_amount,
      'expectedRefundedAmount', v_booking.refunded_amount,
      'financialDisposition', p_financial_disposition,
      'financialAmount', p_financial_amount,
      'financialCurrency', case when p_financial_currency is null
        then null else upper(p_financial_currency) end,
      'externalSettlementReference', p_external_settlement_reference,
      'reason', p_reason,
      'statusMutationAuthorized', true,
      'walletMutationAuthorized', p_financial_disposition in (
        'full_refund', 'partial_refund'
      )
    );
    v_proposal_hash := encode(
      sha256(convert_to(v_proposal::text, 'UTF8')), 'hex'
    );
    if v_case.proposal_hash = v_proposal_hash
       and v_case.proposed_by_user_id = p_actor_user_id then
      return jsonb_build_object(
        'ok', true, 'replay', true,
        'caseId', v_case.id,
        'caseVersion', v_case.version,
        'proposalHash', v_case.proposal_hash,
        'supplierOutcome', v_case.proposal->>'supplierOutcome',
        'financialDisposition', v_case.financial_disposition,
        'makerCheckerRequired', true,
        'statusMutation', false,
        'walletMutation', false
      );
    end if;
    raise exception 'imported financial proposal request identity mismatch'
      using errcode = '22023';
  end if;

  if v_booking.import_source is distinct from 'IMP_EXP'
     or v_booking.status <> 'in-progress'
     or v_booking.active_operation_id is distinct from v_operation.id
     or v_booking.operation_reason is distinct from 'imported_manual_ticketing'
     or v_operation.kind is distinct from 'imported_manual_ticketing'
     or v_operation.state is distinct from 'needs_reconciliation'
     or v_case.case_type is distinct from 'imported_manual_ticketing'
     or v_case.state not in ('assigned', 'awaiting_finance') then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_FINANCE_NOT_PROPOSABLE');
  end if;
  if v_case.approved_at is not null then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_PROPOSAL_LOCKED');
  end if;
  if v_case.version <> p_expected_case_version then
    return jsonb_build_object(
      'ok', false, 'code', 'CASE_VERSION_CONFLICT',
      'caseVersion', v_case.version
    );
  end if;
  if v_booking.payment_state <> 'captured'
     or v_booking.user_payable_amount is null
     or v_booking.captured_amount is distinct from v_booking.user_payable_amount
     or v_booking.refunded_amount < 0
     or v_booking.refunded_amount >= v_booking.captured_amount
     or v_booking.charged_wallet_account_id is null then
    return jsonb_build_object('ok', false, 'code', 'CAPTURED_PAYMENT_MISMATCH');
  end if;
  v_outstanding := v_booking.captured_amount - v_booking.refunded_amount;

  select observation.* into v_evidence
    from public.booking_reconciliation_observations observation
   where observation.reconciliation_case_id = v_case.id
     and observation.observation_kind = 'staff_evidence'
     and observation.observation_source = 'supplier_read'
     and observation.normalized_facts->>'sourceKind'
        = 'imported_supplier_manage_booking'
     and observation.normalized_facts #>> '{outcome,classification}' in (
       'cancelled', 'expired', 'unconfirmed'
     )
     and observation.normalized_facts #>> '{outcome,authoritative}' = 'true'
     and observation.normalized_facts #>> '{validation,fresh}' = 'true'
     and observation.normalized_facts #>> '{validation,identityMatches}' = 'true'
     and observation.observed_at >= clock_timestamp() - interval '5 minutes'
   order by observation.observed_at desc, observation.id desc
   limit 1;
  if not found then
    return jsonb_build_object(
      'ok', false, 'code', 'FRESH_NEGATIVE_IMPORTED_EVIDENCE_REQUIRED'
    );
  end if;
  v_supplier_outcome := v_evidence.normalized_facts
    #>> '{outcome,classification}';

  if p_financial_disposition = 'partial_refund' then
    if p_financial_amount is null
       or p_financial_amount <= 0
       or p_financial_amount >= v_outstanding
       or upper(coalesce(p_financial_currency, '')) <> v_booking.currency then
      return jsonb_build_object('ok', false, 'code', 'INVALID_PARTIAL_REFUND');
    end if;
  elsif p_financial_amount is not null or p_financial_currency is not null then
    return jsonb_build_object('ok', false, 'code', 'UNEXPECTED_FINANCIAL_AMOUNT');
  end if;
  if p_financial_disposition = 'externally_settled' then
    if nullif(btrim(coalesce(p_external_settlement_reference, '')), '') is null
       or char_length(p_external_settlement_reference) > 255 then
      return jsonb_build_object('ok', false, 'code', 'SETTLEMENT_REFERENCE_REQUIRED');
    end if;
  elsif p_external_settlement_reference is not null then
    return jsonb_build_object('ok', false, 'code', 'UNEXPECTED_SETTLEMENT_REFERENCE');
  end if;

  v_risk_flags := case p_financial_disposition
    when 'full_refund' then '["money_movement"]'::jsonb
    when 'partial_refund' then '["fee_or_no_refund","money_movement"]'::jsonb
    when 'no_refund_due' then '["fee_or_no_refund"]'::jsonb
    when 'externally_settled' then '["external_settlement"]'::jsonb
    else '["manual_adjustment"]'::jsonb
  end;
  v_confirmation_codes := case p_financial_disposition
    when 'partial_refund' then
      '["confirm_financial_disposition","confirm_fee_or_no_refund"]'::jsonb
    when 'no_refund_due' then
      '["confirm_financial_disposition","confirm_fee_or_no_refund"]'::jsonb
    when 'externally_settled' then
      '["confirm_external_settlement","confirm_financial_disposition"]'::jsonb
    else '["confirm_financial_disposition"]'::jsonb
  end;
  v_proposal := jsonb_build_object(
    'version', 1,
    'proposalKind', 'imported_manual_ticket_financial',
    'requestKey', p_request_key,
    'domain', 'financial',
    'proposedOutcome', 'cancelled',
    'supplierOutcome', v_supplier_outcome,
    'riskFlags', v_risk_flags,
    'makerCheckerRequired', true,
    'confirmationCodes', v_confirmation_codes,
    'evidenceObservationIds', jsonb_build_array(v_evidence.id),
    'expectedBookingStatus', v_booking.status,
    'expectedPaymentState', v_booking.payment_state,
    'expectedCapturedAmount', v_booking.captured_amount,
    'expectedRefundedAmount', v_booking.refunded_amount,
    'financialDisposition', p_financial_disposition,
    'financialAmount', p_financial_amount,
    'financialCurrency', case when p_financial_currency is null
      then null else upper(p_financial_currency) end,
    'externalSettlementReference', p_external_settlement_reference,
    'reason', p_reason,
    'statusMutationAuthorized', true,
    'walletMutationAuthorized', p_financial_disposition in (
      'full_refund', 'partial_refund'
    )
  );
  v_proposal_hash := encode(
    sha256(convert_to(v_proposal::text, 'UTF8')), 'hex'
  );

  update public.booking_reconciliation_cases
     set state = 'awaiting_approval',
         assigned_team = 'admin',
         assignee_user_id = null,
         assigned_at = clock_timestamp(),
         proposed_outcome = 'cancelled',
         proposal = v_proposal,
         proposal_hash = v_proposal_hash,
         proposed_by_user_id = p_actor_user_id,
         proposed_at = clock_timestamp(),
         approved_by_user_id = null,
         approved_at = null,
         rejected_by_user_id = null,
         rejected_at = null,
         rejection_reason = null,
         financial_disposition = p_financial_disposition,
         financial_amount = p_financial_amount,
         financial_currency = case when p_financial_currency is null
           then null else upper(p_financial_currency) end,
         external_settlement_reference = p_external_settlement_reference,
         version = version + 1
   where id = v_case.id;

  return jsonb_build_object(
    'ok', true, 'replay', false,
    'caseId', v_case.id,
    'caseVersion', v_case.version + 1,
    'proposalHash', v_proposal_hash,
    'supplierOutcome', v_supplier_outcome,
    'financialDisposition', p_financial_disposition,
    'riskFlags', v_risk_flags,
    'makerCheckerRequired', true,
    'statusMutation', false,
    'walletMutation', false
  );
end;
$$;

create or replace function public.execute_impexp_manual_ticket_financial_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_execution_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_operation_id uuid;
  v_wallet_id uuid;
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_evidence public.booking_reconciliation_observations;
  v_supplier_outcome text;
  v_disposition text;
  v_outstanding bigint;
  v_refund_amount bigint := 0;
  v_refunded_after bigint;
  v_retained_amount bigint;
  v_payment_after text;
  v_available_before bigint;
  v_capture_ledger_count integer;
  v_ledger_entry_id uuid;
  v_event_id bigint;
  v_occurrence_number integer;
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if p_booking_id is null
     or p_case_id is null
     or p_expected_case_version is null
     or p_expected_case_version < 1
     or p_proposal_hash !~ '^[a-f0-9]{64}$'
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_execution_request_key is null
     or p_execution_request_key
        !~ '^impexp-financial-execute:v1:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_FINANCIAL_EXECUTION');
  end if;
  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINANCIAL_EXECUTION_FORBIDDEN');
  end if;

  select candidate.operation_id into v_operation_id
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id;
  if not found or v_operation_id is null then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_NOT_FOUND');
  end if;

  -- Global financial mutation order:
  -- booking -> operation -> case -> reservation -> wallet -> account.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  select operation.* into v_operation
    from public.booking_operations operation
   where operation.id = v_operation_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_OPERATION_NOT_FOUND');
  end if;
  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
     and candidate.operation_id = v_operation.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_CASE_MISMATCH');
  end if;

  if v_case.state = 'resolved' then
    if v_case.proposal_hash = p_proposal_hash
       and v_case.resolution->>'executionRequestKey' = p_execution_request_key
       and v_case.resolution->>'resolutionKind'
          = 'imported_manual_ticket_financial' then
      return coalesce(v_case.resolution->'result', '{}'::jsonb)
        || jsonb_build_object(
          'ok', true, 'replay', true,
          'caseId', v_case.id,
          'caseVersion', v_case.version,
          'proposalHash', v_case.proposal_hash,
          'resolutionKind', 'imported_manual_ticket_financial'
        );
    end if;
    return jsonb_build_object('ok', false, 'code', 'CASE_ALREADY_RESOLVED');
  end if;

  if v_booking.import_source is distinct from 'IMP_EXP'
     or v_booking.status <> 'in-progress'
     or v_booking.active_operation_id is distinct from v_operation.id
     or v_booking.payment_state <> 'captured'
     or v_booking.captured_amount is distinct from v_booking.user_payable_amount
     or v_booking.refunded_amount < 0
     or v_booking.refunded_amount >= v_booking.captured_amount
     or v_operation.kind is distinct from 'imported_manual_ticketing'
     or v_operation.state is distinct from 'needs_reconciliation'
     or v_case.case_type is distinct from 'imported_manual_ticketing' then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_FINANCE_NOT_EXECUTABLE');
  end if;
  if v_case.state <> 'awaiting_approval'
     or v_case.version <> p_expected_case_version
     or v_case.proposal_hash is distinct from p_proposal_hash
     or v_case.proposal->>'proposalKind'
        is distinct from 'imported_manual_ticket_financial'
     or coalesce((v_case.proposal->>'makerCheckerRequired')::boolean, false)
        is not true
     or v_case.approved_by_user_id is null
     or v_case.approved_at is null
     or v_case.approved_by_user_id = v_case.proposed_by_user_id
     or v_case.proposal->>'expectedBookingStatus'
        is distinct from v_booking.status
     or v_case.proposal->>'expectedPaymentState'
        is distinct from v_booking.payment_state
     or v_case.proposal->>'financialDisposition'
        is distinct from v_case.financial_disposition
     or (v_case.proposal->>'expectedCapturedAmount')::bigint
        is distinct from v_booking.captured_amount
     or (v_case.proposal->>'expectedRefundedAmount')::bigint
        is distinct from v_booking.refunded_amount then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_FINANCIAL_PROPOSAL_REQUIRED');
  end if;

  v_disposition := v_case.financial_disposition;
  if v_disposition = 'manual_adjustment_required' then
    return jsonb_build_object(
      'ok', false, 'code', 'MANUAL_ADJUSTMENT_REQUIRED',
      'caseId', v_case.id,
      'caseVersion', v_case.version,
      'financialDisposition', v_disposition,
      'capturedAmount', v_booking.captured_amount,
      'currency', v_booking.currency,
      'walletMutation', false
    );
  end if;
  if v_disposition not in (
       'full_refund', 'partial_refund',
       'no_refund_due', 'externally_settled'
     ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_FINANCIAL_DISPOSITION');
  end if;

  select observation.* into v_evidence
    from jsonb_array_elements_text(
      v_case.proposal->'evidenceObservationIds'
    ) evidence_id(id)
    join public.booking_reconciliation_observations observation
      on observation.id = evidence_id.id::uuid
     and observation.reconciliation_case_id = v_case.id
   where observation.observation_kind = 'staff_evidence'
     and observation.observation_source = 'supplier_read'
     and observation.normalized_facts->>'sourceKind'
        = 'imported_supplier_manage_booking'
     and observation.normalized_facts #>> '{outcome,classification}' in (
       'cancelled', 'expired', 'unconfirmed'
     )
     and observation.normalized_facts #>> '{outcome,authoritative}' = 'true'
     and observation.normalized_facts #>> '{validation,fresh}' = 'true'
     and observation.normalized_facts #>> '{validation,identityMatches}' = 'true'
     and observation.observed_at >= v_now - interval '5 minutes'
   order by observation.observed_at desc, observation.id desc
   limit 1;
  if not found then
    return jsonb_build_object(
      'ok', false, 'code', 'FRESH_NEGATIVE_IMPORTED_EVIDENCE_REQUIRED'
    );
  end if;
  v_supplier_outcome := v_evidence.normalized_facts
    #>> '{outcome,classification}';
  if v_case.proposal->>'supplierOutcome' is distinct from v_supplier_outcome then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_OUTCOME_CHANGED');
  end if;

  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
   for update;
  if not found or v_reservation.state <> 'captured'
     or v_reservation.amount is distinct from v_booking.captured_amount
     or v_reservation.wallet_account_id
        is distinct from v_booking.charged_wallet_account_id then
    return jsonb_build_object('ok', false, 'code', 'CAPTURED_RESERVATION_REQUIRED');
  end if;
  select account.wallet_id into v_wallet_id
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.id = v_wallet_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id
     and account.wallet_id = v_wallet.id
   for update;
  if not found or v_account.currency <> v_booking.currency then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_MISMATCH');
  end if;
  select count(*)::integer into v_capture_ledger_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.reservation_id = v_reservation.id
     and ledger.wallet_account_id = v_account.id
     and ledger.transaction_type = 'booking_confirm'
     and ledger.amount = v_booking.captured_amount
     and ledger.currency = v_booking.currency;
  if v_capture_ledger_count <> 1 then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_LEDGER_MISMATCH');
  end if;

  v_outstanding := v_booking.captured_amount - v_booking.refunded_amount;
  if v_disposition = 'full_refund' then
    v_refund_amount := v_outstanding;
  elsif v_disposition = 'partial_refund' then
    if v_case.financial_amount is null
       or v_case.financial_amount <= 0
       or v_case.financial_amount >= v_outstanding
       or v_case.financial_currency <> v_booking.currency then
      return jsonb_build_object('ok', false, 'code', 'INVALID_PARTIAL_REFUND');
    end if;
    v_refund_amount := v_case.financial_amount;
  elsif v_disposition = 'externally_settled'
     and nullif(btrim(v_case.external_settlement_reference), '') is null then
    return jsonb_build_object('ok', false, 'code', 'SETTLEMENT_REFERENCE_REQUIRED');
  end if;

  v_available_before := v_account.available_balance;
  if v_refund_amount > 0 then
    if exists (
      select 1 from public.wallet_ledger_entries ledger
       where ledger.idempotency_key = p_execution_request_key || ':refund'
    ) then
      return jsonb_build_object('ok', false, 'code', 'REFUND_IDEMPOTENCY_CONFLICT');
    end if;
    update public.wallet_accounts
       set available_balance = available_balance + v_refund_amount
     where id = v_account.id;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'refund', v_refund_amount, v_booking.currency,
      v_available_before, v_available_before + v_refund_amount,
      v_account.hold_balance, v_account.hold_balance,
      v_booking.id, v_booking.public_ref, v_reservation.id,
      p_execution_request_key || ':refund', p_actor_user_id, v_actor_role,
      'Approved imported manual-ticket financial disposition',
      jsonb_build_object(
        'reconciliationCaseId', v_case.id,
        'proposalHash', v_case.proposal_hash,
        'operationId', v_operation.id,
        'evidenceObservationId', v_evidence.id,
        'supplierOutcome', v_supplier_outcome,
        'financialDisposition', v_disposition
      )
    ) returning id into v_ledger_entry_id;
  end if;

  v_refunded_after := v_booking.refunded_amount + v_refund_amount;
  v_retained_amount := v_booking.captured_amount - v_refunded_after;
  v_payment_after := case
    when v_refunded_after = v_booking.captured_amount then 'refunded'
    when v_refunded_after > 0 then 'partially-refunded'
    else 'captured'
  end;

  update public.flight_bookings
     set status = 'cancelled',
         payment_state = v_payment_after,
         refunded_amount = v_refunded_after,
         cancelled_at = coalesce(cancelled_at, v_now),
         cancelled_by = p_actor_user_id,
         cancel_reason = v_case.proposal->>'reason',
         booking_status = 'Manual ticketing could not complete ('
           || v_supplier_outcome || ')',
         active_operation_id = null,
         operation_kind = null,
         operation_reason = null,
         operation_request_id = null,
         operation_actor_user_id = null,
         operation_started_at = null,
         operation_prior_status = null
   where id = v_booking.id;
  update public.booking_operations
     set state = 'failed',
         completed_at = v_now,
         error_code = 'IMPEXP_MANUAL_TICKETING_' || upper(v_supplier_outcome),
         error_message = 'Manual ticketing did not complete; approved financial disposition executed.',
         supplier_evidence = supplier_evidence || jsonb_build_object(
           'financialResolution', jsonb_build_object(
             'caseId', v_case.id,
             'evidenceObservationId', v_evidence.id,
             'supplierOutcome', v_supplier_outcome,
             'financialDisposition', v_disposition,
             'refundAmount', v_refund_amount,
             'executedAt', v_now
           )
         )
   where id = v_operation.id;

  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'cancelled';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, 'in-progress', 'cancelled',
    'in-progress', 'cancelled', 'ticketing',
    'imported_manual_ticketing', p_actor_user_id,
    'ImportedManualTicketFinancialResolution',
    jsonb_build_object(
      'evidenceObservationId', v_evidence.id,
      'supplierOutcome', v_supplier_outcome,
      'financialDisposition', v_disposition,
      'refundAmount', v_refund_amount
    ),
    p_execution_request_key || ':cancelled', v_operation.id, v_case.id,
    v_occurrence_number, v_now, v_now,
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'cancelled',
      'paymentState', v_payment_after,
      'operationKind', 'imported_manual_ticketing',
      'operationSource', 'financial_reconciliation',
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'supplierOutcome', v_supplier_outcome,
      'financialDisposition', v_disposition,
      'refundAmount', v_refund_amount,
      'capturedAmount', v_booking.captured_amount,
      'retainedAmount', v_retained_amount,
      'currency', v_booking.currency
    ), 1
  ) returning id into v_event_id;

  v_result := jsonb_build_object(
    'bookingStatus', 'cancelled',
    'paymentState', v_payment_after,
    'operationId', v_operation.id,
    'caseId', v_case.id,
    'reservationId', v_reservation.id,
    'walletAccountId', v_account.id,
    'evidenceObservationId', v_evidence.id,
    'lifecycleEventId', v_event_id,
    'ledgerEntryId', v_ledger_entry_id,
    'supplierOutcome', v_supplier_outcome,
    'financialDisposition', v_disposition,
    'refundAmount', v_refund_amount,
    'refundedAmount', v_refunded_after,
    'retainedAmount', v_retained_amount,
    'capturedAmount', v_booking.captured_amount,
    'currency', v_booking.currency,
    'walletMutation', v_refund_amount > 0,
    'availableBalance', v_available_before + v_refund_amount,
    'holdBalance', v_account.hold_balance,
    'externalSettlementReference', case
      when v_disposition = 'externally_settled'
        then v_case.external_settlement_reference else null end
  );
  update public.booking_reconciliation_cases
     set state = 'resolved',
         resolution_outcome = 'imported_manual_' || v_supplier_outcome
           || '_' || v_disposition,
         resolution = jsonb_build_object(
           'version', 1,
           'executionRequestKey', p_execution_request_key,
           'proposalHash', v_case.proposal_hash,
           'resolutionKind', 'imported_manual_ticket_financial',
           'supplierOutcome', v_supplier_outcome,
           'financialDisposition', v_disposition,
           'executedByRole', v_actor_role,
           'evidenceObservationIds', v_case.proposal->'evidenceObservationIds',
           'result', v_result
         ),
         resolution_reason = v_case.proposal->>'reason',
         resolved_by_user_id = p_actor_user_id,
         resolved_at = v_now,
         closed_at = v_now,
         version = version + 1
   where id = v_case.id;

  return v_result || jsonb_build_object(
    'ok', true, 'replay', false,
    'caseVersion', v_case.version + 1,
    'proposalHash', v_case.proposal_hash,
    'resolutionKind', 'imported_manual_ticket_financial'
  );
end;
$$;

revoke all on function public.propose_impexp_manual_ticket_financial_v1(
  uuid, uuid, integer, text, text, text, bigint, text, text, text
) from public, anon, authenticated;
revoke all on function public.execute_impexp_manual_ticket_financial_v1(
  uuid, uuid, integer, text, text, text
) from public, anon, authenticated;
grant execute on function public.propose_impexp_manual_ticket_financial_v1(
  uuid, uuid, integer, text, text, text, bigint, text, text, text
) to service_role;
grant execute on function public.execute_impexp_manual_ticket_financial_v1(
  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.propose_impexp_manual_ticket_financial_v1(
  uuid, uuid, integer, text, text, text, bigint, text, text, text
) is
  'Creates an immutable-evidence-bound, always-maker-checker financial proposal for a captured imported manual-ticket failure. It changes no booking or wallet truth.';
comment on function public.execute_impexp_manual_ticket_financial_v1(
  uuid, uuid, integer, text, text, text
) is
  'Executes an independently approved imported manual-ticket financial disposition atomically. Refund modes write one wallet ledger row; no-refund and external settlement remain explicit without fabricated wallet movement.';


-- SOURCE: 0066_impexp_manual_ticket_escalation.sql
-- Execute the imported manual-ticket SLA policy in bounded, concurrent-safe
-- batches. Escalation changes internal ownership only; it never invents
-- supplier truth, changes public booking status, or mutates financial rows.

create index if not exists booking_reconciliation_cases_impexp_escalation_idx
  on public.booking_reconciliation_cases (
    due_at, escalation_level, opened_at, subject_booking_id, id
  )
  where case_type = 'imported_manual_ticketing'
    and state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    );

create or replace function public.process_impexp_manual_ticket_escalations_v1(
  p_limit integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_candidate record;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_now timestamptz := clock_timestamp();
  v_action text;
  v_processed integer := 0;
  v_warned integer := 0;
  v_admin_escalated integer := 0;
  v_superadmin_escalated integer := 0;
  v_remaining integer := 0;
begin
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ESCALATION_LIMIT');
  end if;

  for v_candidate in
    select
      booking.id as booking_id,
      operation.id as operation_id,
      reconciliation_case.id as case_id
    from public.booking_reconciliation_cases reconciliation_case
    join public.booking_operations operation
      on operation.id = reconciliation_case.operation_id
    join public.flight_bookings booking
      on booking.id = reconciliation_case.subject_booking_id
     and booking.active_operation_id = operation.id
   where reconciliation_case.case_type = 'imported_manual_ticketing'
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     )
     and operation.kind = 'imported_manual_ticketing'
     and operation.state in ('awaiting_external_action', 'needs_reconciliation')
     and booking.import_source = 'IMP_EXP'
     and booking.status = 'in-progress'
     and (
       (reconciliation_case.due_at is not null
         and reconciliation_case.escalation_level < 2
         and v_now >= reconciliation_case.due_at + interval '60 minutes')
       or (reconciliation_case.due_at is not null
         and reconciliation_case.escalation_level < 1
         and v_now >= reconciliation_case.due_at)
       or (reconciliation_case.escalation_level = 0
         and reconciliation_case.assignee_user_id is null
         and v_now >= reconciliation_case.opened_at + interval '30 minutes'
         and reconciliation_case.escalation_reason
           is distinct from 'manual_ticket_unassigned_warning')
     )
   order by
     coalesce(reconciliation_case.due_at, reconciliation_case.opened_at),
     reconciliation_case.id
   limit p_limit
   for update of booking skip locked
  loop
    -- The candidate query already owns the booking serialization root. Lock
    -- the remaining mutable rows in global booking -> operation -> case order.
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_candidate.operation_id
       and operation.booking_id = v_candidate.booking_id
     for update;
    if not found then
      continue;
    end if;
    select reconciliation_case.* into v_case
      from public.booking_reconciliation_cases reconciliation_case
     where reconciliation_case.id = v_candidate.case_id
       and reconciliation_case.subject_booking_id = v_candidate.booking_id
       and reconciliation_case.operation_id = v_operation.id
     for update;
    if not found
       or v_case.state not in (
         'open', 'assigned', 'awaiting_supplier',
         'awaiting_finance', 'awaiting_approval'
       )
       or v_operation.kind <> 'imported_manual_ticketing'
       or v_operation.state not in (
         'awaiting_external_action', 'needs_reconciliation'
       ) then
      continue;
    end if;

    v_action := null;
    if v_case.due_at is not null
       and v_case.escalation_level < 2
       and v_now >= v_case.due_at + interval '60 minutes' then
      v_action := 'superadmin';
    elsif v_case.due_at is not null
       and v_case.escalation_level < 1
       and v_now >= v_case.due_at then
      v_action := 'admin';
    elsif v_case.escalation_level = 0
       and v_case.assignee_user_id is null
       and v_now >= v_case.opened_at + interval '30 minutes'
       and v_case.escalation_reason
         is distinct from 'manual_ticket_unassigned_warning' then
      v_action := 'warning';
    end if;
    if v_action is null then
      continue;
    end if;

    if v_action = 'warning' then
      update public.booking_reconciliation_cases
         set priority = greatest(priority, 60),
             escalation_reason = 'manual_ticket_unassigned_warning',
             escalated_at = v_now,
             evidence = evidence || jsonb_build_array(jsonb_build_object(
               'type', 'manual_ticket_sla_escalation',
               'level', 0,
               'reason', 'manual_ticket_unassigned_warning',
               'recordedAt', v_now,
               'publicStatusMutation', false,
               'walletMutation', false
             )),
             version = version + 1
       where id = v_case.id;
      v_warned := v_warned + 1;
    else
      update public.booking_operations
         set state = 'needs_reconciliation',
             reason_code = case
               when state = 'awaiting_external_action'
                 then 'imported_manual_ticketing_overdue'
               else reason_code
             end,
             reason_detail = case
               when state = 'awaiting_external_action'
                 then 'Manual ticketing exceeded its external-action SLA and requires explicit reconciliation.'
               else reason_detail
             end,
             reconciliation_required_at = coalesce(
               reconciliation_required_at, v_now
             ),
             error_code = case
               when state = 'awaiting_external_action'
                 then 'IMPEXP_MANUAL_TICKETING_OVERDUE'
               else error_code
             end,
             error_message = case
               when state = 'awaiting_external_action'
                 then 'External manual ticketing exceeded its due time.'
               else error_message
             end,
             supplier_evidence = supplier_evidence || jsonb_build_object(
               'lastSlaEscalation', jsonb_build_object(
                 'level', case when v_action = 'superadmin' then 2 else 1 end,
                 'reason', case when v_action = 'superadmin'
                   then 'manual_ticket_superadmin_escalation'
                   else 'manual_ticket_admin_escalation' end,
                 'escalatedAt', v_now,
                 'supplierTruthInferred', false,
                 'publicStatusMutation', false,
                 'walletMutation', false
               )
             )
       where id = v_operation.id;

      update public.booking_reconciliation_cases
         set state = case
               when state in ('awaiting_finance', 'awaiting_approval')
                 then state
               else 'assigned'
             end,
             reason_code = case
               when state in ('awaiting_finance', 'awaiting_approval')
                 then reason_code
               else 'imported_manual_ticketing_overdue'
             end,
             reason_detail = case
               when state in ('awaiting_finance', 'awaiting_approval')
                 then reason_detail
               else 'Manual ticketing exceeded its SLA; Admin reconciliation is required.'
             end,
             assigned_team = 'admin',
             assignee_user_id = null,
             assigned_at = v_now,
             severity = 'critical',
             priority = case when v_action = 'superadmin' then 100
               else greatest(priority, 90) end,
             escalation_level = case when v_action = 'superadmin' then 2 else 1 end,
             escalation_reason = case when v_action = 'superadmin'
               then 'manual_ticket_superadmin_escalation'
               else 'manual_ticket_admin_escalation' end,
             escalated_at = v_now,
             evidence = evidence || jsonb_build_array(jsonb_build_object(
               'type', 'manual_ticket_sla_escalation',
               'level', case when v_action = 'superadmin' then 2 else 1 end,
               'reason', case when v_action = 'superadmin'
                 then 'manual_ticket_superadmin_escalation'
                 else 'manual_ticket_admin_escalation' end,
               'dueAt', v_case.due_at,
               'overdueSeconds', greatest(
                 0, extract(epoch from (v_now - v_case.due_at))::integer
               ),
               'supplierTruthInferred', false,
               'financialDisposition', v_case.financial_disposition,
               'publicStatusMutation', false,
               'walletMutation', false,
               'recordedAt', v_now
             )),
             version = version + 1
       where id = v_case.id;
      if v_action = 'superadmin' then
        v_superadmin_escalated := v_superadmin_escalated + 1;
      else
        v_admin_escalated := v_admin_escalated + 1;
      end if;
    end if;
    v_processed := v_processed + 1;
  end loop;

  select count(*)::integer into v_remaining
    from public.booking_reconciliation_cases reconciliation_case
    join public.booking_operations operation
      on operation.id = reconciliation_case.operation_id
    join public.flight_bookings booking
      on booking.id = reconciliation_case.subject_booking_id
     and booking.active_operation_id = operation.id
   where reconciliation_case.case_type = 'imported_manual_ticketing'
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     )
     and operation.kind = 'imported_manual_ticketing'
     and operation.state in ('awaiting_external_action', 'needs_reconciliation')
     and booking.status = 'in-progress'
     and (
       (reconciliation_case.due_at is not null
         and reconciliation_case.escalation_level < 2
         and v_now >= reconciliation_case.due_at + interval '60 minutes')
       or (reconciliation_case.due_at is not null
         and reconciliation_case.escalation_level < 1
         and v_now >= reconciliation_case.due_at)
       or (reconciliation_case.escalation_level = 0
         and reconciliation_case.assignee_user_id is null
         and v_now >= reconciliation_case.opened_at + interval '30 minutes'
         and reconciliation_case.escalation_reason
           is distinct from 'manual_ticket_unassigned_warning')
     );

  return jsonb_build_object(
    'ok', true,
    'processed', v_processed,
    'unassignedWarnings', v_warned,
    'adminEscalations', v_admin_escalated,
    'superadminEscalations', v_superadmin_escalated,
    'remainingEligible', v_remaining,
    'limit', p_limit,
    'publicStatusMutation', false,
    'walletMutation', false,
    'supplierTruthInferred', false
  );
end;
$$;

revoke all on function public.process_impexp_manual_ticket_escalations_v1(integer)
  from public, anon, authenticated;
grant execute on function public.process_impexp_manual_ticket_escalations_v1(integer)
  to service_role;

comment on function public.process_impexp_manual_ticket_escalations_v1(integer) is
  'Processes a bounded imported manual-ticket SLA batch: unassigned warning at 30 minutes, Admin reconciliation at due time, and level-2 Super Admin attention after 60 overdue minutes. Never changes booking status, supplier truth, or money.';


-- SOURCE: 0067_impexp_direct_import_charge_authorization.sql
-- Direct confirmed import and wallet capture are separate decisions. Import &
-- Charge requires a fresh server-recorded authorization bound to the supplier,
-- assignee/owner, protected User Payable, supplier gross, currency, and a
-- normalized supplier snapshot hash. Import only never touches wallet money.

create table if not exists public.impexp_import_charge_authorizations (
  id                         uuid primary key default gen_random_uuid(),
  request_key                text not null unique,
  actor_user_id              text not null,
  actor_role                 text not null,
  assigned_user_id           text not null,
  owner_type                 text not null,
  owner_key                  text not null,
  supplier                   text not null,
  supplier_reference         text not null,
  currency                   text not null,
  user_payable_amount        bigint not null,
  supplier_gross_amount      bigint not null,
  authorization_payload_hash text not null,
  authorized_at              timestamptz not null default clock_timestamp(),
  expires_at                 timestamptz not null,
  consumed_at                timestamptz,
  consumed_booking_id        uuid references public.flight_bookings(id)
                             on delete restrict,
  created_at                 timestamptz not null default clock_timestamp(),
  constraint impexp_import_charge_auth_actor_role_check
    check (actor_role in ('staff_support', 'admin', 'superadmin')),
  constraint impexp_import_charge_auth_owner_check
    check (owner_type in ('user', 'agency') and btrim(owner_key) <> ''),
  constraint impexp_import_charge_auth_supplier_check
    check (supplier in ('US_BANGLA', 'AIR_ASTRA', 'NOVOAIR')),
  constraint impexp_import_charge_auth_currency_check
    check (currency ~ '^[A-Z]{3}$'),
  constraint impexp_import_charge_auth_amount_check
    check (user_payable_amount > 0 and supplier_gross_amount >= 0),
  constraint impexp_import_charge_auth_hash_check
    check (authorization_payload_hash ~ '^[a-f0-9]{64}$'),
  constraint impexp_import_charge_auth_request_check
    check (request_key ~ '^impexp-charge-authorization:v1:[0-9a-f-]{36}$'),
  constraint impexp_import_charge_auth_time_check
    check (expires_at > authorized_at),
  constraint impexp_import_charge_auth_consumption_check
    check (
      (consumed_at is null and consumed_booking_id is null)
      or (consumed_at is not null and consumed_booking_id is not null)
    )
);

create index if not exists impexp_import_charge_authorizations_expiry_idx
  on public.impexp_import_charge_authorizations (expires_at, id)
  where consumed_at is null;

alter table public.impexp_import_charge_authorizations enable row level security;
revoke all on table public.impexp_import_charge_authorizations
  from public, anon, authenticated;
grant select, insert, update on table public.impexp_import_charge_authorizations
  to service_role;

create or replace function public.impexp_charge_authorization_payload_v1(
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_data jsonb
)
returns jsonb
language sql
immutable
set search_path = public
as $$
  select jsonb_build_object(
    'version', 1,
    'assignedUserId', p_assigned_user_id,
    'userPayableAmount', p_user_payable_amount,
    'supplierGrossAmount', p_supplier_gross_amount,
    'provider', p_data->>'provider',
    'supplierReference', p_data->>'supplierReference',
    'storedStatus', p_data->>'storedStatus',
    'lifecycleStatus', p_data->>'lifecycleStatus',
    'currency', upper(p_data->>'currency'),
    'passengerCounts', p_data->'passengerCounts',
    'itinerary', p_data->'itinerary',
    'passengers', p_data->'passengers',
    'pnr', p_data->>'pnr',
    'airlinesPnr', p_data->'airlinesPnr',
    'ticketNumbers', p_data->'ticketNumbers'
  );
$$;

create or replace function public.authorize_impexp_import_charge_v1(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_data jsonb,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_target_role text;
  v_agency_code text;
  v_owner_type text;
  v_owner_key text;
  v_supplier text;
  v_supplier_ref text;
  v_currency text;
  v_payload_hash text;
  v_traveller_count integer;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing public.impexp_import_charge_authorizations;
  v_authorization public.impexp_import_charge_authorizations;
  v_now timestamptz := clock_timestamp();
begin
  if p_data is null
     or jsonb_typeof(p_data) <> 'object'
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or nullif(btrim(coalesce(p_assigned_user_id, '')), '') is null
     or p_user_payable_amount is null or p_user_payable_amount <= 0
     or p_supplier_gross_amount is null or p_supplier_gross_amount < 0
     or p_request_key
        !~ '^impexp-charge-authorization:v1:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CHARGE_AUTHORIZATION');
  end if;
  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'IMPEXP_CHARGE_AUTHORIZATION_FORBIDDEN');
  end if;
  select role, agency_code into v_target_role, v_agency_code
    from public.app_users
   where clerk_id = p_assigned_user_id;
  if not found or v_target_role not in ('b2b', 'b2b_sub', 'customer') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_ASSIGNEE');
  end if;
  if v_target_role in ('b2b', 'b2b_sub') then
    if nullif(btrim(v_agency_code), '') is null then
      return jsonb_build_object('ok', false, 'code', 'ASSIGNEE_AGENCY_REQUIRED');
    end if;
    v_owner_type := 'agency';
    v_owner_key := v_agency_code;
  else
    v_owner_type := 'user';
    v_owner_key := p_assigned_user_id;
  end if;

  v_supplier := nullif(btrim(p_data->>'provider'), '');
  v_supplier_ref := nullif(btrim(p_data->>'supplierReference'), '');
  v_currency := upper(coalesce(nullif(btrim(p_data->>'currency'), ''), 'BDT'));
  v_traveller_count := case
    when jsonb_typeof(p_data #> '{passengers,travellers}') = 'array'
      then jsonb_array_length(p_data #> '{passengers,travellers}')
    else 0
  end;
  if v_supplier not in ('US_BANGLA', 'AIR_ASTRA', 'NOVOAIR')
     or v_supplier_ref is null
     or v_currency !~ '^[A-Z]{3}$'
     or p_data->>'storedStatus' is distinct from 'confirmed'
     or p_data->>'lifecycleStatus' is distinct from 'confirmed'
     or nullif(btrim(p_data->>'pnr'), '') is null
     or jsonb_typeof(p_data->'airlinesPnr') <> 'array'
     or jsonb_array_length(case
          when jsonb_typeof(p_data->'airlinesPnr') = 'array'
            then p_data->'airlinesPnr' else '[]'::jsonb end) = 0
     or jsonb_typeof(p_data->'ticketNumbers') <> 'array'
     or v_traveller_count <= 0
     or jsonb_array_length(case
          when jsonb_typeof(p_data->'ticketNumbers') = 'array'
            then p_data->'ticketNumbers' else '[]'::jsonb end)
        <> v_traveller_count
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(p_data->'ticketNumbers') = 'array'
           then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value)
        where jsonb_typeof(ticket.value) <> 'string'
           or nullif(btrim(ticket.value #>> '{}'), '') is null
     )
     or (select count(distinct ticket.value #>> '{}')
           from jsonb_array_elements(case
             when jsonb_typeof(p_data->'ticketNumbers') = 'array'
               then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value))
        <> v_traveller_count
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(p_data->'airlinesPnr') = 'array'
           then p_data->'airlinesPnr' else '[]'::jsonb end) airline(value)
        where jsonb_typeof(airline.value) <> 'string'
           or nullif(btrim(airline.value #>> '{}'), '') is null
     ) then
    return jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_CONFIRMED_IMPORT_EVIDENCE_REQUIRED'
    );
  end if;

  v_payload_hash := encode(sha256(convert_to(
    public.impexp_charge_authorization_payload_v1(
      p_assigned_user_id, p_user_payable_amount,
      p_supplier_gross_amount, p_data
    )::text, 'UTF8'
  )), 'hex');
  select auth_row.* into v_existing
    from public.impexp_import_charge_authorizations auth_row
   where auth_row.request_key = p_request_key
   for update;
  if found then
    if v_existing.actor_user_id = p_actor_user_id
       and v_existing.assigned_user_id = p_assigned_user_id
       and v_existing.authorization_payload_hash = v_payload_hash then
      return jsonb_build_object(
        'ok', true, 'replay', true,
        'authorizationId', v_existing.id,
        'expiresAt', v_existing.expires_at,
        'consumed', v_existing.consumed_at is not null,
        'amount', v_existing.user_payable_amount,
        'currency', v_existing.currency
      );
    end if;
    raise exception 'import charge authorization request identity mismatch'
      using errcode = '22023';
  end if;

  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.owner_type = v_owner_type
     and wallet.owner_key = v_owner_key;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.wallet_id = v_wallet.id
     and account.currency = v_currency;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_account.available_balance < p_user_payable_amount then
    return jsonb_build_object(
      'ok', false, 'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance,
      'required', p_user_payable_amount,
      'currency', v_currency
    );
  end if;

  insert into public.impexp_import_charge_authorizations (
    request_key, actor_user_id, actor_role, assigned_user_id,
    owner_type, owner_key, supplier, supplier_reference, currency,
    user_payable_amount, supplier_gross_amount,
    authorization_payload_hash, authorized_at, expires_at
  ) values (
    p_request_key, p_actor_user_id, v_actor_role, p_assigned_user_id,
    v_owner_type, v_owner_key, v_supplier, v_supplier_ref, v_currency,
    p_user_payable_amount, p_supplier_gross_amount,
    v_payload_hash, v_now, v_now + interval '5 minutes'
  ) returning * into v_authorization;

  return jsonb_build_object(
    'ok', true, 'replay', false,
    'authorizationId', v_authorization.id,
    'expiresAt', v_authorization.expires_at,
    'consumed', false,
    'amount', v_authorization.user_payable_amount,
    'currency', v_authorization.currency,
    'walletAvailable', v_account.available_balance,
    'walletMutation', false
  );
end;
$$;

create or replace function public.create_impexp_booking_v2(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_data jsonb,
  p_import_decision text,
  p_charge_authorization_id uuid,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_target_role text;
  v_agency_code text;
  v_owner_type text;
  v_owner_key text;
  v_supplier text;
  v_supplier_ref text;
  v_currency text;
  v_stored_status text;
  v_lifecycle_status text;
  v_payload_hash text;
  v_existing public.flight_bookings;
  v_authorization public.impexp_import_charge_authorizations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_booking public.flight_bookings;
  v_reservation public.wallet_reservations;
  v_case public.booking_reconciliation_cases;
  v_safe_data jsonb;
  v_created jsonb;
  v_available_before bigint;
  v_hold_before bigint;
  v_ledger_key text;
  v_imported_at timestamptz;
  v_event_id bigint;
  v_occurrence_number integer;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object'
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or nullif(btrim(coalesce(p_assigned_user_id, '')), '') is null
     or p_user_payable_amount is null or p_user_payable_amount <= 0
     or p_supplier_gross_amount is null or p_supplier_gross_amount < 0
     or p_import_decision not in ('import_only', 'import_and_charge')
     or p_request_key !~ '^impexp-import:v2:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end if;
  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'IMPEXP_FORBIDDEN');
  end if;
  select role, agency_code into v_target_role, v_agency_code
    from public.app_users
   where clerk_id = p_assigned_user_id;
  if not found or v_target_role not in ('b2b', 'b2b_sub', 'customer') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_ASSIGNEE');
  end if;
  if v_target_role in ('b2b', 'b2b_sub') then
    if nullif(btrim(v_agency_code), '') is null then
      return jsonb_build_object('ok', false, 'code', 'ASSIGNEE_AGENCY_REQUIRED');
    end if;
    v_owner_type := 'agency';
    v_owner_key := v_agency_code;
  else
    v_owner_type := 'user';
    v_owner_key := p_assigned_user_id;
  end if;

  v_supplier := nullif(btrim(p_data->>'provider'), '');
  v_supplier_ref := nullif(btrim(p_data->>'supplierReference'), '');
  v_currency := upper(coalesce(nullif(btrim(p_data->>'currency'), ''), 'BDT'));
  v_stored_status := p_data->>'storedStatus';
  v_lifecycle_status := p_data->>'lifecycleStatus';
  if v_supplier not in ('US_BANGLA', 'AIR_ASTRA', 'NOVOAIR')
     or v_supplier_ref is null
     or v_currency !~ '^[A-Z]{3}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_IDENTITY');
  end if;
  if v_lifecycle_status <> 'confirmed'
     and (p_import_decision <> 'import_only'
       or p_charge_authorization_id is not null) then
    return jsonb_build_object('ok', false, 'code', 'CHARGE_DECISION_NOT_APPLICABLE');
  end if;
  if v_lifecycle_status = 'confirmed'
     and ((p_import_decision = 'import_and_charge'
         and p_charge_authorization_id is null)
       or (p_import_decision = 'import_only'
         and p_charge_authorization_id is not null)) then
    return jsonb_build_object('ok', false, 'code', 'CHARGE_AUTHORIZATION_MISMATCH');
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('IMP_EXP:' || v_supplier || ':' || v_supplier_ref, 0)
  );
  select booking.* into v_existing
    from public.flight_bookings booking
   where booking.import_source = 'IMP_EXP'
     and booking.supplier = v_supplier
     and booking.booking_ref_number = v_supplier_ref
   limit 1
   for update;
  if found then
    if v_existing.user_payable_amount is null
       or v_existing.booking_owner_type is null
       or v_existing.booking_owner_key is null then
      return jsonb_build_object(
        'ok', false, 'code', 'HISTORICAL_IMPORT_RECONCILIATION_REQUIRED'
      );
    end if;
    if v_existing.user_id is distinct from p_assigned_user_id
       or v_existing.booking_owner_type is distinct from v_owner_type
       or v_existing.booking_owner_key is distinct from v_owner_key then
      return jsonb_build_object('ok', false, 'code', 'IMPORT_ASSIGNEE_MISMATCH');
    end if;
    if v_existing.user_payable_amount <> p_user_payable_amount then
      return jsonb_build_object('ok', false, 'code', 'IMPORT_PAYABLE_MISMATCH');
    end if;
    if v_existing.import_metadata->>'importRequestKey' = p_request_key
       and v_existing.import_metadata->>'importDecision' = p_import_decision then
      return jsonb_build_object(
        'ok', true, 'replay', true,
        'booking', to_jsonb(v_existing),
        'walletCharged', false,
        'chargePreviouslyCaptured', v_existing.payment_state = 'captured',
        'amount', case when v_existing.payment_state = 'captured'
          then v_existing.captured_amount else 0 end,
        'accountId', v_existing.charged_wallet_account_id,
        'status', v_lifecycle_status,
        'importDecision', p_import_decision
      );
    end if;
    if v_existing.payment_state <> 'captured'
       and v_lifecycle_status = 'confirmed' then
      return jsonb_build_object(
        'ok', false,
        'code', 'REIMPORT_CONFIRMATION_REQUIRES_RECONCILIATION'
      );
    end if;
    return public.sync_impexp_booking_v2(
      p_actor_user_id, v_existing.id, p_supplier_gross_amount, p_data
    ) || jsonb_build_object(
      'reimport', true,
      'walletCharged', false,
      'importDecision', p_import_decision
    );
  end if;

  if v_lifecycle_status <> 'confirmed' then
    v_created := public.create_impexp_booking(
      p_actor_user_id, p_assigned_user_id, p_user_payable_amount,
      p_supplier_gross_amount, p_data
    );
    if coalesce((v_created->>'ok')::boolean, false) is not true then
      return v_created;
    end if;
    update public.flight_bookings
       set import_metadata = coalesce(import_metadata, '{}'::jsonb)
         || jsonb_build_object(
           'importDecision', 'import_only',
           'importRequestKey', p_request_key,
           'walletChargeAuthorized', false
         )
     where id = (v_created #>> '{booking,id}')::uuid
     returning * into v_booking;
    return v_created || jsonb_build_object(
      'booking', to_jsonb(v_booking),
      'walletCharged', false,
      'importDecision', 'import_only',
      'priorChargeAuthorizationVerified', false
    );
  end if;

  if v_stored_status <> 'confirmed'
     or jsonb_typeof(p_data #> '{passengers,travellers}') <> 'array'
     or jsonb_array_length(case
          when jsonb_typeof(p_data #> '{passengers,travellers}') = 'array'
            then p_data #> '{passengers,travellers}' else '[]'::jsonb end) = 0
     or nullif(btrim(p_data->>'pnr'), '') is null
     or jsonb_typeof(p_data->'ticketNumbers') <> 'array'
     or jsonb_array_length(case
          when jsonb_typeof(p_data->'ticketNumbers') = 'array'
            then p_data->'ticketNumbers' else '[]'::jsonb end)
       <> jsonb_array_length(case
          when jsonb_typeof(p_data #> '{passengers,travellers}') = 'array'
            then p_data #> '{passengers,travellers}' else '[]'::jsonb end)
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(p_data->'ticketNumbers') = 'array'
           then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value)
        where jsonb_typeof(ticket.value) <> 'string'
           or nullif(btrim(ticket.value #>> '{}'), '') is null
     )
     or (select count(distinct ticket.value #>> '{}')
           from jsonb_array_elements(case
             when jsonb_typeof(p_data->'ticketNumbers') = 'array'
               then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value))
        <> jsonb_array_length(case
          when jsonb_typeof(p_data #> '{passengers,travellers}') = 'array'
            then p_data #> '{passengers,travellers}' else '[]'::jsonb end)
     or jsonb_typeof(p_data->'airlinesPnr') <> 'array'
     or jsonb_array_length(case
          when jsonb_typeof(p_data->'airlinesPnr') = 'array'
            then p_data->'airlinesPnr' else '[]'::jsonb end) = 0
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(p_data->'airlinesPnr') = 'array'
           then p_data->'airlinesPnr' else '[]'::jsonb end) airline(value)
        where jsonb_typeof(airline.value) <> 'string'
           or nullif(btrim(airline.value #>> '{}'), '') is null
     ) then
    return jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_CONFIRMED_IMPORT_EVIDENCE_REQUIRED'
    );
  end if;

  v_payload_hash := encode(sha256(convert_to(
    public.impexp_charge_authorization_payload_v1(
      p_assigned_user_id, p_user_payable_amount,
      p_supplier_gross_amount, p_data
    )::text, 'UTF8'
  )), 'hex');
  if p_import_decision = 'import_and_charge' then
    select auth_row.* into v_authorization
      from public.impexp_import_charge_authorizations auth_row
     where auth_row.id = p_charge_authorization_id
     for update;
    if not found
       or v_authorization.actor_user_id <> p_actor_user_id
       or v_authorization.assigned_user_id <> p_assigned_user_id
       or v_authorization.owner_type <> v_owner_type
       or v_authorization.owner_key <> v_owner_key
       or v_authorization.supplier <> v_supplier
       or v_authorization.supplier_reference <> v_supplier_ref
       or v_authorization.currency <> v_currency
       or v_authorization.user_payable_amount <> p_user_payable_amount
       or v_authorization.supplier_gross_amount <> p_supplier_gross_amount
       or v_authorization.authorization_payload_hash <> v_payload_hash
       or v_authorization.expires_at < clock_timestamp()
       or v_authorization.consumed_at is not null then
      return jsonb_build_object(
        'ok', false, 'code', 'FRESH_MATCHING_CHARGE_AUTHORIZATION_REQUIRED'
      );
    end if;
  end if;

  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.owner_type = v_owner_type
     and wallet.owner_key = v_owner_key;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.wallet_id = v_wallet.id
     and account.currency = v_currency;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if p_import_decision = 'import_and_charge' then
    select wallet.* into strict v_wallet
      from public.wallets wallet
     where wallet.id = v_wallet.id
     for update;
    select account.* into strict v_account
      from public.wallet_accounts account
     where account.id = v_account.id
     for update;
    if v_wallet.status <> 'active' then
      return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
    end if;
    if v_account.available_balance < p_user_payable_amount then
      return jsonb_build_object(
        'ok', false, 'code', 'INSUFFICIENT_FUNDS',
        'available', v_account.available_balance,
        'required', p_user_payable_amount,
        'currency', v_currency
      );
    end if;
  end if;

  -- Reuse the mature non-financial import writer by creating a transaction-
  -- local On Hold/Unpaid row, then atomically apply the explicitly selected
  -- direct-confirmed outcome. No observer can see the intermediate row.
  v_safe_data := p_data || jsonb_build_object(
    'storedStatus', 'on-hold',
    'lifecycleStatus', 'on-hold'
  );
  v_created := public.create_impexp_booking(
    p_actor_user_id, p_assigned_user_id, p_user_payable_amount,
    p_supplier_gross_amount, v_safe_data
  );
  if coalesce((v_created->>'ok')::boolean, false) is not true then
    return v_created;
  end if;
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = (v_created #>> '{booking,id}')::uuid
   for update;
  v_imported_at := coalesce(
    nullif(p_data->>'importedAt', '')::timestamptz,
    clock_timestamp()
  );

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  if p_import_decision = 'import_and_charge' then
    update public.wallet_accounts
       set available_balance = available_balance - p_user_payable_amount
     where id = v_account.id;
    insert into public.wallet_reservations (
      wallet_account_id, booking_id, amount, currency, state,
      requested_by_user_id, issued_by_user_id, captured_at
    ) values (
      v_account.id, v_booking.id, p_user_payable_amount, v_currency,
      'captured', p_actor_user_id, p_actor_user_id, v_imported_at
    ) returning * into v_reservation;
    v_ledger_key := 'impexp-payment:' || v_booking.id::text;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'booking_confirm', p_user_payable_amount, v_currency,
      v_available_before, v_available_before - p_user_payable_amount,
      v_hold_before, v_hold_before, v_booking.id, v_booking.public_ref,
      v_reservation.id, v_ledger_key, p_actor_user_id, v_actor_role,
      'Explicitly authorized direct confirmed import and charge',
      jsonb_build_object(
        'importSource', 'IMP_EXP',
        'supplierGrossAmount', p_supplier_gross_amount,
        'userPayableAmount', p_user_payable_amount,
        'directConfirmedImport', true,
        'importDecision', 'import_and_charge',
        'chargeAuthorizationId', v_authorization.id
      )
    );
  end if;

  update public.flight_bookings
     set status = 'confirmed',
         direct_ticketing = true,
         issued_at = v_imported_at,
         issued_by_user_id = p_actor_user_id,
         payment_state = case when p_import_decision = 'import_and_charge'
           then 'captured' else 'unpaid' end,
         payment_amount = case when p_import_decision = 'import_and_charge'
           then p_user_payable_amount else null end,
         captured_amount = case when p_import_decision = 'import_and_charge'
           then p_user_payable_amount else 0 end,
         charged_wallet_account_id = case
           when p_import_decision = 'import_and_charge'
             then v_account.id else null end,
         import_metadata = coalesce(import_metadata, '{}'::jsonb)
           || jsonb_build_object(
             'lifecycleStatus', 'confirmed',
             'importDecision', p_import_decision,
             'importRequestKey', p_request_key,
             'walletChargeAuthorized',
               p_import_decision = 'import_and_charge',
             'chargeAuthorizationId', case
               when p_import_decision = 'import_and_charge'
                 then v_authorization.id else null end
           )
   where id = v_booking.id
   returning * into v_booking;

  if p_import_decision = 'import_only' then
    insert into public.booking_reconciliation_cases (
      subject_booking_id, case_type, state, reason_code, reason_detail,
      opened_source, opened_by_user_id, opened_by_role, opened_at,
      assigned_team, assigned_at, severity, priority, due_at,
      evidence, financial_disposition, policy_version
    ) values (
      v_booking.id, 'imported_payment_conflict', 'awaiting_finance',
      'direct_confirmed_import_uncharged',
      'Confirmed supplier booking was explicitly imported without a wallet charge.',
      'staff', p_actor_user_id, v_actor_role, clock_timestamp(),
      'accounts', clock_timestamp(), 'critical', 90,
      clock_timestamp() + interval '1 hour',
      jsonb_build_array(jsonb_build_object(
        'type', 'direct_confirmed_import_decision',
        'importDecision', 'import_only',
        'supplier', v_supplier,
        'supplierReference', v_supplier_ref,
        'userPayableAmount', p_user_payable_amount,
        'currency', v_currency,
        'walletMutation', false,
        'recordedAt', clock_timestamp()
      )), 'none', 1
    ) returning * into v_case;
  else
    update public.impexp_import_charge_authorizations
       set consumed_at = clock_timestamp(),
           consumed_booking_id = v_booking.id
     where id = v_authorization.id;
  end if;

  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'confirmed';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, reconciliation_case_id,
    occurrence_number, effective_at, observed_at,
    event_snapshot, event_version
  ) values (
    v_booking.id, null, 'confirmed', null, 'confirmed', null,
    case when p_import_decision = 'import_and_charge'
      then 'direct_confirmed_import_charged'
      else 'direct_confirmed_import_uncharged' end,
    p_actor_user_id,
    case when p_import_decision = 'import_and_charge'
      then 'ImportAndCharge' else 'ImportOnly' end,
    jsonb_build_object(
      'importDecision', p_import_decision,
      'chargeAuthorizationId', case
        when p_import_decision = 'import_and_charge'
          then v_authorization.id else null end,
      'walletCharged', p_import_decision = 'import_and_charge'
    ),
    p_request_key || ':confirmed', case
      when p_import_decision = 'import_only' then v_case.id else null end,
    v_occurrence_number, v_imported_at, clock_timestamp(),
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'confirmed',
      'paymentState', v_booking.payment_state,
      'operationSource', 'imported_direct_confirmed',
      'importDecision', p_import_decision,
      'reconciliationCaseId', case
        when p_import_decision = 'import_only' then v_case.id else null end,
      'userPayableAmount', p_user_payable_amount,
      'currency', v_currency
    ), 1
  ) returning id into v_event_id;

  return jsonb_build_object(
    'ok', true, 'replay', false,
    'booking', to_jsonb(v_booking),
    'status', 'confirmed',
    'importDecision', p_import_decision,
    'walletCharged', p_import_decision = 'import_and_charge',
    'priorChargeAuthorizationVerified',
      p_import_decision = 'import_and_charge',
    'chargeAuthorizationId', case
      when p_import_decision = 'import_and_charge'
        then v_authorization.id else null end,
    'reconciliationCaseId', case
      when p_import_decision = 'import_only' then v_case.id else null end,
    'lifecycleEventId', v_event_id,
    'amount', case when p_import_decision = 'import_and_charge'
      then p_user_payable_amount else 0 end,
    'accountId', case when p_import_decision = 'import_and_charge'
      then v_account.id else null end,
    'availableBalance', case when p_import_decision = 'import_and_charge'
      then v_available_before - p_user_payable_amount else null end,
    'currency', v_currency
  );
end;
$$;

revoke all on function public.impexp_charge_authorization_payload_v1(
  text, bigint, bigint, jsonb
) from public, anon, authenticated;
revoke all on function public.authorize_impexp_import_charge_v1(
  text, text, bigint, bigint, jsonb, text
) from public, anon, authenticated;
revoke all on function public.create_impexp_booking_v2(
  text, text, bigint, bigint, jsonb, text, uuid, text
) from public, anon, authenticated;
grant execute on function public.authorize_impexp_import_charge_v1(
  text, text, bigint, bigint, jsonb, text
) to service_role;
grant execute on function public.create_impexp_booking_v2(
  text, text, bigint, bigint, jsonb, text, uuid, text
) to service_role;

-- The application has moved to v2. Keep the old signature only as a private
-- compatibility helper for non-confirmed import inside v2; clients cannot call
-- its legacy direct-confirmed auto-charge behavior.
revoke execute on function public.create_impexp_booking(
  text, text, bigint, bigint, jsonb
) from service_role;

comment on table public.impexp_import_charge_authorizations is
  'Five-minute, one-use server authorizations for an explicit direct-confirmed Import & Charge decision. Stores hashes and normalized identities, never raw supplier/passenger payloads.';
comment on function public.authorize_impexp_import_charge_v1(
  text, text, bigint, bigint, jsonb, text
) is
  'Records a non-financial, payload-bound prior authorization for Import & Charge after verifying complete confirmed supplier evidence and the assigned wallet snapshot.';
comment on function public.create_impexp_booking_v2(
  text, text, bigint, bigint, jsonb, text, uuid, text
) is
  'Imports with an explicit import_only or import_and_charge decision. A direct confirmed charge requires and atomically consumes a fresh matching prior authorization; import_only never changes wallet money and creates an Accounts-owned payment case.';


-- SOURCE: 0068_impexp_pricing_invariants.sql
-- Imported commercial truth has two intentionally independent amounts:
-- Supplier Gross may be refreshed from supplier evidence, while User Payable
-- and its currency are fixed at import and are the only permitted booking
-- capture amount. Enforce that split at every persistence boundary.

create or replace function public.impexp_pricing_minor_amount_v1(
  p_pricing jsonb,
  p_key text
)
returns bigint
language plpgsql
immutable
set search_path = public
as $$
declare
  v_text text;
  v_minor numeric;
begin
  if p_pricing is null
     or jsonb_typeof(p_pricing) <> 'object'
     or nullif(btrim(coalesce(p_key, '')), '') is null
     or jsonb_typeof(p_pricing->p_key) <> 'number' then
    return null;
  end if;
  v_text := p_pricing->>p_key;
  if v_text !~ '^(0|[1-9][0-9]*)(\.[0-9]{1,2})?$' then
    return null;
  end if;
  v_minor := v_text::numeric * 100;
  if v_minor <> trunc(v_minor)
     or v_minor > 9223372036854775807::numeric then
    return null;
  end if;
  return v_minor::bigint;
end;
$$;

alter table public.flight_bookings
  add constraint flight_bookings_impexp_pricing_truth_check
  check (
    import_source is distinct from 'IMP_EXP'
    or (
      user_payable_amount is not null
      and user_payable_amount > 0
      and supplier_gross_amount is not null
      and supplier_gross_amount >= 0
      and public.impexp_pricing_minor_amount_v1(
        pricing_snapshot, 'sellingPrice'
      ) = user_payable_amount
      and public.impexp_pricing_minor_amount_v1(
        pricing_snapshot, 'supplierTotalPrice'
      ) = supplier_gross_amount
      and public.impexp_pricing_minor_amount_v1(
        pricing_snapshot, 'grossPrice'
      ) = supplier_gross_amount
      and (payment_amount is null or payment_amount = user_payable_amount)
      and captured_amount is not null
      and captured_amount in (0, user_payable_amount)
      and refunded_amount is not null
      and refunded_amount between 0 and captured_amount
    )
  ) not valid;

create or replace function public.enforce_impexp_booking_pricing_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' then
    if old.import_source = 'IMP_EXP' then
      if new.import_source is distinct from old.import_source then
        raise exception 'imported booking source is immutable'
          using errcode = '23514',
            constraint = 'flight_bookings_impexp_import_source_immutable';
      end if;
      if new.user_payable_amount is distinct from old.user_payable_amount then
        raise exception 'imported User Payable is immutable'
          using errcode = '23514',
            constraint = 'flight_bookings_impexp_user_payable_immutable';
      end if;
      if new.currency is distinct from old.currency then
        raise exception 'imported User Payable currency is immutable'
          using errcode = '23514',
            constraint = 'flight_bookings_impexp_currency_immutable';
      end if;
    end if;
  end if;

  if new.import_source is distinct from 'IMP_EXP' then
    return new;
  end if;
  if new.user_payable_amount is null or new.user_payable_amount <= 0
     or new.supplier_gross_amount is null or new.supplier_gross_amount < 0
     or public.impexp_pricing_minor_amount_v1(
          new.pricing_snapshot, 'sellingPrice'
        ) is distinct from new.user_payable_amount
     or public.impexp_pricing_minor_amount_v1(
          new.pricing_snapshot, 'supplierTotalPrice'
        ) is distinct from new.supplier_gross_amount
     or public.impexp_pricing_minor_amount_v1(
          new.pricing_snapshot, 'grossPrice'
        ) is distinct from new.supplier_gross_amount
     or (new.payment_amount is not null
       and new.payment_amount is distinct from new.user_payable_amount)
     or new.captured_amount is null
     or new.captured_amount not in (0, new.user_payable_amount)
     or new.refunded_amount is null
     or new.refunded_amount < 0
     or new.refunded_amount > new.captured_amount then
    raise exception 'imported Supplier Gross/User Payable invariant failed'
      using errcode = '23514',
        constraint = 'flight_bookings_impexp_pricing_truth_check';
  end if;
  return new;
end;
$$;

drop trigger if exists flight_bookings_enforce_impexp_pricing
  on public.flight_bookings;
create trigger flight_bookings_enforce_impexp_pricing
  before insert or update of
    import_source, currency, pricing_snapshot, supplier_gross_amount,
    user_payable_amount, payment_state, payment_amount, captured_amount,
    refunded_amount
  on public.flight_bookings
  for each row execute function public.enforce_impexp_booking_pricing_v1();

create or replace function public.enforce_impexp_reservation_amount_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
begin
  if new.booking_id is null then
    return new;
  end if;
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = new.booking_id;
  if found and v_booking.import_source = 'IMP_EXP'
     and (new.amount is distinct from v_booking.user_payable_amount
       or upper(new.currency) is distinct from upper(v_booking.currency)) then
    raise exception 'imported reservation must equal protected User Payable'
      using errcode = '23514',
        constraint = 'wallet_reservations_impexp_user_payable_check';
  end if;
  return new;
end;
$$;

drop trigger if exists wallet_reservations_enforce_impexp_amount
  on public.wallet_reservations;
create trigger wallet_reservations_enforce_impexp_amount
  before insert or update of booking_id, amount, currency
  on public.wallet_reservations
  for each row execute function public.enforce_impexp_reservation_amount_v1();

create or replace function public.enforce_impexp_capture_ledger_amount_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
begin
  if new.booking_id is null or new.transaction_type <> 'booking_confirm' then
    return new;
  end if;
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = new.booking_id;
  if found and v_booking.import_source = 'IMP_EXP'
     and (new.amount is distinct from v_booking.user_payable_amount
       or upper(new.currency) is distinct from upper(v_booking.currency)
       or new.metadata->>'userPayableAmount'
          is distinct from v_booking.user_payable_amount::text
       or new.metadata->>'supplierGrossAmount'
          is distinct from v_booking.supplier_gross_amount::text) then
    raise exception 'imported capture ledger must equal protected User Payable'
      using errcode = '23514',
        constraint = 'wallet_ledger_entries_impexp_user_payable_check';
  end if;
  return new;
end;
$$;

drop trigger if exists wallet_ledger_enforce_impexp_capture_amount
  on public.wallet_ledger_entries;
create trigger wallet_ledger_enforce_impexp_capture_amount
  before insert on public.wallet_ledger_entries
  for each row execute function public.enforce_impexp_capture_ledger_amount_v1();

revoke all on function public.impexp_pricing_minor_amount_v1(jsonb, text)
  from public, anon, authenticated;
grant execute on function public.impexp_pricing_minor_amount_v1(jsonb, text)
  to service_role;
revoke all on function public.enforce_impexp_booking_pricing_v1()
  from public, anon, authenticated;
revoke all on function public.enforce_impexp_reservation_amount_v1()
  from public, anon, authenticated;
revoke all on function public.enforce_impexp_capture_ledger_amount_v1()
  from public, anon, authenticated;

comment on constraint flight_bookings_impexp_pricing_truth_check
  on public.flight_bookings is
  'New or updated IMP_EXP rows keep Supplier Gross in supplier pricing fields, keep protected User Payable in selling/payment/capture fields, and never conflate the two.';
comment on function public.enforce_impexp_booking_pricing_v1() is
  'Makes imported User Payable and currency immutable while allowing a synchronized Supplier Gross only when its pricing snapshot changes consistently.';
comment on function public.enforce_impexp_reservation_amount_v1() is
  'Rejects imported booking reservations whose amount/currency differ from protected User Payable.';
comment on function public.enforce_impexp_capture_ledger_amount_v1() is
  'Rejects imported booking-confirm ledger debits or metadata that substitute Supplier Gross for protected User Payable.';


-- SOURCE: 0069_booking_lifecycle_timestamp_contract.sql
-- Explicit lifecycle timestamp semantics.
--
-- Every timestamp in this migration is an independently stored fact. Missing
-- business time remains NULL: booking creation/update time is never substituted
-- for submission, operation, supplier, case, status, terminal, deadline, or
-- completion time.

-- Future lifecycle events always record when this system observed the status
-- fact. Callers may provide an earlier, authoritative observed_at (for example,
-- from a normalized supplier evidence receipt); otherwise the insert boundary
-- is the observation boundary. effective_at remains nullable unless the
-- business-effective instant is authoritatively known.
create or replace function public.normalize_booking_status_event_time_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.observed_at is null then
    new.observed_at := clock_timestamp();
  end if;
  return new;
end;
$$;

drop trigger if exists booking_status_events_normalize_time
  on public.booking_status_events;
create trigger booking_status_events_normalize_time
  before insert on public.booking_status_events
  for each row execute function public.normalize_booking_status_event_time_v1();

revoke all on function public.normalize_booking_status_event_time_v1()
  from public, anon, authenticated, service_role;

comment on function public.normalize_booking_status_event_time_v1() is
  'Records the exact local observation boundary for new lifecycle events when a caller has no authoritative observed_at; never invents effective_at.';

-- One staff-only, one-row-per-booking contract for the currently relevant
-- operation, case, and latest lifecycle occurrence. IDs expose the provenance
-- of each joined timestamp. Ordering is deterministic and does not rank a row
-- by a fallback timestamp masquerading as another business fact.
create or replace view public.booking_lifecycle_timestamps_v
with (security_invoker = true)
as
select
  booking.id as booking_id,
  operation.id as operation_id,
  reconciliation_case.id as reconciliation_case_id,
  status_event.id as status_event_id,
  status_event.occurrence_id as status_occurrence_id,
  booking.submission_started_at,
  operation.claimed_at as operation_claimed_at,
  operation.supplier_call_started_at,
  operation.supplier_response_received_at,
  reconciliation_case.opened_at as case_opened_at,
  status_event.effective_at as status_effective_at,
  status_event.observed_at as status_observed_at,
  booking.issued_at,
  booking.cancelled_at,
  booking.ticketing_deadline_at,
  operation.completed_at as operation_completed_at
from public.flight_bookings booking
left join lateral (
  select candidate.*
  from public.booking_operations candidate
  where candidate.booking_id = booking.id
  order by
    (candidate.id = booking.active_operation_id) desc nulls last,
    candidate.claimed_at desc,
    candidate.id desc
  limit 1
) operation on true
left join lateral (
  select candidate.*
  from public.booking_reconciliation_cases candidate
  where candidate.subject_booking_id = booking.id
  order by
    (candidate.operation_id = operation.id) desc nulls last,
    (candidate.state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    )) desc,
    candidate.opened_at desc,
    candidate.id desc
  limit 1
) reconciliation_case on true
left join lateral (
  select candidate.*
  from public.booking_status_events candidate
  where candidate.booking_id = booking.id
  order by candidate.id desc
  limit 1
) status_event on true
where not booking.legacy_operational;

revoke all on table public.booking_lifecycle_timestamps_v
  from public, anon, authenticated;
grant select on table public.booking_lifecycle_timestamps_v to service_role;

comment on view public.booking_lifecycle_timestamps_v is
  'Staff-only exact lifecycle timestamp contract. NULL means the fact is unknown; no created_at or updated_at fallback is used.';

comment on column public.flight_bookings.submission_started_at is
  'Instant the booking submission began; NULL when no authoritative submission start was recorded.';
comment on column public.booking_operations.claimed_at is
  'Instant an actor durably claimed the operation identity; not booking creation or submission time.';
comment on column public.booking_operations.supplier_call_started_at is
  'Instant immediately before the irreversible supplier write call began.';
comment on column public.booking_operations.supplier_response_received_at is
  'Instant the complete supplier write response was received; NULL for no complete response.';
comment on column public.booking_reconciliation_cases.opened_at is
  'Instant the owned reconciliation case was opened.';
comment on column public.booking_status_events.effective_at is
  'Business-effective status instant when authoritatively known; NULL must remain unknown.';
comment on column public.booking_status_events.observed_at is
  'Instant this system observed the status fact; all events inserted after migration 0069 record it.';
comment on column public.flight_bookings.issued_at is
  'Authoritative ticket-issuance instant; NULL does not mean the booking was not issued.';
comment on column public.flight_bookings.cancelled_at is
  'Authoritative cancellation instant; NULL does not mean the booking was not cancelled.';
comment on column public.flight_bookings.ticketing_deadline_at is
  'Normalized supplier ticketing deadline when known; never inferred from booking update time.';
comment on column public.booking_operations.completed_at is
  'Instant the durable operation reached succeeded or failed; separate from supplier response time.';


-- SOURCE: 0070_booking_notification_grace_supersession.sql
-- Coalesce short ordinary In Progress occurrences without erasing history.
--
-- A Confirmed or Cancelled event inserted before an ordinary In Progress grace
-- window expires creates its own immediately eligible outbox intent, then marks
-- the still-pending intermediate intent superseded. Both lifecycle events and
-- both outbox rows remain durable and linked.

create or replace function public.enqueue_booking_lifecycle_event_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_booking_ref text;
  v_payment_state text;
  v_policy text := 'send';
  v_available_at timestamptz;
  v_grace_expires_at timestamptz;
  v_snapshot jsonb;
  v_outbox_id uuid;
begin
  if new.to_lifecycle_status not in (
    'on-hold', 'pending', 'in-progress', 'confirmed',
    'expired', 'unconfirmed', 'cancelled'
  ) then
    raise exception 'unsupported lifecycle notification status'
      using errcode = '23514';
  end if;
  select booking.public_ref, booking.payment_state
    into v_booking_ref, v_payment_state
    from public.flight_bookings booking
   where booking.id = new.booking_id;
  if not found then
    raise exception 'notification booking not found' using errcode = '23503';
  end if;

  if new.to_lifecycle_status = 'in-progress'
     and new.operation_kind in ('ticketing', 'cancellation')
     and coalesce(
       new.event_snapshot->>'operationSource',
       case when new.operation_kind = 'imported_manual_ticketing'
         then 'imported_manual_ticketing' else 'triplover' end
     ) <> 'imported_manual_ticketing' then
    v_policy := 'grace';
    v_grace_expires_at := v_now + interval '120 seconds';
    v_available_at := v_grace_expires_at;
  else
    v_available_at := v_now;
  end if;

  v_snapshot := coalesce(new.event_snapshot, '{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'version', greatest(coalesce(new.event_version, 1), 1),
      'bookingReference', v_booking_ref,
      'lifecycleStatus', new.to_lifecycle_status,
      'paymentState', v_payment_state,
      'occurrenceId', new.occurrence_id,
      'occurrenceNumber', new.occurrence_number,
      'effectiveAt', new.effective_at,
      'observedAt', coalesce(new.observed_at, v_now)
    ));

  insert into public.booking_notification_outbox (
    lifecycle_event_id, booking_id, notification_kind,
    lifecycle_status, event_snapshot, delivery_policy,
    state, policy_version, available_at, grace_expires_at
  ) values (
    new.id, new.booking_id, 'booking_status',
    new.to_lifecycle_status, v_snapshot, v_policy,
    'pending', 1, v_available_at, v_grace_expires_at
  )
  on conflict (lifecycle_event_id, notification_kind) do nothing
  returning id into v_outbox_id;

  if v_outbox_id is null then
    select candidate.id into v_outbox_id
      from public.booking_notification_outbox candidate
     where candidate.lifecycle_event_id = new.id
       and candidate.notification_kind = 'booking_status';
  end if;

  if new.to_lifecycle_status in ('confirmed', 'cancelled') then
    update public.booking_notification_outbox intermediate
       set state = 'superseded',
           suppression_reason = 'terminal_during_in_progress_grace',
           superseded_by_outbox_id = v_outbox_id,
           completed_at = v_now
     where intermediate.booking_id = new.booking_id
       and intermediate.id <> v_outbox_id
       and intermediate.lifecycle_status = 'in-progress'
       and intermediate.delivery_policy = 'grace'
       and intermediate.state = 'pending'
       and intermediate.grace_expires_at > v_now;
  end if;

  return new;
end;
$$;

revoke all on function public.enqueue_booking_lifecycle_event_v1()
  from public, anon, authenticated, service_role;

comment on function public.enqueue_booking_lifecycle_event_v1() is
  'Creates one render-safe occurrence outbox row atomically. A Confirmed/Cancelled occurrence supersedes any still-pending ordinary In Progress grace intent for the same booking while retaining both events and intents.';


-- SOURCE: 0071_booking_notification_occurrence_delivery.sql
-- Occurrence-aware notification claims and recipient registration.
--
-- Legacy booking_status_email_deliveries remains immutable rollout evidence.
-- New work is identified by lifecycle event/outbox, and each normalized
-- recipient has one durable row per outbox occurrence.

create or replace function public.claim_booking_notification_outbox_v1(
  p_limit integer default 25,
  p_booking_id uuid default null
)
returns table (
  outbox_id uuid,
  lifecycle_event_id bigint,
  booking_id uuid,
  occurrence_id uuid,
  lifecycle_status text,
  event_snapshot jsonb,
  claim_token uuid,
  attempt_count integer
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with candidates as (
    select candidate.id
      from public.booking_notification_outbox candidate
     where candidate.state = 'pending'
       and candidate.delivery_policy in ('send', 'grace')
       and candidate.available_at <= clock_timestamp()
       and (p_booking_id is null or candidate.booking_id = p_booking_id)
     order by candidate.available_at, candidate.created_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 25), 100))
  ), claimed as (
    update public.booking_notification_outbox target
       set state = 'processing',
           claimed_at = clock_timestamp(),
           claim_token = gen_random_uuid(),
           attempt_count = target.attempt_count + 1,
           last_error = null
      from candidates
     where target.id = candidates.id
     returning target.*
  )
  select
    claimed.id,
    claimed.lifecycle_event_id,
    claimed.booking_id,
    event.occurrence_id,
    claimed.lifecycle_status,
    claimed.event_snapshot,
    claimed.claim_token,
    claimed.attempt_count
  from claimed
  join public.booking_status_events event
    on event.id = claimed.lifecycle_event_id
  order by claimed.available_at, claimed.created_at, claimed.id;
end;
$$;

create or replace function public.register_booking_notification_delivery_v1(
  p_outbox_id uuid,
  p_claim_token uuid,
  p_recipient_kind text,
  p_recipient_address text
)
returns table (
  delivery_id uuid,
  outbox_id uuid,
  recipient_kind text,
  recipient_address text,
  recipient_address_hash text,
  is_hidden_copy boolean,
  state text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_outbox public.booking_notification_outbox;
  v_address text := lower(btrim(coalesce(p_recipient_address, '')));
  v_address_hash text;
begin
  if p_recipient_kind not in (
    'customer_contact', 'booking_user', 'agency_user', 'system_copy'
  ) then
    raise exception 'invalid notification recipient kind' using errcode = '22023';
  end if;
  if v_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or char_length(v_address) > 320 then
    raise exception 'invalid notification recipient address' using errcode = '22023';
  end if;
  select candidate.* into v_outbox
    from public.booking_notification_outbox candidate
   where candidate.id = p_outbox_id
   for update;
  if not found then
    raise exception 'notification outbox not found' using errcode = 'P0002';
  end if;
  if v_outbox.state <> 'processing'
     or v_outbox.claim_token is distinct from p_claim_token then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;

  v_address_hash := encode(digest(v_address, 'sha256'), 'hex');
  insert into public.booking_notification_deliveries (
    outbox_id, recipient_kind, recipient_address,
    recipient_address_hash, is_hidden_copy, channel,
    state, next_attempt_at
  ) values (
    p_outbox_id, p_recipient_kind, v_address,
    v_address_hash, p_recipient_kind = 'system_copy', 'email',
    'pending', clock_timestamp()
  )
  on conflict (outbox_id, channel, recipient_address_hash) do nothing;

  return query
  select
    delivery.id,
    delivery.outbox_id,
    delivery.recipient_kind,
    delivery.recipient_address,
    delivery.recipient_address_hash,
    delivery.is_hidden_copy,
    delivery.state
  from public.booking_notification_deliveries delivery
  where delivery.outbox_id = p_outbox_id
    and delivery.channel = 'email'
    and delivery.recipient_address_hash = v_address_hash;
end;
$$;

revoke all on function public.claim_booking_notification_outbox_v1(integer,uuid),
  public.register_booking_notification_delivery_v1(uuid,uuid,text,text)
  from public, anon, authenticated;
grant execute on function public.claim_booking_notification_outbox_v1(integer,uuid),
  public.register_booking_notification_delivery_v1(uuid,uuid,text,text)
  to service_role;

comment on function public.claim_booking_notification_outbox_v1(integer,uuid) is
  'Claims eligible notification event occurrences with SKIP LOCKED. Legacy once-per-booking/status delivery rows are not consulted.';
comment on function public.register_booking_notification_delivery_v1(uuid,uuid,text,text) is
  'Registers one normalized recipient per outbox occurrence and address hash. Exact replay returns the same delivery row.';


-- SOURCE: 0072_booking_notification_reentry_policy.sql
-- Material lifecycle re-entry notification policy.
--
-- Returning to On Hold, Pending, In Progress, Expired, or Unconfirmed after a
-- different lifecycle state is a new customer occurrence. Repeating the same
-- non-terminal state without leaving it is audit-only. Historical/backfill and
-- timestamp/case-only repairs may suppress only with an approved explicit code.

create or replace function public.resolve_booking_notification_policy_v1(
  p_from_lifecycle_status text,
  p_to_lifecycle_status text,
  p_operation_kind text,
  p_supplier_operation text,
  p_event_snapshot jsonb
)
returns table (
  resolved_policy text,
  resolved_suppression_reason text,
  resolved_grace_seconds integer
)
language plpgsql
immutable
set search_path = public
as $$
declare
  v_disposition text := nullif(
    btrim(coalesce(p_event_snapshot->>'notificationDisposition', '')), ''
  );
  v_reason text := nullif(
    btrim(coalesce(p_event_snapshot->>'suppressionReason', '')), ''
  );
begin
  if v_disposition is not null and v_disposition <> 'audit_only' then
    raise exception 'invalid notification disposition' using errcode = '22023';
  end if;
  if v_disposition = 'audit_only' then
    if v_reason not in (
      'historical_baseline', 'backfill_observation', 'timestamp_repair',
      'case_only_repair'
    ) then
      raise exception 'unapproved notification suppression reason'
        using errcode = '22023';
    end if;
    return query select 'suppress'::text, v_reason, null::integer;
    return;
  end if;

  if p_supplier_operation = 'MigrationBaseline' then
    return query
      select 'suppress'::text, 'historical_baseline'::text, null::integer;
    return;
  end if;

  if p_to_lifecycle_status in (
       'on-hold', 'pending', 'in-progress', 'expired', 'unconfirmed'
     )
     and p_from_lifecycle_status = p_to_lifecycle_status then
    return query
      select 'suppress'::text, 'non_material_same_status'::text, null::integer;
    return;
  end if;

  if p_to_lifecycle_status = 'in-progress'
     and p_operation_kind in ('ticketing', 'cancellation')
     and coalesce(
       p_event_snapshot->>'operationSource',
       case when p_operation_kind = 'imported_manual_ticketing'
         then 'imported_manual_ticketing' else 'triplover' end
     ) <> 'imported_manual_ticketing' then
    return query select 'grace'::text, null::text, 120;
    return;
  end if;

  return query select 'send'::text, null::text, 0;
end;
$$;

create or replace function public.enqueue_booking_lifecycle_event_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_booking_ref text;
  v_payment_state text;
  v_policy text;
  v_suppression_reason text;
  v_grace_seconds integer;
  v_available_at timestamptz;
  v_grace_expires_at timestamptz;
  v_snapshot jsonb;
  v_outbox_id uuid;
  v_state text;
  v_completed_at timestamptz;
begin
  if new.to_lifecycle_status not in (
    'on-hold', 'pending', 'in-progress', 'confirmed',
    'expired', 'unconfirmed', 'cancelled'
  ) then
    raise exception 'unsupported lifecycle notification status'
      using errcode = '23514';
  end if;
  select booking.public_ref, booking.payment_state
    into v_booking_ref, v_payment_state
    from public.flight_bookings booking
   where booking.id = new.booking_id;
  if not found then
    raise exception 'notification booking not found' using errcode = '23503';
  end if;

  select policy.resolved_policy,
         policy.resolved_suppression_reason,
         policy.resolved_grace_seconds
    into v_policy, v_suppression_reason, v_grace_seconds
    from public.resolve_booking_notification_policy_v1(
      new.from_lifecycle_status,
      new.to_lifecycle_status,
      new.operation_kind,
      new.supplier_operation,
      coalesce(new.event_snapshot, '{}'::jsonb)
    ) policy;

  if v_policy = 'grace' then
    v_grace_expires_at := v_now + make_interval(secs => v_grace_seconds);
    v_available_at := v_grace_expires_at;
  else
    v_available_at := v_now;
  end if;
  if v_policy = 'suppress' then
    v_state := 'suppressed';
    v_completed_at := v_now;
  else
    v_state := 'pending';
  end if;

  v_snapshot := coalesce(new.event_snapshot, '{}'::jsonb)
    || jsonb_strip_nulls(jsonb_build_object(
      'version', greatest(coalesce(new.event_version, 1), 1),
      'bookingReference', v_booking_ref,
      'lifecycleStatus', new.to_lifecycle_status,
      'paymentState', v_payment_state,
      'occurrenceId', new.occurrence_id,
      'occurrenceNumber', new.occurrence_number,
      'effectiveAt', new.effective_at,
      'observedAt', coalesce(new.observed_at, v_now)
    ));

  insert into public.booking_notification_outbox (
    lifecycle_event_id, booking_id, notification_kind,
    lifecycle_status, event_snapshot, delivery_policy,
    state, policy_version, available_at, grace_expires_at,
    suppression_reason, completed_at
  ) values (
    new.id, new.booking_id, 'booking_status',
    new.to_lifecycle_status, v_snapshot, v_policy,
    v_state, 1, v_available_at, v_grace_expires_at,
    v_suppression_reason, v_completed_at
  )
  on conflict (lifecycle_event_id, notification_kind) do nothing
  returning id into v_outbox_id;

  if v_outbox_id is null then
    select candidate.id into v_outbox_id
      from public.booking_notification_outbox candidate
     where candidate.lifecycle_event_id = new.id
       and candidate.notification_kind = 'booking_status';
  end if;

  if v_policy <> 'suppress'
     and new.to_lifecycle_status in ('confirmed', 'cancelled') then
    update public.booking_notification_outbox intermediate
       set state = 'superseded',
           suppression_reason = 'terminal_during_in_progress_grace',
           superseded_by_outbox_id = v_outbox_id,
           completed_at = v_now
     where intermediate.booking_id = new.booking_id
       and intermediate.id <> v_outbox_id
       and intermediate.lifecycle_status = 'in-progress'
       and intermediate.delivery_policy = 'grace'
       and intermediate.state = 'pending'
       and intermediate.grace_expires_at > v_now;
  end if;

  return new;
end;
$$;

revoke all on function public.resolve_booking_notification_policy_v1(
  text,text,text,text,jsonb
) from public, anon, authenticated;
grant execute on function public.resolve_booking_notification_policy_v1(
  text,text,text,text,jsonb
) to service_role;
revoke all on function public.enqueue_booking_lifecycle_event_v1()
  from public, anon, authenticated, service_role;

comment on function public.resolve_booking_notification_policy_v1(
  text,text,text,text,jsonb
) is 'Version-1 material occurrence policy. Cross-status non-terminal re-entry sends again; same-status non-terminal and approved historical/timestamp/case-only repair are retained as suppressed outbox evidence.';


-- SOURCE: 0073_booking_notification_render_snapshot.sql
-- Immutable email render snapshot captured at lifecycle-event time.
--
-- The snapshot contains the booking document fields the customer email uses,
-- a minimized passenger projection, and no recipient address, contact phone,
-- supplier capability token, passport number, or passport expiry. A later
-- booking/profile edit cannot change the meaning of this occurrence.

create or replace function public.enrich_booking_notification_snapshot_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_event public.booking_status_events;
  v_booking public.flight_bookings;
  v_profile public.user_profiles;
  v_header jsonb;
  v_company public.company_settings;
  v_travellers jsonb;
begin
  select * into strict v_company from public.company_settings where id;
  select candidate.* into v_event
    from public.booking_status_events candidate
   where candidate.id = new.lifecycle_event_id;
  if not found or v_event.booking_id <> new.booking_id then
    raise exception 'notification event identity mismatch' using errcode = '23503';
  end if;
  select candidate.* into v_booking
    from public.flight_bookings candidate
   where candidate.id = new.booking_id;
  if not found then
    raise exception 'notification booking not found' using errcode = '23503';
  end if;

  if v_booking.audience = 'agency' and v_booking.agency_code is not null then
    select profile.* into v_profile
      from public.agencies agency
      join public.user_profiles profile
        on profile.clerk_id = agency.owner_user_id
     where agency.agency_code = v_booking.agency_code;
  end if;
  if v_booking.audience = 'agency' then
    v_header := jsonb_build_object(
      'name', coalesce(nullif(btrim(v_profile.agency_name), ''),
        v_booking.agency_code, v_company.display_name),
      'licenseNo', coalesce(nullif(btrim(v_profile.agency_license_no), ''),
        coalesce(v_company.license_number, '--')),
      'mobile', coalesce(nullif(btrim(v_profile.agency_mobile), ''), '--'),
      'email', coalesce(nullif(btrim(v_profile.agency_email), ''), '--'),
      'address', coalesce(nullif(btrim(v_profile.agency_address), ''), '--'),
      'logoUrl', null
    );
  else
    v_header := jsonb_build_object(
      'name', v_company.display_name,
      'licenseNo', coalesce(v_company.license_number, '--'),
      'mobile', coalesce(v_company.phone, '--'),
      'email', coalesce(v_company.email, '--'),
      'address',
        coalesce(v_company.address, '--'),
      'logoUrl', null
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'passengerType', traveller->>'passengerType',
    'title', traveller->>'title',
    'firstName', traveller->>'firstName',
    'lastName', traveller->>'lastName',
    'gender', traveller->>'gender',
    'dateOfBirth', traveller->>'dateOfBirth',
    'nationality', traveller->>'nationality'
  ) order by ordinal), '[]'::jsonb)
    into v_travellers
    from jsonb_array_elements(
      case
        when jsonb_typeof(v_booking.passengers->'travellers') = 'array'
          then v_booking.passengers->'travellers'
        else '[]'::jsonb
      end
    ) with ordinality as item(traveller, ordinal);

  -- Remove any caller-provided bookingSnapshot before writing enforced fields.
  new.event_snapshot := (coalesce(new.event_snapshot, '{}'::jsonb)
      - 'bookingSnapshot')
    || jsonb_build_object('bookingSnapshot', jsonb_build_object(
      'snapshotVersion', 1,
      'bookingId', v_booking.id,
      'publicRef', v_booking.public_ref,
      'lifecycleStatus', v_event.to_lifecycle_status,
      'storedStatus', v_booking.status,
      'audience', v_booking.audience,
      'agencyCode', v_booking.agency_code,
      'supplier', v_booking.supplier,
      'importSource', v_booking.import_source,
      'paymentState', v_booking.payment_state,
      'currency', v_booking.currency,
      'pricingSnapshot', v_booking.pricing_snapshot,
      'supplierGrossAmount', v_booking.supplier_gross_amount,
      'passengerCounts', v_booking.passenger_counts,
      'travelDate', v_booking.travel_date,
      'directTicketing', v_booking.direct_ticketing,
      'passportRequired', coalesce(v_booking.passport_required, true),
      'itinerary', v_booking.itinerary,
      'fares', coalesce(v_booking.fares, '[]'::jsonb),
      'repricedAt', v_booking.repriced_at,
      'pnr', v_booking.pnr,
      'airlinesPnr', coalesce(v_booking.airlines_pnr, '[]'::jsonb),
      'bookingRefNumber', v_booking.booking_ref_number,
      'bookingStatus', v_booking.booking_status,
      'ticketingTimeLimit', v_booking.ticketing_time_limit,
      'ticketingDeadlineAt', v_booking.ticketing_deadline_at,
      'ticketNumbers', coalesce(v_booking.ticket_numbers, '[]'::jsonb),
      'warnings', coalesce(v_booking.warnings, '[]'::jsonb),
      'submissionStartedAt', v_booking.submission_started_at,
      'bookedAt', coalesce(v_booking.submission_started_at, v_booking.created_at),
      'processingSince', case when v_event.to_lifecycle_status = 'in-progress'
        then v_booking.operation_started_at else null end,
      'issuedAt', v_booking.issued_at,
      'cancelledAt', v_booking.cancelled_at,
      'operationKind', v_event.operation_kind,
      'operationReason', v_event.operation_reason,
      'headerContact', v_header,
      'travellers', v_travellers
    ));
  return new;
end;
$$;

drop trigger if exists booking_notification_outbox_render_snapshot
  on public.booking_notification_outbox;
create trigger booking_notification_outbox_render_snapshot
  before insert on public.booking_notification_outbox
  for each row execute function public.enrich_booking_notification_snapshot_v1();

revoke all on function public.enrich_booking_notification_snapshot_v1()
  from public, anon, authenticated, service_role;

-- If an event lands in the schema-first rollout interval after 0060 but before
-- this snapshot trigger exists, its historical document cannot be recreated
-- exactly. Keep it as explicit non-send evidence; the old worker remains the
-- delivery authority until the application cutover.
update public.booking_notification_outbox
   set delivery_policy = 'suppress',
       state = 'suppressed',
       suppression_reason = 'pre_snapshot_cutover_legacy_delivery',
       completed_at = clock_timestamp(),
       claimed_at = null,
       claim_token = null
 where state in ('pending', 'processing')
   and not (event_snapshot ? 'bookingSnapshot');

comment on function public.enrich_booking_notification_snapshot_v1() is
  'Enforces versioned event-time email document data without recipient/contact addresses, supplier tokens, or passenger passport fields.';


-- SOURCE: 0074_booking_notification_recipient_delivery.sql
-- Independent visible-recipient delivery and partial retry.

alter table public.booking_notification_outbox
  add column if not exists recipients_expanded_at timestamptz;

create or replace function public.claim_booking_notification_outbox_v2(
  p_limit integer default 25,
  p_booking_id uuid default null
)
returns table (
  outbox_id uuid,
  lifecycle_event_id bigint,
  booking_id uuid,
  occurrence_id uuid,
  lifecycle_status text,
  event_snapshot jsonb,
  recipients_expanded boolean,
  claim_token uuid,
  attempt_count integer
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with candidates as (
    select candidate.id
      from public.booking_notification_outbox candidate
     where candidate.state = 'pending'
       and candidate.delivery_policy in ('send', 'grace')
       and candidate.available_at <= clock_timestamp()
       and candidate.attempt_count < candidate.max_attempts
       and (p_booking_id is null or candidate.booking_id = p_booking_id)
     order by candidate.available_at, candidate.created_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 25), 100))
  ), claimed as (
    update public.booking_notification_outbox target
       set state = 'processing',
           claimed_at = clock_timestamp(),
           claim_token = gen_random_uuid(),
           attempt_count = target.attempt_count + 1,
           last_error = null
      from candidates
     where target.id = candidates.id
     returning target.*
  )
  select
    claimed.id,
    claimed.lifecycle_event_id,
    claimed.booking_id,
    event.occurrence_id,
    claimed.lifecycle_status,
    claimed.event_snapshot,
    claimed.recipients_expanded_at is not null,
    claimed.claim_token,
    claimed.attempt_count
  from claimed
  join public.booking_status_events event
    on event.id = claimed.lifecycle_event_id
  order by claimed.available_at, claimed.created_at, claimed.id;
end;
$$;

create or replace function public.register_booking_notification_delivery_v1(
  p_outbox_id uuid,
  p_claim_token uuid,
  p_recipient_kind text,
  p_recipient_address text
)
returns table (
  delivery_id uuid,
  outbox_id uuid,
  recipient_kind text,
  recipient_address text,
  recipient_address_hash text,
  is_hidden_copy boolean,
  state text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_outbox public.booking_notification_outbox;
  v_address text := lower(btrim(coalesce(p_recipient_address, '')));
  v_address_hash text;
  v_existing public.booking_notification_deliveries;
begin
  if p_recipient_kind not in (
    'customer_contact', 'booking_user', 'agency_user', 'system_copy'
  ) then
    raise exception 'invalid notification recipient kind' using errcode = '22023';
  end if;
  if v_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or char_length(v_address) > 320 then
    raise exception 'invalid notification recipient address' using errcode = '22023';
  end if;
  select candidate.* into v_outbox
    from public.booking_notification_outbox candidate
   where candidate.id = p_outbox_id
   for update;
  if not found then
    raise exception 'notification outbox not found' using errcode = 'P0002';
  end if;
  if v_outbox.state <> 'processing'
     or v_outbox.claim_token is distinct from p_claim_token then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;

  v_address_hash := encode(digest(v_address, 'sha256'), 'hex');
  select delivery.* into v_existing
    from public.booking_notification_deliveries delivery
   where delivery.outbox_id = p_outbox_id
     and delivery.channel = 'email'
     and delivery.recipient_address_hash = v_address_hash;
  if found then
    return query select
      v_existing.id, v_existing.outbox_id, v_existing.recipient_kind,
      v_existing.recipient_address, v_existing.recipient_address_hash,
      v_existing.is_hidden_copy, v_existing.state;
    return;
  end if;
  if v_outbox.recipients_expanded_at is not null then
    raise exception 'notification recipient set is immutable'
      using errcode = '23514';
  end if;

  insert into public.booking_notification_deliveries (
    outbox_id, recipient_kind, recipient_address,
    recipient_address_hash, is_hidden_copy, channel,
    state, next_attempt_at
  ) values (
    p_outbox_id, p_recipient_kind, v_address,
    v_address_hash, p_recipient_kind = 'system_copy', 'email',
    'pending', clock_timestamp()
  ) returning * into v_existing;
  return query select
    v_existing.id, v_existing.outbox_id, v_existing.recipient_kind,
    v_existing.recipient_address, v_existing.recipient_address_hash,
    v_existing.is_hidden_copy, v_existing.state;
end;
$$;

create or replace function public.complete_booking_notification_recipient_expansion_v1(
  p_outbox_id uuid,
  p_claim_token uuid
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare v_count integer;
begin
  perform 1 from public.booking_notification_outbox candidate
   where candidate.id = p_outbox_id
     and candidate.state = 'processing'
     and candidate.claim_token = p_claim_token
   for update;
  if not found then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;
  select count(*)::integer into v_count
    from public.booking_notification_deliveries delivery
   where delivery.outbox_id = p_outbox_id
     and not delivery.is_hidden_copy;
  if v_count = 0 then
    raise exception 'notification has no visible recipient' using errcode = '23514';
  end if;
  update public.booking_notification_outbox
     set recipients_expanded_at = coalesce(
       recipients_expanded_at, clock_timestamp()
     )
   where id = p_outbox_id;
  return true;
end;
$$;

create or replace function public.claim_booking_notification_deliveries_v1(
  p_outbox_id uuid,
  p_outbox_claim_token uuid,
  p_limit integer default 25
)
returns table (
  delivery_id uuid,
  recipient_kind text,
  recipient_address text,
  recipient_address_hash text,
  is_hidden_copy boolean,
  rendered_content jsonb,
  delivery_claim_token uuid,
  attempt_count integer
)
language plpgsql
security definer
set search_path = public
as $$
begin
  perform 1 from public.booking_notification_outbox candidate
   where candidate.id = p_outbox_id
     and candidate.state = 'processing'
     and candidate.claim_token = p_outbox_claim_token
     and candidate.recipients_expanded_at is not null
   for update;
  if not found then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;
  return query
  with candidates as (
    select candidate.id
      from public.booking_notification_deliveries candidate
     where candidate.outbox_id = p_outbox_id
       and candidate.state in ('pending', 'retry')
       and candidate.next_attempt_at <= clock_timestamp()
       and candidate.attempt_count < candidate.max_attempts
       and not candidate.is_hidden_copy
     order by candidate.next_attempt_at, candidate.created_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 25), 100))
  ), claimed as (
    update public.booking_notification_deliveries target
       set state = 'processing',
           claimed_at = clock_timestamp(),
           claim_token = gen_random_uuid(),
           last_attempt_at = clock_timestamp(),
           attempt_count = target.attempt_count + 1,
           last_error = null
      from candidates
     where target.id = candidates.id
     returning target.*
  )
  select
    claimed.id, claimed.recipient_kind, claimed.recipient_address,
    claimed.recipient_address_hash, claimed.is_hidden_copy,
    claimed.rendered_content, claimed.claim_token, claimed.attempt_count
  from claimed
  order by claimed.created_at, claimed.id;
end;
$$;

create or replace function public.store_booking_notification_render_v1(
  p_delivery_id uuid,
  p_delivery_claim_token uuid,
  p_rendered_content jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare v_content jsonb;
begin
  if jsonb_typeof(p_rendered_content) <> 'object'
     or p_rendered_content->>'version' <> '1'
     or nullif(p_rendered_content->>'subject', '') is null
     or nullif(p_rendered_content->>'html', '') is null
     or nullif(p_rendered_content->>'text', '') is null then
    raise exception 'invalid rendered notification content' using errcode = '22023';
  end if;
  update public.booking_notification_deliveries delivery
     set rendered_content = coalesce(delivery.rendered_content, p_rendered_content)
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_delivery_claim_token
  returning delivery.rendered_content into v_content;
  if not found then
    raise exception 'notification delivery claim mismatch' using errcode = '40001';
  end if;
  return v_content;
end;
$$;

create or replace function public.mark_booking_notification_delivery_sent_v1(
  p_delivery_id uuid,
  p_delivery_claim_token uuid,
  p_provider_message_id text default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.booking_notification_deliveries delivery
     set state = 'sent',
         sent_at = clock_timestamp(),
         completed_at = clock_timestamp(),
         provider_message_id = nullif(left(p_provider_message_id, 500), ''),
         claimed_at = null,
         claim_token = null,
         last_error = null
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_delivery_claim_token;
  return found;
end;
$$;

create or replace function public.fail_booking_notification_delivery_v1(
  p_delivery_id uuid,
  p_delivery_claim_token uuid,
  p_error text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_state text;
begin
  update public.booking_notification_deliveries delivery
     set state = case when delivery.attempt_count >= delivery.max_attempts
           then 'dead_letter' else 'retry' end,
         next_attempt_at = case when delivery.attempt_count >= delivery.max_attempts
           then delivery.next_attempt_at
           else clock_timestamp() + interval '1 minute' end,
         completed_at = case when delivery.attempt_count >= delivery.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = left(coalesce(p_error, 'Notification delivery failed.'), 1000)
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_delivery_claim_token
  returning delivery.state into v_state;
  if not found then
    raise exception 'notification delivery claim mismatch' using errcode = '40001';
  end if;
  return v_state;
end;
$$;

create or replace function public.finalize_booking_notification_outbox_v1(
  p_outbox_id uuid,
  p_claim_token uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_outbox public.booking_notification_outbox;
  v_active integer;
  v_retry integer;
  v_dead integer;
  v_sent integer;
  v_next timestamptz;
begin
  select candidate.* into v_outbox
    from public.booking_notification_outbox candidate
   where candidate.id = p_outbox_id
   for update;
  if not found or v_outbox.state <> 'processing'
     or v_outbox.claim_token is distinct from p_claim_token then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;
  select
    count(*) filter (where state = 'processing'),
    count(*) filter (where state in ('pending', 'retry')),
    count(*) filter (where state in ('failed', 'dead_letter')),
    count(*) filter (where state = 'sent'),
    min(next_attempt_at) filter (where state in ('pending', 'retry'))
    into v_active, v_retry, v_dead, v_sent, v_next
    from public.booking_notification_deliveries
   where outbox_id = p_outbox_id and not is_hidden_copy;
  if v_active > 0 then
    return jsonb_build_object('ok', false, 'code', 'DELIVERIES_STILL_PROCESSING');
  elsif v_dead > 0 then
    update public.booking_notification_outbox
       set state = 'dead_letter', completed_at = clock_timestamp(),
           claimed_at = null, claim_token = null,
           last_error = 'One or more recipient deliveries exhausted retries.'
     where id = p_outbox_id;
    return jsonb_build_object('ok', true, 'state', 'dead_letter',
      'sent', v_sent, 'failed', v_dead);
  elsif v_retry > 0 then
    update public.booking_notification_outbox
       set state = 'pending', available_at = coalesce(v_next, clock_timestamp()),
           claimed_at = null, claim_token = null, completed_at = null
     where id = p_outbox_id;
    return jsonb_build_object('ok', true, 'state', 'pending',
      'sent', v_sent, 'retry', v_retry);
  elsif v_sent > 0 then
    update public.booking_notification_outbox
       set state = 'sent', completed_at = clock_timestamp(),
           claimed_at = null, claim_token = null, last_error = null
     where id = p_outbox_id;
    return jsonb_build_object('ok', true, 'state', 'sent', 'sent', v_sent);
  end if;
  return jsonb_build_object('ok', false, 'code', 'NO_VISIBLE_DELIVERIES');
end;
$$;

create or replace function public.fail_booking_notification_outbox_v1(
  p_outbox_id uuid,
  p_claim_token uuid,
  p_error text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_state text;
begin
  update public.booking_notification_outbox outbox
     set state = case when outbox.attempt_count >= outbox.max_attempts
           then 'dead_letter' else 'pending' end,
         available_at = case when outbox.attempt_count >= outbox.max_attempts
           then outbox.available_at else clock_timestamp() + interval '1 minute' end,
         completed_at = case when outbox.attempt_count >= outbox.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = left(coalesce(p_error, 'Notification processing failed.'), 1000)
   where outbox.id = p_outbox_id
     and outbox.state = 'processing'
     and outbox.claim_token = p_claim_token
  returning outbox.state into v_state;
  if not found then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;
  return v_state;
end;
$$;

revoke all on function public.claim_booking_notification_outbox_v2(integer,uuid),
  public.complete_booking_notification_recipient_expansion_v1(uuid,uuid),
