  public.finalize_booking_notification_outbox_v1(uuid,uuid),
  public.fail_booking_notification_outbox_v1(uuid,uuid,text)
  to service_role;

comment on column public.booking_notification_outbox.recipients_expanded_at is
  'Freezes the visible recipient set for this occurrence. Later retries cannot add a newly changed booking/profile address.';
comment on function public.finalize_booking_notification_outbox_v1(uuid,uuid) is
  'Derives occurrence outcome from independent visible-recipient rows; sent recipients stay terminal while only retry recipients become eligible again.';


-- SOURCE: 0075_booking_notification_resilience_metrics.sql
-- Notification retry, stale-claim recovery, dead-letter escalation, and metrics.

alter table public.booking_notification_outbox
  add column if not exists dead_lettered_at timestamptz,
  add column if not exists escalated_at timestamptz;
alter table public.booking_notification_deliveries
  add column if not exists dead_lettered_at timestamptz;

alter table public.booking_notification_outbox
  add constraint booking_notification_outbox_dead_letter_time_check
  check (state <> 'dead_letter' or dead_lettered_at is not null) not valid;
alter table public.booking_notification_deliveries
  add constraint booking_notification_deliveries_dead_letter_time_check
  check (state <> 'dead_letter' or dead_lettered_at is not null) not valid;

create or replace function public.stamp_booking_notification_dead_letter_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.state = 'dead_letter' then
    new.dead_lettered_at := coalesce(new.dead_lettered_at, clock_timestamp());
  end if;
  return new;
end;
$$;

drop trigger if exists booking_notification_outbox_stamp_dead_letter
  on public.booking_notification_outbox;
create trigger booking_notification_outbox_stamp_dead_letter
  before insert or update on public.booking_notification_outbox
  for each row execute function public.stamp_booking_notification_dead_letter_v1();
drop trigger if exists booking_notification_deliveries_stamp_dead_letter
  on public.booking_notification_deliveries;
create trigger booking_notification_deliveries_stamp_dead_letter
  before insert or update on public.booking_notification_deliveries
  for each row execute function public.stamp_booking_notification_dead_letter_v1();

create or replace function public.booking_notification_retry_delay_v1(
  p_attempt_count integer
)
returns interval
language sql
immutable
set search_path = public
as $$
  select case
    when p_attempt_count <= 1 then interval '1 minute'
    when p_attempt_count = 2 then interval '5 minutes'
    when p_attempt_count = 3 then interval '15 minutes'
    when p_attempt_count = 4 then interval '1 hour'
    when p_attempt_count = 5 then interval '4 hours'
    when p_attempt_count = 6 then interval '12 hours'
    else interval '24 hours'
  end
$$;

create or replace function public.fail_booking_notification_delivery_v1(
  p_delivery_id uuid,
  p_delivery_claim_token uuid,
  p_error text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_state text;
begin
  update public.booking_notification_deliveries delivery
     set state = case when delivery.attempt_count >= delivery.max_attempts
           then 'dead_letter' else 'retry' end,
         next_attempt_at = case when delivery.attempt_count >= delivery.max_attempts
           then delivery.next_attempt_at
           else clock_timestamp()
             + public.booking_notification_retry_delay_v1(delivery.attempt_count)
           end,
         completed_at = case when delivery.attempt_count >= delivery.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = left(coalesce(p_error, 'Notification delivery failed.'), 1000)
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_delivery_claim_token
  returning delivery.state into v_state;
  if not found then
    raise exception 'notification delivery claim mismatch' using errcode = '40001';
  end if;
  return v_state;
end;
$$;

create or replace function public.fail_booking_notification_outbox_v1(
  p_outbox_id uuid,
  p_claim_token uuid,
  p_error text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_state text;
begin
  update public.booking_notification_outbox outbox
     set state = case when outbox.attempt_count >= outbox.max_attempts
           then 'dead_letter' else 'pending' end,
         available_at = case when outbox.attempt_count >= outbox.max_attempts
           then outbox.available_at
           else clock_timestamp()
             + public.booking_notification_retry_delay_v1(outbox.attempt_count)
           end,
         completed_at = case when outbox.attempt_count >= outbox.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = left(coalesce(p_error, 'Notification processing failed.'), 1000)
   where outbox.id = p_outbox_id
     and outbox.state = 'processing'
     and outbox.claim_token = p_claim_token
  returning outbox.state into v_state;
  if not found then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;
  return v_state;
end;
$$;

create or replace function public.recover_stale_booking_notification_claims_v1(
  p_limit integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_cutoff timestamptz := clock_timestamp() - interval '15 minutes';
  v_delivery_count integer := 0;
  v_outbox_count integer := 0;
begin
  with candidates as (
    select candidate.id
      from public.booking_notification_deliveries candidate
     where candidate.state = 'processing'
       and candidate.claimed_at <= v_cutoff
     order by candidate.claimed_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.booking_notification_deliveries delivery
     set state = case when delivery.attempt_count >= delivery.max_attempts
           then 'dead_letter' else 'retry' end,
         next_attempt_at = case when delivery.attempt_count >= delivery.max_attempts
           then delivery.next_attempt_at else clock_timestamp() end,
         completed_at = case when delivery.attempt_count >= delivery.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = 'Recovered stale recipient delivery claim.'
    from candidates
   where delivery.id = candidates.id;
  get diagnostics v_delivery_count = row_count;

  with candidates as (
    select candidate.id
      from public.booking_notification_outbox candidate
     where candidate.state = 'processing'
       and candidate.claimed_at <= v_cutoff
       and not exists (
         select 1 from public.booking_notification_deliveries active
          where active.outbox_id = candidate.id
            and active.state = 'processing'
            and active.claimed_at > v_cutoff
       )
     order by candidate.claimed_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.booking_notification_outbox outbox
     set state = case
           when outbox.attempt_count >= outbox.max_attempts
             or exists (
               select 1 from public.booking_notification_deliveries delivery
                where delivery.outbox_id = outbox.id
                  and delivery.state in ('failed', 'dead_letter')
             ) then 'dead_letter'
           else 'pending'
         end,
         available_at = case
           when outbox.attempt_count >= outbox.max_attempts then outbox.available_at
           else coalesce((
             select min(delivery.next_attempt_at)
               from public.booking_notification_deliveries delivery
              where delivery.outbox_id = outbox.id
                and delivery.state in ('pending', 'retry')
           ), clock_timestamp())
         end,
         completed_at = case
           when outbox.attempt_count >= outbox.max_attempts
             or exists (
               select 1 from public.booking_notification_deliveries delivery
                where delivery.outbox_id = outbox.id
                  and delivery.state in ('failed', 'dead_letter')
             ) then clock_timestamp()
           else null
         end,
         claimed_at = null,
         claim_token = null,
         last_error = 'Recovered stale notification outbox claim.'
    from candidates
   where outbox.id = candidates.id;
  get diagnostics v_outbox_count = row_count;
  return jsonb_build_object(
    'recoveredDeliveries', v_delivery_count,
    'recoveredOutboxes', v_outbox_count
  );
end;
$$;

create or replace function public.escalate_booking_notification_dead_letters_v1(
  p_limit integer default 100
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare v_count integer;
begin
  with candidates as (
    select candidate.id
      from public.booking_notification_outbox candidate
     where candidate.state = 'dead_letter'
       and candidate.escalated_at is null
     order by candidate.dead_lettered_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.booking_notification_outbox outbox
     set escalated_at = clock_timestamp()
    from candidates
   where outbox.id = candidates.id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

create or replace view public.booking_notification_metrics_v
with (security_invoker = true)
as
select
  now() as observed_at,
  count(*) filter (where outbox.state = 'pending')::bigint
    as pending_outbox_count,
  count(*) filter (where outbox.state = 'processing')::bigint
    as processing_outbox_count,
  count(*) filter (where outbox.state = 'sent')::bigint
    as sent_outbox_count,
  count(*) filter (where outbox.state = 'suppressed')::bigint
    as suppressed_outbox_count,
  count(*) filter (where outbox.state = 'superseded')::bigint
    as superseded_outbox_count,
  count(*) filter (where outbox.state = 'dead_letter')::bigint
    as dead_letter_outbox_count,
  count(*) filter (
    where outbox.state = 'dead_letter' and outbox.escalated_at is null
  )::bigint as un_escalated_dead_letter_count,
  min(outbox.created_at) filter (where outbox.state = 'pending')
    as oldest_pending_outbox_at,
  min(outbox.dead_lettered_at) filter (where outbox.state = 'dead_letter')
    as oldest_dead_letter_at,
  (select count(*)::bigint
     from public.booking_notification_deliveries delivery
    where delivery.state = 'retry') as retry_delivery_count,
  (select count(*)::bigint
     from public.booking_notification_deliveries delivery
    where delivery.state = 'processing') as processing_delivery_count,
  (select count(*)::bigint
     from public.booking_notification_deliveries delivery
    where delivery.state = 'sent') as sent_delivery_count,
  (select count(*)::bigint
     from public.booking_notification_deliveries delivery
    where delivery.state = 'dead_letter') as dead_letter_delivery_count
from public.booking_notification_outbox outbox;

revoke all on table public.booking_notification_metrics_v
  from public, anon, authenticated;
grant select on table public.booking_notification_metrics_v to service_role;

revoke all on function public.stamp_booking_notification_dead_letter_v1(),
  public.booking_notification_retry_delay_v1(integer),
  public.recover_stale_booking_notification_claims_v1(integer),
  public.escalate_booking_notification_dead_letters_v1(integer)
  from public, anon, authenticated;
grant execute on function public.booking_notification_retry_delay_v1(integer),
  public.recover_stale_booking_notification_claims_v1(integer),
  public.escalate_booking_notification_dead_letters_v1(integer)
  to service_role;
revoke all on function public.stamp_booking_notification_dead_letter_v1()
  from service_role;

comment on view public.booking_notification_metrics_v is
  'Address-free occurrence/delivery health: pending, processing, retry, sent, suppression, supersession, dead-letter, and escalation counts.';


-- SOURCE: 0076_booking_due_deadline_index.sql
-- Keep the expiry sweep on the small, ordered set of actionable deadlines.
-- The stable booking ID is the keyset tie-breaker used by the Phase 8 worker.
create index if not exists flight_bookings_due_expiry_observation_idx
  on public.flight_bookings (ticketing_deadline_at, id)
  where not legacy_operational
    and status = 'on-hold'
    and active_operation_id is null
    and operation_kind is null
    and ticketing_deadline_at is not null
    and public.jsonb_is_nonempty_array(airlines_pnr);

comment on index public.flight_bookings_due_expiry_observation_idx is
  'Ordered expiry-observation candidates only: active On Hold supplier bookings with an airline PNR, a deadline, and no unresolved operation.';


-- SOURCE: 0077_booking_due_expiry_observation.sql
-- Replace the legacy oldest-updated-row sweep with a due-first expiry query.
-- P8.2 deliberately filters both deadline eligibility and prior observation
-- before applying the bounded limit. Later Phase 8 migrations add the worker
-- cursor/concurrency contract without reintroducing the broad scan.
create or replace function public.record_booking_lifecycle_observations(
  p_limit integer default 500
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
  v_observed_at timestamptz := clock_timestamp();
begin
  with due_unobserved as (
    select
      booking.id,
      booking.status,
      booking.ticketing_deadline_at,
      coalesce(latest_event.to_lifecycle_status, 'on-hold') as last_status
    from public.flight_bookings booking
    left join lateral (
      select event.to_lifecycle_status
      from public.booking_status_events event
      where event.booking_id = booking.id
      order by event.id desc
      limit 1
    ) latest_event on true
    where not booking.legacy_operational
      and booking.status = 'on-hold'
      and booking.active_operation_id is null
      and booking.operation_kind is null
      and booking.ticketing_deadline_at is not null
      and booking.ticketing_deadline_at <= v_observed_at
      and public.jsonb_is_nonempty_array(booking.airlines_pnr)
      and coalesce(latest_event.to_lifecycle_status, 'on-hold') <> 'expired'
    order by booking.ticketing_deadline_at, booking.id
    limit greatest(1, least(coalesce(p_limit, 500), 2000))
  ), inserted as (
    insert into public.booking_status_events (
      booking_id,
      from_lifecycle_status,
      to_lifecycle_status,
      stored_status_before,
      stored_status_after,
      supplier_operation,
      supplier_evidence,
      idempotency_key,
      effective_at,
      observed_at,
      event_snapshot
    )
    select
      candidate.id,
      candidate.last_status,
      'expired',
      candidate.status,
      candidate.status,
      'LifecycleSweep',
      jsonb_build_object(
        'deadlineAt', candidate.ticketing_deadline_at,
        'observationSource', 'due_expiry_worker'
      ),
      'derived-expired:v1:' || to_char(
        candidate.ticketing_deadline_at at time zone 'UTC',
        'YYYYMMDD"T"HH24MISS.US"Z"'
      ),
      candidate.ticketing_deadline_at,
      v_observed_at,
      jsonb_build_object(
        'deadlineAt', candidate.ticketing_deadline_at,
        'observationSource', 'due_expiry_worker'
      )
    from due_unobserved candidate
    on conflict do nothing
    returning 1
  )
  select count(*) into v_count from inserted;

  return v_count;
end;
$$;

revoke all on function public.record_booking_lifecycle_observations(integer)
  from public, anon, authenticated;
grant execute on function public.record_booking_lifecycle_observations(integer)
  to service_role;

comment on function public.record_booking_lifecycle_observations(integer) is
  'Compatibility expiry observer: filters due, actionable, not-currently-observed Expired occurrences before the bounded deadline/ID-ordered limit.';


-- SOURCE: 0078_booking_expiry_keyset_pagination.sql
-- Cursor-based batches avoid rescanning already examined rows inside one worker
-- run. A fresh scheduler invocation starts without a cursor; rows successfully
-- observed by an earlier run are excluded by lifecycle occurrence state.
create or replace function public.record_due_booking_expiry_observation_batch_v1(
  p_after_deadline timestamptz default null,
  p_after_id uuid default null,
  p_limit integer default 250
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 250), 500));
  v_observed_at timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if (p_after_deadline is null) <> (p_after_id is null) then
    raise exception 'expiry cursor requires both deadline and booking ID'
      using errcode = '22023';
  end if;

  with due_unobserved as materialized (
    select
      booking.id,
      booking.status,
      booking.ticketing_deadline_at,
      coalesce(latest_event.to_lifecycle_status, 'on-hold') as last_status
    from public.flight_bookings booking
    left join lateral (
      select event.to_lifecycle_status
      from public.booking_status_events event
      where event.booking_id = booking.id
      order by event.id desc
      limit 1
    ) latest_event on true
    where not booking.legacy_operational
      and booking.status = 'on-hold'
      and booking.active_operation_id is null
      and booking.operation_kind is null
      and booking.ticketing_deadline_at is not null
      and booking.ticketing_deadline_at <= v_observed_at
      and public.jsonb_is_nonempty_array(booking.airlines_pnr)
      and coalesce(latest_event.to_lifecycle_status, 'on-hold') <> 'expired'
      and (
        p_after_deadline is null
        or (booking.ticketing_deadline_at, booking.id)
          > (p_after_deadline, p_after_id)
      )
    order by booking.ticketing_deadline_at, booking.id
    limit v_limit
    for update of booking skip locked
  ), inserted as (
    insert into public.booking_status_events (
      booking_id,
      from_lifecycle_status,
      to_lifecycle_status,
      stored_status_before,
      stored_status_after,
      supplier_operation,
      supplier_evidence,
      idempotency_key,
      effective_at,
      observed_at,
      event_snapshot
    )
    select
      candidate.id,
      candidate.last_status,
      'expired',
      candidate.status,
      candidate.status,
      'LifecycleSweep',
      jsonb_build_object(
        'deadlineAt', candidate.ticketing_deadline_at,
        'observationSource', 'due_expiry_worker'
      ),
      'derived-expired:v1:' || to_char(
        candidate.ticketing_deadline_at at time zone 'UTC',
        'YYYYMMDD"T"HH24MISS.US"Z"'
      ),
      candidate.ticketing_deadline_at,
      v_observed_at,
      jsonb_build_object(
        'deadlineAt', candidate.ticketing_deadline_at,
        'observationSource', 'due_expiry_worker'
      )
    from due_unobserved candidate
    on conflict do nothing
    returning 1
  )
  select jsonb_build_object(
    'selectedCount', (select count(*) from due_unobserved),
    'insertedCount', (select count(*) from inserted),
    'nextDeadline', (
      select candidate.ticketing_deadline_at
      from due_unobserved candidate
      order by candidate.ticketing_deadline_at desc, candidate.id desc
      limit 1
    ),
    'nextId', (
      select candidate.id
      from due_unobserved candidate
      order by candidate.ticketing_deadline_at desc, candidate.id desc
      limit 1
    ),
    'hasMore', (select count(*) = v_limit from due_unobserved),
    'observedAt', v_observed_at
  ) into v_result;

  return v_result;
end;
$$;

-- Retain the original RPC as a one-batch compatibility wrapper while the
-- application worker cuts over to the cursor result.
create or replace function public.record_booking_lifecycle_observations(
  p_limit integer default 500
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare v_result jsonb;
begin
  v_result := public.record_due_booking_expiry_observation_batch_v1(
    null,
    null,
    p_limit
  );
  return coalesce((v_result->>'insertedCount')::integer, 0);
end;
$$;

revoke all on function public.record_due_booking_expiry_observation_batch_v1(
  timestamptz, uuid, integer
) from public, anon, authenticated, service_role;
grant execute on function public.record_due_booking_expiry_observation_batch_v1(
  timestamptz, uuid, integer
) to service_role;

revoke all on function public.record_booking_lifecycle_observations(integer)
  from public, anon, authenticated, service_role;
grant execute on function public.record_booking_lifecycle_observations(integer)
  to service_role;

comment on function public.record_due_booking_expiry_observation_batch_v1(
  timestamptz, uuid, integer
) is
  'Records one due Expired occurrence batch after an optional (deadline, booking ID) cursor and returns the last examined key.';


-- SOURCE: 0079_booking_expiry_worker_runs.sql
-- Durable expiry-worker run evidence. The cursor is scoped to one bounded run;
-- every new scheduler invocation starts at the due-index head because prior
-- observations leave the eligible set. This avoids a global high-water mark
-- skipping a newly corrected, earlier deadline.
create table if not exists public.booking_lifecycle_worker_runs (
  id uuid primary key default gen_random_uuid(),
  worker_kind text not null,
  state text not null default 'running',
  cursor_deadline timestamptz,
  cursor_booking_id uuid,
  batch_count integer not null default 0,
  selected_count bigint not null default 0,
  inserted_count bigint not null default 0,
  last_observed_at timestamptz,
  last_batch_at timestamptz,
  stop_reason text,
  last_error text,
  started_at timestamptz not null default clock_timestamp(),
  completed_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  constraint booking_lifecycle_worker_runs_kind_check
    check (worker_kind = 'due_expiry_observation'),
  constraint booking_lifecycle_worker_runs_state_check
    check (state in ('running', 'succeeded', 'bounded', 'failed')),
  constraint booking_lifecycle_worker_runs_cursor_check
    check ((cursor_deadline is null) = (cursor_booking_id is null)),
  constraint booking_lifecycle_worker_runs_counts_check
    check (
      batch_count >= 0
      and selected_count >= 0
      and inserted_count >= 0
      and inserted_count <= selected_count
    ),
  constraint booking_lifecycle_worker_runs_completion_check
    check (
      (state = 'running' and completed_at is null and stop_reason is null)
      or
      (state <> 'running' and completed_at is not null and stop_reason is not null)
    )
);

create index if not exists booking_lifecycle_worker_runs_recent_idx
  on public.booking_lifecycle_worker_runs (worker_kind, started_at desc, id desc);
create index if not exists booking_lifecycle_worker_runs_running_idx
  on public.booking_lifecycle_worker_runs (started_at, id)
  where state = 'running';

drop trigger if exists booking_lifecycle_worker_runs_touch_updated_at
  on public.booking_lifecycle_worker_runs;
create trigger booking_lifecycle_worker_runs_touch_updated_at
  before update on public.booking_lifecycle_worker_runs
  for each row execute function public.touch_updated_at();

alter table public.booking_lifecycle_worker_runs enable row level security;
revoke all on table public.booking_lifecycle_worker_runs
  from public, anon, authenticated, service_role;
grant select on table public.booking_lifecycle_worker_runs to service_role;

create or replace function public.start_due_booking_expiry_worker_run_v1()
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare v_run_id uuid;
begin
  insert into public.booking_lifecycle_worker_runs (worker_kind)
  values ('due_expiry_observation')
  returning id into v_run_id;
  return v_run_id;
end;
$$;

-- The run row is locked before the batch call. Event/outbox insertion and the
-- durable cursor/count update therefore commit or roll back together.
create or replace function public.record_due_booking_expiry_worker_batch_v2(
  p_run_id uuid,
  p_limit integer default 250
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_run public.booking_lifecycle_worker_runs;
  v_batch jsonb;
  v_selected integer;
  v_inserted integer;
  v_next_deadline timestamptz;
  v_next_id uuid;
  v_observed_at timestamptz;
begin
  select * into v_run
  from public.booking_lifecycle_worker_runs
  where id = p_run_id
  for update;
  if not found or v_run.worker_kind <> 'due_expiry_observation' then
    raise exception 'expiry worker run not found' using errcode = 'P0002';
  end if;
  if v_run.state <> 'running' then
    raise exception 'expiry worker run is already complete' using errcode = '55000';
  end if;

  v_batch := public.record_due_booking_expiry_observation_batch_v1(
    v_run.cursor_deadline,
    v_run.cursor_booking_id,
    p_limit
  );
  v_selected := coalesce((v_batch->>'selectedCount')::integer, 0);
  v_inserted := coalesce((v_batch->>'insertedCount')::integer, 0);
  v_next_deadline := nullif(v_batch->>'nextDeadline', '')::timestamptz;
  v_next_id := nullif(v_batch->>'nextId', '')::uuid;
  v_observed_at := nullif(v_batch->>'observedAt', '')::timestamptz;
  if v_selected > 0 and (v_next_deadline is null or v_next_id is null) then
    raise exception 'expiry batch returned an invalid cursor' using errcode = '22023';
  end if;

  update public.booking_lifecycle_worker_runs
     set cursor_deadline = coalesce(v_next_deadline, cursor_deadline),
         cursor_booking_id = coalesce(v_next_id, cursor_booking_id),
         batch_count = batch_count + 1,
         selected_count = selected_count + v_selected,
         inserted_count = inserted_count + v_inserted,
         last_observed_at = v_observed_at,
         last_batch_at = clock_timestamp()
   where id = p_run_id;

  return v_batch || jsonb_build_object('runId', p_run_id);
end;
$$;

create or replace function public.complete_due_booking_expiry_worker_run_v1(
  p_run_id uuid,
  p_stop_reason text,
  p_error text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare v_run public.booking_lifecycle_worker_runs;
begin
  if p_stop_reason not in (
    'drained', 'time_budget', 'batch_cap', 'rpc_error', 'invalid_cursor'
  ) then
    raise exception 'unsupported expiry worker stop reason' using errcode = '22023';
  end if;
  update public.booking_lifecycle_worker_runs
     set state = case
           when p_stop_reason = 'drained' then 'succeeded'
           when p_stop_reason in ('time_budget', 'batch_cap') then 'bounded'
           else 'failed'
         end,
         stop_reason = p_stop_reason,
         last_error = nullif(left(coalesce(p_error, ''), 1000), ''),
         completed_at = clock_timestamp()
   where id = p_run_id and state = 'running'
   returning * into v_run;
  if not found then
    select * into v_run from public.booking_lifecycle_worker_runs where id = p_run_id;
  end if;
  if not found then
    raise exception 'expiry worker run not found' using errcode = 'P0002';
  end if;
  return jsonb_build_object(
    'runId', v_run.id,
    'state', v_run.state,
    'stopReason', v_run.stop_reason,
    'batchCount', v_run.batch_count,
    'selectedCount', v_run.selected_count,
    'insertedCount', v_run.inserted_count,
    'cursorDeadline', v_run.cursor_deadline,
    'cursorBookingId', v_run.cursor_booking_id,
    'startedAt', v_run.started_at,
    'completedAt', v_run.completed_at
  );
end;
$$;

revoke all on function public.start_due_booking_expiry_worker_run_v1(),
  public.record_due_booking_expiry_worker_batch_v2(uuid, integer),
  public.complete_due_booking_expiry_worker_run_v1(uuid, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.start_due_booking_expiry_worker_run_v1(),
  public.record_due_booking_expiry_worker_batch_v2(uuid, integer),
  public.complete_due_booking_expiry_worker_run_v1(uuid, text, text)
  to service_role;

comment on table public.booking_lifecycle_worker_runs is
  'Durable, address/PII-free execution evidence for bounded derived-lifecycle workers; one cursor is scoped to one scheduler run.';


-- SOURCE: 0080_booking_unconfirmed_observation_paths.sql
-- Booking creation already emits the resolver-derived initial lifecycle event,
-- and PNR refresh emits a before/after transition. Imported Sync receives the
-- same primary-path guarantee here. The bounded repair function is audit-only
-- and exists solely for historical/missed-event recovery.

create or replace function public.ensure_import_sync_unconfirmed_event_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_last_status text;
  v_observed_at timestamptz := coalesce(new.synced_at, clock_timestamp());
begin
  if new.import_source is distinct from 'IMP_EXP'
     or new.synced_at is not distinct from old.synced_at
     or public.resolve_booking_lifecycle(
       new.status,
       new.airlines_pnr,
       new.ticketing_deadline_at,
       new.operation_kind
     ) <> 'unconfirmed' then
    return new;
  end if;

  select event.to_lifecycle_status into v_last_status
  from public.booking_status_events event
  where event.booking_id = new.id
  order by event.id desc
  limit 1;
  if v_last_status is not distinct from 'unconfirmed' then
    return new;
  end if;

  insert into public.booking_status_events (
    booking_id,
    from_lifecycle_status,
    to_lifecycle_status,
    stored_status_before,
    stored_status_after,
    operation_kind,
    operation_reason,
    actor_user_id,
    supplier_operation,
    supplier_evidence,
    idempotency_key,
    observed_at,
    event_snapshot
  ) values (
    new.id,
    coalesce(v_last_status, 'on-hold'),
    'unconfirmed',
    old.status,
    new.status,
    new.operation_kind,
    new.operation_reason,
    nullif(new.import_metadata->>'lastSyncedBy', ''),
    'ImportedSync',
    jsonb_build_object(
      'observationSource', 'import_sync',
      'statusMutation', false,
      'walletMutation', false
    ),
    'import-sync-unconfirmed:v1:' || to_char(
      v_observed_at at time zone 'UTC',
      'YYYYMMDD"T"HH24MISS.US"Z"'
    ),
    v_observed_at,
    jsonb_build_object('observationSource', 'import_sync')
  ) on conflict do nothing;
  return new;
end;
$$;

drop trigger if exists flight_bookings_import_sync_unconfirmed_event
  on public.flight_bookings;
create trigger flight_bookings_import_sync_unconfirmed_event
  after update of synced_at on public.flight_bookings
  for each row execute function public.ensure_import_sync_unconfirmed_event_v1();

revoke all on function public.ensure_import_sync_unconfirmed_event_v1()
  from public, anon, authenticated, service_role;

create index if not exists flight_bookings_unconfirmed_repair_idx
  on public.flight_bookings (id)
  where not legacy_operational
    and status = 'on-hold'
    and active_operation_id is null
    and operation_kind is null
    and not public.jsonb_is_nonempty_array(airlines_pnr);

create or replace function public.record_unconfirmed_booking_repair_batch_v1(
  p_after_id uuid default null,
  p_limit integer default 50
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_observed_at timestamptz := clock_timestamp();
  v_result jsonb;
begin
  with repair_candidates as materialized (
    select
      booking.id,
      booking.status,
      latest_event.id as last_event_id,
      coalesce(latest_event.to_lifecycle_status, 'on-hold') as last_status
    from public.flight_bookings booking
    left join lateral (
      select event.id, event.to_lifecycle_status
      from public.booking_status_events event
      where event.booking_id = booking.id
      order by event.id desc
      limit 1
    ) latest_event on true
    where not booking.legacy_operational
      and booking.status = 'on-hold'
      and booking.active_operation_id is null
      and booking.operation_kind is null
      and not public.jsonb_is_nonempty_array(booking.airlines_pnr)
      and coalesce(latest_event.to_lifecycle_status, 'on-hold') <> 'unconfirmed'
      and (p_after_id is null or booking.id > p_after_id)
    order by booking.id
    limit v_limit
    for update of booking skip locked
  ), inserted as (
    insert into public.booking_status_events (
      booking_id,
      from_lifecycle_status,
      to_lifecycle_status,
      stored_status_before,
      stored_status_after,
      supplier_operation,
      supplier_evidence,
      idempotency_key,
      observed_at,
      event_snapshot
    )
    select
      candidate.id,
      candidate.last_status,
      'unconfirmed',
      candidate.status,
      candidate.status,
      'LifecycleRepair',
      jsonb_build_object(
        'observationSource', 'unconfirmed_repair_backstop',
        'statusMutation', false,
        'walletMutation', false
      ),
      'derived-unconfirmed:repair:v1:'
        || coalesce(candidate.last_event_id::text, 'initial'),
      v_observed_at,
      jsonb_build_object(
        'observationSource', 'unconfirmed_repair_backstop',
        'notificationDisposition', 'audit_only',
        'suppressionReason', 'case_only_repair'
      )
    from repair_candidates candidate
    on conflict do nothing
    returning 1
  )
  select jsonb_build_object(
    'selectedCount', (select count(*) from repair_candidates),
    'insertedCount', (select count(*) from inserted),
    'nextId', (
      select candidate.id
      from repair_candidates candidate
      order by candidate.id desc
      limit 1
    ),
    'hasMore', (select count(*) = v_limit from repair_candidates),
    'observedAt', v_observed_at
  ) into v_result;
  return v_result;
end;
$$;

revoke all on function public.record_unconfirmed_booking_repair_batch_v1(
  uuid, integer
) from public, anon, authenticated, service_role;
grant execute on function public.record_unconfirmed_booking_repair_batch_v1(
  uuid, integer
) to service_role;

comment on function public.record_unconfirmed_booking_repair_batch_v1(
  uuid, integer
) is
  'Bounded audit-only repair for an On Hold/no-airline-PNR row whose current Unconfirmed occurrence was missed by booking creation or Sync.';


-- SOURCE: 0081_booking_derived_lifecycle_metrics.sql
-- Address/PII-free monitoring for derived lifecycle backlog, detection latency,
-- bounded-worker health, and missed-observation starvation.
create index if not exists booking_status_events_expiry_latency_idx
  on public.booking_status_events (observed_at desc, id desc)
  where to_lifecycle_status = 'expired'
    and supplier_operation = 'LifecycleSweep';

create or replace view public.booking_derived_lifecycle_metrics_v
with (security_invoker = true)
as
with due_expiry as (
  select booking.ticketing_deadline_at
  from public.flight_bookings booking
  left join lateral (
    select event.to_lifecycle_status
    from public.booking_status_events event
    where event.booking_id = booking.id
    order by event.id desc
    limit 1
  ) latest_event on true
  where not booking.legacy_operational
    and booking.status = 'on-hold'
    and booking.active_operation_id is null
    and booking.operation_kind is null
    and booking.ticketing_deadline_at is not null
    and booking.ticketing_deadline_at <= clock_timestamp()
    and public.jsonb_is_nonempty_array(booking.airlines_pnr)
    and coalesce(latest_event.to_lifecycle_status, 'on-hold') <> 'expired'
), expiry_backlog as (
  select
    count(*)::bigint as due_expiry_count,
    min(ticketing_deadline_at) as oldest_due_deadline_at,
    coalesce(max(greatest(
      extract(epoch from (clock_timestamp() - ticketing_deadline_at)),
      0
    )), 0)::double precision as max_expiry_overdue_seconds,
    count(*) filter (
      where ticketing_deadline_at
        <= clock_timestamp() - interval '30 minutes'
    )::bigint as starved_expiry_count
  from due_expiry
), unconfirmed_backlog as (
  select count(*)::bigint as unconfirmed_repair_count
  from public.flight_bookings booking
  left join lateral (
    select event.to_lifecycle_status
    from public.booking_status_events event
    where event.booking_id = booking.id
    order by event.id desc
    limit 1
  ) latest_event on true
  where not booking.legacy_operational
    and booking.status = 'on-hold'
    and booking.active_operation_id is null
    and booking.operation_kind is null
    and not public.jsonb_is_nonempty_array(booking.airlines_pnr)
    and coalesce(latest_event.to_lifecycle_status, 'on-hold') <> 'unconfirmed'
), latency as (
  select
    count(*)::bigint as expiry_observations_24h,
    coalesce(avg(greatest(
      extract(epoch from (event.observed_at - event.effective_at)),
      0
    )), 0)::double precision as average_detection_latency_seconds,
    coalesce(percentile_cont(0.95) within group (
      order by greatest(
        extract(epoch from (event.observed_at - event.effective_at)),
        0
      )
    ), 0)::double precision as p95_detection_latency_seconds,
    coalesce(max(greatest(
      extract(epoch from (event.observed_at - event.effective_at)),
      0
    )), 0)::double precision as max_detection_latency_seconds
  from public.booking_status_events event
  where event.to_lifecycle_status = 'expired'
    and event.supplier_operation = 'LifecycleSweep'
    and event.effective_at is not null
    and event.observed_at is not null
    and event.observed_at >= clock_timestamp() - interval '24 hours'
), run_health as (
  select
    count(*) filter (
      where run.state = 'failed'
        and run.started_at >= clock_timestamp() - interval '24 hours'
    )::bigint as failed_runs_24h,
    count(*) filter (
      where run.state = 'bounded'
        and run.started_at >= clock_timestamp() - interval '24 hours'
    )::bigint as bounded_runs_24h,
    count(*) filter (
      where run.state = 'running'
        and run.started_at < clock_timestamp() - interval '15 minutes'
    )::bigint as stale_running_runs,
    max(run.completed_at) filter (
      where run.state = 'succeeded'
    ) as last_successful_run_at
  from public.booking_lifecycle_worker_runs run
  where run.worker_kind = 'due_expiry_observation'
)
select
  clock_timestamp() as observed_at,
  expiry_backlog.due_expiry_count,
  expiry_backlog.oldest_due_deadline_at,
  expiry_backlog.max_expiry_overdue_seconds,
  expiry_backlog.starved_expiry_count,
  unconfirmed_backlog.unconfirmed_repair_count,
  latency.expiry_observations_24h,
  latency.average_detection_latency_seconds,
  latency.p95_detection_latency_seconds,
  latency.max_detection_latency_seconds,
  run_health.failed_runs_24h,
  run_health.bounded_runs_24h,
  run_health.stale_running_runs,
  run_health.last_successful_run_at,
  latest_run.started_at as last_run_started_at,
  latest_run.completed_at as last_run_completed_at,
  latest_run.stop_reason as last_run_stop_reason,
  latest_run.selected_count as last_run_selected_count,
  latest_run.inserted_count as last_run_inserted_count
from expiry_backlog
cross join unconfirmed_backlog
cross join latency
cross join run_health
left join lateral (
  select run.*
  from public.booking_lifecycle_worker_runs run
  where run.worker_kind = 'due_expiry_observation'
  order by run.started_at desc, run.id desc
  limit 1
) latest_run on true;

revoke all on table public.booking_derived_lifecycle_metrics_v
  from public, anon, authenticated, service_role;
grant select on table public.booking_derived_lifecycle_metrics_v to service_role;

comment on view public.booking_derived_lifecycle_metrics_v is
  'Service-only aggregate health for due Expired backlog, >30-minute starvation, Unconfirmed repair backlog, 24-hour detection latency, and bounded worker outcomes; contains no booking or recipient identity.';


-- SOURCE: 0082_booking_notification_address_hash_resolution.sql
-- Keep recipient hashing compatible with the restricted SECURITY DEFINER
-- search path. sha256(bytea) is available without relying on the pgcrypto
-- extension schema being present in search_path.
create or replace function public.register_booking_notification_delivery_v1(
  p_outbox_id uuid,
  p_claim_token uuid,
  p_recipient_kind text,
  p_recipient_address text
)
returns table (
  delivery_id uuid,
  outbox_id uuid,
  recipient_kind text,
  recipient_address text,
  recipient_address_hash text,
  is_hidden_copy boolean,
  state text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_outbox public.booking_notification_outbox;
  v_address text := lower(btrim(coalesce(p_recipient_address, '')));
  v_address_hash text;
  v_existing public.booking_notification_deliveries;
begin
  if p_recipient_kind not in (
    'customer_contact', 'booking_user', 'agency_user', 'system_copy'
  ) then
    raise exception 'invalid notification recipient kind' using errcode = '22023';
  end if;
  if v_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or char_length(v_address) > 320 then
    raise exception 'invalid notification recipient address' using errcode = '22023';
  end if;
  select candidate.* into v_outbox
    from public.booking_notification_outbox candidate
   where candidate.id = p_outbox_id
   for update;
  if not found then
    raise exception 'notification outbox not found' using errcode = 'P0002';
  end if;
  if v_outbox.state <> 'processing'
     or v_outbox.claim_token is distinct from p_claim_token then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;

  v_address_hash := encode(sha256(convert_to(v_address, 'UTF8')), 'hex');
  select delivery.* into v_existing
    from public.booking_notification_deliveries delivery
   where delivery.outbox_id = p_outbox_id
     and delivery.channel = 'email'
     and delivery.recipient_address_hash = v_address_hash;
  if found then
    return query select
      v_existing.id, v_existing.outbox_id, v_existing.recipient_kind,
      v_existing.recipient_address, v_existing.recipient_address_hash,
      v_existing.is_hidden_copy, v_existing.state;
    return;
  end if;
  if v_outbox.recipients_expanded_at is not null then
    raise exception 'notification recipient set is immutable'
      using errcode = '23514';
  end if;

  insert into public.booking_notification_deliveries (
    outbox_id, recipient_kind, recipient_address,
    recipient_address_hash, is_hidden_copy, channel,
    state, next_attempt_at
  ) values (
    p_outbox_id, p_recipient_kind, v_address,
    v_address_hash, p_recipient_kind = 'system_copy', 'email',
    'pending', clock_timestamp()
  ) returning * into v_existing;
  return query select
    v_existing.id, v_existing.outbox_id, v_existing.recipient_kind,
    v_existing.recipient_address, v_existing.recipient_address_hash,
    v_existing.is_hidden_copy, v_existing.state;
end;
$$;

comment on function public.register_booking_notification_delivery_v1(
  uuid, uuid, text, text
) is
  'Registers one immutable email recipient for a claimed outbox row using a search-path-safe SHA-256 address hash.';


-- SOURCE: 0083_booking_local_time_limit_requests.sql
-- Local time-limit approval for Triplover On Hold bookings.
--
-- supplier_ticketing_* is the current supplier evidence. The established
-- ticketing_deadline_at remains the operational/effective deadline so the
-- lifecycle resolver, issue/cancel claims, expiry worker, notifications and
-- reconciliation continue to use one authority. A local approval changes the
-- effective deadline only; supplier evidence is retained independently and in
-- append-only observations.

alter table public.flight_bookings
  add column if not exists supplier_ticketing_time_limit text,
  add column if not exists supplier_ticketing_deadline_at timestamptz,
  add column if not exists supplier_deadline_source text,
  add column if not exists local_ticketing_deadline_at timestamptz,
  add column if not exists active_local_time_limit_request_id uuid;

update public.flight_bookings
   set supplier_ticketing_time_limit = coalesce(
         supplier_ticketing_time_limit, ticketing_time_limit
       ),
       supplier_ticketing_deadline_at = coalesce(
         supplier_ticketing_deadline_at, ticketing_deadline_at
       ),
       supplier_deadline_source = coalesce(
         supplier_deadline_source, deadline_source, 'migration_baseline'
       )
 where lower(coalesce(supplier, '')) = 'triplover'
   and (
     supplier_ticketing_time_limit is null
     or supplier_ticketing_deadline_at is null
     or supplier_deadline_source is null
   );

alter table public.flight_bookings
  drop constraint if exists flight_bookings_deadline_source_check;
alter table public.flight_bookings
  add constraint flight_bookings_deadline_source_check
  check (
    deadline_source is null
    or deadline_source in ('supplier', 'pnr_call', 'assumed', 'local_approved')
  );

create table public.booking_deadline_observations (
  id                         uuid primary key default gen_random_uuid(),
  booking_id                 uuid not null
                             references public.flight_bookings(id)
                             on delete restrict,
  observation_source        text not null,
  supplier_status           text,
  supplier_time_limit_raw   text,
  supplier_deadline_at      timestamptz,
  supplier_deadline_source  text,
  actor_user_id              text not null,
  actor_role                 text not null,
  normalized_evidence        jsonb not null default '{}'::jsonb,
  evidence_hash              text not null,
  observed_at                timestamptz not null default clock_timestamp(),
  constraint booking_deadline_observations_source_check check (
    observation_source in ('migration_baseline', 'booking_create', 'pnr_sync')
  ),
  constraint booking_deadline_observations_actor_role_check check (
    actor_role in (
      'superadmin', 'admin', 'staff_support', 'staff_account',
      'customer', 'b2b', 'b2b_sub', 'system'
    )
  ),
  constraint booking_deadline_observations_hash_check check (
    evidence_hash ~ '^[a-f0-9]{64}$'
  ),
  unique (booking_id, evidence_hash)
);

create index booking_deadline_observations_booking_idx
  on public.booking_deadline_observations (booking_id, observed_at desc, id);

create table public.booking_local_time_limit_requests (
  id                         uuid primary key default gen_random_uuid(),
  booking_id                 uuid not null
                             references public.flight_bookings(id)
                             on delete restrict,
  state                      text not null default 'pending',
  eligibility_reason         text not null,
  supplier_time_limit_snapshot text,
  supplier_deadline_snapshot timestamptz,
  requested_by_user_id       text not null,
  requested_by_role          text not null,
  request_key                text not null,
  requested_at               timestamptz not null default clock_timestamp(),
  granted_minutes            integer,
  approved_deadline_at       timestamptz,
  verification_note          text,
  decided_by_user_id         text,
  decided_by_role            text,
  decided_at                 timestamptz,
  rejection_reason           text,
  superseded_at              timestamptz,
  superseded_reason          text,
  superseded_by_request_id   uuid
                             references public.booking_local_time_limit_requests(id)
                             on delete restrict,
  version                    integer not null default 1,
  created_at                 timestamptz not null default clock_timestamp(),
  updated_at                 timestamptz not null default clock_timestamp(),
  constraint booking_local_ttl_state_check check (
    state in ('pending', 'approved', 'rejected', 'superseded')
  ),
  constraint booking_local_ttl_reason_check check (
    eligibility_reason in (
      'supplier_deadline_missing',
      'supplier_deadline_under_15_minutes'
    )
  ),
  constraint booking_local_ttl_requester_role_check check (
    requested_by_role in ('b2b', 'b2b_sub', 'customer')
  ),
  constraint booking_local_ttl_decider_role_check check (
    decided_by_role is null
    or decided_by_role in ('superadmin', 'admin', 'staff_support')
  ),
  constraint booking_local_ttl_grant_check check (
    granted_minutes is null or granted_minutes between 1 and 30
  ),
  constraint booking_local_ttl_request_key_check check (
    char_length(request_key) between 1 and 255
  ),
  constraint booking_local_ttl_version_check check (version > 0),
  constraint booking_local_ttl_pending_shape_check check (
    state <> 'pending'
    or (
      granted_minutes is null and approved_deadline_at is null
      and verification_note is null and decided_by_user_id is null
      and decided_by_role is null and decided_at is null
      and rejection_reason is null and superseded_at is null
    )
  ),
  constraint booking_local_ttl_approved_shape_check check (
    state <> 'approved'
    or (
      granted_minutes is not null and approved_deadline_at is not null
      and verification_note is not null and decided_by_user_id is not null
      and decided_by_role is not null and decided_at is not null
      and rejection_reason is null
    )
  ),
  constraint booking_local_ttl_rejected_shape_check check (
    state <> 'rejected'
    or (
      rejection_reason is not null and decided_by_user_id is not null
      and decided_by_role is not null and decided_at is not null
      and granted_minutes is null and approved_deadline_at is null
    )
  ),
  unique (requested_by_user_id, request_key)
);

create unique index booking_local_ttl_one_pending_idx
  on public.booking_local_time_limit_requests (booking_id)
  where state = 'pending';
create index booking_local_ttl_queue_idx
  on public.booking_local_time_limit_requests (requested_at, id)
  where state = 'pending';
create index booking_local_ttl_booking_history_idx
  on public.booking_local_time_limit_requests (booking_id, requested_at desc, id);

alter table public.flight_bookings
  add constraint flight_bookings_active_local_ttl_request_fk
  foreign key (active_local_time_limit_request_id)
  references public.booking_local_time_limit_requests(id)
  on delete restrict
  not valid;

create table public.booking_local_time_limit_events (
  id                    bigint generated always as identity primary key,
  booking_id            uuid not null
                        references public.flight_bookings(id) on delete restrict,
  request_id            uuid not null
                        references public.booking_local_time_limit_requests(id)
                        on delete restrict,
  event_type            text not null,
  actor_user_id         text not null,
  actor_role            text not null,
  prior_deadline_at     timestamptz,
  resulting_deadline_at timestamptz,
  granted_minutes       integer,
  reason                text,
  operation_request_key text,
  evidence              jsonb not null default '{}'::jsonb,
  created_at            timestamptz not null default clock_timestamp(),
  constraint booking_local_ttl_events_type_check check (
    event_type in (
      'requested', 'approved', 'rejected', 'superseded',
      'used_for_ticketing', 'used_for_cancellation', 'supplier_conflict'
    )
  ),
  constraint booking_local_ttl_events_actor_role_check check (
    actor_role in (
      'superadmin', 'admin', 'staff_support', 'staff_account',
      'customer', 'b2b', 'b2b_sub', 'system'
    )
  ),
  constraint booking_local_ttl_events_grant_check check (
    granted_minutes is null or granted_minutes between 1 and 30
  )
);

create index booking_local_ttl_events_booking_idx
  on public.booking_local_time_limit_events (booking_id, created_at desc, id);
create unique index booking_local_ttl_events_operation_once_idx
  on public.booking_local_time_limit_events (
    request_id, event_type, operation_request_key
  ) where operation_request_key is not null;

create or replace function public.prevent_booking_deadline_audit_mutation()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  raise exception 'booking deadline audit records are immutable'
    using errcode = '55000';
end;
$$;

create trigger booking_deadline_observations_immutable
  before update or delete on public.booking_deadline_observations
  for each row execute function public.prevent_booking_deadline_audit_mutation();
create trigger booking_local_ttl_events_immutable
  before update or delete on public.booking_local_time_limit_events
  for each row execute function public.prevent_booking_deadline_audit_mutation();

create trigger booking_local_ttl_requests_touch_updated_at
  before update on public.booking_local_time_limit_requests
  for each row execute function public.touch_updated_at();

-- Capture legacy writers as supplier evidence and prevent them from replacing
-- an active local effective deadline during a rolling application deployment.
create or replace function public.enforce_booking_deadline_authority_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_local_authority_write boolean;
  v_explicit_supplier_write boolean;
  v_legacy_deadline_write boolean;
begin
  if tg_op = 'INSERT' then
    new.supplier_ticketing_time_limit := coalesce(
      new.supplier_ticketing_time_limit, new.ticketing_time_limit
    );
    new.supplier_ticketing_deadline_at := coalesce(
      new.supplier_ticketing_deadline_at, new.ticketing_deadline_at
    );
    new.supplier_deadline_source := coalesce(
      new.supplier_deadline_source, new.deadline_source, 'booking_create'
    );
    if new.active_local_time_limit_request_id is not null then
      new.ticketing_deadline_at := new.local_ticketing_deadline_at;
      new.deadline_source := 'local_approved';
    end if;
    return new;
  end if;

  v_local_authority_write :=
    new.active_local_time_limit_request_id is distinct from
      old.active_local_time_limit_request_id
    or new.local_ticketing_deadline_at is distinct from
      old.local_ticketing_deadline_at;
  v_explicit_supplier_write :=
    new.supplier_ticketing_time_limit is distinct from
      old.supplier_ticketing_time_limit
    or new.supplier_ticketing_deadline_at is distinct from
      old.supplier_ticketing_deadline_at
    or new.supplier_deadline_source is distinct from
      old.supplier_deadline_source;
  v_legacy_deadline_write :=
    new.ticketing_time_limit is distinct from old.ticketing_time_limit
    or new.ticketing_deadline_at is distinct from old.ticketing_deadline_at
    or new.deadline_source is distinct from old.deadline_source;

  if not v_local_authority_write
     and not v_explicit_supplier_write
     and v_legacy_deadline_write then
    new.supplier_ticketing_time_limit := new.ticketing_time_limit;
    new.supplier_ticketing_deadline_at := new.ticketing_deadline_at;
    new.supplier_deadline_source := coalesce(
      new.deadline_source, 'legacy_supplier_writer'
    );
  end if;

  if new.active_local_time_limit_request_id is not null then
    new.ticketing_deadline_at := new.local_ticketing_deadline_at;
    new.deadline_source := 'local_approved';
    new.ticketing_time_limit := new.supplier_ticketing_time_limit;
  elsif v_local_authority_write or v_explicit_supplier_write
        or v_legacy_deadline_write then
    new.ticketing_time_limit := new.supplier_ticketing_time_limit;
    new.ticketing_deadline_at := new.supplier_ticketing_deadline_at;
    new.deadline_source := case
      when new.supplier_ticketing_deadline_at is null
        then coalesce(new.supplier_deadline_source, 'pnr_call')
      when new.supplier_deadline_source in ('supplier', 'pnr_call', 'assumed')
        then new.supplier_deadline_source
      else 'pnr_call'
    end;
  end if;
  return new;
end;
$$;

create trigger flight_bookings_deadline_authority_v1
  before insert or update of
    ticketing_time_limit, ticketing_deadline_at, deadline_source,
    supplier_ticketing_time_limit, supplier_ticketing_deadline_at,
    supplier_deadline_source, local_ticketing_deadline_at,
    active_local_time_limit_request_id
  on public.flight_bookings
  for each row execute function public.enforce_booking_deadline_authority_v1();

insert into public.booking_deadline_observations (
  booking_id, observation_source, supplier_status,
  supplier_time_limit_raw, supplier_deadline_at, supplier_deadline_source,
  actor_user_id, actor_role, normalized_evidence, evidence_hash, observed_at
)
select
  booking.id, 'migration_baseline', booking.booking_status,
  booking.supplier_ticketing_time_limit,
  booking.supplier_ticketing_deadline_at,
  booking.supplier_deadline_source,
  'system:migration-0083', 'system',
  jsonb_build_object('migration', '0083', 'preservedOriginalEvidence', true),
  encode(sha256(convert_to(concat_ws('|',
    booking.id::text, 'migration_baseline',
    coalesce(booking.supplier_ticketing_time_limit, ''),
    coalesce(booking.supplier_ticketing_deadline_at::text, ''),
    coalesce(booking.supplier_deadline_source, '')
  ), 'UTF8')), 'hex'),
  clock_timestamp()
from public.flight_bookings booking
on conflict do nothing;

create or replace function public.record_initial_booking_deadline_observation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare v_hash text;
begin
  v_hash := encode(sha256(convert_to(concat_ws('|',
    new.id::text, 'booking_create',
    coalesce(new.supplier_ticketing_time_limit, ''),
    coalesce(new.supplier_ticketing_deadline_at::text, ''),
    coalesce(new.supplier_deadline_source, '')
  ), 'UTF8')), 'hex');
  insert into public.booking_deadline_observations (
    booking_id, observation_source, supplier_status,
    supplier_time_limit_raw, supplier_deadline_at, supplier_deadline_source,
    actor_user_id, actor_role, normalized_evidence, evidence_hash
  ) values (
    new.id, 'booking_create', new.booking_status,
    new.supplier_ticketing_time_limit, new.supplier_ticketing_deadline_at,
    new.supplier_deadline_source, 'system:booking-create', 'system',
    '{}'::jsonb, v_hash
  ) on conflict do nothing;
  return new;
end;
$$;

create trigger flight_bookings_initial_deadline_observation_v1
  after insert on public.flight_bookings
  for each row execute function public.record_initial_booking_deadline_observation_v1();

-- Users submit no duration. Eligibility and ownership are decided under the
-- booking row lock using database time and the stored user/agency registry.
create or replace function public.request_booking_local_time_limit_v1(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
  v_actor_agency text;
  v_existing public.booking_local_time_limit_requests;
  v_request public.booking_local_time_limit_requests;
  v_reason text;
begin
  if nullif(btrim(p_actor_user_id), '') is null
     or p_actor_role not in ('b2b', 'b2b_sub', 'customer')
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 255 then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_FORBIDDEN');
  end if;

  select role, agency_code into v_actor_role, v_actor_agency
    from public.app_users where clerk_id = p_actor_user_id;
  if not found or v_actor_role is distinct from p_actor_role then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_FORBIDDEN');
  end if;

  select * into v_booking from public.flight_bookings
   where id = p_booking_id and not legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  if not (
    (p_actor_role = 'customer'
      and v_booking.booking_owner_type = 'user'
      and v_booking.booking_owner_key = p_actor_user_id)
    or
    (p_actor_role in ('b2b', 'b2b_sub')
      and v_actor_agency is not null
      and v_booking.booking_owner_type = 'agency'
      and v_booking.booking_owner_key = v_actor_agency)
  ) then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_FORBIDDEN');
  end if;

  select * into v_existing
    from public.booking_local_time_limit_requests
   where requested_by_user_id = p_actor_user_id
     and request_key = p_request_key;
  if found then
    if v_existing.booking_id is distinct from p_booking_id then
      return jsonb_build_object('ok', false, 'code', 'REQUEST_KEY_CONFLICT');
    end if;
    return jsonb_build_object(
      'ok', true, 'replay', true, 'requestId', v_existing.id,
      'state', v_existing.state, 'requestedAt', v_existing.requested_at,
      'version', v_existing.version
    );
  end if;

  if lower(coalesce(v_booking.supplier, '')) <> 'triplover'
     or v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.direct_ticketing
     or v_booking.issued_at is not null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ELIGIBLE');
  end if;
  if not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_UNCONFIRMED');
  end if;
  if exists (
    select 1 from public.booking_reconciliation_cases c
     where c.subject_booking_id = p_booking_id
       and c.state in (
         'open', 'assigned', 'awaiting_supplier',
         'awaiting_finance', 'awaiting_approval'
       )
  ) then
    return jsonb_build_object(
      'ok', false, 'code', 'BOOKING_RECONCILIATION_REQUIRED'
    );
  end if;
  if v_booking.active_local_time_limit_request_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', case
        when v_booking.local_ticketing_deadline_at <= clock_timestamp()
          then 'BOOKING_EXPIRED'
        else 'LOCAL_TIME_LIMIT_ACTIVE'
      end
    );
  end if;
  if v_booking.supplier_ticketing_deadline_at >=
       clock_timestamp() + interval '15 minutes' then
    return jsonb_build_object(
      'ok', false, 'code', 'SUPPLIER_DEADLINE_SUFFICIENT'
    );
  end if;

  select * into v_existing
    from public.booking_local_time_limit_requests
   where booking_id = p_booking_id and state = 'pending'
   for update;
  if found then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'requestId', v_existing.id,
      'state', v_existing.state, 'requestedAt', v_existing.requested_at,
      'version', v_existing.version
    );
  end if;

  v_reason := case
    when v_booking.supplier_ticketing_deadline_at is null
      then 'supplier_deadline_missing'
    else 'supplier_deadline_under_15_minutes'
  end;
  insert into public.booking_local_time_limit_requests (
    booking_id, eligibility_reason, supplier_time_limit_snapshot,
    supplier_deadline_snapshot, requested_by_user_id,
    requested_by_role, request_key
  ) values (
    p_booking_id, v_reason, v_booking.supplier_ticketing_time_limit,
    v_booking.supplier_ticketing_deadline_at, p_actor_user_id,
    p_actor_role, p_request_key
  ) returning * into v_request;

  insert into public.booking_local_time_limit_events (
    booking_id, request_id, event_type, actor_user_id, actor_role,
    prior_deadline_at, reason, evidence
  ) values (
    p_booking_id, v_request.id, 'requested', p_actor_user_id, p_actor_role,
    v_booking.ticketing_deadline_at, v_reason,
    jsonb_build_object(
      'supplierTimeLimit', v_booking.supplier_ticketing_time_limit,
      'supplierDeadlineAt', v_booking.supplier_ticketing_deadline_at,
      'thresholdMinutes', 15,
      'walletMutation', false
    )
  );
  return jsonb_build_object(
    'ok', true, 'replay', false, 'requestId', v_request.id,
    'state', v_request.state, 'requestedAt', v_request.requested_at,
    'version', v_request.version
  );
end;
$$;

-- Staff chooses the duration only after supplier-portal verification. The
-- optimistic version prevents two staff decisions from racing.
create or replace function public.decide_booking_local_time_limit_v1(
  p_booking_id uuid,
  p_request_id uuid,
  p_expected_version integer,
  p_actor_user_id text,
  p_action text,
  p_granted_minutes numeric,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_request public.booking_local_time_limit_requests;
  v_actor_role text;
  v_granted_minutes integer;
  v_approved_at timestamptz;
  v_deadline timestamptz;
  v_before_lifecycle text;
  v_after_lifecycle text;
begin
  select role into v_actor_role
    from public.app_users where clerk_id = p_actor_user_id;
  if not found or v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'DECISION_FORBIDDEN');
  end if;
  if p_action not in ('approve', 'reject')
     or p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_reason), '') is null
     or char_length(btrim(p_reason)) < 3
     or char_length(btrim(p_reason)) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_DECISION');
  end if;

  select * into v_booking from public.flight_bookings
   where id = p_booking_id and not legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select * into v_request from public.booking_local_time_limit_requests
   where id = p_request_id and booking_id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND');
  end if;
  if v_request.state <> 'pending'
     or v_request.version <> p_expected_version then
    return jsonb_build_object(
      'ok', false, 'code', 'REQUEST_VERSION_CONFLICT',
      'state', v_request.state, 'version', v_request.version
    );
  end if;

  if p_action = 'reject' then
    update public.booking_local_time_limit_requests set
      state = 'rejected', rejection_reason = btrim(p_reason),
      decided_by_user_id = p_actor_user_id,
      decided_by_role = v_actor_role, decided_at = clock_timestamp(),
      version = version + 1
    where id = p_request_id returning * into v_request;
    insert into public.booking_local_time_limit_events (
      booking_id, request_id, event_type, actor_user_id, actor_role,
      prior_deadline_at, reason, evidence
    ) values (
      p_booking_id, p_request_id, 'rejected', p_actor_user_id, v_actor_role,
      v_booking.ticketing_deadline_at, btrim(p_reason),
      jsonb_build_object('walletMutation', false)
    );
    return jsonb_build_object(
      'ok', true, 'requestId', v_request.id, 'state', v_request.state,
      'version', v_request.version
    );
  end if;

  if p_granted_minutes is null
     or p_granted_minutes <> trunc(p_granted_minutes)
     or p_granted_minutes < 1
     or p_granted_minutes > 30 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_GRANT_MINUTES');
  end if;
  v_granted_minutes := p_granted_minutes::integer;
  if lower(coalesce(v_booking.supplier, '')) <> 'triplover'
     or v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.direct_ticketing
     or v_booking.issued_at is not null
     or not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ELIGIBLE');
  end if;
  if exists (
    select 1 from public.booking_reconciliation_cases c
     where c.subject_booking_id = p_booking_id
       and c.state in (
         'open', 'assigned', 'awaiting_supplier',
         'awaiting_finance', 'awaiting_approval'
       )
  ) then
    return jsonb_build_object(
      'ok', false, 'code', 'BOOKING_RECONCILIATION_REQUIRED'
    );
  end if;

  if v_booking.supplier_ticketing_deadline_at >=
       clock_timestamp() + interval '15 minutes' then
    update public.booking_local_time_limit_requests set
      state = 'superseded', superseded_at = clock_timestamp(),
      superseded_reason = 'supplier_deadline_now_sufficient',
      version = version + 1
    where id = p_request_id returning * into v_request;
    insert into public.booking_local_time_limit_events (
      booking_id, request_id, event_type, actor_user_id, actor_role,
      prior_deadline_at, resulting_deadline_at, reason, evidence
    ) values (
      p_booking_id, p_request_id, 'superseded', p_actor_user_id, v_actor_role,
      v_booking.ticketing_deadline_at,
      v_booking.supplier_ticketing_deadline_at,
      'supplier_deadline_now_sufficient',
      jsonb_build_object('thresholdMinutes', 15, 'walletMutation', false)
    );
    return jsonb_build_object(
      'ok', false, 'code', 'SUPPLIER_DEADLINE_SUFFICIENT',
      'requestId', v_request.id, 'state', v_request.state,
      'version', v_request.version
    );
  end if;

  v_before_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  v_approved_at := clock_timestamp();
  v_deadline := v_approved_at + make_interval(mins => v_granted_minutes);
  update public.booking_local_time_limit_requests set
    state = 'approved', granted_minutes = v_granted_minutes,
    approved_deadline_at = v_deadline,
    verification_note = btrim(p_reason),
    decided_by_user_id = p_actor_user_id,
    decided_by_role = v_actor_role, decided_at = v_approved_at,
    version = version + 1
  where id = p_request_id returning * into v_request;

  if v_booking.active_local_time_limit_request_id is not null
     and v_booking.active_local_time_limit_request_id <> p_request_id then
    update public.booking_local_time_limit_requests set
      state = 'superseded', superseded_at = clock_timestamp(),
      superseded_reason = 'replaced_by_new_approval',
      superseded_by_request_id = p_request_id, version = version + 1
    where id = v_booking.active_local_time_limit_request_id
      and state = 'approved';
  end if;
  update public.flight_bookings set
    local_ticketing_deadline_at = v_deadline,
    active_local_time_limit_request_id = p_request_id,
    ticketing_deadline_at = v_deadline,
    deadline_source = 'local_approved'
  where id = p_booking_id
  returning * into v_booking;

  insert into public.booking_local_time_limit_events (
    booking_id, request_id, event_type, actor_user_id, actor_role,
    prior_deadline_at, resulting_deadline_at, granted_minutes, reason, evidence
  ) values (
    p_booking_id, p_request_id, 'approved', p_actor_user_id, v_actor_role,
    v_request.supplier_deadline_snapshot, v_deadline,
    v_granted_minutes, btrim(p_reason),
    jsonb_build_object(
      'supplierPortalVerified', true,
      'supplierDeadlinePreserved', true,
      'walletMutation', false
    )
  );

  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  if v_after_lifecycle is distinct from v_before_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation,
      supplier_evidence, idempotency_key
    ) values (
      p_booking_id, v_before_lifecycle, v_after_lifecycle,
      v_booking.status, v_booking.status, v_booking.operation_kind,
      v_booking.operation_reason, p_actor_user_id, 'LocalTimeLimitApproval',
      jsonb_build_object(
        'requestId', p_request_id, 'grantedMinutes', v_granted_minutes,
        'approvedDeadlineAt', v_deadline, 'walletMutation', false
      ), 'local-time-limit:' || p_request_id::text || ':approved'
    ) on conflict do nothing;
  end if;
  return jsonb_build_object(
    'ok', true, 'requestId', v_request.id, 'state', v_request.state,
    'grantedMinutes', v_granted_minutes,
    'approvedDeadlineAt', v_deadline,
    'lifecycleStatus', v_after_lifecycle, 'version', v_request.version
  );
end;
$$;

-- PNR V3 records explicit NULL deadlines, keeps local and supplier authority
-- separate, and supersedes a local grant if the supplier later supplies a
-- normal (>= 15 minute) deadline or terminal truth.
create or replace function public.record_booking_pnr_refresh_v3(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_sync_source text,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticketing_time_limit text,
  p_ticketing_deadline_at timestamptz,
  p_normalized_evidence jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_before public.flight_bookings;
  v_after_sync public.flight_bookings;
  v_after public.flight_bookings;
  v_request_id uuid;
  v_target text;
  v_hash text;
  v_before_lifecycle text;
  v_after_sync_lifecycle text;
  v_after_lifecycle text;
  v_supersede_reason text;
begin
  select * into v_before from public.flight_bookings
   where id = p_booking_id and not legacy_operational for update;
  if not found then raise exception 'booking not found' using errcode = 'P0002'; end if;

  v_before_lifecycle := public.resolve_booking_lifecycle(
    v_before.status, v_before.airlines_pnr,
    v_before.ticketing_deadline_at, v_before.operation_kind
  );
  v_after_sync := public.record_booking_pnr_refresh_v2(
    p_booking_id, p_actor_user_id, p_actor_role, p_sync_source,
    p_supplier_status, p_airlines_pnr, null, null,
    coalesce(p_normalized_evidence, '{}'::jsonb)
  );
  v_after_sync_lifecycle := public.resolve_booking_lifecycle(
    v_after_sync.status, v_after_sync.airlines_pnr,
    v_after_sync.ticketing_deadline_at, v_after_sync.operation_kind
  );
  v_target := case lower(btrim(coalesce(p_supplier_status, '')))
    when 'issued' then 'confirmed'
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    else null
  end;
  v_hash := encode(sha256(convert_to(concat_ws('|',
    p_booking_id::text, 'pnr_sync', coalesce(p_sync_source, ''),
    coalesce(p_supplier_status, ''), coalesce(p_ticketing_time_limit, ''),
    coalesce(p_ticketing_deadline_at::text, ''),
    coalesce(p_normalized_evidence, '{}'::jsonb)::text
  ), 'UTF8')), 'hex');
  insert into public.booking_deadline_observations (
    booking_id, observation_source, supplier_status,
    supplier_time_limit_raw, supplier_deadline_at, supplier_deadline_source,
    actor_user_id, actor_role, normalized_evidence, evidence_hash
  ) values (
    p_booking_id, 'pnr_sync', p_supplier_status,
    p_ticketing_time_limit, p_ticketing_deadline_at, 'pnr_call',
    p_actor_user_id, p_actor_role,
    coalesce(p_normalized_evidence, '{}'::jsonb), v_hash
  ) on conflict do nothing;

  v_request_id := v_after_sync.active_local_time_limit_request_id;
  v_supersede_reason := case
    when v_target is not null then 'supplier_terminal_evidence'
    when p_ticketing_deadline_at >= clock_timestamp() + interval '15 minutes'
      then 'supplier_deadline_now_sufficient'
    else null
  end;
  if v_request_id is not null and v_supersede_reason is not null then
    update public.booking_local_time_limit_requests set
      state = 'superseded', superseded_at = clock_timestamp(),
      superseded_reason = v_supersede_reason, version = version + 1
    where id = v_request_id and state = 'approved';
    insert into public.booking_local_time_limit_events (
      booking_id, request_id, event_type, actor_user_id, actor_role,
      prior_deadline_at, resulting_deadline_at, reason, evidence
    ) values (
      p_booking_id, v_request_id,
      case when v_target is null then 'superseded' else 'supplier_conflict' end,
      p_actor_user_id, p_actor_role,
      v_after_sync.local_ticketing_deadline_at, p_ticketing_deadline_at,
      v_supersede_reason,
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'supplierDeadlineAt', p_ticketing_deadline_at,
        'walletMutation', false
      )
    );
  end if;

  update public.flight_bookings set
    supplier_ticketing_time_limit = p_ticketing_time_limit,
    supplier_ticketing_deadline_at = p_ticketing_deadline_at,
    supplier_deadline_source = 'pnr_call',
    active_local_time_limit_request_id = case
      when v_supersede_reason is not null then null
      else active_local_time_limit_request_id
    end,
    ticketing_time_limit = p_ticketing_time_limit,
    ticketing_deadline_at = case
      when v_supersede_reason is not null then p_ticketing_deadline_at
      when active_local_time_limit_request_id is not null
        then local_ticketing_deadline_at
      else p_ticketing_deadline_at
    end,
    deadline_source = case
      when v_supersede_reason is null
           and active_local_time_limit_request_id is not null
        then 'local_approved'
      else 'pnr_call'
    end
  where id = p_booking_id returning * into v_after;

  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_after.status, v_after.airlines_pnr,
    v_after.ticketing_deadline_at, v_after.operation_kind
  );
  if v_after_lifecycle is distinct from v_after_sync_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation,
      supplier_evidence, idempotency_key
    ) values (
      p_booking_id, v_after_sync_lifecycle, v_after_lifecycle,
      v_after_sync.status, v_after.status, v_after.operation_kind,
      v_after.operation_reason, p_actor_user_id, 'PnrRefreshV3',
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'supplierDeadlineAt', p_ticketing_deadline_at,
        'localGrantSuperseded', v_supersede_reason is not null,
        'walletMutation', false
      ), 'pnr-refresh-v3:' || v_hash
    ) on conflict do nothing;
  end if;
  return v_after;
end;
$$;

-- AirTicketingDetails has no TTL field. It retains deadline evidence but closes
-- an active local grant when terminal supplier evidence is observed.
create or replace function public.record_booking_supplier_refresh_v3(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_sync_source text,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticket_numbers jsonb,
  p_issued_at timestamptz,
  p_cancelled_at timestamptz,
  p_normalized_evidence jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_after_sync public.flight_bookings;
  v_after public.flight_bookings;
  v_request_id uuid;
  v_target text;
  v_before_clear_lifecycle text;
  v_after_lifecycle text;
begin
  v_after_sync := public.record_booking_supplier_refresh_v2(
    p_booking_id, p_actor_user_id, p_actor_role, p_sync_source,
    p_supplier_status, p_airlines_pnr, p_ticket_numbers,
    p_issued_at, p_cancelled_at,
    coalesce(p_normalized_evidence, '{}'::jsonb)
  );
  v_target := case lower(btrim(coalesce(p_supplier_status, '')))
    when 'issued' then 'confirmed'
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    else null
  end;
  v_request_id := v_after_sync.active_local_time_limit_request_id;
  if v_target is null or v_request_id is null then
    return v_after_sync;
  end if;
  v_before_clear_lifecycle := public.resolve_booking_lifecycle(
    v_after_sync.status, v_after_sync.airlines_pnr,
    v_after_sync.ticketing_deadline_at, v_after_sync.operation_kind
  );
  update public.booking_local_time_limit_requests set
    state = 'superseded', superseded_at = clock_timestamp(),
    superseded_reason = 'supplier_terminal_evidence', version = version + 1
  where id = v_request_id and state = 'approved';
  insert into public.booking_local_time_limit_events (
    booking_id, request_id, event_type, actor_user_id, actor_role,
    prior_deadline_at, reason, evidence
  ) values (
    p_booking_id, v_request_id, 'supplier_conflict',
    p_actor_user_id, p_actor_role,
    v_after_sync.local_ticketing_deadline_at,
    'supplier_terminal_evidence',
    jsonb_build_object(
      'supplierStatus', p_supplier_status,
      'source', 'AirTicketingDetails', 'walletMutation', false
    )
  );
  update public.flight_bookings set
    active_local_time_limit_request_id = null,
    ticketing_deadline_at = supplier_ticketing_deadline_at,
    deadline_source = case
      when supplier_ticketing_deadline_at is null then 'pnr_call'
      when supplier_deadline_source in ('supplier', 'pnr_call', 'assumed')
        then supplier_deadline_source
      else 'pnr_call'
    end
  where id = p_booking_id returning * into v_after;
  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_after.status, v_after.airlines_pnr,
    v_after.ticketing_deadline_at, v_after.operation_kind
  );
  if v_after_lifecycle is distinct from v_before_clear_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation,
      supplier_evidence
    ) values (
      p_booking_id, v_before_clear_lifecycle, v_after_lifecycle,
      v_after_sync.status, v_after.status, v_after.operation_kind,
      v_after.operation_reason, p_actor_user_id,
      'SupplierRefreshV3LocalGrantClosed',
      jsonb_build_object(
        'requestId', v_request_id, 'supplierStatus', p_supplier_status,
        'walletMutation', false
      )
    );
  end if;
  return v_after;
end;
$$;

-- Add the local-deadline gate to the established transactional claims. The
-- pricing_snapshot sellingPrice reserve/capture behavior is intentionally
-- unchanged.
create or replace function public.wallet_begin_booking_issue(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_amount bigint;
  v_result jsonb;
begin
  select * into v_booking from public.flight_bookings
   where id = p_booking_id and not legacy_operational for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND'); end if;
  if v_booking.status = 'confirmed' or v_booking.payment_state = 'captured' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;
  if v_booking.status <> 'on-hold' or v_booking.operation_kind is not null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_UNCONFIRMED');
  end if;
  if v_booking.active_local_time_limit_request_id is not null then
    if v_booking.local_ticketing_deadline_at is null
       or v_booking.local_ticketing_deadline_at <= clock_timestamp() then
      return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
    end if;
  elsif v_booking.supplier_ticketing_deadline_at is null
     or v_booking.supplier_ticketing_deadline_at <
          clock_timestamp() + interval '15 minutes' then
    return jsonb_build_object('ok', false, 'code', 'LOCAL_TIME_LIMIT_REQUIRED');
  end if;
  if v_booking.ticketing_deadline_at is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_DEADLINE_REQUIRED');
  end if;
  if v_booking.ticketing_deadline_at <= clock_timestamp() then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
  end if;
  if v_booking.booking_owner_type is null or v_booking.booking_owner_key is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_OWNER_REQUIRED');
  end if;
  begin
    v_amount := round((v_booking.pricing_snapshot->>'sellingPrice')::numeric * 100)::bigint;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end;
  v_result := public.wallet_reserve_amount(
    v_booking.id, null, v_booking.booking_owner_type,
    v_booking.booking_owner_key, v_amount, v_booking.currency,
    p_actor_user_id, p_actor_role, p_idempotency_key, v_booking.public_ref
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then return v_result; end if;
  if v_booking.active_local_time_limit_request_id is not null then
    insert into public.booking_local_time_limit_events (
      booking_id, request_id, event_type, actor_user_id, actor_role,
      resulting_deadline_at, operation_request_key, evidence
    ) values (
      p_booking_id, v_booking.active_local_time_limit_request_id,
      'used_for_ticketing', p_actor_user_id, p_actor_role,
      v_booking.local_ticketing_deadline_at, p_idempotency_key,
      jsonb_build_object('walletAmountMinor', v_amount)
    ) on conflict do nothing;
  end if;
  update public.flight_bookings set
    status = 'in-progress', operation_kind = 'ticketing',
    operation_reason = 'ticketing', operation_request_id = p_idempotency_key,
    operation_actor_user_id = p_actor_user_id, operation_started_at = now(),
    operation_prior_status = 'on-hold'
  where id = p_booking_id;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation, idempotency_key
  ) values (
    p_booking_id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'ticketing', 'ticketing', p_actor_user_id, 'NewTicket',
    p_idempotency_key || ':ticketing-start'
  ) on conflict do nothing;
  return v_result || jsonb_build_object('status', 'in-progress');
end;
$$;

create or replace function public.begin_booking_cancellation(
  p_booking_id uuid,
  p_actor_user_id text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
begin
  select * into v_booking from public.flight_bookings
   where id = p_booking_id and not legacy_operational for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND'); end if;
  if v_booking.status <> 'on-hold' or v_booking.operation_kind is not null
     or v_booking.issued_at is not null or v_booking.direct_ticketing
     or v_booking.payment_state in ('held','captured','reconciliation') then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_CANCELLABLE');
  end if;
  if not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_UNCONFIRMED');
  end if;
  if v_booking.active_local_time_limit_request_id is not null then
    if v_booking.local_ticketing_deadline_at is null
       or v_booking.local_ticketing_deadline_at <= clock_timestamp() then
      return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
    end if;
  elsif v_booking.supplier_ticketing_deadline_at is null
     or v_booking.supplier_ticketing_deadline_at <
          clock_timestamp() + interval '15 minutes' then
    return jsonb_build_object('ok', false, 'code', 'LOCAL_TIME_LIMIT_REQUIRED');
  end if;
  if v_booking.ticketing_deadline_at is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_DEADLINE_REQUIRED');
  end if;
  if v_booking.ticketing_deadline_at <= clock_timestamp() then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
  end if;
  if v_booking.active_local_time_limit_request_id is not null then
    select role into v_actor_role
      from public.app_users where clerk_id = p_actor_user_id;
    insert into public.booking_local_time_limit_events (
      booking_id, request_id, event_type, actor_user_id, actor_role,
      resulting_deadline_at, operation_request_key, evidence
    ) values (
      p_booking_id, v_booking.active_local_time_limit_request_id,
      'used_for_cancellation', p_actor_user_id,
      case
        when v_actor_role in (
          'superadmin', 'admin', 'staff_support', 'staff_account',
          'customer', 'b2b', 'b2b_sub'
        ) then v_actor_role
        else 'system'
      end,
      v_booking.local_ticketing_deadline_at, p_idempotency_key,
      jsonb_build_object('walletMutation', false)
    ) on conflict do nothing;
  end if;
  update public.flight_bookings set
    status = 'in-progress', operation_kind = 'cancellation',
    operation_reason = 'cancellation', operation_request_id = p_idempotency_key,
    operation_actor_user_id = p_actor_user_id, operation_started_at = now(),
    operation_prior_status = 'on-hold'
  where id = p_booking_id;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation, idempotency_key
  ) values (
    p_booking_id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'cancellation', 'cancellation', p_actor_user_id, 'Cancel',
    p_idempotency_key || ':cancellation-start'
  ) on conflict do nothing;
  return jsonb_build_object('ok', true, 'status', 'in-progress');
end;
$$;

