  'Approves or rejects after staff verification. Approval sets the effective deadline without changing wallet state or supplier evidence.';


-- SOURCE: 0084_local_time_limit_expired_request_cap.sql
-- Keep the existing NULL and under-15-minute eligibility paths, but cap new
-- requests for an expired supplier deadline at three hours. The request RPC
-- and the direct-write trigger both use database time as the authority.

alter table public.booking_local_time_limit_requests
  drop constraint if exists booking_local_ttl_reason_check;
alter table public.booking_local_time_limit_requests
  add constraint booking_local_ttl_reason_check check (
    eligibility_reason in (
      'supplier_deadline_missing',
      'supplier_deadline_under_15_minutes',
      'supplier_deadline_expired_under_3_hours'
    )
  );

create or replace function public.request_booking_local_time_limit_v1(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
  v_actor_agency text;
  v_existing public.booking_local_time_limit_requests;
  v_request public.booking_local_time_limit_requests;
  v_reason text;
  v_now timestamptz;
begin
  if nullif(btrim(p_actor_user_id), '') is null
     or p_actor_role not in ('b2b', 'b2b_sub', 'customer')
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 255 then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_FORBIDDEN');
  end if;

  select role, agency_code into v_actor_role, v_actor_agency
    from public.app_users where clerk_id = p_actor_user_id;
  if not found or v_actor_role is distinct from p_actor_role then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_FORBIDDEN');
  end if;

  select * into v_booking from public.flight_bookings
   where id = p_booking_id and not legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  v_now := clock_timestamp();

  if not (
    (p_actor_role = 'customer'
      and v_booking.booking_owner_type = 'user'
      and v_booking.booking_owner_key = p_actor_user_id)
    or
    (p_actor_role in ('b2b', 'b2b_sub')
      and v_actor_agency is not null
      and v_booking.booking_owner_type = 'agency'
      and v_booking.booking_owner_key = v_actor_agency)
  ) then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_FORBIDDEN');
  end if;

  select * into v_existing
    from public.booking_local_time_limit_requests
   where requested_by_user_id = p_actor_user_id
     and request_key = p_request_key;
  if found then
    if v_existing.booking_id is distinct from p_booking_id then
      return jsonb_build_object('ok', false, 'code', 'REQUEST_KEY_CONFLICT');
    end if;
    return jsonb_build_object(
      'ok', true, 'replay', true, 'requestId', v_existing.id,
      'state', v_existing.state, 'requestedAt', v_existing.requested_at,
      'version', v_existing.version
    );
  end if;

  if lower(coalesce(v_booking.supplier, '')) <> 'triplover'
     or v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.direct_ticketing
     or v_booking.issued_at is not null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ELIGIBLE');
  end if;
  if not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_UNCONFIRMED');
  end if;
  if exists (
    select 1 from public.booking_reconciliation_cases c
     where c.subject_booking_id = p_booking_id
       and c.state in (
         'open', 'assigned', 'awaiting_supplier',
         'awaiting_finance', 'awaiting_approval'
       )
  ) then
    return jsonb_build_object(
      'ok', false, 'code', 'BOOKING_RECONCILIATION_REQUIRED'
    );
  end if;
  if v_booking.active_local_time_limit_request_id is not null then
    return jsonb_build_object(
      'ok', false,
      'code', case
        when v_booking.local_ticketing_deadline_at <= v_now
          then 'BOOKING_EXPIRED'
        else 'LOCAL_TIME_LIMIT_ACTIVE'
      end
    );
  end if;
  if v_booking.supplier_ticketing_deadline_at >=
       v_now + interval '15 minutes' then
    return jsonb_build_object(
      'ok', false, 'code', 'SUPPLIER_DEADLINE_SUFFICIENT'
    );
  end if;
  if v_booking.supplier_ticketing_deadline_at <=
       v_now - interval '3 hours' then
    return jsonb_build_object(
      'ok', false, 'code', 'LOCAL_TIME_LIMIT_REQUEST_WINDOW_EXPIRED'
    );
  end if;

  select * into v_existing
    from public.booking_local_time_limit_requests
   where booking_id = p_booking_id and state = 'pending'
   for update;
  if found then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'requestId', v_existing.id,
      'state', v_existing.state, 'requestedAt', v_existing.requested_at,
      'version', v_existing.version
    );
  end if;

  v_reason := case
    when v_booking.supplier_ticketing_deadline_at is null
      then 'supplier_deadline_missing'
    when v_booking.supplier_ticketing_deadline_at <= v_now
      then 'supplier_deadline_expired_under_3_hours'
    else 'supplier_deadline_under_15_minutes'
  end;
  insert into public.booking_local_time_limit_requests (
    booking_id, eligibility_reason, supplier_time_limit_snapshot,
    supplier_deadline_snapshot, requested_by_user_id,
    requested_by_role, request_key
  ) values (
    p_booking_id, v_reason, v_booking.supplier_ticketing_time_limit,
    v_booking.supplier_ticketing_deadline_at, p_actor_user_id,
    p_actor_role, p_request_key
  ) returning * into v_request;

  insert into public.booking_local_time_limit_events (
    booking_id, request_id, event_type, actor_user_id, actor_role,
    prior_deadline_at, reason, evidence
  ) values (
    p_booking_id, v_request.id, 'requested', p_actor_user_id, p_actor_role,
    v_booking.ticketing_deadline_at, v_reason,
    jsonb_build_object(
      'supplierTimeLimit', v_booking.supplier_ticketing_time_limit,
      'supplierDeadlineAt', v_booking.supplier_ticketing_deadline_at,
      'thresholdMinutes', 15,
      'expiredRequestWindowMinutes', 180,
      'walletMutation', false
    )
  );
  return jsonb_build_object(
    'ok', true, 'replay', false, 'requestId', v_request.id,
    'state', v_request.state, 'requestedAt', v_request.requested_at,
    'version', v_request.version
  );
end;
$$;

create or replace function public.enforce_local_time_limit_request_window_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_supplier_deadline timestamptz;
  v_now timestamptz := clock_timestamp();
begin
  select booking.supplier_ticketing_deadline_at
    into v_supplier_deadline
    from public.flight_bookings booking
   where booking.id = new.booking_id
   for key share;
  if not found then
    raise exception 'booking not found'
      using errcode = 'P0002';
  end if;

  if v_supplier_deadline >= v_now + interval '15 minutes' then
    raise exception 'supplier ticketing deadline has at least 15 minutes remaining'
      using
        errcode = '23514',
        constraint = 'booking_local_ttl_under_15_minutes_check';
  end if;
  if v_supplier_deadline <= v_now - interval '3 hours' then
    raise exception 'supplier ticketing deadline expired at least 3 hours ago'
      using
        errcode = '23514',
        constraint = 'booking_local_ttl_expired_request_window_check';
  end if;
  return new;
end;
$$;

drop trigger if exists booking_local_ttl_request_window_v1
  on public.booking_local_time_limit_requests;
create trigger booking_local_ttl_request_window_v1
  before insert
  on public.booking_local_time_limit_requests
  for each row execute function public.enforce_local_time_limit_request_window_v1();

revoke all on function public.enforce_local_time_limit_request_window_v1()
  from public, anon, authenticated, service_role;

comment on function public.request_booking_local_time_limit_v1(
  uuid, text, text, text
) is
  'Creates one owner-scoped request when Triplover TTL is missing, has less than 15 minutes remaining, or expired less than 3 hours ago; database time is authoritative and users cannot choose minutes.';

comment on function public.enforce_local_time_limit_request_window_v1() is
  'Prevents direct request inserts outside the NULL, under-15-minute, and less-than-3-hours-expired eligibility window using database time.';


-- SOURCE: 0085_supplier_accounts_and_operational_controls.sql
-- Supplier-account binding and Super Admin operational controls.
--
-- A supplier account is deliberately separate from `supplier = 'triplover'`:
-- the latter identifies the integration, while this column identifies the
-- credential/URL set that must remain stable for one search and booking.
-- Historical rows are intentionally left NULL rather than guessed from a
-- deployment-wide setting. They require a safe manual reconciliation path.

alter table public.flight_search_quotes
  add column if not exists supplier_account text;
alter table public.flight_search_quotes
  drop constraint if exists flight_search_quotes_supplier_account_check;
alter table public.flight_search_quotes
  add constraint flight_search_quotes_supplier_account_check
  check (supplier_account is null or supplier_account in ('firsttrip', 'takeoff'));

alter table public.booking_attempts
  add column if not exists supplier_account text;
alter table public.booking_attempts
  drop constraint if exists booking_attempts_supplier_account_check;
alter table public.booking_attempts
  add constraint booking_attempts_supplier_account_check
  check (supplier_account is null or supplier_account in ('firsttrip', 'takeoff'));

alter table public.flight_bookings
  add column if not exists supplier_account text;
alter table public.flight_bookings
  drop constraint if exists flight_bookings_supplier_account_check;
alter table public.flight_bookings
  add constraint flight_bookings_supplier_account_check
  check (supplier_account is null or supplier_account in ('firsttrip', 'takeoff'));

create index if not exists booking_attempts_supplier_account_idx
  on public.booking_attempts (supplier_account, created_at desc)
  where supplier_account is not null;
create index if not exists flight_bookings_supplier_account_idx
  on public.flight_bookings (supplier_account, created_at desc)
  where supplier_account is not null;

comment on column public.flight_search_quotes.supplier_account is
  'Credential account used to create this expiring search. Never inferred after creation.';
comment on column public.booking_attempts.supplier_account is
  'Credential account copied from the source search. NULL denotes a historical row.';
comment on column public.flight_bookings.supplier_account is
  'Credential account copied from its booking attempt. NULL denotes a historical row.';

-- The existing atomic attempt-to-booking finalizer has a deliberately narrow
-- insert list. This trigger copies the bound account inside that same database
-- transaction without changing any lifecycle or ticketing semantics.
create or replace function public.copy_booking_supplier_account_from_attempt()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.supplier_account is null and new.attempt_id is not null then
    select supplier_account into new.supplier_account
      from public.booking_attempts
     where id = new.attempt_id;
  end if;

  if new.supplier = 'triplover'
     and not new.legacy_operational
     and new.attempt_id is not null
     and new.supplier_account is null then
    raise exception 'booking attempt is missing supplier account'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists flight_bookings_copy_supplier_account
  on public.flight_bookings;
create trigger flight_bookings_copy_supplier_account
  before insert on public.flight_bookings
  for each row execute function public.copy_booking_supplier_account_from_attempt();

revoke all on function public.copy_booking_supplier_account_from_attempt()
  from public, anon, authenticated;

-- One optional row. Leaving this table empty preserves the legacy environment
-- switches during a rolling release; the first Super Admin save makes the
-- database the only operational authority.
create table if not exists public.supplier_operational_settings (
  id                text primary key check (id = 'triplover'),
  active_supplier   text not null
                    check (active_supplier in ('firsttrip', 'takeoff')),
  booking_enabled   boolean not null,
  ticketing_enabled boolean not null,
  version           integer not null default 1 check (version > 0),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (not ticketing_enabled or booking_enabled)
);

alter table public.supplier_operational_settings enable row level security;
revoke all on table public.supplier_operational_settings from anon, authenticated;

comment on table public.supplier_operational_settings is
  'Singleton Super Admin control for the active Triplover account and booking/ticketing gates. Empty means temporary legacy-environment fallback.';

-- PostgreSQL expands fb.* when a view is created. Later reporting views depend
-- on booking_lifecycle_v, so do not drop it. Instead preserve every existing
-- output column and its order, then append supplier_account. That keeps the
-- lifecycle_status position stable for dependent views while exposing the new
-- account to application reads.
do $$
declare
  v_existing_columns text;
begin
  select string_agg(format('fb.%I', attribute.attname), ', ' order by attribute.attnum)
    into v_existing_columns
    from pg_attribute attribute
   where attribute.attrelid = 'public.booking_lifecycle_v'::regclass
     and attribute.attnum > 0
     and not attribute.attisdropped
     and attribute.attname not in ('lifecycle_status', 'supplier_account');

  if v_existing_columns is null then
    raise exception 'booking_lifecycle_v has no expected source columns';
  end if;

  execute format(
    'create or replace view public.booking_lifecycle_v with (security_invoker = true) as
       select %s,
         public.resolve_booking_lifecycle(
           fb.status, fb.airlines_pnr, fb.ticketing_deadline_at, fb.operation_kind
         ) as lifecycle_status,
         fb.supplier_account
       from public.flight_bookings fb
       where not fb.legacy_operational',
    v_existing_columns
  );
end;
$$;


-- SOURCE: 0086_manual_booking_import.sql
-- Manual Booking Import is a source on the canonical booking lifecycle.  It
-- never represents a supplier API booking and deliberately writes the same
-- booking, wallet, lifecycle-event, notification-outbox, and reporting rows.

alter table public.flight_bookings
  drop constraint if exists flight_bookings_import_source_check;
alter table public.flight_bookings
  add constraint flight_bookings_import_source_check
  check (import_source is null or import_source in ('IMP_EXP', 'MANUAL'));

create unique index if not exists flight_bookings_manual_reference_key
  on public.flight_bookings (booking_ref_number)
  where import_source = 'MANUAL' and booking_ref_number is not null;
create index if not exists flight_bookings_manual_created_idx
  on public.flight_bookings (created_at desc)
  where import_source = 'MANUAL';

-- A source command can suppress the generic insert event only while it builds
-- a richer, actor-attributed lifecycle event in the same transaction.
create or replace function public.record_initial_booking_status_event()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not new.legacy_operational
     and coalesce(current_setting('app.skip_initial_booking_status_event', true), '') <> 'true' then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, supplier_operation, supplier_evidence,
      idempotency_key, created_at
    ) values (
      new.id, null,
      public.resolve_booking_lifecycle(
        new.status, new.airlines_pnr, new.ticketing_deadline_at, new.operation_kind
      ),
      null, new.status, new.operation_kind, new.operation_reason, 'Book',
      jsonb_build_object('bookingStatus', new.booking_status,
        'airlinesPnr', new.airlines_pnr),
      'booking-created', new.created_at
    ) on conflict do nothing;
  end if;
  return new;
end;
$$;

-- Request records make a browser retry return the original result rather than
-- creating a second booking or a second wallet debit.  They are audit records,
-- not a separate booking model.
create table if not exists public.manual_booking_actions (
  id             uuid primary key default gen_random_uuid(),
  request_key    text not null unique,
  booking_id     uuid references public.flight_bookings (id) on delete restrict,
  action         text not null check (action in ('import', 'status_change')),
  actor_user_id  text not null,
  actor_role     text not null,
  payload_hash   text not null check (payload_hash ~ '^[a-f0-9]{64}$'),
  result         jsonb not null check (jsonb_typeof(result) = 'object'),
  created_at     timestamptz not null default clock_timestamp()
);
alter table public.manual_booking_actions enable row level security;
revoke all on table public.manual_booking_actions from public, anon, authenticated;
grant select, insert on table public.manual_booking_actions to service_role;

-- Manual commercial truth follows the same protected User Payable rules as
-- IMP/EXP, while remaining independent from supplier-sync pricing.
alter table public.flight_bookings
  add constraint flight_bookings_manual_pricing_truth_check
  check (
    import_source is distinct from 'MANUAL'
    or (
      user_payable_amount is not null and user_payable_amount > 0
      and supplier_gross_amount is not null and supplier_gross_amount >= 0
      and public.impexp_pricing_minor_amount_v1(pricing_snapshot, 'sellingPrice') = user_payable_amount
      and public.impexp_pricing_minor_amount_v1(pricing_snapshot, 'supplierTotalPrice') = supplier_gross_amount
      and public.impexp_pricing_minor_amount_v1(pricing_snapshot, 'grossPrice') = supplier_gross_amount
      and (payment_amount is null or payment_amount = user_payable_amount)
      and captured_amount in (0, user_payable_amount)
      and refunded_amount between 0 and captured_amount
    )
  ) not valid;

alter table public.flight_bookings
  add constraint flight_bookings_manual_on_hold_unpaid_check
  check (
    import_source is distinct from 'MANUAL'
    or status <> 'on-hold'
    or (
      payment_state = 'unpaid' and charged_wallet_account_id is null
      and captured_amount = 0 and refunded_amount = 0
    )
  ) not valid;

create or replace function public.enforce_manual_booking_invariants_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' and old.import_source = 'MANUAL' then
    if new.import_source is distinct from old.import_source then
      raise exception 'manual booking source is immutable'
        using errcode = '23514', constraint = 'flight_bookings_manual_source_immutable';
    end if;
    if new.user_payable_amount is distinct from old.user_payable_amount
       or new.currency is distinct from old.currency then
      raise exception 'manual User Payable and currency are immutable'
        using errcode = '23514', constraint = 'flight_bookings_manual_payable_immutable';
    end if;
  end if;
  if new.import_source is distinct from 'MANUAL' then return new; end if;
  if new.user_payable_amount is null or new.user_payable_amount <= 0
     or new.supplier_gross_amount is null or new.supplier_gross_amount < 0
     or public.impexp_pricing_minor_amount_v1(new.pricing_snapshot, 'sellingPrice') is distinct from new.user_payable_amount
     or public.impexp_pricing_minor_amount_v1(new.pricing_snapshot, 'supplierTotalPrice') is distinct from new.supplier_gross_amount
     or public.impexp_pricing_minor_amount_v1(new.pricing_snapshot, 'grossPrice') is distinct from new.supplier_gross_amount
     or (new.payment_amount is not null and new.payment_amount is distinct from new.user_payable_amount)
     or new.captured_amount not in (0, new.user_payable_amount)
     or new.refunded_amount < 0 or new.refunded_amount > new.captured_amount then
    raise exception 'manual Supplier Gross/User Payable invariant failed'
      using errcode = '23514', constraint = 'flight_bookings_manual_pricing_truth_check';
  end if;
  return new;
end;
$$;

drop trigger if exists flight_bookings_enforce_manual_invariants on public.flight_bookings;
create trigger flight_bookings_enforce_manual_invariants
before insert or update of import_source, currency, pricing_snapshot,
  supplier_gross_amount, user_payable_amount, payment_state, payment_amount,
  captured_amount, refunded_amount
on public.flight_bookings
for each row execute function public.enforce_manual_booking_invariants_v1();

create or replace function public.enforce_manual_reservation_amount_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare v_booking public.flight_bookings;
begin
  if new.booking_id is null then return new; end if;
  select * into v_booking from public.flight_bookings where id = new.booking_id;
  if found and v_booking.import_source = 'MANUAL'
     and (new.amount is distinct from v_booking.user_payable_amount
       or upper(new.currency) is distinct from upper(v_booking.currency)) then
    raise exception 'manual reservation must equal protected User Payable'
      using errcode = '23514', constraint = 'wallet_reservations_manual_user_payable_check';
  end if;
  return new;
end;
$$;
drop trigger if exists wallet_reservations_enforce_manual_amount on public.wallet_reservations;
create trigger wallet_reservations_enforce_manual_amount
before insert or update of booking_id, amount, currency on public.wallet_reservations
for each row execute function public.enforce_manual_reservation_amount_v1();

create or replace function public.enforce_manual_capture_ledger_amount_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare v_booking public.flight_bookings;
begin
  if new.booking_id is null or new.transaction_type <> 'booking_confirm' then return new; end if;
  select * into v_booking from public.flight_bookings where id = new.booking_id;
  if found and v_booking.import_source = 'MANUAL'
     and (new.amount is distinct from v_booking.user_payable_amount
       or upper(new.currency) is distinct from upper(v_booking.currency)
       or new.metadata->>'userPayableAmount' is distinct from v_booking.user_payable_amount::text
       or new.metadata->>'supplierGrossAmount' is distinct from v_booking.supplier_gross_amount::text) then
    raise exception 'manual capture ledger must equal protected User Payable'
      using errcode = '23514', constraint = 'wallet_ledger_entries_manual_user_payable_check';
  end if;
  return new;
end;
$$;
drop trigger if exists wallet_ledger_enforce_manual_capture_amount on public.wallet_ledger_entries;
create trigger wallet_ledger_enforce_manual_capture_amount
before insert on public.wallet_ledger_entries
for each row execute function public.enforce_manual_capture_ledger_amount_v1();

-- Extend the owner Confirm & Pay command, without changing the existing
-- supplier-import semantics.  The command still creates no supplier write.
create or replace function public.wallet_confirm_impexp_booking(
  p_booking_id uuid, p_actor_user_id text, p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings; v_actor_role text; v_actor_agency text;
  v_existing_operation public.booking_operations; v_existing_case public.booking_reconciliation_cases;
  v_existing_reservation public.wallet_reservations; v_wallet public.wallets;
  v_account public.wallet_accounts; v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases; v_reservation public.wallet_reservations;
  v_available_before bigint; v_hold_before bigint; v_ledger_key text;
  v_operation_request_key text; v_payload_hash text; v_now timestamptz := clock_timestamp();
  v_due_at timestamptz; v_event_id bigint; v_occurrence_number integer;
begin
  if p_booking_id is null or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_idempotency_key), '') is null or char_length(p_idempotency_key) > 220 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CONFIRM_REQUEST');
  end if;
  select role, agency_code into v_actor_role, v_actor_agency from public.app_users where clerk_id = p_actor_user_id;
  if not found or v_actor_role not in ('customer', 'b2b', 'b2b_sub') then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_CONFIRM_FORBIDDEN');
  end if;
  select * into v_booking from public.flight_bookings
   where id = p_booking_id and import_source in ('IMP_EXP', 'MANUAL') for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND'); end if;
  if not ((v_actor_role = 'customer' and v_booking.booking_owner_type = 'user' and v_booking.booking_owner_key = p_actor_user_id)
    or (v_actor_role in ('b2b', 'b2b_sub') and nullif(btrim(v_actor_agency), '') is not null
      and v_booking.booking_owner_type = 'agency' and v_booking.booking_owner_key = v_actor_agency)) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_CONFIRM_FORBIDDEN');
  end if;
  v_ledger_key := lower(v_booking.import_source) || '-payment:' || v_booking.id::text;
  v_operation_request_key := lower(v_booking.import_source) || '-manual-ticketing:' || v_booking.id::text;
  v_payload_hash := encode(sha256(convert_to(jsonb_build_object('version', 1, 'bookingId', v_booking.id,
    'ownerType', v_booking.booking_owner_type, 'ownerKey', v_booking.booking_owner_key,
    'amount', v_booking.user_payable_amount, 'currency', upper(v_booking.currency))::text, 'UTF8')), 'hex');
  select * into v_existing_operation from public.booking_operations
   where booking_id = v_booking.id and state in ('claimed','supplier_call_started','awaiting_external_action','needs_reconciliation')
   order by claimed_at desc, id desc limit 1 for update;
  select * into v_existing_case from public.booking_reconciliation_cases
   where subject_booking_id = v_booking.id and state not in ('resolved','closed_no_change')
   order by opened_at desc limit 1 for update;
  select * into v_existing_reservation from public.wallet_reservations where booking_id = v_booking.id for update;
  if v_booking.payment_state = 'captured' then
    if v_booking.status = 'in-progress' and v_booking.captured_amount = v_booking.user_payable_amount
       and v_booking.refunded_amount = 0 and v_booking.active_operation_id = v_existing_operation.id
       and v_existing_operation.kind = 'imported_manual_ticketing'
       and v_existing_operation.request_key = v_operation_request_key
       and v_existing_operation.request_payload_hash = v_payload_hash
       and v_existing_operation.state = 'awaiting_external_action'
       and v_existing_reservation.state = 'captured'
       and v_existing_reservation.amount = v_booking.user_payable_amount
       and v_existing_reservation.wallet_account_id = v_booking.charged_wallet_account_id
       and exists (select 1 from public.wallet_ledger_entries ledger where ledger.idempotency_key = v_ledger_key and ledger.booking_id = v_booking.id and ledger.amount = v_booking.user_payable_amount) then
      return jsonb_build_object('ok', true, 'replay', true, 'status', 'in-progress',
        'operationId', v_existing_operation.id, 'operationState', v_existing_operation.state,
        'reconciliationCaseId', v_existing_case.id, 'reservationId', v_existing_reservation.id,
        'accountId', v_booking.charged_wallet_account_id, 'amount', v_booking.captured_amount, 'currency', v_booking.currency);
    end if;
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  end if;
  if v_existing_operation.id is not null or v_existing_case.id is not null or v_existing_reservation.id is not null then
    return jsonb_build_object('ok', false, 'code', 'RECONCILIATION_REQUIRED');
  end if;
  if v_booking.status <> 'on-hold' or v_booking.operation_kind is not null or v_booking.payment_state <> 'unpaid'
    or v_booking.charged_wallet_account_id is not null or v_booking.captured_amount <> 0 or v_booking.refunded_amount <> 0
    or public.resolve_booking_lifecycle(v_booking.status, v_booking.airlines_pnr, v_booking.ticketing_deadline_at, v_booking.operation_kind) <> 'on-hold' then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if v_booking.user_payable_amount is null or v_booking.user_payable_amount <= 0 then return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT'); end if;
  select * into v_wallet from public.wallets where owner_type = v_booking.booking_owner_type and owner_key = v_booking.booking_owner_key for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND'); end if;
  select * into v_account from public.wallet_accounts where wallet_id = v_wallet.id and currency = upper(v_booking.currency) for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND'); end if;
  if v_wallet.status <> 'active' then return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN'); end if;
  if v_account.available_balance < v_booking.user_payable_amount then return jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_FUNDS', 'available', v_account.available_balance, 'required', v_booking.user_payable_amount, 'currency', v_account.currency); end if;
  v_due_at := case when v_booking.ticketing_deadline_at is null then v_now + interval '2 hours'
    else greatest(v_now, least(v_now + interval '2 hours', v_booking.ticketing_deadline_at - interval '1 hour')) end;
  insert into public.booking_operations (booking_id, kind, state, reason_code, reason_detail, request_key, request_payload_hash, actor_user_id, actor_role, source, prior_stored_status, prior_lifecycle_status, supplier, supplier_operation, supplier_unique_trans_id, supplier_booking_code_ref, supplier_pnr, supplier_evidence, policy_version, claimed_at, external_action_due_at)
  values (v_booking.id, 'imported_manual_ticketing', 'awaiting_external_action', 'imported_manual_ticketing', 'Owner payment captured; external manual ticketing is required.', v_operation_request_key, v_payload_hash, p_actor_user_id, v_actor_role, 'customer', 'on-hold', 'on-hold', v_booking.supplier, 'ManualExternalTicketing', v_booking.supplier_refs->>'uniqueTransId', v_booking.booking_code_ref, v_booking.pnr,
    jsonb_build_object('paymentCaptured', true, 'supplierApiCalled', false, 'clientRequestId', p_idempotency_key, 'importSource', v_booking.import_source, 'userPayableAmount', v_booking.user_payable_amount, 'currency', v_booking.currency, 'externalActionDueAt', v_due_at), 1, v_now, v_due_at) returning * into v_operation;
  insert into public.booking_reconciliation_cases (subject_booking_id, operation_id, case_type, state, reason_code, reason_detail, opened_source, opened_by_user_id, opened_by_role, opened_at, assigned_team, assigned_at, severity, priority, due_at, escalation_level, evidence, financial_disposition, policy_version)
  values (v_booking.id, v_operation.id, 'imported_manual_ticketing', 'assigned', 'manual_ticketing_required', 'Payment received; verify and complete external manual ticketing.', 'operation', p_actor_user_id, v_actor_role, v_now, 'support', v_now, 'high', 30, v_due_at, 0,
    jsonb_build_array(jsonb_build_object('type','owner_payment_capture','operationId',v_operation.id,'amount',v_booking.user_payable_amount,'currency',v_booking.currency,'supplierApiCalled',false,'recordedAt',v_now)), 'none', 1) returning * into v_case;
  v_available_before := v_account.available_balance; v_hold_before := v_account.hold_balance;
  update public.wallet_accounts set available_balance = available_balance - v_booking.user_payable_amount where id = v_account.id;
  insert into public.wallet_reservations (wallet_account_id, booking_id, amount, currency, state, requested_by_user_id, issued_by_user_id, captured_at)
  values (v_account.id, v_booking.id, v_booking.user_payable_amount, v_account.currency, 'captured', p_actor_user_id, p_actor_user_id, v_now) returning * into v_reservation;
  insert into public.wallet_ledger_entries (wallet_account_id, transaction_type, amount, currency, available_before, available_after, hold_before, hold_after, booking_id, booking_reference, reservation_id, idempotency_key, created_by_user_id, created_by_role, remarks, metadata)
  values (v_account.id, 'booking_confirm', v_booking.user_payable_amount, v_account.currency, v_available_before, v_available_before - v_booking.user_payable_amount, v_hold_before, v_hold_before, v_booking.id, v_booking.public_ref, v_reservation.id, v_ledger_key, p_actor_user_id, v_actor_role, 'Owner confirmed external booking for manual ticketing',
    jsonb_build_object('importSource',v_booking.import_source,'operationId',v_operation.id,'reconciliationCaseId',v_case.id,'supplierGrossAmount',v_booking.supplier_gross_amount,'userPayableAmount',v_booking.user_payable_amount));
  update public.flight_bookings set charged_wallet_account_id = v_account.id, payment_state = 'captured', payment_amount = user_payable_amount, captured_amount = user_payable_amount, status = 'in-progress', active_operation_id = v_operation.id, operation_kind = 'ticketing', operation_reason = 'imported_manual_ticketing', operation_request_id = v_operation_request_key, operation_actor_user_id = p_actor_user_id, operation_started_at = v_now, operation_prior_status = 'on-hold' where id = v_booking.id;
  select count(*)::integer + 1 into v_occurrence_number from public.booking_status_events where booking_id = v_booking.id and to_lifecycle_status = 'in-progress';
  insert into public.booking_status_events (booking_id,from_lifecycle_status,to_lifecycle_status,stored_status_before,stored_status_after,operation_kind,operation_reason,actor_user_id,supplier_operation,supplier_evidence,idempotency_key,operation_id,reconciliation_case_id,occurrence_number,effective_at,observed_at,event_snapshot,event_version)
  values (v_booking.id,'on-hold','in-progress','on-hold','in-progress','ticketing','imported_manual_ticketing',p_actor_user_id,'ImportCustomerConfirm',jsonb_build_object('walletCaptured',true,'supplierApiCalled',false,'importSource',v_booking.import_source,'userPayableAmount',v_booking.user_payable_amount),v_ledger_key || ':in-progress',v_operation.id,v_case.id,v_occurrence_number,v_now,v_now,jsonb_build_object('version',1,'bookingReference',v_booking.public_ref,'lifecycleStatus','in-progress','paymentState','captured','operationKind','imported_manual_ticketing','operationSource','imported_manual_ticketing','operationId',v_operation.id,'reconciliationCaseId',v_case.id,'userPayableAmount',v_booking.user_payable_amount,'currency',v_booking.currency),1) returning id into v_event_id;
  return jsonb_build_object('ok',true,'replay',false,'status','in-progress','operationId',v_operation.id,'operationState',v_operation.state,'reconciliationCaseId',v_case.id,'reservationId',v_reservation.id,'accountId',v_account.id,'lifecycleEventId',v_event_id,'amount',v_booking.user_payable_amount,'currency',v_account.currency,'availableBalance',v_available_before-v_booking.user_payable_amount,'holdBalance',v_hold_before);
end;
$$;

create or replace function public.create_manual_booking_v1(
  p_actor_user_id text, p_assigned_user_id text, p_user_payable_amount bigint,
  p_supplier_gross_amount bigint, p_data jsonb, p_request_key text
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_actor_role text; v_target_role text; v_agency_code text; v_owner_type text; v_owner_key text;
  v_currency text; v_initial_status text; v_reference text; v_payload_hash text; v_existing_action public.manual_booking_actions;
  v_existing public.flight_bookings; v_attempt_id uuid := gen_random_uuid(); v_search_id uuid := gen_random_uuid();
  v_booking_id uuid := gen_random_uuid(); v_booking public.flight_bookings; v_wallet public.wallets; v_account public.wallet_accounts;
  v_reservation public.wallet_reservations; v_now timestamptz := clock_timestamp(); v_available_before bigint; v_hold_before bigint;
  v_ledger_key text; v_ticket_count integer; v_result jsonb; v_pnr text; v_ticket_numbers jsonb; v_issued_at timestamptz;
  v_event_id bigint; v_occurrence_number integer;
begin
  if p_data is null or jsonb_typeof(p_data) <> 'object' or nullif(btrim(coalesce(p_actor_user_id,'')),'') is null
    or nullif(btrim(coalesce(p_assigned_user_id,'')),'') is null or p_user_payable_amount is null or p_user_payable_amount <= 0
    or p_supplier_gross_amount is null or p_supplier_gross_amount < 0
    or p_request_key !~ '^manual-import:v1:[0-9a-f-]{36}$' then return jsonb_build_object('ok',false,'code','INVALID_MANUAL_IMPORT_DATA'); end if;
  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role is null or v_actor_role not in ('staff_support','admin','superadmin') then return jsonb_build_object('ok',false,'code','MANUAL_IMPORT_FORBIDDEN'); end if;
  select role, agency_code into v_target_role, v_agency_code from public.app_users where clerk_id = p_assigned_user_id;
  if not found or v_target_role not in ('b2b','b2b_sub','customer') then return jsonb_build_object('ok',false,'code','INVALID_IMPORT_ASSIGNEE'); end if;
  if v_target_role in ('b2b','b2b_sub') then
    if nullif(btrim(v_agency_code),'') is null then return jsonb_build_object('ok',false,'code','ASSIGNEE_AGENCY_REQUIRED'); end if;
    v_owner_type := 'agency'; v_owner_key := v_agency_code;
  else v_owner_type := 'user'; v_owner_key := p_assigned_user_id; end if;
  v_currency := upper(coalesce(nullif(btrim(p_data->>'currency'),''),'BDT')); v_initial_status := p_data->>'initialStatus';
  v_reference := nullif(btrim(p_data->>'supplierReference'),''); v_pnr := nullif(btrim(p_data->>'pnr'),''); v_ticket_numbers := coalesce(p_data->'ticketNumbers','[]'::jsonb);
  v_ticket_count := case when jsonb_typeof(p_data #> '{passengers,travellers}')='array' then jsonb_array_length(p_data #> '{passengers,travellers}') else 0 end;
  if p_data->>'provider' is distinct from 'MANUAL' or v_reference is null or v_pnr is null or v_currency !~ '^[A-Z]{3}$'
    or v_initial_status not in ('on-hold','confirmed') or coalesce(p_data->>'travelDate','') !~ '^\d{4}-\d{2}-\d{2}$'
    or jsonb_typeof(p_data->'passengerCounts') <> 'object' or jsonb_typeof(p_data->'itinerary') <> 'object'
    or jsonb_typeof(p_data->'fares') <> 'array' or jsonb_typeof(p_data->'passengers') <> 'object'
    or jsonb_typeof(p_data->'airlinesPnr') <> 'array' or v_ticket_count <= 0
    or jsonb_array_length(case when jsonb_typeof(p_data->'airlinesPnr')='array' then p_data->'airlinesPnr' else '[]'::jsonb end) = 0 then
    return jsonb_build_object('ok',false,'code','INVALID_MANUAL_IMPORT_DATA');
  end if;
  if v_initial_status = 'confirmed' then
    begin v_issued_at := nullif(p_data->>'issuedAt','')::timestamptz; exception when others then v_issued_at := null; end;
    if v_issued_at is null or jsonb_typeof(v_ticket_numbers) <> 'array' or jsonb_array_length(v_ticket_numbers) <> v_ticket_count
      or exists (select 1 from jsonb_array_elements(v_ticket_numbers) ticket(value) where jsonb_typeof(ticket.value) <> 'string' or nullif(btrim(ticket.value #>> '{}'),'') is null)
      or (select count(distinct upper(ticket.value #>> '{}')) from jsonb_array_elements(v_ticket_numbers) ticket(value)) <> v_ticket_count then
      return jsonb_build_object('ok',false,'code','COMPLETE_CONFIRMED_MANUAL_EVIDENCE_REQUIRED');
    end if;
  elsif jsonb_array_length(v_ticket_numbers) <> 0 or nullif(p_data->>'issuedAt','') is not null then
    return jsonb_build_object('ok',false,'code','ON_HOLD_MANUAL_IMPORT_CANNOT_INCLUDE_TICKETS');
  end if;
  v_payload_hash := encode(sha256(convert_to(jsonb_build_object('assignedUserId',p_assigned_user_id,'userPayableAmount',p_user_payable_amount,'supplierGrossAmount',p_supplier_gross_amount,'data',p_data)::text,'UTF8')),'hex');
  select * into v_existing_action from public.manual_booking_actions where request_key = p_request_key for update;
  if found then
    if v_existing_action.actor_user_id = p_actor_user_id and v_existing_action.payload_hash = v_payload_hash then return v_existing_action.result || jsonb_build_object('replay',true); end if;
    return jsonb_build_object('ok',false,'code','MANUAL_REQUEST_IDENTITY_MISMATCH');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('MANUAL:' || v_reference,0));
  select * into v_existing from public.flight_bookings where import_source='MANUAL' and booking_ref_number=v_reference limit 1 for update;
  if found then return jsonb_build_object('ok',false,'code','MANUAL_BOOKING_ALREADY_IMPORTED','booking',jsonb_build_object('id',v_existing.id,'public_ref',v_existing.public_ref,'payment_state',v_existing.payment_state)); end if;
  if v_initial_status='confirmed' then
    select * into v_wallet from public.wallets where owner_type=v_owner_type and owner_key=v_owner_key for update;
    if not found then return jsonb_build_object('ok',false,'code','WALLET_NOT_FOUND'); end if;
    select * into v_account from public.wallet_accounts where wallet_id=v_wallet.id and currency=v_currency for update;
    if not found then return jsonb_build_object('ok',false,'code','WALLET_ACCOUNT_NOT_FOUND'); end if;
    if v_wallet.status <> 'active' then return jsonb_build_object('ok',false,'code','WALLET_FROZEN'); end if;
    if v_account.available_balance < p_user_payable_amount then return jsonb_build_object('ok',false,'code','INSUFFICIENT_FUNDS','available',v_account.available_balance,'required',p_user_payable_amount,'currency',v_currency); end if;
    v_available_before:=v_account.available_balance; v_hold_before:=v_account.hold_balance;
    update public.wallet_accounts set available_balance=available_balance-p_user_payable_amount where id=v_account.id;
  end if;
  insert into public.booking_attempts (id,access_token_hash,user_id,audience,agency_code,supplier,state,search_id,itinerary_id,unique_trans_id,item_code_ref,price_code_ref,booking_code_ref,pnr,offer_snapshot,passenger_snapshot,expires_at,submitted_at,resolved_at,created_at)
  values (v_attempt_id,encode(sha256(convert_to(v_attempt_id::text,'UTF8')),'hex'),p_assigned_user_id,case when v_owner_type='agency' then 'agency' else 'b2c' end,case when v_owner_type='agency' then v_agency_code else null end,'manual','succeeded',v_search_id,'manual:'||v_reference,v_reference,v_reference,v_reference,'manual:'||v_reference,v_pnr,
    jsonb_build_object('itinerary',p_data->'itinerary','fares',p_data->'fares','currency',v_currency,'pricing',jsonb_build_object('audience',case when v_owner_type='agency' then 'agency' else 'b2c' end,'agencyCode',case when v_owner_type='agency' then v_agency_code else null end,'sellingPrice',p_user_payable_amount::numeric/100,'supplierTotalPrice',p_supplier_gross_amount::numeric/100,'grossPrice',p_supplier_gross_amount::numeric/100,'serviceMarginAmount',0,'basis','manual'),'passengerCounts',p_data->'passengerCounts','travelDate',p_data->>'travelDate','directTicketing',v_initial_status='confirmed','passportRequired',coalesce((p_data->>'passportRequired')::boolean,true),'repricedAt',v_now),p_data->'passengers',v_now,v_now,v_now,v_now);
  perform set_config('app.skip_initial_booking_status_event', 'true', true);
  insert into public.flight_bookings (id,public_ref,attempt_id,access_token_hash,supplier,user_id,audience,agency_code,search_id,itinerary_id,status,currency,pricing_snapshot,passenger_counts,travel_date,direct_ticketing,itinerary,fares,passport_required,supplier_refs,repriced_at,accepted_at,expires_at,passengers,pnr,airlines_pnr,booking_ref_number,booking_status,ticketing_deadline_at,deadline_source,booking_code_ref,ticket_numbers,warnings,supplier_message,issued_at,submission_started_at,legacy_operational,booked_by_user_id,issued_by_user_id,booking_owner_type,booking_owner_key,charged_wallet_account_id,payment_state,payment_amount,captured_amount,refunded_amount,supplier_gross_amount,user_payable_amount,import_source,imported_by_user_id,import_metadata,created_at)
  values (v_booking_id,public.allocate_booking_ref(),v_attempt_id,encode(sha256(convert_to(v_booking_id::text,'UTF8')),'hex'),'manual',p_assigned_user_id,case when v_owner_type='agency' then 'agency' else 'b2c' end,case when v_owner_type='agency' then v_agency_code else null end,v_search_id,'manual:'||v_reference,case when v_initial_status='confirmed' then 'confirmed' else 'on-hold' end,v_currency,
    jsonb_build_object('audience',case when v_owner_type='agency' then 'agency' else 'b2c' end,'agencyCode',case when v_owner_type='agency' then v_agency_code else null end,'sellingPrice',p_user_payable_amount::numeric/100,'supplierTotalPrice',p_supplier_gross_amount::numeric/100,'grossPrice',p_supplier_gross_amount::numeric/100,'serviceMarginAmount',0,'basis','manual'),p_data->'passengerCounts',(p_data->>'travelDate')::date,v_initial_status='confirmed',p_data->'itinerary',p_data->'fares',coalesce((p_data->>'passportRequired')::boolean,true),jsonb_build_object('externalImport',true,'manualImport',true,'uniqueTransId',v_reference,'itemCodeRef',v_reference,'priceCodeRef',v_reference),v_now,v_now,v_now,p_data->'passengers',v_pnr,p_data->'airlinesPnr',v_reference,case when v_initial_status='confirmed' then 'Manual Confirmed' else 'Manual On Hold' end,nullif(p_data->>'ticketingDeadlineAt','')::timestamptz,case when nullif(p_data->>'ticketingDeadlineAt','') is not null then 'assumed' else null end,'manual:'||v_reference,case when v_initial_status='confirmed' then v_ticket_numbers else '[]'::jsonb end,'[]'::jsonb,nullif(p_data->>'supplierMessage',''),case when v_initial_status='confirmed' then v_issued_at else null end,v_now,false,p_actor_user_id,case when v_initial_status='confirmed' then p_actor_user_id else null end,v_owner_type,v_owner_key,case when v_initial_status='confirmed' then v_account.id else null end,case when v_initial_status='confirmed' then 'captured' else 'unpaid' end,case when v_initial_status='confirmed' then p_user_payable_amount else null end,case when v_initial_status='confirmed' then p_user_payable_amount else 0 end,0,p_supplier_gross_amount,p_user_payable_amount,'MANUAL',p_actor_user_id,jsonb_build_object('source','manual','externalReference',v_reference,'importRequestKey',p_request_key,'initialStatus',v_initial_status,'walletCharged',v_initial_status='confirmed'),v_now) returning * into v_booking;
  if v_initial_status='confirmed' then
    insert into public.wallet_reservations (wallet_account_id,booking_id,amount,currency,state,requested_by_user_id,issued_by_user_id,captured_at) values (v_account.id,v_booking.id,p_user_payable_amount,v_currency,'captured',p_actor_user_id,p_actor_user_id,v_now) returning * into v_reservation;
    v_ledger_key := 'manual-payment:'||v_booking.id::text;
    insert into public.wallet_ledger_entries (wallet_account_id,transaction_type,amount,currency,available_before,available_after,hold_before,hold_after,booking_id,booking_reference,reservation_id,idempotency_key,created_by_user_id,created_by_role,remarks,metadata)
    values (v_account.id,'booking_confirm',p_user_payable_amount,v_currency,v_available_before,v_available_before-p_user_payable_amount,v_hold_before,v_hold_before,v_booking.id,v_booking.public_ref,v_reservation.id,v_ledger_key,p_actor_user_id,v_actor_role,'Manual confirmed booking import and charge',jsonb_build_object('importSource','MANUAL','supplierGrossAmount',p_supplier_gross_amount,'userPayableAmount',p_user_payable_amount,'directConfirmedImport',true));
  end if;
  select count(*)::integer + 1 into v_occurrence_number from public.booking_status_events
   where booking_id=v_booking.id and to_lifecycle_status=v_initial_status;
  insert into public.booking_status_events (booking_id,from_lifecycle_status,to_lifecycle_status,stored_status_before,stored_status_after,actor_user_id,supplier_operation,supplier_evidence,idempotency_key,occurrence_number,effective_at,observed_at,event_snapshot,event_version)
  values (v_booking.id,null,v_initial_status,null,v_booking.status,p_actor_user_id,'ManualBookingImport',
    jsonb_build_object('requestKey',p_request_key,'walletCharged',v_initial_status='confirmed','supplierApiCalled',false,'ticketCount',case when v_initial_status='confirmed' then jsonb_array_length(v_booking.ticket_numbers) else 0 end),
    p_request_key || ':' || v_initial_status,v_occurrence_number,v_now,v_now,
    jsonb_build_object('version',1,'bookingReference',v_booking.public_ref,'lifecycleStatus',v_initial_status,'paymentState',v_booking.payment_state,'operationSource','manual','userPayableAmount',v_booking.user_payable_amount,'currency',v_booking.currency),1) returning id into v_event_id;
  v_result := jsonb_build_object('ok',true,'booking',jsonb_build_object('id',v_booking.id,'public_ref',v_booking.public_ref,'payment_state',v_booking.payment_state),'status',v_initial_status,'walletCharged',v_initial_status='confirmed','lifecycleEventId',v_event_id,'amount',case when v_initial_status='confirmed' then p_user_payable_amount else 0 end,'accountId',case when v_initial_status='confirmed' then v_account.id else null end,'currency',v_currency);
  insert into public.manual_booking_actions (request_key,booking_id,action,actor_user_id,actor_role,payload_hash,result) values (p_request_key,v_booking.id,'import',p_actor_user_id,v_actor_role,v_payload_hash,v_result);
  insert into public.security_audit_events (actor_user_id,actor_role,action,target_type,target_id,outcome,metadata) values (p_actor_user_id,v_actor_role,'booking.manual.import','booking',v_booking.id::text,'succeeded',jsonb_build_object('requestKey',p_request_key,'initialStatus',v_initial_status,'walletCharged',v_initial_status='confirmed','amount',case when v_initial_status='confirmed' then p_user_payable_amount else 0 end,'currency',v_currency));
  return v_result;
end;
$$;

create or replace function public.update_manual_booking_status_v1(
  p_booking_id uuid, p_actor_user_id text, p_target_status text,
  p_data jsonb, p_request_key text
)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_actor_role text; v_booking public.flight_bookings; v_existing_action public.manual_booking_actions;
  v_payload_hash text; v_now timestamptz := clock_timestamp(); v_before text; v_pnr text; v_airlines_pnr jsonb;
  v_deadline timestamptz; v_ticket_numbers jsonb; v_issued_at timestamptz; v_ticket_count integer;
  v_wallet public.wallets; v_account public.wallet_accounts; v_reservation public.wallet_reservations;
  v_operation public.booking_operations; v_case public.booking_reconciliation_cases; v_available_before bigint; v_hold_before bigint;
  v_ledger_key text; v_event_id bigint; v_occurrence_number integer; v_result jsonb;
begin
  if p_booking_id is null or p_data is null or jsonb_typeof(p_data) <> 'object' or nullif(btrim(coalesce(p_actor_user_id,'')),'') is null
     or p_target_status not in ('on-hold','pending','confirmed','expired','unconfirmed','cancelled')
     or p_request_key !~ '^manual-status:v1:[0-9a-f-]{36}$' then return jsonb_build_object('ok',false,'code','INVALID_MANUAL_STATUS_REQUEST'); end if;
  select role into v_actor_role from public.app_users where clerk_id=p_actor_user_id;
  if v_actor_role is null or v_actor_role not in ('staff_support','admin','superadmin') then return jsonb_build_object('ok',false,'code','MANUAL_STATUS_FORBIDDEN'); end if;
  select * into v_booking from public.flight_bookings where id=p_booking_id and import_source='MANUAL' for update;
  if not found then return jsonb_build_object('ok',false,'code','MANUAL_BOOKING_NOT_FOUND'); end if;
  v_payload_hash:=encode(sha256(convert_to(jsonb_build_object('bookingId',p_booking_id,'targetStatus',p_target_status,'data',p_data)::text,'UTF8')),'hex');
  select * into v_existing_action from public.manual_booking_actions where request_key=p_request_key for update;
  if found then
    if v_existing_action.booking_id=v_booking.id and v_existing_action.actor_user_id=p_actor_user_id and v_existing_action.payload_hash=v_payload_hash then return v_existing_action.result || jsonb_build_object('replay',true); end if;
    return jsonb_build_object('ok',false,'code','MANUAL_REQUEST_IDENTITY_MISMATCH');
  end if;
  v_before:=public.resolve_booking_lifecycle(v_booking.status,v_booking.airlines_pnr,v_booking.ticketing_deadline_at,v_booking.operation_kind);
  if v_before in ('confirmed','cancelled') then return jsonb_build_object('ok',false,'code','MANUAL_TERMINAL_BOOKING'); end if;
  v_pnr:=coalesce(nullif(btrim(p_data->>'pnr'),''),v_booking.pnr); v_airlines_pnr:=coalesce(p_data->'airlinesPnr',v_booking.airlines_pnr,'[]'::jsonb);
  begin v_deadline:=coalesce(nullif(p_data->>'ticketingDeadlineAt','')::timestamptz,v_booking.ticketing_deadline_at); exception when others then return jsonb_build_object('ok',false,'code','INVALID_MANUAL_STATUS_DATA'); end;
  if p_target_status='confirmed' then
    begin v_issued_at:=nullif(p_data->>'issuedAt','')::timestamptz; exception when others then v_issued_at:=null; end;
    v_ticket_numbers:=coalesce(p_data->'ticketNumbers','[]'::jsonb); v_ticket_count:=case when jsonb_typeof(v_booking.passengers->'travellers')='array' then jsonb_array_length(v_booking.passengers->'travellers') else 0 end;
    if v_issued_at is null or v_ticket_count<=0 or jsonb_typeof(v_ticket_numbers)<>'array' or jsonb_array_length(v_ticket_numbers)<>v_ticket_count
       or exists (select 1 from jsonb_array_elements(v_ticket_numbers) ticket(value) where jsonb_typeof(ticket.value)<>'string' or nullif(btrim(ticket.value #>> '{}'),'') is null)
       or (select count(distinct upper(ticket.value #>> '{}')) from jsonb_array_elements(v_ticket_numbers) ticket(value))<>v_ticket_count then return jsonb_build_object('ok',false,'code','COMPLETE_CONFIRMED_MANUAL_EVIDENCE_REQUIRED'); end if;
    if v_before='in-progress' then
      select * into v_operation from public.booking_operations where id=v_booking.active_operation_id for update;
      select * into v_case from public.booking_reconciliation_cases where operation_id=v_operation.id and subject_booking_id=v_booking.id and state not in ('resolved','closed_no_change') order by opened_at desc limit 1 for update;
      select * into v_reservation from public.wallet_reservations where booking_id=v_booking.id for update;
      if v_booking.payment_state<>'captured' or v_booking.captured_amount<>v_booking.user_payable_amount or v_operation.kind<>'imported_manual_ticketing' or v_operation.state<>'awaiting_external_action' or v_reservation.state<>'captured' then return jsonb_build_object('ok',false,'code','MANUAL_TICKETING_RECONCILIATION_REQUIRED'); end if;
      update public.booking_operations set state='succeeded',completed_at=v_now,supplier_evidence=coalesce(supplier_evidence,'{}'::jsonb)||jsonb_build_object('manualTicketDetailsRecordedAt',v_now,'supplierApiCalled',false) where id=v_operation.id;
      update public.booking_reconciliation_cases set state='resolved',resolution_outcome='ticketed',resolution=jsonb_build_object('version',1,'executionRequestKey',p_request_key,'resolutionKind','manual_ticketed','walletMutation',false),resolution_reason='Manual external ticket details recorded',resolved_by_user_id=p_actor_user_id,resolved_at=v_now,closed_at=v_now,version=version+1 where id=v_case.id;
      update public.flight_bookings set status='confirmed',direct_ticketing=true,issued_at=v_issued_at,issued_by_user_id=p_actor_user_id,ticket_numbers=v_ticket_numbers,active_operation_id=null,operation_kind=null,operation_reason=null,operation_request_id=null,operation_actor_user_id=null,operation_started_at=null,operation_prior_status=null where id=v_booking.id returning * into v_booking;
    elsif v_before='on-hold' then
      if v_booking.payment_state<>'unpaid' or v_booking.captured_amount<>0 or v_booking.charged_wallet_account_id is not null then return jsonb_build_object('ok',false,'code','MANUAL_PAYMENT_RECONCILIATION_REQUIRED'); end if;
      select * into v_wallet from public.wallets where owner_type=v_booking.booking_owner_type and owner_key=v_booking.booking_owner_key for update;
      if not found then return jsonb_build_object('ok',false,'code','WALLET_NOT_FOUND'); end if;
      select * into v_account from public.wallet_accounts where wallet_id=v_wallet.id and currency=upper(v_booking.currency) for update;
      if not found then return jsonb_build_object('ok',false,'code','WALLET_ACCOUNT_NOT_FOUND'); end if;
      if v_wallet.status<>'active' then return jsonb_build_object('ok',false,'code','WALLET_FROZEN'); end if;
      if v_account.available_balance<v_booking.user_payable_amount then return jsonb_build_object('ok',false,'code','INSUFFICIENT_FUNDS','available',v_account.available_balance,'required',v_booking.user_payable_amount,'currency',v_account.currency); end if;
      v_available_before:=v_account.available_balance; v_hold_before:=v_account.hold_balance;
      update public.wallet_accounts set available_balance=available_balance-v_booking.user_payable_amount where id=v_account.id;
      insert into public.wallet_reservations (wallet_account_id,booking_id,amount,currency,state,requested_by_user_id,issued_by_user_id,captured_at) values (v_account.id,v_booking.id,v_booking.user_payable_amount,v_account.currency,'captured',p_actor_user_id,p_actor_user_id,v_now) returning * into v_reservation;
      v_ledger_key:='manual-payment:'||v_booking.id::text;
      insert into public.wallet_ledger_entries (wallet_account_id,transaction_type,amount,currency,available_before,available_after,hold_before,hold_after,booking_id,booking_reference,reservation_id,idempotency_key,created_by_user_id,created_by_role,remarks,metadata) values (v_account.id,'booking_confirm',v_booking.user_payable_amount,v_account.currency,v_available_before,v_available_before-v_booking.user_payable_amount,v_hold_before,v_hold_before,v_booking.id,v_booking.public_ref,v_reservation.id,v_ledger_key,p_actor_user_id,v_actor_role,'Manual On Hold to Confirmed status change and charge',jsonb_build_object('importSource','MANUAL','supplierGrossAmount',v_booking.supplier_gross_amount,'userPayableAmount',v_booking.user_payable_amount,'manualStatusTransition','on-hold->confirmed'));
      update public.flight_bookings set status='confirmed',direct_ticketing=true,issued_at=v_issued_at,issued_by_user_id=p_actor_user_id,ticket_numbers=v_ticket_numbers,payment_state='captured',payment_amount=user_payable_amount,captured_amount=user_payable_amount,charged_wallet_account_id=v_account.id where id=v_booking.id returning * into v_booking;
    else return jsonb_build_object('ok',false,'code','MANUAL_CONFIRM_TRANSITION_NOT_ALLOWED'); end if;
  elsif v_before='in-progress' then return jsonb_build_object('ok',false,'code','MANUAL_IN_PROGRESS_REQUIRES_TICKET_DETAILS');
  elsif v_booking.payment_state<>'unpaid' or v_booking.captured_amount<>0 or v_booking.charged_wallet_account_id is not null then return jsonb_build_object('ok',false,'code','MANUAL_PAYMENT_RECONCILIATION_REQUIRED');
  elsif p_target_status='cancelled' then
    if nullif(btrim(p_data->>'cancellationReason'),'') is null then return jsonb_build_object('ok',false,'code','MANUAL_CANCELLATION_REASON_REQUIRED'); end if;
    update public.flight_bookings set status='cancelled',cancelled_at=v_now,cancelled_by=p_actor_user_id,cancel_reason=btrim(p_data->>'cancellationReason') where id=v_booking.id returning * into v_booking;
  elsif p_target_status='pending' then
    update public.flight_bookings set status='pending' where id=v_booking.id returning * into v_booking;
  elsif p_target_status='unconfirmed' then
    update public.flight_bookings set status='on-hold',airlines_pnr='[]'::jsonb,ticketing_deadline_at=null,deadline_source=null where id=v_booking.id returning * into v_booking;
  elsif p_target_status='expired' then
    if v_pnr is null or not public.jsonb_is_nonempty_array(v_airlines_pnr) then return jsonb_build_object('ok',false,'code','MANUAL_PNR_REQUIRED'); end if;
    update public.flight_bookings set status='on-hold',pnr=v_pnr,airlines_pnr=v_airlines_pnr,ticketing_deadline_at=least(coalesce(v_deadline,v_now),v_now),deadline_source='assumed' where id=v_booking.id returning * into v_booking;
  else
    if v_pnr is null or not public.jsonb_is_nonempty_array(v_airlines_pnr) then return jsonb_build_object('ok',false,'code','MANUAL_PNR_REQUIRED'); end if;
    if v_deadline is not null and v_deadline<=v_now then return jsonb_build_object('ok',false,'code','MANUAL_ON_HOLD_DEADLINE_MUST_BE_FUTURE'); end if;
    update public.flight_bookings set status='on-hold',pnr=v_pnr,airlines_pnr=v_airlines_pnr,ticketing_deadline_at=v_deadline,deadline_source=case when v_deadline is null then null else 'assumed' end where id=v_booking.id returning * into v_booking;
  end if;
  if public.resolve_booking_lifecycle(v_booking.status,v_booking.airlines_pnr,v_booking.ticketing_deadline_at,v_booking.operation_kind)<>p_target_status then raise exception 'manual status backing facts did not resolve to target' using errcode='23514'; end if;
  select count(*)::integer+1 into v_occurrence_number from public.booking_status_events where booking_id=v_booking.id and to_lifecycle_status=p_target_status;
  insert into public.booking_status_events (booking_id,from_lifecycle_status,to_lifecycle_status,stored_status_before,stored_status_after,operation_kind,operation_reason,actor_user_id,supplier_operation,supplier_evidence,idempotency_key,operation_id,reconciliation_case_id,occurrence_number,effective_at,observed_at,event_snapshot,event_version)
  values (v_booking.id,v_before,p_target_status,case when v_before in ('expired','unconfirmed') then 'on-hold' else v_before end,v_booking.status,case when p_target_status='confirmed' and v_before='in-progress' then 'ticketing' else null end,case when p_target_status='confirmed' and v_before='in-progress' then 'imported_manual_ticketing' when p_target_status='confirmed' then 'manual_direct_confirm' else 'manual_status_change' end,p_actor_user_id,'ManualStatusChange',jsonb_build_object('requestKey',p_request_key,'walletCharged',p_target_status='confirmed' and v_before='on-hold','walletMutation',p_target_status='confirmed' and v_before='on-hold','supplierApiCalled',false,'ticketCount',case when p_target_status='confirmed' then jsonb_array_length(v_booking.ticket_numbers) else 0 end),p_request_key || ':' || p_target_status,case when v_before='in-progress' then v_operation.id else null end,case when v_before='in-progress' then v_case.id else null end,v_occurrence_number,v_now,v_now,jsonb_build_object('version',1,'bookingReference',v_booking.public_ref,'lifecycleStatus',p_target_status,'paymentState',v_booking.payment_state,'operationSource','manual','userPayableAmount',v_booking.user_payable_amount,'currency',v_booking.currency),1) returning id into v_event_id;
  v_result:=jsonb_build_object('ok',true,'booking',jsonb_build_object('id',v_booking.id,'public_ref',v_booking.public_ref,'payment_state',v_booking.payment_state),'status',p_target_status,'walletCharged',p_target_status='confirmed' and v_before='on-hold','walletMutation',p_target_status='confirmed' and v_before='on-hold','lifecycleEventId',v_event_id,'amount',case when p_target_status='confirmed' and v_before='on-hold' then v_booking.user_payable_amount else 0 end,'currency',v_booking.currency);
  insert into public.manual_booking_actions (request_key,booking_id,action,actor_user_id,actor_role,payload_hash,result) values (p_request_key,v_booking.id,'status_change',p_actor_user_id,v_actor_role,v_payload_hash,v_result);
  insert into public.security_audit_events (actor_user_id,actor_role,action,target_type,target_id,outcome,metadata) values (p_actor_user_id,v_actor_role,'booking.manual.status_change','booking',v_booking.id::text,'succeeded',jsonb_build_object('requestKey',p_request_key,'fromStatus',v_before,'targetStatus',p_target_status,'walletCharged',p_target_status='confirmed' and v_before='on-hold'));
  return v_result;
end;
$$;

revoke all on function public.create_manual_booking_v1(text,text,bigint,bigint,jsonb,text) from public,anon,authenticated;
grant execute on function public.create_manual_booking_v1(text,text,bigint,bigint,jsonb,text) to service_role;
revoke all on function public.update_manual_booking_status_v1(uuid,text,text,jsonb,text) from public,anon,authenticated;
grant execute on function public.update_manual_booking_status_v1(uuid,text,text,jsonb,text) to service_role;
revoke all on function public.wallet_confirm_impexp_booking(uuid,text,text) from public,anon,authenticated;
grant execute on function public.wallet_confirm_impexp_booking(uuid,text,text) to service_role;

comment on column public.flight_bookings.import_source is
  'IMP_EXP for supplier imports and MANUAL for staff-entered external bookings. MANUAL rows must never invoke supplier APIs.';


-- SOURCE: 0087_manual_booking_pricing_scale_fix.sql
-- Manual imports persist amounts in minor units, but PostgreSQL numeric division
-- can retain more than two trailing decimal places in the JSON pricing snapshot.
-- The shared IMP/EXP helper deliberately rejects that representation. Manual
-- bookings need the same cent-precision rule without rejecting harmless scale.

create or replace function public.manual_pricing_minor_amount_v1(
  p_pricing jsonb,
  p_key text
)
returns bigint
language plpgsql
immutable
set search_path = public
as $$
declare
  v_text text;
  v_minor numeric;
begin
  if p_pricing is null
     or jsonb_typeof(p_pricing) <> 'object'
     or nullif(btrim(coalesce(p_key, '')), '') is null
     or jsonb_typeof(p_pricing -> p_key) <> 'number' then
    return null;
  end if;

  v_text := p_pricing ->> p_key;
  begin
    v_minor := v_text::numeric * 100;
  exception when others then
    return null;
  end;

  if v_minor < 0
     or v_minor <> trunc(v_minor)
     or v_minor > 9223372036854775807::numeric then
    return null;
  end if;

  return v_minor::bigint;
end;
$$;

alter table public.flight_bookings
  drop constraint if exists flight_bookings_manual_pricing_truth_check;

alter table public.flight_bookings
  add constraint flight_bookings_manual_pricing_truth_check
  check (
    import_source is distinct from 'MANUAL'
    or (
      user_payable_amount is not null and user_payable_amount > 0
      and supplier_gross_amount is not null and supplier_gross_amount >= 0
      and public.manual_pricing_minor_amount_v1(pricing_snapshot, 'sellingPrice') = user_payable_amount
      and public.manual_pricing_minor_amount_v1(pricing_snapshot, 'supplierTotalPrice') = supplier_gross_amount
      and public.manual_pricing_minor_amount_v1(pricing_snapshot, 'grossPrice') = supplier_gross_amount
      and (payment_amount is null or payment_amount = user_payable_amount)
      and captured_amount in (0, user_payable_amount)
      and refunded_amount between 0 and captured_amount
    )
  ) not valid;

create or replace function public.enforce_manual_booking_invariants_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' and old.import_source = 'MANUAL' then
    if new.import_source is distinct from old.import_source then
      raise exception 'manual booking source is immutable'
        using errcode = '23514', constraint = 'flight_bookings_manual_source_immutable';
    end if;
    if new.user_payable_amount is distinct from old.user_payable_amount
       or new.currency is distinct from old.currency then
      raise exception 'manual User Payable and currency are immutable'
        using errcode = '23514', constraint = 'flight_bookings_manual_payable_immutable';
    end if;
  end if;

  if new.import_source is distinct from 'MANUAL' then
    return new;
  end if;

  if new.user_payable_amount is null or new.user_payable_amount <= 0
     or new.supplier_gross_amount is null or new.supplier_gross_amount < 0
     or public.manual_pricing_minor_amount_v1(new.pricing_snapshot, 'sellingPrice') is distinct from new.user_payable_amount
     or public.manual_pricing_minor_amount_v1(new.pricing_snapshot, 'supplierTotalPrice') is distinct from new.supplier_gross_amount
     or public.manual_pricing_minor_amount_v1(new.pricing_snapshot, 'grossPrice') is distinct from new.supplier_gross_amount
     or (new.payment_amount is not null and new.payment_amount is distinct from new.user_payable_amount)
     or new.captured_amount not in (0, new.user_payable_amount)
     or new.refunded_amount < 0 or new.refunded_amount > new.captured_amount then
    raise exception 'manual Supplier Gross/User Payable invariant failed'
      using errcode = '23514', constraint = 'flight_bookings_manual_pricing_truth_check';
  end if;

  return new;
end;
$$;

revoke all on function public.manual_pricing_minor_amount_v1(jsonb, text)
  from public, anon, authenticated;
grant execute on function public.manual_pricing_minor_amount_v1(jsonb, text)
  to service_role;

comment on function public.manual_pricing_minor_amount_v1(jsonb, text) is
  'Manual booking pricing accepts numerically exact minor-unit values regardless of harmless PostgreSQL decimal scale.';


-- SOURCE: 0088_wallet_owner_bank_accounts.sql
-- Multiple sender bank accounts for the owner of a wallet. B2B members share
-- the agency-owned rows because their wallet owner is the agency code.

create table if not exists public.wallet_owner_bank_accounts (
  id             uuid primary key default gen_random_uuid(),
  owner_type     text not null check (owner_type in ('user', 'agency')),
  owner_key      text not null check (char_length(trim(owner_key)) between 1 and 255),
  bank_name      text not null check (char_length(trim(bank_name)) between 2 and 150),
  account_name   text not null check (char_length(trim(account_name)) between 2 and 150),
  account_number text not null check (char_length(trim(account_number)) between 3 and 100),
  branch_code    text,
  routing_number text,
  swift_code     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (owner_type, owner_key, account_number)
);

create index if not exists wallet_owner_bank_accounts_owner_idx
  on public.wallet_owner_bank_accounts (owner_type, owner_key, bank_name, account_name);

drop trigger if exists wallet_owner_bank_accounts_touch_updated_at
  on public.wallet_owner_bank_accounts;
create trigger wallet_owner_bank_accounts_touch_updated_at
  before update on public.wallet_owner_bank_accounts
  for each row execute function public.touch_updated_at();

alter table public.wallet_owner_bank_accounts enable row level security;
revoke all on table public.wallet_owner_bank_accounts from public, anon, authenticated;
grant select, insert, update, delete on table public.wallet_owner_bank_accounts to service_role;

-- Preserve existing profile-bank users as their first saved account. A B2B
-- profile moves under its shared agency wallet; all other profiles stay with
-- their personal wallet owner. This keeps existing transfer users working
-- while new accounts use the dedicated multi-account store.
insert into public.wallet_owner_bank_accounts (
  owner_type,
  owner_key,
  bank_name,
  account_name,
  account_number,
  branch_code,
  routing_number,
  swift_code
)
select
  case
    when u.role in ('b2b', 'b2b_sub') and u.agency_code is not null then 'agency'
    else 'user'
  end,
  case
    when u.role in ('b2b', 'b2b_sub') and u.agency_code is not null then u.agency_code
    else u.clerk_id
  end,
  p.bank_name,
  p.account_name,
  p.account_number,
  nullif(trim(p.branch_code), ''),
  nullif(trim(p.routing_number), ''),
  nullif(trim(p.swift_code), '')
from public.user_profiles p
join public.app_users u on u.clerk_id = p.clerk_id
where nullif(trim(p.bank_name), '') is not null
  and nullif(trim(p.account_name), '') is not null
  and nullif(trim(p.account_number), '') is not null
on conflict (owner_type, owner_key, account_number) do nothing;

-- The account ID is deliberately not a foreign key. A saved account can be
-- deleted after use; the immutable `user_bank_account` JSON snapshot is the
-- historical source of truth while this ID retains the original audit link.
alter table public.wallet_deposit_requests
  add column if not exists source_bank_account_id uuid;

alter table public.wallet_deposit_requests
  drop constraint if exists wallet_deposit_method_fields_check;
alter table public.wallet_deposit_requests
  add constraint wallet_deposit_method_fields_check check (
    (method = 'cash'
      and branch_id is not null
      and received_by_user_id is not null)
    or
    (method = 'bank'
      and company_bank_account_id is not null
      and deposit_date is not null
      and nullif(trim(reference_number), '') is not null
      and attachment is not null)
    or
    (method = 'bank_transfer'
      and company_bank_account_id is not null
      and source_bank_account_id is not null
      and user_bank_account is not null
      and deposit_date is not null
      and nullif(trim(reference_number), '') is not null
      and attachment is not null)
    or
    (method = 'mobile'
      and mfs_provider is not null
      and mfs_account_id is not null
      and mfs_payment_type is not null
      and deposit_date is not null
      and nullif(trim(reference_number), '') is not null
      and gateway_fee_bps is not null
      and gross_amount is not null
      and attachment is not null)
    or
    (method = 'cheque'
      and cheque_issued_date is not null
      and cheque_issued_bank is not null
      and payment_date is not null
      and company_bank_account_id is not null
      and nullif(trim(reference_number), '') is not null
      and attachment is not null)
  ) not valid;

comment on table public.wallet_owner_bank_accounts is
  'Saved sender bank accounts scoped to a wallet owner; B2B accounts are agency-scoped.';
comment on column public.wallet_deposit_requests.source_bank_account_id is
  'Original selected saved sender account ID. It may outlive the saved account; user_bank_account is the immutable snapshot.';


-- SOURCE: 0089_wallet_adjustment_public_references.sql
-- Human-facing manual adjustment references: STAYYMMDD######.
-- The reference is allocated once, cannot be changed, and links the approved
-- manual credit/debit ledger entry back to its maker-checker request.

create table if not exists public.adjustment_ref_counters (
  ref_date   date primary key,
  last_value integer not null default 0
             check (last_value between 0 and 999999),
  updated_at timestamptz not null default now()
);

alter table public.adjustment_ref_counters enable row level security;
revoke all on table public.adjustment_ref_counters
  from public, anon, authenticated, service_role;

create or replace function public.allocate_adjustment_ref_for(p_date date)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_next integer;
begin
  insert into public.adjustment_ref_counters as c (ref_date, last_value)
  values (p_date, 1)
  on conflict (ref_date) do update
    set last_value = c.last_value + 1,
        updated_at = now()
  returning c.last_value into v_next;

  if v_next > 999999 then
    raise exception 'daily adjustment reference capacity exhausted';
  end if;

  return 'STA' || to_char(p_date, 'YYMMDD') || lpad(v_next::text, 6, '0');
end;
$$;

create or replace function public.allocate_adjustment_ref()
returns text
language sql
security definer
set search_path = public
as $$
  select public.allocate_adjustment_ref_for(
    (now() at time zone 'Asia/Dhaka')::date
  );
$$;

revoke execute on function public.allocate_adjustment_ref_for(date),
  public.allocate_adjustment_ref()
  from public, anon, authenticated;
grant execute on function public.allocate_adjustment_ref_for(date),
  public.allocate_adjustment_ref()
  to service_role;

alter table public.wallet_adjustment_requests
  add column if not exists public_ref text;

do $$
declare
  v_request record;
begin
  for v_request in
    select id, (requested_at at time zone 'Asia/Dhaka')::date as ref_date
      from public.wallet_adjustment_requests
     where public_ref is null
     order by requested_at, id
  loop
    update public.wallet_adjustment_requests
       set public_ref = public.allocate_adjustment_ref_for(v_request.ref_date)
     where id = v_request.id;
  end loop;
end;
$$;

alter table public.wallet_adjustment_requests
  alter column public_ref set default public.allocate_adjustment_ref(),
  alter column public_ref set not null;

do $$
begin
  if not exists (
    select 1 from pg_constraint
     where conname = 'wallet_adjustment_requests_public_ref_format_check'
  ) then
    alter table public.wallet_adjustment_requests
      add constraint wallet_adjustment_requests_public_ref_format_check
      check (public_ref ~ '^STA[0-9]{12}$');
  end if;
end;
$$;

create unique index if not exists wallet_adjustment_requests_public_ref_key
  on public.wallet_adjustment_requests (public_ref);

create or replace function public.prevent_adjustment_public_ref_change()
returns trigger
language plpgsql
as $$
begin
  if new.public_ref is distinct from old.public_ref then
    raise exception 'adjustment request reference is immutable' using errcode = '55000';
  end if;
  return new;
end;
$$;

drop trigger if exists wallet_adjustment_public_ref_immutable
  on public.wallet_adjustment_requests;
create trigger wallet_adjustment_public_ref_immutable
  before update on public.wallet_adjustment_requests
  for each row execute function public.prevent_adjustment_public_ref_change();

revoke execute on function public.prevent_adjustment_public_ref_change()
  from public, anon, authenticated, service_role;

comment on column public.wallet_adjustment_requests.public_ref is
  'Immutable customer-facing manual adjustment reference, STAYYMMDD######.';


-- SOURCE: 0090_booking_attempt_response_watchdog.sql
-- A recorded HTTP response proves the Book request completed at the transport
-- boundary. It must not be reported as a supplier-call timeout simply because
-- a process died before the response could be finalized into a booking.
--
-- The normal request path persists the booking immediately after Book. This
-- secondary branch only catches a genuine crash between that response and the
-- transaction, and preserves the no-replay reconciliation policy.

create or replace function public.process_booking_attempt_watchdog(
  p_limit integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_attempt public.booking_attempts;
  v_state_before text;
  v_reason_code text;
  v_reason_detail text;
  v_wallet_result jsonb;
  v_case_id uuid;
  v_processed integer := 0;
  v_cases_created integer := 0;
  v_cutoff timestamptz := now() - interval '3 minutes';
begin
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception 'attempt watchdog limit must be between 1 and 500'
      using errcode = '22023';
  end if;

  for v_attempt in
    select attempt.*
      from public.booking_attempts attempt
     where attempt.state in ('submitting', 'unknown')
       and attempt.operation_request_key is not null
       and coalesce(
         attempt.supplier_response_received_at,
         attempt.supplier_call_started_at,
         attempt.submitted_at,
         attempt.resolved_at,
         attempt.updated_at
       ) <= v_cutoff
       and not exists (
         select 1
           from public.booking_reconciliation_cases open_case
          where open_case.subject_booking_attempt_id = attempt.id
            and open_case.case_type = 'attempt_uncertainty'
            and open_case.state in (
              'open', 'assigned', 'awaiting_supplier',
              'awaiting_finance', 'awaiting_approval'
            )
       )
     order by coalesce(
       attempt.supplier_response_received_at,
       attempt.supplier_call_started_at,
       attempt.submitted_at,
       attempt.resolved_at,
       attempt.updated_at
     ), attempt.id
     limit p_limit
     for update skip locked
  loop
    v_state_before := v_attempt.state;
    v_reason_code := case
      when v_attempt.supplier_response_received_at is not null
        then 'book_response_finalization_watchdog_timeout'
      when v_attempt.supplier_call_started_at is not null
        then 'book_supplier_call_watchdog_timeout'
      else 'book_local_claim_watchdog_timeout'
    end;
    v_reason_detail := case
      when v_attempt.supplier_response_received_at is not null then
        'Book received an HTTP response but no booking outcome was finalized within the three-minute watchdog; reconcile by authoritative read and never replay the write.'
      when v_attempt.supplier_call_started_at is not null then
        'Book supplier write exceeded the three-minute watchdog; reconcile by authoritative read and never replay the write.'
      else
        'Book attempt claim exceeded the three-minute watchdog before the supplier-call boundary was recorded.'
    end;

    v_wallet_result := public.wallet_mark_reconciliation(
      null,
      v_attempt.id,
      v_reason_detail
    );

    update public.booking_attempts
       set state = 'unknown',
           error_code = upper(v_reason_code),
           supplier_message = coalesce(supplier_message, v_reason_detail),
           resolved_at = coalesce(resolved_at, now())
     where id = v_attempt.id;

    v_case_id := null;
    insert into public.booking_reconciliation_cases (
      subject_booking_attempt_id, case_type, state,
      reason_code, reason_detail, opened_source,
      opened_by_user_id, opened_by_role, opened_at,
      assigned_team, severity, priority, due_at,
      evidence, evidence_latest_at, evidence_normalizer_version,
      policy_version
    ) values (
      v_attempt.id, 'attempt_uncertainty', 'open',
      v_reason_code, v_reason_detail, 'operation',
      'system:attempt-watchdog', 'system', now(),
      'support', 'high', 85, now() + interval '15 minutes',
      jsonb_build_array(jsonb_build_object(
        'kind', 'attempt_watchdog_observation',
        'observedAt', now(),
        'attemptStateBefore', v_state_before,
        'supplierCallStartedAt', v_attempt.supplier_call_started_at,
        'supplierResponseRecorded',
          v_attempt.supplier_response_received_at is not null,
        'walletPositionProtected', coalesce(
          (v_wallet_result->>'ok')::boolean, false
        ),
        'automaticSupplierReplay', false
      )),
      now(), 1, 1
    ) on conflict do nothing
    returning id into v_case_id;

    v_processed := v_processed + 1;
    if v_case_id is not null then
      v_cases_created := v_cases_created + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'processed', v_processed,
    'casesCreated', v_cases_created,
    'thresholdSeconds', 180,
    'caseDueSeconds', 900,
    'limit', p_limit,
    'historicalNullIdentityExcluded', true,
    'automaticSupplierReplay', false
  );
end;
$$;

revoke all on function public.process_booking_attempt_watchdog(integer)
  from public, anon, authenticated;
grant execute on function public.process_booking_attempt_watchdog(integer)
  to service_role;

comment on function public.process_booking_attempt_watchdog(integer) is
  'Moves stale operation-identified attempts to owned reconciliation after three minutes. A recorded HTTP response is classified as finalization timeout, never as a supplier-call timeout; no supplier write is replayed.';


-- SOURCE: 0091_booking_pnr_deadline_refresh_queue.sql
-- Durable post-Book PNR deadline refreshes. The Book write remains atomic and
-- is never replayed: this queue contains only safe `/api/pnr` reads for newly
-- created held Triplover bookings. There is intentionally no backfill, so
-- applying this migration never reconciles an existing production booking.
--
-- Carrier availability policy, confirmed against supplier samples:
--   * BS: PNR TTL is normally available immediately. Try at 0, +1, +3 min.
--   * every non-BS carrier: TTL may arrive 2--5 minutes later. Try at
--     +2, +4, +6 min. An early null value is never terminal.

create table public.booking_pnr_refresh_jobs (
  id                  uuid primary key default gen_random_uuid(),
  booking_id          uuid not null unique
                      references public.flight_bookings(id) on delete restrict,
  carrier_group       text not null,
  state               text not null default 'pending',
  attempt_count       integer not null default 0,
  next_attempt_at     timestamptz not null,
  claimed_at          timestamptz,
  claimed_by          text,
  last_attempt_at     timestamptz,
  last_error_code     text,
  completed_at        timestamptz,
  completion_reason   text,
  created_at          timestamptz not null default clock_timestamp(),
  updated_at          timestamptz not null default clock_timestamp(),
  constraint booking_pnr_refresh_jobs_carrier_group_check
    check (carrier_group in ('bs_immediate', 'non_bs_delayed')),
  constraint booking_pnr_refresh_jobs_state_check
    check (state in ('pending', 'running', 'completed', 'exhausted', 'skipped')),
  constraint booking_pnr_refresh_jobs_attempt_count_check
    check (attempt_count between 0 and 3),
  constraint booking_pnr_refresh_jobs_error_code_check
    check (last_error_code is null or last_error_code ~ '^[A-Z0-9_:-]{1,80}$'),
  constraint booking_pnr_refresh_jobs_shape_check
    check (
      (state = 'pending' and claimed_at is null and claimed_by is null and completed_at is null)
      or (state = 'running' and claimed_at is not null and claimed_by is not null and completed_at is null)
      or (state in ('completed', 'exhausted', 'skipped') and completed_at is not null)
    )
);

create index booking_pnr_refresh_jobs_due_idx
  on public.booking_pnr_refresh_jobs (next_attempt_at, id)
  where state = 'pending';
create index booking_pnr_refresh_jobs_running_lease_idx
  on public.booking_pnr_refresh_jobs (claimed_at, id)
  where state = 'running';

create trigger booking_pnr_refresh_jobs_touch_updated_at
  before update on public.booking_pnr_refresh_jobs
  for each row execute function public.touch_updated_at();

-- Centralize queue timing in the database so all workers obey the exact same
-- carrier policy, regardless of deployment topology or server timezone.
create or replace function public.booking_pnr_refresh_initial_due_at_v1(
  p_carrier_group text,
  p_booked_at timestamptz
)
returns timestamptz
language sql
immutable
set search_path = public
as $$
  select case p_carrier_group
    when 'bs_immediate' then p_booked_at
    when 'non_bs_delayed' then p_booked_at + interval '2 minutes'
    else null
  end;
$$;

-- `p_attempt_count` is the completed read count. Returning NULL means the
-- bounded retry policy is exhausted. A clock-relative minimum keeps a delayed
-- scheduler from issuing two supplier calls back-to-back in the same run.
create or replace function public.booking_pnr_refresh_next_due_at_v1(
  p_carrier_group text,
  p_attempt_count integer,
  p_booked_at timestamptz
)
returns timestamptz
language plpgsql
stable
set search_path = public
as $$
begin
  if p_carrier_group = 'bs_immediate' then
    return case p_attempt_count
      when 1 then greatest(p_booked_at + interval '1 minute', clock_timestamp() + interval '1 minute')
      when 2 then greatest(p_booked_at + interval '3 minutes', clock_timestamp() + interval '2 minutes')
      else null
    end;
  end if;
  if p_carrier_group = 'non_bs_delayed' then
    return case p_attempt_count
      when 1 then greatest(p_booked_at + interval '4 minutes', clock_timestamp() + interval '2 minutes')
      when 2 then greatest(p_booked_at + interval '6 minutes', clock_timestamp() + interval '2 minutes')
      else null
    end;
  end if;
  return null;
end;
$$;

-- Enqueue only newly inserted supplier holds. Existing rows are deliberately
-- untouched; queueing starts with bookings created after this migration.
create or replace function public.enqueue_booking_pnr_refresh_job_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_carrier_group text;
begin
  if new.legacy_operational
     or lower(coalesce(new.supplier, '')) <> 'triplover'
     or new.status <> 'on-hold'
     or new.direct_ticketing
     or new.import_source is not null
     or coalesce(new.supplier_account, '') not in ('firsttrip', 'takeoff')
     or nullif(btrim(coalesce(new.pnr, '')), '') is null
     or nullif(btrim(coalesce(new.booking_code_ref, '')), '') is null
     or nullif(btrim(new.supplier_refs->>'uniqueTransId'), '') is null
     or nullif(btrim(new.supplier_refs->>'itemCodeRef'), '') is null
     or nullif(btrim(new.supplier_refs->>'priceCodeRef'), '') is null then
    return new;
  end if;

  v_carrier_group := case upper(btrim(coalesce(new.itinerary->>'carrierCode', '')))
    when 'BS' then 'bs_immediate'
    else 'non_bs_delayed'
  end;
  insert into public.booking_pnr_refresh_jobs (
    booking_id, carrier_group, next_attempt_at
  ) values (
    new.id,
    v_carrier_group,
    public.booking_pnr_refresh_initial_due_at_v1(v_carrier_group, new.created_at)
  ) on conflict (booking_id) do nothing;
  return new;
end;
$$;

create trigger flight_bookings_enqueue_pnr_refresh_job_v1
  after insert on public.flight_bookings
  for each row execute function public.enqueue_booking_pnr_refresh_job_v1();

-- One worker claims one safe PNR read. A stale lease can be reclaimed because
-- PNR is read-only. Jobs for bookings that are no longer ordinary held
-- bookings are closed without a supplier call.
create or replace function public.claim_due_booking_pnr_refresh_job_v1(
  p_worker_id text
)
returns table (
  job_id uuid,
  booking_id uuid,
  supplier_account text,
  supplier_refs jsonb,
  pnr text,
  booking_ref_number text,
  booking_code_ref text,
  carrier_code text,
  deadline_not_before timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
begin
  if nullif(btrim(p_worker_id), '') is null or char_length(p_worker_id) > 255 then
    raise exception 'PNR refresh worker identity is required' using errcode = '22023';
  end if;

  update public.booking_pnr_refresh_jobs
     set state = 'pending', claimed_at = null, claimed_by = null,
         last_error_code = coalesce(last_error_code, 'WORKER_LEASE_EXPIRED')
   where state = 'running'
     and claimed_at < clock_timestamp() - interval '3 minutes';

  update public.booking_pnr_refresh_jobs job
     set state = 'skipped', completed_at = clock_timestamp(),
         completion_reason = 'booking_not_refreshable',
         claimed_at = null, claimed_by = null
    from public.flight_bookings booking
   where booking.id = job.booking_id
     and job.state = 'pending'
     and job.next_attempt_at <= clock_timestamp()
     and (
       booking.legacy_operational
       or lower(coalesce(booking.supplier, '')) <> 'triplover'
       or booking.status <> 'on-hold'
       or booking.operation_kind is not null
       or booking.import_source is not null
       or coalesce(booking.supplier_account, '') not in ('firsttrip', 'takeoff')
       or nullif(btrim(coalesce(booking.pnr, '')), '') is null
       or nullif(btrim(coalesce(booking.booking_code_ref, '')), '') is null
       or nullif(btrim(booking.supplier_refs->>'uniqueTransId'), '') is null
       or nullif(btrim(booking.supplier_refs->>'itemCodeRef'), '') is null
       or nullif(btrim(booking.supplier_refs->>'priceCodeRef'), '') is null
     );

  return query
  with candidate as (
    select job.id
      from public.booking_pnr_refresh_jobs job
      join public.flight_bookings booking on booking.id = job.booking_id
     where job.state = 'pending'
       and job.next_attempt_at <= clock_timestamp()
       and not booking.legacy_operational
       and lower(coalesce(booking.supplier, '')) = 'triplover'
       and booking.status = 'on-hold'
       and booking.operation_kind is null
       and booking.import_source is null
       and booking.supplier_account in ('firsttrip', 'takeoff')
     order by job.next_attempt_at, job.id
     limit 1
     for update of job skip locked
  ), claimed as (
    update public.booking_pnr_refresh_jobs job
       set state = 'running', claimed_at = clock_timestamp(), claimed_by = p_worker_id
      from candidate
     where job.id = candidate.id
    returning job.id, job.booking_id
  )
  select
    claimed.id,
    booking.id,
    booking.supplier_account,
    booking.supplier_refs,
    booking.pnr,
    booking.booking_ref_number,
    booking.booking_code_ref,
    booking.itinerary->>'carrierCode',
    coalesce(booking.submission_started_at, booking.created_at)
  from claimed
  join public.flight_bookings booking on booking.id = claimed.booking_id;
end;
$$;

-- Missing PNR deadlines and transport/protocol failures consume the same
-- bounded retry budget. A missing early non-BS value therefore remains queued
-- through +6 minutes; it is never persisted as an authoritative NULL read.
create or replace function public.finish_booking_pnr_refresh_job_v1(
  p_job_id uuid,
  p_worker_id text,
  p_outcome text,
  p_error_code text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_job public.booking_pnr_refresh_jobs;
  v_attempt_count integer;
  v_next_attempt_at timestamptz;
begin
  if p_outcome not in ('deadline_found', 'deadline_missing', 'retryable_error', 'skipped') then
    raise exception 'unsupported PNR refresh outcome' using errcode = '22023';
  end if;
  if p_error_code is not null and p_error_code !~ '^[A-Z0-9_:-]{1,80}$' then
    raise exception 'invalid PNR refresh error code' using errcode = '22023';
  end if;

  select * into v_job
    from public.booking_pnr_refresh_jobs
   where id = p_job_id
   for update;
  if not found or v_job.state <> 'running' or v_job.claimed_by <> p_worker_id then
    return jsonb_build_object('ok', false, 'code', 'JOB_NOT_CLAIMED');
  end if;

  if p_outcome = 'deadline_found' then
    update public.booking_pnr_refresh_jobs
       set state = 'completed', attempt_count = attempt_count + 1,
           last_attempt_at = clock_timestamp(), last_error_code = null,
           completed_at = clock_timestamp(), completion_reason = 'deadline_found',
           claimed_at = null, claimed_by = null
     where id = v_job.id;
    return jsonb_build_object('ok', true, 'state', 'completed');
  end if;

  if p_outcome = 'skipped' then
    update public.booking_pnr_refresh_jobs
       set state = 'skipped', completed_at = clock_timestamp(),
           completion_reason = coalesce(p_error_code, 'worker_skipped'),
           claimed_at = null, claimed_by = null
     where id = v_job.id;
    return jsonb_build_object('ok', true, 'state', 'skipped');
  end if;

  v_attempt_count := v_job.attempt_count + 1;
  v_next_attempt_at := public.booking_pnr_refresh_next_due_at_v1(
    v_job.carrier_group, v_attempt_count, v_job.created_at
  );
  if v_next_attempt_at is null then
    update public.booking_pnr_refresh_jobs
       set state = 'exhausted', attempt_count = v_attempt_count,
           last_attempt_at = clock_timestamp(), last_error_code = p_error_code,
           completed_at = clock_timestamp(),
           completion_reason = case
             when p_outcome = 'deadline_missing' then 'deadline_unavailable_after_retry_window'
             else 'retry_window_exhausted'
           end,
           claimed_at = null, claimed_by = null
     where id = v_job.id;
    return jsonb_build_object('ok', true, 'state', 'exhausted');
  end if;

  update public.booking_pnr_refresh_jobs
     set state = 'pending', attempt_count = v_attempt_count,
         next_attempt_at = v_next_attempt_at,
         last_attempt_at = clock_timestamp(), last_error_code = p_error_code,
         claimed_at = null, claimed_by = null
   where id = v_job.id;
  return jsonb_build_object('ok', true, 'state', 'pending');
end;
$$;

alter table public.booking_pnr_refresh_jobs enable row level security;
revoke all on table public.booking_pnr_refresh_jobs
  from public, anon, authenticated, service_role;

revoke all on function public.booking_pnr_refresh_initial_due_at_v1(text, timestamptz),
  public.booking_pnr_refresh_next_due_at_v1(text, integer, timestamptz),
  public.enqueue_booking_pnr_refresh_job_v1(),
  public.claim_due_booking_pnr_refresh_job_v1(text),
  public.finish_booking_pnr_refresh_job_v1(uuid, text, text, text)
  from public, anon, authenticated, service_role;
grant execute on function public.claim_due_booking_pnr_refresh_job_v1(text),
  public.finish_booking_pnr_refresh_job_v1(uuid, text, text, text)
  to service_role;

comment on table public.booking_pnr_refresh_jobs is
  'Durable, bounded read-only PNR deadline refreshes for newly created Triplover holds. BS is due immediately; all non-BS carriers start after two minutes and retry through six minutes. Existing bookings are never backfilled.';


-- SOURCE: 0092_takeoff_manual_ticket_reconciliation.sql
-- Forward-only extension of the exact ticketed reconciliation resolver.
--
-- Generic ticketed evidence keeps its existing ticketCodeRef requirement.
-- TakeOff's manual-portal profile is the narrow exception: Triplover can
-- report an issued ticket number and issue time but no ticketCodeRef. That
-- profile is accepted only when immutable AirTicketingDetails evidence echoes
-- the exact booking uniqueTransId and includes a positive numeric supplier
-- bookingId. The resolver independently checks those facts before any wallet
-- movement, then carries both identifiers into every material audit record.

create or replace function public.resolve_booking_reconciliation_ticketed_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_execution_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_contract jsonb;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_operation public.booking_operations;
  v_reservation public.wallet_reservations;
  v_account public.wallet_accounts;
  v_evidence public.booking_reconciliation_observations;
  v_ticketed_profile text;
  v_is_takeoff_manual_ticket boolean := false;
  v_ticket_code_ref text;
  v_ticket_numbers jsonb;
  v_supplier_pnr text;
  v_airlines_pnr jsonb;
  v_supplier_status text;
  v_issued_at timestamptz;
  v_expected_supplier_unique_trans_id text;
  v_supplier_unique_trans_id text;
  v_supplier_internal_booking_id_text text;
  v_supplier_internal_booking_id bigint;
  v_supplier_identifiers jsonb;
  v_available_before bigint;
  v_hold_before bigint;
  v_ledger_entry_id uuid;
  v_event_id bigint;
  v_occurrence_number integer;
  v_from_lifecycle text;
  v_resolution_result jsonb;
begin
  v_contract := public.booking_reconciliation_resolution_contract_v1(
    p_booking_id, p_case_id, p_expected_case_version, p_proposal_hash,
    p_actor_user_id, p_execution_request_key, 'ticketed'
  );
  if coalesce((v_contract->>'ok')::boolean, false) is not true
     or coalesce((v_contract->>'replay')::boolean, false) then
    return v_contract;
  end if;

  select * into strict v_booking
    from public.flight_bookings where id = p_booking_id;
  select * into strict v_case
    from public.booking_reconciliation_cases where id = p_case_id;
  if v_case.financial_disposition <> 'capture_existing_hold' then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_DISPOSITION_REQUIRED');
  end if;
  if v_booking.status not in ('on-hold', 'pending', 'in-progress') then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_STATUS_NOT_TICKETABLE');
  end if;
  if v_booking.payment_state not in ('held', 'reconciliation')
     or v_booking.captured_amount <> 0
     or v_booking.refunded_amount <> 0 then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_PAYMENT_NOT_CAPTURABLE');
  end if;

  if v_case.operation_id is not null then
    select * into v_operation
      from public.booking_operations where id = v_case.operation_id;
    if v_operation.state <> 'needs_reconciliation' then
      return jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_RECONCILING');
    end if;
  end if;
  select * into v_reservation
    from public.wallet_reservations
   where id = (v_contract->>'reservationId')::uuid;
  if not found
     or v_reservation.state not in ('active', 'reconciliation')
     or v_reservation.booking_id is distinct from p_booking_id
     or v_reservation.amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'PROTECTED_HOLD_REQUIRED');
  end if;
  select * into v_account
    from public.wallet_accounts
   where id = v_reservation.wallet_account_id;
  if not found
     or v_account.id is distinct from (v_contract->>'walletAccountId')::uuid
     or v_account.currency <> v_reservation.currency
     or v_booking.currency <> v_reservation.currency
     or (v_booking.payment_amount is not null
       and v_booking.payment_amount <> v_reservation.amount)
     or (v_booking.charged_wallet_account_id is not null
       and v_booking.charged_wallet_account_id <> v_account.id) then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_IDENTITY_MISMATCH');
  end if;
  if v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'HOLD_BALANCE_MISMATCH');
  end if;

  select observation.* into v_evidence
    from jsonb_array_elements_text(
      v_case.proposal->'evidenceObservationIds'
    ) evidence_id(id)
    join public.booking_reconciliation_observations observation
      on observation.id = evidence_id.id::uuid
     and observation.reconciliation_case_id = v_case.id
   where observation.normalized_facts->>'requestedPurpose' = 'ticketed'
     and observation.normalized_facts #>> '{validation,authoritativeFor}' = 'ticketed'
     and coalesce((observation.normalized_facts
       #>> '{validation,valid}')::boolean, false)
     and coalesce((observation.normalized_facts
       #>> '{validation,complete}')::boolean, false)
     and coalesce((observation.normalized_facts
       #>> '{validation,fresh}')::boolean, false)
     and coalesce((observation.normalized_facts
       #>> '{validation,identityMatches}')::boolean, false)
     and observation.normalized_facts
       #>> '{evidence,airTicketing,source}' = 'air-ticketing-details'
   order by observation.observed_at desc, observation.id desc
   limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'AUTHORITATIVE_TICKET_EVIDENCE_REQUIRED');
  end if;

  -- Do not trust the validation summary alone for a financial resolution.
  -- The locked booking's supplier reference is the authority for the exact
  -- Triplover transaction identity, and manual TakeOff evidence must echo it.
  v_expected_supplier_unique_trans_id := v_booking.supplier_refs->>'uniqueTransId';
  if v_expected_supplier_unique_trans_id is null
     or v_expected_supplier_unique_trans_id = ''
     or v_expected_supplier_unique_trans_id <> btrim(v_expected_supplier_unique_trans_id) then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_REQUIRED');
  end if;
  v_ticketed_profile := coalesce(
    nullif(btrim(v_evidence.normalized_facts
      #>> '{validation,ticketedProfile}'), ''),
    'generic'
  );
  if v_ticketed_profile not in ('generic', 'takeoff_manual_ticket') then
    return jsonb_build_object('ok', false, 'code', 'UNSUPPORTED_TICKET_EVIDENCE_PROFILE');
  end if;
  v_is_takeoff_manual_ticket := v_ticketed_profile = 'takeoff_manual_ticket';
  v_supplier_unique_trans_id := v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,ticketInfoUniqueTransId}';
  if v_supplier_unique_trans_id = ''
     or v_supplier_unique_trans_id <> btrim(v_supplier_unique_trans_id) then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_MISMATCH');
  end if;
  if v_supplier_unique_trans_id is not null
     and v_supplier_unique_trans_id <> v_expected_supplier_unique_trans_id then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_MISMATCH');
  end if;
  v_supplier_internal_booking_id_text := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,supplierBookingId}'), '');

  v_ticket_code_ref := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,ticketCodeRef}'), '');
  v_ticket_numbers := v_evidence.normalized_facts
    #> '{evidence,airTicketing,facts,ticketNumbers}';
  if jsonb_typeof(v_ticket_numbers) <> 'array'
     or jsonb_array_length(v_ticket_numbers) = 0
     or exists (
       select 1 from jsonb_array_elements(v_ticket_numbers) ticket(value)
        where jsonb_typeof(ticket.value) <> 'string'
           or nullif(btrim(ticket.value #>> '{}'), '') is null
     ) then
    return jsonb_build_object('ok', false, 'code', 'TICKET_EVIDENCE_INCOMPLETE');
  end if;
  v_supplier_pnr := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,pnr}'), '');
  v_airlines_pnr := v_evidence.normalized_facts
    #> '{evidence,airTicketing,facts,airlinesPnr}';
  v_supplier_status := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,supplierStatus}'), '');
  begin
    v_issued_at := nullif(v_evidence.normalized_facts
      #>> '{evidence,airTicketing,facts,issuedAt}', '')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ISSUED_TIMESTAMP');
  end;

  if v_is_takeoff_manual_ticket then
    if v_booking.supplier_account is distinct from 'takeoff' then
      return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_PROFILE_SUPPLIER_MISMATCH');
    end if;
    if v_supplier_unique_trans_id is null then
      return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_REQUIRED');
    end if;
    if jsonb_typeof(v_evidence.normalized_facts
         #> '{evidence,airTicketing,facts,supplierBookingId}') <> 'number'
       or v_supplier_internal_booking_id_text is null
       or v_supplier_internal_booking_id_text !~ '^[1-9][0-9]{0,18}$' then
      return jsonb_build_object('ok', false, 'code', 'SUPPLIER_INTERNAL_BOOKING_ID_REQUIRED');
    end if;
    begin
      v_supplier_internal_booking_id := v_supplier_internal_booking_id_text::bigint;
    exception when numeric_value_out_of_range then
      return jsonb_build_object('ok', false, 'code', 'SUPPLIER_INTERNAL_BOOKING_ID_REQUIRED');
    end;
    if v_issued_at is null then
      return jsonb_build_object('ok', false, 'code', 'ISSUED_TIMESTAMP_REQUIRED');
    end if;
  elsif v_ticket_code_ref is null then
    -- Preserve the generic ticketed path unchanged: a ticket code remains
    -- mandatory unless the explicit TakeOff manual evidence profile applies.
    return jsonb_build_object('ok', false, 'code', 'TICKET_EVIDENCE_INCOMPLETE');
  end if;

  v_issued_at := coalesce(v_issued_at, v_evidence.observed_at);
  if v_issued_at > v_evidence.observed_at + interval '1 minute' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ISSUED_TIMESTAMP');
  end if;
  v_supplier_identifiers := jsonb_build_object(
    'ticketedProfile', v_ticketed_profile,
    'supplierAccount', v_booking.supplier_account,
    'supplierUniqueTransId', v_supplier_unique_trans_id,
    'expectedSupplierUniqueTransId', v_expected_supplier_unique_trans_id,
    'supplierInternalBookingId', v_supplier_internal_booking_id
  );

  if exists (
    select 1 from public.wallet_ledger_entries ledger
     where ledger.idempotency_key = p_execution_request_key || ':capture'
  ) then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_IDEMPOTENCY_CONFLICT');
  end if;
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts
     set hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;
  update public.wallet_reservations
     set booking_id = p_booking_id,
         booking_attempt_id = null,
         state = 'captured',
         issued_by_user_id = p_actor_user_id,
         captured_at = clock_timestamp(),
         reconciliation_at = null,
         reconciliation_reason = null
   where id = v_reservation.id;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks, metadata
  ) values (
    v_account.id, 'booking_confirm', v_reservation.amount,
    v_reservation.currency, v_available_before, v_available_before,
    v_hold_before, v_hold_before - v_reservation.amount,
    v_booking.id, v_booking.public_ref, v_reservation.id,
    p_execution_request_key || ':capture', p_actor_user_id,
    v_contract->>'actorRole',
    'Approved ticketing reconciliation capture',
    jsonb_build_object(
      'reconciliationCaseId', v_case.id,
      'proposalHash', v_case.proposal_hash,
      'operationId', v_case.operation_id,
      'evidenceObservationId', v_evidence.id,
      'resolutionKind', 'ticketed',
      'supplierIdentifiers', v_supplier_identifiers
    )
  ) returning id into v_ledger_entry_id;

  v_from_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  update public.flight_bookings
     set status = 'confirmed',
         charged_wallet_account_id = v_account.id,
         payment_state = 'captured',
         payment_amount = v_reservation.amount,
         captured_amount = v_reservation.amount,
         refunded_amount = 0,
         issued_by_user_id = p_actor_user_id,
         issued_at = coalesce(issued_at, v_issued_at),
         pnr = case when v_is_takeoff_manual_ticket then v_booking.pnr
           else coalesce(v_supplier_pnr, pnr) end,
         airlines_pnr = case
           when v_is_takeoff_manual_ticket then v_booking.airlines_pnr
           when jsonb_typeof(v_airlines_pnr) = 'array'
             and jsonb_array_length(v_airlines_pnr) > 0
             then v_airlines_pnr else airlines_pnr end,
         -- These are intentionally exact locked values, not a supplier-write
         -- path. The reconciliation keeps the original reference chain and
         -- deadline while storing the supplier's additional IDs in audit data.
         supplier_refs = v_booking.supplier_refs,
         ticketing_deadline_at = v_booking.ticketing_deadline_at,
         booking_status = coalesce(v_supplier_status, 'Confirmed'),
         ticket_code_ref = case when v_is_takeoff_manual_ticket
           then ticket_code_ref else v_ticket_code_ref end,
         ticket_numbers = v_ticket_numbers,
         active_operation_id = null,
         operation_kind = null,
         operation_reason = null,
         operation_request_id = null,
         operation_actor_user_id = null,
         operation_started_at = null,
         operation_prior_status = null
   where id = v_booking.id;
  if v_case.operation_id is not null then
    update public.booking_operations
       set state = 'succeeded',
           completed_at = clock_timestamp(),
           error_code = null,
           error_message = null,
           supplier_evidence = coalesce(supplier_evidence, '{}'::jsonb)
             || jsonb_build_object(
               'reconciliationResolution', jsonb_build_object(
                 'caseId', v_case.id,
                 'outcome', 'ticketed',
                 'evidenceObservationId', v_evidence.id,
                 'supplierIdentifiers', v_supplier_identifiers
               )
             )
     where id = v_case.operation_id;
  end if;

  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'confirmed';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle, 'confirmed',
    v_booking.status, 'confirmed', v_booking.operation_kind,
    v_booking.operation_reason, p_actor_user_id, 'ReconciliationTicketed',
    jsonb_build_object(
      'evidenceObservationId', v_evidence.id,
      'ticketCodeRefPresent', v_ticket_code_ref is not null,
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'supplierIdentifiers', v_supplier_identifiers
    ),
    p_execution_request_key || ':confirmed', v_case.operation_id,
    v_case.id, v_occurrence_number, v_issued_at, clock_timestamp(),
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'confirmed',
      'paymentState', 'captured',
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'operationKind', coalesce(v_booking.operation_kind, 'reconciliation'),
      'reconciliationCaseId', v_case.id,
      'supplierIdentifiers', v_supplier_identifiers
    ), 1
  ) returning id into v_event_id;

  v_resolution_result := jsonb_build_object(
    'bookingStatus', 'confirmed',
    'paymentState', 'captured',
    'reservationId', v_reservation.id,
    'walletAccountId', v_account.id,
    'ledgerEntryId', v_ledger_entry_id,
    'lifecycleEventId', v_event_id,
    'capturedAmount', v_reservation.amount,
    'currency', v_reservation.currency,
    'availableBalance', v_available_before,
    'holdBalance', v_hold_before - v_reservation.amount,
    'supplierUniqueTransId', v_supplier_unique_trans_id,
    'supplierInternalBookingId', v_supplier_internal_booking_id,
    'supplierIdentifiers', v_supplier_identifiers
  );
  update public.booking_reconciliation_cases
     set state = 'resolved',
         resolution_outcome = 'ticketed',
         resolution = jsonb_build_object(
           'version', 1,
           'executionRequestKey', p_execution_request_key,
           'proposalHash', v_case.proposal_hash,
           'resolutionKind', 'ticketed',
           'executedByRole', v_contract->>'actorRole',
           'evidenceObservationIds', v_case.proposal->'evidenceObservationIds',
           'supplierIdentifiers', v_supplier_identifiers,
           'result', v_resolution_result
         ),
         resolution_reason = v_case.proposal->>'reason',
         resolved_by_user_id = p_actor_user_id,
         resolved_at = clock_timestamp(),
         closed_at = clock_timestamp(),
         version = version + 1
   where id = v_case.id;

  return v_resolution_result || jsonb_build_object(
    'ok', true,
    'replay', false,
    'caseId', v_case.id,
    'caseVersion', v_case.version + 1,
    'resolutionKind', 'ticketed'
  );
end;
$$;

revoke all on function public.resolve_booking_reconciliation_ticketed_v1(
  uuid, uuid, integer, text, text, text
) from public, anon, authenticated;
grant execute on function public.resolve_booking_reconciliation_ticketed_v1(
  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.resolve_booking_reconciliation_ticketed_v1(
  uuid, uuid, integer, text, text, text
) is
  'Atomically captures the already protected hold and confirms a booking only from approved fresh immutable ticket evidence. Generic evidence requires ticketCodeRef; the narrow TakeOff manual-ticket profile additionally requires exact echoed uniqueTransId and a positive numeric supplier bookingId, which are preserved in resolution, operation, ledger, and lifecycle-event metadata.';


-- SOURCE: 0093_booking_reconciliation_captured_cancellation_confirmation.sql
-- Forward reissue of the later duplicate 0060 migration. Production already
-- owns 0060_booking_lifecycle_event_outbox, so this never repairs or changes
-- that historical migration; it applies this independent functionality once
-- under the next unique forward version.
--
-- A captured booking may be proven cancelled before the financial disposition
-- is known. This narrow contract records that supplier truth without releasing
-- a reservation, moving a wallet balance, creating a ledger entry, or closing
-- the case. A later, independently-approved financial proposal must use the
-- exact captured-cancellation wrappers from 0056.

create or replace function public.confirm_booking_reconciliation_cancelled_captured_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_execution_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_contract jsonb;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_operation public.booking_operations;
  v_reservation public.wallet_reservations;
  v_evidence public.booking_reconciliation_observations;
  v_existing public.booking_reconciliation_observations;
  v_supplier_pnr text;
  v_airlines_pnr jsonb;
  v_supplier_status text;
  v_cancelled_at timestamptz;
  v_event_id bigint;
  v_occurrence_number integer;
  v_from_lifecycle text;
  v_confirmation_facts jsonb;
  v_confirmation_hash text;
  v_result jsonb;
begin
  -- A repeat may arrive after the status proposal has deliberately been
  -- cleared for the subsequent financial proposal. The immutable observation
  -- is the case-bound idempotency record for this first, no-money stage.
  select observation.* into v_existing
    from public.booking_reconciliation_observations observation
   where observation.reconciliation_case_id = p_case_id
     and observation.observation_key = p_execution_request_key || ':cancelled-confirmed';
  if found then
    if v_existing.normalized_facts->>'action'
         <> 'captured_cancellation_confirmed' then
      raise exception 'captured cancellation request identity mismatch'
        using errcode = '22023';
    end if;
    return coalesce(v_existing.normalized_facts->'result', '{}'::jsonb)
      || jsonb_build_object('ok', true, 'replay', true, 'caseId', p_case_id);
  end if;

  v_contract := public.booking_reconciliation_resolution_contract_v1(
    p_booking_id, p_case_id, p_expected_case_version, p_proposal_hash,
    p_actor_user_id, p_execution_request_key, 'cancelled'
  );
  if coalesce((v_contract->>'ok')::boolean, false) is not true
     or coalesce((v_contract->>'replay')::boolean, false) then
    return v_contract;
  end if;

  select * into strict v_booking
    from public.flight_bookings where id = p_booking_id;
  select * into strict v_case
    from public.booking_reconciliation_cases where id = p_case_id;

  if v_case.financial_disposition <> 'none'
     or v_case.proposed_outcome <> 'cancelled'
     or v_booking.status not in ('on-hold', 'pending', 'in-progress')
     or v_booking.payment_state not in (
       'captured', 'partially-refunded', 'reconciliation'
     )
     or v_booking.captured_amount <= 0
     or v_booking.refunded_amount < 0
     or v_booking.refunded_amount >= v_booking.captured_amount then
    return jsonb_build_object(
      'ok', false, 'code', 'BOOKING_NOT_CAPTURED_CANCELLATION_CONFIRMABLE'
    );
  end if;
  if v_case.operation_id is not null then
    select * into v_operation
      from public.booking_operations where id = v_case.operation_id;
    if not found or v_operation.state <> 'needs_reconciliation' then
      return jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_RECONCILING');
    end if;
  end if;
  select * into v_reservation
    from public.wallet_reservations
   where id = (v_contract->>'reservationId')::uuid;
  if not found
     or v_reservation.state <> 'captured'
     or v_reservation.booking_id is distinct from p_booking_id
     or v_reservation.amount <> v_booking.captured_amount
     or v_reservation.wallet_account_id
        is distinct from v_booking.charged_wallet_account_id then
    return jsonb_build_object('ok', false, 'code', 'CAPTURED_RESERVATION_REQUIRED');
  end if;

  select observation.* into v_evidence
    from jsonb_array_elements_text(
      v_case.proposal->'evidenceObservationIds'
    ) evidence_id(id)
    join public.booking_reconciliation_observations observation
      on observation.id = evidence_id.id::uuid
     and observation.reconciliation_case_id = v_case.id
   where observation.normalized_facts->>'requestedPurpose' = 'cancelled'
     and observation.normalized_facts #>> '{validation,authoritativeFor}' = 'cancelled'
     and observation.normalized_facts #>> '{validation,valid}' = 'true'
     and observation.normalized_facts #>> '{validation,complete}' = 'true'
     and observation.normalized_facts #>> '{validation,fresh}' = 'true'
     and observation.normalized_facts
       #>> '{validation,identityMatches}' = 'true'
     and observation.normalized_facts
       #>> '{evidence,airTicketing,source}' = 'air-ticketing-details'
   order by observation.observed_at desc, observation.id desc
   limit 1;
  if not found then
    return jsonb_build_object(
      'ok', false, 'code', 'AUTHORITATIVE_CANCELLATION_EVIDENCE_REQUIRED'
    );
  end if;

  v_supplier_pnr := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,pnr}'), '');
  v_airlines_pnr := v_evidence.normalized_facts
    #> '{evidence,airTicketing,facts,airlinesPnr}';
  v_supplier_status := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,supplierStatus}'), '');
  begin
    v_cancelled_at := nullif(v_evidence.normalized_facts
      #>> '{evidence,airTicketing,facts,cancelledAt}', '')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CANCELLATION_TIMESTAMP');
  end;
  v_cancelled_at := coalesce(v_cancelled_at, v_evidence.observed_at);
  if v_cancelled_at > v_evidence.observed_at + interval '1 minute' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_CANCELLATION_TIMESTAMP');
  end if;

  v_from_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  update public.flight_bookings
     set status = 'cancelled',
         cancelled_at = coalesce(cancelled_at, v_cancelled_at),
         cancelled_by = p_actor_user_id,
         cancel_reason = coalesce(
           nullif(v_case.proposal->>'reason', ''),
           'Supplier cancellation verified; financial review remains open'
         ),
         pnr = coalesce(v_supplier_pnr, pnr),
         airlines_pnr = case
           when jsonb_typeof(v_airlines_pnr) = 'array'
             and jsonb_array_length(v_airlines_pnr) > 0
             then v_airlines_pnr else airlines_pnr end,
         booking_status = coalesce(v_supplier_status, 'Cancelled')
   where id = v_booking.id;

  if v_case.operation_id is not null then
    update public.booking_operations
       set supplier_evidence = coalesce(supplier_evidence, '{}'::jsonb)
           || jsonb_build_object(
             'reconciliationCancellationConfirmed', jsonb_build_object(
               'caseId', v_case.id,
               'evidenceObservationId', v_evidence.id,
               'financialReviewRequired', true
             )
           )
     where id = v_case.operation_id;
  end if;

  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'cancelled';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle, 'cancelled',
    v_booking.status, 'cancelled', v_booking.operation_kind,
    v_booking.operation_reason, p_actor_user_id,
    'ReconciliationCapturedCancellationConfirmed',
    jsonb_build_object('evidenceObservationId', v_evidence.id),
    p_execution_request_key || ':cancelled', v_case.operation_id,
    v_case.id, v_occurrence_number, v_cancelled_at,
    clock_timestamp(),
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'cancelled',
      'paymentState', v_booking.payment_state,
      'financialReviewRequired', true,
      'financialDisposition', 'none',
      'resolutionReason', v_case.proposal->>'reason',
      'reconciliationCaseId', v_case.id
    ), 1
  ) returning id into v_event_id;

  v_result := jsonb_build_object(
    'bookingStatus', 'cancelled',
    'paymentState', v_booking.payment_state,
    'lifecycleEventId', v_event_id,
    'evidenceObservationId', v_evidence.id,
    'statusMutation', true,
    'walletMutation', false,
    'reservationMutation', false,
    'ledgerMutation', false,
    'financialReviewRequired', true
  );
  v_confirmation_facts := jsonb_build_object(
    'action', 'captured_cancellation_confirmed',
    'evidenceObservationId', v_evidence.id,
    'evidenceSource', 'air-ticketing-details',
    'proposalHash', v_case.proposal_hash,
    'previousBookingStatus', v_booking.status,
    'newBookingStatus', 'cancelled',
    'paymentStateBefore', v_booking.payment_state,
    'paymentStateAfter', v_booking.payment_state,
    'walletMutation', false,
    'resolutionReason', v_case.proposal->>'reason',
    'result', v_result
  );
  v_confirmation_hash := encode(
    sha256(convert_to(v_confirmation_facts::text, 'UTF8')), 'hex'
  );
  insert into public.booking_reconciliation_observations (
    reconciliation_case_id, observation_key, observation_kind,
    observation_source, actor_user_id, actor_role, normalized_facts,
    normalized_facts_hash, observed_at
  ) values (
    v_case.id, p_execution_request_key || ':cancelled-confirmed',
    'staff_evidence', 'staff', p_actor_user_id, v_contract->>'actorRole',
    v_confirmation_facts, v_confirmation_hash, clock_timestamp()
  );

  -- The status proposal has been executed. Clear it only after preserving its
  -- reason/evidence in immutable lifecycle and observation records, then keep
  -- the same case open for the distinct financial proposal.
  update public.booking_reconciliation_cases
     set state = 'awaiting_finance',
         proposed_outcome = null,
         proposal = '{}'::jsonb,
         proposal_hash = null,
         proposed_by_user_id = null,
         proposed_at = null,
         approved_by_user_id = null,
         approved_at = null,
         rejected_by_user_id = null,
         rejected_at = null,
         rejection_reason = null,
         financial_disposition = 'none',
         financial_amount = null,
         financial_currency = null,
         external_settlement_reference = null,
         version = version + 1
   where id = v_case.id;

  return v_result || jsonb_build_object(
    'ok', true, 'replay', false,
    'caseId', v_case.id,
    'caseVersion', v_case.version + 1,
    'resolutionKind', 'cancelled'
  );
end;
$$;

revoke all on function public.confirm_booking_reconciliation_cancelled_captured_v1(
  uuid, uuid, integer, text, text, text
) from public, anon, authenticated;
grant execute on function public.confirm_booking_reconciliation_cancelled_captured_v1(
  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.confirm_booking_reconciliation_cancelled_captured_v1(
  uuid, uuid, integer, text, text, text
) is
  'Confirms a fresh, authoritative captured-booking cancellation without any wallet or ledger mutation. It keeps the same immutable case open for a separate financial review.';

-- Keeping a case open is an explicit investigative decision, not a silent
-- dismissal. Store the note as immutable case evidence; it cannot close or
-- mutate booking/payment/wallet state.
create or replace function public.record_booking_reconciliation_keep_open_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_evidence_observation_id uuid,
  p_actor_user_id text,
  p_request_key text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_case public.booking_reconciliation_cases;
  v_evidence public.booking_reconciliation_observations;
  v_existing public.booking_reconciliation_observations;
  v_facts jsonb;
  v_hash text;
begin
  if p_booking_id is null or p_case_id is null
     or p_evidence_observation_id is null
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 220
     or nullif(btrim(p_reason), '') is null
     or char_length(p_reason) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_KEEP_OPEN_NOTE');
  end if;
  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if not found or v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'KEEP_OPEN_FORBIDDEN');
  end if;
  select reconciliation_case.* into v_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;
  if v_case.state not in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     ) then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN');
  end if;
  select observation.* into v_evidence
    from public.booking_reconciliation_observations observation
   where observation.id = p_evidence_observation_id
     and observation.reconciliation_case_id = p_case_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_CASE_MISMATCH');
  end if;
  select observation.* into v_existing
    from public.booking_reconciliation_observations observation
   where observation.reconciliation_case_id = p_case_id
     and observation.observation_key = p_request_key || ':keep-open';
  if found then
    if v_existing.actor_user_id = p_actor_user_id
       and v_existing.normalized_facts->>'action' = 'case_kept_open'
       and v_existing.normalized_facts->>'reason' = p_reason
       and v_existing.normalized_facts->>'evidenceObservationId'
         = p_evidence_observation_id::text then
      return jsonb_build_object(
        'ok', true, 'replay', true, 'caseId', p_case_id,
        'caseVersion', v_case.version,
        'statusMutation', false, 'walletMutation', false
      );
    end if;
    raise exception 'keep-open request identity mismatch' using errcode = '22023';
  end if;
  v_facts := jsonb_build_object(
    'action', 'case_kept_open',
    'evidenceObservationId', p_evidence_observation_id,
    'evidenceSource', v_evidence.observation_source,
    'previousCaseState', v_case.state,
    'newCaseState', v_case.state,
    'previousBookingStatus', null,
    'newBookingStatus', null,
    'paymentChanges', false,
    'reason', p_reason
  );
  v_hash := encode(sha256(convert_to(v_facts::text, 'UTF8')), 'hex');
  insert into public.booking_reconciliation_observations (
    reconciliation_case_id, observation_key, observation_kind,
    observation_source, actor_user_id, actor_role,
    normalized_facts, normalized_facts_hash, observed_at
  ) values (
    p_case_id, p_request_key || ':keep-open', 'staff_evidence', 'staff',
    p_actor_user_id, v_actor_role, v_facts, v_hash, clock_timestamp()
  );
  return jsonb_build_object(
    'ok', true, 'replay', false, 'caseId', p_case_id,
    'caseVersion', v_case.version,
    'statusMutation', false, 'walletMutation', false
  );
end;
$$;

revoke all on function public.record_booking_reconciliation_keep_open_v1(
  uuid, uuid, uuid, text, text, text
) from public, anon, authenticated;
grant execute on function public.record_booking_reconciliation_keep_open_v1(
  uuid, uuid, uuid, text, text, text
) to service_role;

comment on function public.record_booking_reconciliation_keep_open_v1(
  uuid, uuid, uuid, text, text, text
) is
  'Appends an immutable evidence-linked investigation note without closing a case or mutating booking/payment/wallet state.';


-- SOURCE: 0094_booking_pnr_echoed_transaction_validation.sql
-- Forward-only hardening of the ticketed reconciliation resolver.
--
-- The prior TakeOff manual-ticket profile remains unchanged. This extension
-- adds an independent, generic safety check: when a fresh PNR response itself
-- returns one or more uniqueTransID echoes, every supplied echo must match
-- the locked booking reference byte-for-byte before the protected hold can be
-- captured. Missing PNR echoes remain absent; no request identifier is copied
-- into immutable supplier evidence.

-- Forward-only extension of the exact ticketed reconciliation resolver.
--
-- Generic ticketed evidence keeps its existing ticketCodeRef requirement.
-- TakeOff's manual-portal profile is the narrow exception: Triplover can
-- report an issued ticket number and issue time but no ticketCodeRef. That
-- profile is accepted only when immutable AirTicketingDetails evidence echoes
-- the exact booking uniqueTransId and includes a positive numeric supplier
-- bookingId. The resolver independently checks those facts before any wallet
-- movement, then carries both identifiers into every material audit record.

create or replace function public.resolve_booking_reconciliation_ticketed_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_execution_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_contract jsonb;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_operation public.booking_operations;
  v_reservation public.wallet_reservations;
  v_account public.wallet_accounts;
  v_evidence public.booking_reconciliation_observations;
  v_ticketed_profile text;
  v_is_takeoff_manual_ticket boolean := false;
  v_ticket_code_ref text;
  v_ticket_numbers jsonb;
  v_supplier_pnr text;
  v_airlines_pnr jsonb;
  v_supplier_status text;
  v_issued_at timestamptz;
  v_expected_supplier_unique_trans_id text;
  v_supplier_unique_trans_id text;
  v_pnr_supplier_unique_trans_ids jsonb;
  v_pnr_supplier_unique_trans_id text;
  v_supplier_internal_booking_id_text text;
  v_supplier_internal_booking_id bigint;
  v_supplier_identifiers jsonb;
  v_available_before bigint;
  v_hold_before bigint;
  v_ledger_entry_id uuid;
  v_event_id bigint;
  v_occurrence_number integer;
  v_from_lifecycle text;
  v_resolution_result jsonb;
begin
  v_contract := public.booking_reconciliation_resolution_contract_v1(
    p_booking_id, p_case_id, p_expected_case_version, p_proposal_hash,
    p_actor_user_id, p_execution_request_key, 'ticketed'
  );
  if coalesce((v_contract->>'ok')::boolean, false) is not true
     or coalesce((v_contract->>'replay')::boolean, false) then
    return v_contract;
  end if;

  select * into strict v_booking
    from public.flight_bookings where id = p_booking_id;
  select * into strict v_case
    from public.booking_reconciliation_cases where id = p_case_id;
  if v_case.financial_disposition <> 'capture_existing_hold' then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_DISPOSITION_REQUIRED');
  end if;
  if v_booking.status not in ('on-hold', 'pending', 'in-progress') then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_STATUS_NOT_TICKETABLE');
  end if;
  if v_booking.payment_state not in ('held', 'reconciliation')
     or v_booking.captured_amount <> 0
     or v_booking.refunded_amount <> 0 then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_PAYMENT_NOT_CAPTURABLE');
  end if;

  if v_case.operation_id is not null then
    select * into v_operation
      from public.booking_operations where id = v_case.operation_id;
    if v_operation.state <> 'needs_reconciliation' then
      return jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_RECONCILING');
    end if;
  end if;
  select * into v_reservation
    from public.wallet_reservations
   where id = (v_contract->>'reservationId')::uuid;
  if not found
     or v_reservation.state not in ('active', 'reconciliation')
     or v_reservation.booking_id is distinct from p_booking_id
     or v_reservation.amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'PROTECTED_HOLD_REQUIRED');
  end if;
  select * into v_account
    from public.wallet_accounts
   where id = v_reservation.wallet_account_id;
  if not found
     or v_account.id is distinct from (v_contract->>'walletAccountId')::uuid
     or v_account.currency <> v_reservation.currency
     or v_booking.currency <> v_reservation.currency
     or (v_booking.payment_amount is not null
       and v_booking.payment_amount <> v_reservation.amount)
     or (v_booking.charged_wallet_account_id is not null
       and v_booking.charged_wallet_account_id <> v_account.id) then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_IDENTITY_MISMATCH');
  end if;
  if v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'HOLD_BALANCE_MISMATCH');
  end if;

  select observation.* into v_evidence
    from jsonb_array_elements_text(
      v_case.proposal->'evidenceObservationIds'
    ) evidence_id(id)
    join public.booking_reconciliation_observations observation
      on observation.id = evidence_id.id::uuid
     and observation.reconciliation_case_id = v_case.id
   where observation.normalized_facts->>'requestedPurpose' = 'ticketed'
     and observation.normalized_facts #>> '{validation,authoritativeFor}' = 'ticketed'
     and coalesce((observation.normalized_facts
       #>> '{validation,valid}')::boolean, false)
     and coalesce((observation.normalized_facts
       #>> '{validation,complete}')::boolean, false)
     and coalesce((observation.normalized_facts
       #>> '{validation,fresh}')::boolean, false)
     and coalesce((observation.normalized_facts
       #>> '{validation,identityMatches}')::boolean, false)
     and observation.normalized_facts
       #>> '{evidence,airTicketing,source}' = 'air-ticketing-details'
   order by observation.observed_at desc, observation.id desc
   limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'AUTHORITATIVE_TICKET_EVIDENCE_REQUIRED');
  end if;

  -- Do not trust the validation summary alone for a financial resolution.
  -- The locked booking's supplier reference is the authority for the exact
  -- Triplover transaction identity, and manual TakeOff evidence must echo it.
  v_expected_supplier_unique_trans_id := v_booking.supplier_refs->>'uniqueTransId';
  if v_expected_supplier_unique_trans_id is null
     or v_expected_supplier_unique_trans_id = ''
     or v_expected_supplier_unique_trans_id <> btrim(v_expected_supplier_unique_trans_id) then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_REQUIRED');
  end if;
  v_ticketed_profile := coalesce(
    nullif(btrim(v_evidence.normalized_facts
      #>> '{validation,ticketedProfile}'), ''),
    'generic'
  );
  if v_ticketed_profile not in ('generic', 'takeoff_manual_ticket') then
    return jsonb_build_object('ok', false, 'code', 'UNSUPPORTED_TICKET_EVIDENCE_PROFILE');
  end if;
  v_is_takeoff_manual_ticket := v_ticketed_profile = 'takeoff_manual_ticket';

  -- PNR echoes are response-origin supplier facts. They are optional because
  -- Triplover may omit them, but if present every value must bind exactly to
  -- the locked booking transaction. This deliberately does not consult the
  -- PNR request identity or synthesize a value from local data.
  v_pnr_supplier_unique_trans_ids := v_evidence.normalized_facts
    #> '{evidence,pnr,facts,supplierEchoedUniqueTransIds}';
  if v_pnr_supplier_unique_trans_ids is not null
     and v_pnr_supplier_unique_trans_ids <> 'null'::jsonb then
    if jsonb_typeof(v_pnr_supplier_unique_trans_ids) <> 'array'
       or exists (
         select 1
           from jsonb_array_elements(v_pnr_supplier_unique_trans_ids) echo(value)
          where jsonb_typeof(echo.value) <> 'string'
             or nullif(btrim(echo.value #>> '{}'), '') is null
       ) then
      return jsonb_build_object('ok', false, 'code', 'PNR_SUPPLIER_UNIQUE_TRANS_ID_INVALID');
    end if;
    for v_pnr_supplier_unique_trans_id in
      select echo.value #>> '{}'
        from jsonb_array_elements(v_pnr_supplier_unique_trans_ids) echo(value)
    loop
      if v_pnr_supplier_unique_trans_id <> v_expected_supplier_unique_trans_id then
        return jsonb_build_object('ok', false, 'code', 'PNR_SUPPLIER_UNIQUE_TRANS_ID_MISMATCH');
      end if;
    end loop;
  end if;

  v_supplier_unique_trans_id := v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,ticketInfoUniqueTransId}';
  if v_supplier_unique_trans_id = ''
     or v_supplier_unique_trans_id <> btrim(v_supplier_unique_trans_id) then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_MISMATCH');
  end if;
  if v_supplier_unique_trans_id is not null
     and v_supplier_unique_trans_id <> v_expected_supplier_unique_trans_id then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_MISMATCH');
  end if;
  v_supplier_internal_booking_id_text := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,supplierBookingId}'), '');

  v_ticket_code_ref := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,ticketCodeRef}'), '');
  v_ticket_numbers := v_evidence.normalized_facts
    #> '{evidence,airTicketing,facts,ticketNumbers}';
  if jsonb_typeof(v_ticket_numbers) <> 'array'
     or jsonb_array_length(v_ticket_numbers) = 0
     or exists (
       select 1 from jsonb_array_elements(v_ticket_numbers) ticket(value)
        where jsonb_typeof(ticket.value) <> 'string'
           or nullif(btrim(ticket.value #>> '{}'), '') is null
     ) then
    return jsonb_build_object('ok', false, 'code', 'TICKET_EVIDENCE_INCOMPLETE');
  end if;
  v_supplier_pnr := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,pnr}'), '');
  v_airlines_pnr := v_evidence.normalized_facts
    #> '{evidence,airTicketing,facts,airlinesPnr}';
  v_supplier_status := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,airTicketing,facts,supplierStatus}'), '');
  begin
    v_issued_at := nullif(v_evidence.normalized_facts
      #>> '{evidence,airTicketing,facts,issuedAt}', '')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ISSUED_TIMESTAMP');
  end;

  if v_is_takeoff_manual_ticket then
    if v_booking.supplier_account is distinct from 'takeoff' then
      return jsonb_build_object('ok', false, 'code', 'MANUAL_TICKET_PROFILE_SUPPLIER_MISMATCH');
    end if;
    if v_supplier_unique_trans_id is null then
      return jsonb_build_object('ok', false, 'code', 'SUPPLIER_UNIQUE_TRANS_ID_REQUIRED');
    end if;
    if jsonb_typeof(v_evidence.normalized_facts
         #> '{evidence,airTicketing,facts,supplierBookingId}') <> 'number'
       or v_supplier_internal_booking_id_text is null
       or v_supplier_internal_booking_id_text !~ '^[1-9][0-9]{0,18}$' then
      return jsonb_build_object('ok', false, 'code', 'SUPPLIER_INTERNAL_BOOKING_ID_REQUIRED');
    end if;
    begin
      v_supplier_internal_booking_id := v_supplier_internal_booking_id_text::bigint;
    exception when numeric_value_out_of_range then
      return jsonb_build_object('ok', false, 'code', 'SUPPLIER_INTERNAL_BOOKING_ID_REQUIRED');
    end;
    if v_issued_at is null then
      return jsonb_build_object('ok', false, 'code', 'ISSUED_TIMESTAMP_REQUIRED');
    end if;
  elsif v_ticket_code_ref is null then
    -- Preserve the generic ticketed path unchanged: a ticket code remains
    -- mandatory unless the explicit TakeOff manual evidence profile applies.
    return jsonb_build_object('ok', false, 'code', 'TICKET_EVIDENCE_INCOMPLETE');
  end if;

  v_issued_at := coalesce(v_issued_at, v_evidence.observed_at);
  if v_issued_at > v_evidence.observed_at + interval '1 minute' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ISSUED_TIMESTAMP');
  end if;
  v_supplier_identifiers := jsonb_build_object(
    'ticketedProfile', v_ticketed_profile,
    'supplierAccount', v_booking.supplier_account,
    'supplierUniqueTransId', v_supplier_unique_trans_id,
    'expectedSupplierUniqueTransId', v_expected_supplier_unique_trans_id,
    'supplierInternalBookingId', v_supplier_internal_booking_id,
    'pnrSupplierEchoedUniqueTransIds', coalesce(
      v_pnr_supplier_unique_trans_ids,
      '[]'::jsonb
    )
  );

  if exists (
    select 1 from public.wallet_ledger_entries ledger
     where ledger.idempotency_key = p_execution_request_key || ':capture'
  ) then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_IDEMPOTENCY_CONFLICT');
  end if;
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts
     set hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;
  update public.wallet_reservations
     set booking_id = p_booking_id,
         booking_attempt_id = null,
         state = 'captured',
         issued_by_user_id = p_actor_user_id,
         captured_at = clock_timestamp(),
         reconciliation_at = null,
         reconciliation_reason = null
   where id = v_reservation.id;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks, metadata
  ) values (
    v_account.id, 'booking_confirm', v_reservation.amount,
    v_reservation.currency, v_available_before, v_available_before,
    v_hold_before, v_hold_before - v_reservation.amount,
    v_booking.id, v_booking.public_ref, v_reservation.id,
    p_execution_request_key || ':capture', p_actor_user_id,
    v_contract->>'actorRole',
    'Approved ticketing reconciliation capture',
    jsonb_build_object(
      'reconciliationCaseId', v_case.id,
      'proposalHash', v_case.proposal_hash,
      'operationId', v_case.operation_id,
      'evidenceObservationId', v_evidence.id,
      'resolutionKind', 'ticketed',
      'supplierIdentifiers', v_supplier_identifiers
    )
  ) returning id into v_ledger_entry_id;

  v_from_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  update public.flight_bookings
     set status = 'confirmed',
         charged_wallet_account_id = v_account.id,
         payment_state = 'captured',
         payment_amount = v_reservation.amount,
         captured_amount = v_reservation.amount,
         refunded_amount = 0,
         issued_by_user_id = p_actor_user_id,
         issued_at = coalesce(issued_at, v_issued_at),
         pnr = case when v_is_takeoff_manual_ticket then v_booking.pnr
           else coalesce(v_supplier_pnr, pnr) end,
         airlines_pnr = case
           when v_is_takeoff_manual_ticket then v_booking.airlines_pnr
           when jsonb_typeof(v_airlines_pnr) = 'array'
             and jsonb_array_length(v_airlines_pnr) > 0
             then v_airlines_pnr else airlines_pnr end,
         -- These are intentionally exact locked values, not a supplier-write
         -- path. The reconciliation keeps the original reference chain and
         -- deadline while storing the supplier's additional IDs in audit data.
         supplier_refs = v_booking.supplier_refs,
         ticketing_deadline_at = v_booking.ticketing_deadline_at,
         booking_status = coalesce(v_supplier_status, 'Confirmed'),
         ticket_code_ref = case when v_is_takeoff_manual_ticket
           then ticket_code_ref else v_ticket_code_ref end,
         ticket_numbers = v_ticket_numbers,
         active_operation_id = null,
         operation_kind = null,
         operation_reason = null,
         operation_request_id = null,
         operation_actor_user_id = null,
         operation_started_at = null,
         operation_prior_status = null
   where id = v_booking.id;
  if v_case.operation_id is not null then
    update public.booking_operations
       set state = 'succeeded',
           completed_at = clock_timestamp(),
           error_code = null,
           error_message = null,
           supplier_evidence = coalesce(supplier_evidence, '{}'::jsonb)
             || jsonb_build_object(
               'reconciliationResolution', jsonb_build_object(
                 'caseId', v_case.id,
                 'outcome', 'ticketed',
                 'evidenceObservationId', v_evidence.id,
                 'supplierIdentifiers', v_supplier_identifiers
               )
             )
     where id = v_case.operation_id;
  end if;

  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'confirmed';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle, 'confirmed',
    v_booking.status, 'confirmed', v_booking.operation_kind,
    v_booking.operation_reason, p_actor_user_id, 'ReconciliationTicketed',
    jsonb_build_object(
      'evidenceObservationId', v_evidence.id,
      'ticketCodeRefPresent', v_ticket_code_ref is not null,
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'supplierIdentifiers', v_supplier_identifiers
    ),
    p_execution_request_key || ':confirmed', v_case.operation_id,
    v_case.id, v_occurrence_number, v_issued_at, clock_timestamp(),
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'confirmed',
      'paymentState', 'captured',
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'operationKind', coalesce(v_booking.operation_kind, 'reconciliation'),
      'reconciliationCaseId', v_case.id,
      'supplierIdentifiers', v_supplier_identifiers
    ), 1
  ) returning id into v_event_id;

  v_resolution_result := jsonb_build_object(
    'bookingStatus', 'confirmed',
    'paymentState', 'captured',
    'reservationId', v_reservation.id,
    'walletAccountId', v_account.id,
    'ledgerEntryId', v_ledger_entry_id,
    'lifecycleEventId', v_event_id,
    'capturedAmount', v_reservation.amount,
    'currency', v_reservation.currency,
    'availableBalance', v_available_before,
    'holdBalance', v_hold_before - v_reservation.amount,
    'supplierUniqueTransId', v_supplier_unique_trans_id,
    'supplierInternalBookingId', v_supplier_internal_booking_id,
    'pnrSupplierEchoedUniqueTransIds', coalesce(
      v_pnr_supplier_unique_trans_ids,
      '[]'::jsonb
    ),
    'supplierIdentifiers', v_supplier_identifiers
  );
  update public.booking_reconciliation_cases
     set state = 'resolved',
         resolution_outcome = 'ticketed',
         resolution = jsonb_build_object(
           'version', 1,
           'executionRequestKey', p_execution_request_key,
           'proposalHash', v_case.proposal_hash,
           'resolutionKind', 'ticketed',
           'executedByRole', v_contract->>'actorRole',
           'evidenceObservationIds', v_case.proposal->'evidenceObservationIds',
           'supplierIdentifiers', v_supplier_identifiers,
           'result', v_resolution_result
         ),
         resolution_reason = v_case.proposal->>'reason',
         resolved_by_user_id = p_actor_user_id,
         resolved_at = clock_timestamp(),
         closed_at = clock_timestamp(),
         version = version + 1
   where id = v_case.id;

  return v_resolution_result || jsonb_build_object(
    'ok', true,
    'replay', false,
    'caseId', v_case.id,
    'caseVersion', v_case.version + 1,
    'resolutionKind', 'ticketed'
  );
end;
$$;

revoke all on function public.resolve_booking_reconciliation_ticketed_v1(
  uuid, uuid, integer, text, text, text
) from public, anon, authenticated;
grant execute on function public.resolve_booking_reconciliation_ticketed_v1(
  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.resolve_booking_reconciliation_ticketed_v1(
  uuid, uuid, integer, text, text, text
) is
  'Atomically captures the already protected hold and confirms a booking only from approved fresh immutable ticket evidence. Generic evidence requires ticketCodeRef; the narrow TakeOff manual-ticket profile additionally requires exact echoed uniqueTransId and a positive numeric supplier bookingId, which are preserved in resolution, operation, ledger, and lifecycle-event metadata. Any supplier-returned PNR uniqueTransID echo is also compared byte-for-byte and retained in that metadata.';


-- SOURCE: 0095_booking_reconciliation_stale_approved_proposal_supersession.sql
-- Forward-only recovery for an approved reconciliation proposal whose
-- proposal-bound evidence expired before execution.
--
-- This deliberately does not amend an approved proposal. The source case keeps
-- its proposal, maker/checker approval, evidence IDs, and reason unchanged;
-- it is marked terminally superseded and a separate successor case starts an
-- entirely new evidence/proposal/approval cycle.

alter table public.booking_reconciliation_cases
  drop constraint if exists booking_reconciliation_cases_state_check;

alter table public.booking_reconciliation_cases
  add constraint booking_reconciliation_cases_state_check
  check (state in (
    'open',
    'assigned',
    'awaiting_supplier',
    'awaiting_finance',
    'awaiting_approval',
    'resolved',
    'closed_no_change',
    'superseded'
  ));

alter table public.booking_reconciliation_cases
  add column if not exists superseded_at timestamptz,
  add column if not exists superseded_by_user_id text,
  add column if not exists superseded_by_role text,
  add column if not exists supersede_reason text,
  add column if not exists superseded_by_case_id uuid,
  add column if not exists supersedes_case_id uuid;

alter table public.booking_reconciliation_cases
  add constraint booking_reconciliation_cases_superseded_by_case_fk
  foreign key (superseded_by_case_id)
  references public.booking_reconciliation_cases (id)
  on delete restrict
  not valid,
  add constraint booking_reconciliation_cases_supersedes_case_fk
  foreign key (supersedes_case_id)
  references public.booking_reconciliation_cases (id)
  on delete restrict
  not valid,
  add constraint booking_reconciliation_cases_superseded_shape_v1_check
  check (
    (
      state = 'superseded'
      and superseded_at is not null
      and nullif(btrim(superseded_by_user_id), '') is not null
      and nullif(btrim(superseded_by_role), '') is not null
      and nullif(btrim(supersede_reason), '') is not null
      and resolved_at is null
    )
    or (
      state <> 'superseded'
      and superseded_at is null
      and superseded_by_user_id is null
      and superseded_by_role is null
      and supersede_reason is null
      and superseded_by_case_id is null
    )
  ) not valid;

create unique index if not exists
  booking_reconciliation_cases_superseded_by_case_unique_idx
  on public.booking_reconciliation_cases (superseded_by_case_id)
  where superseded_by_case_id is not null;

create unique index if not exists
  booking_reconciliation_cases_supersedes_case_unique_idx
  on public.booking_reconciliation_cases (supersedes_case_id)
  where supersedes_case_id is not null;

create table if not exists public.booking_reconciliation_proposal_supersessions (
  id uuid primary key default gen_random_uuid(),
  source_case_id uuid not null references public.booking_reconciliation_cases (id)
    on delete restrict,
  successor_case_id uuid not null references public.booking_reconciliation_cases (id)
    on delete restrict,
  superseded_proposal_hash text not null check (superseded_proposal_hash ~ '^[a-f0-9]{64}$'),
  superseded_proposal jsonb not null check (jsonb_typeof(superseded_proposal) = 'object'),
  superseded_proposed_by_user_id text not null,
  superseded_proposed_at timestamptz not null,
  superseded_approved_by_user_id text not null,
  superseded_approved_at timestamptz not null,
  superseded_evidence_observation_ids jsonb not null
    check (jsonb_typeof(superseded_evidence_observation_ids) = 'array'),
  superseded_by_user_id text not null,
  superseded_by_role text not null,
  superseded_at timestamptz not null default clock_timestamp(),
  supersede_request_key text not null,
  supersede_reason text not null,
  constraint booking_reconciliation_proposal_supersessions_distinct_cases_check
    check (source_case_id <> successor_case_id),
  constraint booking_reconciliation_proposal_supersessions_maker_checker_check
    check (superseded_proposed_by_user_id <> superseded_approved_by_user_id),
  constraint booking_reconciliation_proposal_supersessions_reason_check
    check (nullif(btrim(supersede_reason), '') is not null),
  constraint booking_reconciliation_proposal_supersessions_request_key_check
    check (nullif(btrim(supersede_request_key), '') is not null
      and char_length(supersede_request_key) <= 220),
  unique (source_case_id, superseded_proposal_hash),
  unique (source_case_id, supersede_request_key)
);

create or replace function public.deny_booking_reconciliation_proposal_supersession_mutation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'booking reconciliation proposal supersessions are immutable'
    using errcode = '55000';
end;
$$;

drop trigger if exists booking_reconciliation_proposal_supersessions_deny_mutation_v1
  on public.booking_reconciliation_proposal_supersessions;
create trigger booking_reconciliation_proposal_supersessions_deny_mutation_v1
  before update or delete on public.booking_reconciliation_proposal_supersessions
  for each row execute function public.deny_booking_reconciliation_proposal_supersession_mutation_v1();

create or replace function public.supersede_stale_approved_booking_reconciliation_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_request_key text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_case_operation_id uuid;
  v_existing public.booking_reconciliation_proposal_supersessions;
  v_successor_case_id uuid;
  v_supersession_id uuid;
  v_successor_case_version integer;
  v_source_case_version integer;
  v_evidence_ids uuid[];
  v_evidence_input_count integer;
  v_evidence_found_count integer;
  v_stale_evidence_count integer;
  v_cutoff timestamptz := clock_timestamp() - interval '5 minutes';
begin
  if p_booking_id is null
     or p_case_id is null
     or p_expected_case_version is null
     or p_expected_case_version < 1
     or p_proposal_hash is null
     or p_proposal_hash !~ '^[a-f0-9]{64}$'
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 220
     or nullif(btrim(p_reason), '') is null
     or char_length(p_reason) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_PROPOSAL_SUPERSESSION');
  end if;

  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if coalesce(v_actor_role, '') <> 'superadmin' then
    return jsonb_build_object('ok', false, 'code', 'SUPERSESSION_FORBIDDEN');
  end if;

  -- Preserve the global reconciliation lock order: booking -> operation -> case.
  select reconciliation_case.operation_id into v_case_operation_id
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND');
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  if v_case_operation_id is not null then
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_case_operation_id
       and operation.booking_id = p_booking_id
     for update;
  end if;

  select reconciliation_case.* into v_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.id = p_case_id
     and reconciliation_case.subject_booking_id = p_booking_id
   for update;
  if not found or v_case.operation_id is distinct from v_case_operation_id then
    return jsonb_build_object('ok', false, 'code', 'CASE_OPERATION_CHANGED');
  end if;

  select supersession.* into v_existing
    from public.booking_reconciliation_proposal_supersessions supersession
   where supersession.source_case_id = p_case_id
     and supersession.supersede_request_key = p_request_key;
  if found then
    if v_existing.superseded_proposal_hash = p_proposal_hash
       and v_existing.superseded_by_user_id = p_actor_user_id
       and v_existing.supersede_reason = p_reason then
      return jsonb_build_object(
        'ok', true,
        'replay', true,
        'caseId', p_case_id,
        'caseVersion', v_case.version,
        'proposalHash', p_proposal_hash,
        'supersessionId', v_existing.id,
        'successorCaseId', v_existing.successor_case_id,
        'requiresFreshEvidence', true,
        'bookingMutation', false,
        'walletMutation', false,
        'reservationMutation', false,
        'ledgerMutation', false,
        'supplierWrite', false
      );
    end if;
    raise exception 'proposal supersession request identity mismatch' using errcode = '22023';
  end if;

  -- Replay is intentionally checked before mutable booking/operation state so
  -- a safely completed request can be returned idempotently even after the
  -- successor review later completes the original operation.
  if v_booking.status <> 'in-progress'
     or v_booking.payment_state <> 'reconciliation'
     or v_booking.captured_amount <> 0
     or v_booking.refunded_amount <> 0
     or v_booking.active_operation_id is distinct from v_case_operation_id then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_STALE_CAPTURE_RECONCILIATION');
  end if;
  if v_case_operation_id is null
     or v_operation.id is null
     or v_operation.state <> 'needs_reconciliation' then
    return jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_RECONCILING');
  end if;
  if v_case.state = 'superseded' then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_ALREADY_SUPERSEDED');
  end if;
  if v_case.state <> 'awaiting_approval'
     or v_case.resolved_at is not null
     or v_case.rejected_at is not null
     or v_case.proposal_hash is null
     or v_case.proposal_hash <> p_proposal_hash
     or v_case.approved_by_user_id is null
     or v_case.approved_at is null
     or v_case.proposed_by_user_id is null
     or v_case.proposed_at is null then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_PROPOSAL_REQUIRED');
  end if;
  if v_case.version <> p_expected_case_version then
    return jsonb_build_object(
      'ok', false,
      'code', 'CASE_VERSION_CONFLICT',
      'caseVersion', v_case.version
    );
  end if;
  if v_case.proposed_outcome is distinct from 'ticketed'
     or v_case.financial_disposition is distinct from 'capture_existing_hold'
     or coalesce((v_case.proposal->>'makerCheckerRequired')::boolean, false) is not true
     or v_case.approved_by_user_id = v_case.proposed_by_user_id then
    return jsonb_build_object('ok', false, 'code', 'STALE_TICKETED_CAPTURE_PROPOSAL_REQUIRED');
  end if;
  if jsonb_typeof(v_case.proposal->'evidenceObservationIds') <> 'array'
     or jsonb_array_length(v_case.proposal->'evidenceObservationIds') = 0 then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_EVIDENCE_REQUIRED');
  end if;

  select count(*) into v_evidence_input_count
    from jsonb_array_elements_text(v_case.proposal->'evidenceObservationIds') evidence(id);
  if exists (
    select 1
      from jsonb_array_elements_text(v_case.proposal->'evidenceObservationIds') evidence(id)
     where evidence.id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_EVIDENCE_INVALID');
  end if;
  select array_agg(evidence.id::uuid order by evidence.id)
    into v_evidence_ids
    from jsonb_array_elements_text(v_case.proposal->'evidenceObservationIds') evidence(id);
  if coalesce(cardinality(v_evidence_ids), 0) <> v_evidence_input_count
     or (select count(distinct evidence.id)
           from unnest(v_evidence_ids) as evidence(id))
        <> v_evidence_input_count then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_EVIDENCE_INVALID');
  end if;
  select count(*), count(*) filter (where observation.observed_at < v_cutoff)
    into v_evidence_found_count, v_stale_evidence_count
    from public.booking_reconciliation_observations observation
   where observation.reconciliation_case_id = p_case_id
     and observation.id = any(v_evidence_ids);
  if v_evidence_found_count <> v_evidence_input_count then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_CASE_MISMATCH');
  end if;
  -- Require every proposal-bound observation to have expired. This is stricter
  -- than merely noticing a stale latest observation and mirrors the resolver's
  -- all-bound-evidence freshness requirement.
  if v_stale_evidence_count <> v_evidence_input_count then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_EVIDENCE_NOT_EXPIRED');
  end if;

  -- Mark the source terminal before inserting its successor so the existing
  -- one-open-case-per-booking/type index remains true throughout this
  -- transaction. The successor pointer is attached immediately afterward;
  -- neither intermediate state is externally observable before commit.
  update public.booking_reconciliation_cases
     set state = 'superseded',
         superseded_at = clock_timestamp(),
         superseded_by_user_id = p_actor_user_id,
         superseded_by_role = v_actor_role,
         supersede_reason = p_reason,
         version = version + 1
   where id = v_case.id
   returning version into v_source_case_version;

  insert into public.booking_reconciliation_cases (
    subject_booking_id,
    operation_id,
    case_type,
    state,
    reason_code,
    reason_detail,
    opened_source,
    opened_by_user_id,
    opened_by_role,
    policy_version,
    assigned_team,
    severity,
    priority,
    due_at,
    supersedes_case_id
  ) values (
    v_case.subject_booking_id,
    v_case.operation_id,
    v_case.case_type,
    'awaiting_supplier',
    'stale_approved_proposal_superseded',
    'A prior approved ticketed-capture proposal expired before execution. New supplier evidence and a new maker/checker review are required.',
    'staff',
    p_actor_user_id,
    v_actor_role,
    v_case.policy_version,
    v_case.assigned_team,
    v_case.severity,
    v_case.priority,
    v_case.due_at,
    v_case.id
  ) returning id, version into v_successor_case_id, v_successor_case_version;

  insert into public.booking_reconciliation_proposal_supersessions (
    source_case_id,
    successor_case_id,
    superseded_proposal_hash,
    superseded_proposal,
    superseded_proposed_by_user_id,
    superseded_proposed_at,
    superseded_approved_by_user_id,
    superseded_approved_at,
    superseded_evidence_observation_ids,
    superseded_by_user_id,
    superseded_by_role,
    supersede_request_key,
    supersede_reason
  ) values (
    v_case.id,
    v_successor_case_id,
    v_case.proposal_hash,
    v_case.proposal,
    v_case.proposed_by_user_id,
    v_case.proposed_at,
    v_case.approved_by_user_id,
    v_case.approved_at,
    v_case.proposal->'evidenceObservationIds',
    p_actor_user_id,
    v_actor_role,
    p_request_key,
    p_reason
  ) returning id into v_supersession_id;

  update public.booking_reconciliation_cases
     set superseded_by_case_id = v_successor_case_id
   where id = v_case.id;

  -- This immutable, PII-minimized event deliberately records identifiers and
  -- hashes only. The exact prior proposal/reason remains in the immutable
  -- supersession snapshot, not copied into security audit metadata.
  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id, outcome, metadata
  ) values (
    p_actor_user_id,
    v_actor_role,
    'booking.reconciliation.proposal_superseded',
    'flight_booking',
    p_booking_id::text,
    'succeeded',
    jsonb_build_object(
      'caseId', v_case.id,
      'successorCaseId', v_successor_case_id,
      'supersessionId', v_supersession_id,
      'supersededProposalHash', v_case.proposal_hash,
      'priorProposedByUserId', v_case.proposed_by_user_id,
      'priorProposedAt', v_case.proposed_at,
      'priorApprovedByUserId', v_case.approved_by_user_id,
      'priorApprovedAt', v_case.approved_at,
      'proposalEvidenceObservationIds', to_jsonb(v_evidence_ids),
      'priorReasonRecorded', coalesce(nullif(v_case.proposal->>'reason', ''), '') <> '',
      'supersedeReasonRecorded', true,
      'supersedeReasonHash', encode(sha256(convert_to(p_reason, 'UTF8')), 'hex'),
      'sourceCaseState', 'superseded',
      'successorCaseState', 'awaiting_supplier',
      'proposalBodyStored', false,
      'bookingMutation', false,
      'walletMutation', false,
      'reservationMutation', false,
      'ledgerMutation', false,
      'supplierWrite', false
    )
  );

  return jsonb_build_object(
    'ok', true,
    'replay', false,
    'caseId', v_case.id,
    'caseVersion', v_source_case_version,
    'proposalHash', v_case.proposal_hash,
    'supersessionId', v_supersession_id,
    'successorCaseId', v_successor_case_id,
    'successorCaseVersion', v_successor_case_version,
    'requiresFreshEvidence', true,
    'bookingMutation', false,
    'walletMutation', false,
    'reservationMutation', false,
    'ledgerMutation', false,
    'supplierWrite', false
  );
end;
$$;

revoke all on table public.booking_reconciliation_proposal_supersessions
  from public, anon, authenticated;
revoke all on function public.deny_booking_reconciliation_proposal_supersession_mutation_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.supersede_stale_approved_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text, text
) from public, anon, authenticated;
grant execute on function public.supersede_stale_approved_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text, text
) to service_role;

comment on table public.booking_reconciliation_proposal_supersessions is
  'Immutable, case-bound snapshots of approved stale reconciliation proposals superseded before financial execution.';
comment on function public.supersede_stale_approved_booking_reconciliation_v1(
  uuid, uuid, integer, text, text, text, text
) is
  'Super Admin-only, audited, no-money recovery for an approved ticketed-capture proposal whose every proposal-bound evidence observation has expired. It preserves the source case and opens an empty-evidence successor case.';


-- SOURCE: 0096_booking_reconciliation_superseded_terminal_compatibility.sql
-- Treat the 0095 archival `superseded` state as terminal in the small number
-- of legacy functions that previously used a resolved/closed deny-list.
--
-- These forward redefinitions are deliberately source-guarded: each block
-- obtains the already-deployed function definition, verifies the exact known
-- predicate/anchor count, changes only that terminal-state handling, and then
-- re-creates the same function. If an unexpected function revision is live,
-- the migration fails before making a partial change. No function body runs
-- while this migration is applied, and no booking, supplier, wallet,
-- reservation, ledger, or case data is changed by this migration.

-- Shared resolution contracts must reject a superseded source before locking a
-- protected reservation or wallet. All exact outcome resolvers inherit this.
do $$
declare
  v_definition text;
  v_anchor text := $anchor$  if v_case.state in ('resolved', 'closed_no_change')
     or v_case.resolved_at is not null then$anchor$;
  v_guard text := $guard$  if v_case.state = 'superseded' then
    return jsonb_build_object(
      'ok', false,
      'code', 'PROPOSAL_SUPERSEDED',
      'caseId', v_case.id,
      'successorCaseId', v_case.superseded_by_case_id
    );
  end if;

$guard$;
begin
  select pg_get_functiondef(
    'public.booking_reconciliation_resolution_contract_v1(uuid,uuid,integer,text,text,text,text)'::regprocedure
  ) into v_definition;
  if v_definition is null
     or (length(v_definition) - length(replace(v_definition, v_anchor, '')))
        / nullif(length(v_anchor), 0) <> 1 then
    raise exception 'unexpected booking reconciliation resolution contract; refusing superseded compatibility rewrite'
      using errcode = '55000';
  end if;
  execute replace(v_definition, v_anchor, v_guard || v_anchor);
end;
$$;

-- A historic checker approval must not replay successfully after its proposal
-- has been superseded. The successor always requires a new independent
-- approval.
do $$
declare
  v_definition text;
  v_anchor text := $anchor$  if v_case.approved_at is not null then$anchor$;
  v_guard text := $guard$  if v_case.state = 'superseded' then
    return jsonb_build_object(
      'ok', false,
      'code', 'PROPOSAL_SUPERSEDED',
      'caseId', v_case.id,
      'successorCaseId', v_case.superseded_by_case_id
    );
  end if;
$guard$;
begin
  select pg_get_functiondef(
    'public.approve_booking_reconciliation_v1(uuid,uuid,integer,text,text)'::regprocedure
  ) into v_definition;
  if v_definition is null
     or (length(v_definition) - length(replace(v_definition, v_anchor, '')))
        / nullif(length(v_anchor), 0) <> 1 then
    raise exception 'unexpected reconciliation approval contract; refusing superseded compatibility rewrite'
      using errcode = '55000';
  end if;
  execute replace(v_definition, v_anchor, v_guard || v_anchor);
end;
$$;

-- Generic release remains unavailable while a real open case exists, but must
-- ignore a terminal superseded source after its successor is resolved.
do $$
declare
  v_definition text;
  v_find text := $find$       and reconciliation_case.state not in ('resolved', 'closed_no_change')$find$;
  v_replace text := $replace$       and reconciliation_case.state in (
         'open', 'assigned', 'awaiting_supplier', 'awaiting_finance', 'awaiting_approval'
       )$replace$;
begin
  select pg_get_functiondef(
    'public.wallet_release_reservation(uuid,uuid,text,text,text,text)'::regprocedure
  ) into v_definition;
  if v_definition is null
     or (length(v_definition) - length(replace(v_definition, v_find, '')))
        / nullif(length(v_find), 0) <> 2 then
    raise exception 'unexpected wallet release guard; refusing superseded compatibility rewrite'
      using errcode = '55000';
  end if;
  execute replace(v_definition, v_find, v_replace);
end;
$$;

-- The ordinary captured-booking refund path likewise ignores only terminal
-- source history; it still blocks on any active successor case.
do $$
declare
  v_definition text;
  v_find text := $find$     and reconciliation_case.state not in ('resolved', 'closed_no_change')$find$;
  v_replace text := $replace$     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier', 'awaiting_finance', 'awaiting_approval'
     )$replace$;
begin
  select pg_get_functiondef(
    'public.wallet_refund_booking(uuid,bigint,text,text,text,text)'::regprocedure
  ) into v_definition;
  if v_definition is null
     or (length(v_definition) - length(replace(v_definition, v_find, '')))
        / nullif(length(v_find), 0) <> 1 then
    raise exception 'unexpected wallet refund guard; refusing superseded compatibility rewrite'
      using errcode = '55000';
  end if;
  execute replace(v_definition, v_find, v_replace);
end;
$$;

-- The live 0086 owner-confirm function must not treat a superseded historic
-- case as an active imported/manual case.
do $$
declare
  v_definition text;
  v_find text := $find$state not in ('resolved','closed_no_change')$find$;
  v_replace text := $replace$state in ('open','assigned','awaiting_supplier','awaiting_finance','awaiting_approval')$replace$;
begin
  select pg_get_functiondef(
    'public.wallet_confirm_impexp_booking(uuid,text,text)'::regprocedure
  ) into v_definition;
  if v_definition is null
     or (length(v_definition) - length(replace(v_definition, v_find, '')))
        / nullif(length(v_find), 0) <> 1 then
    raise exception 'unexpected imported/manual confirmation guard; refusing superseded compatibility rewrite'
      using errcode = '55000';
  end if;
  execute replace(v_definition, v_find, v_replace);
end;
$$;

-- The live 0086 manual-status function uses the same open-case selection.
-- It additionally fails closed when no active case exists, rather than ever
-- proceeding with a null case record after ignoring a terminal source.
do $$
declare
  v_definition text;
  v_find text := $find$state not in ('resolved','closed_no_change')$find$;
  v_replace text := $replace$state in ('open','assigned','awaiting_supplier','awaiting_finance','awaiting_approval')$replace$;
  v_anchor text := $anchor$      select * into v_reservation from public.wallet_reservations where booking_id=v_booking.id for update;
      if v_booking.payment_state<>'captured'$anchor$;
  v_guarded_anchor text := $guard$      select * into v_reservation from public.wallet_reservations where booking_id=v_booking.id for update;
      if v_case.id is null then
        return jsonb_build_object('ok',false,'code','MANUAL_TICKETING_RECONCILIATION_REQUIRED');
      end if;
      if v_booking.payment_state<>'captured'$guard$;
begin
  select pg_get_functiondef(
    'public.update_manual_booking_status_v1(uuid,text,text,jsonb,text)'::regprocedure
  ) into v_definition;
  if v_definition is null
     or (length(v_definition) - length(replace(v_definition, v_find, '')))
        / nullif(length(v_find), 0) <> 1
     or (length(v_definition) - length(replace(v_definition, v_anchor, '')))
        / nullif(length(v_anchor), 0) <> 1 then
    raise exception 'unexpected manual status guard; refusing superseded compatibility rewrite'
      using errcode = '55000';
  end if;
  v_definition := replace(v_definition, v_find, v_replace);
  execute replace(v_definition, v_anchor, v_guarded_anchor);
end;
$$;

comment on function public.booking_reconciliation_resolution_contract_v1(
  uuid, uuid, integer, text, text, text, text
) is
  'Shared reconciliation contract. A superseded source proposal is terminal and must use its successor case; no reservation or wallet lock is taken for that rejected source.';


-- SOURCE: 0097_booking_dashboard_list_performance.sql
-- A deliberately narrow, list-only projection for the bookings dashboard.
-- It avoids transferring booking snapshots, passenger documents, raw supplier
-- references, and every historic lifecycle event just to render one table page.
create or replace view public.booking_dashboard_list_v
with (security_invoker = true)
as
select
  booking.id,
  booking.public_ref,
  booking.user_id,
  booking.agency_code,
  booking.status,
  booking.lifecycle_status,
  booking.operation_kind,
  booking.operation_reason,
  booking.operation_started_at,
  booking.created_at,
  booking.issued_at,
  booking.cancelled_at,
  booking.ticketing_deadline_at,
  latest_event.created_at as last_lifecycle_event_at,
  nullif(booking.supplier_refs ->> 'uniqueTransId', '') as supplier_reference,
  coalesce(
    (
      select string_agg(value, ', ')
      from jsonb_array_elements_text(
        case
          when jsonb_typeof(booking.airlines_pnr) = 'array'
            then booking.airlines_pnr
          else '[]'::jsonb
        end
      ) as value
    ),
    ''
  ) as airline_pnr,
  coalesce(booking.pnr, '') as pnr,
  nullif(
    concat_ws(
      ' ',
      booking.passengers #>> '{travellers,0,firstName}',
      booking.passengers #>> '{travellers,0,lastName}'
    ),
    ''
  ) as lead_name,
  jsonb_array_length(
    case
      when jsonb_typeof(booking.passengers -> 'travellers') = 'array'
        then booking.passengers -> 'travellers'
      else '[]'::jsonb
    end
  ) as traveller_count,
  booking.passenger_counts,
  coalesce(nullif(booking.pricing_snapshot ->> 'sellingPrice', '')::numeric, 0) as fare,
  nullif(booking.pricing_snapshot ->> 'grossPrice', '')::numeric as gross,
  coalesce(
    (
      select string_agg(
        concat_ws('-', leg ->> 'from', leg ->> 'to'),
        ', '
      )
      from jsonb_array_elements(
        case
          when jsonb_typeof(booking.itinerary -> 'legs') = 'array'
            then booking.itinerary -> 'legs'
          else '[]'::jsonb
        end
      ) as leg
    ),
    ''
  ) as route,
  coalesce(nullif(booking.itinerary ->> 'carrierCode', ''), '—') as airline,
  coalesce(
    nullif(booking.itinerary #>> '{legs,0,segments,0,departure}', ''),
    booking.travel_date::text
  ) as fly_date,
  nullif(booking.pricing_snapshot ->> 'supplierTotalPrice', '')::numeric
    as supplier_payable,
  coalesce(nullif(booking.pricing_snapshot ->> 'sellingPrice', '')::numeric, 0)
    - coalesce(
      nullif(booking.pricing_snapshot ->> 'supplierTotalPrice', '')::numeric,
      0
    ) as profit,
  coalesce(user_record.email, '') as booking_user_email,
  booking.import_source,
  booking.payment_state,
  case
    when booking.lifecycle_status = 'in-progress'
      then booking.operation_started_at
    when booking.lifecycle_status = 'confirmed'
      then booking.issued_at
    when booking.lifecycle_status = 'expired'
      then coalesce(booking.ticketing_deadline_at, latest_event.created_at)
    when booking.lifecycle_status = 'cancelled'
      then coalesce(booking.cancelled_at, latest_event.created_at)
    when booking.lifecycle_status = 'unconfirmed'
      then latest_event.created_at
    else null
  end as lifecycle_at,
  coalesce(
    nullif(
      concat_ws(
        ' ',
        booking.passengers #>> '{travellers,0,firstName}',
        booking.passengers #>> '{travellers,0,lastName}'
      ),
      ''
    ),
    ''
  ) as sort_name,
  lower(
    concat_ws(
      ' ',
      booking.public_ref,
      booking.pnr,
      coalesce(
        (
          select string_agg(value, ' ')
          from jsonb_array_elements_text(
            case
              when jsonb_typeof(booking.airlines_pnr) = 'array'
                then booking.airlines_pnr
              else '[]'::jsonb
            end
          ) as value
        ),
        ''
      ),
      booking.passengers #>> '{travellers,0,firstName}',
      booking.passengers #>> '{travellers,0,lastName}',
      user_record.email
    )
  ) as search_text,
  case
    when coalesce((booking.passenger_counts ->> 'ADT')::integer, 0) > 0
      then 'Adult ' || (booking.passenger_counts ->> 'ADT')
    else ''
  end || case
    when coalesce((booking.passenger_counts ->> 'CHD')::integer, 0)
      + coalesce((booking.passenger_counts ->> 'CNN')::integer, 0) > 0
      then ', Child ' || (
        coalesce((booking.passenger_counts ->> 'CHD')::integer, 0)
        + coalesce((booking.passenger_counts ->> 'CNN')::integer, 0)
      )
    else ''
  end || case
    when coalesce((booking.passenger_counts ->> 'INF')::integer, 0)
      + coalesce((booking.passenger_counts ->> 'INS')::integer, 0) > 0
      then ', Infant ' || (
        coalesce((booking.passenger_counts ->> 'INF')::integer, 0)
        + coalesce((booking.passenger_counts ->> 'INS')::integer, 0)
      )
    else ''
  end as passenger_type
from public.booking_lifecycle_v booking
left join lateral (
  select event.created_at
  from public.booking_status_events event
  where event.booking_id = booking.id
  order by event.created_at desc
  limit 1
) latest_event on true
left join public.app_users user_record
  on user_record.clerk_id = booking.user_id;

revoke all on table public.booking_dashboard_list_v
  from public, anon, authenticated;
grant select on table public.booking_dashboard_list_v to service_role;

-- The user and global paths are both ordered by newest booking. The existing
-- user index handles the former; this covers agencies without widening the
-- index to legacy operational records.
create index if not exists flight_bookings_agency_dashboard_created_idx
  on public.flight_bookings (agency_code, created_at desc)
  where not legacy_operational;

-- The lateral latest-event lookup above is intentionally one indexed row per
-- visible booking. Keep this explicit in case old environments predate 0031.
create index if not exists booking_status_events_booking_created_idx
  on public.booking_status_events (booking_id, created_at desc);

comment on view public.booking_dashboard_list_v is
  'Narrow, paginated dashboard projection with the latest lifecycle timestamp and creator email in one read.';


-- SOURCE: 0098_booking_dashboard_status_sort.sql
-- The dashboard's status column has a business order rather than an
-- alphabetical order. Keep it in a thin wrapper so the narrow list projection
-- remains reusable and PostgREST can order it before pagination.
create or replace view public.booking_dashboard_list_ordered_v
with (security_invoker = true)
as
select
  booking.*,
  case booking.lifecycle_status
    when 'on-hold' then 0
    when 'pending' then 1
    when 'in-progress' then 2
    when 'confirmed' then 3
    when 'unconfirmed' then 4
    when 'expired' then 5
    when 'cancelled' then 6
    else 99
  end as status_order
from public.booking_dashboard_list_v booking;

revoke all on table public.booking_dashboard_list_ordered_v
  from public, anon, authenticated;
grant select on table public.booking_dashboard_list_ordered_v to service_role;

comment on view public.booking_dashboard_list_ordered_v is
  'Dashboard list projection with the product-defined lifecycle sort order.';


-- SOURCE: 0099_staff_on_behalf_booking.sql
-- Staff may create supplier holds for a selected customer/agency, but may not
-- reserve wallet funds or issue tickets. Creator and financial owner remain
-- distinct, durable audit identities.

alter table public.booking_attempts
  add column if not exists created_by_user_id text
    references public.app_users (clerk_id) on delete set null,
  add column if not exists staff_on_behalf boolean not null default false;

update public.booking_attempts
   set created_by_user_id = coalesce(created_by_user_id, user_id)
 where created_by_user_id is null;

create index if not exists booking_attempts_creator_created_idx
  on public.booking_attempts (created_by_user_id, created_at desc);

create or replace function public.enforce_staff_on_behalf_booking_v1()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_attempt public.booking_attempts;
  v_creator_role text;
  v_owner_role text;
  v_owner_agency text;
begin
  if new.attempt_id is null then return new; end if;
  select * into v_attempt from public.booking_attempts where id = new.attempt_id;
  if not found or not v_attempt.staff_on_behalf then return new; end if;

  select role into v_creator_role
    from public.app_users where clerk_id = v_attempt.created_by_user_id;
  select role, agency_code into v_owner_role, v_owner_agency
    from public.app_users where clerk_id = v_attempt.user_id;

  if v_creator_role not in ('superadmin', 'admin', 'staff_support') then
    raise exception 'staff booking creator is not authorized' using errcode = '42501';
  end if;
  if v_owner_role not in ('b2b', 'b2b_sub', 'customer') then
    raise exception 'staff booking owner is not eligible' using errcode = '42501';
  end if;
  if new.user_id is distinct from v_attempt.user_id then
    raise exception 'staff booking owner changed during finalization' using errcode = '23514';
  end if;
  if v_owner_role in ('b2b', 'b2b_sub') and
     (v_owner_agency is null or new.audience <> 'agency' or
      new.agency_code is distinct from v_owner_agency) then
    raise exception 'staff booking agency owner mismatch' using errcode = '23514';
  end if;
  if v_owner_role = 'customer' and new.audience <> 'b2c' then
    raise exception 'staff booking B2C owner mismatch' using errcode = '23514';
  end if;
  if new.status <> 'on-hold' or new.direct_ticketing or new.issued_at is not null or
     new.payment_state <> 'unpaid' or new.charged_wallet_account_id is not null or
     coalesce(new.captured_amount, 0) <> 0 or coalesce(new.refunded_amount, 0) <> 0 then
    raise exception 'staff booking must remain an unpaid hold' using errcode = '23514';
  end if;

  new.booked_by_user_id := v_attempt.created_by_user_id;
  return new;
end;
$$;

drop trigger if exists flight_bookings_staff_on_behalf_invariant_v1
  on public.flight_bookings;
create trigger flight_bookings_staff_on_behalf_invariant_v1
  before insert on public.flight_bookings
  for each row execute function public.enforce_staff_on_behalf_booking_v1();

-- Backend defense-in-depth: even a future route calling the wallet RPC cannot
-- make Admin or Support the actor for NewTicket.
create or replace function public.wallet_begin_booking_issue(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_amount bigint;
  v_result jsonb;
begin
  if p_actor_role in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'ISSUE_FORBIDDEN');
  end if;
  select * into v_booking from public.flight_bookings
   where id = p_booking_id and not legacy_operational for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND'); end if;
  if v_booking.status = 'confirmed' or v_booking.payment_state = 'captured' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;
  if v_booking.status <> 'on-hold' or v_booking.operation_kind is not null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_UNCONFIRMED');
  end if;
  if v_booking.ticketing_deadline_at is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_DEADLINE_REQUIRED');
  end if;
  if v_booking.ticketing_deadline_at <= now() then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
  end if;
  if v_booking.booking_owner_type is null or v_booking.booking_owner_key is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_OWNER_REQUIRED');
  end if;
  begin
    v_amount := round((v_booking.pricing_snapshot->>'sellingPrice')::numeric * 100)::bigint;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end;
  v_result := public.wallet_reserve_amount(
    v_booking.id, null, v_booking.booking_owner_type, v_booking.booking_owner_key,
    v_amount, v_booking.currency, p_actor_user_id, p_actor_role,
    p_idempotency_key, v_booking.public_ref
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then return v_result; end if;
  update public.flight_bookings set
    status = 'in-progress', operation_kind = 'ticketing',
    operation_reason = 'ticketing', operation_request_id = p_idempotency_key,
    operation_actor_user_id = p_actor_user_id, operation_started_at = now(),
    operation_prior_status = 'on-hold'
  where id = v_booking.id;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation, idempotency_key
  ) values (
    v_booking.id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'ticketing', 'ticketing', p_actor_user_id, 'NewTicket',
    p_idempotency_key || ':ticketing-start'
  ) on conflict do nothing;
  return v_result || jsonb_build_object('status', 'in-progress');
end;
$$;

create or replace function public.wallet_begin_booking_issue_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text,
  p_request_payload_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_claim jsonb;
  v_replay jsonb;
  v_result jsonb;
  v_operation_id uuid;
begin
  if p_actor_role in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'ISSUE_FORBIDDEN');
  end if;
  v_claim := public.claim_booking_operation_identity(
    p_booking_id, 'ticketing', 'ticketing', null,
    p_request_key, p_request_payload_hash,
    p_actor_user_id, p_actor_role, 'staff', 'NewTicket', null
  );
  if coalesce((v_claim->>'ok')::boolean, false) is not true then return v_claim; end if;
  v_replay := public.booking_operation_replay_response(v_claim);
  if v_replay is not null then return v_replay; end if;
  v_operation_id := (v_claim->>'operationId')::uuid;
  v_result := public.wallet_begin_booking_issue(
    p_booking_id, p_actor_user_id, p_actor_role, p_request_key
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    update public.booking_operations set
      state = 'failed', completed_at = now(),
      error_code = coalesce(v_result->>'code', 'CLAIM_FAILED'),
      supplier_evidence = jsonb_build_object(
        'phase', 'local_claim', 'resultCode', v_result->>'code'
      )
    where id = v_operation_id and state = 'claimed';
    return v_result || jsonb_build_object(
      'operationId', v_operation_id, 'operationState', 'failed'
    );
  end if;
  update public.flight_bookings set active_operation_id = v_operation_id
    where id = p_booking_id;
  update public.booking_status_events set operation_id = v_operation_id
    where booking_id = p_booking_id
      and idempotency_key = p_request_key || ':ticketing-start';
  return v_result || jsonb_build_object(
    'replay', false, 'operationId', v_operation_id, 'operationState', 'claimed'
  );
end;
$$;

-- Add creator identity to the already-narrow paginated list in the same query.
create or replace view public.booking_dashboard_creator_v
with (security_invoker = true)
as
select
  list.*,
  coalesce(nullif(concat_ws(' ', creator.first_name, creator.last_name), ''), creator.email, '')
    as creator_name,
  coalesce(creator.role, '') as creator_role,
  coalesce(creator.email, '') as creator_email,
  creator.agency_code as creator_agency_code,
  nullif(owner_profile.agency_name, '') as creator_agency_name,
  lower(concat_ws(' ',
    coalesce(creator.first_name, ''), coalesce(creator.last_name, ''),
    coalesce(creator.email, ''), coalesce(creator.role, ''),
    coalesce(creator.agency_code, ''), coalesce(owner_profile.agency_name, '')
  )) as creator_search_text
from public.booking_dashboard_list_ordered_v list
join public.flight_bookings booking on booking.id = list.id
left join public.app_users creator
  on creator.clerk_id = coalesce(booking.booked_by_user_id, booking.user_id)
left join public.agencies creator_agency
  on creator_agency.agency_code = creator.agency_code
left join public.user_profiles owner_profile
  on owner_profile.clerk_id = creator_agency.owner_user_id;

revoke all on table public.booking_dashboard_creator_v from public, anon, authenticated;
grant select on table public.booking_dashboard_creator_v to service_role;

comment on view public.booking_dashboard_creator_v is
  'Paginated booking list with creator role and agency identity resolved in one read.';


-- SOURCE: 0100_staff_booking_attempt_hold_recovery.sql
-- Controlled recovery for a staff-created held booking whose supplier response
-- was received but could not be durably finalized. The caller must first read
-- the supplier by the attempt's immutable transaction identity. No wallet
-- reservation is created or modified by this function.

create or replace function public.recover_staff_booking_attempt_hold_v1(
  p_attempt_id uuid,
  p_actor_user_id text,
  p_expected_unique_trans_id text,
  p_supplier_observed_at timestamptz,
  p_supplier_evidence_hash text,
  p_outcome jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_attempt public.booking_attempts;
  v_actor_role text;
  v_case public.booking_reconciliation_cases;
  v_booking public.flight_bookings;
begin
  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role <> 'superadmin' then
    raise exception 'super admin recovery authority is required'
      using errcode = '42501';
  end if;

  select * into v_attempt
    from public.booking_attempts
   where id = p_attempt_id
   for update;
  if not found then
    raise exception 'booking attempt does not exist' using errcode = 'P0002';
  end if;
  if not v_attempt.staff_on_behalf or v_attempt.state <> 'unknown' then
    raise exception 'only an unknown staff-created booking attempt can be recovered'
      using errcode = '23514';
  end if;
  if nullif(btrim(p_expected_unique_trans_id), '') is null
     or p_expected_unique_trans_id is distinct from v_attempt.unique_trans_id then
    raise exception 'supplier transaction identity mismatch'
      using errcode = '22023';
  end if;
  if p_supplier_observed_at is null
     or p_supplier_observed_at > now() + interval '5 minutes' then
    raise exception 'invalid supplier observation time' using errcode = '22023';
  end if;
  if p_supplier_evidence_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'invalid supplier evidence hash' using errcode = '22023';
  end if;
  if p_outcome is null or jsonb_typeof(p_outcome) <> 'object'
     or p_outcome->>'status' <> 'held'
     or nullif(btrim(p_outcome->>'pnr'), '') is null
     or nullif(btrim(p_outcome->>'bookingCodeRef'), '') is null
     or coalesce(p_outcome->'ticketNumbers', '[]'::jsonb) <> '[]'::jsonb
     or nullif(btrim(p_outcome->>'ticketCodeRef'), '') is not null then
    raise exception 'recovery outcome is not a verified supplier hold'
      using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_outcome->'airlinesPnr', 'null'::jsonb)) <> 'array'
     or jsonb_array_length(p_outcome->'airlinesPnr') = 0 then
    raise exception 'recovery outcome requires an airline PNR'
      using errcode = '22023';
  end if;

  if exists (
    select 1 from public.wallet_reservations
     where booking_attempt_id = p_attempt_id
  ) then
    raise exception 'staff booking recovery cannot touch a wallet-backed attempt'
      using errcode = '23514';
  end if;
  if exists (
    select 1 from public.flight_bookings where attempt_id = p_attempt_id
  ) then
    raise exception 'booking attempt already has a business booking'
      using errcode = '23514';
  end if;

  select * into v_case
    from public.booking_reconciliation_cases
   where subject_booking_attempt_id = p_attempt_id
     and case_type = 'attempt_uncertainty'
     and state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     )
   for update;
  if not found then
    raise exception 'open attempt reconciliation case is required'
      using errcode = '23514';
  end if;

  -- Re-enter the existing atomic finalizer only after the manual supplier read
  -- has proved the original unique transaction produced an unpaid hold.
  update public.booking_attempts
     set state = 'submitting',
         supplier_response_received_at = coalesce(
           supplier_response_received_at,
           p_supplier_observed_at
         ),
         supplier_response_http_status = coalesce(
           supplier_response_http_status,
           200
         )
   where id = p_attempt_id;

  v_booking := public.create_booking_from_attempt_v2(
    p_attempt_id,
    v_attempt.operation_request_key,
    v_attempt.operation_request_payload_hash,
    p_outcome
  );

  update public.booking_attempts
     set error_code = null,
         supplier_message = coalesce(
           nullif(btrim(p_outcome->>'message'), ''),
           'Recovered from a verified supplier hold'
         )
   where id = p_attempt_id;

  update public.booking_reconciliation_cases
     set state = 'resolved',
         resolution_outcome = 'booking_recovered_held',
         resolution_reason = 'Original supplier transaction verified as an unpaid hold',
         resolution = jsonb_build_object(
           'bookingId', v_booking.id,
           'bookingPublicRef', v_booking.public_ref,
           'supplierEvidenceHash', p_supplier_evidence_hash,
           'supplierObservedAt', p_supplier_observed_at,
           'financialDisposition', 'none'
         ),
         financial_disposition = 'none',
         resolved_by_user_id = p_actor_user_id,
         resolved_at = now(),
         closed_at = now(),
         version = version + 1
   where id = v_case.id;

  return v_booking;
end;
$$;

revoke all on function public.recover_staff_booking_attempt_hold_v1(
  uuid, text, text, timestamptz, text, jsonb
) from public, anon, authenticated;
grant execute on function public.recover_staff_booking_attempt_hold_v1(
  uuid, text, text, timestamptz, text, jsonb
) to service_role;

comment on function public.recover_staff_booking_attempt_hold_v1(
  uuid, text, text, timestamptz, text, jsonb
) is
  'Super Admin-only recovery of an unknown staff-created booking after an identity-matched supplier read proves the original transaction produced an unpaid hold. Never reserves or charges wallet funds.';


-- SOURCE: 0101_on_hold_cancellation_independence.sql
-- On Hold cancellation is a supplier hold-release action, not ticketing.
-- A customer must not need wallet funds or a local Issue Ticket time-limit
-- grant to cancel an unissued booking they own. Expired lifecycle rows remain
-- protected by their effective deadline, while a missing deadline does not
-- manufacture an Issue Ticket prerequisite for cancellation.

create or replace function public.begin_booking_cancellation(
  p_booking_id uuid,
  p_actor_user_id text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
begin
  select * into v_booking
    from public.flight_bookings
   where id = p_booking_id and not legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  if v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.issued_at is not null
     or v_booking.direct_ticketing
     or v_booking.payment_state in ('held', 'captured', 'reconciliation') then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_CANCELLABLE');
  end if;
  if not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_UNCONFIRMED');
  end if;
  if v_booking.ticketing_deadline_at is not null
     and v_booking.ticketing_deadline_at <= clock_timestamp() then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
  end if;

  if v_booking.active_local_time_limit_request_id is not null then
    select role into v_actor_role
      from public.app_users
     where clerk_id = p_actor_user_id;
    insert into public.booking_local_time_limit_events (
      booking_id, request_id, event_type, actor_user_id, actor_role,
      resulting_deadline_at, operation_request_key, evidence
    ) values (
      p_booking_id, v_booking.active_local_time_limit_request_id,
      'used_for_cancellation', p_actor_user_id,
      case
        when v_actor_role in (
          'superadmin', 'admin', 'staff_support', 'staff_account',
          'customer', 'b2b', 'b2b_sub'
        ) then v_actor_role
        else 'system'
      end,
      v_booking.local_ticketing_deadline_at, p_idempotency_key,
      jsonb_build_object('walletMutation', false)
    ) on conflict do nothing;
  end if;

  update public.flight_bookings
     set status = 'in-progress',
         operation_kind = 'cancellation',
         operation_reason = 'cancellation',
         operation_request_id = p_idempotency_key,
         operation_actor_user_id = p_actor_user_id,
         operation_started_at = now(),
         operation_prior_status = 'on-hold'
   where id = p_booking_id;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation, idempotency_key
  ) values (
    p_booking_id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'cancellation', 'cancellation', p_actor_user_id, 'Cancel',
    p_idempotency_key || ':cancellation-start'
  ) on conflict do nothing;
  return jsonb_build_object(
    'ok', true,
    'status', 'in-progress',
    'walletMutation', false
  );
end;
$$;

revoke all on function public.begin_booking_cancellation(uuid, text, text)
  from public, anon, authenticated;
grant execute on function public.begin_booking_cancellation(uuid, text, text)
  to service_role;

comment on function public.begin_booking_cancellation(uuid, text, text) is
  'Claims an owned, unissued On Hold booking for supplier cancellation without checking, reserving, charging, or deducting wallet balance and without requiring an Issue Ticket local time-limit grant.';


-- SOURCE: 0102_admin_owner_wallet_ticketing.sql
-- SuperAdmin/Admin may issue an On Hold booking on behalf of its assigned
-- B2B/B2C owner. The actor identity is retained for audit, while reservation
-- and capture continue to use the booking owner's wallet. Support remains
-- forbidden before any wallet or supplier operation starts.

create or replace function public.wallet_begin_booking_issue(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_amount bigint;
  v_result jsonb;
begin
  if p_actor_role = 'staff_support' then
    return jsonb_build_object('ok', false, 'code', 'ISSUE_FORBIDDEN');
  end if;
  select * into v_booking
    from public.flight_bookings
   where id = p_booking_id and not legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  if v_booking.status = 'confirmed' or v_booking.payment_state = 'captured' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;
  if v_booking.status <> 'on-hold' or v_booking.operation_kind is not null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if not public.jsonb_is_nonempty_array(v_booking.airlines_pnr) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_UNCONFIRMED');
  end if;
  if v_booking.ticketing_deadline_at is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_DEADLINE_REQUIRED');
  end if;
  if v_booking.ticketing_deadline_at <= now() then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_EXPIRED');
  end if;
  if v_booking.booking_owner_type is null or v_booking.booking_owner_key is null then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_OWNER_REQUIRED');
  end if;
  begin
    v_amount := round(
      (v_booking.pricing_snapshot->>'sellingPrice')::numeric * 100
    )::bigint;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end;
  v_result := public.wallet_reserve_amount(
    v_booking.id, null,
    v_booking.booking_owner_type, v_booking.booking_owner_key,
    v_amount, v_booking.currency,
    p_actor_user_id, p_actor_role,
    p_idempotency_key, v_booking.public_ref
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    return v_result;
  end if;
  update public.flight_bookings
     set status = 'in-progress',
         operation_kind = 'ticketing',
         operation_reason = 'ticketing',
         operation_request_id = p_idempotency_key,
         operation_actor_user_id = p_actor_user_id,
         operation_started_at = now(),
         operation_prior_status = 'on-hold'
   where id = v_booking.id;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation, idempotency_key,
    supplier_evidence
  ) values (
    v_booking.id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'ticketing', 'ticketing', p_actor_user_id, 'NewTicket',
    p_idempotency_key || ':ticketing-start',
    jsonb_build_object(
      'actorRole', p_actor_role,
      'walletOwnerType', v_booking.booking_owner_type,
      'walletOwnerKey', v_booking.booking_owner_key,
      'staffIssuedForOwner', p_actor_role in ('superadmin', 'admin')
    )
  ) on conflict do nothing;
  return v_result || jsonb_build_object(
    'status', 'in-progress',
    'walletOwnerType', v_booking.booking_owner_type,
    'walletOwnerKey', v_booking.booking_owner_key,
    'staffIssuedForOwner', p_actor_role in ('superadmin', 'admin')
  );
end;
$$;

create or replace function public.wallet_begin_booking_issue_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_request_key text,
  p_request_payload_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_claim jsonb;
  v_replay jsonb;
  v_result jsonb;
  v_operation_id uuid;
begin
  if p_actor_role = 'staff_support' then
    return jsonb_build_object('ok', false, 'code', 'ISSUE_FORBIDDEN');
  end if;
  v_claim := public.claim_booking_operation_identity(
    p_booking_id, 'ticketing', 'ticketing', null,
    p_request_key, p_request_payload_hash,
    p_actor_user_id, p_actor_role, 'staff', 'NewTicket', null
  );
  if coalesce((v_claim->>'ok')::boolean, false) is not true then
    return v_claim;
  end if;
  v_replay := public.booking_operation_replay_response(v_claim);
  if v_replay is not null then return v_replay; end if;
  v_operation_id := (v_claim->>'operationId')::uuid;
  v_result := public.wallet_begin_booking_issue(
    p_booking_id, p_actor_user_id, p_actor_role, p_request_key
  );
  if coalesce((v_result->>'ok')::boolean, false) is not true then
    update public.booking_operations
       set state = 'failed',
           completed_at = now(),
           error_code = coalesce(v_result->>'code', 'CLAIM_FAILED'),
           supplier_evidence = jsonb_build_object(
             'phase', 'local_claim',
             'resultCode', v_result->>'code',
             'actorRole', p_actor_role
           )
     where id = v_operation_id and state = 'claimed';
    return v_result || jsonb_build_object(
      'operationId', v_operation_id,
      'operationState', 'failed'
    );
  end if;
  update public.flight_bookings
     set active_operation_id = v_operation_id
   where id = p_booking_id;
  update public.booking_status_events
     set operation_id = v_operation_id
   where booking_id = p_booking_id
     and idempotency_key = p_request_key || ':ticketing-start';
  return v_result || jsonb_build_object(
    'replay', false,
    'operationId', v_operation_id,
    'operationState', 'claimed'
  );
end;
$$;

revoke all on function public.wallet_begin_booking_issue(
  uuid, text, text, text
) from public, anon, authenticated;
revoke all on function public.wallet_begin_booking_issue_v2(
  uuid, text, text, text, text
) from public, anon, authenticated;
grant execute on function public.wallet_begin_booking_issue(
  uuid, text, text, text
) to service_role;
grant execute on function public.wallet_begin_booking_issue_v2(
  uuid, text, text, text, text
) to service_role;

comment on function public.wallet_begin_booking_issue(
  uuid, text, text, text
) is
  'Reserves the booking owner wallet for ticketing. SuperAdmin/Admin may act for the owner; Support is forbidden before any wallet mutation.';
comment on function public.wallet_begin_booking_issue_v2(
  uuid, text, text, text, text
) is
  'Idempotent ticketing claim allowing SuperAdmin/Admin to charge the assigned booking owner wallet while retaining the staff actor for audit; Support remains forbidden.';


-- SOURCE: 0103_passenger_profiles.sql
-- Saved passenger profiles are intentionally separate from booking snapshots.
-- Every value is entered by the traveller/profile owner. Checkout defaults,
-- account or supplier contacts, and values merely prefilled from a profile are
-- never written back unless the user edits that field and chooses to save it.

create table if not exists public.passenger_profile_ref_counters (
  ref_date date primary key,
  last_value integer not null default 0 check (last_value >= 0),
  updated_at timestamptz not null default now()
);

alter table public.passenger_profile_ref_counters enable row level security;
revoke all on table public.passenger_profile_ref_counters from anon, authenticated;
grant select, insert, update on table public.passenger_profile_ref_counters to service_role;

create or replace function public.allocate_passenger_profile_ref_for(p_date date)
returns text
language plpgsql
as $$
declare
  v_next integer;
begin
  insert into public.passenger_profile_ref_counters as c (ref_date, last_value)
  values (p_date, 1)
  on conflict (ref_date) do update
    set last_value = c.last_value + 1,
        updated_at = now()
  returning c.last_value into v_next;

  return 'STP' || to_char(p_date, 'YYMMDD') || lpad(v_next::text, 6, '0');
end;
$$;

create or replace function public.allocate_passenger_profile_ref()
returns text
language sql
as $$
  select public.allocate_passenger_profile_ref_for(
    (now() at time zone 'Asia/Dhaka')::date
  );
$$;

revoke execute on function public.allocate_passenger_profile_ref_for(date)
  from public, anon, authenticated;
revoke execute on function public.allocate_passenger_profile_ref()
  from public, anon, authenticated;
grant execute on function public.allocate_passenger_profile_ref_for(date) to service_role;
grant execute on function public.allocate_passenger_profile_ref() to service_role;

create table if not exists public.passenger_profiles (
  id uuid primary key default gen_random_uuid(),
  public_ref text not null default public.allocate_passenger_profile_ref(),
  owner_user_id text not null references public.app_users (clerk_id) on delete cascade,

  passenger_type text not null check (passenger_type in ('ADT', 'CHD', 'CNN', 'INF', 'INS')),
  title text not null check (title in ('Mr', 'Mrs', 'Ms', 'Mstr', 'Miss')),
  given_name text not null check (char_length(given_name) between 1 and 60),
  surname text not null check (char_length(surname) between 1 and 60),
  gender text not null check (gender in ('Male', 'Female')),
  nationality text not null check (nationality ~ '^[A-Z]{2}$'),

  -- Optional contact values are saved only when the user types them. These
  -- are never seeded from supplier/company configuration or an account profile.
  phone_country_code text check (phone_country_code is null or phone_country_code ~ '^\+[0-9]{1,4}$'),
  phone text check (phone is null or phone ~ '^[0-9]{6,15}$'),
  email text check (email is null or char_length(email) <= 254),

  -- Optional document and preference fields. They are profile data only and
  -- must never be seeded from a supplier, account, or booking default.
  date_of_birth date,
  passport_number text check (passport_number is null or passport_number ~ '^[A-Z0-9]{5,20}$'),
  passport_expiry date,
  issuing_country text check (issuing_country is null or issuing_country ~ '^[A-Z]{2}$'),
  loyalty_airline_code text check (loyalty_airline_code is null or loyalty_airline_code ~ '^[A-Z0-9]{2,10}$'),
  loyalty_account_number text check (loyalty_account_number is null or char_length(loyalty_account_number) <= 50),
  ssr_requests jsonb not null default '[]'::jsonb
    check (jsonb_typeof(ssr_requests) = 'array'),
  organization text check (organization is null or char_length(organization) <= 120),

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint passenger_profiles_public_ref_format_check
    check (public_ref ~ '^STP[0-9]{12}$'),
  constraint passenger_profiles_title_match_check
    check (
      (passenger_type = 'ADT' and gender = 'Male' and title = 'Mr')
      or (passenger_type = 'ADT' and gender = 'Female' and title in ('Ms', 'Mrs'))
      or (passenger_type in ('CHD', 'CNN', 'INF', 'INS') and gender = 'Male' and title = 'Mstr')
      or (passenger_type in ('CHD', 'CNN', 'INF', 'INS') and gender = 'Female' and title = 'Miss')
    ),
  constraint passenger_profiles_phone_pair_check
    check (
      (phone is null and phone_country_code is null)
      or (phone is not null and phone_country_code is not null)
    )
);

create unique index if not exists passenger_profiles_public_ref_key
  on public.passenger_profiles (public_ref);
create index if not exists passenger_profiles_owner_created_idx
  on public.passenger_profiles (owner_user_id, created_at desc);
create index if not exists passenger_profiles_name_idx
  on public.passenger_profiles (owner_user_id, surname, given_name);

drop trigger if exists passenger_profiles_touch_updated_at on public.passenger_profiles;
create trigger passenger_profiles_touch_updated_at
  before update on public.passenger_profiles
  for each row execute function public.touch_updated_at();

create or replace function public.prevent_passenger_profile_ref_change()
returns trigger
language plpgsql
as $$
begin
  if new.public_ref is distinct from old.public_ref then
    raise exception 'Passenger profile reference is immutable';
  end if;
  return new;
end;
$$;

drop trigger if exists passenger_profiles_public_ref_immutable on public.passenger_profiles;
create trigger passenger_profiles_public_ref_immutable
  before update on public.passenger_profiles
  for each row execute function public.prevent_passenger_profile_ref_change();

alter table public.passenger_profiles enable row level security;
revoke all on table public.passenger_profiles from anon, authenticated;
grant select, insert, update, delete on table public.passenger_profiles to service_role;

revoke execute on function public.prevent_passenger_profile_ref_change()
  from public, anon, authenticated;
grant execute on function public.prevent_passenger_profile_ref_change() to service_role;

comment on table public.passenger_profiles is
  'User-saved passenger profiles. Values are retained only after explicit user entry; prefilled checkout, account, and supplier data is not saved.';
comment on column public.passenger_profiles.public_ref is
  'Immutable public passenger identifier, STPYYMMDD###### (for example, STP260822000001).';


-- SOURCE: 0104_booking_dashboard_on_behalf_agency.sql
-- The dashboard needs to distinguish the internal colleague who created a
-- booking from the agency whose account the booking belongs to.  Keep both
-- identities in the existing narrow, paginated list projection so rendering
-- the "Created By" cell never requires a per-row lookup.
create or replace view public.booking_dashboard_creator_v
with (security_invoker = true)
as
select
  list.*,
  coalesce(nullif(concat_ws(' ', creator.first_name, creator.last_name), ''), creator.email, '')
    as creator_name,
  coalesce(creator.role, '') as creator_role,
  coalesce(creator.email, '') as creator_email,
  creator.agency_code as creator_agency_code,
  nullif(creator_agency_profile.agency_name, '') as creator_agency_name,
  lower(concat_ws(' ',
    coalesce(creator.first_name, ''), coalesce(creator.last_name, ''),
    coalesce(creator.email, ''), coalesce(creator.role, ''),
    coalesce(creator.agency_code, ''), coalesce(creator_agency_profile.agency_name, ''),
    coalesce(booking.agency_code, ''), coalesce(booking_agency_profile.agency_name, '')
  )) as creator_search_text,
  booking.agency_code as booking_agency_code,
  nullif(booking_agency_profile.agency_name, '') as booking_agency_name
from public.booking_dashboard_list_ordered_v list
join public.flight_bookings booking on booking.id = list.id
left join public.app_users creator
  on creator.clerk_id = coalesce(booking.booked_by_user_id, booking.user_id)
left join public.agencies creator_agency
  on creator_agency.agency_code = creator.agency_code
left join public.user_profiles creator_agency_profile
  on creator_agency_profile.clerk_id = creator_agency.owner_user_id
left join public.agencies booking_agency
  on booking_agency.agency_code = booking.agency_code
left join public.user_profiles booking_agency_profile
  on booking_agency_profile.clerk_id = booking_agency.owner_user_id;

comment on view public.booking_dashboard_creator_v is
  'Paginated booking list with creator and owning-agency identities resolved in one read.';


-- SOURCE: 0105_manual_booking_supplier_payable.sql
-- Manual imports now retain three separate commercial values:
-- gross amount, supplier payable, and the wallet-captured user payable.
-- Supplier payable is stored in the existing pricing snapshot, which is the
-- source used by the booking list and profit reports.

alter table public.flight_bookings
  drop constraint if exists flight_bookings_manual_pricing_truth_check;

alter table public.flight_bookings
  add constraint flight_bookings_manual_pricing_truth_check
  check (
    import_source is distinct from 'MANUAL'
    or (
      user_payable_amount is not null
      and user_payable_amount > 0
      and supplier_gross_amount is not null
      and supplier_gross_amount >= 0
      and public.manual_pricing_minor_amount_v1(pricing_snapshot, 'sellingPrice')
        = user_payable_amount
      and public.manual_pricing_minor_amount_v1(pricing_snapshot, 'grossPrice')
        = supplier_gross_amount
      and public.manual_pricing_minor_amount_v1(pricing_snapshot, 'supplierTotalPrice')
        is not null
      and public.manual_pricing_minor_amount_v1(pricing_snapshot, 'supplierTotalPrice')
        >= 0
      and (payment_amount is null or payment_amount = user_payable_amount)
      and captured_amount in (0, user_payable_amount)
      and refunded_amount between 0 and captured_amount
    )
  ) not valid;

create or replace function public.enforce_manual_booking_invariants_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' and old.import_source = 'MANUAL' then
    if new.import_source is distinct from old.import_source then
      raise exception 'manual booking source is immutable'
        using errcode = '23514', constraint = 'flight_bookings_manual_source_immutable';
    end if;
    if new.user_payable_amount is distinct from old.user_payable_amount
       or new.currency is distinct from old.currency then
      raise exception 'manual User Payable and currency are immutable'
        using errcode = '23514', constraint = 'flight_bookings_manual_payable_immutable';
    end if;
  end if;

  if new.import_source is distinct from 'MANUAL' then
    return new;
  end if;

  if new.user_payable_amount is null or new.user_payable_amount <= 0
     or new.supplier_gross_amount is null or new.supplier_gross_amount < 0
     or public.manual_pricing_minor_amount_v1(new.pricing_snapshot, 'sellingPrice')
          is distinct from new.user_payable_amount
     or public.manual_pricing_minor_amount_v1(new.pricing_snapshot, 'grossPrice')
          is distinct from new.supplier_gross_amount
     or public.manual_pricing_minor_amount_v1(new.pricing_snapshot, 'supplierTotalPrice')
          is null
     or public.manual_pricing_minor_amount_v1(new.pricing_snapshot, 'supplierTotalPrice') < 0
     or (new.payment_amount is not null
       and new.payment_amount is distinct from new.user_payable_amount)
     or new.captured_amount not in (0, new.user_payable_amount)
     or new.refunded_amount < 0 or new.refunded_amount > new.captured_amount then
    raise exception 'manual Gross/Supplier Payable/User Payable invariant failed'
      using errcode = '23514', constraint = 'flight_bookings_manual_pricing_truth_check';
  end if;

  return new;
end;
$$;

create or replace function public.create_manual_booking_v2(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_supplier_payable_amount bigint,
  p_data jsonb,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
  v_booking_id uuid;
  v_attempt_id uuid;
  v_supplier_payable_major numeric;
  v_payload_minor numeric;
begin
  if p_supplier_payable_amount is null or p_supplier_payable_amount < 0
     or p_data is null or jsonb_typeof(p_data) <> 'object'
     or jsonb_typeof(p_data -> 'supplierPayableAmount') <> 'number' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_MANUAL_IMPORT_DATA');
  end if;

  begin
    v_payload_minor := (p_data ->> 'supplierPayableAmount')::numeric * 100;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'INVALID_MANUAL_IMPORT_DATA');
  end;
  if v_payload_minor < 0
     or v_payload_minor <> trunc(v_payload_minor)
     or v_payload_minor is distinct from p_supplier_payable_amount::numeric then
    return jsonb_build_object('ok', false, 'code', 'INVALID_MANUAL_IMPORT_DATA');
  end if;

  -- v1 owns the durable booking, wallet, ledger, and idempotency transaction.
  -- This wrapper keeps those safeguards intact, then records the supplier cost
  -- in the same transaction before the booking can be returned to the caller.
  v_result := public.create_manual_booking_v1(
    p_actor_user_id,
    p_assigned_user_id,
    p_user_payable_amount,
    p_supplier_gross_amount,
    p_data,
    p_request_key
  );
  if coalesce((v_result ->> 'ok')::boolean, false) is not true then
    return v_result;
  end if;

  begin
    v_booking_id := (v_result #>> '{booking,id}')::uuid;
  exception when others then
    raise exception 'manual booking result omitted its booking identity';
  end;
  v_supplier_payable_major := p_supplier_payable_amount::numeric / 100;

  update public.flight_bookings
     set pricing_snapshot = coalesce(pricing_snapshot, '{}'::jsonb)
           || jsonb_build_object('supplierTotalPrice', v_supplier_payable_major),
         import_metadata = coalesce(import_metadata, '{}'::jsonb)
           || jsonb_build_object('supplierPayableAmount', v_supplier_payable_major)
   where id = v_booking_id
     and import_source = 'MANUAL'
  returning attempt_id into v_attempt_id;
  if not found then
    raise exception 'manual booking pricing target was not found';
  end if;

  update public.booking_attempts
     set offer_snapshot = coalesce(offer_snapshot, '{}'::jsonb)
           || jsonb_build_object(
             'pricing',
             coalesce(offer_snapshot -> 'pricing', '{}'::jsonb)
               || jsonb_build_object('supplierTotalPrice', v_supplier_payable_major)
           )
   where id = v_attempt_id;

  return v_result || jsonb_build_object(
    'supplierPayableAmount', p_supplier_payable_amount
  );
end;
$$;

revoke all on function public.create_manual_booking_v2(text, text, bigint, bigint, bigint, jsonb, text)
  from public, anon, authenticated;
grant execute on function public.create_manual_booking_v2(text, text, bigint, bigint, bigint, jsonb, text)
  to service_role;

comment on function public.create_manual_booking_v2(text, text, bigint, bigint, bigint, jsonb, text) is
  'Creates a manual booking with separate Gross, Supplier Payable, and User Payable values.';


-- SOURCE: 0106_superadmin_booking_decisions.sql
-- One-step Super Admin booking decisions.
--
-- Actual reservation and immutable ledger history are authoritative. The
-- denormalized flight_bookings.payment_state is repaired from proven
-- accounting truth and is never used by itself to choose a money movement.

create table if not exists public.superadmin_booking_decisions (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.flight_bookings (id) on delete restrict,
  request_key text not null unique
    check (char_length(request_key) between 1 and 220),
  actor_user_id text not null check (nullif(btrim(actor_user_id), '') is not null),
  actor_role text not null check (actor_role = 'superadmin'),
  decision text not null check (decision in (
    'confirm_ticketed', 'cancel', 'keep_on_hold',
    'extend_deadline', 'close_without_change'
  )),
  note text,
  request_snapshot jsonb not null check (jsonb_typeof(request_snapshot) = 'object'),
  accounting_snapshot jsonb not null check (jsonb_typeof(accounting_snapshot) = 'object'),
  result jsonb not null check (jsonb_typeof(result) = 'object'),
  created_at timestamptz not null default clock_timestamp()
);

create index if not exists superadmin_booking_decisions_booking_created_idx
  on public.superadmin_booking_decisions (booking_id, created_at desc);

create or replace function public.deny_superadmin_booking_decision_mutation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'superadmin booking decisions are immutable' using errcode = '55000';
end;
$$;

drop trigger if exists superadmin_booking_decisions_immutable_v1
  on public.superadmin_booking_decisions;
create trigger superadmin_booking_decisions_immutable_v1
  before update or delete on public.superadmin_booking_decisions
  for each row execute function public.deny_superadmin_booking_decision_mutation_v1();

alter table public.superadmin_booking_decisions enable row level security;
revoke all on table public.superadmin_booking_decisions
  from public, anon, authenticated;
grant select, insert on table public.superadmin_booking_decisions to service_role;

-- Read-only accounting classification shared by preview and the locked
-- executor. A caller must still re-run it after acquiring mutation locks.
create or replace function public.classify_superadmin_booking_accounting_v1(
  p_booking_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_reservation public.wallet_reservations;
  v_capture public.wallet_ledger_entries;
  v_reservation_count integer := 0;
  v_capture_count integer := 0;
  v_booking_ledger_count integer := 0;
  v_refund_count integer := 0;
  v_refund_amount bigint := 0;
  v_refund_account_count integer := 0;
  v_hold_net bigint := 0;
  v_expected_amount bigint;
  v_account_hold bigint;
  v_account_currency text;
  v_state text;
begin
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  if v_booking.user_payable_amount is not null
     and v_booking.user_payable_amount > 0 then
    v_expected_amount := v_booking.user_payable_amount;
  else
    begin
      v_expected_amount := round(
        (v_booking.pricing_snapshot->>'sellingPrice')::numeric * 100
      )::bigint;
    exception when others then
      return jsonb_build_object('ok', false, 'code', 'INVALID_USER_PAYABLE');
    end;
  end if;
  if v_expected_amount is null or v_expected_amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_USER_PAYABLE');
  end if;

  select count(*)::integer into v_reservation_count
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
      or (reservation.booking_id is null
        and reservation.booking_attempt_id = v_booking.attempt_id);
  if v_reservation_count > 1 then
    return jsonb_build_object('ok', false, 'code', 'MULTIPLE_RESERVATIONS');
  end if;
  if v_reservation_count = 1 then
    select reservation.* into v_reservation
      from public.wallet_reservations reservation
     where reservation.booking_id = v_booking.id
        or (reservation.booking_id is null
          and reservation.booking_attempt_id = v_booking.attempt_id)
     order by reservation.booking_id nulls last
     limit 1;
  end if;

  select count(*)::integer into v_booking_ledger_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.transaction_type in (
       'booking_hold', 'booking_confirm', 'hold_release', 'refund'
     );

  select count(*)::integer into v_capture_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.transaction_type = 'booking_confirm';
  if v_capture_count > 1 then
    return jsonb_build_object('ok', false, 'code', 'MULTIPLE_CAPTURE_LEDGER_ENTRIES');
  end if;
  if v_capture_count = 1 then
    select ledger.* into v_capture
      from public.wallet_ledger_entries ledger
     where ledger.booking_id = v_booking.id
       and ledger.transaction_type = 'booking_confirm';
  end if;

  select count(*)::integer,
         coalesce(sum(ledger.amount), 0)::bigint,
         count(distinct ledger.wallet_account_id)::integer
    into v_refund_count, v_refund_amount, v_refund_account_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.transaction_type = 'refund';

  if v_capture_count = 1 then
    if v_capture.amount <> v_expected_amount
       or v_capture.currency is distinct from upper(v_booking.currency)
       or not (
         (v_capture.available_before - v_capture.available_after = v_capture.amount
           and v_capture.hold_before = v_capture.hold_after)
         or
         (v_capture.available_before = v_capture.available_after
           and v_capture.hold_before - v_capture.hold_after = v_capture.amount)
       )
       or v_refund_amount > v_capture.amount
       or (v_refund_count > 0 and (
         v_refund_account_count <> 1
         or exists (
           select 1 from public.wallet_ledger_entries refund
            where refund.booking_id = v_booking.id
              and refund.transaction_type = 'refund'
              and (refund.wallet_account_id <> v_capture.wallet_account_id
                or refund.currency <> v_capture.currency)
         )
       ))
       or (v_booking.charged_wallet_account_id is not null
         and v_booking.charged_wallet_account_id <> v_capture.wallet_account_id)
       or (v_reservation.id is not null and (
         v_reservation.id is distinct from v_capture.reservation_id
         or v_reservation.wallet_account_id <> v_capture.wallet_account_id
         or v_reservation.amount <> v_capture.amount
         or v_reservation.currency <> v_capture.currency
         or v_reservation.state <> 'captured'
       )) then
      return jsonb_build_object('ok', false, 'code', 'CAPTURE_ACCOUNTING_CONFLICT');
    end if;
    v_state := 'paid';
    return jsonb_build_object(
      'ok', true,
      'accountingState', v_state,
      'expectedAmount', v_expected_amount,
      'currency', upper(v_booking.currency),
      'reservationId', v_reservation.id,
      'reservationState', v_reservation.state,
      'walletAccountId', v_capture.wallet_account_id,
      'capturedAmount', v_capture.amount,
      'refundedAmount', v_refund_amount,
      'outstandingAmount', v_capture.amount - v_refund_amount,
      'paymentStateObserved', v_booking.payment_state,
      'paymentStateStale', v_booking.payment_state is distinct from case
        when v_refund_amount = v_capture.amount then 'refunded'
        when v_refund_amount > 0 then 'partially-refunded'
        else 'captured'
      end
    );
  end if;

  if v_refund_count > 0
     or v_booking.captured_amount > 0
     or v_booking.refunded_amount > 0
     or v_booking.payment_state in ('captured', 'partially-refunded', 'refunded') then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_LEDGER_MISSING');
  end if;

  if v_reservation.id is not null then
    select coalesce(sum(case
      when ledger.transaction_type = 'booking_hold' then ledger.amount
      when ledger.transaction_type = 'hold_release' then -ledger.amount
      when ledger.transaction_type = 'booking_confirm'
       and ledger.hold_before - ledger.hold_after = ledger.amount
        then -ledger.amount
      else 0
    end), 0)::bigint into v_hold_net
      from public.wallet_ledger_entries ledger
     where ledger.reservation_id = v_reservation.id;

    select account.hold_balance, account.currency
      into v_account_hold, v_account_currency
      from public.wallet_accounts account
     where account.id = v_reservation.wallet_account_id;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
    end if;

    if v_reservation.state in ('active', 'reconciliation') then
      if v_reservation.amount <> v_expected_amount
         or v_reservation.currency <> upper(v_booking.currency)
         or v_account_currency <> v_reservation.currency
         or v_hold_net <> v_reservation.amount
         or v_account_hold < v_reservation.amount
         or (v_booking.charged_wallet_account_id is not null
           and v_booking.charged_wallet_account_id
             <> v_reservation.wallet_account_id) then
        return jsonb_build_object('ok', false, 'code', 'ACTIVE_HOLD_ACCOUNTING_CONFLICT');
      end if;
      v_state := 'active_hold';
      return jsonb_build_object(
        'ok', true,
        'accountingState', v_state,
        'expectedAmount', v_expected_amount,
        'currency', upper(v_booking.currency),
        'reservationId', v_reservation.id,
        'reservationState', v_reservation.state,
        'walletAccountId', v_reservation.wallet_account_id,
        'capturedAmount', 0,
        'refundedAmount', 0,
        'outstandingAmount', 0,
        'paymentStateObserved', v_booking.payment_state,
        'paymentStateStale', v_booking.payment_state not in ('held', 'reconciliation')
      );
    elsif v_reservation.state = 'released' then
      if v_hold_net <> 0 then
        return jsonb_build_object('ok', false, 'code', 'RELEASE_ACCOUNTING_CONFLICT');
      end if;
    elsif v_reservation.state = 'captured' then
      return jsonb_build_object('ok', false, 'code', 'CAPTURE_LEDGER_MISSING');
    else
      return jsonb_build_object('ok', false, 'code', 'UNKNOWN_RESERVATION_STATE');
    end if;
  elsif v_booking_ledger_count > 0 then
    return jsonb_build_object('ok', false, 'code', 'RESERVATION_LEDGER_MISMATCH');
  end if;

  return jsonb_build_object(
    'ok', true,
    'accountingState', 'unpaid',
    'expectedAmount', v_expected_amount,
    'currency', upper(v_booking.currency),
    'reservationId', v_reservation.id,
    'reservationState', v_reservation.state,
    'walletAccountId', v_reservation.wallet_account_id,
    'capturedAmount', 0,
    'refundedAmount', 0,
    'outstandingAmount', 0,
    'paymentStateObserved', v_booking.payment_state,
    'paymentStateStale', v_booking.payment_state <> case
      when v_reservation.state = 'released' then 'released' else 'unpaid' end
  );
end;
$$;

create or replace function public.preview_superadmin_booking_decision_v1(
  p_booking_id uuid,
  p_actor_user_id text,
  p_decision text,
  p_refund_disposition text,
  p_refund_amount bigint,
  p_external_settlement_reference text,
  p_new_deadline_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_accounting jsonb;
  v_state text;
  v_wallet_effect text := 'none';
  v_wallet_amount bigint := 0;
  v_outstanding bigint := 0;
  v_to_status text;
begin
  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if v_actor_role is distinct from 'superadmin' then
    return jsonb_build_object('ok', false, 'code', 'SUPERADMIN_DECISION_FORBIDDEN');
  end if;
  if p_decision is null or p_decision not in (
    'confirm_ticketed', 'cancel', 'keep_on_hold',
    'extend_deadline', 'close_without_change'
  ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPERADMIN_DECISION');
  end if;
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  v_accounting := public.classify_superadmin_booking_accounting_v1(p_booking_id);
  if coalesce((v_accounting->>'ok')::boolean, false) is not true then
    return v_accounting;
  end if;
  v_state := v_accounting->>'accountingState';
  v_outstanding := coalesce((v_accounting->>'outstandingAmount')::bigint, 0);

  if p_decision = 'confirm_ticketed' then
    v_to_status := 'confirmed';
    v_wallet_effect := case v_state
      when 'paid' then 'none'
      when 'active_hold' then 'capture_hold'
      when 'unpaid' then 'direct_charge'
      else 'accounting_conflict'
    end;
    v_wallet_amount := case when v_state = 'paid' then 0
      else (v_accounting->>'expectedAmount')::bigint end;
  elsif p_decision = 'cancel' then
    v_to_status := 'cancelled';
    if v_state = 'active_hold' then
      v_wallet_effect := 'release_hold';
      v_wallet_amount := (v_accounting->>'expectedAmount')::bigint;
    elsif v_state = 'unpaid' then
      v_wallet_effect := 'none';
    elsif v_state = 'paid' and v_outstanding = 0 then
      v_wallet_effect := 'none';
    elsif v_state = 'paid' then
      if p_refund_disposition is null or p_refund_disposition not in (
        'full_refund', 'partial_refund', 'no_refund_due', 'externally_settled'
      ) then
        return jsonb_build_object('ok', false, 'code', 'REFUND_DECISION_REQUIRED');
      end if;
      if p_refund_disposition = 'full_refund' then
        v_wallet_effect := 'refund';
        v_wallet_amount := v_outstanding;
      elsif p_refund_disposition = 'partial_refund' then
        if p_refund_amount is null or p_refund_amount <= 0
           or p_refund_amount >= v_outstanding then
          return jsonb_build_object('ok', false, 'code', 'INVALID_PARTIAL_REFUND');
        end if;
        v_wallet_effect := 'refund';
        v_wallet_amount := p_refund_amount;
      elsif p_refund_disposition = 'no_refund_due' then
        v_wallet_effect := 'no_refund';
      else
        if nullif(btrim(coalesce(p_external_settlement_reference, '')), '') is null then
          return jsonb_build_object('ok', false, 'code', 'SETTLEMENT_REFERENCE_REQUIRED');
        end if;
        v_wallet_effect := 'externally_settled';
      end if;
    end if;
  elsif p_decision in ('keep_on_hold', 'extend_deadline') then
    if v_state = 'paid' then
      return jsonb_build_object('ok', false, 'code', 'PAID_BOOKING_CANNOT_BE_HELD');
    end if;
    if p_decision = 'keep_on_hold'
       and v_booking.ticketing_deadline_at is not null
       and v_booking.ticketing_deadline_at <= clock_timestamp() then
      return jsonb_build_object(
        'ok', false, 'code', 'EXPIRED_REQUIRES_DEADLINE_EXTENSION'
      );
    end if;
    if p_decision = 'extend_deadline'
       and (p_new_deadline_at is null or p_new_deadline_at <= clock_timestamp()) then
      return jsonb_build_object('ok', false, 'code', 'FUTURE_DEADLINE_REQUIRED');
    end if;
    v_to_status := 'on-hold';
    v_wallet_effect := 'preserve';
  else
    v_to_status := v_booking.status;
    v_wallet_effect := 'none';
  end if;

  return jsonb_build_object(
    'ok', true,
    'bookingId', v_booking.id,
    'bookingReference', v_booking.public_ref,
    'decision', p_decision,
    'fromStoredStatus', v_booking.status,
    'fromLifecycleStatus', public.resolve_booking_lifecycle(
      v_booking.status, v_booking.airlines_pnr,
      v_booking.ticketing_deadline_at, v_booking.operation_kind
    ),
    'toStoredStatus', v_to_status,
    'walletEffect', v_wallet_effect,
    'walletAmount', v_wallet_amount,
    'currency', v_accounting->>'currency',
    'accounting', v_accounting,
    'refundDisposition', p_refund_disposition,
    'newDeadlineAt', p_new_deadline_at
  );
end;
$$;

create or replace function public.execute_superadmin_booking_decision_v1(
  p_booking_id uuid,
  p_actor_user_id text,
  p_request_key text,
  p_decision text,
  p_refund_disposition text,
  p_refund_amount bigint,
  p_external_settlement_reference text,
  p_new_deadline_at timestamptz,
  p_note text,
  p_money_movement_confirmed boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing public.superadmin_booking_decisions;
  v_preview jsonb;
  v_accounting jsonb;
  v_accounting_state text;
  v_wallet_effect text;
  v_amount bigint;
  v_available_before bigint;
  v_hold_before bigint;
  v_from_lifecycle text;
  v_to_status text;
  v_payment_after text;
  v_event_id bigint;
  v_occurrence_number integer;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_booking_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or nullif(btrim(coalesce(p_request_key, '')), '') is null
     or p_request_key !~ '^superadmin-booking-decision:v1:[0-9a-f-]{36}$'
     or char_length(p_request_key) > 220
     or p_decision is null
     or p_decision not in (
       'confirm_ticketed', 'cancel', 'keep_on_hold',
       'extend_deadline', 'close_without_change'
     )
     or char_length(coalesce(p_note, '')) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPERADMIN_DECISION');
  end if;
  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if v_actor_role is distinct from 'superadmin' then
    return jsonb_build_object('ok', false, 'code', 'SUPERADMIN_DECISION_FORBIDDEN');
  end if;

  -- The booking lock serializes decisions for one booking. The globally unique
  -- request key then makes exact retries safe across bookings as well.
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select decision.* into v_existing
    from public.superadmin_booking_decisions decision
   where decision.request_key = p_request_key;
  if found then
    if v_existing.booking_id <> p_booking_id
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.decision <> p_decision then
      return jsonb_build_object('ok', false, 'code', 'DECISION_IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing.result || jsonb_build_object('ok', true, 'replay', true);
  end if;

  -- Preserve the established mutation lock order: booking -> operation ->
  -- case -> reservation -> wallet -> account.
  perform 1 from public.booking_operations operation
   where operation.booking_id = v_booking.id
     and operation.state in (
       'claimed', 'supplier_call_started',
       'awaiting_external_action', 'needs_reconciliation'
     )
   order by operation.id
   for update;
  perform 1 from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = v_booking.id
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     )
   order by reconciliation_case.id
   for update;
  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
      or (reservation.booking_id is null
        and reservation.booking_attempt_id = v_booking.attempt_id)
   order by reservation.booking_id nulls last
   limit 1
   for update;

  v_preview := public.preview_superadmin_booking_decision_v1(
    p_booking_id, p_actor_user_id, p_decision, p_refund_disposition,
    p_refund_amount, p_external_settlement_reference, p_new_deadline_at
  );
  if coalesce((v_preview->>'ok')::boolean, false) is not true then
    return v_preview;
  end if;
  v_accounting := v_preview->'accounting';
  v_accounting_state := v_accounting->>'accountingState';
  v_wallet_effect := v_preview->>'walletEffect';
  v_amount := coalesce((v_preview->>'walletAmount')::bigint, 0);
  v_to_status := v_preview->>'toStoredStatus';
  v_from_lifecycle := v_preview->>'fromLifecycleStatus';

  if v_wallet_effect in ('capture_hold', 'direct_charge', 'release_hold', 'refund')
     and p_money_movement_confirmed is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'MONEY_MOVEMENT_CONFIRMATION_REQUIRED',
      'walletEffect', v_wallet_effect,
      'walletAmount', v_amount,
      'currency', v_accounting->>'currency'
    );
  end if;

  if v_wallet_effect in ('capture_hold', 'release_hold', 'refund') then
    if v_reservation.id is null
       or v_reservation.id::text is distinct from v_accounting->>'reservationId' then
      return jsonb_build_object('ok', false, 'code', 'RESERVATION_CHANGED');
    end if;
    select wallet.* into v_wallet
      from public.wallets wallet
      join public.wallet_accounts account on account.wallet_id = wallet.id
     where account.id = v_reservation.wallet_account_id
     for update of wallet;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
    end if;
    select account.* into v_account
      from public.wallet_accounts account
     where account.id = v_reservation.wallet_account_id
       and account.wallet_id = v_wallet.id
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
    end if;
  elsif v_wallet_effect = 'direct_charge' then
    if v_booking.booking_owner_type is null
       or v_booking.booking_owner_key is null then
      return jsonb_build_object('ok', false, 'code', 'BOOKING_OWNER_REQUIRED');
    end if;
    select wallet.* into v_wallet
      from public.wallets wallet
     where wallet.owner_type = v_booking.booking_owner_type
       and wallet.owner_key = v_booking.booking_owner_key
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
    end if;
    select account.* into v_account
      from public.wallet_accounts account
     where account.wallet_id = v_wallet.id
       and account.currency = upper(v_booking.currency)
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
    end if;
  end if;

  if v_wallet_effect in ('capture_hold', 'release_hold') then
    if v_reservation.state not in ('active', 'reconciliation')
       or v_account.currency <> v_reservation.currency
       or v_account.hold_balance < v_reservation.amount
       or v_reservation.amount <> v_amount then
      return jsonb_build_object('ok', false, 'code', 'ACTIVE_HOLD_CHANGED');
    end if;
    v_available_before := v_account.available_balance;
    v_hold_before := v_account.hold_balance;
    if v_wallet_effect = 'capture_hold' then
      update public.wallet_accounts
         set hold_balance = hold_balance - v_amount
       where id = v_account.id;
      update public.wallet_reservations
         set booking_id = v_booking.id,
             booking_attempt_id = null,
             state = 'captured',
             issued_by_user_id = p_actor_user_id,
             captured_at = v_now,
             reconciliation_at = null,
             reconciliation_reason = null
       where id = v_reservation.id;
      insert into public.wallet_ledger_entries (
        wallet_account_id, transaction_type, amount, currency,
        available_before, available_after, hold_before, hold_after,
        booking_id, booking_reference, reservation_id, idempotency_key,
        created_by_user_id, created_by_role, remarks, metadata
      ) values (
        v_account.id, 'booking_confirm', v_amount, v_account.currency,
        v_available_before, v_available_before,
        v_hold_before, v_hold_before - v_amount,
        v_booking.id, v_booking.public_ref, v_reservation.id,
        p_request_key || ':capture', p_actor_user_id, 'superadmin',
        coalesce(nullif(btrim(p_note), ''), 'Super Admin confirmed ticketed'),
        jsonb_build_object(
          'decision', p_decision, 'accountingSource', 'active_hold',
          'userPayableAmount', v_amount,
          'supplierGrossAmount', v_booking.supplier_gross_amount,
          'evidenceRequired', false
        )
      );
    else
      update public.wallet_accounts
         set available_balance = available_balance + v_amount,
             hold_balance = hold_balance - v_amount
       where id = v_account.id;
      update public.wallet_reservations
         set booking_id = v_booking.id,
             booking_attempt_id = null,
             state = 'released',
             released_at = v_now,
             release_reason = left(coalesce(nullif(btrim(p_note), ''),
               'Super Admin cancelled booking'), 1000),
             reconciliation_at = null,
             reconciliation_reason = null
       where id = v_reservation.id;
      insert into public.wallet_ledger_entries (
        wallet_account_id, transaction_type, amount, currency,
        available_before, available_after, hold_before, hold_after,
        booking_id, booking_reference, reservation_id, idempotency_key,
        created_by_user_id, created_by_role, remarks, metadata
      ) values (
        v_account.id, 'hold_release', v_amount, v_account.currency,
        v_available_before, v_available_before + v_amount,
        v_hold_before, v_hold_before - v_amount,
        v_booking.id, v_booking.public_ref, v_reservation.id,
        p_request_key || ':release', p_actor_user_id, 'superadmin',
        coalesce(nullif(btrim(p_note), ''), 'Super Admin cancelled booking'),
        jsonb_build_object(
          'decision', p_decision, 'accountingSource', 'active_hold',
          'userPayableAmount', v_amount, 'evidenceRequired', false
        )
      );
    end if;
  elsif v_wallet_effect = 'direct_charge' then
    if v_wallet.status <> 'active' then
      return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
    end if;
    if v_account.available_balance < v_amount then
      return jsonb_build_object(
        'ok', false, 'code', 'INSUFFICIENT_FUNDS',
        'available', v_account.available_balance,
        'required', v_amount, 'currency', v_account.currency
      );
    end if;
    v_available_before := v_account.available_balance;
    v_hold_before := v_account.hold_balance;
    update public.wallet_accounts
       set available_balance = available_balance - v_amount
     where id = v_account.id;
    if v_reservation.id is null then
      insert into public.wallet_reservations (
        wallet_account_id, booking_id, amount, currency, state, cycle,
        requested_by_user_id, issued_by_user_id, captured_at
      ) values (
        v_account.id, v_booking.id, v_amount, v_account.currency,
        'captured', 1, p_actor_user_id, p_actor_user_id, v_now
      ) returning * into v_reservation;
    else
      update public.wallet_reservations
         set booking_id = v_booking.id,
             booking_attempt_id = null,
             wallet_account_id = v_account.id,
             amount = v_amount,
             currency = v_account.currency,
             state = 'captured',
             cycle = cycle + 1,
             requested_by_user_id = p_actor_user_id,
             issued_by_user_id = p_actor_user_id,
             captured_at = v_now,
             released_at = null,
             release_reason = null,
             reconciliation_at = null,
             reconciliation_reason = null
       where id = v_reservation.id
       returning * into v_reservation;
    end if;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'booking_confirm', v_amount, v_account.currency,
      v_available_before, v_available_before - v_amount,
      v_hold_before, v_hold_before,
      v_booking.id, v_booking.public_ref, v_reservation.id,
      p_request_key || ':charge', p_actor_user_id, 'superadmin',
      coalesce(nullif(btrim(p_note), ''), 'Super Admin confirmed ticketed'),
      jsonb_build_object(
        'decision', p_decision, 'accountingSource', 'direct_charge',
        'userPayableAmount', v_amount,
        'supplierGrossAmount', v_booking.supplier_gross_amount,
        'evidenceRequired', false
      )
    );
  elsif v_wallet_effect = 'refund' then
    if v_account.currency <> (v_accounting->>'currency')
       or v_account.id::text is distinct from v_accounting->>'walletAccountId'
       or v_amount <= 0
       or v_amount > (v_accounting->>'outstandingAmount')::bigint then
      return jsonb_build_object('ok', false, 'code', 'REFUND_ACCOUNTING_CHANGED');
    end if;
    v_available_before := v_account.available_balance;
    v_hold_before := v_account.hold_balance;
    update public.wallet_accounts
       set available_balance = available_balance + v_amount
     where id = v_account.id;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'refund', v_amount, v_account.currency,
      v_available_before, v_available_before + v_amount,
      v_hold_before, v_hold_before,
      v_booking.id, v_booking.public_ref, v_reservation.id,
      p_request_key || ':refund', p_actor_user_id, 'superadmin',
      coalesce(nullif(btrim(p_note), ''), 'Super Admin cancellation refund'),
      jsonb_build_object(
        'decision', p_decision,
        'financialDisposition', p_refund_disposition,
        'accountingSource', 'captured_ledger',
        'evidenceRequired', false
      )
    );
  end if;

  -- Finish any superseded active operation without deleting it.
  if p_decision <> 'close_without_change' then
    update public.booking_operations
       set state = 'failed',
           completed_at = coalesce(completed_at, v_now),
           error_code = 'SUPERADMIN_DECISION_SUPERSEDED',
           error_message = 'Superseded by an explicit Super Admin booking decision',
           supplier_evidence = supplier_evidence || jsonb_build_object(
             'superAdminDecision', p_decision,
             'decisionRequestKey', p_request_key,
             'evidenceRequired', false,
             'walletEffect', v_wallet_effect
           )
     where booking_id = v_booking.id
       and state in (
         'claimed', 'supplier_call_started',
         'awaiting_external_action', 'needs_reconciliation'
       );
  end if;

  if p_decision = 'confirm_ticketed' then
    v_payment_after := case
      when v_accounting_state = 'paid' then case
        when (v_accounting->>'refundedAmount')::bigint
          = (v_accounting->>'capturedAmount')::bigint then 'refunded'
        when (v_accounting->>'refundedAmount')::bigint > 0 then 'partially-refunded'
        else 'captured' end
      else 'captured'
    end;
    update public.flight_bookings
       set status = 'confirmed',
           active_operation_id = null,
           operation_kind = null,
           operation_reason = null,
           operation_request_id = null,
           operation_actor_user_id = null,
           operation_started_at = null,
           operation_prior_status = null,
           charged_wallet_account_id = coalesce(
             case when v_account.id is not null then v_account.id end,
             nullif(v_accounting->>'walletAccountId', '')::uuid,
             charged_wallet_account_id
           ),
           payment_state = v_payment_after,
           payment_amount = (v_accounting->>'expectedAmount')::bigint,
           captured_amount = case when v_accounting_state = 'paid'
             then (v_accounting->>'capturedAmount')::bigint
             else (v_accounting->>'expectedAmount')::bigint end,
           refunded_amount = case when v_accounting_state = 'paid'
             then (v_accounting->>'refundedAmount')::bigint else 0 end,
           issued_by_user_id = p_actor_user_id,
           issued_at = coalesce(issued_at, v_now),
           booking_status = coalesce(nullif(booking_status, ''), 'Confirmed')
     where id = v_booking.id;
  elsif p_decision = 'cancel' then
    v_payment_after := case
      when v_wallet_effect = 'release_hold' then 'released'
      when v_accounting_state = 'unpaid' then 'unpaid'
      when v_accounting_state = 'paid' then case
        when (v_accounting->>'refundedAmount')::bigint +
          case when v_wallet_effect = 'refund' then v_amount else 0 end
          = (v_accounting->>'capturedAmount')::bigint then 'refunded'
        when (v_accounting->>'refundedAmount')::bigint +
          case when v_wallet_effect = 'refund' then v_amount else 0 end > 0
          then 'partially-refunded'
        else 'captured' end
      else v_booking.payment_state
    end;
    update public.flight_bookings
       set status = 'cancelled',
           active_operation_id = null,
           operation_kind = null,
           operation_reason = null,
           operation_request_id = null,
           operation_actor_user_id = null,
           operation_started_at = null,
           operation_prior_status = null,
           charged_wallet_account_id = coalesce(
             nullif(v_accounting->>'walletAccountId', '')::uuid,
             charged_wallet_account_id
           ),
           payment_state = v_payment_after,
           payment_amount = case when v_accounting_state = 'paid'
             then (v_accounting->>'capturedAmount')::bigint
             else payment_amount end,
           captured_amount = case when v_accounting_state = 'paid'
             then (v_accounting->>'capturedAmount')::bigint else 0 end,
           refunded_amount = case when v_accounting_state = 'paid'
             then (v_accounting->>'refundedAmount')::bigint +
               case when v_wallet_effect = 'refund' then v_amount else 0 end
             else 0 end,
           cancelled_at = coalesce(cancelled_at, v_now),
           cancelled_by = p_actor_user_id,
           cancel_reason = left(coalesce(nullif(btrim(p_note), ''),
             'Super Admin decision'), 1000)
     where id = v_booking.id;
  elsif p_decision in ('keep_on_hold', 'extend_deadline') then
    update public.flight_bookings
       set status = 'on-hold',
           active_operation_id = null,
           operation_kind = null,
           operation_reason = null,
           operation_request_id = null,
           operation_actor_user_id = null,
           operation_started_at = null,
           operation_prior_status = null,
           payment_state = case when v_accounting_state = 'active_hold'
             then 'held'
             when v_reservation.state = 'released' then 'released'
             else 'unpaid' end,
           charged_wallet_account_id = case
             when v_accounting_state = 'active_hold'
               then nullif(v_accounting->>'walletAccountId', '')::uuid
             else charged_wallet_account_id end,
           ticketing_deadline_at = case when p_decision = 'extend_deadline'
             then p_new_deadline_at else ticketing_deadline_at end,
           local_ticketing_deadline_at = case when p_decision = 'extend_deadline'
             then p_new_deadline_at else local_ticketing_deadline_at end,
           deadline_source = case when p_decision = 'extend_deadline'
             then 'local_approved' else deadline_source end
     where id = v_booking.id;
  end if;

  update public.booking_reconciliation_cases
     set state = case when p_decision = 'close_without_change'
       then 'closed_no_change' else 'resolved' end,
         resolution_outcome = 'superadmin_' || p_decision,
         resolution = jsonb_build_object(
           'version', 1,
           'resolutionKind', 'superadmin_booking_decision',
           'decision', p_decision,
           'decisionRequestKey', p_request_key,
           'actorRole', 'superadmin',
           'evidenceRequired', false,
           'accounting', v_accounting,
           'walletEffect', v_wallet_effect,
           'walletAmount', v_amount,
           'refundDisposition', p_refund_disposition,
           'externalSettlementReference', p_external_settlement_reference
         ),
         resolution_reason = nullif(btrim(p_note), ''),
         resolved_by_user_id = p_actor_user_id,
         resolved_at = v_now,
         closed_at = case when p_decision = 'close_without_change'
           then v_now else closed_at end,
         version = version + 1
   where subject_booking_id = v_booking.id
     and state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     );

  if p_decision = 'close_without_change' then
    v_to_status := v_booking.status;
  end if;
  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = case v_to_status
       when 'confirmed' then 'confirmed'
       when 'cancelled' then 'cancelled'
       else public.resolve_booking_lifecycle(
         v_to_status, v_booking.airlines_pnr,
         case when p_decision = 'extend_deadline' then p_new_deadline_at
           else v_booking.ticketing_deadline_at end,
         case when p_decision = 'close_without_change'
           then v_booking.operation_kind else null end
       ) end;

  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle,
    case v_to_status
      when 'confirmed' then 'confirmed'
      when 'cancelled' then 'cancelled'
      else public.resolve_booking_lifecycle(
        v_to_status, v_booking.airlines_pnr,
        case when p_decision = 'extend_deadline' then p_new_deadline_at
          else v_booking.ticketing_deadline_at end,
        case when p_decision = 'close_without_change'
          then v_booking.operation_kind else null end
      ) end,
    v_booking.status, v_to_status, null, null,
    p_actor_user_id, 'SuperAdminDecision',
    jsonb_build_object(
      'decision', p_decision,
      'actorRole', 'superadmin',
      'evidenceRequired', false,
      'accountingState', v_accounting_state,
      'walletEffect', v_wallet_effect,
      'walletAmount', v_amount
    ),
    p_request_key || ':status', v_occurrence_number,
    v_now, v_now,
    jsonb_strip_nulls(jsonb_build_object(
      'version', 1,
      'decision', p_decision,
      'walletEffect', v_wallet_effect,
      'walletAmount', v_amount,
      'currency', v_accounting->>'currency',
      'financialDisposition', p_refund_disposition,
      'newDeadlineAt', p_new_deadline_at,
      'notificationDisposition', case when p_decision = 'close_without_change'
        then 'audit_only' else null end,
      'suppressionReason', case when p_decision = 'close_without_change'
        then 'case_only_repair' else null end
    )), 1
  ) returning id into v_event_id;

  v_result := jsonb_build_object(
    'ok', true,
    'replay', false,
    'bookingId', v_booking.id,
    'bookingReference', v_booking.public_ref,
    'decision', p_decision,
    'bookingStatus', v_to_status,
    'walletEffect', v_wallet_effect,
    'walletAmount', v_amount,
    'currency', v_accounting->>'currency',
    'accountingStateBefore', v_accounting_state,
    'lifecycleEventId', v_event_id,
    'paymentState', v_payment_after
  );

  insert into public.superadmin_booking_decisions (
    booking_id, request_key, actor_user_id, actor_role, decision, note,
    request_snapshot, accounting_snapshot, result
  ) values (
    v_booking.id, p_request_key, p_actor_user_id, 'superadmin', p_decision,
    nullif(btrim(p_note), ''),
    jsonb_strip_nulls(jsonb_build_object(
      'decision', p_decision,
      'refundDisposition', p_refund_disposition,
      'refundAmount', p_refund_amount,
      'externalSettlementReference', p_external_settlement_reference,
      'newDeadlineAt', p_new_deadline_at,
      'moneyMovementConfirmed', p_money_movement_confirmed
    )),
    v_accounting, v_result
  );
  return v_result;
end;
$$;

revoke all on function public.classify_superadmin_booking_accounting_v1(uuid),
  public.preview_superadmin_booking_decision_v1(uuid,text,text,text,bigint,text,timestamptz),
  public.execute_superadmin_booking_decision_v1(uuid,text,text,text,text,bigint,text,timestamptz,text,boolean),
  public.deny_superadmin_booking_decision_mutation_v1()
  from public, anon, authenticated;
grant execute on function public.classify_superadmin_booking_accounting_v1(uuid),
  public.preview_superadmin_booking_decision_v1(uuid,text,text,text,bigint,text,timestamptz),
  public.execute_superadmin_booking_decision_v1(uuid,text,text,text,text,bigint,text,timestamptz,text,boolean)
  to service_role;

comment on table public.superadmin_booking_decisions is
  'Immutable one-step Super Admin booking decisions, including the reservation/ledger accounting snapshot and atomic result.';
comment on function public.classify_superadmin_booking_accounting_v1(uuid) is
  'Classifies paid, active-hold, or unpaid truth from a matching reservation and immutable ledger. payment_state is only a stale-state signal.';
comment on function public.preview_superadmin_booking_decision_v1(uuid,text,text,text,bigint,text,timestamptz) is
  'Read-only Super Admin decision preview showing the exact wallet effect without requiring supplier evidence.';
comment on function public.execute_superadmin_booking_decision_v1(uuid,text,text,text,text,bigint,text,timestamptz,text,boolean) is
  'Atomically applies one evidence-optional Super Admin booking decision. Actual reservation/ledger truth controls charge, capture, release, refund, or no movement; inconsistent accounting fails closed.';


-- SOURCE: 0107_superadmin_issue_resolution.sql
-- Super Admin resolution for stuck ordinary B2B/B2C Issue Now bookings.
--
-- This is deliberately separate from Instant Purchase, IMP/EXP, Manual Import,
-- deposits, and the generic maker-checker adjustment workflow. Proven local
-- reservation/ledger truth always uses the normal path. A manually verified
-- supplier exception never invents a reservation and records its own immutable
-- resolution plus a distinct append-only ledger entry.

-- 1. Distinct manual-resolution ledger vocabulary --------------------------

alter table public.wallet_ledger_entries
  drop constraint if exists wallet_ledger_entries_transaction_type_check;
alter table public.wallet_ledger_entries
  add constraint wallet_ledger_entries_transaction_type_check
  check (transaction_type in (
    'deposit', 'booking_hold', 'booking_confirm', 'hold_release', 'refund',
    'manual_credit', 'manual_debit', 'adjustment', 'reversal',
    'superadmin_resolution_credit',
    'superadmin_resolution_debit',
    'superadmin_resolution_hold_release',
    'superadmin_resolution_hold_capture'
  ));

-- 2. Durable Super Admin deadline authority --------------------------------

create table if not exists public.superadmin_booking_deadline_overrides (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.flight_bookings(id) on delete restrict,
  request_key text not null unique
    check (char_length(request_key) between 1 and 220),
  effective_deadline_at timestamptz not null,
  supplier_deadline_snapshot timestamptz,
  supplier_time_limit_snapshot text,
  actor_user_id text not null,
  actor_role text not null check (actor_role = 'superadmin'),
  note text,
  created_at timestamptz not null default clock_timestamp()
);

create index if not exists superadmin_deadline_overrides_booking_created_idx
  on public.superadmin_booking_deadline_overrides (booking_id, created_at desc);

-- Forward declaration for the automatic preview functions below. The complete
-- body replaces this declaration after the manual-resolution schema exists.
create or replace function public.superadmin_issue_resolution_context_v2(
  p_booking_id uuid,
  p_actor_user_id text
)
returns jsonb
language sql
security definer
set search_path = public
as $$
  select jsonb_build_object('ok', false, 'code', 'SETUP_IN_PROGRESS')
$$;

alter table public.flight_bookings
  add column if not exists active_superadmin_deadline_override_id uuid;

do $$
begin
  if not exists (
    select 1 from pg_constraint
     where conname = 'flight_bookings_active_superadmin_deadline_override_fk'
  ) then
    alter table public.flight_bookings
      add constraint flight_bookings_active_superadmin_deadline_override_fk
      foreign key (active_superadmin_deadline_override_id)
      references public.superadmin_booking_deadline_overrides(id)
      on delete restrict not valid;
  end if;
end;
$$;

-- 5. Contextual automatic preview -------------------------------------------

create or replace function public.preview_superadmin_issue_resolution_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_supplier_outcome text,
  p_refund_disposition text,
  p_refund_amount bigint,
  p_external_settlement_reference text,
  p_new_deadline_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_context jsonb;
  v_accounting jsonb;
  v_state text;
  v_effect text := 'none';
  v_amount bigint := 0;
  v_wallet jsonb;
  v_available_before bigint;
  v_available_after bigint;
  v_hold_before bigint;
  v_hold_after bigint;
  v_protected_hold bigint := 0;
  v_legacy_preview jsonb;
  v_to_status text;
begin
  v_context := public.superadmin_issue_resolution_context_v2(
    p_booking_id, p_actor_user_id
  );
  if coalesce((v_context->>'ok')::boolean, false) is not true then
    return v_context;
  end if;
  if p_supplier_outcome not in ('ticket_issued', 'still_valid', 'not_issued') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPPLIER_OUTCOME');
  end if;
  v_accounting := v_context->'accounting';
  if coalesce((v_accounting->>'ok')::boolean, false) is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'MANUAL_RESOLUTION_REQUIRED',
      'manualAllowed', true,
      'accounting', v_accounting,
      'context', v_context
    );
  end if;
  v_state := v_accounting->>'accountingState';
  v_wallet := v_context->'wallet';
  v_available_before := coalesce((v_wallet->>'availableBalance')::bigint, 0);
  v_hold_before := coalesce((v_wallet->>'holdBalance')::bigint, 0);
  v_available_after := v_available_before;
  v_hold_after := v_hold_before;
  if v_state = 'active_hold' then
    select coalesce(sum(reservation.amount), 0)::bigint
      into v_protected_hold
      from public.wallet_reservations reservation
     where reservation.wallet_account_id =
         (v_accounting->>'walletAccountId')::uuid
       and reservation.state in ('active', 'reconciliation')
       and reservation.id <> (v_accounting->>'reservationId')::uuid;
    if v_hold_before <
       (v_accounting->>'expectedAmount')::bigint + v_protected_hold then
      return jsonb_build_object(
        'ok', false, 'code', 'ACTIVE_HOLD_ACCOUNTING_CONFLICT',
        'hold', v_hold_before,
        'bookingHold', (v_accounting->>'expectedAmount')::bigint,
        'protectedHold', v_protected_hold
      );
    end if;
  end if;

  if p_supplier_outcome = 'ticket_issued' then
    v_to_status := 'confirmed';
    if v_state = 'paid' then
      v_effect := 'none';
    elsif v_state = 'active_hold' then
      v_effect := 'capture_hold';
      v_amount := (v_accounting->>'expectedAmount')::bigint;
      v_hold_after := v_hold_before - v_amount;
    else
      return jsonb_build_object(
        'ok', false, 'code', 'MANUAL_RESOLUTION_REQUIRED',
        'manualAllowed', true,
        'reason', 'NO_LOCAL_CAPTURE_SOURCE',
        'accounting', v_accounting,
        'context', v_context
      );
    end if;
  elsif p_supplier_outcome = 'still_valid' then
    v_to_status := 'on-hold';
    if v_state = 'paid' then
      return jsonb_build_object('ok', false, 'code', 'PAID_BOOKING_CANNOT_BE_HELD');
    elsif v_state = 'active_hold' then
      v_effect := 'release_hold';
      v_amount := (v_accounting->>'expectedAmount')::bigint;
      v_available_after := v_available_before + v_amount;
      v_hold_after := v_hold_before - v_amount;
    end if;
    if (v_context->>'lifecycleStatus') = 'expired'
       and p_new_deadline_at is null then
      return jsonb_build_object('ok', false, 'code', 'FUTURE_DEADLINE_REQUIRED');
    end if;
    if p_new_deadline_at is not null
       and p_new_deadline_at <= clock_timestamp() then
      return jsonb_build_object('ok', false, 'code', 'FUTURE_DEADLINE_REQUIRED');
    end if;
  else
    v_to_status := 'cancelled';
    if v_state = 'active_hold' then
      v_effect := 'release_hold';
      v_amount := (v_accounting->>'expectedAmount')::bigint;
      v_available_after := v_available_before + v_amount;
      v_hold_after := v_hold_before - v_amount;
    elsif v_state = 'paid' then
      v_legacy_preview := public.preview_superadmin_booking_decision_v1(
        p_booking_id, p_actor_user_id, 'cancel', p_refund_disposition,
        p_refund_amount, p_external_settlement_reference, null
      );
      if coalesce((v_legacy_preview->>'ok')::boolean, false) is not true then
        return v_legacy_preview;
      end if;
      v_effect := v_legacy_preview->>'walletEffect';
      v_amount := coalesce((v_legacy_preview->>'walletAmount')::bigint, 0);
      if v_effect = 'refund' then
        v_available_after := v_available_before + v_amount;
      end if;
    end if;
  end if;

  if v_effect in ('capture_hold', 'release_hold')
     and (v_wallet is null or nullif(v_wallet->>'accountId', '') is null) then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;

  return jsonb_build_object(
    'ok', true,
    'mode', 'automatic_local_accounting',
    'bookingId', v_context->>'bookingId',
    'bookingReference', v_context->>'bookingReference',
    'fromStatus', v_context->>'bookingStatus',
    'fromLifecycleStatus', v_context->>'lifecycleStatus',
    'toStatus', v_to_status,
    'supplierOutcome', p_supplier_outcome,
    'walletEffect', v_effect,
    'walletAmount', v_amount,
    'currency', v_accounting->>'currency',
    'availableBefore', v_available_before,
    'availableAfter', v_available_after,
    'holdBefore', v_hold_before,
    'holdAfter', v_hold_after,
    'protectedHold', v_protected_hold,
    'newDeadlineAt', p_new_deadline_at,
    'accounting', v_accounting,
    'wallet', v_wallet,
    'manualAllowed', false
  );
end;
$$;

-- Normal restore/cancel when local truth is either a real Hold or proven no
-- financial footprint. Restore intentionally releases an Issue Now Hold.
create or replace function public.execute_superadmin_hold_outcome_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_request_key text,
  p_supplier_outcome text,
  p_new_deadline_at timestamptz,
  p_note text,
  p_money_movement_confirmed boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_existing public.superadmin_booking_decisions;
  v_preview jsonb;
  v_accounting jsonb;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_amount bigint := 0;
  v_effect text;
  v_before_available bigint;
  v_before_hold bigint;
  v_to_status text;
  v_from_lifecycle text;
  v_after_lifecycle text;
  v_event_id bigint;
  v_occurrence integer;
  v_override_id uuid;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_supplier_outcome not in ('still_valid', 'not_issued')
     or p_request_key !~ '^superadmin-booking-decision:v1:[0-9a-f-]{36}$'
     or char_length(coalesce(p_note, '')) > 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPERADMIN_DECISION');
  end if;
  select * into v_booking from public.flight_bookings
   where id = p_booking_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select * into v_existing from public.superadmin_booking_decisions
   where request_key = p_request_key;
  if found then
    if v_existing.booking_id <> p_booking_id
       or v_existing.actor_user_id <> p_actor_user_id then
      return jsonb_build_object('ok', false, 'code', 'DECISION_IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing.result || jsonb_build_object('ok', true, 'replay', true);
  end if;

  perform 1 from public.booking_operations operation
   where operation.booking_id = p_booking_id
     and operation.state in (
       'claimed', 'supplier_call_started',
       'awaiting_external_action', 'needs_reconciliation'
     ) order by operation.id for update;
  perform 1 from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = p_booking_id
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     ) order by reconciliation_case.id for update;
  select * into v_reservation from public.wallet_reservations reservation
   where reservation.booking_id = p_booking_id
      or (reservation.booking_id is null
        and reservation.booking_attempt_id = v_booking.attempt_id)
   order by reservation.booking_id nulls last limit 1 for update;

  v_preview := public.preview_superadmin_issue_resolution_v2(
    p_booking_id, p_actor_user_id, p_supplier_outcome,
    null, null, null, p_new_deadline_at
  );
  if coalesce((v_preview->>'ok')::boolean, false) is not true then
    return v_preview;
  end if;
  v_accounting := v_preview->'accounting';
  if v_accounting->>'accountingState' not in ('active_hold', 'unpaid') then
    return jsonb_build_object('ok', false, 'code', 'ACCOUNTING_STATE_CHANGED');
  end if;
  v_effect := v_preview->>'walletEffect';
  v_amount := coalesce((v_preview->>'walletAmount')::bigint, 0);
  if v_effect = 'release_hold' and p_money_movement_confirmed is not true then
    return jsonb_build_object(
      'ok', false, 'code', 'MONEY_MOVEMENT_CONFIRMATION_REQUIRED'
    );
  end if;

  if v_effect = 'release_hold' then
    if v_reservation.id is null
       or v_reservation.id::text is distinct from v_accounting->>'reservationId'
       or v_reservation.state not in ('active', 'reconciliation')
       or v_reservation.amount <> v_amount then
      return jsonb_build_object('ok', false, 'code', 'RESERVATION_CHANGED');
    end if;
    select wallet.* into v_wallet from public.wallets wallet
      join public.wallet_accounts account on account.wallet_id = wallet.id
     where account.id = v_reservation.wallet_account_id for update of wallet;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
    end if;
    select * into v_account from public.wallet_accounts account
     where account.id = v_reservation.wallet_account_id
       and account.wallet_id = v_wallet.id for update;
    if not found or v_account.hold_balance < v_amount then
      return jsonb_build_object('ok', false, 'code', 'ACTIVE_HOLD_CHANGED');
    end if;
    v_before_available := v_account.available_balance;
    v_before_hold := v_account.hold_balance;
    update public.wallet_accounts set
      available_balance = available_balance + v_amount,
      hold_balance = hold_balance - v_amount
    where id = v_account.id;
    update public.wallet_reservations set
      booking_id = v_booking.id, booking_attempt_id = null,
      state = 'released', released_at = v_now,
      release_reason = left(coalesce(nullif(btrim(p_note), ''),
        'Super Admin Issue Now resolution'), 1000),
      reconciliation_at = null, reconciliation_reason = null
    where id = v_reservation.id;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'hold_release', v_amount, v_account.currency,
      v_before_available, v_before_available + v_amount,
      v_before_hold, v_before_hold - v_amount,
      v_booking.id, v_booking.public_ref, v_reservation.id,
      p_request_key || ':release', p_actor_user_id, 'superadmin',
      coalesce(nullif(btrim(p_note), ''), 'Super Admin Issue Now resolution'),
      jsonb_build_object(
        'resolutionMode', 'automatic_local_accounting',
        'supplierOutcome', p_supplier_outcome,
        'evidenceRequired', false
      )
    );
  end if;

  v_from_lifecycle := public.resolve_superadmin_issue_lifecycle_v2(
    v_booking.status, v_booking.legacy_operational, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  v_to_status := case when p_supplier_outcome = 'still_valid'
    then 'on-hold' else 'cancelled' end;
  if p_supplier_outcome = 'still_valid' and p_new_deadline_at is not null then
    insert into public.superadmin_booking_deadline_overrides (
      booking_id, request_key, effective_deadline_at,
      supplier_deadline_snapshot, supplier_time_limit_snapshot,
      actor_user_id, actor_role, note
    ) values (
      v_booking.id, p_request_key || ':deadline', p_new_deadline_at,
      v_booking.supplier_ticketing_deadline_at,
      v_booking.supplier_ticketing_time_limit,
      p_actor_user_id, 'superadmin', nullif(btrim(p_note), '')
    ) returning id into v_override_id;
  end if;

  update public.booking_operations set
    state = 'failed', completed_at = coalesce(completed_at, v_now),
    error_code = 'SUPERADMIN_DECISION_SUPERSEDED',
    error_message = 'Superseded by an explicit Super Admin Issue Now resolution',
    supplier_evidence = supplier_evidence || jsonb_build_object(
      'supplierOutcome', p_supplier_outcome,
      'decisionRequestKey', p_request_key,
      'evidenceRequired', false, 'walletEffect', v_effect
    )
  where booking_id = v_booking.id
    and state in (
      'claimed', 'supplier_call_started',
      'awaiting_external_action', 'needs_reconciliation'
    );

  update public.flight_bookings set
    status = v_to_status,
    active_operation_id = null, operation_kind = null,
    operation_reason = null, operation_request_id = null,
    operation_actor_user_id = null, operation_started_at = null,
    operation_prior_status = null,
    charged_wallet_account_id = case when v_effect = 'release_hold'
      then v_account.id else charged_wallet_account_id end,
    payment_state = case when v_effect = 'release_hold' then 'released'
      when v_accounting->>'reservationState' = 'released' then 'released'
      else 'unpaid' end,
    active_superadmin_deadline_override_id = case
      when p_supplier_outcome = 'still_valid' and v_override_id is not null
        then v_override_id
      when p_supplier_outcome = 'not_issued' then null
      else active_superadmin_deadline_override_id end,
    local_ticketing_deadline_at = case
      when p_supplier_outcome = 'still_valid' and p_new_deadline_at is not null
        then p_new_deadline_at else local_ticketing_deadline_at end,
    ticketing_deadline_at = case
      when p_supplier_outcome = 'still_valid' and p_new_deadline_at is not null
        then p_new_deadline_at else ticketing_deadline_at end,
    deadline_source = case
      when p_supplier_outcome = 'still_valid' and p_new_deadline_at is not null
        then 'superadmin_override' else deadline_source end,
    cancelled_at = case when p_supplier_outcome = 'not_issued'
      then coalesce(cancelled_at, v_now) else cancelled_at end,
    cancelled_by = case when p_supplier_outcome = 'not_issued'
      then p_actor_user_id else cancelled_by end,
    cancel_reason = case when p_supplier_outcome = 'not_issued'
      then left(coalesce(nullif(btrim(p_note), ''),
        'Super Admin Issue Now resolution'), 1000) else cancel_reason end
  where id = v_booking.id;

  update public.booking_reconciliation_cases set
    state = 'resolved',
    resolution_outcome = 'superadmin_issue_' || p_supplier_outcome,
    resolution = jsonb_build_object(
      'version', 2, 'resolutionKind', 'superadmin_issue_resolution',
      'supplierOutcome', p_supplier_outcome,
      'decisionRequestKey', p_request_key,
      'evidenceRequired', false,
      'accounting', v_accounting,
      'walletEffect', v_effect, 'walletAmount', v_amount
    ),
    resolution_reason = nullif(btrim(p_note), ''),
    resolved_by_user_id = p_actor_user_id,
    resolved_at = v_now, version = version + 1
  where subject_booking_id = v_booking.id
    and state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    );

  v_after_lifecycle := case when v_to_status = 'cancelled' then 'cancelled'
    else public.resolve_superadmin_issue_lifecycle_v2(
      v_to_status, v_booking.legacy_operational, v_booking.airlines_pnr,
      coalesce(p_new_deadline_at, v_booking.ticketing_deadline_at), null
    ) end;
  select count(*)::integer + 1 into v_occurrence
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = v_after_lifecycle;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after,
    actor_user_id, supplier_operation, supplier_evidence,
    idempotency_key, occurrence_number, effective_at, observed_at,
    event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle, v_after_lifecycle,
    v_booking.status, v_to_status, p_actor_user_id,
    'SuperAdminIssueResolution', jsonb_build_object(
      'supplierOutcome', p_supplier_outcome, 'evidenceRequired', false,
      'walletEffect', v_effect, 'walletAmount', v_amount
    ), p_request_key || ':status', v_occurrence, v_now, v_now,
    jsonb_strip_nulls(jsonb_build_object(
      'version', 2, 'supplierOutcome', p_supplier_outcome,
      'walletEffect', v_effect, 'walletAmount', v_amount,
      'newDeadlineAt', p_new_deadline_at,
      'notificationDisposition', case
        when v_from_lifecycle = v_after_lifecycle then 'audit_only'
        else null end,
      'suppressionReason', case
        when v_from_lifecycle = v_after_lifecycle
          then 'superadmin_same_status_resolution' else null end
    )), 2
  ) returning id into v_event_id;

  v_result := jsonb_build_object(
    'ok', true, 'replay', false,
    'bookingId', v_booking.id, 'bookingReference', v_booking.public_ref,
    'supplierOutcome', p_supplier_outcome,
    'bookingStatus', v_to_status, 'walletEffect', v_effect,
    'walletAmount', v_amount, 'currency', v_accounting->>'currency',
    'accountingStateBefore', v_accounting->>'accountingState',
    'lifecycleEventId', v_event_id
  );
  insert into public.superadmin_booking_decisions (
    booking_id, request_key, actor_user_id, actor_role, decision, note,
    request_snapshot, accounting_snapshot, result
  ) values (
    v_booking.id, p_request_key, p_actor_user_id, 'superadmin',
    case when p_supplier_outcome = 'still_valid'
      then 'keep_on_hold' else 'cancel' end,
    nullif(btrim(p_note), ''),
    jsonb_strip_nulls(jsonb_build_object(
      'version', 2, 'supplierOutcome', p_supplier_outcome,
      'newDeadlineAt', p_new_deadline_at,
      'moneyMovementConfirmed', p_money_movement_confirmed
    )), v_accounting, v_result
  );
  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, metadata
  ) values (
    p_actor_user_id, 'superadmin', 'booking.superadmin_issue_resolution',
    'flight_booking', v_booking.id::text, 'succeeded',
    jsonb_build_object(
      'requestKey', p_request_key, 'supplierOutcome', p_supplier_outcome,
      'resolutionMode', 'automatic_local_accounting',
      'walletEffect', v_effect, 'walletAmount', v_amount
    )
  );
  return v_result;
end;
$$;


alter table public.flight_bookings
  drop constraint if exists flight_bookings_deadline_source_check;
alter table public.flight_bookings
  add constraint flight_bookings_deadline_source_check
  check (
    deadline_source is null
    or deadline_source in (
      'supplier', 'pnr_call', 'assumed', 'local_approved',
      'superadmin_override'
    )
  );

-- Retained rows keep legacy_operational=true and therefore remain excluded
-- from normal lifecycle views/workers. The explicit Super Admin resolver may,
-- however, store one of the modern decided outcomes on such a row.
alter table public.flight_bookings
  drop constraint if exists flight_bookings_status_check;
alter table public.flight_bookings
  add constraint flight_bookings_status_check
  check (
    (
      legacy_operational and status in (
        'draft', 'submitting', 'held', 'ticketed', 'failed', 'unknown',
        'on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled'
      )
    )
    or (
      not legacy_operational and status in (
        'on-hold', 'pending', 'in-progress', 'confirmed', 'cancelled'
      )
    )
  );

create or replace function public.resolve_superadmin_issue_lifecycle_v2(
  p_status text,
  p_legacy_operational boolean,
  p_airlines_pnr jsonb,
  p_ticketing_deadline_at timestamptz,
  p_operation_kind text
)
returns text
language sql
stable
set search_path = public
as $$
  select case
    when not p_legacy_operational then public.resolve_booking_lifecycle(
      p_status, p_airlines_pnr, p_ticketing_deadline_at, p_operation_kind
    )
    when p_status in ('ticketed', 'confirmed') then 'confirmed'
    when p_status in ('failed', 'cancelled') then 'cancelled'
    when p_status in ('submitting', 'unknown', 'in-progress')
      or p_operation_kind is not null then 'in-progress'
    when p_status in ('draft', 'pending') then 'pending'
    when p_status in ('held', 'on-hold')
      and not public.jsonb_is_nonempty_array(p_airlines_pnr) then 'unconfirmed'
    when p_status in ('held', 'on-hold')
      and p_ticketing_deadline_at is not null
      and p_ticketing_deadline_at <= now() then 'expired'
    else 'on-hold'
  end
$$;

create or replace function public.prevent_superadmin_resolution_mutation_v2()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'Super Admin resolution records are immutable'
    using errcode = '55000';
end;
$$;

drop trigger if exists superadmin_booking_deadline_overrides_immutable
  on public.superadmin_booking_deadline_overrides;
create trigger superadmin_booking_deadline_overrides_immutable
  before update or delete on public.superadmin_booking_deadline_overrides
  for each row execute function public.prevent_superadmin_resolution_mutation_v2();

-- An active Super Admin deadline is the effective deadline. Supplier writers
-- continue updating supplier_* columns and append-only observations, but cannot
-- overwrite the active local authority. Terminal booking state clears only the
-- active pointer; the immutable override remains readable.
create or replace function public.enforce_booking_deadline_authority_v2()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_override_deadline timestamptz;
  v_local_authority_write boolean;
  v_explicit_supplier_write boolean;
  v_legacy_deadline_write boolean;
begin
  if new.status in ('confirmed', 'cancelled') then
    new.active_superadmin_deadline_override_id := null;
  end if;

  if tg_op = 'INSERT' then
    new.supplier_ticketing_time_limit := coalesce(
      new.supplier_ticketing_time_limit, new.ticketing_time_limit
    );
    new.supplier_ticketing_deadline_at := coalesce(
      new.supplier_ticketing_deadline_at, new.ticketing_deadline_at
    );
    new.supplier_deadline_source := coalesce(
      new.supplier_deadline_source, new.deadline_source, 'booking_create'
    );
  else
    v_local_authority_write :=
      new.active_local_time_limit_request_id is distinct from
        old.active_local_time_limit_request_id
      or new.local_ticketing_deadline_at is distinct from
        old.local_ticketing_deadline_at
      or new.active_superadmin_deadline_override_id is distinct from
        old.active_superadmin_deadline_override_id;
    v_explicit_supplier_write :=
      new.supplier_ticketing_time_limit is distinct from
        old.supplier_ticketing_time_limit
      or new.supplier_ticketing_deadline_at is distinct from
        old.supplier_ticketing_deadline_at
      or new.supplier_deadline_source is distinct from old.supplier_deadline_source;
    v_legacy_deadline_write :=
      new.ticketing_time_limit is distinct from old.ticketing_time_limit
      or new.ticketing_deadline_at is distinct from old.ticketing_deadline_at
      or new.deadline_source is distinct from old.deadline_source;

    if not v_local_authority_write
       and not v_explicit_supplier_write
       and v_legacy_deadline_write then
      new.supplier_ticketing_time_limit := new.ticketing_time_limit;
      new.supplier_ticketing_deadline_at := new.ticketing_deadline_at;
      new.supplier_deadline_source := coalesce(
        new.deadline_source, 'legacy_supplier_writer'
      );
    end if;
  end if;

  if new.active_superadmin_deadline_override_id is not null then
    select deadline_override.effective_deadline_at
      into v_override_deadline
      from public.superadmin_booking_deadline_overrides deadline_override
     where deadline_override.id = new.active_superadmin_deadline_override_id
       and deadline_override.booking_id = new.id;
    if not found then
      raise exception 'active Super Admin deadline override does not match booking'
        using errcode = '23514';
    end if;
    new.local_ticketing_deadline_at := v_override_deadline;
    new.ticketing_deadline_at := v_override_deadline;
    new.ticketing_time_limit := new.supplier_ticketing_time_limit;
    new.deadline_source := 'superadmin_override';
  elsif new.active_local_time_limit_request_id is not null then
    new.ticketing_deadline_at := new.local_ticketing_deadline_at;
    new.deadline_source := 'local_approved';
    new.ticketing_time_limit := new.supplier_ticketing_time_limit;
  elsif tg_op = 'UPDATE' and (
    v_local_authority_write or v_explicit_supplier_write or v_legacy_deadline_write
  ) then
    new.ticketing_time_limit := new.supplier_ticketing_time_limit;
    new.ticketing_deadline_at := new.supplier_ticketing_deadline_at;
    new.deadline_source := case
      when new.supplier_ticketing_deadline_at is null
        then coalesce(new.supplier_deadline_source, 'pnr_call')
      when new.supplier_deadline_source in ('supplier', 'pnr_call', 'assumed')
        then new.supplier_deadline_source
      else 'pnr_call'
    end;
  end if;
  return new;
end;
$$;

drop trigger if exists flight_bookings_deadline_authority_v1
  on public.flight_bookings;
drop trigger if exists flight_bookings_deadline_authority_v2
  on public.flight_bookings;
create trigger flight_bookings_deadline_authority_v2
  before insert or update of
    status, ticketing_time_limit, ticketing_deadline_at, deadline_source,
    supplier_ticketing_time_limit, supplier_ticketing_deadline_at,
    supplier_deadline_source, local_ticketing_deadline_at,
    active_local_time_limit_request_id, active_superadmin_deadline_override_id
  on public.flight_bookings
  for each row execute function public.enforce_booking_deadline_authority_v2();

-- 3. Immutable manual financial resolution ---------------------------------

create table if not exists public.superadmin_manual_financial_resolutions (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.flight_bookings(id) on delete restrict,
  booking_reference text not null,
  request_key text not null unique
    check (char_length(request_key) between 1 and 220),
  request_hash text not null check (request_hash ~ '^[a-f0-9]{64}$'),
  wallet_id uuid not null references public.wallets(id) on delete restrict,
  wallet_account_id uuid not null references public.wallet_accounts(id) on delete restrict,
  wallet_owner_type text not null check (wallet_owner_type in ('user', 'agency')),
  wallet_owner_key text not null,
  customer_wallet_action text not null check (customer_wallet_action in (
    'none', 'credit_available', 'debit_available',
    'release_orphan_hold', 'capture_orphan_hold'
  )),
  customer_wallet_amount bigint not null check (customer_wallet_amount >= 0),
  customer_wallet_currency text not null check (customer_wallet_currency ~ '^[A-Z]{3}$'),
  customer_amount_basis text,
  available_before bigint not null check (available_before >= 0),
  available_after bigint not null check (available_after >= 0),
  hold_before bigint not null check (hold_before >= 0),
  hold_after bigint not null check (hold_after >= 0),
  supplier_outcome text not null check (supplier_outcome in (
    'ticket_issued', 'still_valid', 'not_issued'
  )),
  issue_now_case_confirmed boolean not null
    check (issue_now_case_confirmed),
  supplier_reference text,
  supplier_amount bigint check (supplier_amount is null or supplier_amount > 0),
  supplier_currency text check (
    supplier_currency is null or supplier_currency ~ '^[A-Z]{3}$'
  ),
  booking_result text not null check (booking_result in (
    'confirmed', 'on-hold', 'cancelled'
  )),
  accounting_conflict_code text,
  actor_user_id text not null,
  actor_role text not null check (actor_role = 'superadmin'),
  note text,
  verified_at timestamptz not null,
  ledger_entry_id uuid references public.wallet_ledger_entries(id) on delete restrict,
  lifecycle_event_id bigint references public.booking_status_events(id) on delete restrict,
  reverses_resolution_id uuid references public.superadmin_manual_financial_resolutions(id) on delete restrict,
  result jsonb not null check (jsonb_typeof(result) = 'object'),
  created_at timestamptz not null default clock_timestamp(),
  check (
    (customer_wallet_action = 'none' and customer_wallet_amount = 0 and ledger_entry_id is null)
    or
    (customer_wallet_action <> 'none' and customer_wallet_amount > 0 and ledger_entry_id is not null)
  ),
  check (
    (supplier_amount is null and supplier_currency is null)
    or (supplier_amount is not null and supplier_currency is not null)
  )
);

create index if not exists superadmin_manual_resolution_booking_created_idx
  on public.superadmin_manual_financial_resolutions (booking_id, created_at desc);
create index if not exists superadmin_manual_resolution_wallet_created_idx
  on public.superadmin_manual_financial_resolutions (wallet_account_id, created_at desc);
create unique index if not exists superadmin_manual_resolution_supplier_effect_key
  on public.superadmin_manual_financial_resolutions (
    booking_id, supplier_reference, customer_wallet_action
  )
  where supplier_reference is not null
    and customer_wallet_action <> 'none'
    and reverses_resolution_id is null;

drop trigger if exists superadmin_manual_financial_resolutions_immutable
  on public.superadmin_manual_financial_resolutions;
create trigger superadmin_manual_financial_resolutions_immutable
  before update or delete on public.superadmin_manual_financial_resolutions
  for each row execute function public.prevent_superadmin_resolution_mutation_v2();

alter table public.flight_bookings
  add column if not exists last_superadmin_manual_resolution_id uuid;
do $$
begin
  if not exists (
    select 1 from pg_constraint
     where conname = 'flight_bookings_last_superadmin_manual_resolution_fk'
  ) then
    alter table public.flight_bookings
      add constraint flight_bookings_last_superadmin_manual_resolution_fk
      foreign key (last_superadmin_manual_resolution_id)
      references public.superadmin_manual_financial_resolutions(id)
      on delete restrict not valid;
  end if;
end;
$$;

-- 4. Shared read-only context ------------------------------------------------

create or replace function public.superadmin_issue_resolution_context_v2(
  p_booking_id uuid,
  p_actor_user_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text;
  v_booking public.flight_bookings;
  v_accounting jsonb;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_reservation_count integer := 0;
  v_ledger_count integer := 0;
  v_has_booking_owner boolean;
begin
  select role into v_role from public.app_users where clerk_id = p_actor_user_id;
  if v_role is distinct from 'superadmin' then
    return jsonb_build_object('ok', false, 'code', 'SUPERADMIN_DECISION_FORBIDDEN');
  end if;

  select * into v_booking from public.flight_bookings
   where id = p_booking_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  if lower(coalesce(v_booking.supplier, '')) <> 'triplover'
     or v_booking.import_source is not null
     or coalesce(v_booking.direct_ticketing, false)
     or coalesce(v_booking.audience, '') not in ('b2c', 'agency') then
    return jsonb_build_object('ok', false, 'code', 'ISSUE_RESOLUTION_SCOPE_FORBIDDEN');
  end if;
  v_has_booking_owner := coalesce(
    v_booking.booking_owner_type in ('user', 'agency'), false
  ) and nullif(btrim(v_booking.booking_owner_key), '') is not null;
  if v_booking.last_superadmin_manual_resolution_id is not null
     or v_booking.status in ('ticketed', 'failed', 'confirmed', 'cancelled') then
    return jsonb_build_object(
      'ok', false, 'code', 'ALREADY_RESOLVED',
      'bookingId', v_booking.id,
      'bookingReference', v_booking.public_ref,
      'bookingStatus', v_booking.status,
      'manualResolutionId', v_booking.last_superadmin_manual_resolution_id
    );
  end if;

  v_accounting := public.classify_superadmin_booking_accounting_v1(p_booking_id);

  -- A malformed historical price must not block a booking-only decision when
  -- the complete local footprint proves that no customer money moved.
  if coalesce(v_accounting->>'code', '') = 'INVALID_USER_PAYABLE' then
    select count(*)::integer into v_reservation_count
      from public.wallet_reservations reservation
     where reservation.booking_id = v_booking.id
        or (reservation.booking_id is null
          and reservation.booking_attempt_id = v_booking.attempt_id);
    select count(*)::integer into v_ledger_count
      from public.wallet_ledger_entries ledger
     where ledger.booking_id = v_booking.id
       and ledger.transaction_type in (
         'booking_hold', 'booking_confirm', 'hold_release', 'refund',
         'superadmin_resolution_credit', 'superadmin_resolution_debit',
         'superadmin_resolution_hold_release',
         'superadmin_resolution_hold_capture'
       );
    if v_reservation_count = 0 and v_ledger_count = 0
       and coalesce(v_booking.captured_amount, 0) = 0
       and coalesce(v_booking.refunded_amount, 0) = 0
       and v_booking.payment_state not in (
         'captured', 'partially-refunded', 'refunded', 'reconciliation'
       ) then
      v_accounting := jsonb_build_object(
        'ok', true, 'accountingState', 'unpaid',
        'accountingSource', 'proven_no_financial_footprint',
        'expectedAmount', null, 'currency', upper(v_booking.currency),
        'reservationId', null, 'reservationState', null,
        'walletAccountId', null, 'capturedAmount', 0,
        'refundedAmount', 0, 'outstandingAmount', 0,
        'paymentStateObserved', v_booking.payment_state,
        'paymentStateStale', v_booking.payment_state <> 'unpaid'
      );
    end if;
  end if;

  -- Ownerless retained history can still take a proven no-money booking-only
  -- Restore/Cancel decision. Any paid, held, conflicting, or manual financial
  -- case still requires a concrete B2B/B2C wallet owner.
  if not v_has_booking_owner and not (
    coalesce((v_accounting->>'ok')::boolean, false)
    and v_accounting->>'accountingState' = 'unpaid'
  ) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_OWNER_REQUIRED');
  end if;

  if v_has_booking_owner then
    select wallet.* into v_wallet from public.wallets wallet
     where wallet.owner_type = v_booking.booking_owner_type
       and wallet.owner_key = v_booking.booking_owner_key;
    if found then
      select account.* into v_account from public.wallet_accounts account
       where account.wallet_id = v_wallet.id
         and account.currency = upper(v_booking.currency);
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'bookingId', v_booking.id,
    'bookingReference', v_booking.public_ref,
    'bookingStatus', v_booking.status,
    'legacyOperational', v_booking.legacy_operational,
    'lifecycleStatus', public.resolve_superadmin_issue_lifecycle_v2(
      v_booking.status, v_booking.legacy_operational, v_booking.airlines_pnr,
      v_booking.ticketing_deadline_at, v_booking.operation_kind
    ),
    'currentDeadlineAt', v_booking.ticketing_deadline_at,
    'supplierDeadlineAt', v_booking.supplier_ticketing_deadline_at,
    'accounting', v_accounting,
    'wallet', case when v_wallet.id is null then null else jsonb_build_object(
      'walletId', v_wallet.id,
      'walletStatus', v_wallet.status,
      'ownerType', v_wallet.owner_type,
      'ownerKey', v_wallet.owner_key,
      'accountId', v_account.id,
      'currency', coalesce(v_account.currency, upper(v_booking.currency)),
      'availableBalance', v_account.available_balance,
      'holdBalance', v_account.hold_balance
    ) end,
    'manualAllowed', true
  );
end;
$$;

-- Manual preview keeps supplier facts and the customer-wallet decision in
-- separate arguments. No default or database expression copies one amount into
-- the other.
create or replace function public.preview_superadmin_manual_financial_resolution_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_supplier_outcome text,
  p_issue_now_case_confirmed boolean,
  p_customer_wallet_action text,
  p_customer_wallet_amount bigint,
  p_customer_amount_basis text,
  p_supplier_reference text,
  p_supplier_amount bigint,
  p_supplier_currency text,
  p_new_deadline_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_context jsonb;
  v_accounting jsonb;
  v_wallet jsonb;
  v_booking public.flight_bookings;
  v_matching_reservation public.wallet_reservations;
  v_matching_count integer := 0;
  v_protected_hold bigint := 0;
  v_resolvable_hold bigint := 0;
  v_available_before bigint;
  v_hold_before bigint;
  v_available_after bigint;
  v_hold_after bigint;
  v_booking_result text;
begin
  v_context := public.superadmin_issue_resolution_context_v2(
    p_booking_id, p_actor_user_id
  );
  if coalesce((v_context->>'ok')::boolean, false) is not true then
    return v_context;
  end if;
  if p_supplier_outcome not in ('ticket_issued', 'still_valid', 'not_issued') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPPLIER_OUTCOME');
  end if;
  if p_issue_now_case_confirmed is not true then
    return jsonb_build_object('ok', false, 'code', 'ISSUE_NOW_CASE_CONFIRMATION_REQUIRED');
  end if;
  if p_customer_wallet_action not in (
    'none', 'credit_available', 'debit_available',
    'release_orphan_hold', 'capture_orphan_hold'
  ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_MANUAL_WALLET_ACTION');
  end if;
  if p_supplier_outcome = 'ticket_issued'
     and p_customer_wallet_action in ('credit_available', 'release_orphan_hold') then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_ACTION_OUTCOME_CONFLICT');
  end if;
  if p_supplier_outcome in ('still_valid', 'not_issued')
     and p_customer_wallet_action in ('debit_available', 'capture_orphan_hold') then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_ACTION_OUTCOME_CONFLICT');
  end if;
  if p_customer_wallet_action = 'none' then
    if coalesce(p_customer_wallet_amount, 0) <> 0 then
      return jsonb_build_object('ok', false, 'code', 'MANUAL_AMOUNT_NOT_ALLOWED');
    end if;
  elsif p_customer_wallet_amount is null or p_customer_wallet_amount <= 0
        or nullif(btrim(coalesce(p_customer_amount_basis, '')), '') is null then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_CUSTOMER_AMOUNT_REQUIRED');
  end if;
  if (p_supplier_amount is null) <> (p_supplier_currency is null) then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_AMOUNT_PAIR_REQUIRED');
  end if;
  if p_supplier_amount is not null and (
    p_supplier_amount <= 0 or upper(p_supplier_currency) !~ '^[A-Z]{3}$'
  ) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPPLIER_AMOUNT');
  end if;

  v_accounting := v_context->'accounting';
  -- A complete normal state must use the normal lane. The one exception is a
  -- proven-no-money issued ticket, for which no normal Capture exists.
  if coalesce((v_accounting->>'ok')::boolean, false)
     and not (
       v_accounting->>'accountingState' = 'unpaid'
       and p_supplier_outcome = 'ticket_issued'
     ) then
    return jsonb_build_object(
      'ok', false, 'code', 'NORMAL_ACCOUNTING_AVAILABLE',
      'accounting', v_accounting
    );
  end if;

  v_wallet := v_context->'wallet';
  if v_wallet is null or nullif(v_wallet->>'accountId', '') is null then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  select * into v_booking from public.flight_bookings
   where id = p_booking_id;
  select count(*)::integer into v_matching_count
    from public.wallet_reservations reservation
   where reservation.booking_id = p_booking_id
      or (reservation.booking_id is null
        and reservation.booking_attempt_id = v_booking.attempt_id);
  if v_matching_count > 1 then
    return jsonb_build_object('ok', false, 'code', 'MULTIPLE_RESERVATIONS');
  elsif v_matching_count = 1 then
    select * into v_matching_reservation
      from public.wallet_reservations reservation
     where reservation.booking_id = p_booking_id
        or (reservation.booking_id is null
          and reservation.booking_attempt_id = v_booking.attempt_id)
     order by reservation.booking_id nulls last limit 1;
  end if;
  v_available_before := (v_wallet->>'availableBalance')::bigint;
  v_hold_before := (v_wallet->>'holdBalance')::bigint;
  select coalesce(sum(reservation.amount), 0)::bigint
    into v_protected_hold
    from public.wallet_reservations reservation
   where reservation.wallet_account_id = (v_wallet->>'accountId')::uuid
     and reservation.state in ('active', 'reconciliation')
     and (v_matching_reservation.id is null
       or reservation.id <> v_matching_reservation.id);
  v_resolvable_hold := v_hold_before - v_protected_hold;
  if v_resolvable_hold < 0 then
    return jsonb_build_object('ok', false, 'code', 'ACTIVE_HOLD_ACCOUNTING_CONFLICT');
  end if;
  if v_matching_reservation.id is not null
     and v_matching_reservation.state in ('active', 'reconciliation') then
    if v_matching_reservation.wallet_account_id
         <> (v_wallet->>'accountId')::uuid
       or v_matching_reservation.currency <> v_wallet->>'currency' then
      return jsonb_build_object('ok', false, 'code', 'RESERVATION_ACCOUNT_CONFLICT');
    end if;
    if p_customer_wallet_action not in (
      'release_orphan_hold', 'capture_orphan_hold'
    ) then
      return jsonb_build_object(
        'ok', false, 'code', 'MANUAL_ACTIVE_RESERVATION_ACTION_REQUIRED'
      );
    end if;
    if p_customer_wallet_amount <> v_matching_reservation.amount then
      return jsonb_build_object(
        'ok', false, 'code', 'MANUAL_RESERVATION_AMOUNT_CONFLICT',
        'reservationAmount', v_matching_reservation.amount
      );
    end if;
  end if;
  v_available_after := v_available_before;
  v_hold_after := v_hold_before;

  if p_customer_wallet_action = 'credit_available' then
    v_available_after := v_available_before + p_customer_wallet_amount;
  elsif p_customer_wallet_action = 'debit_available' then
    if v_wallet->>'walletStatus' <> 'active' then
      return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
    end if;
    if v_available_before < p_customer_wallet_amount then
      return jsonb_build_object(
        'ok', false, 'code', 'INSUFFICIENT_FUNDS',
        'available', v_available_before, 'required', p_customer_wallet_amount
      );
    end if;
    v_available_after := v_available_before - p_customer_wallet_amount;
  elsif p_customer_wallet_action = 'release_orphan_hold' then
    if v_resolvable_hold < p_customer_wallet_amount then
      return jsonb_build_object(
        'ok', false, 'code', 'INSUFFICIENT_HOLD_BALANCE',
        'hold', v_hold_before, 'protectedHold', v_protected_hold,
        'resolvableHold', v_resolvable_hold,
        'required', p_customer_wallet_amount
      );
    end if;
    v_available_after := v_available_before + p_customer_wallet_amount;
    v_hold_after := v_hold_before - p_customer_wallet_amount;
  elsif p_customer_wallet_action = 'capture_orphan_hold' then
    if v_resolvable_hold < p_customer_wallet_amount then
      return jsonb_build_object(
        'ok', false, 'code', 'INSUFFICIENT_HOLD_BALANCE',
        'hold', v_hold_before, 'protectedHold', v_protected_hold,
        'resolvableHold', v_resolvable_hold,
        'required', p_customer_wallet_amount
      );
    end if;
    v_hold_after := v_hold_before - p_customer_wallet_amount;
  end if;

  v_booking_result := case p_supplier_outcome
    when 'ticket_issued' then 'confirmed'
    when 'still_valid' then 'on-hold'
    else 'cancelled'
  end;
  if p_supplier_outcome = 'still_valid'
     and (p_new_deadline_at is null or p_new_deadline_at <= clock_timestamp()) then
    return jsonb_build_object('ok', false, 'code', 'FUTURE_DEADLINE_REQUIRED');
  end if;

  return jsonb_build_object(
    'ok', true,
    'mode', 'manual_supplier_verified',
    'bookingId', v_context->>'bookingId',
    'bookingReference', v_context->>'bookingReference',
    'fromStatus', v_context->>'bookingStatus',
    'fromLifecycleStatus', v_context->>'lifecycleStatus',
    'toStatus', v_booking_result,
    'supplierOutcome', p_supplier_outcome,
    'issueNowCaseConfirmed', true,
    'supplierReference', nullif(btrim(coalesce(p_supplier_reference, '')), ''),
    'supplierAmount', p_supplier_amount,
    'supplierCurrency', case when p_supplier_currency is null then null
      else upper(p_supplier_currency) end,
    'customerWalletAction', p_customer_wallet_action,
    'customerWalletAmount', coalesce(p_customer_wallet_amount, 0),
    'customerWalletCurrency', v_wallet->>'currency',
    'customerAmountBasis', nullif(btrim(coalesce(p_customer_amount_basis, '')), ''),
    'walletId', v_wallet->>'walletId',
    'walletAccountId', v_wallet->>'accountId',
    'walletOwnerType', v_wallet->>'ownerType',
    'walletOwnerKey', v_wallet->>'ownerKey',
    'matchingReservationId', v_matching_reservation.id,
    'matchingReservationState', v_matching_reservation.state,
    'protectedHold', v_protected_hold,
    'resolvableHold', v_resolvable_hold,
    'availableBefore', v_available_before,
    'availableAfter', v_available_after,
    'holdBefore', v_hold_before,
    'holdAfter', v_hold_after,
    'newDeadlineAt', p_new_deadline_at,
    'accountingConflictCode', case
      when coalesce((v_accounting->>'ok')::boolean, false) then null
      else v_accounting->>'code' end,
    'supplierAmountDeterminesCustomerAmount', false
  );
end;
$$;

-- 6. Atomic manual supplier-verified executor -------------------------------

create or replace function public.execute_superadmin_manual_financial_resolution_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_request_key text,
  p_supplier_outcome text,
  p_issue_now_case_confirmed boolean,
  p_customer_wallet_action text,
  p_customer_wallet_amount bigint,
  p_customer_amount_basis text,
  p_supplier_reference text,
  p_supplier_amount bigint,
  p_supplier_currency text,
  p_new_deadline_at timestamptz,
  p_note text,
  p_manual_effect_confirmed boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_existing public.superadmin_manual_financial_resolutions;
  v_context jsonb;
  v_preview jsonb;
  v_account public.wallet_accounts;
  v_wallet public.wallets;
  v_reservation public.wallet_reservations;
  v_resolution_id uuid := gen_random_uuid();
  v_request_hash text;
  v_ledger_id uuid;
  v_event_id bigint;
  v_override_id uuid;
  v_action text;
  v_amount bigint;
  v_currency text;
  v_available_before bigint;
  v_available_after bigint;
  v_hold_before bigint;
  v_hold_after bigint;
  v_from_lifecycle text;
  v_to_status text;
  v_to_lifecycle text;
  v_occurrence integer;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_request_key !~ '^superadmin-manual-resolution:v2:[0-9a-f-]{36}$'
     or char_length(coalesce(p_note, '')) > 1000
     or p_manual_effect_confirmed is not true then
    return jsonb_build_object('ok', false, 'code',
      case when p_manual_effect_confirmed is not true
        then 'MANUAL_EFFECT_CONFIRMATION_REQUIRED'
        else 'INVALID_MANUAL_RESOLUTION' end
    );
  end if;
  v_request_hash := encode(sha256(convert_to(
    jsonb_strip_nulls(jsonb_build_object(
      'bookingId', p_booking_id,
      'supplierOutcome', p_supplier_outcome,
      'issueNowCaseConfirmed', p_issue_now_case_confirmed,
      'customerWalletAction', p_customer_wallet_action,
      'customerWalletAmount', p_customer_wallet_amount,
      'customerAmountBasis', nullif(btrim(coalesce(p_customer_amount_basis, '')), ''),
      'supplierReference', nullif(btrim(coalesce(p_supplier_reference, '')), ''),
      'supplierAmount', p_supplier_amount,
      'supplierCurrency', case when p_supplier_currency is null then null
        else upper(p_supplier_currency) end,
      'newDeadlineAt', p_new_deadline_at,
      'note', nullif(btrim(coalesce(p_note, '')), '')
    ))::text, 'UTF8')), 'hex');

  select * into v_booking from public.flight_bookings
   where id = p_booking_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  select * into v_existing
    from public.superadmin_manual_financial_resolutions
   where request_key = p_request_key;
  if found then
    if v_existing.booking_id <> p_booking_id
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.request_hash <> v_request_hash then
      return jsonb_build_object('ok', false, 'code', 'DECISION_IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing.result || jsonb_build_object('ok', true, 'replay', true);
  end if;

  perform 1 from public.booking_operations operation
   where operation.booking_id = p_booking_id
     and operation.state in (
       'claimed', 'supplier_call_started',
       'awaiting_external_action', 'needs_reconciliation'
     ) order by operation.id for update;
  perform 1 from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = p_booking_id
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     ) order by reconciliation_case.id for update;
  v_context := public.superadmin_issue_resolution_context_v2(
    p_booking_id, p_actor_user_id
  );
  if coalesce((v_context->>'ok')::boolean, false) is not true then
    return v_context;
  end if;
  if v_context->'wallet' is null
     or nullif(v_context->'wallet'->>'accountId', '') is null then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  -- Hold is an account aggregate. Lock the matching reservation and every live
  -- reservation on the target account together in deterministic ID order,
  -- before the wallet, so another booking's protected Hold cannot be consumed.
  perform 1 from public.wallet_reservations reservation
   where (
       reservation.wallet_account_id =
         (v_context->'wallet'->>'accountId')::uuid
       and reservation.state in ('active', 'reconciliation')
     )
     or reservation.booking_id = p_booking_id
     or (reservation.booking_id is null
       and reservation.booking_attempt_id = v_booking.attempt_id)
   order by reservation.id for update;
  select wallet.* into v_wallet from public.wallets wallet
   where wallet.id = (v_context->'wallet'->>'walletId')::uuid
     and wallet.owner_type = v_booking.booking_owner_type
     and wallet.owner_key = v_booking.booking_owner_key
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
  end if;
  select account.* into v_account from public.wallet_accounts account
   where account.id = (v_context->'wallet'->>'accountId')::uuid
     and account.wallet_id = v_wallet.id
     and account.currency = upper(v_booking.currency)
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;

  -- Re-preview after every relevant lock. If local records became complete, the
  -- manual lane refuses to compete with the normal Capture/Release lane.
  v_preview := public.preview_superadmin_manual_financial_resolution_v2(
    p_booking_id, p_actor_user_id, p_supplier_outcome,
    p_issue_now_case_confirmed,
    p_customer_wallet_action, p_customer_wallet_amount,
    p_customer_amount_basis, p_supplier_reference, p_supplier_amount,
    p_supplier_currency, p_new_deadline_at
  );
  if coalesce((v_preview->>'ok')::boolean, false) is not true then
    return v_preview;
  end if;
  if (v_preview->>'availableBefore')::bigint <> v_account.available_balance
     or (v_preview->>'holdBefore')::bigint <> v_account.hold_balance then
    return jsonb_build_object('ok', false, 'code', 'ACCOUNTING_STATE_CHANGED');
  end if;
  if nullif(v_preview->>'supplierReference', '') is not null
     and exists (
       select 1 from public.superadmin_manual_financial_resolutions resolution
        where resolution.booking_id = p_booking_id
          and resolution.supplier_reference = v_preview->>'supplierReference'
          and resolution.customer_wallet_action = p_customer_wallet_action
          and resolution.reverses_resolution_id is null
     ) then
    return jsonb_build_object('ok', false, 'code', 'MANUAL_SUPPLIER_EFFECT_DUPLICATE');
  end if;

  v_action := v_preview->>'customerWalletAction';
  v_amount := (v_preview->>'customerWalletAmount')::bigint;
  v_currency := v_preview->>'customerWalletCurrency';
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  v_available_after := (v_preview->>'availableAfter')::bigint;
  v_hold_after := (v_preview->>'holdAfter')::bigint;

  if nullif(v_preview->>'matchingReservationId', '') is not null then
    select * into v_reservation from public.wallet_reservations reservation
     where reservation.id = (v_preview->>'matchingReservationId')::uuid;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'RESERVATION_CHANGED');
    end if;
  end if;

  if v_action <> 'none' then
    update public.wallet_accounts set
      available_balance = v_available_after,
      hold_balance = v_hold_after
    where id = v_account.id;
    if v_reservation.id is not null
       and v_action in ('release_orphan_hold', 'capture_orphan_hold') then
      update public.wallet_reservations set
        booking_id = v_booking.id,
        booking_attempt_id = null,
        state = case when v_action = 'release_orphan_hold'
          then 'released' else 'captured' end,
        released_at = case when v_action = 'release_orphan_hold'
          then v_now else released_at end,
        release_reason = case when v_action = 'release_orphan_hold'
          then left(coalesce(nullif(btrim(p_note), ''),
            'Super Admin supplier-verified manual release'), 1000)
          else release_reason end,
        issued_by_user_id = case when v_action = 'capture_orphan_hold'
          then p_actor_user_id else issued_by_user_id end,
        captured_at = case when v_action = 'capture_orphan_hold'
          then v_now else captured_at end,
        reconciliation_at = null,
        reconciliation_reason = null
      where id = v_reservation.id;
    end if;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id,
      case v_action
        when 'credit_available' then 'superadmin_resolution_credit'
        when 'debit_available' then 'superadmin_resolution_debit'
        when 'release_orphan_hold' then 'superadmin_resolution_hold_release'
        else 'superadmin_resolution_hold_capture'
      end,
      v_amount, v_currency,
      v_available_before, v_available_after,
      v_hold_before, v_hold_after,
      v_booking.id, v_booking.public_ref,
      case when v_action in ('release_orphan_hold', 'capture_orphan_hold')
        then v_reservation.id else null end,
      p_request_key || ':ledger', p_actor_user_id, 'superadmin',
      coalesce(nullif(btrim(p_note), ''),
        'Super Admin supplier-verified manual financial resolution'),
      jsonb_strip_nulls(jsonb_build_object(
        'resolutionId', v_resolution_id,
        'resolutionMode', 'manual_supplier_verified',
        'supplierOutcome', p_supplier_outcome,
        'issueNowCaseConfirmed', true,
        'supplierReference', nullif(btrim(coalesce(p_supplier_reference, '')), ''),
        'supplierAmount', p_supplier_amount,
        'supplierCurrency', case when p_supplier_currency is null then null
          else upper(p_supplier_currency) end,
        'customerWalletAmount', v_amount,
        'customerWalletCurrency', v_currency,
        'customerAmountBasis', nullif(btrim(coalesce(p_customer_amount_basis, '')), ''),
        'matchingReservationId', case
          when v_action in ('release_orphan_hold', 'capture_orphan_hold')
            then v_reservation.id else null end,
        'protectedHold', v_preview->>'protectedHold',
        'resolvableHold', v_preview->>'resolvableHold',
        'supplierAmountDeterminesCustomerAmount', false,
        'evidenceUploadRequired', false
      ))
    ) returning id into v_ledger_id;
  end if;

  v_from_lifecycle := public.resolve_superadmin_issue_lifecycle_v2(
    v_booking.status, v_booking.legacy_operational, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  v_to_status := v_preview->>'toStatus';
  if v_to_status = 'on-hold' then
    insert into public.superadmin_booking_deadline_overrides (
      booking_id, request_key, effective_deadline_at,
      supplier_deadline_snapshot, supplier_time_limit_snapshot,
      actor_user_id, actor_role, note
    ) values (
      v_booking.id, p_request_key || ':deadline', p_new_deadline_at,
      v_booking.supplier_ticketing_deadline_at,
      v_booking.supplier_ticketing_time_limit,
      p_actor_user_id, 'superadmin', nullif(btrim(p_note), '')
    ) returning id into v_override_id;
  end if;

  update public.booking_operations set
    state = 'failed', completed_at = coalesce(completed_at, v_now),
    error_code = 'SUPERADMIN_MANUAL_RESOLUTION_SUPERSEDED',
    error_message = 'Superseded by a supplier-verified Super Admin resolution',
    supplier_evidence = supplier_evidence || jsonb_strip_nulls(jsonb_build_object(
      'manualResolutionId', v_resolution_id,
      'supplierOutcome', p_supplier_outcome,
      'issueNowCaseConfirmed', true,
      'supplierReference', nullif(btrim(coalesce(p_supplier_reference, '')), ''),
      'customerWalletAction', v_action,
      'evidenceUploadRequired', false
    ))
  where booking_id = v_booking.id
    and state in (
      'claimed', 'supplier_call_started',
      'awaiting_external_action', 'needs_reconciliation'
    );

  update public.flight_bookings set
    status = v_to_status,
    active_operation_id = null, operation_kind = null,
    operation_reason = null, operation_request_id = null,
    operation_actor_user_id = null, operation_started_at = null,
    operation_prior_status = null,
    active_superadmin_deadline_override_id = case when v_to_status = 'on-hold'
      then v_override_id else null end,
    local_ticketing_deadline_at = case when v_to_status = 'on-hold'
      then p_new_deadline_at else local_ticketing_deadline_at end,
    ticketing_deadline_at = case when v_to_status = 'on-hold'
      then p_new_deadline_at else ticketing_deadline_at end,
    deadline_source = case when v_to_status = 'on-hold'
      then 'superadmin_override' else deadline_source end,
    issued_by_user_id = case when v_to_status = 'confirmed'
      then p_actor_user_id else issued_by_user_id end,
    issued_at = case when v_to_status = 'confirmed'
      then coalesce(issued_at, v_now) else issued_at end,
    booking_status = case when v_to_status = 'confirmed'
      then coalesce(nullif(booking_status, ''), 'Confirmed') else booking_status end,
    cancelled_at = case when v_to_status = 'cancelled'
      then coalesce(cancelled_at, v_now) else cancelled_at end,
    cancelled_by = case when v_to_status = 'cancelled'
      then p_actor_user_id else cancelled_by end,
    cancel_reason = case when v_to_status = 'cancelled'
      then left(coalesce(nullif(btrim(p_note), ''),
        'Super Admin supplier-verified resolution'), 1000)
      else cancel_reason end
  where id = v_booking.id;

  update public.booking_reconciliation_cases set
    state = 'resolved',
    resolution_outcome = 'superadmin_manual_' || p_supplier_outcome,
    resolution = jsonb_strip_nulls(jsonb_build_object(
      'version', 2,
      'resolutionKind', 'superadmin_manual_financial_resolution',
      'manualResolutionId', v_resolution_id,
      'requestKey', p_request_key,
      'supplierOutcome', p_supplier_outcome,
      'supplierReference', nullif(btrim(coalesce(p_supplier_reference, '')), ''),
      'supplierAmount', p_supplier_amount,
      'supplierCurrency', case when p_supplier_currency is null then null
        else upper(p_supplier_currency) end,
      'customerWalletAction', v_action,
      'customerWalletAmount', v_amount,
      'customerWalletCurrency', v_currency,
      'supplierAmountDeterminesCustomerAmount', false,
      'ledgerEntryId', v_ledger_id,
      'evidenceUploadRequired', false
    )),
    resolution_reason = nullif(btrim(p_note), ''),
    resolved_by_user_id = p_actor_user_id,
    resolved_at = v_now, version = version + 1
  where subject_booking_id = v_booking.id
    and state in (
      'open', 'assigned', 'awaiting_supplier',
      'awaiting_finance', 'awaiting_approval'
    );

  v_to_lifecycle := case v_to_status
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    else public.resolve_superadmin_issue_lifecycle_v2(
      'on-hold', v_booking.legacy_operational,
      v_booking.airlines_pnr, p_new_deadline_at, null
    ) end;
  select count(*)::integer + 1 into v_occurrence
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = v_to_lifecycle;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after,
    actor_user_id, supplier_operation, supplier_evidence,
    idempotency_key, occurrence_number, effective_at, observed_at,
    event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle, v_to_lifecycle,
    v_booking.status, v_to_status, p_actor_user_id,
    'SuperAdminManualFinancialResolution',
    jsonb_strip_nulls(jsonb_build_object(
      'manualResolutionId', v_resolution_id,
      'supplierOutcome', p_supplier_outcome,
      'supplierReference', nullif(btrim(coalesce(p_supplier_reference, '')), ''),
      'customerWalletAction', v_action,
      'customerWalletAmount', v_amount,
      'customerWalletCurrency', v_currency,
      'evidenceUploadRequired', false
    )),
    p_request_key || ':status', v_occurrence, v_now, v_now,
    jsonb_strip_nulls(jsonb_build_object(
      'version', 2,
      'resolutionMode', 'manual_supplier_verified',
      'manualResolutionId', v_resolution_id,
      'customerWalletAction', v_action,
      'customerWalletAmount', v_amount,
      'customerWalletCurrency', v_currency,
      'supplierAmountDeterminesCustomerAmount', false,
      'newDeadlineAt', p_new_deadline_at,
      'notificationDisposition', case
        when v_from_lifecycle = v_to_lifecycle then 'audit_only'
        else null end,
      'suppressionReason', case
        when v_from_lifecycle = v_to_lifecycle
          then 'superadmin_same_status_resolution' else null end
    )), 2
  ) returning id into v_event_id;

  v_result := jsonb_build_object(
    'ok', true, 'replay', false,
    'mode', 'manual_supplier_verified',
    'resolutionId', v_resolution_id,
    'bookingId', v_booking.id,
    'bookingReference', v_booking.public_ref,
    'bookingStatus', v_to_status,
    'supplierOutcome', p_supplier_outcome,
    'customerWalletAction', v_action,
    'customerWalletAmount', v_amount,
    'customerWalletCurrency', v_currency,
    'availableBefore', v_available_before,
    'availableAfter', v_available_after,
    'holdBefore', v_hold_before,
    'holdAfter', v_hold_after,
    'ledgerEntryId', v_ledger_id,
    'lifecycleEventId', v_event_id,
    'supplierAmountDeterminesCustomerAmount', false
  );

  insert into public.superadmin_manual_financial_resolutions (
    id, booking_id, booking_reference, request_key, request_hash,
    wallet_id, wallet_account_id, wallet_owner_type, wallet_owner_key,
    customer_wallet_action, customer_wallet_amount,
    customer_wallet_currency, customer_amount_basis,
    available_before, available_after, hold_before, hold_after,
    supplier_outcome, supplier_reference, supplier_amount, supplier_currency,
    issue_now_case_confirmed,
    booking_result, accounting_conflict_code,
    actor_user_id, actor_role, note, verified_at,
    ledger_entry_id, lifecycle_event_id, result
  ) values (
    v_resolution_id, v_booking.id, v_booking.public_ref,
    p_request_key, v_request_hash,
    v_wallet.id, v_account.id, v_wallet.owner_type, v_wallet.owner_key,
    v_action, v_amount, v_currency,
    nullif(btrim(coalesce(p_customer_amount_basis, '')), ''),
    v_available_before, v_available_after, v_hold_before, v_hold_after,
    p_supplier_outcome,
    nullif(btrim(coalesce(p_supplier_reference, '')), ''),
    p_supplier_amount,
    case when p_supplier_currency is null then null
      else upper(p_supplier_currency) end,
    true,
    v_to_status, v_preview->>'accountingConflictCode',
    p_actor_user_id, 'superadmin', nullif(btrim(p_note), ''), v_now,
    v_ledger_id, v_event_id, v_result
  );
  update public.flight_bookings
     set last_superadmin_manual_resolution_id = v_resolution_id
   where id = v_booking.id;
  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, metadata
  ) values (
    p_actor_user_id, 'superadmin',
    'booking.superadmin_manual_financial_resolution',
    'flight_booking', v_booking.id::text, 'succeeded',
    jsonb_strip_nulls(jsonb_build_object(
      'resolutionId', v_resolution_id,
      'requestKey', p_request_key,
      'supplierOutcome', p_supplier_outcome,
      'issueNowCaseConfirmed', true,
      'supplierReferenceRecorded',
        nullif(btrim(coalesce(p_supplier_reference, '')), '') is not null,
      'customerWalletAction', v_action,
      'customerWalletAmount', v_amount,
      'customerWalletCurrency', v_currency,
      'supplierAmount', p_supplier_amount,
      'supplierCurrency', case when p_supplier_currency is null then null
        else upper(p_supplier_currency) end,
      'supplierAmountDeterminesCustomerAmount', false,
      'ledgerEntryId', v_ledger_id
    ))
  );
  return v_result;
end;
$$;

-- 7. One automatic execution boundary ---------------------------------------

create or replace function public.execute_superadmin_issue_resolution_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_request_key text,
  p_supplier_outcome text,
  p_refund_disposition text,
  p_refund_amount bigint,
  p_external_settlement_reference text,
  p_new_deadline_at timestamptz,
  p_note text,
  p_money_movement_confirmed boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_existing public.superadmin_booking_decisions;
  v_preview jsonb;
  v_state text;
  v_expected_decision text;
begin
  if p_request_key !~ '^superadmin-booking-decision:v1:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_SUPERADMIN_DECISION');
  end if;
  select * into v_booking from public.flight_bookings
   where id = p_booking_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;
  v_expected_decision := case p_supplier_outcome
    when 'ticket_issued' then 'confirm_ticketed'
    when 'still_valid' then 'keep_on_hold'
    when 'not_issued' then 'cancel'
    else null end;
  select * into v_existing from public.superadmin_booking_decisions
   where request_key = p_request_key;
  if found then
    if v_expected_decision is null
       or v_existing.booking_id <> p_booking_id
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.decision <> v_expected_decision
       or v_existing.note is distinct from nullif(btrim(coalesce(p_note, '')), '')
       or (
         v_existing.request_snapshot ? 'supplierOutcome'
         and (
           v_existing.request_snapshot->>'supplierOutcome'
             is distinct from p_supplier_outcome
           or (v_existing.request_snapshot->>'newDeadlineAt')::timestamptz
             is distinct from p_new_deadline_at
         )
       )
       or (
         not (v_existing.request_snapshot ? 'supplierOutcome')
         and (
           v_existing.request_snapshot->>'refundDisposition'
             is distinct from p_refund_disposition
           or (v_existing.request_snapshot->>'refundAmount')::bigint
             is distinct from p_refund_amount
           or v_existing.request_snapshot->>'externalSettlementReference'
             is distinct from p_external_settlement_reference
           or (v_existing.request_snapshot->>'newDeadlineAt')::timestamptz
             is distinct from p_new_deadline_at
         )
       ) then
      return jsonb_build_object(
        'ok', false, 'code', 'DECISION_IDEMPOTENCY_CONFLICT'
      );
    end if;
    return v_existing.result || jsonb_build_object('ok', true, 'replay', true);
  end if;
  perform 1 from public.booking_operations operation
   where operation.booking_id = p_booking_id
     and operation.state in (
       'claimed', 'supplier_call_started',
       'awaiting_external_action', 'needs_reconciliation'
     ) order by operation.id for update;
  perform 1 from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = p_booking_id
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier',
       'awaiting_finance', 'awaiting_approval'
     ) order by reconciliation_case.id for update;
  v_preview := public.preview_superadmin_issue_resolution_v2(
    p_booking_id, p_actor_user_id, p_supplier_outcome,
    p_refund_disposition, p_refund_amount,
    p_external_settlement_reference, p_new_deadline_at
  );
  if coalesce((v_preview->>'ok')::boolean, false) is not true then
    return v_preview;
  end if;
  v_state := v_preview->'accounting'->>'accountingState';
  if v_state = 'active_hold' then
    perform 1 from public.wallet_reservations reservation
     where reservation.wallet_account_id =
         (v_preview->'accounting'->>'walletAccountId')::uuid
       and reservation.state in ('active', 'reconciliation')
     order by reservation.id for update;
    v_preview := public.preview_superadmin_issue_resolution_v2(
      p_booking_id, p_actor_user_id, p_supplier_outcome,
      p_refund_disposition, p_refund_amount,
      p_external_settlement_reference, p_new_deadline_at
    );
    if coalesce((v_preview->>'ok')::boolean, false) is not true then
      return v_preview;
    end if;
    if v_preview->'accounting'->>'accountingState' <> 'active_hold' then
      return jsonb_build_object('ok', false, 'code', 'ACCOUNTING_STATE_CHANGED');
    end if;
  end if;
  if p_supplier_outcome = 'ticket_issued' then
    if v_booking.status = 'confirmed' and v_state = 'paid' then
      return jsonb_build_object(
        'ok', false, 'code', 'ALREADY_RESOLVED',
        'bookingStatus', 'confirmed', 'walletEffect', 'none'
      );
    end if;
    return public.execute_superadmin_booking_decision_v1(
      p_booking_id, p_actor_user_id, p_request_key,
      'confirm_ticketed', null, null, null, null,
      p_note, p_money_movement_confirmed
    );
  elsif p_supplier_outcome = 'not_issued' and v_state = 'paid' then
    return public.execute_superadmin_booking_decision_v1(
      p_booking_id, p_actor_user_id, p_request_key,
      'cancel', p_refund_disposition, p_refund_amount,
      p_external_settlement_reference, null,
      p_note, p_money_movement_confirmed
    );
  end if;
  return public.execute_superadmin_hold_outcome_v2(
    p_booking_id, p_actor_user_id, p_request_key,
    p_supplier_outcome, p_new_deadline_at,
    p_note, p_money_movement_confirmed
  );
end;
$$;

-- 8. Security boundary -------------------------------------------------------

alter table public.superadmin_booking_deadline_overrides enable row level security;
alter table public.superadmin_manual_financial_resolutions enable row level security;
revoke all on table public.superadmin_booking_deadline_overrides,
  public.superadmin_manual_financial_resolutions
  from public, anon, authenticated;
grant select, insert on table public.superadmin_booking_deadline_overrides,
  public.superadmin_manual_financial_resolutions
  to service_role;

revoke all on function public.superadmin_issue_resolution_context_v2(uuid,text),
  public.resolve_superadmin_issue_lifecycle_v2(text,boolean,jsonb,timestamptz,text),
  public.preview_superadmin_issue_resolution_v2(uuid,text,text,text,bigint,text,timestamptz),
  public.execute_superadmin_hold_outcome_v2(uuid,text,text,text,timestamptz,text,boolean),
  public.preview_superadmin_manual_financial_resolution_v2(uuid,text,text,boolean,text,bigint,text,text,bigint,text,timestamptz),
  public.execute_superadmin_manual_financial_resolution_v2(uuid,text,text,text,boolean,text,bigint,text,text,bigint,text,timestamptz,text,boolean),
  public.execute_superadmin_issue_resolution_v2(uuid,text,text,text,text,bigint,text,timestamptz,text,boolean),
  public.prevent_superadmin_resolution_mutation_v2(),
  public.enforce_booking_deadline_authority_v2()
  from public, anon, authenticated;

grant execute on function public.superadmin_issue_resolution_context_v2(uuid,text),
  public.preview_superadmin_issue_resolution_v2(uuid,text,text,text,bigint,text,timestamptz),
  public.preview_superadmin_manual_financial_resolution_v2(uuid,text,text,boolean,text,bigint,text,text,bigint,text,timestamptz),
  public.execute_superadmin_manual_financial_resolution_v2(uuid,text,text,text,boolean,text,bigint,text,text,bigint,text,timestamptz,text,boolean),
  public.execute_superadmin_issue_resolution_v2(uuid,text,text,text,text,bigint,text,timestamptz,text,boolean)
  to service_role;

-- Internal implementation: callable from the owner function only.
revoke all on function public.execute_superadmin_hold_outcome_v2(
  uuid,text,text,text,timestamptz,text,boolean
) from service_role;

comment on table public.superadmin_manual_financial_resolutions is
  'Immutable booking-bound Super Admin supplier-verified customer-wallet resolutions. Supplier and customer-wallet amounts are independent facts.';
comment on table public.superadmin_booking_deadline_overrides is
  'Immutable Super Admin effective-deadline decisions; supplier deadline history remains separate and readable.';
comment on function public.execute_superadmin_manual_financial_resolution_v2(uuid,text,text,text,boolean,text,bigint,text,text,bigint,text,timestamptz,text,boolean) is
  'Atomically applies a supplier-verified manual customer-wallet resolution for a stuck ordinary B2B/B2C Issue Now booking. Never invents a reservation or rewrites ledger history.';


-- SOURCE: 0108_imported_booking_ticketing_resolution.sql
-- Dedicated MANUAL / IMP_EXP owner Issue Now and staff resolution.
--
-- Imported On Hold creation remains non-financial. The owner later moves the
-- protected User Payable from Available to Hold without calling a supplier
-- API. Authorized operations staff then either capture that exact Hold with
-- complete ticket evidence or release it with a cancellation timestamp and
-- reason. Rows captured by the former Confirm & Pay behavior remain supported
-- without a second charge; their cancellation uses an explicit refund choice.
-- Ordinary Triplover Issue Now and the 0107 Super Admin resolver are untouched.

create table if not exists public.imported_ticketing_resolutions (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique
    references public.flight_bookings(id) on delete restrict,
  booking_reference text not null,
  request_key text not null unique
    check (char_length(request_key) between 1 and 220),
  request_hash text not null check (request_hash ~ '^[a-f0-9]{64}$'),
  import_source text not null check (import_source in ('IMP_EXP', 'MANUAL')),
  decision text not null check (decision in ('confirm_ticketed', 'cancel')),
  accounting_mode text not null check (
    accounting_mode in ('active_hold', 'legacy_captured')
  ),
  wallet_account_id uuid not null
    references public.wallet_accounts(id) on delete restrict,
  reservation_id uuid not null
    references public.wallet_reservations(id) on delete restrict,
  wallet_effect text not null check (
    wallet_effect in ('capture_hold', 'release_hold', 'refund', 'none')
  ),
  wallet_amount bigint not null check (wallet_amount >= 0),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  available_before bigint not null check (available_before >= 0),
  available_after bigint not null check (available_after >= 0),
  hold_before bigint not null check (hold_before >= 0),
  hold_after bigint not null check (hold_after >= 0),
  ticket_numbers jsonb not null default '[]'::jsonb
    check (jsonb_typeof(ticket_numbers) = 'array'),
  issued_at timestamptz,
  cancellation_at timestamptz,
  cancellation_reason text,
  refund_disposition text check (
    refund_disposition is null or refund_disposition in (
      'full_refund', 'partial_refund', 'no_refund_due', 'externally_settled'
    )
  ),
  refund_amount bigint not null default 0 check (refund_amount >= 0),
  external_settlement_reference text,
  actor_user_id text not null,
  actor_role text not null check (
    actor_role in ('staff_support', 'admin', 'superadmin')
  ),
  operation_id uuid references public.booking_operations(id) on delete restrict,
  reconciliation_case_id uuid
    references public.booking_reconciliation_cases(id) on delete restrict,
  ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  lifecycle_event_id bigint
    references public.booking_status_events(id) on delete restrict,
  result jsonb not null check (jsonb_typeof(result) = 'object'),
  created_at timestamptz not null default clock_timestamp(),
  check (
    (decision = 'confirm_ticketed' and issued_at is not null
      and cancellation_at is null and cancellation_reason is null)
    or
    (decision = 'cancel' and issued_at is null
      and cancellation_at is not null
      and nullif(btrim(cancellation_reason), '') is not null)
  ),
  check (
    (wallet_effect = 'none' and wallet_amount = 0 and ledger_entry_id is null)
    or
    (wallet_effect <> 'none' and wallet_amount > 0 and ledger_entry_id is not null)
  ),
  check (
    refund_disposition <> 'externally_settled'
    or nullif(btrim(external_settlement_reference), '') is not null
  )
);

create index if not exists imported_ticketing_resolutions_created_idx
  on public.imported_ticketing_resolutions(created_at desc);

create or replace function public.prevent_imported_ticketing_resolution_mutation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'Imported ticketing resolution records are immutable'
    using errcode = '55000';
end;
$$;

drop trigger if exists imported_ticketing_resolutions_immutable
  on public.imported_ticketing_resolutions;
create trigger imported_ticketing_resolutions_immutable
  before update or delete on public.imported_ticketing_resolutions
  for each row execute function
    public.prevent_imported_ticketing_resolution_mutation_v1();

alter table public.imported_ticketing_resolutions enable row level security;
revoke all on table public.imported_ticketing_resolutions
  from public, anon, authenticated;
grant select on table public.imported_ticketing_resolutions
  to service_role;
revoke all on function public.prevent_imported_ticketing_resolution_mutation_v1()
  from public, anon, authenticated;

-- Owner command. This is intentionally not wallet_begin_booking_issue: no
-- supplier NewTicket request is made and supplier_call_started_at stays null.
create or replace function public.wallet_begin_imported_booking_issue_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
  v_actor_agency text;
  v_existing_ledger public.wallet_ledger_entries;
  v_existing_operation public.booking_operations;
  v_existing_case public.booking_reconciliation_cases;
  v_existing_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_available_before bigint;
  v_hold_before bigint;
  v_due_at timestamptz;
  v_occurrence integer;
  v_event_id bigint;
  v_now timestamptz := clock_timestamp();
begin
  if p_booking_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_request_key !~ '^imported-issue:v2:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORTED_ISSUE_REQUEST');
  end if;

  select role, agency_code into v_actor_role, v_actor_agency
    from public.app_users
   where clerk_id = p_actor_user_id;
  if not found or v_actor_role not in ('customer', 'b2b', 'b2b_sub') then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ISSUE_FORBIDDEN');
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
     and booking.import_source in ('IMP_EXP', 'MANUAL')
     and not booking.legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;

  if not (
    (v_actor_role = 'customer'
      and v_booking.booking_owner_type = 'user'
      and v_booking.booking_owner_key = p_actor_user_id)
    or
    (v_actor_role in ('b2b', 'b2b_sub')
      and nullif(btrim(v_actor_agency), '') is not null
      and v_booking.booking_owner_type = 'agency'
      and v_booking.booking_owner_key = v_actor_agency)
  ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ISSUE_FORBIDDEN');
  end if;

  select ledger.* into v_existing_ledger
    from public.wallet_ledger_entries ledger
   where ledger.idempotency_key = p_request_key || ':hold';
  if found and v_existing_ledger.booking_id is distinct from v_booking.id then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ISSUE_IDEMPOTENCY_CONFLICT');
  end if;

  select operation.* into v_existing_operation
    from public.booking_operations operation
   where operation.booking_id = v_booking.id
     and operation.state in (
       'claimed', 'supplier_call_started', 'awaiting_external_action',
       'needs_reconciliation'
     )
   order by operation.claimed_at desc, operation.id desc
   limit 1
   for update;
  select reconciliation_case.* into v_existing_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = v_booking.id
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier', 'awaiting_finance',
       'awaiting_approval'
     )
   order by reconciliation_case.opened_at desc, reconciliation_case.id desc
   limit 1
   for update;
  select reservation.* into v_existing_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
   for update;

  if v_existing_reservation.id is not null
     and v_existing_reservation.state in ('active', 'reconciliation')
     and v_booking.status = 'in-progress'
     and v_booking.payment_state in ('held', 'reconciliation')
     and v_existing_reservation.amount = v_booking.user_payable_amount
     and v_existing_operation.id = v_booking.active_operation_id
     and v_existing_operation.kind = 'imported_manual_ticketing'
     and v_existing_case.operation_id = v_existing_operation.id
     and exists (
       select 1 from public.wallet_ledger_entries ledger
        where ledger.reservation_id = v_existing_reservation.id
          and ledger.transaction_type = 'booking_hold'
          and ledger.amount = v_existing_reservation.amount
     ) then
    select account.* into v_account
      from public.wallet_accounts account
     where account.id = v_existing_reservation.wallet_account_id;
    return jsonb_build_object(
      'ok', true, 'replay', true, 'status', 'in-progress',
      'paymentState', v_booking.payment_state,
      'operationId', v_existing_operation.id,
      'reconciliationCaseId', v_existing_case.id,
      'reservationId', v_existing_reservation.id,
      'accountId', v_existing_reservation.wallet_account_id,
      'amount', v_existing_reservation.amount,
      'currency', v_existing_reservation.currency,
      'availableBalance', v_account.available_balance,
      'holdBalance', v_account.hold_balance
    );
  end if;

  if v_booking.status = 'confirmed'
     or v_booking.payment_state in ('captured', 'partially-refunded', 'refunded')
     or (v_existing_reservation.id is not null
       and v_existing_reservation.state = 'captured') then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;
  if v_existing_operation.id is not null
     or v_existing_case.id is not null
     or v_existing_reservation.id is not null
     or v_existing_ledger.id is not null then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ACCOUNTING_RECONCILIATION_REQUIRED');
  end if;
  if v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.payment_state <> 'unpaid'
     or v_booking.charged_wallet_account_id is not null
     or v_booking.captured_amount <> 0
     or v_booking.refunded_amount <> 0
     or public.resolve_booking_lifecycle(
       v_booking.status, v_booking.airlines_pnr,
       v_booking.ticketing_deadline_at, v_booking.operation_kind
     ) <> 'on-hold' then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if v_booking.user_payable_amount is null
     or v_booking.user_payable_amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end if;

  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.owner_type = v_booking.booking_owner_type
     and wallet.owner_key = v_booking.booking_owner_key
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.wallet_id = v_wallet.id
     and account.currency = upper(v_booking.currency)
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_account.available_balance < v_booking.user_payable_amount then
    return jsonb_build_object(
      'ok', false, 'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance,
      'required', v_booking.user_payable_amount,
      'currency', v_account.currency
    );
  end if;

  v_due_at := case
    when v_booking.ticketing_deadline_at is null then v_now + interval '2 hours'
    else greatest(
      v_now,
      least(v_now + interval '2 hours',
        v_booking.ticketing_deadline_at - interval '1 hour')
    )
  end;

  insert into public.booking_operations (
    booking_id, kind, state, reason_code, reason_detail,
    request_key, request_payload_hash, actor_user_id, actor_role, source,
    prior_stored_status, prior_lifecycle_status, supplier,
    supplier_operation, supplier_unique_trans_id,
    supplier_booking_code_ref, supplier_pnr, supplier_evidence,
    policy_version, claimed_at, external_action_due_at
  ) values (
    v_booking.id, 'imported_manual_ticketing', 'awaiting_external_action',
    'imported_manual_ticketing',
    'Owner placed User Payable on Hold; external ticketing outcome is required.',
    'imported-ticketing:v2:' || v_booking.id::text,
    encode(sha256(convert_to(jsonb_build_object(
      'version', 2, 'bookingId', v_booking.id,
      'ownerType', v_booking.booking_owner_type,
      'ownerKey', v_booking.booking_owner_key,
      'amount', v_booking.user_payable_amount,
      'currency', upper(v_booking.currency)
    )::text, 'UTF8')), 'hex'),
    p_actor_user_id, v_actor_role, 'customer', 'on-hold', 'on-hold',
    v_booking.supplier, 'ManualExternalTicketing',
    v_booking.supplier_refs->>'uniqueTransId', v_booking.booking_code_ref,
    v_booking.pnr,
    jsonb_build_object(
      'paymentHeld', true, 'paymentCaptured', false,
      'supplierApiCalled', false, 'clientRequestKey', p_request_key,
      'importSource', v_booking.import_source,
      'userPayableAmount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'externalActionDueAt', v_due_at,
      'accountingContractVersion', 2
    ),
    2, v_now, v_due_at
  ) returning * into v_operation;

  insert into public.booking_reconciliation_cases (
    subject_booking_id, operation_id, case_type, state,
    reason_code, reason_detail, opened_source, opened_by_user_id,
    opened_by_role, opened_at, assigned_team, assigned_at,
    severity, priority, due_at, escalation_level, evidence,
    financial_disposition, policy_version
  ) values (
    v_booking.id, v_operation.id, 'imported_manual_ticketing', 'assigned',
    'manual_ticketing_required',
    'User Payable is protected in Hold; verify ticketing and Capture or Release.',
    'operation', p_actor_user_id, v_actor_role, v_now,
    'support', v_now, 'high', 30, v_due_at, 0,
    jsonb_build_array(jsonb_build_object(
      'type', 'owner_payment_hold', 'operationId', v_operation.id,
      'amount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'supplierApiCalled', false,
      'accountingContractVersion', 2, 'recordedAt', v_now
    )),
    'none', 2
  ) returning * into v_case;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts set
    available_balance = available_balance - v_booking.user_payable_amount,
    hold_balance = hold_balance + v_booking.user_payable_amount
  where id = v_account.id;

  insert into public.wallet_reservations (
    wallet_account_id, booking_id, amount, currency, state,
    requested_by_user_id
  ) values (
    v_account.id, v_booking.id, v_booking.user_payable_amount,
    v_account.currency, 'active', p_actor_user_id
  ) returning * into v_reservation;

  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks, metadata
  ) values (
    v_account.id, 'booking_hold', v_booking.user_payable_amount,
    v_account.currency, v_available_before,
    v_available_before - v_booking.user_payable_amount,
    v_hold_before, v_hold_before + v_booking.user_payable_amount,
    v_booking.id, v_booking.public_ref, v_reservation.id,
    p_request_key || ':hold', p_actor_user_id, v_actor_role,
    'Imported booking Issue Now Hold',
    jsonb_build_object(
      'importSource', v_booking.import_source,
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'supplierGrossAmount', v_booking.supplier_gross_amount,
      'userPayableAmount', v_booking.user_payable_amount,
      'supplierApiCalled', false, 'accountingContractVersion', 2
    )
  );

  update public.flight_bookings set
    charged_wallet_account_id = v_account.id,
    payment_state = 'held', payment_amount = user_payable_amount,
    captured_amount = 0, status = 'in-progress',
    active_operation_id = v_operation.id,
    operation_kind = 'ticketing',
    operation_reason = 'imported_manual_ticketing',
    operation_request_id = p_request_key,
    operation_actor_user_id = p_actor_user_id,
    operation_started_at = v_now,
    operation_prior_status = 'on-hold'
  where id = v_booking.id;

  select count(*)::integer + 1 into v_occurrence
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'in-progress';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number, effective_at,
    observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'ticketing', 'imported_manual_ticketing', p_actor_user_id,
    'ImportCustomerIssueNow',
    jsonb_build_object(
      'walletHeld', true, 'walletCaptured', false,
      'supplierApiCalled', false, 'importSource', v_booking.import_source,
      'userPayableAmount', v_booking.user_payable_amount,
      'accountingContractVersion', 2
    ),
    p_request_key || ':in-progress', v_operation.id, v_case.id,
    v_occurrence, v_now, v_now,
    jsonb_build_object(
      'version', 2, 'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'in-progress', 'paymentState', 'held',
      'operationKind', 'imported_manual_ticketing',
      'operationSource', 'imported_manual_ticketing',
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'userPayableAmount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'accountingContractVersion', 2
    ), 2
  ) returning id into v_event_id;

  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, metadata
  ) values (
    p_actor_user_id, v_actor_role, 'booking.imported.issue_now',
    'flight_booking', v_booking.id::text, 'succeeded',
    jsonb_build_object(
      'requestKey', p_request_key, 'importSource', v_booking.import_source,
      'walletEffect', 'hold', 'amount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'reservationId', v_reservation.id,
      'supplierApiCalled', false
    )
  );

  return jsonb_build_object(
    'ok', true, 'replay', false, 'status', 'in-progress',
    'paymentState', 'held', 'operationId', v_operation.id,
    'reconciliationCaseId', v_case.id,
    'reservationId', v_reservation.id, 'accountId', v_account.id,
    'lifecycleEventId', v_event_id,
    'amount', v_booking.user_payable_amount,
    'currency', v_account.currency,
    'availableBalance', v_available_before - v_booking.user_payable_amount,
    'holdBalance', v_hold_before + v_booking.user_payable_amount
  );
end;
$$;

-- Read-only staff context. The reservation and immutable ledger decide whether
-- this is a new active-Hold row or a legacy captured-before-ticketing row.
create or replace function public.imported_ticketing_resolution_context_v1(
  p_booking_id uuid,
  p_actor_user_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text;
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_reservation_count integer;
  v_hold_count integer;
  v_capture_count integer;
  v_refund_amount bigint;
  v_hold_net bigint;
  v_accounting_mode text;
begin
  select role into v_role from public.app_users where clerk_id = p_actor_user_id;
  if v_role is null or v_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_RESOLUTION_FORBIDDEN');
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
     and booking.import_source in ('IMP_EXP', 'MANUAL');
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  if exists (
    select 1 from public.imported_ticketing_resolutions resolution
     where resolution.booking_id = v_booking.id
  ) or v_booking.status in ('confirmed', 'cancelled') then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_ALREADY_RESOLVED');
  end if;
  if v_booking.status <> 'in-progress'
     or v_booking.operation_reason not in (
       'imported_manual_ticketing', 'ticketing_reconciliation'
     ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_RESOLVABLE');
  end if;

  if v_booking.active_operation_id is not null then
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_booking.active_operation_id
       and operation.booking_id = v_booking.id
       and operation.kind = 'imported_manual_ticketing'
       and operation.state in ('awaiting_external_action', 'needs_reconciliation');
  end if;
  if v_operation.id is null then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_OPERATION_NOT_FOUND');
  end if;
  select reconciliation_case.* into v_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = v_booking.id
     and reconciliation_case.operation_id = v_operation.id
     and reconciliation_case.case_type = 'imported_manual_ticketing'
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier', 'awaiting_finance',
       'awaiting_approval'
     )
   order by reconciliation_case.opened_at desc
   limit 1;
  if v_case.id is null then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_CASE_NOT_FOUND');
  end if;

  select count(*)::integer into v_reservation_count
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id;
  if v_reservation_count <> 1 then
    return jsonb_build_object('ok', false, 'code',
      case when v_reservation_count = 0 then 'IMPORTED_RESERVATION_NOT_FOUND'
        else 'IMPORTED_MULTIPLE_RESERVATIONS' end);
  end if;
  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id;

  select count(*)::integer into v_hold_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.reservation_id = v_reservation.id
     and ledger.transaction_type = 'booking_hold';
  select count(*)::integer into v_capture_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.reservation_id = v_reservation.id
     and ledger.transaction_type = 'booking_confirm';
  select coalesce(sum(ledger.amount), 0)::bigint into v_refund_amount
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
     and ledger.transaction_type = 'refund';

  select wallet.* into v_wallet
    from public.wallet_accounts account
    join public.wallets wallet on wallet.id = account.wallet_id
   where account.id = v_reservation.wallet_account_id
     and wallet.owner_type = v_booking.booking_owner_type
     and wallet.owner_key = v_booking.booking_owner_key;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_OWNER_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id
     and account.wallet_id = v_wallet.id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;

  if v_reservation.amount <> v_booking.user_payable_amount
     or v_reservation.currency <> upper(v_booking.currency)
     or v_account.currency <> v_reservation.currency
     or v_booking.charged_wallet_account_id is distinct from v_account.id then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_RESERVATION_ACCOUNT_CONFLICT');
  end if;

  if v_reservation.state in ('active', 'reconciliation') then
    select coalesce(sum(case
      when ledger.transaction_type = 'booking_hold' then ledger.amount
      when ledger.transaction_type = 'hold_release' then -ledger.amount
      when ledger.transaction_type = 'booking_confirm'
       and ledger.hold_before - ledger.hold_after = ledger.amount
        then -ledger.amount
      else 0 end), 0)::bigint into v_hold_net
      from public.wallet_ledger_entries ledger
     where ledger.reservation_id = v_reservation.id;
    if v_hold_count <> 1 or v_capture_count <> 0
       or v_hold_net <> v_reservation.amount
       or v_account.hold_balance < v_reservation.amount
       or v_booking.payment_state not in ('held', 'reconciliation')
       or v_booking.captured_amount <> 0
       or v_booking.refunded_amount <> 0 then
      return jsonb_build_object('ok', false, 'code', 'IMPORTED_ACTIVE_HOLD_CONFLICT');
    end if;
    v_accounting_mode := 'active_hold';
  elsif v_reservation.state = 'captured' then
    if v_capture_count <> 1
       or v_booking.payment_state not in (
         'captured', 'partially-refunded', 'refunded'
       )
       or v_booking.captured_amount <> v_reservation.amount
       or v_booking.refunded_amount <> v_refund_amount
       or v_refund_amount > v_booking.captured_amount then
      return jsonb_build_object('ok', false, 'code', 'IMPORTED_LEGACY_CAPTURE_CONFLICT');
    end if;
    v_accounting_mode := 'legacy_captured';
  else
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_RESERVATION_STATE_CONFLICT');
  end if;

  return jsonb_build_object(
    'ok', true, 'bookingId', v_booking.id,
    'bookingReference', v_booking.public_ref,
    'importSource', v_booking.import_source,
    'status', v_booking.status, 'paymentState', v_booking.payment_state,
    'accountingMode', v_accounting_mode,
    'operationId', v_operation.id, 'operationState', v_operation.state,
    'reconciliationCaseId', v_case.id, 'caseState', v_case.state,
    'reservationId', v_reservation.id,
    'reservationState', v_reservation.state,
    'walletId', v_wallet.id, 'walletAccountId', v_account.id,
    'walletStatus', v_wallet.status,
    'walletOwnerType', v_wallet.owner_type,
    'walletOwnerKey', v_wallet.owner_key,
    'currency', v_account.currency,
    'userPayableAmount', v_booking.user_payable_amount,
    'capturedAmount', v_booking.captured_amount,
    'refundedAmount', v_booking.refunded_amount,
    'outstandingAmount', v_booking.captured_amount - v_booking.refunded_amount,
    'availableBefore', v_account.available_balance,
    'holdBefore', v_account.hold_balance,
    'confirmEffect', case when v_accounting_mode = 'active_hold'
      then 'capture_hold' else 'none' end,
    'confirmAmount', case when v_accounting_mode = 'active_hold'
      then v_reservation.amount else 0 end,
    'confirmAvailableAfter', v_account.available_balance,
    'confirmHoldAfter', case when v_accounting_mode = 'active_hold'
      then v_account.hold_balance - v_reservation.amount
      else v_account.hold_balance end,
    'cancelEffect', case when v_accounting_mode = 'active_hold'
      then 'release_hold' else 'refund_decision_required' end,
    'cancelAmount', case when v_accounting_mode = 'active_hold'
      then v_reservation.amount else v_booking.captured_amount - v_booking.refunded_amount end,
    'cancelAvailableAfter', case when v_accounting_mode = 'active_hold'
      then v_account.available_balance + v_reservation.amount
      else null end,
    'cancelHoldAfter', case when v_accounting_mode = 'active_hold'
      then v_account.hold_balance - v_reservation.amount
      else v_account.hold_balance end
  );
end;
$$;

create or replace function public.resolve_imported_booking_ticketing_v1(
  p_booking_id uuid,
  p_actor_user_id text,
  p_decision text,
  p_data jsonb,
  p_request_key text,
  p_money_effect_confirmed boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text;
  v_booking public.flight_bookings;
  v_existing public.imported_ticketing_resolutions;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_wallet_id uuid;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_context jsonb;
  v_request_hash text;
  v_accounting_mode text;
  v_ticket_numbers jsonb := '[]'::jsonb;
  v_traveller_count integer;
  v_issued_at timestamptz;
  v_cancellation_at timestamptz;
  v_cancellation_reason text;
  v_refund_disposition text;
  v_requested_refund bigint;
  v_external_reference text;
  v_refund_amount bigint := 0;
  v_wallet_effect text := 'none';
  v_wallet_amount bigint := 0;
  v_available_before bigint;
  v_available_after bigint;
  v_hold_before bigint;
  v_hold_after bigint;
  v_ledger_id uuid;
  v_event_id bigint;
  v_resolution_id uuid := gen_random_uuid();
  v_occurrence integer;
  v_to_status text;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_booking_id is null
     or p_decision not in ('confirm_ticketed', 'cancel')
     or p_data is null or jsonb_typeof(p_data) <> 'object'
     or p_request_key !~ '^imported-resolution:v1:[0-9a-f-]{36}$'
     or p_money_effect_confirmed is not true then
    return jsonb_build_object('ok', false, 'code',
      case when p_money_effect_confirmed is not true
        then 'IMPORTED_EFFECT_CONFIRMATION_REQUIRED'
        else 'INVALID_IMPORTED_RESOLUTION_REQUEST' end);
  end if;
  select role into v_role from public.app_users where clerk_id = p_actor_user_id;
  if v_role is null or v_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_RESOLUTION_FORBIDDEN');
  end if;

  v_request_hash := encode(sha256(convert_to(jsonb_build_object(
    'bookingId', p_booking_id, 'decision', p_decision, 'data', p_data
  )::text, 'UTF8')), 'hex');

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
     and booking.import_source in ('IMP_EXP', 'MANUAL')
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;
  select resolution.* into v_existing
    from public.imported_ticketing_resolutions resolution
   where resolution.request_key = p_request_key;
  if found then
    if v_existing.booking_id <> v_booking.id
       or v_existing.actor_user_id <> p_actor_user_id
       or v_existing.request_hash <> v_request_hash then
      return jsonb_build_object('ok', false, 'code', 'IMPORTED_RESOLUTION_IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing.result || jsonb_build_object('ok', true, 'replay', true);
  end if;
  if v_booking.status in ('confirmed', 'cancelled')
     or exists (select 1 from public.imported_ticketing_resolutions resolution
       where resolution.booking_id = v_booking.id) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_ALREADY_RESOLVED');
  end if;

  if v_booking.active_operation_id is not null then
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_booking.active_operation_id
     for update;
  end if;
  if v_operation.id is not null then
    select reconciliation_case.* into v_case
      from public.booking_reconciliation_cases reconciliation_case
     where reconciliation_case.subject_booking_id = v_booking.id
       and reconciliation_case.operation_id = v_operation.id
       and reconciliation_case.case_type = 'imported_manual_ticketing'
       and reconciliation_case.state in (
         'open', 'assigned', 'awaiting_supplier', 'awaiting_finance',
         'awaiting_approval'
       )
     order by reconciliation_case.opened_at desc
     limit 1
     for update;
  end if;
  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_RESERVATION_NOT_FOUND');
  end if;
  select account.wallet_id into v_wallet_id
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id;
  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.id = v_wallet_id
   for update;
  select account.* into v_account
    from public.wallet_accounts account
   where account.id = v_reservation.wallet_account_id
     and account.wallet_id = v_wallet.id
   for update;

  v_context := public.imported_ticketing_resolution_context_v1(
    v_booking.id, p_actor_user_id
  );
  if coalesce((v_context->>'ok')::boolean, false) is not true then
    return v_context;
  end if;
  if (v_context->>'availableBefore')::bigint <> v_account.available_balance
     or (v_context->>'holdBefore')::bigint <> v_account.hold_balance
     or (v_context->>'reservationId')::uuid <> v_reservation.id then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ACCOUNTING_STATE_CHANGED');
  end if;
  v_accounting_mode := v_context->>'accountingMode';

  if p_decision = 'confirm_ticketed' then
    begin
      v_issued_at := nullif(p_data->>'issuedAt', '')::timestamptz;
    exception when others then
      v_issued_at := null;
    end;
    v_ticket_numbers := coalesce(p_data->'ticketNumbers', '[]'::jsonb);
    v_traveller_count := case
      when jsonb_typeof(v_booking.passengers->'travellers') = 'array'
        then jsonb_array_length(v_booking.passengers->'travellers')
      else 0 end;
    if v_issued_at is null or v_issued_at > v_now
       or v_traveller_count <= 0
       or jsonb_typeof(v_ticket_numbers) <> 'array'
       or jsonb_array_length(v_ticket_numbers) <> v_traveller_count
       or exists (
         select 1 from jsonb_array_elements(v_ticket_numbers) ticket(value)
          where jsonb_typeof(ticket.value) <> 'string'
             or nullif(btrim(ticket.value #>> '{}'), '') is null
       )
       or (select count(distinct upper(ticket.value #>> '{}'))
             from jsonb_array_elements(v_ticket_numbers) ticket(value))
          <> v_traveller_count then
      return jsonb_build_object('ok', false, 'code', 'IMPORTED_TICKET_EVIDENCE_REQUIRED');
    end if;
    v_to_status := 'confirmed';
  else
    begin
      v_cancellation_at := nullif(p_data->>'cancellationAt', '')::timestamptz;
    exception when others then
      v_cancellation_at := null;
    end;
    v_cancellation_reason := nullif(btrim(p_data->>'cancellationReason'), '');
    v_refund_disposition := nullif(btrim(p_data->>'refundDisposition'), '');
    v_external_reference := nullif(btrim(p_data->>'externalSettlementReference'), '');
    begin
      v_requested_refund := nullif(p_data->>'refundAmount', '')::bigint;
    exception when others then
      v_requested_refund := null;
    end;
    if v_cancellation_at is null
       or v_cancellation_at > v_now
       or v_cancellation_reason is null then
      return jsonb_build_object('ok', false, 'code', 'IMPORTED_CANCELLATION_DETAILS_REQUIRED');
    end if;
    if v_accounting_mode = 'active_hold' then
      if v_refund_disposition is not null
         and v_refund_disposition <> 'release_existing_hold' then
        return jsonb_build_object('ok', false, 'code', 'IMPORTED_REFUND_NOT_ALLOWED_FOR_HOLD');
      end if;
      v_refund_disposition := null;
    else
      if v_refund_disposition not in (
        'full_refund', 'partial_refund', 'no_refund_due', 'externally_settled'
      ) then
        return jsonb_build_object('ok', false, 'code', 'IMPORTED_REFUND_DECISION_REQUIRED');
      end if;
      if v_refund_disposition = 'full_refund' then
        v_refund_amount := (v_context->>'outstandingAmount')::bigint;
        if v_refund_amount <= 0 then
          return jsonb_build_object('ok', false, 'code', 'IMPORTED_NOTHING_TO_REFUND');
        end if;
      elsif v_refund_disposition = 'partial_refund' then
        v_refund_amount := coalesce(v_requested_refund, 0);
        if v_refund_amount <= 0
           or v_refund_amount >= (v_context->>'outstandingAmount')::bigint then
          return jsonb_build_object('ok', false, 'code', 'IMPORTED_PARTIAL_REFUND_INVALID');
        end if;
      elsif v_refund_disposition = 'externally_settled'
         and v_external_reference is null then
        return jsonb_build_object('ok', false, 'code', 'IMPORTED_EXTERNAL_REFERENCE_REQUIRED');
      end if;
    end if;
    v_to_status := 'cancelled';
  end if;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  v_available_after := v_available_before;
  v_hold_after := v_hold_before;

  if v_accounting_mode = 'active_hold' then
    if v_account.hold_balance < v_reservation.amount then
      return jsonb_build_object('ok', false, 'code', 'IMPORTED_HOLD_BALANCE_MISMATCH');
    end if;
    v_wallet_amount := v_reservation.amount;
    v_hold_after := v_hold_before - v_wallet_amount;
    if p_decision = 'confirm_ticketed' then
      v_wallet_effect := 'capture_hold';
      update public.wallet_accounts set hold_balance = v_hold_after
       where id = v_account.id;
      update public.wallet_reservations set
        state = 'captured', issued_by_user_id = p_actor_user_id,
        captured_at = v_now, reconciliation_at = null,
        reconciliation_reason = null
      where id = v_reservation.id
        and state in ('active', 'reconciliation');
      insert into public.wallet_ledger_entries (
        wallet_account_id, transaction_type, amount, currency,
        available_before, available_after, hold_before, hold_after,
        booking_id, booking_reference, reservation_id, idempotency_key,
        created_by_user_id, created_by_role, remarks, metadata
      ) values (
        v_account.id, 'booking_confirm', v_wallet_amount, v_account.currency,
        v_available_before, v_available_after, v_hold_before, v_hold_after,
        v_booking.id, v_booking.public_ref, v_reservation.id,
        p_request_key || ':ledger', p_actor_user_id, v_role,
        'Imported ticketing Hold captured after verified issuance',
        jsonb_build_object(
          'importSource', v_booking.import_source,
          'supplierGrossAmount', v_booking.supplier_gross_amount,
          'userPayableAmount', v_booking.user_payable_amount,
          'resolutionId', v_resolution_id,
          'accountingContractVersion', 2
        )
      ) returning id into v_ledger_id;
    else
      v_wallet_effect := 'release_hold';
      v_available_after := v_available_before + v_wallet_amount;
      update public.wallet_accounts set
        available_balance = v_available_after, hold_balance = v_hold_after
      where id = v_account.id;
      update public.wallet_reservations set
        state = 'released', released_at = v_now,
        release_reason = left(v_cancellation_reason, 1000),
        reconciliation_at = null, reconciliation_reason = null
      where id = v_reservation.id
        and state in ('active', 'reconciliation');
      insert into public.wallet_ledger_entries (
        wallet_account_id, transaction_type, amount, currency,
        available_before, available_after, hold_before, hold_after,
        booking_id, booking_reference, reservation_id, idempotency_key,
        created_by_user_id, created_by_role, remarks, metadata
      ) values (
        v_account.id, 'hold_release', v_wallet_amount, v_account.currency,
        v_available_before, v_available_after, v_hold_before, v_hold_after,
        v_booking.id, v_booking.public_ref, v_reservation.id,
        p_request_key || ':ledger', p_actor_user_id, v_role,
        left(v_cancellation_reason, 1000),
        jsonb_build_object(
          'importSource', v_booking.import_source,
          'userPayableAmount', v_booking.user_payable_amount,
          'resolutionId', v_resolution_id,
          'accountingContractVersion', 2
        )
      ) returning id into v_ledger_id;
    end if;
  elsif p_decision = 'cancel' and v_refund_amount > 0 then
    v_wallet_effect := 'refund';
    v_wallet_amount := v_refund_amount;
    v_available_after := v_available_before + v_refund_amount;
    update public.wallet_accounts set available_balance = v_available_after
     where id = v_account.id;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'refund', v_refund_amount, v_account.currency,
      v_available_before, v_available_after, v_hold_before, v_hold_after,
      v_booking.id, v_booking.public_ref, v_reservation.id,
      p_request_key || ':ledger', p_actor_user_id, v_role,
      left(v_cancellation_reason, 1000),
      jsonb_build_object(
        'importSource', v_booking.import_source,
        'resolutionId', v_resolution_id,
        'refundDisposition', v_refund_disposition,
        'legacyCapturedBeforeTicketing', true
      )
    ) returning id into v_ledger_id;
  end if;

  update public.booking_operations set
    state = 'succeeded', completed_at = v_now,
    reason_detail = case when p_decision = 'confirm_ticketed'
      then 'Imported ticket issuance verified and wallet settlement completed.'
      else 'Imported non-issuance verified and wallet disposition completed.' end,
    supplier_evidence = coalesce(supplier_evidence, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
        'importedResolutionId', v_resolution_id,
        'decision', p_decision, 'ticketNumbers', v_ticket_numbers,
        'issuedAt', v_issued_at, 'cancellationAt', v_cancellation_at,
        'cancellationReason', v_cancellation_reason,
        'refundDisposition', v_refund_disposition,
        'externalSettlementReference', v_external_reference,
        'walletEffect', v_wallet_effect, 'walletAmount', v_wallet_amount,
        'resolvedAt', v_now
      ))
  where id = v_operation.id;

  update public.booking_reconciliation_cases set
    state = 'resolved',
    financial_disposition = case
      when v_accounting_mode = 'active_hold' and p_decision = 'confirm_ticketed'
        then 'capture_existing_hold'
      when v_accounting_mode = 'active_hold' and p_decision = 'cancel'
        then 'release_existing_hold'
      when p_decision = 'cancel' then v_refund_disposition
      else 'none' end,
    financial_amount = case
      when v_wallet_effect in ('capture_hold', 'release_hold', 'refund')
        then v_wallet_amount else null end,
    financial_currency = case
      when v_wallet_effect in ('capture_hold', 'release_hold', 'refund')
        then v_account.currency else null end,
    external_settlement_reference = v_external_reference,
    resolution_outcome = case when p_decision = 'confirm_ticketed'
      then 'imported_ticketed' else 'imported_cancelled' end,
    resolution = jsonb_strip_nulls(jsonb_build_object(
      'version', 2, 'resolutionKind', 'imported_ticketing_resolution',
      'resolutionId', v_resolution_id, 'requestKey', p_request_key,
      'decision', p_decision, 'accountingMode', v_accounting_mode,
      'walletEffect', v_wallet_effect, 'walletAmount', v_wallet_amount,
      'ledgerEntryId', v_ledger_id, 'ticketNumbers', v_ticket_numbers,
      'issuedAt', v_issued_at, 'cancellationAt', v_cancellation_at,
      'cancellationReason', v_cancellation_reason,
      'refundDisposition', v_refund_disposition,
      'externalSettlementReference', v_external_reference
    )),
    resolution_reason = coalesce(v_cancellation_reason,
      'Imported ticket issuance verified'),
    resolved_by_user_id = p_actor_user_id,
    resolved_at = v_now, closed_at = v_now, version = version + 1
  where id = v_case.id;

  update public.flight_bookings set
    status = v_to_status,
    payment_state = case
      when v_accounting_mode = 'active_hold' and p_decision = 'confirm_ticketed'
        then 'captured'
      when v_accounting_mode = 'active_hold' and p_decision = 'cancel'
        then 'released'
      when p_decision = 'cancel'
       and refunded_amount + v_refund_amount = captured_amount
       and captured_amount > 0 then 'refunded'
      when p_decision = 'cancel' and v_refund_amount > 0
        then 'partially-refunded'
      else payment_state end,
    captured_amount = case
      when v_accounting_mode = 'active_hold' and p_decision = 'confirm_ticketed'
        then v_reservation.amount
      else captured_amount end,
    refunded_amount = refunded_amount + v_refund_amount,
    direct_ticketing = case when p_decision = 'confirm_ticketed'
      then true else direct_ticketing end,
    ticket_numbers = case when p_decision = 'confirm_ticketed'
      then v_ticket_numbers else ticket_numbers end,
    issued_at = case when p_decision = 'confirm_ticketed'
      then v_issued_at else issued_at end,
    issued_by_user_id = case when p_decision = 'confirm_ticketed'
      then p_actor_user_id else issued_by_user_id end,
    booking_status = case when p_decision = 'confirm_ticketed'
      then 'Confirmed' else booking_status end,
    cancelled_at = case when p_decision = 'cancel'
      then v_cancellation_at else cancelled_at end,
    cancelled_by = case when p_decision = 'cancel'
      then p_actor_user_id else cancelled_by end,
    cancel_reason = case when p_decision = 'cancel'
      then left(v_cancellation_reason, 1000) else cancel_reason end,
    active_operation_id = null, operation_kind = null,
    operation_reason = null, operation_request_id = null,
    operation_actor_user_id = null, operation_started_at = null,
    operation_prior_status = null
  where id = v_booking.id;

  select count(*)::integer + 1 into v_occurrence
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = v_to_status;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number, effective_at,
    observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, 'in-progress', v_to_status,
    'in-progress', v_to_status, 'ticketing',
    'imported_manual_ticketing', p_actor_user_id,
    'ImportedTicketingResolution',
    jsonb_strip_nulls(jsonb_build_object(
      'resolutionId', v_resolution_id, 'decision', p_decision,
      'accountingMode', v_accounting_mode,
      'walletEffect', v_wallet_effect, 'walletAmount', v_wallet_amount,
      'ticketNumbers', v_ticket_numbers, 'issuedAt', v_issued_at,
      'cancellationAt', v_cancellation_at,
      'refundDisposition', v_refund_disposition
    )),
    p_request_key || ':status', v_operation.id, v_case.id,
    v_occurrence, coalesce(v_issued_at, v_cancellation_at, v_now), v_now,
    jsonb_strip_nulls(jsonb_build_object(
      'version', 2, 'bookingReference', v_booking.public_ref,
      'lifecycleStatus', v_to_status,
      'paymentState', case
        when v_accounting_mode = 'active_hold' and p_decision = 'confirm_ticketed'
          then 'captured'
        when v_accounting_mode = 'active_hold' and p_decision = 'cancel'
          then 'released'
        when v_refund_amount > 0 then 'refunded_or_partial'
        else v_booking.payment_state end,
      'operationSource', 'imported_ticketing_resolution',
      'accountingMode', v_accounting_mode,
      'walletEffect', v_wallet_effect, 'walletAmount', v_wallet_amount,
      'currency', v_account.currency, 'resolutionId', v_resolution_id
    )), 2
  ) returning id into v_event_id;

  v_result := jsonb_build_object(
    'ok', true, 'replay', false, 'resolutionId', v_resolution_id,
    'bookingId', v_booking.id, 'bookingReference', v_booking.public_ref,
    'status', v_to_status, 'decision', p_decision,
    'accountingMode', v_accounting_mode,
    'walletEffect', v_wallet_effect, 'walletAmount', v_wallet_amount,
    'currency', v_account.currency,
    'availableBefore', v_available_before,
    'availableAfter', v_available_after,
    'holdBefore', v_hold_before, 'holdAfter', v_hold_after,
    'ledgerEntryId', v_ledger_id, 'lifecycleEventId', v_event_id,
    'reservationId', v_reservation.id,
    'reconciliationCaseId', v_case.id
  );

  insert into public.imported_ticketing_resolutions (
    id, booking_id, booking_reference, request_key, request_hash,
    import_source, decision, accounting_mode, wallet_account_id,
    reservation_id, wallet_effect, wallet_amount, currency,
    available_before, available_after, hold_before, hold_after,
    ticket_numbers, issued_at, cancellation_at, cancellation_reason,
    refund_disposition, refund_amount, external_settlement_reference,
    actor_user_id, actor_role, operation_id, reconciliation_case_id,
    ledger_entry_id, lifecycle_event_id, result
  ) values (
    v_resolution_id, v_booking.id, v_booking.public_ref,
    p_request_key, v_request_hash, v_booking.import_source,
    p_decision, v_accounting_mode, v_account.id, v_reservation.id,
    v_wallet_effect, v_wallet_amount, v_account.currency,
    v_available_before, v_available_after, v_hold_before, v_hold_after,
    v_ticket_numbers, v_issued_at, v_cancellation_at,
    v_cancellation_reason, v_refund_disposition, v_refund_amount,
    v_external_reference, p_actor_user_id, v_role, v_operation.id,
    v_case.id, v_ledger_id, v_event_id, v_result
  );

  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, metadata
  ) values (
    p_actor_user_id, v_role, 'booking.imported.ticketing_resolution',
    'flight_booking', v_booking.id::text, 'succeeded',
    jsonb_build_object(
      'requestKey', p_request_key, 'resolutionId', v_resolution_id,
      'importSource', v_booking.import_source, 'decision', p_decision,
      'accountingMode', v_accounting_mode,
      'walletEffect', v_wallet_effect, 'walletAmount', v_wallet_amount,
      'currency', v_account.currency
    )
  );
  return v_result;
end;
$$;

-- Compatibility signature used by the existing application boundary. Its
-- meaning is now imported Issue Now (Hold), not pre-ticketing capture.
create or replace function public.wallet_confirm_impexp_booking(
  p_booking_id uuid,
  p_actor_user_id text,
  p_idempotency_key text
)
returns jsonb
language sql
security definer
set search_path = public
as $$
  select public.wallet_begin_imported_booking_issue_v2(
    p_booking_id,
    p_actor_user_id,
    'imported-issue:v2:' || p_idempotency_key
  )
$$;

-- The pre-0108 manual status command could confirm directly from On Hold and
-- debit Available without the owner Issue Now Hold. Preserve its non-financial
-- status commands behind a wrapper, but make imported confirmation exclusive
-- to the dedicated resolver above.
alter function public.update_manual_booking_status_v1(
  uuid, text, text, jsonb, text
) rename to update_manual_booking_status_legacy_0108;

revoke all on function public.update_manual_booking_status_legacy_0108(
  uuid, text, text, jsonb, text
) from public, anon, authenticated, service_role;

create function public.update_manual_booking_status_v1(
  p_booking_id uuid,
  p_actor_user_id text,
  p_target_status text,
  p_data jsonb,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_target_status = 'confirmed' then
    return jsonb_build_object(
      'ok', false,
      'code', 'IMPORTED_TICKETING_RESOLUTION_REQUIRED'
    );
  end if;
  return public.update_manual_booking_status_legacy_0108(
    p_booking_id,
    p_actor_user_id,
    p_target_status,
    p_data,
    p_request_key
  );
end;
$$;

revoke all on function public.wallet_begin_imported_booking_issue_v2(
  uuid, text, text
) from public, anon, authenticated;
revoke all on function public.imported_ticketing_resolution_context_v1(
  uuid, text
) from public, anon, authenticated;
revoke all on function public.resolve_imported_booking_ticketing_v1(
  uuid, text, text, jsonb, text, boolean
) from public, anon, authenticated;
revoke all on function public.wallet_confirm_impexp_booking(
  uuid, text, text
) from public, anon, authenticated;
revoke all on function public.update_manual_booking_status_v1(
  uuid, text, text, jsonb, text
) from public, anon, authenticated;
grant execute on function public.wallet_begin_imported_booking_issue_v2(
  uuid, text, text
) to service_role;
grant execute on function public.imported_ticketing_resolution_context_v1(
  uuid, text
) to service_role;
grant execute on function public.resolve_imported_booking_ticketing_v1(
  uuid, text, text, jsonb, text, boolean
) to service_role;
grant execute on function public.wallet_confirm_impexp_booking(
  uuid, text, text
) to service_role;
grant execute on function public.update_manual_booking_status_v1(
  uuid, text, text, jsonb, text
) to service_role;

comment on function public.wallet_begin_imported_booking_issue_v2(
  uuid, text, text
) is
  'Atomically moves imported User Payable from Available to an active Hold and opens imported external ticketing; it never calls a supplier API.';
comment on function public.resolve_imported_booking_ticketing_v1(
  uuid, text, text, jsonb, text, boolean
) is
  'Atomically captures/releases a new imported Hold or safely handles a legacy pre-ticketing capture with required ticket/cancellation evidence and idempotent audit history.';


-- SOURCE: 0109_supplier_reference_api_import.sql
-- Canonical FirstTrip/TakeOff booking import by supplier uniqueTransID.
-- These rows remain ordinary Triplover API bookings: import_source stays NULL,
-- the real reference chain and supplier_account are immutable, and every
-- existing Issue/Cancel/PNR/wallet/lifecycle path continues to apply.

alter table public.flight_bookings
  add column if not exists booking_origin text;

alter table public.flight_bookings
  drop constraint if exists flight_bookings_booking_origin_check;
alter table public.flight_bookings
  add constraint flight_bookings_booking_origin_check
  check (
    booking_origin is null
    or booking_origin = 'supplier_reference_import'
  );

create unique index if not exists
  flight_bookings_supplier_account_unique_trans_id_key
  on public.flight_bookings (
    supplier_account,
    ((supplier_refs->>'uniqueTransId'))
  )
  where not legacy_operational
    and supplier_account is not null
    and nullif(btrim(supplier_refs->>'uniqueTransId'), '') is not null;

create index if not exists flight_bookings_supplier_reference_origin_created_idx
  on public.flight_bookings (created_at desc)
  where booking_origin = 'supplier_reference_import';

comment on column public.flight_bookings.booking_origin is
  'Nullable audit origin. supplier_reference_import marks API-backed FirstTrip/TakeOff imports without changing their ordinary Triplover operational behavior.';

create or replace function public.protect_supplier_reference_booking_identity_v1()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if old.booking_origin = 'supplier_reference_import' and (
    new.booking_origin is distinct from old.booking_origin
    or new.supplier is distinct from old.supplier
    or new.supplier_account is distinct from old.supplier_account
    or new.supplier_refs->>'uniqueTransId'
       is distinct from old.supplier_refs->>'uniqueTransId'
    or new.supplier_refs->>'itemCodeRef'
       is distinct from old.supplier_refs->>'itemCodeRef'
    or new.supplier_refs->>'priceCodeRef'
       is distinct from old.supplier_refs->>'priceCodeRef'
    or new.booking_code_ref is distinct from old.booking_code_ref
    or new.booking_ref_number is distinct from old.booking_ref_number
  ) then
    raise exception 'supplier-reference booking identity is immutable'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists flight_bookings_protect_supplier_reference_identity_v1
  on public.flight_bookings;
create trigger flight_bookings_protect_supplier_reference_identity_v1
  before update of
    booking_origin, supplier, supplier_account, supplier_refs,
    booking_code_ref, booking_ref_number
  on public.flight_bookings
  for each row execute function
    public.protect_supplier_reference_booking_identity_v1();

revoke all on function
  public.protect_supplier_reference_booking_identity_v1()
  from public, anon, authenticated;

create table if not exists public.supplier_reference_charge_authorizations (
  id                         uuid primary key default gen_random_uuid(),
  request_key                text not null unique,
  actor_user_id              text not null,
  actor_role                 text not null,
  assigned_user_id           text not null,
  owner_type                 text not null,
  owner_key                  text not null,
  supplier_account           text not null,
  supplier_reference         text not null,
  currency                   text not null,
  user_payable_amount        bigint not null,
  supplier_gross_amount      bigint not null,
  authorization_payload_hash text not null,
  authorized_at              timestamptz not null default clock_timestamp(),
  expires_at                 timestamptz not null,
  consumed_at                timestamptz,
  consumed_booking_id        uuid
                             references public.flight_bookings(id)
                             on delete restrict,
  created_at                 timestamptz not null default clock_timestamp(),
  constraint supplier_reference_charge_actor_role_check
    check (actor_role in ('staff_support', 'admin', 'superadmin')),
  constraint supplier_reference_charge_owner_check
    check (owner_type in ('user', 'agency') and btrim(owner_key) <> ''),
  constraint supplier_reference_charge_account_check
    check (supplier_account in ('firsttrip', 'takeoff')),
  constraint supplier_reference_charge_reference_check
    check (supplier_reference ~ '^(FST|TOT)[0-9]{18}$'),
  constraint supplier_reference_charge_currency_check
    check (currency ~ '^[A-Z]{3}$'),
  constraint supplier_reference_charge_amount_check
    check (user_payable_amount > 0 and supplier_gross_amount > 0),
  constraint supplier_reference_charge_hash_check
    check (authorization_payload_hash ~ '^[a-f0-9]{64}$'),
  constraint supplier_reference_charge_request_check
    check (
      request_key ~ '^supplier-reference-charge:v1:[0-9a-f-]{36}$'
    ),
  constraint supplier_reference_charge_time_check
    check (expires_at > authorized_at),
  constraint supplier_reference_charge_consumption_check
    check (
      (consumed_at is null and consumed_booking_id is null)
      or (consumed_at is not null and consumed_booking_id is not null)
    )
);

create index if not exists supplier_reference_charge_expiry_idx
  on public.supplier_reference_charge_authorizations (expires_at, id)
  where consumed_at is null;

alter table public.supplier_reference_charge_authorizations
  enable row level security;
revoke all on table public.supplier_reference_charge_authorizations
  from public, anon, authenticated;
grant select, insert, update
  on table public.supplier_reference_charge_authorizations
  to service_role;

create or replace function public.supplier_reference_import_payload_hash_v1(
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_data jsonb
)
returns text
language sql
immutable
set search_path = public
as $$
  select encode(sha256(convert_to(jsonb_build_object(
    'version', 1,
    'assignedUserId', p_assigned_user_id,
    'userPayableAmount', p_user_payable_amount,
    'supplierGrossAmount', p_supplier_gross_amount,
    -- retrievedAt is the local observation time of each mandatory live fetch.
    -- Authorization and import deliberately fetch again, so that one volatile
    -- field cannot be part of their otherwise exact shared fingerprint.
    'booking', p_data - array[
      'retrievedAt', 'pricingCalculatedAt', 'supplierEvidenceTimestamp'
    ]
  )::text, 'UTF8')), 'hex');
$$;

create or replace function public.supplier_reference_money_minor_v1(
  p_value jsonb
)
returns bigint
language plpgsql
immutable
set search_path = public
as $$
declare
  v_text text;
begin
  if p_value is null or jsonb_typeof(p_value) <> 'number' then return null; end if;
  v_text := p_value #>> '{}';
  if v_text !~ '^-?[0-9]+([.][0-9]+)?$' then return null; end if;
  return round(v_text::numeric * 100)::bigint;
exception when others then
  return null;
end;
$$;

create or replace function public.authorize_supplier_reference_charge_v1(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_data jsonb,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_target_role text;
  v_agency_code text;
  v_audience text;
  v_owner_type text;
  v_owner_key text;
  v_supplier_account text;
  v_supplier_reference text;
  v_currency text;
  v_payload_hash text;
  v_traveller_count integer;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing public.supplier_reference_charge_authorizations;
  v_authorization public.supplier_reference_charge_authorizations;
  v_now timestamptz := clock_timestamp();
begin
  if p_data is null
     or jsonb_typeof(p_data) <> 'object'
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or nullif(btrim(coalesce(p_assigned_user_id, '')), '') is null
     or p_user_payable_amount is null or p_user_payable_amount <= 0
     or p_supplier_gross_amount is null or p_supplier_gross_amount <= 0
     or p_request_key
        !~ '^supplier-reference-charge:v1:[0-9a-f-]{36}$' then
    return jsonb_build_object(
      'ok', false, 'code', 'INVALID_CHARGE_AUTHORIZATION'
    );
  end if;

  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object(
      'ok', false, 'code', 'SUPPLIER_REFERENCE_IMPORT_FORBIDDEN'
    );
  end if;

  select role, agency_code into v_target_role, v_agency_code
    from public.app_users
   where clerk_id = p_assigned_user_id;
  if not found or v_target_role not in ('b2b', 'b2b_sub', 'customer') then
    return jsonb_build_object(
      'ok', false, 'code', 'INVALID_IMPORT_ASSIGNEE'
    );
  end if;
  if v_target_role in ('b2b', 'b2b_sub') then
    if nullif(btrim(v_agency_code), '') is null then
      return jsonb_build_object(
        'ok', false, 'code', 'ASSIGNEE_AGENCY_REQUIRED'
      );
    end if;
    v_owner_type := 'agency';
    v_owner_key := v_agency_code;
    v_audience := 'agency';
  else
    v_owner_type := 'user';
    v_owner_key := p_assigned_user_id;
    v_audience := 'b2c';
    v_agency_code := null;
  end if;

  v_supplier_account := nullif(btrim(p_data->>'supplierAccount'), '');
  v_supplier_reference := nullif(btrim(p_data->>'supplierReference'), '');
  v_currency := upper(coalesce(nullif(btrim(p_data->>'currency'), ''), 'BDT'));
  v_traveller_count := case
    when jsonb_typeof(p_data #> '{passengers,travellers}') = 'array'
      then jsonb_array_length(p_data #> '{passengers,travellers}')
    else 0
  end;
  if v_supplier_account not in ('firsttrip', 'takeoff')
     or v_supplier_reference is null
     or (v_supplier_account = 'firsttrip'
       and v_supplier_reference !~ '^FST[0-9]{18}$')
     or (v_supplier_account = 'takeoff'
       and v_supplier_reference !~ '^TOT[0-9]{18}$')
     or p_data #>> '{supplierRefs,uniqueTransId}'
        is distinct from v_supplier_reference
     or p_data->>'lifecycleStatus' is distinct from 'confirmed'
     or p_data->>'storedStatus' is distinct from 'confirmed'
     or v_currency <> 'BDT'
     or p_data->>'pricingMode' is distinct from 'import_time_current_markup'
     or nullif(p_data->>'pricingCalculatedAt', '') is null
     or nullif(p_data->>'supplierEvidenceTimestamp', '') is null
     or p_data->>'supplierEvidenceTimestamp' is distinct from p_data->>'retrievedAt'
     or jsonb_typeof(p_data->'supplierFares') <> 'array'
     or jsonb_typeof(p_data->'pricingRoutes') <> 'array'
     or coalesce(p_data->>'pricingCarrierCode', '') !~ '^[A-Z0-9]{2}$'
     or jsonb_typeof(p_data->'pricingSnapshot') <> 'object'
     or jsonb_typeof(p_data #> '{pricingSnapshot,components}') <> 'array'
     or p_data #>> '{pricingSnapshot,audience}' is distinct from v_audience
     or p_data #>> '{pricingSnapshot,agencyCode}' is distinct from v_agency_code
     or public.supplier_reference_money_minor_v1(
          p_data #> '{pricingSnapshot,sellingPrice}'
        ) is distinct from p_user_payable_amount
     or public.supplier_reference_money_minor_v1(p_data->'supplierGross')
        is distinct from p_supplier_gross_amount
     or public.supplier_reference_money_minor_v1(
          p_data #> '{pricingSnapshot,grossPrice}'
        ) is distinct from p_supplier_gross_amount
     or public.supplier_reference_money_minor_v1(p_data->'supplierPayable')
        is distinct from public.supplier_reference_money_minor_v1(
          p_data #> '{pricingSnapshot,supplierTotalPrice}'
        ) then
    return jsonb_build_object(
      'ok', false, 'code', 'CHARGE_NOT_APPLICABLE'
    );
  end if;
  if v_traveller_count <= 0
     or jsonb_typeof(p_data->'ticketNumbers') <> 'array'
     or jsonb_array_length(case
          when jsonb_typeof(p_data->'ticketNumbers') = 'array'
            then p_data->'ticketNumbers' else '[]'::jsonb end)
        <> v_traveller_count
     or exists (
       select 1
         from jsonb_array_elements(case
           when jsonb_typeof(p_data->'ticketNumbers') = 'array'
             then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value)
        where jsonb_typeof(ticket.value) <> 'string'
           or nullif(btrim(ticket.value #>> '{}'), '') is null
     )
     or (select count(distinct ticket.value #>> '{}')
           from jsonb_array_elements(case
             when jsonb_typeof(p_data->'ticketNumbers') = 'array'
               then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value))
        <> v_traveller_count then
    return jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_TICKET_EVIDENCE_REQUIRED'
    );
  end if;

  v_payload_hash := public.supplier_reference_import_payload_hash_v1(
    p_assigned_user_id,
    p_user_payable_amount,
    p_supplier_gross_amount,
    p_data
  );
  select * into v_existing
    from public.supplier_reference_charge_authorizations charge_auth
   where charge_auth.request_key = p_request_key
   for update;
  if found then
    if v_existing.actor_user_id = p_actor_user_id
       and v_existing.assigned_user_id = p_assigned_user_id
       and v_existing.authorization_payload_hash = v_payload_hash then
      return jsonb_build_object(
        'ok', true,
        'replay', true,
        'authorizationId', v_existing.id,
        'expiresAt', v_existing.expires_at,
        'consumed', v_existing.consumed_at is not null,
        'amount', v_existing.user_payable_amount,
        'currency', v_existing.currency
      );
    end if;
    raise exception 'supplier-reference charge request identity mismatch'
      using errcode = '22023';
  end if;

  select * into v_wallet
    from public.wallets wallet
   where wallet.owner_type = v_owner_type
     and wallet.owner_key = v_owner_key;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select * into v_account
    from public.wallet_accounts account
   where account.wallet_id = v_wallet.id
     and account.currency = v_currency;
  if not found then
    return jsonb_build_object(
      'ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND'
    );
  end if;
  if v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_account.available_balance < p_user_payable_amount then
    return jsonb_build_object(
      'ok', false,
      'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance,
      'required', p_user_payable_amount,
      'currency', v_currency
    );
  end if;

  insert into public.supplier_reference_charge_authorizations (
    request_key, actor_user_id, actor_role, assigned_user_id,
    owner_type, owner_key, supplier_account, supplier_reference,
    currency, user_payable_amount, supplier_gross_amount,
    authorization_payload_hash, authorized_at, expires_at
  ) values (
    p_request_key, p_actor_user_id, v_actor_role, p_assigned_user_id,
    v_owner_type, v_owner_key, v_supplier_account, v_supplier_reference,
    v_currency, p_user_payable_amount, p_supplier_gross_amount,
    v_payload_hash, v_now, v_now + interval '5 minutes'
  ) returning * into v_authorization;

  return jsonb_build_object(
    'ok', true,
    'replay', false,
    'authorizationId', v_authorization.id,
    'expiresAt', v_authorization.expires_at,
    'consumed', false,
    'amount', v_authorization.user_payable_amount,
    'currency', v_authorization.currency,
    'walletAvailable', v_account.available_balance,
    'walletMutation', false
  );
end;
$$;

create or replace function public.create_supplier_reference_booking_v1(
  p_actor_user_id text,
  p_assigned_user_id text,
  p_user_payable_amount bigint,
  p_supplier_gross_amount bigint,
  p_data jsonb,
  p_import_decision text,
  p_charge_authorization_id uuid,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_target_role text;
  v_agency_code text;
  v_audience text;
  v_owner_type text;
  v_owner_key text;
  v_supplier_account text;
  v_supplier_reference text;
  v_currency text;
  v_status text;
  v_payload_hash text;
  v_traveller_count integer;
  v_existing public.flight_bookings;
  v_authorization public.supplier_reference_charge_authorizations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_booking public.flight_bookings;
  v_reservation public.wallet_reservations;
  v_attempt_id uuid := gen_random_uuid();
  v_booking_id uuid := gen_random_uuid();
  v_search_id uuid := gen_random_uuid();
  v_public_ref text;
  v_available_before bigint;
  v_hold_before bigint;
  v_created_at timestamptz;
  v_issued_at timestamptz;
  v_cancelled_at timestamptz;
  v_deadline_at timestamptz;
  v_effective_at timestamptz;
  v_pricing jsonb;
  v_wallet_charged boolean := false;
begin
  if p_data is null
     or jsonb_typeof(p_data) <> 'object'
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or nullif(btrim(coalesce(p_assigned_user_id, '')), '') is null
     or p_user_payable_amount is null or p_user_payable_amount <= 0
     or p_supplier_gross_amount is null or p_supplier_gross_amount <= 0
     or p_import_decision not in ('import_only', 'import_and_charge')
     or p_request_key
        !~ '^supplier-reference-import:v1:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end if;

  select role into v_actor_role
    from public.app_users
   where clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object(
      'ok', false, 'code', 'SUPPLIER_REFERENCE_IMPORT_FORBIDDEN'
    );
  end if;
  select role, agency_code into v_target_role, v_agency_code
    from public.app_users
   where clerk_id = p_assigned_user_id;
  if not found or v_target_role not in ('b2b', 'b2b_sub', 'customer') then
    return jsonb_build_object(
      'ok', false, 'code', 'INVALID_IMPORT_ASSIGNEE'
    );
  end if;
  if v_target_role in ('b2b', 'b2b_sub') then
    if nullif(btrim(v_agency_code), '') is null then
      return jsonb_build_object(
        'ok', false, 'code', 'ASSIGNEE_AGENCY_REQUIRED'
      );
    end if;
    v_owner_type := 'agency';
    v_owner_key := v_agency_code;
    v_audience := 'agency';
  else
    v_owner_type := 'user';
    v_owner_key := p_assigned_user_id;
    v_audience := 'b2c';
    v_agency_code := null;
  end if;

  v_supplier_account := nullif(btrim(p_data->>'supplierAccount'), '');
  v_supplier_reference := nullif(btrim(p_data->>'supplierReference'), '');
  v_currency := upper(coalesce(nullif(btrim(p_data->>'currency'), ''), 'BDT'));
  v_status := nullif(btrim(p_data->>'storedStatus'), '');
  v_traveller_count := case
    when jsonb_typeof(p_data #> '{passengers,travellers}') = 'array'
      then jsonb_array_length(p_data #> '{passengers,travellers}')
    else 0
  end;
  if v_supplier_account not in ('firsttrip', 'takeoff')
     or v_supplier_reference is null
     or (v_supplier_account = 'firsttrip'
       and v_supplier_reference !~ '^FST[0-9]{18}$')
     or (v_supplier_account = 'takeoff'
       and v_supplier_reference !~ '^TOT[0-9]{18}$')
     or p_data #>> '{supplierRefs,uniqueTransId}'
        is distinct from v_supplier_reference
     or p_data->>'lifecycleStatus' is distinct from v_status
     or v_status not in ('on-hold', 'confirmed', 'cancelled')
     or v_currency <> 'BDT'
     or p_data->>'pricingMode' is distinct from 'import_time_current_markup'
     or nullif(p_data->>'pricingCalculatedAt', '') is null
     or nullif(p_data->>'supplierEvidenceTimestamp', '') is null
     or p_data->>'supplierEvidenceTimestamp' is distinct from p_data->>'retrievedAt'
     or jsonb_typeof(p_data->'pricingRoutes') <> 'array'
     or coalesce(p_data->>'pricingCarrierCode', '') !~ '^[A-Z0-9]{2}$'
     or jsonb_typeof(p_data->'pricingSnapshot') <> 'object'
     or jsonb_typeof(p_data #> '{pricingSnapshot,components}') <> 'array'
     or p_data #>> '{pricingSnapshot,audience}' is distinct from v_audience
     or p_data #>> '{pricingSnapshot,agencyCode}' is distinct from v_agency_code
     or public.supplier_reference_money_minor_v1(
          p_data #> '{pricingSnapshot,sellingPrice}'
        ) is distinct from p_user_payable_amount
     or public.supplier_reference_money_minor_v1(p_data->'supplierGross')
        is distinct from p_supplier_gross_amount
     or public.supplier_reference_money_minor_v1(
          p_data #> '{pricingSnapshot,grossPrice}'
        ) is distinct from p_supplier_gross_amount
     or public.supplier_reference_money_minor_v1(p_data->'supplierPayable')
        is distinct from public.supplier_reference_money_minor_v1(
          p_data #> '{pricingSnapshot,supplierTotalPrice}'
        ) then
    return jsonb_build_object(
      'ok', false, 'code', 'INVALID_SUPPLIER_REFERENCE_IDENTITY'
    );
  end if;
  if v_status <> 'confirmed'
     and (p_import_decision <> 'import_only'
       or p_charge_authorization_id is not null) then
    return jsonb_build_object(
      'ok', false, 'code', 'CHARGE_DECISION_NOT_APPLICABLE'
    );
  end if;
  if p_import_decision = 'import_and_charge'
     and (v_status <> 'confirmed' or p_charge_authorization_id is null) then
    return jsonb_build_object(
      'ok', false, 'code', 'FRESH_MATCHING_CHARGE_AUTHORIZATION_REQUIRED'
    );
  end if;
  if p_import_decision = 'import_only'
     and p_charge_authorization_id is not null then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end if;

  if v_traveller_count <= 0
     or jsonb_typeof(p_data->'passengerCounts') <> 'object'
     or jsonb_typeof(p_data->'itinerary') <> 'object'
     or jsonb_typeof(p_data->'fares') <> 'array'
     or jsonb_typeof(p_data->'supplierFares') <> 'array'
     or jsonb_typeof(p_data->'airlinesPnr') <> 'array'
     or jsonb_array_length(case
          when jsonb_typeof(p_data->'airlinesPnr') = 'array'
            then p_data->'airlinesPnr' else '[]'::jsonb end) = 0
     or coalesce(p_data->>'travelDate', '')
        !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or nullif(btrim(p_data->>'pnr'), '') is null
     or nullif(btrim(p_data->>'bookingRefNumber'), '') is null
     or nullif(btrim(p_data->>'bookingCodeRef'), '') is null
     or nullif(btrim(p_data #>> '{supplierRefs,itemCodeRef}'), '') is null
     or nullif(btrim(p_data #>> '{supplierRefs,priceCodeRef}'), '') is null then
    return jsonb_build_object(
      'ok', false, 'code', 'OPERATIONAL_REFERENCES_INCOMPLETE'
    );
  end if;
  if exists (
    select 1
      from jsonb_array_elements(p_data->'airlinesPnr') airline(value)
     where jsonb_typeof(airline.value) <> 'string'
        or nullif(btrim(airline.value #>> '{}'), '') is null
  ) then
    return jsonb_build_object(
      'ok', false, 'code', 'OPERATIONAL_REFERENCES_INCOMPLETE'
    );
  end if;
  if v_status = 'confirmed' and (
    jsonb_typeof(p_data->'ticketNumbers') <> 'array'
    or jsonb_array_length(case
         when jsonb_typeof(p_data->'ticketNumbers') = 'array'
           then p_data->'ticketNumbers' else '[]'::jsonb end)
       <> v_traveller_count
    or exists (
      select 1
        from jsonb_array_elements(case
          when jsonb_typeof(p_data->'ticketNumbers') = 'array'
            then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value)
       where jsonb_typeof(ticket.value) <> 'string'
          or nullif(btrim(ticket.value #>> '{}'), '') is null
    )
    or (select count(distinct ticket.value #>> '{}')
          from jsonb_array_elements(case
            when jsonb_typeof(p_data->'ticketNumbers') = 'array'
              then p_data->'ticketNumbers' else '[]'::jsonb end) ticket(value))
       <> v_traveller_count
  ) then
    return jsonb_build_object(
      'ok', false, 'code', 'COMPLETE_TICKET_EVIDENCE_REQUIRED'
    );
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'SUPPLIER_REFERENCE:' || v_supplier_account || ':' || v_supplier_reference,
    0
  ));
  select * into v_existing
    from public.flight_bookings booking
   where booking.supplier_account = v_supplier_account
     and booking.supplier_refs->>'uniqueTransId' = v_supplier_reference
   limit 1
   for update;
  if found then
    if v_existing.booking_origin = 'supplier_reference_import'
       and v_existing.import_metadata->>'importRequestKey' = p_request_key
       and v_existing.user_id is not distinct from p_assigned_user_id
       and v_existing.booking_owner_type is not distinct from v_owner_type
       and v_existing.booking_owner_key is not distinct from v_owner_key
       and v_existing.user_payable_amount = p_user_payable_amount
       and v_existing.import_metadata->>'importDecision'
         = p_import_decision then
      return jsonb_build_object(
        'ok', true,
        'replay', true,
        'booking', to_jsonb(v_existing),
        'walletCharged', v_existing.payment_state = 'captured',
        'amount', case when v_existing.payment_state = 'captured'
          then v_existing.captured_amount else 0 end,
        'currency', v_existing.currency,
        'accountId', v_existing.charged_wallet_account_id,
        'importDecision', p_import_decision
      );
    end if;
    if v_existing.user_id is distinct from p_assigned_user_id
       or v_existing.booking_owner_type is distinct from v_owner_type
       or v_existing.booking_owner_key is distinct from v_owner_key then
      return jsonb_build_object(
        'ok', false, 'code', 'IMPORT_ASSIGNEE_MISMATCH'
      );
    end if;
    if v_existing.user_payable_amount is distinct from p_user_payable_amount then
      return jsonb_build_object(
        'ok', false, 'code', 'IMPORT_PAYABLE_MISMATCH'
      );
    end if;
    return jsonb_build_object(
      'ok', false, 'code', 'SUPPLIER_REFERENCE_ALREADY_EXISTS'
    );
  end if;

  v_payload_hash := public.supplier_reference_import_payload_hash_v1(
    p_assigned_user_id,
    p_user_payable_amount,
    p_supplier_gross_amount,
    p_data
  );
  if p_import_decision = 'import_and_charge' then
    select * into v_authorization
      from public.supplier_reference_charge_authorizations charge_auth
     where charge_auth.id = p_charge_authorization_id
     for update;
    if not found
       or v_authorization.actor_user_id <> p_actor_user_id
       or v_authorization.assigned_user_id <> p_assigned_user_id
       or v_authorization.owner_type <> v_owner_type
       or v_authorization.owner_key <> v_owner_key
       or v_authorization.supplier_account <> v_supplier_account
       or v_authorization.supplier_reference <> v_supplier_reference
       or v_authorization.currency <> v_currency
       or v_authorization.user_payable_amount <> p_user_payable_amount
       or v_authorization.supplier_gross_amount <> p_supplier_gross_amount
       or v_authorization.authorization_payload_hash <> v_payload_hash
       or v_authorization.expires_at < clock_timestamp()
       or v_authorization.consumed_at is not null then
      return jsonb_build_object(
        'ok', false,
        'code', 'FRESH_MATCHING_CHARGE_AUTHORIZATION_REQUIRED'
      );
    end if;

    select * into v_wallet
      from public.wallets wallet
     where wallet.owner_type = v_owner_type
       and wallet.owner_key = v_owner_key
     for update;
    if not found then
      return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
    end if;
    select * into v_account
      from public.wallet_accounts account
     where account.wallet_id = v_wallet.id
       and account.currency = v_currency
     for update;
    if not found then
      return jsonb_build_object(
        'ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND'
      );
    end if;
    if v_wallet.status <> 'active' then
      return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
    end if;
    if v_account.available_balance < p_user_payable_amount then
      return jsonb_build_object(
        'ok', false,
        'code', 'INSUFFICIENT_FUNDS',
        'available', v_account.available_balance,
        'required', p_user_payable_amount,
        'currency', v_currency
      );
    end if;
    v_available_before := v_account.available_balance;
    v_hold_before := v_account.hold_balance;
    v_wallet_charged := true;
  end if;

  begin
    v_created_at := coalesce(
      nullif(p_data->>'bookedAt', '')::timestamptz,
      clock_timestamp()
    );
    v_issued_at := nullif(p_data->>'issuedAt', '')::timestamptz;
    v_cancelled_at := nullif(p_data->>'cancelledAt', '')::timestamptz;
    v_deadline_at := nullif(p_data->>'ticketingDeadlineAt', '')::timestamptz;
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORT_DATA');
  end;

  v_public_ref := public.allocate_booking_ref();
  v_pricing := p_data->'pricingSnapshot';

  insert into public.booking_attempts (
    id, access_token_hash, user_id, audience, agency_code,
    supplier, state, search_id, itinerary_id,
    unique_trans_id, item_code_ref, price_code_ref,
    booking_code_ref, pnr, offer_snapshot, passenger_snapshot,
    expires_at, submitted_at, resolved_at, created_at,
    supplier_account, created_by_user_id, staff_on_behalf
  ) values (
    v_attempt_id,
    encode(sha256(convert_to(
      'supplier-reference:' || v_supplier_account || ':' || v_supplier_reference,
      'UTF8'
    )), 'hex'),
    p_assigned_user_id, v_audience, v_agency_code,
    'triplover', 'succeeded', v_search_id,
    'supplier-reference:' || v_supplier_account || ':' || v_supplier_reference,
    v_supplier_reference,
    p_data #>> '{supplierRefs,itemCodeRef}',
    p_data #>> '{supplierRefs,priceCodeRef}',
    p_data->>'bookingCodeRef', p_data->>'pnr',
    jsonb_build_object(
      'itinerary', p_data->'itinerary',
      'fares', p_data->'fares',
      'supplierFareEvidence', p_data->'supplierFares',
      'currency', v_currency,
      'pricing', v_pricing,
      'passengerCounts', p_data->'passengerCounts',
      'travelDate', p_data->>'travelDate',
      'directTicketing', coalesce((p_data->>'directTicketing')::boolean, false),
      'passportRequired', coalesce((p_data->>'passportRequired')::boolean, true),
      'repricedAt', p_data->>'pricingCalculatedAt',
      'pricingMode', p_data->>'pricingMode',
      'supplierPayable', p_data->'supplierPayable',
      'supplierGross', p_data->'supplierGross',
      'supplierDiscount', p_data->'supplierDiscount',
      'supplierEvidenceTimestamp', p_data->>'supplierEvidenceTimestamp',
      'bookingOrigin', 'supplier_reference_import'
    ),
    p_data->'passengers',
    coalesce(v_deadline_at, v_created_at),
    v_created_at, clock_timestamp(), v_created_at,
    v_supplier_account, p_actor_user_id, false
  );

  if v_wallet_charged then
    update public.wallet_accounts
       set available_balance = available_balance - p_user_payable_amount
     where id = v_account.id;
  end if;

  perform set_config('app.skip_initial_booking_status_event', 'true', true);
  insert into public.flight_bookings (
    id, public_ref, attempt_id, supplier, user_id, audience, agency_code,
    search_id, itinerary_id, status, currency, pricing_snapshot,
    passenger_counts, travel_date, direct_ticketing, itinerary, fares,
    passport_required, supplier_refs, repriced_at, accepted_at, passengers,
    pnr, airlines_pnr, booking_ref_number, booking_status,
    ticketing_time_limit, ticketing_deadline_at, deadline_source,
    supplier_ticketing_time_limit, supplier_ticketing_deadline_at,
    supplier_deadline_source, booking_code_ref, ticket_code_ref,
    ticket_numbers, warnings, supplier_message, issued_at, cancelled_at,
    submission_started_at, legacy_operational, booked_by_user_id,
    issued_by_user_id, booking_owner_type, booking_owner_key,
    charged_wallet_account_id, payment_state, payment_amount,
    captured_amount, refunded_amount, supplier_gross_amount,
    user_payable_amount, import_source, imported_by_user_id,
    import_metadata, booking_origin, synced_at, created_at
  ) values (
    v_booking_id, v_public_ref, v_attempt_id, 'triplover',
    p_assigned_user_id, v_audience, v_agency_code,
    v_search_id,
    'supplier-reference:' || v_supplier_account || ':' || v_supplier_reference,
    v_status, v_currency, v_pricing,
    p_data->'passengerCounts', (p_data->>'travelDate')::date,
    coalesce((p_data->>'directTicketing')::boolean, false),
    p_data->'itinerary', p_data->'fares',
    coalesce((p_data->>'passportRequired')::boolean, true),
    p_data->'supplierRefs',
    coalesce(nullif(p_data->>'pricingCalculatedAt', '')::timestamptz, clock_timestamp()),
    v_created_at, p_data->'passengers',
    p_data->>'pnr', p_data->'airlinesPnr', p_data->>'bookingRefNumber',
    p_data->>'supplierStatus', nullif(p_data->>'ticketingTimeLimit', ''),
    v_deadline_at, case when v_deadline_at is not null then 'pnr_call' end,
    nullif(p_data->>'ticketingTimeLimit', ''), v_deadline_at,
    case when v_deadline_at is not null then 'pnr_call' end,
    p_data->>'bookingCodeRef', nullif(p_data->>'ticketCodeRef', ''),
    coalesce(p_data->'ticketNumbers', '[]'::jsonb), '[]'::jsonb,
    nullif(p_data->>'supplierMessage', ''), v_issued_at, v_cancelled_at,
    v_created_at, false, p_actor_user_id, null,
    v_owner_type, v_owner_key,
    case when v_wallet_charged then v_account.id else null end,
    case when v_wallet_charged then 'captured' else 'unpaid' end,
    case when v_wallet_charged then p_user_payable_amount else null end,
    case when v_wallet_charged then p_user_payable_amount else 0 end,
    0, p_supplier_gross_amount, p_user_payable_amount,
    null, p_actor_user_id,
    jsonb_build_object(
      'source', 'supplier_reference_import',
      'supplierAccount', v_supplier_account,
      'supplierReference', v_supplier_reference,
      'supplierBookingId', p_data->'supplierBookingId',
      'importRequestKey', p_request_key,
      'importDecision', p_import_decision,
      'walletCharged', v_wallet_charged,
      'retrievedAt', p_data->>'retrievedAt',
      'pricingMode', p_data->>'pricingMode',
      'pricingCalculatedAt', p_data->>'pricingCalculatedAt',
      'supplierEvidenceTimestamp', p_data->>'supplierEvidenceTimestamp',
      'supplierPayable', p_data->'supplierPayable',
      'supplierGross', p_data->'supplierGross',
      'supplierDiscount', p_data->'supplierDiscount',
      'pricingCarrierCode', p_data->>'pricingCarrierCode',
      'pricingRoutes', p_data->'pricingRoutes',
      'canonicalPricingSnapshot', p_data->'pricingSnapshot',
      'supplierFareEvidence', p_data->'supplierFares'
    ),
    'supplier_reference_import',
    coalesce(nullif(p_data->>'retrievedAt', '')::timestamptz, clock_timestamp()),
    v_created_at
  ) returning * into v_booking;

  if v_wallet_charged then
    insert into public.wallet_reservations (
      wallet_account_id, booking_id, amount, currency, state,
      requested_by_user_id, issued_by_user_id, captured_at
    ) values (
      v_account.id, v_booking.id, p_user_payable_amount, v_currency,
      'captured', p_actor_user_id, p_actor_user_id, clock_timestamp()
    ) returning * into v_reservation;

    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, booking_reference, reservation_id, idempotency_key,
      created_by_user_id, created_by_role, remarks, metadata
    ) values (
      v_account.id, 'booking_confirm', p_user_payable_amount, v_currency,
      v_available_before, v_available_before - p_user_payable_amount,
      v_hold_before, v_hold_before,
      v_booking.id, v_booking.public_ref, v_reservation.id,
      'supplier-reference-payment:' || v_booking.id::text,
      p_actor_user_id, v_actor_role,
      'Explicitly authorized supplier-reference Import & Charge',
      jsonb_build_object(
        'bookingOrigin', 'supplier_reference_import',
        'supplierAccount', v_supplier_account,
        'supplierReference', v_supplier_reference,
        'supplierGrossAmount', p_supplier_gross_amount,
        'supplierPayableAmount', public.supplier_reference_money_minor_v1(
          p_data->'supplierPayable'
        ),
        'userPayableAmount', p_user_payable_amount,
        'pricingMode', p_data->>'pricingMode',
        'importDecision', p_import_decision,
        'chargeAuthorizationId', v_authorization.id
      )
    );

    update public.supplier_reference_charge_authorizations
       set consumed_at = clock_timestamp(),
           consumed_booking_id = v_booking.id
     where id = v_authorization.id;
  end if;

  v_effective_at := case v_status
    when 'confirmed' then v_issued_at
    when 'cancelled' then v_cancelled_at
    else v_created_at
  end;
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after,
    actor_user_id, supplier_operation, supplier_evidence,
    idempotency_key, occurrence_number, effective_at, observed_at,
    event_snapshot, event_version
  ) values (
    v_booking.id, null,
    public.resolve_booking_lifecycle(
      v_booking.status, v_booking.airlines_pnr,
      v_booking.ticketing_deadline_at, v_booking.operation_kind
    ),
    null, v_booking.status,
    p_actor_user_id, 'SupplierReferenceImport',
    jsonb_build_object(
      'bookingOrigin', 'supplier_reference_import',
      'supplierAccount', v_supplier_account,
      'supplierReference', v_supplier_reference,
      'supplierStatus', p_data->>'supplierStatus',
      'walletCharged', v_wallet_charged,
      'importDecision', p_import_decision
      ,'pricingMode', p_data->>'pricingMode'
      ,'pricingCalculatedAt', p_data->>'pricingCalculatedAt'
      ,'supplierEvidenceTimestamp', p_data->>'supplierEvidenceTimestamp'
      ,'supplierPayable', p_data->'supplierPayable'
      ,'supplierGross', p_data->'supplierGross'
      ,'supplierDiscount', p_data->'supplierDiscount'
      ,'canonicalPricingSnapshot', p_data->'pricingSnapshot'
    ),
    p_request_key || ':created', 1, v_effective_at, clock_timestamp(),
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'lifecycleStatus', public.resolve_booking_lifecycle(
        v_booking.status, v_booking.airlines_pnr,
        v_booking.ticketing_deadline_at, v_booking.operation_kind
      ),
      'paymentState', v_booking.payment_state,
      'operationSource', 'supplier_reference_import',
      'bookingOrigin', 'supplier_reference_import',
      'supplierAccount', v_supplier_account,
      'importDecision', p_import_decision,
      'userPayableAmount', p_user_payable_amount,
      'currency', v_currency
    ), 1
  );

  return jsonb_build_object(
    'ok', true,
    'replay', false,
    'booking', to_jsonb(v_booking),
    'walletCharged', v_wallet_charged,
    'amount', case when v_wallet_charged then p_user_payable_amount else 0 end,
    'currency', v_currency,
    'accountId', case when v_wallet_charged then v_account.id else null end,
    'importDecision', p_import_decision
  );
end;
$$;

revoke all on function public.supplier_reference_import_payload_hash_v1(
  text, bigint, bigint, jsonb
) from public, anon, authenticated;
revoke all on function public.supplier_reference_money_minor_v1(jsonb)
  from public, anon, authenticated;
revoke all on function public.authorize_supplier_reference_charge_v1(
  text, text, bigint, bigint, jsonb, text
) from public, anon, authenticated;
revoke all on function public.create_supplier_reference_booking_v1(
  text, text, bigint, bigint, jsonb, text, uuid, text
) from public, anon, authenticated;

grant execute on function public.authorize_supplier_reference_charge_v1(
  text, text, bigint, bigint, jsonb, text
) to service_role;
grant execute on function public.create_supplier_reference_booking_v1(
  text, text, bigint, bigint, jsonb, text, uuid, text
) to service_role;

comment on function public.authorize_supplier_reference_charge_v1(
  text, text, bigint, bigint, jsonb, text
) is
  'Records a five-minute, one-use, exact-payload authorization after checking the assigned owner wallet. It never mutates wallet money or creates a booking.';
comment on function public.create_supplier_reference_booking_v1(
  text, text, bigint, bigint, jsonb, text, uuid, text
) is
  'Atomically creates an ordinary Triplover API-backed booking from real FirstTrip/TakeOff references. Held and terminal historical imports make no wallet movement; explicit confirmed Import & Charge consumes one fresh authorization and writes the captured reservation and immutable ledger in the same transaction.';


-- SOURCE: 0110_staff_imported_issue_now.sql
-- Super Admin, Admin, and Support Staff may start imported/manual ticketing on
-- behalf of the assigned owner. The actor is retained for audit, while every
-- wallet lookup and Hold remains pinned to the booking's durable owner.
-- Accounts Staff and all other roles stay forbidden. No supplier API is called.

create or replace function public.wallet_begin_imported_booking_issue_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_actor_role text;
  v_actor_agency text;
  v_existing_ledger public.wallet_ledger_entries;
  v_existing_operation public.booking_operations;
  v_existing_case public.booking_reconciliation_cases;
  v_existing_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_available_before bigint;
  v_hold_before bigint;
  v_due_at timestamptz;
  v_occurrence integer;
  v_event_id bigint;
  v_on_behalf boolean;
  v_now timestamptz := clock_timestamp();
begin
  if p_booking_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_request_key !~ '^imported-issue:v2:[0-9a-f-]{36}$' then
    return jsonb_build_object('ok', false, 'code', 'INVALID_IMPORTED_ISSUE_REQUEST');
  end if;

  select role, agency_code into v_actor_role, v_actor_agency
    from public.app_users
   where clerk_id = p_actor_user_id;
  if not found
     or v_actor_role not in (
       'customer', 'b2b', 'b2b_sub',
       'superadmin', 'admin', 'staff_support'
     ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ISSUE_FORBIDDEN');
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
     and booking.import_source in ('IMP_EXP', 'MANUAL')
     and not booking.legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_BOOKING_NOT_FOUND');
  end if;

  v_on_behalf := v_actor_role in ('superadmin', 'admin', 'staff_support');
  if not (
    (v_on_behalf
      and v_booking.booking_owner_type in ('user', 'agency')
      and nullif(btrim(v_booking.booking_owner_key), '') is not null)
    or
    (v_actor_role = 'customer'
      and v_booking.booking_owner_type = 'user'
      and v_booking.booking_owner_key = p_actor_user_id)
    or
    (v_actor_role in ('b2b', 'b2b_sub')
      and nullif(btrim(v_actor_agency), '') is not null
      and v_booking.booking_owner_type = 'agency'
      and v_booking.booking_owner_key = v_actor_agency)
  ) then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ISSUE_FORBIDDEN');
  end if;

  select ledger.* into v_existing_ledger
    from public.wallet_ledger_entries ledger
   where ledger.idempotency_key = p_request_key || ':hold';
  if found and v_existing_ledger.booking_id is distinct from v_booking.id then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ISSUE_IDEMPOTENCY_CONFLICT');
  end if;

  select operation.* into v_existing_operation
    from public.booking_operations operation
   where operation.booking_id = v_booking.id
     and operation.state in (
       'claimed', 'supplier_call_started', 'awaiting_external_action',
       'needs_reconciliation'
     )
   order by operation.claimed_at desc, operation.id desc
   limit 1
   for update;
  select reconciliation_case.* into v_existing_case
    from public.booking_reconciliation_cases reconciliation_case
   where reconciliation_case.subject_booking_id = v_booking.id
     and reconciliation_case.state in (
       'open', 'assigned', 'awaiting_supplier', 'awaiting_finance',
       'awaiting_approval'
     )
   order by reconciliation_case.opened_at desc, reconciliation_case.id desc
   limit 1
   for update;
  select reservation.* into v_existing_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
   for update;

  if v_existing_reservation.id is not null
     and v_existing_reservation.state in ('active', 'reconciliation')
     and v_booking.status = 'in-progress'
     and v_booking.payment_state in ('held', 'reconciliation')
     and v_existing_reservation.amount = v_booking.user_payable_amount
     and v_existing_operation.id = v_booking.active_operation_id
     and v_existing_operation.kind = 'imported_manual_ticketing'
     and v_existing_case.operation_id = v_existing_operation.id
     and exists (
       select 1 from public.wallet_ledger_entries ledger
        where ledger.reservation_id = v_existing_reservation.id
          and ledger.transaction_type = 'booking_hold'
          and ledger.amount = v_existing_reservation.amount
     ) then
    select account.* into v_account
      from public.wallet_accounts account
     where account.id = v_existing_reservation.wallet_account_id;
    return jsonb_build_object(
      'ok', true, 'replay', true, 'status', 'in-progress',
      'paymentState', v_booking.payment_state,
      'operationId', v_existing_operation.id,
      'reconciliationCaseId', v_existing_case.id,
      'reservationId', v_existing_reservation.id,
      'accountId', v_existing_reservation.wallet_account_id,
      'amount', v_existing_reservation.amount,
      'currency', v_existing_reservation.currency,
      'availableBalance', v_account.available_balance,
      'holdBalance', v_account.hold_balance
    );
  end if;

  if v_booking.status = 'confirmed'
     or v_booking.payment_state in ('captured', 'partially-refunded', 'refunded')
     or (v_existing_reservation.id is not null
       and v_existing_reservation.state = 'captured') then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CAPTURED');
  end if;
  if v_existing_operation.id is not null
     or v_existing_case.id is not null
     or v_existing_reservation.id is not null
     or v_existing_ledger.id is not null then
    return jsonb_build_object('ok', false, 'code', 'IMPORTED_ACCOUNTING_RECONCILIATION_REQUIRED');
  end if;
  if v_booking.status <> 'on-hold'
     or v_booking.operation_kind is not null
     or v_booking.payment_state <> 'unpaid'
     or v_booking.charged_wallet_account_id is not null
     or v_booking.captured_amount <> 0
     or v_booking.refunded_amount <> 0
     or public.resolve_booking_lifecycle(
       v_booking.status, v_booking.airlines_pnr,
       v_booking.ticketing_deadline_at, v_booking.operation_kind
     ) <> 'on-hold' then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_ISSUABLE');
  end if;
  if v_booking.user_payable_amount is null
     or v_booking.user_payable_amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_BOOKING_AMOUNT');
  end if;

  -- Never resolve a wallet from the actor. Both owner and authorized staff
  -- paths use only the durable owner already assigned to this booking.
  select wallet.* into v_wallet
    from public.wallets wallet
   where wallet.owner_type = v_booking.booking_owner_type
     and wallet.owner_key = v_booking.booking_owner_key
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_NOT_FOUND');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.wallet_id = v_wallet.id
     and account.currency = upper(v_booking.currency)
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'WALLET_ACCOUNT_NOT_FOUND');
  end if;
  if v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_account.available_balance < v_booking.user_payable_amount then
    return jsonb_build_object(
      'ok', false, 'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance,
      'required', v_booking.user_payable_amount,
      'currency', v_account.currency
    );
  end if;

  v_due_at := case
    when v_booking.ticketing_deadline_at is null then v_now + interval '2 hours'
    else greatest(
      v_now,
      least(v_now + interval '2 hours',
        v_booking.ticketing_deadline_at - interval '1 hour')
    )
  end;

  insert into public.booking_operations (
    booking_id, kind, state, reason_code, reason_detail,
    request_key, request_payload_hash, actor_user_id, actor_role, source,
    prior_stored_status, prior_lifecycle_status, supplier,
    supplier_operation, supplier_unique_trans_id,
    supplier_booking_code_ref, supplier_pnr, supplier_evidence,
    policy_version, claimed_at, external_action_due_at
  ) values (
    v_booking.id, 'imported_manual_ticketing', 'awaiting_external_action',
    'imported_manual_ticketing',
    case when v_on_behalf
      then 'Authorized staff placed assigned owner User Payable on Hold; external ticketing outcome is required.'
      else 'Owner placed User Payable on Hold; external ticketing outcome is required.'
    end,
    'imported-ticketing:v2:' || v_booking.id::text,
    encode(sha256(convert_to(jsonb_build_object(
      'version', 2, 'bookingId', v_booking.id,
      'ownerType', v_booking.booking_owner_type,
      'ownerKey', v_booking.booking_owner_key,
      'amount', v_booking.user_payable_amount,
      'currency', upper(v_booking.currency)
    )::text, 'UTF8')), 'hex'),
    p_actor_user_id, v_actor_role,
    case when v_on_behalf then 'staff' else 'customer' end,
    'on-hold', 'on-hold', v_booking.supplier,
    'ManualExternalTicketing',
    v_booking.supplier_refs->>'uniqueTransId', v_booking.booking_code_ref,
    v_booking.pnr,
    jsonb_build_object(
      'paymentHeld', true, 'paymentCaptured', false,
      'supplierApiCalled', false, 'clientRequestKey', p_request_key,
      'importSource', v_booking.import_source,
      'userPayableAmount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'externalActionDueAt', v_due_at,
      'initiatedOnBehalf', v_on_behalf,
      'walletOwnerType', v_booking.booking_owner_type,
      'accountingContractVersion', 2
    ),
    2, v_now, v_due_at
  ) returning * into v_operation;

  insert into public.booking_reconciliation_cases (
    subject_booking_id, operation_id, case_type, state,
    reason_code, reason_detail, opened_source, opened_by_user_id,
    opened_by_role, opened_at, assigned_team, assigned_at,
    severity, priority, due_at, escalation_level, evidence,
    financial_disposition, policy_version
  ) values (
    v_booking.id, v_operation.id, 'imported_manual_ticketing', 'assigned',
    'manual_ticketing_required',
    'User Payable is protected in Hold; verify ticketing and Capture or Release.',
    'operation', p_actor_user_id, v_actor_role, v_now,
    'support', v_now, 'high', 30, v_due_at, 0,
    jsonb_build_array(jsonb_build_object(
      'type', 'owner_payment_hold', 'operationId', v_operation.id,
      'amount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'supplierApiCalled', false,
      'initiatedOnBehalf', v_on_behalf,
      'walletOwnerType', v_booking.booking_owner_type,
      'accountingContractVersion', 2, 'recordedAt', v_now
    )),
    'none', 2
  ) returning * into v_case;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts set
    available_balance = available_balance - v_booking.user_payable_amount,
    hold_balance = hold_balance + v_booking.user_payable_amount
  where id = v_account.id;

  insert into public.wallet_reservations (
    wallet_account_id, booking_id, amount, currency, state,
    requested_by_user_id
  ) values (
    v_account.id, v_booking.id, v_booking.user_payable_amount,
    v_account.currency, 'active', p_actor_user_id
  ) returning * into v_reservation;

  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks, metadata
  ) values (
    v_account.id, 'booking_hold', v_booking.user_payable_amount,
    v_account.currency, v_available_before,
    v_available_before - v_booking.user_payable_amount,
    v_hold_before, v_hold_before + v_booking.user_payable_amount,
    v_booking.id, v_booking.public_ref, v_reservation.id,
    p_request_key || ':hold', p_actor_user_id, v_actor_role,
    'Imported booking Issue Now Hold',
    jsonb_build_object(
      'importSource', v_booking.import_source,
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'supplierGrossAmount', v_booking.supplier_gross_amount,
      'userPayableAmount', v_booking.user_payable_amount,
      'supplierApiCalled', false,
      'initiatedOnBehalf', v_on_behalf,
      'walletOwnerType', v_booking.booking_owner_type,
      'accountingContractVersion', 2
    )
  );

  update public.flight_bookings set
    charged_wallet_account_id = v_account.id,
    payment_state = 'held', payment_amount = user_payable_amount,
    captured_amount = 0, status = 'in-progress',
    active_operation_id = v_operation.id,
    operation_kind = 'ticketing',
    operation_reason = 'imported_manual_ticketing',
    operation_request_id = p_request_key,
    operation_actor_user_id = p_actor_user_id,
    operation_started_at = v_now,
    operation_prior_status = 'on-hold'
  where id = v_booking.id;

  select count(*)::integer + 1 into v_occurrence
    from public.booking_status_events event
   where event.booking_id = v_booking.id
     and event.to_lifecycle_status = 'in-progress';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number, effective_at,
    observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, 'on-hold', 'in-progress', 'on-hold', 'in-progress',
    'ticketing', 'imported_manual_ticketing', p_actor_user_id,
    case when v_on_behalf
      then 'ImportStaffIssueNow'
      else 'ImportCustomerIssueNow'
    end,
    jsonb_build_object(
      'walletHeld', true, 'walletCaptured', false,
      'supplierApiCalled', false, 'importSource', v_booking.import_source,
      'userPayableAmount', v_booking.user_payable_amount,
      'initiatedOnBehalf', v_on_behalf,
      'walletOwnerType', v_booking.booking_owner_type,
      'accountingContractVersion', 2
    ),
    p_request_key || ':in-progress', v_operation.id, v_case.id,
    v_occurrence, v_now, v_now,
    jsonb_build_object(
      'version', 2, 'bookingReference', v_booking.public_ref,
      'lifecycleStatus', 'in-progress', 'paymentState', 'held',
      'operationKind', 'imported_manual_ticketing',
      'operationSource', 'imported_manual_ticketing',
      'operationId', v_operation.id,
      'reconciliationCaseId', v_case.id,
      'userPayableAmount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'accountingContractVersion', 2
    ), 2
  ) returning id into v_event_id;

  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, metadata
  ) values (
    p_actor_user_id, v_actor_role, 'booking.imported.issue_now',
    'flight_booking', v_booking.id::text, 'succeeded',
    jsonb_build_object(
      'requestKey', p_request_key, 'importSource', v_booking.import_source,
      'walletEffect', 'hold', 'amount', v_booking.user_payable_amount,
      'currency', v_booking.currency, 'reservationId', v_reservation.id,
      'supplierApiCalled', false, 'initiatedOnBehalf', v_on_behalf,
      'walletOwnerType', v_booking.booking_owner_type
    )
  );

  return jsonb_build_object(
    'ok', true, 'replay', false, 'status', 'in-progress',
    'paymentState', 'held', 'operationId', v_operation.id,
    'reconciliationCaseId', v_case.id,
    'reservationId', v_reservation.id, 'accountId', v_account.id,
    'lifecycleEventId', v_event_id,
    'amount', v_booking.user_payable_amount,
    'currency', v_account.currency,
    'availableBalance', v_available_before - v_booking.user_payable_amount,
    'holdBalance', v_hold_before + v_booking.user_payable_amount
  );
end;
$$;

revoke all on function public.wallet_begin_imported_booking_issue_v2(
  uuid, text, text
) from public, anon, authenticated;
grant execute on function public.wallet_begin_imported_booking_issue_v2(
  uuid, text, text
) to service_role;

comment on function public.wallet_begin_imported_booking_issue_v2(
  uuid, text, text
) is
  'Atomically moves imported User Payable from the assigned owner wallet Available balance to Hold. The owner, Super Admin, Admin, or Support Staff may initiate it. It never calls a supplier API.';


-- SOURCE: 0111_announcement_slider_management.sql
-- Managed public announcement slider.
--
-- The public site reads these rows through the server-only service client.
-- Dashboard writes replace the complete ordered set in one transaction, with
-- an optimistic version check so two editors cannot silently overwrite one
-- another.

create table if not exists public.announcement_slider_settings (
  id          text primary key check (id = 'primary'),
  version     integer not null default 1 check (version > 0),
  updated_at  timestamptz not null default now(),
  updated_by  text not null check (char_length(updated_by) between 1 and 255)
);

create table if not exists public.announcement_slider_messages (
  id          uuid primary key,
  message     text not null
              check (char_length(btrim(message)) between 1 and 180),
  is_active   boolean not null default true,
  sort_order  integer not null check (sort_order >= 0),
  created_at  timestamptz not null default now(),
  created_by  text not null check (char_length(created_by) between 1 and 255),
  updated_at  timestamptz not null default now(),
  updated_by  text not null check (char_length(updated_by) between 1 and 255)
);

create index if not exists announcement_slider_messages_order_idx
  on public.announcement_slider_messages (sort_order, created_at, id);

alter table public.announcement_slider_settings enable row level security;
alter table public.announcement_slider_messages enable row level security;
revoke all on table public.announcement_slider_settings
  from public, anon, authenticated;
revoke all on table public.announcement_slider_messages
  from public, anon, authenticated;
grant select, insert, update, delete on table public.announcement_slider_settings
  to service_role;
grant select, insert, update, delete on table public.announcement_slider_messages
  to service_role;

insert into public.announcement_slider_settings (id, version, updated_by)
values ('primary', 1, 'system:migration')
on conflict (id) do nothing;

-- Announcements start empty.

create or replace function public.replace_announcement_slider_messages_v1(
  p_actor_user_id text,
  p_expected_version integer,
  p_messages jsonb
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_current_version integer;
  v_next_version integer;
  v_message_count integer;
begin
  if p_actor_user_id is null
     or char_length(btrim(p_actor_user_id)) not between 1 and 255 then
    raise exception 'invalid announcement actor' using errcode = '22023';
  end if;
  if p_expected_version is null or p_expected_version < 1 then
    raise exception 'invalid announcement version' using errcode = '22023';
  end if;
  if p_messages is null or jsonb_typeof(p_messages) <> 'array' then
    raise exception 'announcement messages must be an array' using errcode = '22023';
  end if;

  v_message_count := jsonb_array_length(p_messages);
  if v_message_count > 12 then
    raise exception 'too many announcement messages' using errcode = '22023';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_messages) item
     where jsonb_typeof(item) <> 'object'
        or not (item ? 'id')
        or coalesce(item->>'id', '') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or not (item ? 'text')
        or char_length(btrim(coalesce(item->>'text', ''))) not between 1 and 180
        or not (item ? 'active')
        or jsonb_typeof(item->'active') <> 'boolean'
  ) then
    raise exception 'invalid announcement message' using errcode = '22023';
  end if;

  if (
    select count(distinct item->>'id')
      from jsonb_array_elements(p_messages) item
  ) <> v_message_count then
    raise exception 'duplicate announcement message id' using errcode = '22023';
  end if;

  select version
    into v_current_version
    from public.announcement_slider_settings
   where id = 'primary'
   for update;

  if not found then
    raise exception 'announcement settings are unavailable' using errcode = '55000';
  end if;
  if v_current_version <> p_expected_version then
    raise exception 'announcement settings changed in another session'
      using errcode = '40001';
  end if;

  delete from public.announcement_slider_messages existing
   where not exists (
     select 1
       from jsonb_array_elements(p_messages) item
      where (item->>'id')::uuid = existing.id
   );

  insert into public.announcement_slider_messages (
    id, message, is_active, sort_order, created_by, updated_by
  )
  select
    (item->>'id')::uuid,
    btrim(item->>'text'),
    (item->>'active')::boolean,
    (ordinality - 1)::integer,
    btrim(p_actor_user_id),
    btrim(p_actor_user_id)
  from jsonb_array_elements(p_messages) with ordinality as incoming(item, ordinality)
  on conflict (id) do update
    set message = excluded.message,
        is_active = excluded.is_active,
        sort_order = excluded.sort_order,
        updated_at = now(),
        updated_by = excluded.updated_by;

  update public.announcement_slider_settings
     set version = version + 1,
         updated_at = now(),
         updated_by = btrim(p_actor_user_id)
   where id = 'primary'
  returning version into v_next_version;

  return v_next_version;
end;
$$;

revoke all on function public.replace_announcement_slider_messages_v1(
  text, integer, jsonb
) from public, anon, authenticated;
grant execute on function public.replace_announcement_slider_messages_v1(
  text, integer, jsonb
) to service_role;

comment on table public.announcement_slider_settings is
  'Singleton version and editor metadata for the public announcement slider.';
comment on table public.announcement_slider_messages is
  'Ordered public announcement-slider messages managed by Super Admin, Admin, and Media Staff.';
comment on function public.replace_announcement_slider_messages_v1(text, integer, jsonb) is
  'Atomically validates and replaces the complete ordered announcement-slider message set.';


-- SOURCE: 0112_announcement_slider_speed.sql
-- Adjustable announcement-slider speed. The value is the duration of one
-- complete ticker loop: lower values move faster and higher values move slower.

alter table public.announcement_slider_settings
  add column if not exists scroll_duration_seconds integer not null default 28;

alter table public.announcement_slider_settings
  drop constraint if exists announcement_slider_settings_scroll_duration_check;
alter table public.announcement_slider_settings
  add constraint announcement_slider_settings_scroll_duration_check
  check (scroll_duration_seconds between 12 and 90);

create or replace function public.replace_announcement_slider_messages_v2(
  p_actor_user_id text,
  p_expected_version integer,
  p_scroll_duration_seconds integer,
  p_messages jsonb
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_next_version integer;
begin
  if p_scroll_duration_seconds is null
     or p_scroll_duration_seconds not between 12 and 90 then
    raise exception 'invalid announcement slider speed' using errcode = '22023';
  end if;

  -- v1 owns all message validation, row replacement, locking, and optimistic
  -- versioning. Calling it here keeps the speed and message update in this same
  -- transaction while preserving the already-deployed v1 migration contract.
  v_next_version := public.replace_announcement_slider_messages_v1(
    p_actor_user_id,
    p_expected_version,
    p_messages
  );

  update public.announcement_slider_settings
     set scroll_duration_seconds = p_scroll_duration_seconds
   where id = 'primary';

  return v_next_version;
end;
$$;

revoke all on function public.replace_announcement_slider_messages_v2(
  text, integer, integer, jsonb
) from public, anon, authenticated;
grant execute on function public.replace_announcement_slider_messages_v2(
  text, integer, integer, jsonb
) to service_role;

comment on column public.announcement_slider_settings.scroll_duration_seconds is
  'Seconds for one complete ticker animation loop; lower is faster.';
comment on function public.replace_announcement_slider_messages_v2(
  text, integer, integer, jsonb
) is
  'Atomically replaces the announcement messages and their public ticker speed.';


-- SOURCE: 0113_flight_search_history.sql
-- Private per-user flight-search history with an anonymized popular-search
-- fallback for the dashboard. Only the service-role server can read or write
-- the underlying rows; browsers never query this table directly.

create table if not exists public.flight_search_history (
  id uuid primary key default gen_random_uuid(),
  user_id text not null references public.app_users (clerk_id) on delete cascade,

  -- Exact validated request fingerprint. Repeating the same search moves its
  -- existing row to the front instead of filling the list with duplicates.
  search_key text not null check (search_key ~ '^[0-9a-f]{64}$'),
  -- Route/trip/cabin fingerprint used only for anonymous aggregation. Dates
  -- and passenger details are deliberately absent from this grouping key.
  popularity_key text not null check (popularity_key ~ '^[0-9a-f]{64}$'),

  trip_type text not null check (trip_type in ('oneway', 'round', 'multicity')),
  routes jsonb not null
    check (jsonb_typeof(routes) = 'array' and jsonb_array_length(routes) between 1 and 6),
  first_departure_date date not null,
  adults smallint not null check (adults between 1 and 9),
  children smallint not null check (children between 0 and 8),
  infants smallint not null check (infants between 0 and 9),
  children_ages jsonb not null default '[]'::jsonb
    check (jsonb_typeof(children_ages) = 'array'),
  cabin_class smallint not null check (cabin_class between 1 and 5),
  preferred_carriers jsonb not null default '[]'::jsonb
    check (jsonb_typeof(preferred_carriers) = 'array'),
  searched_at timestamptz not null default now(),

  constraint flight_search_history_user_search_key unique (user_id, search_key)
);

create index if not exists flight_search_history_user_recent_idx
  on public.flight_search_history (user_id, searched_at desc);
create index if not exists flight_search_history_popular_idx
  on public.flight_search_history
  (first_departure_date, popularity_key, searched_at desc);
create index if not exists flight_search_history_searched_at_idx
  on public.flight_search_history (searched_at);

alter table public.flight_search_history enable row level security;
revoke all on table public.flight_search_history from anon, authenticated;
grant select, insert, update, delete on table public.flight_search_history
  to service_role;

-- Returns one recent representative for each popular route/trip/cabin group.
-- A group must have searches from multiple distinct users before it can leave
-- the database, preventing an individual's search from becoming a "popular"
-- recommendation by itself. No user id is part of the result contract.
create or replace function public.popular_flight_searches_v1(
  p_since timestamptz,
  p_today date,
  p_limit integer default 5,
  p_min_distinct_users integer default 2
)
returns table (
  id uuid,
  trip_type text,
  routes jsonb,
  first_departure_date date,
  adults smallint,
  children smallint,
  infants smallint,
  cabin_class smallint,
  searched_at timestamptz,
  search_count bigint,
  distinct_user_count bigint
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with eligible as (
    select h.*
    from public.flight_search_history h
    where h.searched_at >= p_since
      and h.first_departure_date >= p_today
  ),
  grouped as (
    select
      e.popularity_key,
      count(*)::bigint as search_count,
      count(distinct e.user_id)::bigint as distinct_user_count,
      max(e.searched_at) as latest_search_at
    from eligible e
    group by e.popularity_key
    having count(distinct e.user_id) >= greatest(p_min_distinct_users, 2)
  ),
  representatives as (
    select distinct on (e.popularity_key)
      e.popularity_key,
      e.id,
      e.trip_type,
      e.routes,
      e.first_departure_date,
      e.adults,
      e.children,
      e.infants,
      e.cabin_class,
      e.searched_at
    from eligible e
    join grouped g on g.popularity_key = e.popularity_key
    order by e.popularity_key, e.searched_at desc, e.id
  )
  select
    r.id,
    r.trip_type,
    r.routes,
    r.first_departure_date,
    r.adults,
    r.children,
    r.infants,
    r.cabin_class,
    r.searched_at,
    g.search_count,
    g.distinct_user_count
  from representatives r
  join grouped g on g.popularity_key = r.popularity_key
  order by
    g.distinct_user_count desc,
    g.search_count desc,
    g.latest_search_at desc
  limit least(greatest(p_limit, 1), 10);
$$;

revoke execute on function public.popular_flight_searches_v1(
  timestamptz, date, integer, integer
) from public, anon, authenticated;
grant execute on function public.popular_flight_searches_v1(
  timestamptz, date, integer, integer
) to service_role;

comment on table public.flight_search_history is
  'Validated successful flight searches for private recent-history and anonymous multi-user popularity.';
comment on function public.popular_flight_searches_v1(
  timestamptz, date, integer, integer
) is
  'Anonymized popular future searches; returns only groups searched by at least two distinct users.';


-- SOURCE: 0115_ticketing_operation_window_reconciliation.sql
-- Prevent a read-only PNR observation from racing a NewTicket write. A
-- Booked/Held/Created observation is transitional only when its immutable
-- receipt overlaps a healthy ticketing operation and its supplier identity
-- matches the booking. The rule is supplier-neutral and applies to every
-- Triplover credential account.

create or replace function public.booking_ticketing_observation_overlap_v1(
  p_booking_id uuid,
  p_normalized_evidence jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_request_at timestamptz;
  v_response_at timestamptz;
  v_expected_trans_id text;
  v_expected_booking_code text;
  v_expected_pnr text;
  v_echo jsonb;
  v_operation_id uuid;
begin
  if p_booking_id is null
     or jsonb_typeof(coalesce(p_normalized_evidence, '{}'::jsonb)) <> 'object'
     or p_normalized_evidence->>'source' is distinct from 'pnr' then
    return null;
  end if;

  begin
    v_request_at := (p_normalized_evidence #>> '{receipt,requestStartedAt}')::timestamptz;
    v_response_at := (p_normalized_evidence #>> '{receipt,responseReceivedAt}')::timestamptz;
  exception when others then
    return null;
  end;
  if v_request_at is null or v_response_at is null
     or v_response_at < v_request_at
     or v_response_at > clock_timestamp() + interval '1 minute' then
    return null;
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id and not booking.legacy_operational;
  if not found then return null; end if;

  v_expected_trans_id := nullif(btrim(v_booking.supplier_refs->>'uniqueTransId'), '');
  v_expected_booking_code := nullif(btrim(v_booking.booking_code_ref), '');
  v_expected_pnr := coalesce(
    nullif(btrim(v_booking.pnr), ''),
    nullif(btrim(v_booking.booking_ref_number), '')
  );
  if v_expected_trans_id is null or v_expected_booking_code is null or v_expected_pnr is null
     or upper(btrim(coalesce(p_normalized_evidence #>> '{identity,uniqueTransId}', '')))
          is distinct from upper(v_expected_trans_id)
     or upper(btrim(coalesce(p_normalized_evidence #>> '{identity,bookingCodeRef}', '')))
          is distinct from upper(v_expected_booking_code)
     or upper(btrim(coalesce(p_normalized_evidence #>> '{identity,requestedPnr}', '')))
          is distinct from upper(v_expected_pnr)
     or upper(btrim(coalesce(p_normalized_evidence #>> '{facts,responsePnr}', '')))
          is distinct from upper(v_expected_pnr) then
    return null;
  end if;

  v_echo := coalesce(
    p_normalized_evidence #> '{facts,supplierEchoedUniqueTransIds}',
    '[]'::jsonb
  );
  if jsonb_typeof(v_echo) <> 'array'
     or exists (
       select 1 from jsonb_array_elements_text(v_echo) echoed(value)
        where upper(btrim(echoed.value)) is distinct from upper(v_expected_trans_id)
     ) then
    return null;
  end if;

  select operation.id into v_operation_id
    from public.booking_operations operation
   where operation.booking_id = p_booking_id
     and operation.kind = 'ticketing'
     and (
       (
         operation.state in ('claimed', 'supplier_call_started')
         and v_response_at >= operation.claimed_at
         and v_request_at <= clock_timestamp()
         and v_response_at <= operation.claimed_at + interval '3 minutes'
       )
       or (
         operation.state = 'succeeded'
         and operation.completed_at is not null
         and v_response_at >= operation.claimed_at
         and v_request_at <= operation.completed_at
         and v_response_at <= operation.completed_at
       )
     )
   order by operation.claimed_at desc, operation.id desc
   limit 1;
  return v_operation_id;
end;
$$;

revoke all on function public.booking_ticketing_observation_overlap_v1(uuid, jsonb)
  from public, anon, authenticated, service_role;

create or replace function public.record_booking_pnr_refresh_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_sync_source text,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticketing_time_limit text,
  p_ticketing_deadline_at timestamptz,
  p_normalized_evidence jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_before public.flight_bookings;
  v_after public.flight_bookings;
  v_target text;
  v_case_type text;
  v_conflict boolean;
  v_terminal boolean;
  v_transitional boolean;
  v_overlap_operation_id uuid;
  v_before_lifecycle text;
  v_after_lifecycle text;
  v_facts jsonb;
begin
  if nullif(btrim(p_actor_user_id), '') is null
     or p_actor_role not in (
       'superadmin', 'admin', 'staff_support', 'staff_account',
       'customer', 'b2b', 'b2b_sub', 'system'
     )
     or p_sync_source not in (
       'ordinary_sync', 'cancellation_verification', 'compatibility_sync'
     ) then
    raise exception 'invalid PNR refresh actor' using errcode = '22023';
  end if;

  select booking.* into v_before
    from public.flight_bookings booking
   where booking.id = p_booking_id and not booking.legacy_operational
   for update;
  if not found then raise exception 'booking not found' using errcode = 'P0002'; end if;

  v_target := case lower(btrim(coalesce(p_supplier_status, '')))
    when 'issued' then 'confirmed'
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    when 'booked' then 'on-hold'
    when 'created' then 'on-hold'
    when 'held' then 'on-hold'
    else null
  end;
  v_overlap_operation_id := case when v_target = 'on-hold'
    then public.booking_ticketing_observation_overlap_v1(
      p_booking_id, coalesce(p_normalized_evidence, '{}'::jsonb)
    ) else null end;
  v_transitional := v_overlap_operation_id is not null;
  v_terminal := v_before.status in ('confirmed', 'cancelled');
  v_conflict := case
    when v_transitional then false
    when v_terminal then v_target is distinct from v_before.status
    when p_sync_source = 'cancellation_verification'
      and v_before.status = 'in-progress' and v_target = 'on-hold' then false
    else v_target in ('confirmed', 'cancelled')
      or (v_target is not null and v_target <> v_before.status)
  end;
  v_before_lifecycle := public.resolve_booking_lifecycle(
    v_before.status, v_before.airlines_pnr,
    v_before.ticketing_deadline_at, v_before.operation_kind
  );
  v_facts := jsonb_build_object(
    'version', 2,
    'action', 'ordinary_supplier_sync',
    'source', 'pnr',
    'syncSource', p_sync_source,
    'bookingId', p_booking_id,
    'localStoredStatus', v_before.status,
    'localLifecycleStatus', v_before_lifecycle,
    'supplierStatus', p_supplier_status,
    'candidateLifecycleStatus', v_target,
    'protectedTerminal', v_terminal,
    'ticketingOperationOverlap', v_transitional,
    'overlapOperationId', v_overlap_operation_id,
    'statusMutation', false,
    'walletMutation', false,
    'evidence', coalesce(p_normalized_evidence, '{}'::jsonb)
  );

  if v_conflict then
    update public.flight_bookings
       set synced_at = clock_timestamp(), booking_status = p_supplier_status
     where id = p_booking_id returning * into v_after;
    v_case_type := case
      when v_terminal then 'terminal_conflict'
      when v_target = 'cancelled' then 'cancellation_uncertainty'
      else 'ticketing_uncertainty'
    end;
    perform public.record_booking_sync_case_v1(
      p_booking_id, v_case_type, 'pnr_sync_conflicts_with_local_truth',
      'Ordinary PNR Sync differs from local lifecycle truth and requires controlled resolution.',
      p_actor_user_id, p_actor_role,
      v_facts || jsonb_build_object('caseType', v_case_type)
    );
  else
    update public.flight_bookings
       set synced_at = clock_timestamp(),
           booking_status = case
             when v_transitional and v_terminal then booking_status
             else p_supplier_status
           end,
           airlines_pnr = case
             when public.jsonb_is_nonempty_array(p_airlines_pnr)
               then p_airlines_pnr else airlines_pnr
           end,
           ticketing_time_limit = case
             when p_ticketing_deadline_at is not null and not (v_transitional and v_terminal)
               then p_ticketing_time_limit else ticketing_time_limit
           end,
           ticketing_deadline_at = case
             when v_transitional and v_terminal then ticketing_deadline_at
             else coalesce(p_ticketing_deadline_at, ticketing_deadline_at)
           end,
           deadline_source = case
             when p_ticketing_deadline_at is not null and not (v_transitional and v_terminal)
               then 'pnr_call' else deadline_source
           end
     where id = p_booking_id returning * into v_after;
  end if;

  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_after.status, v_after.airlines_pnr,
    v_after.ticketing_deadline_at, v_after.operation_kind
  );
  if v_after_lifecycle is distinct from v_before_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation, supplier_evidence
    ) values (
      p_booking_id, v_before_lifecycle, v_after_lifecycle,
      v_before.status, v_after.status, v_after.operation_kind,
      v_after.operation_reason, p_actor_user_id, 'PnrRefreshV2',
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'airlinesPnr', p_airlines_pnr,
        'ticketingDeadlineAt', p_ticketing_deadline_at,
        'ticketingOperationOverlap', v_transitional,
        'statusMutation', false, 'walletMutation', false
      )
    );
  end if;
  return v_after;
end;
$$;

create or replace function public.record_booking_pnr_refresh_v3(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_sync_source text,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticketing_time_limit text,
  p_ticketing_deadline_at timestamptz,
  p_normalized_evidence jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_before public.flight_bookings;
  v_after_sync public.flight_bookings;
  v_after public.flight_bookings;
  v_request_id uuid;
  v_target text;
  v_overlap_operation_id uuid;
  v_transitional_terminal boolean;
  v_hash text;
  v_before_lifecycle text;
  v_after_sync_lifecycle text;
  v_after_lifecycle text;
  v_supersede_reason text;
begin
  select * into v_before from public.flight_bookings
   where id = p_booking_id and not legacy_operational for update;
  if not found then raise exception 'booking not found' using errcode = 'P0002'; end if;

  v_before_lifecycle := public.resolve_booking_lifecycle(
    v_before.status, v_before.airlines_pnr,
    v_before.ticketing_deadline_at, v_before.operation_kind
  );
  v_overlap_operation_id := case
    when lower(btrim(coalesce(p_supplier_status, ''))) in ('booked', 'created', 'held')
    then public.booking_ticketing_observation_overlap_v1(
      p_booking_id, coalesce(p_normalized_evidence, '{}'::jsonb)
    ) else null end;
  v_after_sync := public.record_booking_pnr_refresh_v2(
    p_booking_id, p_actor_user_id, p_actor_role, p_sync_source,
    p_supplier_status, p_airlines_pnr, null, null,
    coalesce(p_normalized_evidence, '{}'::jsonb)
  );
  v_after_sync_lifecycle := public.resolve_booking_lifecycle(
    v_after_sync.status, v_after_sync.airlines_pnr,
    v_after_sync.ticketing_deadline_at, v_after_sync.operation_kind
  );
  v_transitional_terminal := v_overlap_operation_id is not null
    and v_after_sync.status in ('confirmed', 'cancelled');
  v_target := case lower(btrim(coalesce(p_supplier_status, '')))
    when 'issued' then 'confirmed'
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    else null
  end;
  v_hash := encode(sha256(convert_to(concat_ws('|',
    p_booking_id::text, 'pnr_sync', coalesce(p_sync_source, ''),
    coalesce(p_supplier_status, ''), coalesce(p_ticketing_time_limit, ''),
    coalesce(p_ticketing_deadline_at::text, ''),
    coalesce(p_normalized_evidence, '{}'::jsonb)::text
  ), 'UTF8')), 'hex');
  insert into public.booking_deadline_observations (
    booking_id, observation_source, supplier_status,
    supplier_time_limit_raw, supplier_deadline_at, supplier_deadline_source,
    actor_user_id, actor_role, normalized_evidence, evidence_hash
  ) values (
    p_booking_id, 'pnr_sync', p_supplier_status,
    p_ticketing_time_limit, p_ticketing_deadline_at, 'pnr_call',
    p_actor_user_id, p_actor_role,
    coalesce(p_normalized_evidence, '{}'::jsonb), v_hash
  ) on conflict do nothing;

  -- Preserve the stale response as evidence, but never let it overwrite the
  -- terminal booking/deadline snapshot completed by the ticketing operation.
  if v_transitional_terminal then return v_after_sync; end if;

  v_request_id := v_after_sync.active_local_time_limit_request_id;
  v_supersede_reason := case
    when v_target is not null then 'supplier_terminal_evidence'
    when p_ticketing_deadline_at >= clock_timestamp() + interval '15 minutes'
      then 'supplier_deadline_now_sufficient'
    else null
  end;
  if v_request_id is not null and v_supersede_reason is not null then
    update public.booking_local_time_limit_requests set
      state = 'superseded', superseded_at = clock_timestamp(),
      superseded_reason = v_supersede_reason, version = version + 1
    where id = v_request_id and state = 'approved';
    insert into public.booking_local_time_limit_events (
      booking_id, request_id, event_type, actor_user_id, actor_role,
      prior_deadline_at, resulting_deadline_at, reason, evidence
    ) values (
      p_booking_id, v_request_id,
      case when v_target is null then 'superseded' else 'supplier_conflict' end,
      p_actor_user_id, p_actor_role,
      v_after_sync.local_ticketing_deadline_at, p_ticketing_deadline_at,
      v_supersede_reason,
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'supplierDeadlineAt', p_ticketing_deadline_at,
        'walletMutation', false
      )
    );
  end if;

  update public.flight_bookings set
    supplier_ticketing_time_limit = p_ticketing_time_limit,
    supplier_ticketing_deadline_at = p_ticketing_deadline_at,
    supplier_deadline_source = 'pnr_call',
    active_local_time_limit_request_id = case
      when v_supersede_reason is not null then null
      else active_local_time_limit_request_id
    end,
    ticketing_time_limit = p_ticketing_time_limit,
    ticketing_deadline_at = case
      when v_supersede_reason is not null then p_ticketing_deadline_at
      when active_local_time_limit_request_id is not null
        then local_ticketing_deadline_at
      else p_ticketing_deadline_at
    end,
    deadline_source = case
      when v_supersede_reason is null
           and active_local_time_limit_request_id is not null
        then 'local_approved'
      else 'pnr_call'
    end
  where id = p_booking_id returning * into v_after;

  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_after.status, v_after.airlines_pnr,
    v_after.ticketing_deadline_at, v_after.operation_kind
  );
  if v_after_lifecycle is distinct from v_after_sync_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation,
      supplier_evidence, idempotency_key
    ) values (
      p_booking_id, v_after_sync_lifecycle, v_after_lifecycle,
      v_after_sync.status, v_after.status, v_after.operation_kind,
      v_after.operation_reason, p_actor_user_id, 'PnrRefreshV3',
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'supplierDeadlineAt', p_ticketing_deadline_at,
        'localGrantSuperseded', v_supersede_reason is not null,
        'walletMutation', false
      ), 'pnr-refresh-v3:' || v_hash
    ) on conflict do nothing;
  end if;
  return v_after;
end;
$$;

revoke all on function public.record_booking_pnr_refresh_v2(
  uuid, text, text, text, text, jsonb, text, timestamptz, jsonb
) from public, anon, authenticated;
revoke all on function public.record_booking_pnr_refresh_v3(
  uuid, text, text, text, text, jsonb, text, timestamptz, jsonb
) from public, anon, authenticated;
grant execute on function public.record_booking_pnr_refresh_v2(
  uuid, text, text, text, text, jsonb, text, timestamptz, jsonb
) to service_role;
grant execute on function public.record_booking_pnr_refresh_v3(
  uuid, text, text, text, text, jsonb, text, timestamptz, jsonb
) to service_role;

comment on function public.booking_ticketing_observation_overlap_v1(uuid, jsonb)
is 'Returns the matching healthy ticketing operation only when a case-bound PNR receipt and supplier identity overlap its NewTicket window. It is supplier-account neutral and moves no lifecycle or financial state.';

-- Supplier lifecycle timestamps are enrichment only. Once the booking writer
-- has established its authoritative terminal instant, a later report cannot
-- replace it with a lower-quality observation.
create or replace function public.record_booking_supplier_refresh_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_sync_source text,
  p_supplier_status text,
  p_airlines_pnr jsonb,
  p_ticket_numbers jsonb,
  p_issued_at timestamptz,
  p_cancelled_at timestamptz,
  p_normalized_evidence jsonb
)
returns public.flight_bookings
language plpgsql
security definer
set search_path = public
as $$
declare
  v_before public.flight_bookings;
  v_after public.flight_bookings;
  v_target text;
  v_case_type text;
  v_conflict boolean;
  v_terminal boolean;
  v_before_lifecycle text;
  v_after_lifecycle text;
  v_facts jsonb;
begin
  if nullif(btrim(p_actor_user_id), '') is null
     or p_actor_role not in (
       'superadmin', 'admin', 'staff_support', 'staff_account',
       'customer', 'b2b', 'b2b_sub', 'system'
     )
     or p_sync_source not in (
       'ordinary_sync', 'cancellation_verification', 'compatibility_sync'
     ) then
    raise exception 'invalid supplier refresh actor' using errcode = '22023';
  end if;

  select booking.* into v_before
    from public.flight_bookings booking
   where booking.id = p_booking_id and not booking.legacy_operational
   for update;
  if not found then raise exception 'booking not found' using errcode = 'P0002'; end if;

  v_target := case lower(btrim(coalesce(p_supplier_status, '')))
    when 'issued' then 'confirmed'
    when 'confirmed' then 'confirmed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    else null
  end;
  v_terminal := v_before.status in ('confirmed', 'cancelled');
  v_conflict := case
    when v_terminal then v_target is distinct from v_before.status
    else v_target is not null and v_target <> v_before.status
  end;
  v_before_lifecycle := public.resolve_booking_lifecycle(
    v_before.status, v_before.airlines_pnr,
    v_before.ticketing_deadline_at, v_before.operation_kind
  );
  v_facts := jsonb_build_object(
    'version', 2, 'action', 'ordinary_supplier_sync',
    'source', 'air-ticketing-details', 'syncSource', p_sync_source,
    'bookingId', p_booking_id, 'localStoredStatus', v_before.status,
    'localLifecycleStatus', v_before_lifecycle,
    'supplierStatus', p_supplier_status,
    'candidateLifecycleStatus', v_target,
    'protectedTerminal', v_terminal,
    'statusMutation', false, 'walletMutation', false,
    'evidence', coalesce(p_normalized_evidence, '{}'::jsonb)
  );

  if v_conflict then
    update public.flight_bookings
       set synced_at = clock_timestamp(), booking_status = p_supplier_status
     where id = p_booking_id returning * into v_after;
    v_case_type := case
      when v_terminal then 'terminal_conflict'
      when v_target = 'cancelled' then 'cancellation_uncertainty'
      else 'ticketing_uncertainty'
    end;
    perform public.record_booking_sync_case_v1(
      p_booking_id, v_case_type,
      'supplier_sync_conflicts_with_local_truth',
      'Ordinary AirTicketingDetails Sync differs from local lifecycle truth and requires controlled resolution.',
      p_actor_user_id, p_actor_role,
      v_facts || jsonb_build_object('caseType', v_case_type)
    );
  else
    update public.flight_bookings
       set synced_at = clock_timestamp(),
           booking_status = p_supplier_status,
           airlines_pnr = case
             when public.jsonb_is_nonempty_array(p_airlines_pnr)
               then p_airlines_pnr else airlines_pnr
           end,
           ticket_numbers = case
             when public.jsonb_is_nonempty_array(p_ticket_numbers)
               then p_ticket_numbers else ticket_numbers
           end,
           issued_at = case
             when status = 'confirmed' and v_target = 'confirmed'
               then coalesce(issued_at, p_issued_at)
             else issued_at
           end,
           cancelled_at = case
             when status = 'cancelled' and v_target = 'cancelled'
               then coalesce(cancelled_at, p_cancelled_at)
             else cancelled_at
           end
     where id = p_booking_id returning * into v_after;
  end if;

  v_after_lifecycle := public.resolve_booking_lifecycle(
    v_after.status, v_after.airlines_pnr,
    v_after.ticketing_deadline_at, v_after.operation_kind
  );
  if v_after_lifecycle is distinct from v_before_lifecycle then
    insert into public.booking_status_events (
      booking_id, from_lifecycle_status, to_lifecycle_status,
      stored_status_before, stored_status_after, operation_kind,
      operation_reason, actor_user_id, supplier_operation, supplier_evidence
    ) values (
      p_booking_id, v_before_lifecycle, v_after_lifecycle,
      v_before.status, v_after.status, v_after.operation_kind,
      v_after.operation_reason, p_actor_user_id, 'SupplierRefreshV2',
      jsonb_build_object(
        'supplierStatus', p_supplier_status,
        'statusMutation', false, 'walletMutation', false
      )
    );
  end if;
  return v_after;
end;
$$;

revoke all on function public.record_booking_supplier_refresh_v2(
  uuid, text, text, text, text, jsonb, jsonb, timestamptz, timestamptz, jsonb
) from public, anon, authenticated;
grant execute on function public.record_booking_supplier_refresh_v2(
  uuid, text, text, text, text, jsonb, jsonb, timestamptz, timestamptz, jsonb
) to service_role;

-- Permit the service-owned post-ticketing verifier to append the same
-- immutable case-bound evidence as the staff endpoint. All existing payload,
-- freshness and no-mutation constraints remain unchanged.
create or replace function public.record_booking_reconciliation_evidence_read_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_observation_key text,
  p_normalized_facts jsonb,
  p_normalized_facts_hash text,
  p_observed_at timestamptz,
  p_evidence_observed_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_case public.booking_reconciliation_cases;
  v_observation public.booking_reconciliation_observations;
  v_existing_hash text;
  v_created boolean := false;
  v_case_version integer;
begin
  if p_booking_id is null or p_case_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_actor_role not in ('staff_support', 'admin', 'superadmin', 'system')
     or p_observation_key !~ '^evidence-read:v1:[a-f0-9]{64}$'
     or p_normalized_facts_hash !~ '^[a-f0-9]{64}$'
     or jsonb_typeof(coalesce(p_normalized_facts, '{}'::jsonb)) <> 'object'
     or coalesce(p_normalized_facts->>'version', '') <> '1'
     or coalesce(p_normalized_facts->>'action', '') <> 'supplier_evidence_read'
     or coalesce((p_normalized_facts->>'statusMutation')::boolean, true) is not false
     or coalesce((p_normalized_facts->>'walletMutation')::boolean, true) is not false
     or coalesce((p_normalized_facts->>'destructiveSupplierCall')::boolean, true) is not false
     or p_normalized_facts->>'bookingId' is distinct from p_booking_id::text
     or p_normalized_facts->>'caseId' is distinct from p_case_id::text
     or p_observed_at is null
     or p_observed_at > clock_timestamp() + interval '1 minute'
     or p_observed_at < clock_timestamp() - interval '5 minutes'
     or (p_evidence_observed_at is not null and (
       p_evidence_observed_at > p_observed_at + interval '1 minute'
       or p_evidence_observed_at < p_observed_at - interval '5 minutes'
     )) then
    raise exception 'invalid reconciliation evidence-read observation'
      using errcode = '22023';
  end if;

  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
   for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND'); end if;
  if v_case.state not in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  ) then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN');
  end if;
  if not exists (
    select 1 from public.flight_bookings booking where booking.id = p_booking_id
  ) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  insert into public.booking_reconciliation_observations (
    reconciliation_case_id, observation_key, observation_kind,
    observation_source, actor_user_id, actor_role, normalized_facts,
    normalized_facts_hash, observed_at
  ) values (
    p_case_id, p_observation_key, 'staff_evidence', 'supplier_read',
    p_actor_user_id, p_actor_role, p_normalized_facts,
    p_normalized_facts_hash, p_observed_at
  ) on conflict (reconciliation_case_id, observation_key) do nothing
  returning * into v_observation;

  if v_observation.id is null then
    select observation.normalized_facts_hash into v_existing_hash
      from public.booking_reconciliation_observations observation
     where observation.reconciliation_case_id = p_case_id
       and observation.observation_key = p_observation_key;
    if v_existing_hash is distinct from p_normalized_facts_hash then
      raise exception 'evidence-read request payload mismatch' using errcode = '22023';
    end if;
    select observation.* into v_observation
      from public.booking_reconciliation_observations observation
     where observation.reconciliation_case_id = p_case_id
       and observation.observation_key = p_observation_key;
  else
    v_created := true;
    update public.booking_reconciliation_cases
       set evidence_latest_at = case
             when p_evidence_observed_at is null then evidence_latest_at
             when evidence_latest_at is null then p_evidence_observed_at
             else greatest(evidence_latest_at, p_evidence_observed_at)
           end,
           evidence_normalizer_version = case
             when p_evidence_observed_at is null then evidence_normalizer_version
             else 1
           end,
           version = version + 1
     where id = p_case_id;
  end if;

  select version into v_case_version
    from public.booking_reconciliation_cases where id = p_case_id;
  return jsonb_build_object(
    'ok', true, 'replay', not v_created, 'caseId', p_case_id,
    'caseVersion', v_case_version, 'observationId', v_observation.id,
    'evidenceLatestAt', case when p_evidence_observed_at is null
      then null else p_evidence_observed_at end,
    'statusMutation', false, 'walletMutation', false,
    'destructiveSupplierCall', false
  );
end;
$$;

revoke all on function public.record_booking_reconciliation_evidence_read_v1(
  uuid, uuid, text, text, text, jsonb, text, timestamptz, timestamptz
) from public, anon, authenticated;
grant execute on function public.record_booking_reconciliation_evidence_read_v1(
  uuid, uuid, text, text, text, jsonb, text, timestamptz, timestamptz
) to service_role;

-- Close only the historical false-positive shape created by an overlapping
-- PNR read. Unlike the general no-change closer, this function accepts an
-- already-succeeded ticketing operation and deliberately mutates only the
-- reconciliation case plus its security audit record.
create or replace function public.close_booking_ticketing_race_no_change_v1(
  p_booking_id uuid,
  p_case_id uuid,
  p_observation_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_observation public.booking_reconciliation_observations;
  v_operation_id uuid;
  v_evidence_at timestamptz;
begin
  if p_booking_id is null or p_case_id is null or p_observation_id is null then
    raise exception 'invalid ticketing-race closure request' using errcode = '22023';
  end if;

  select candidate.operation_id into v_operation_id
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND'); end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND'); end if;

  if v_operation_id is not null then
    select operation.* into v_operation
      from public.booking_operations operation
     where operation.id = v_operation_id
       and operation.booking_id = p_booking_id
     for update;
  end if;
  select candidate.* into v_case
    from public.booking_reconciliation_cases candidate
   where candidate.id = p_case_id
     and candidate.subject_booking_id = p_booking_id
   for update;

  if v_case.state = 'closed_no_change'
     and v_case.resolution_outcome = 'supplier_truth_unchanged'
     and v_case.resolution->>'observationId' = p_observation_id::text then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'caseId', p_case_id,
      'observationId', p_observation_id,
      'statusMutation', false, 'walletMutation', false
    );
  end if;
  if v_case.state not in (
    'open', 'assigned', 'awaiting_supplier',
    'awaiting_finance', 'awaiting_approval'
  ) then
    return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN');
  end if;

  select reservation.* into v_reservation
    from public.wallet_reservations reservation
   where reservation.booking_id = p_booking_id for update;
  select observation.* into v_observation
    from public.booking_reconciliation_observations observation
   where observation.id = p_observation_id
     and observation.reconciliation_case_id = p_case_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'EVIDENCE_NOT_FOUND'); end if;

  if v_case.case_type <> 'ticketing_uncertainty'
     or v_case.reason_code <> 'pnr_sync_conflicts_with_local_truth'
     or v_case.opened_source <> 'supplier_sync'
     or v_case.proposed_outcome is not null
     or v_case.financial_disposition <> 'none'
     or v_case.operation_id is null
     or v_operation.id is null
     or v_operation.kind <> 'ticketing'
     or v_operation.state <> 'succeeded'
     or v_operation.completed_at is null
     or v_case.opened_at < v_operation.claimed_at - interval '1 minute'
     or v_case.opened_at > v_operation.completed_at + interval '1 minute'
     or v_booking.active_operation_id is not null
     or v_booking.status <> 'confirmed'
     or exists (
       select 1 from public.booking_reconciliation_cases other_case
        where other_case.subject_booking_id = p_booking_id
          and other_case.id <> p_case_id
          and other_case.state in (
            'open', 'assigned', 'awaiting_supplier',
            'awaiting_finance', 'awaiting_approval'
          )
     ) then
    return jsonb_build_object('ok', false, 'code', 'TICKETING_RACE_CLOSURE_NOT_ELIGIBLE');
  end if;

  begin
    v_evidence_at := (v_observation.normalized_facts->>'evidenceObservedAt')::timestamptz;
  exception when others then
    v_evidence_at := null;
  end;
  if v_observation.observation_kind <> 'staff_evidence'
     or v_observation.observation_source <> 'supplier_read'
     or v_observation.normalized_facts->>'action' is distinct from 'supplier_evidence_read'
     or v_observation.normalized_facts->>'bookingId' is distinct from p_booking_id::text
     or v_observation.normalized_facts->>'caseId' is distinct from p_case_id::text
     or v_observation.normalized_facts #>> '{validation,authoritativeFor}'
          is distinct from 'ticketed'
     or coalesce((v_observation.normalized_facts #>> '{validation,valid}')::boolean, false) is not true
     or coalesce((v_observation.normalized_facts #>> '{validation,complete}')::boolean, false) is not true
     or coalesce((v_observation.normalized_facts #>> '{validation,fresh}')::boolean, false) is not true
     or coalesce((v_observation.normalized_facts #>> '{validation,identityMatches}')::boolean, false) is not true
     or v_evidence_at is null
     or v_evidence_at < clock_timestamp() - interval '5 minutes'
     or v_evidence_at > clock_timestamp() + interval '1 minute'
     or not (
       coalesce(v_observation.normalized_facts->'recordedSources', '[]'::jsonb)
         @> '["pnr", "air-ticketing-details"]'::jsonb
     )
     or v_observation.normalized_facts #>> '{evidence,pnr,source}' is distinct from 'pnr'
     or v_observation.normalized_facts #>> '{evidence,airTicketing,source}'
          is distinct from 'air-ticketing-details'
     or upper(btrim(coalesce(
          v_observation.normalized_facts #>> '{expectedIdentity,uniqueTransId}', ''
        ))) is distinct from upper(btrim(coalesce(
          v_booking.supplier_refs->>'uniqueTransId', ''
        )))
     or upper(btrim(coalesce(
          v_observation.normalized_facts #>> '{expectedIdentity,bookingCodeRef}', ''
        ))) is distinct from upper(btrim(coalesce(v_booking.booking_code_ref, '')))
     or v_observation.normalized_facts #>> '{localContext,storedStatus}'
          is distinct from v_booking.status
     or v_observation.normalized_facts #>> '{localContext,paymentState}'
          is distinct from v_booking.payment_state then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_NOT_AUTHORITATIVE');
  end if;

  if not (
    v_booking.payment_state = 'captured'
    and v_booking.captured_amount > 0
    and v_booking.refunded_amount = 0
    and v_booking.payment_amount = v_booking.captured_amount
    and v_reservation.id is not null
    and v_reservation.state = 'captured'
    and v_reservation.amount = v_booking.captured_amount
    and v_reservation.currency = v_booking.currency
  ) then
    return jsonb_build_object('ok', false, 'code', 'FINANCIAL_CONFLICT');
  end if;

  update public.booking_reconciliation_cases
     set state = 'closed_no_change',
         resolution_outcome = 'supplier_truth_unchanged',
         resolution = jsonb_build_object(
           'observationId', p_observation_id,
           'authoritativeFor', 'ticketed',
           'closureKind', 'ticketing_operation_window_race',
           'statusMutation', false, 'walletMutation', false
         ),
         resolution_reason =
           'Fresh complete supplier evidence confirms the issued ticket, booking identity, itinerary, passengers, and already-captured financial state',
         resolved_by_user_id = 'system:post-ticketing-evidence',
         resolved_at = clock_timestamp(), closed_at = clock_timestamp(),
         version = version + 1
   where id = p_case_id;

  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id, outcome, metadata
  ) values (
    'system:post-ticketing-evidence', 'system',
    'booking.reconciliation.ticketing_race_closed_no_change',
    'flight_booking', p_booking_id::text, 'succeeded',
    jsonb_build_object(
      'caseId', p_case_id, 'operationId', v_operation.id,
      'observationId', p_observation_id, 'authoritativeFor', 'ticketed',
      'statusMutation', false, 'walletMutation', false
    )
  );

  return jsonb_build_object(
    'ok', true, 'replay', false, 'caseId', p_case_id,
    'operationId', v_operation.id, 'observationId', p_observation_id,
    'closedNoChange', true, 'statusMutation', false, 'walletMutation', false
  );
end;
$$;

revoke all on function public.close_booking_ticketing_race_no_change_v1(uuid, uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.close_booking_ticketing_race_no_change_v1(uuid, uuid, uuid)
  to service_role;

comment on function public.close_booking_ticketing_race_no_change_v1(uuid, uuid, uuid)
is 'Idempotently closes only a PNR-sync ticketing race case after fresh complete PNR plus AirTicketingDetails evidence matches the confirmed booking and captured reservation. It changes no booking, operation, wallet, reservation, ledger, event, or notification state.';


-- SOURCE: 0116_canonical_supplier_evidence_v2.sql
-- Canonical Supplier Evidence V2.
--
-- V1 observations and functions remain unchanged for immutable historical and
-- supplier-import evidence. New live reconciliation reads use a distinct V2
-- observation/idempotency namespace and one supplier-neutral evidence shape.

create or replace function public.booking_reconciliation_evidence_v2_authoritative(
  p_booking_id uuid,
  p_case_id uuid,
  p_observation_id uuid,
  p_truth text
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_observation public.booking_reconciliation_observations;
  v_facts jsonb;
  v_evidence_at timestamptz;
  v_expected_payable_minor bigint;
begin
  if p_truth not in ('ticketed', 'cancelled') then return false; end if;
  select * into v_booking from public.flight_bookings where id = p_booking_id;
  select * into v_observation
    from public.booking_reconciliation_observations
   where id = p_observation_id and reconciliation_case_id = p_case_id;
  if v_booking.id is null or v_observation.id is null then return false; end if;
  v_facts := v_observation.normalized_facts;
  begin
    v_evidence_at := (v_facts->>'evidenceObservedAt')::timestamptz;
    v_expected_payable_minor := round(
      ((v_booking.pricing_snapshot->>'supplierTotalPrice')::numeric) * 100
    )::bigint;
  exception when others then
    return false;
  end;

  return
    v_observation.observation_kind = 'staff_evidence'
    and v_observation.observation_source = 'supplier_read'
    and v_facts->>'version' = '2'
    and v_facts->>'evidenceContract' = 'canonical_supplier_evidence_v2'
    and v_facts->>'action' = 'supplier_evidence_read'
    and v_facts->>'bookingId' = p_booking_id::text
    and v_facts->>'caseId' = p_case_id::text
    and v_facts->>'requestedPurpose' = p_truth
    and v_facts #>> '{validation,contractVersion}' = '2'
    and v_facts #>> '{validation,authoritativeFor}' = p_truth
    and coalesce((v_facts #>> '{validation,valid}')::boolean, false)
    and coalesce((v_facts #>> '{validation,complete}')::boolean, false)
    and coalesce((v_facts #>> '{validation,fresh}')::boolean, false)
    and coalesce((v_facts #>> '{validation,identityMatches}')::boolean, false)
    and coalesce((v_facts->>'statusMutation')::boolean, true) is false
    and coalesce((v_facts->>'walletMutation')::boolean, true) is false
    and coalesce((v_facts->>'destructiveSupplierCall')::boolean, true) is false
    and v_evidence_at between clock_timestamp() - interval '5 minutes'
                          and clock_timestamp() + interval '1 minute'
    and coalesce(v_facts->'recordedSources', '[]'::jsonb)
          @> '["pnr", "ticket-report"]'::jsonb
    and v_facts #>> '{evidence,pnr,schemaVersion}' = '2'
    and v_facts #>> '{evidence,pnr,source}' = 'pnr'
    and v_facts #>> '{evidence,ticketReport,schemaVersion}' = '2'
    and v_facts #>> '{evidence,ticketReport,source}' = 'ticket-report'
    and v_facts #>> '{expectedIdentity,supplierAccount}'
          is not distinct from v_booking.supplier_account
    and v_facts #>> '{expectedIdentity,bookingIdentity,transactionId}'
          is not distinct from v_booking.supplier_refs->>'uniqueTransId'
    and v_facts #>> '{expectedIdentity,bookingIdentity,supplierPnr}'
          is not distinct from v_booking.pnr
    and v_facts #>> '{expectedIdentity,bookingIdentity,bookingReference}'
          is not distinct from v_booking.booking_ref_number
    and v_facts #>> '{expectedIdentity,bookingIdentity,operationalReferences,itemCodeRef}'
          is not distinct from v_booking.supplier_refs->>'itemCodeRef'
    and v_facts #>> '{expectedIdentity,bookingIdentity,operationalReferences,priceCodeRef}'
          is not distinct from v_booking.supplier_refs->>'priceCodeRef'
    and v_facts #>> '{expectedIdentity,bookingIdentity,operationalReferences,bookingCodeRef}'
          is not distinct from v_booking.booking_code_ref
    and v_facts #>> '{evidence,ticketReport,bookingIdentity,transactionId}'
          is not distinct from v_booking.supplier_refs->>'uniqueTransId'
    and v_facts #>> '{evidence,ticketReport,bookingIdentity,supplierPnr}'
          is not distinct from v_booking.pnr
    and v_facts #>> '{evidence,ticketReport,bookingIdentity,bookingReference}'
          is not distinct from v_booking.booking_ref_number
    and v_facts #>> '{evidence,ticketReport,bookingIdentity,operationalReferences,itemCodeRef}'
          is not distinct from v_booking.supplier_refs->>'itemCodeRef'
    and v_facts #>> '{evidence,ticketReport,bookingIdentity,operationalReferences,priceCodeRef}'
          is not distinct from v_booking.supplier_refs->>'priceCodeRef'
    and v_facts #>> '{evidence,ticketReport,bookingIdentity,operationalReferences,bookingCodeRef}'
          is not distinct from v_booking.booking_code_ref
    and v_facts #>> '{evidence,pnr,requestIdentity,transactionId}'
          is not distinct from v_booking.supplier_refs->>'uniqueTransId'
    and v_facts #>> '{evidence,pnr,requestIdentity,supplierPnr}'
          is not distinct from v_booking.pnr
    and v_facts #>> '{evidence,pnr,requestIdentity,bookingReference}'
          is not distinct from v_booking.booking_ref_number
    and upper(v_facts #>> '{expectedIdentity,financial,currency}')
          is not distinct from upper(v_booking.currency)
    and (v_facts #>> '{expectedIdentity,financial,supplierPayableMinor}')::bigint
          = v_expected_payable_minor
    and v_expected_payable_minor > 0
    and (v_facts #>> '{evidence,ticketReport,financial,supplierPayableMinor}')::bigint
          = v_expected_payable_minor
    and upper(v_facts #>> '{evidence,ticketReport,financial,currency}')
          is not distinct from upper(v_booking.currency)
    and v_facts #>> '{localContext,storedStatus}' = v_booking.status
    and v_facts #>> '{localContext,paymentState}' = v_booking.payment_state
    and (
      v_booking.status <> 'confirmed'
      or (
        jsonb_typeof(coalesce(v_booking.ticket_numbers, '[]'::jsonb)) = 'array'
        and jsonb_array_length(coalesce(v_booking.ticket_numbers, '[]'::jsonb)) > 0
        and (
          select array_agg(upper(btrim(value)) order by upper(btrim(value)))
            from jsonb_array_elements_text(v_booking.ticket_numbers)
        ) = (
          select array_agg(
                   upper(btrim(ticket.value->>'fullNumber'))
                   order by upper(btrim(ticket.value->>'fullNumber'))
                 )
            from jsonb_array_elements(coalesce(
              v_facts #> '{evidence,ticketReport,tickets}', '[]'::jsonb
            )) ticket(value)
           where jsonb_typeof(ticket.value) = 'object'
             and nullif(btrim(ticket.value->>'fullNumber'), '') is not null
        )
      )
    );
exception when others then
  return false;
end;
$$;

revoke all on function public.booking_reconciliation_evidence_v2_authoritative(
  uuid, uuid, uuid, text
) from public, anon, authenticated;
grant execute on function public.booking_reconciliation_evidence_v2_authoritative(
  uuid, uuid, uuid, text
) to service_role;

create or replace function public.record_booking_reconciliation_evidence_read_v2(
  p_booking_id uuid,
  p_case_id uuid,
  p_actor_user_id text,
  p_actor_role text,
  p_observation_key text,
  p_normalized_facts jsonb,
  p_normalized_facts_hash text,
  p_observed_at timestamptz,
  p_evidence_observed_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_case public.booking_reconciliation_cases;
  v_observation public.booking_reconciliation_observations;
  v_existing_hash text;
  v_created boolean := false;
  v_case_version integer;
begin
  if p_booking_id is null or p_case_id is null
     or nullif(btrim(coalesce(p_actor_user_id, '')), '') is null
     or p_actor_role not in ('staff_support', 'admin', 'superadmin', 'system')
     or p_observation_key !~ '^evidence-read:v2:[a-f0-9]{64}$'
     or p_normalized_facts_hash !~ '^[a-f0-9]{64}$'
     or jsonb_typeof(coalesce(p_normalized_facts, '{}'::jsonb)) <> 'object'
     or p_normalized_facts->>'version' <> '2'
     or p_normalized_facts->>'evidenceContract' <> 'canonical_supplier_evidence_v2'
     or p_normalized_facts->>'action' <> 'supplier_evidence_read'
     or coalesce((p_normalized_facts->>'statusMutation')::boolean, true)
     or coalesce((p_normalized_facts->>'walletMutation')::boolean, true)
     or coalesce((p_normalized_facts->>'destructiveSupplierCall')::boolean, true)
     or p_normalized_facts->>'bookingId' is distinct from p_booking_id::text
     or p_normalized_facts->>'caseId' is distinct from p_case_id::text
     or p_normalized_facts #>> '{validation,contractVersion}' <> '2'
     or p_observed_at is null
     or p_observed_at > clock_timestamp() + interval '1 minute'
     or p_observed_at < clock_timestamp() - interval '5 minutes'
     or (p_evidence_observed_at is not null and (
       p_evidence_observed_at > p_observed_at + interval '1 minute'
       or p_evidence_observed_at < p_observed_at - interval '5 minutes'
     )) then
    raise exception 'invalid canonical V2 reconciliation evidence observation'
      using errcode = '22023';
  end if;

  select * into v_case from public.booking_reconciliation_cases
   where id = p_case_id and subject_booking_id = p_booking_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND'); end if;
  if v_case.state not in (
    'open', 'assigned', 'awaiting_supplier', 'awaiting_finance', 'awaiting_approval'
  ) then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN'); end if;
  if not exists (select 1 from public.flight_bookings where id = p_booking_id) then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  insert into public.booking_reconciliation_observations (
    reconciliation_case_id, observation_key, observation_kind,
    observation_source, actor_user_id, actor_role, normalized_facts,
    normalized_facts_hash, observed_at
  ) values (
    p_case_id, p_observation_key, 'staff_evidence', 'supplier_read',
    p_actor_user_id, p_actor_role, p_normalized_facts,
    p_normalized_facts_hash, p_observed_at
  ) on conflict (reconciliation_case_id, observation_key) do nothing
  returning * into v_observation;

  if v_observation.id is null then
    select normalized_facts_hash into v_existing_hash
      from public.booking_reconciliation_observations
     where reconciliation_case_id = p_case_id and observation_key = p_observation_key;
    if v_existing_hash is distinct from p_normalized_facts_hash then
      raise exception 'canonical V2 evidence request payload mismatch' using errcode = '22023';
    end if;
    select * into v_observation from public.booking_reconciliation_observations
     where reconciliation_case_id = p_case_id and observation_key = p_observation_key;
  else
    v_created := true;
    update public.booking_reconciliation_cases
       set evidence_latest_at = case
             when p_evidence_observed_at is null then evidence_latest_at
             when evidence_latest_at is null then p_evidence_observed_at
             else greatest(evidence_latest_at, p_evidence_observed_at) end,
           evidence_normalizer_version = case
             when p_evidence_observed_at is null then evidence_normalizer_version else 2 end,
           version = version + 1
     where id = p_case_id;
  end if;
  select version into v_case_version from public.booking_reconciliation_cases where id = p_case_id;
  return jsonb_build_object(
    'ok', true, 'replay', not v_created, 'caseId', p_case_id,
    'caseVersion', v_case_version, 'observationId', v_observation.id,
    'evidenceLatestAt', p_evidence_observed_at,
    'statusMutation', false, 'walletMutation', false,
    'destructiveSupplierCall', false
  );
end;
$$;

revoke all on function public.record_booking_reconciliation_evidence_read_v2(
  uuid, uuid, text, text, text, jsonb, text, timestamptz, timestamptz
) from public, anon, authenticated;
grant execute on function public.record_booking_reconciliation_evidence_read_v2(
  uuid, uuid, text, text, text, jsonb, text, timestamptz, timestamptz
) to service_role;

create or replace function public.close_booking_reconciliation_no_change_v2(
  p_booking_id uuid,
  p_case_id uuid,
  p_observation_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_operation_id uuid;
  v_truth text;
begin
  if p_booking_id is null or p_case_id is null or p_observation_id is null then
    raise exception 'invalid V2 no-change closure request' using errcode = '22023';
  end if;
  select operation_id into v_operation_id from public.booking_reconciliation_cases
   where id = p_case_id and subject_booking_id = p_booking_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND'); end if;
  select * into v_booking from public.flight_bookings
   where id = p_booking_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND'); end if;
  if v_operation_id is not null then
    select * into v_operation from public.booking_operations
     where id = v_operation_id and booking_id = p_booking_id for update;
  end if;
  select * into v_case from public.booking_reconciliation_cases
   where id = p_case_id and subject_booking_id = p_booking_id for update;
  if v_case.state = 'closed_no_change'
     and v_case.resolution_outcome = 'supplier_truth_unchanged'
     and v_case.resolution->>'observationId' = p_observation_id::text then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'caseId', p_case_id,
      'observationId', p_observation_id, 'closedNoChange', true,
      'statusMutation', false, 'walletMutation', false
    );
  end if;
  if v_case.state not in (
    'open', 'assigned', 'awaiting_supplier', 'awaiting_finance', 'awaiting_approval'
  ) then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN'); end if;
  select * into v_reservation from public.wallet_reservations
   where booking_id = p_booking_id for update;
  if v_case.case_type not in ('ticketing_uncertainty', 'cancellation_uncertainty')
     or v_case.proposed_outcome is not null
     or v_case.financial_disposition <> 'none'
     or v_case.operation_id is null
     or v_operation.id is null
     or v_operation.state <> 'needs_reconciliation'
     or (v_booking.active_operation_id is not null
       and v_booking.active_operation_id <> v_operation.id)
     or exists (
       select 1 from public.booking_reconciliation_cases other_case
        where other_case.subject_booking_id = p_booking_id
          and other_case.id <> p_case_id
          and other_case.state in (
            'open', 'assigned', 'awaiting_supplier',
            'awaiting_finance', 'awaiting_approval'
          )
     ) then
    return jsonb_build_object('ok', false, 'code', 'NO_CHANGE_CLOSURE_NOT_ELIGIBLE');
  end if;
  v_truth := case v_booking.status
    when 'confirmed' then 'ticketed'
    when 'cancelled' then 'cancelled'
    else null end;
  if v_truth is null or not public.booking_reconciliation_evidence_v2_authoritative(
    p_booking_id, p_case_id, p_observation_id, v_truth
  ) or (v_truth = 'ticketed' and v_operation.kind <> 'ticketing')
     or (v_truth = 'cancelled' and v_operation.kind <> 'cancellation') then
    return jsonb_build_object('ok', false, 'code', 'EVIDENCE_NOT_AUTHORITATIVE');
  end if;
  if (
    v_truth = 'ticketed' and not (
      v_booking.payment_state = 'captured'
      and v_booking.captured_amount > 0
      and v_booking.refunded_amount = 0
      and v_booking.payment_amount = v_booking.captured_amount
      and v_reservation.id is not null
      and v_reservation.state = 'captured'
      and v_reservation.amount = v_booking.captured_amount
      and v_reservation.currency = v_booking.currency
    )
  ) or (
    v_truth = 'cancelled' and not (
      (v_booking.payment_state = 'unpaid' and v_booking.captured_amount = 0
        and v_booking.refunded_amount = 0 and v_reservation.id is null)
      or (v_booking.payment_state = 'released' and v_booking.captured_amount = 0
        and v_booking.refunded_amount = 0 and v_reservation.id is not null
        and v_reservation.state = 'released')
      or (v_booking.payment_state = 'refunded' and v_booking.captured_amount > 0
        and v_booking.refunded_amount = v_booking.captured_amount
        and v_reservation.id is not null and v_reservation.state = 'captured')
    )
  ) then return jsonb_build_object('ok', false, 'code', 'FINANCIAL_CONFLICT'); end if;

  update public.booking_operations
     set state = 'succeeded', completed_at = coalesce(completed_at, clock_timestamp()),
         error_code = null, error_message = null,
         supplier_evidence = coalesce(supplier_evidence, '{}'::jsonb) ||
           jsonb_build_object('canonicalV2NoChangeClosure', jsonb_build_object(
             'observationId', p_observation_id, 'authoritativeFor', v_truth,
             'closedAt', clock_timestamp()))
   where id = v_operation.id;
  update public.flight_bookings
     set active_operation_id = null, operation_kind = null, operation_reason = null,
         operation_request_id = null, operation_actor_user_id = null,
         operation_started_at = null, operation_prior_status = null
   where id = p_booking_id;
  update public.booking_reconciliation_cases
     set state = 'closed_no_change', resolution_outcome = 'supplier_truth_unchanged',
         resolution = jsonb_build_object(
           'version', 2, 'evidenceContract', 'canonical_supplier_evidence_v2',
           'observationId', p_observation_id, 'authoritativeFor', v_truth,
           'statusMutation', false, 'walletMutation', false),
         resolution_reason =
           'Fresh canonical V2 supplier evidence confirms existing terminal and financial truth',
         resolved_by_user_id = 'system:evidence-v2-no-change',
         resolved_at = clock_timestamp(), closed_at = clock_timestamp(),
         version = version + 1
   where id = p_case_id;
  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id, outcome, metadata
  ) values (
    'system:evidence-v2-no-change', 'system',
    'booking.reconciliation.closed_no_change_v2', 'flight_booking',
    p_booking_id::text, 'succeeded', jsonb_build_object(
      'caseId', p_case_id, 'operationId', v_operation.id,
      'observationId', p_observation_id, 'authoritativeFor', v_truth,
      'statusMutation', false, 'walletMutation', false)
  );
  return jsonb_build_object(
    'ok', true, 'replay', false, 'caseId', p_case_id,
    'operationId', v_operation.id, 'observationId', p_observation_id,
    'closedNoChange', true, 'statusMutation', false, 'walletMutation', false
  );
end;
$$;

revoke all on function public.close_booking_reconciliation_no_change_v2(uuid, uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.close_booking_reconciliation_no_change_v2(uuid, uuid, uuid)
  to service_role;

create or replace function public.close_booking_ticketing_race_no_change_v2(
  p_booking_id uuid,
  p_case_id uuid,
  p_observation_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_operation public.booking_operations;
  v_case public.booking_reconciliation_cases;
  v_reservation public.wallet_reservations;
  v_operation_id uuid;
begin
  if p_booking_id is null or p_case_id is null or p_observation_id is null then
    raise exception 'invalid V2 ticketing-race closure request' using errcode = '22023';
  end if;
  select operation_id into v_operation_id from public.booking_reconciliation_cases
   where id = p_case_id and subject_booking_id = p_booking_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_FOUND'); end if;
  select * into v_booking from public.flight_bookings where id = p_booking_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND'); end if;
  if v_operation_id is not null then
    select * into v_operation from public.booking_operations
     where id = v_operation_id and booking_id = p_booking_id for update;
  end if;
  select * into v_case from public.booking_reconciliation_cases
   where id = p_case_id and subject_booking_id = p_booking_id for update;
  if v_case.state = 'closed_no_change'
     and v_case.resolution_outcome = 'supplier_truth_unchanged'
     and v_case.resolution->>'observationId' = p_observation_id::text then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'caseId', p_case_id,
      'observationId', p_observation_id, 'closedNoChange', true,
      'statusMutation', false, 'walletMutation', false);
  end if;
  if v_case.state not in (
    'open', 'assigned', 'awaiting_supplier', 'awaiting_finance', 'awaiting_approval'
  ) then return jsonb_build_object('ok', false, 'code', 'CASE_NOT_OPEN'); end if;
  select * into v_reservation from public.wallet_reservations
   where booking_id = p_booking_id for update;
  if v_case.case_type <> 'ticketing_uncertainty'
     or v_case.reason_code <> 'pnr_sync_conflicts_with_local_truth'
     or v_case.opened_source <> 'supplier_sync'
     or v_case.proposed_outcome is not null
     or v_case.financial_disposition <> 'none'
     or v_case.operation_id is null or v_operation.id is null
     or v_operation.kind <> 'ticketing' or v_operation.state <> 'succeeded'
     or v_operation.completed_at is null
     or v_case.opened_at < v_operation.claimed_at - interval '1 minute'
     or v_case.opened_at > v_operation.completed_at + interval '1 minute'
     or v_booking.active_operation_id is not null
     or v_booking.status <> 'confirmed'
     or exists (
       select 1 from public.booking_reconciliation_cases other_case
        where other_case.subject_booking_id = p_booking_id and other_case.id <> p_case_id
          and other_case.state in (
            'open', 'assigned', 'awaiting_supplier', 'awaiting_finance', 'awaiting_approval'
          )
     ) then
    return jsonb_build_object('ok', false, 'code', 'TICKETING_RACE_CLOSURE_NOT_ELIGIBLE');
  end if;
  if not public.booking_reconciliation_evidence_v2_authoritative(
    p_booking_id, p_case_id, p_observation_id, 'ticketed'
  ) then return jsonb_build_object('ok', false, 'code', 'EVIDENCE_NOT_AUTHORITATIVE'); end if;
  if not (
    v_booking.payment_state = 'captured' and v_booking.captured_amount > 0
    and v_booking.refunded_amount = 0
    and v_booking.payment_amount = v_booking.captured_amount
    and v_reservation.id is not null and v_reservation.state = 'captured'
    and v_reservation.amount = v_booking.captured_amount
    and v_reservation.currency = v_booking.currency
  ) then return jsonb_build_object('ok', false, 'code', 'FINANCIAL_CONFLICT'); end if;
  update public.booking_reconciliation_cases
     set state = 'closed_no_change', resolution_outcome = 'supplier_truth_unchanged',
         resolution = jsonb_build_object(
           'version', 2, 'evidenceContract', 'canonical_supplier_evidence_v2',
           'observationId', p_observation_id, 'authoritativeFor', 'ticketed',
           'closureKind', 'ticketing_operation_window_race',
           'statusMutation', false, 'walletMutation', false),
         resolution_reason =
           'Fresh canonical V2 supplier evidence confirms the issued ticket, complete identity, and already-captured financial state',
         resolved_by_user_id = 'system:post-ticketing-evidence-v2',
         resolved_at = clock_timestamp(), closed_at = clock_timestamp(),
         version = version + 1
   where id = p_case_id;
  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id, outcome, metadata
  ) values (
    'system:post-ticketing-evidence-v2', 'system',
    'booking.reconciliation.ticketing_race_closed_no_change_v2',
    'flight_booking', p_booking_id::text, 'succeeded', jsonb_build_object(
      'caseId', p_case_id, 'operationId', v_operation.id,
      'observationId', p_observation_id, 'authoritativeFor', 'ticketed',
      'statusMutation', false, 'walletMutation', false)
  );
  return jsonb_build_object(
    'ok', true, 'replay', false, 'caseId', p_case_id,
    'operationId', v_operation.id, 'observationId', p_observation_id,
    'closedNoChange', true, 'statusMutation', false, 'walletMutation', false
  );
end;
$$;

revoke all on function public.close_booking_ticketing_race_no_change_v2(uuid, uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.close_booking_ticketing_race_no_change_v2(uuid, uuid, uuid)
  to service_role;

create or replace function public.resolve_booking_reconciliation_ticketed_v2(
  p_booking_id uuid,
  p_case_id uuid,
  p_expected_case_version integer,
  p_proposal_hash text,
  p_actor_user_id text,
  p_execution_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_contract jsonb;
  v_booking public.flight_bookings;
  v_case public.booking_reconciliation_cases;
  v_operation public.booking_operations;
  v_reservation public.wallet_reservations;
  v_account public.wallet_accounts;
  v_evidence public.booking_reconciliation_observations;
  v_ticket_numbers jsonb;
  v_supplier_pnr text;
  v_airlines_pnr jsonb;
  v_supplier_status text;
  v_issued_at timestamptz;
  v_supplier_unique_trans_id text;
  v_supplier_internal_booking_id text;
  v_supplier_identifiers jsonb;
  v_available_before bigint;
  v_hold_before bigint;
  v_ledger_entry_id uuid;
  v_event_id bigint;
  v_occurrence_number integer;
  v_from_lifecycle text;
  v_resolution_result jsonb;
begin
  v_contract := public.booking_reconciliation_resolution_contract_v1(
    p_booking_id, p_case_id, p_expected_case_version, p_proposal_hash,
    p_actor_user_id, p_execution_request_key, 'ticketed'
  );
  if coalesce((v_contract->>'ok')::boolean, false) is not true
     or coalesce((v_contract->>'replay')::boolean, false) then
    return v_contract;
  end if;
  select * into strict v_booking from public.flight_bookings where id = p_booking_id;
  select * into strict v_case from public.booking_reconciliation_cases where id = p_case_id;
  if v_case.financial_disposition <> 'capture_existing_hold' then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_DISPOSITION_REQUIRED');
  end if;
  if v_booking.status not in ('on-hold', 'pending', 'in-progress') then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_STATUS_NOT_TICKETABLE');
  end if;
  if v_booking.payment_state not in ('held', 'reconciliation')
     or v_booking.captured_amount <> 0 or v_booking.refunded_amount <> 0 then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_PAYMENT_NOT_CAPTURABLE');
  end if;
  if v_case.operation_id is not null then
    select * into v_operation from public.booking_operations where id = v_case.operation_id;
    if v_operation.state <> 'needs_reconciliation' then
      return jsonb_build_object('ok', false, 'code', 'OPERATION_NOT_RECONCILING');
    end if;
  end if;
  select * into v_reservation from public.wallet_reservations
   where id = (v_contract->>'reservationId')::uuid;
  if not found or v_reservation.state not in ('active', 'reconciliation')
     or v_reservation.booking_id is distinct from p_booking_id
     or v_reservation.amount <= 0 then
    return jsonb_build_object('ok', false, 'code', 'PROTECTED_HOLD_REQUIRED');
  end if;
  select * into v_account from public.wallet_accounts
   where id = v_reservation.wallet_account_id;
  if not found
     or v_account.id is distinct from (v_contract->>'walletAccountId')::uuid
     or v_account.currency <> v_reservation.currency
     or v_booking.currency <> v_reservation.currency
     or (v_booking.payment_amount is not null
       and v_booking.payment_amount <> v_reservation.amount)
     or (v_booking.charged_wallet_account_id is not null
       and v_booking.charged_wallet_account_id <> v_account.id) then
    return jsonb_build_object('ok', false, 'code', 'CAPTURE_IDENTITY_MISMATCH');
  end if;
  if v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'HOLD_BALANCE_MISMATCH');
  end if;

  select observation.* into v_evidence
    from jsonb_array_elements_text(v_case.proposal->'evidenceObservationIds') evidence_id(id)
    join public.booking_reconciliation_observations observation
      on observation.id = evidence_id.id::uuid
     and observation.reconciliation_case_id = v_case.id
   where observation.normalized_facts->>'version' = '2'
     and observation.normalized_facts->>'evidenceContract' = 'canonical_supplier_evidence_v2'
     and observation.normalized_facts->>'requestedPurpose' = 'ticketed'
     and observation.normalized_facts #>> '{validation,authoritativeFor}' = 'ticketed'
   order by observation.observed_at desc, observation.id desc limit 1;
  if not found or not public.booking_reconciliation_evidence_v2_authoritative(
    p_booking_id, p_case_id, v_evidence.id, 'ticketed'
  ) then
    return jsonb_build_object('ok', false, 'code', 'AUTHORITATIVE_TICKET_EVIDENCE_REQUIRED');
  end if;

  v_supplier_unique_trans_id := v_evidence.normalized_facts
    #>> '{evidence,ticketReport,bookingIdentity,transactionId}';
  v_supplier_internal_booking_id := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,ticketReport,bookingIdentity,supplierBookingId}'), '');
  if v_supplier_unique_trans_id is distinct from
       (v_booking.supplier_refs->>'uniqueTransId')
     or v_supplier_internal_booking_id is null then
    return jsonb_build_object('ok', false, 'code', 'SUPPLIER_BOOKING_IDENTITY_MISMATCH');
  end if;
  select coalesce(jsonb_agg(to_jsonb(ticket.value->>'fullNumber')), '[]'::jsonb)
    into v_ticket_numbers
    from jsonb_array_elements(coalesce(
      v_evidence.normalized_facts #> '{evidence,ticketReport,tickets}', '[]'::jsonb
    )) ticket(value)
   where jsonb_typeof(ticket.value) = 'object'
     and nullif(btrim(ticket.value->>'fullNumber'), '') is not null;
  if jsonb_array_length(v_ticket_numbers) = 0
     or jsonb_array_length(v_ticket_numbers) <>
       jsonb_array_length(coalesce(
         v_evidence.normalized_facts #> '{evidence,ticketReport,passengers}', '[]'::jsonb
       )) then
    return jsonb_build_object('ok', false, 'code', 'TICKET_EVIDENCE_INCOMPLETE');
  end if;
  v_supplier_pnr := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,ticketReport,bookingIdentity,supplierPnr}'), '');
  v_airlines_pnr := v_evidence.normalized_facts
    #> '{evidence,ticketReport,bookingIdentity,airlinePnrs}';
  v_supplier_status := nullif(btrim(v_evidence.normalized_facts
    #>> '{evidence,ticketReport,lifecycle,rawStatus}'), '');
  begin
    v_issued_at := nullif(v_evidence.normalized_facts
      #>> '{evidence,ticketReport,lifecycle,issuedAt}', '')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ISSUED_TIMESTAMP');
  end;
  if v_issued_at is null or v_issued_at > v_evidence.observed_at + interval '1 minute' then
    return jsonb_build_object('ok', false, 'code', 'ISSUED_TIMESTAMP_REQUIRED');
  end if;
  v_supplier_identifiers := jsonb_build_object(
    'evidenceContract', 'canonical_supplier_evidence_v2',
    'supplierAccount', v_booking.supplier_account,
    'supplierUniqueTransId', v_supplier_unique_trans_id,
    'supplierInternalBookingId', v_supplier_internal_booking_id,
    'supplierPnr', v_supplier_pnr,
    'bookingReference', v_evidence.normalized_facts
      #>> '{evidence,ticketReport,bookingIdentity,bookingReference}'
  );

  if exists (
    select 1 from public.wallet_ledger_entries
     where idempotency_key = p_execution_request_key || ':capture'
  ) then return jsonb_build_object('ok', false, 'code', 'CAPTURE_IDEMPOTENCY_CONFLICT'); end if;
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts set hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;
  update public.wallet_reservations
     set booking_id = p_booking_id, booking_attempt_id = null, state = 'captured',
         issued_by_user_id = p_actor_user_id, captured_at = clock_timestamp(),
         reconciliation_at = null, reconciliation_reason = null
   where id = v_reservation.id;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, booking_reference, reservation_id, idempotency_key,
    created_by_user_id, created_by_role, remarks, metadata
  ) values (
    v_account.id, 'booking_confirm', v_reservation.amount, v_reservation.currency,
    v_available_before, v_available_before, v_hold_before,
    v_hold_before - v_reservation.amount, v_booking.id, v_booking.public_ref,
    v_reservation.id, p_execution_request_key || ':capture', p_actor_user_id,
    v_contract->>'actorRole', 'Approved canonical V2 ticketing reconciliation capture',
    jsonb_build_object(
      'reconciliationCaseId', v_case.id, 'proposalHash', v_case.proposal_hash,
      'operationId', v_case.operation_id, 'evidenceObservationId', v_evidence.id,
      'resolutionKind', 'ticketed', 'supplierIdentifiers', v_supplier_identifiers)
  ) returning id into v_ledger_entry_id;

  v_from_lifecycle := public.resolve_booking_lifecycle(
    v_booking.status, v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at, v_booking.operation_kind
  );
  update public.flight_bookings
     set status = 'confirmed', charged_wallet_account_id = v_account.id,
         payment_state = 'captured', payment_amount = v_reservation.amount,
         captured_amount = v_reservation.amount, refunded_amount = 0,
         issued_by_user_id = p_actor_user_id,
         -- A later report can never overwrite an already accepted authoritative instant.
         issued_at = coalesce(issued_at, v_issued_at),
         pnr = coalesce(v_supplier_pnr, pnr),
         airlines_pnr = case when jsonb_typeof(v_airlines_pnr) = 'array'
           and jsonb_array_length(v_airlines_pnr) > 0 then v_airlines_pnr
           else airlines_pnr end,
         supplier_refs = v_booking.supplier_refs,
         ticketing_deadline_at = v_booking.ticketing_deadline_at,
         booking_status = coalesce(v_supplier_status, 'Confirmed'),
         -- ticketCodeRef is opaque workflow metadata, not ticket identity.
         ticket_code_ref = v_booking.ticket_code_ref,
         ticket_numbers = v_ticket_numbers,
         active_operation_id = null, operation_kind = null,
         operation_reason = null, operation_request_id = null,
         operation_actor_user_id = null, operation_started_at = null,
         operation_prior_status = null
   where id = v_booking.id;
  if v_case.operation_id is not null then
    update public.booking_operations
       set state = 'succeeded', completed_at = clock_timestamp(),
           error_code = null, error_message = null,
           supplier_evidence = coalesce(supplier_evidence, '{}'::jsonb) ||
             jsonb_build_object('canonicalV2ReconciliationResolution', jsonb_build_object(
               'caseId', v_case.id, 'outcome', 'ticketed',
               'evidenceObservationId', v_evidence.id,
               'supplierIdentifiers', v_supplier_identifiers))
     where id = v_case.operation_id;
  end if;
  select count(*)::integer + 1 into v_occurrence_number
    from public.booking_status_events
   where booking_id = v_booking.id and to_lifecycle_status = 'confirmed';
  insert into public.booking_status_events (
    booking_id, from_lifecycle_status, to_lifecycle_status,
    stored_status_before, stored_status_after, operation_kind,
    operation_reason, actor_user_id, supplier_operation,
    supplier_evidence, idempotency_key, operation_id,
    reconciliation_case_id, occurrence_number,
    effective_at, observed_at, event_snapshot, event_version
  ) values (
    v_booking.id, v_from_lifecycle, 'confirmed', v_booking.status, 'confirmed',
    v_booking.operation_kind, v_booking.operation_reason, p_actor_user_id,
    'ReconciliationTicketedV2', jsonb_build_object(
      'evidenceObservationId', v_evidence.id,
      'ticketCount', jsonb_array_length(v_ticket_numbers),
      'supplierIdentifiers', v_supplier_identifiers),
    p_execution_request_key || ':confirmed', v_case.operation_id,
    v_case.id, v_occurrence_number, v_issued_at, clock_timestamp(),
    jsonb_build_object(
      'version', 2, 'evidenceContract', 'canonical_supplier_evidence_v2',
      'bookingReference', v_booking.public_ref, 'lifecycleStatus', 'confirmed',
      'paymentState', 'captured', 'ticketCount', jsonb_array_length(v_ticket_numbers),
      'operationKind', coalesce(v_booking.operation_kind, 'reconciliation'),
      'reconciliationCaseId', v_case.id,
      'supplierIdentifiers', v_supplier_identifiers), 1
  ) returning id into v_event_id;
  v_resolution_result := jsonb_build_object(
    'bookingStatus', 'confirmed', 'paymentState', 'captured',
    'reservationId', v_reservation.id, 'walletAccountId', v_account.id,
    'ledgerEntryId', v_ledger_entry_id, 'lifecycleEventId', v_event_id,
    'capturedAmount', v_reservation.amount, 'currency', v_reservation.currency,
    'availableBalance', v_available_before,
    'holdBalance', v_hold_before - v_reservation.amount,
    'supplierUniqueTransId', v_supplier_unique_trans_id,
    'supplierInternalBookingId', v_supplier_internal_booking_id,
    'supplierIdentifiers', v_supplier_identifiers
  );
  update public.booking_reconciliation_cases
     set state = 'resolved', resolution_outcome = 'ticketed',
         resolution = jsonb_build_object(
           'version', 2, 'evidenceContract', 'canonical_supplier_evidence_v2',
           'executionRequestKey', p_execution_request_key,
           'proposalHash', v_case.proposal_hash, 'resolutionKind', 'ticketed',
           'executedByRole', v_contract->>'actorRole',
           'evidenceObservationIds', v_case.proposal->'evidenceObservationIds',
           'supplierIdentifiers', v_supplier_identifiers,
           'result', v_resolution_result),
         resolution_reason = v_case.proposal->>'reason',
         resolved_by_user_id = p_actor_user_id,
         resolved_at = clock_timestamp(), closed_at = clock_timestamp(),
         version = version + 1
   where id = v_case.id;
  return v_resolution_result || jsonb_build_object(
    'ok', true, 'replay', false, 'caseId', v_case.id,
    'caseVersion', v_case.version + 1, 'resolutionKind', 'ticketed'
  );
end;
$$;

revoke all on function public.resolve_booking_reconciliation_ticketed_v2(
  uuid, uuid, integer, text, text, text
) from public, anon, authenticated;
grant execute on function public.resolve_booking_reconciliation_ticketed_v2(
  uuid, uuid, integer, text, text, text
) to service_role;

comment on function public.resolve_booking_reconciliation_ticketed_v2(
  uuid, uuid, integer, text, text, text
) is
  'Supplier-neutral V2 ticketed resolver. It accepts only fresh canonical evidence and performs the existing approved, idempotent protected-hold capture.';


-- SOURCE: 0117_booking_user_visibility.sql
-- Staff-controlled B2B booking visibility.
--
-- This is intentionally independent of booking lifecycle and accounting. A
-- hidden booking remains available to every internal worker and staff query;
-- only customer/B2B application readers apply the visibility flag.

alter table public.flight_bookings
  add column if not exists hidden_from_user boolean not null default false,
  add column if not exists hidden_by_user_id text,
  add column if not exists hidden_at timestamptz,
  add column if not exists hidden_reason text;

alter table public.flight_bookings
  drop constraint if exists flight_bookings_user_visibility_consistency;
alter table public.flight_bookings
  add constraint flight_bookings_user_visibility_consistency
  check (
    (
      hidden_from_user
      and hidden_at is not null
      and nullif(btrim(hidden_by_user_id), '') is not null
      and char_length(hidden_by_user_id) <= 255
      and char_length(btrim(hidden_reason)) between 3 and 1000
    )
    or
    (
      not hidden_from_user
      and hidden_at is null
      and hidden_by_user_id is null
      and hidden_reason is null
    )
  );

comment on column public.flight_bookings.hidden_from_user is
  'Visibility-only flag for normal B2B/customer reads. It never changes lifecycle, supplier, or wallet processing.';
comment on column public.flight_bookings.hidden_by_user_id is
  'Staff user who most recently hid the booking; cleared on restore while the immutable event remains.';
comment on column public.flight_bookings.hidden_at is
  'Time the current hidden state began; cleared on restore.';
comment on column public.flight_bookings.hidden_reason is
  'Reason for the current hidden state; immutable history is retained in booking_user_visibility_events.';

create index if not exists flight_bookings_visible_agency_created_idx
  on public.flight_bookings (agency_code, created_at desc)
  where not legacy_operational and not hidden_from_user;

create table if not exists public.booking_user_visibility_events (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.flight_bookings (id) on delete restrict,
  request_key text not null unique
    check (char_length(request_key) between 1 and 220),
  action text not null check (action in ('hide', 'unhide')),
  hidden_after boolean not null,
  actor_user_id text not null
    check (char_length(actor_user_id) between 1 and 255),
  actor_role text not null
    check (actor_role in ('superadmin', 'admin', 'staff_support')),
  reason text not null check (char_length(btrim(reason)) between 3 and 1000),
  effective_status text not null
    check (effective_status in (
      'pending', 'on-hold', 'in-progress', 'confirmed', 'cancelled',
      'expired', 'unconfirmed'
    )),
  eligibility_snapshot jsonb not null default '{}'::jsonb
    check (jsonb_typeof(eligibility_snapshot) = 'object'),
  result jsonb not null check (jsonb_typeof(result) = 'object'),
  created_at timestamptz not null default clock_timestamp()
);

create index if not exists booking_user_visibility_events_booking_created_idx
  on public.booking_user_visibility_events (booking_id, created_at desc);

create or replace function public.deny_booking_user_visibility_event_mutation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'booking user visibility events are immutable'
    using errcode = '55000';
end;
$$;

drop trigger if exists booking_user_visibility_events_immutable_v1
  on public.booking_user_visibility_events;
create trigger booking_user_visibility_events_immutable_v1
  before update or delete on public.booking_user_visibility_events
  for each row execute function public.deny_booking_user_visibility_event_mutation_v1();

alter table public.booking_user_visibility_events enable row level security;
revoke all on table public.booking_user_visibility_events
  from public, anon, authenticated;
grant select, insert on table public.booking_user_visibility_events
  to service_role;

comment on table public.booking_user_visibility_events is
  'Immutable audit trail for hiding and restoring B2B bookings in normal user-facing reads.';

-- One authoritative eligibility classifier is shared by the UI preview and
-- the locked mutation. It fails closed on either wallet records or stale
-- denormalized financial markers.
create or replace function public.booking_user_hide_eligibility_v1(
  p_booking_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_effective_status text;
  v_reservation_count integer := 0;
  v_ledger_count integer := 0;
  v_summary_clean boolean := false;
  v_eligible boolean := false;
  v_code text;
begin
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  v_effective_status := public.resolve_booking_lifecycle(
    v_booking.status,
    v_booking.airlines_pnr,
    v_booking.ticketing_deadline_at,
    v_booking.operation_kind
  );

  select count(*)::integer into v_reservation_count
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
      or reservation.booking_attempt_id = v_booking.attempt_id;

  select count(*)::integer into v_ledger_count
    from public.wallet_ledger_entries ledger
   where ledger.booking_id = v_booking.id
      or ledger.booking_reference = v_booking.public_ref
      or exists (
        select 1
          from public.wallet_reservations reservation
         where reservation.id = ledger.reservation_id
           and (
             reservation.booking_id = v_booking.id
             or reservation.booking_attempt_id = v_booking.attempt_id
           )
      );

  v_summary_clean :=
    v_booking.payment_state = 'unpaid'
    and v_booking.payment_amount is null
    and coalesce(v_booking.captured_amount, 0) = 0
    and coalesce(v_booking.refunded_amount, 0) = 0
    and v_booking.charged_wallet_account_id is null;

  if v_booking.legacy_operational
     or v_booking.audience <> 'agency'
     or v_booking.booking_owner_type <> 'agency'
     or nullif(btrim(v_booking.agency_code), '') is null then
    v_code := 'NOT_B2B_BOOKING';
  elsif v_effective_status not in ('on-hold', 'cancelled', 'expired') then
    v_code := 'STATUS_NOT_ELIGIBLE';
  elsif v_reservation_count > 0 or v_ledger_count > 0 then
    v_code := 'WALLET_FOOTPRINT_FOUND';
  elsif not v_summary_clean then
    v_code := 'FINANCIAL_SUMMARY_NOT_CLEAN';
  else
    v_eligible := true;
    v_code := 'ELIGIBLE';
  end if;

  return jsonb_build_object(
    'ok', true,
    'code', v_code,
    'bookingId', v_booking.id,
    'bookingReference', v_booking.public_ref,
    'hiddenFromUser', v_booking.hidden_from_user,
    'hiddenByUserId', v_booking.hidden_by_user_id,
    'hiddenAt', v_booking.hidden_at,
    'hiddenReason', v_booking.hidden_reason,
    'effectiveStatus', v_effective_status,
    'eligibleToHide', v_eligible,
    'reservationCount', v_reservation_count,
    'ledgerCount', v_ledger_count,
    'financialSummaryClean', v_summary_clean
  );
end;
$$;

create or replace function public.booking_user_visibility_context_v1(
  p_booking_id uuid,
  p_actor_user_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_context jsonb;
  v_last_event public.booking_user_visibility_events;
begin
  select user_row.role into v_actor_role
    from public.app_users user_row
   where user_row.clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'VISIBILITY_FORBIDDEN');
  end if;

  v_context := public.booking_user_hide_eligibility_v1(p_booking_id);
  if coalesce((v_context->>'ok')::boolean, false) = false then
    return v_context;
  end if;

  select event.* into v_last_event
    from public.booking_user_visibility_events event
   where event.booking_id = p_booking_id
   order by event.created_at desc, event.id desc
   limit 1;

  return v_context || jsonb_build_object(
    'canManage', true,
    'lastAction', v_last_event.action,
    'lastActionAt', v_last_event.created_at,
    'lastActionByUserId', v_last_event.actor_user_id,
    'lastActionReason', v_last_event.reason
  );
end;
$$;

create or replace function public.set_booking_user_visibility_v1(
  p_booking_reference text,
  p_action text,
  p_reason text,
  p_actor_user_id text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_booking public.flight_bookings;
  v_attempt public.booking_attempts;
  v_existing public.booking_user_visibility_events;
  v_eligibility jsonb;
  v_effective_status text;
  v_result jsonb;
  v_hidden_after boolean;
  v_suppressed_outboxes integer := 0;
begin
  if p_action not in ('hide', 'unhide')
     or nullif(btrim(p_booking_reference), '') is null
     or nullif(btrim(p_actor_user_id), '') is null
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 220
     or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1000 then
    return jsonb_build_object('ok', false, 'code', 'INVALID_VISIBILITY_REQUEST');
  end if;

  select user_row.role into v_actor_role
    from public.app_users user_row
   where user_row.clerk_id = p_actor_user_id;
  if v_actor_role is null
     or v_actor_role not in ('superadmin', 'admin', 'staff_support') then
    return jsonb_build_object('ok', false, 'code', 'VISIBILITY_FORBIDDEN');
  end if;

  -- Serialize replay detection too: two deliveries of the same command must
  -- converge on one immutable event rather than racing the unique constraint.
  perform pg_advisory_xact_lock(
    hashtextextended('booking-user-visibility:' || p_request_key, 0)
  );

  select event.* into v_existing
    from public.booking_user_visibility_events event
   where event.request_key = p_request_key;
  if found then
    if v_existing.actor_user_id <> p_actor_user_id
       or v_existing.action <> p_action
       or v_existing.reason <> btrim(p_reason)
       or not exists (
         select 1 from public.flight_bookings booking
          where booking.id = v_existing.booking_id
            and booking.public_ref = btrim(p_booking_reference)
       ) then
      return jsonb_build_object('ok', false, 'code', 'REQUEST_KEY_REUSED');
    end if;
    return v_existing.result || jsonb_build_object('replay', true);
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.public_ref = btrim(p_booking_reference)
     and not booking.legacy_operational
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  -- Lock the attempt as well as all related reservation rows. Existing wallet
  -- functions use these foreign-key subjects, so the eligibility snapshot and
  -- state change are serialized with normal booking finance operations.
  select attempt.* into v_attempt
    from public.booking_attempts attempt
   where attempt.id = v_booking.attempt_id
   for update;

  perform 1
    from public.wallet_reservations reservation
   where reservation.booking_id = v_booking.id
      or reservation.booking_attempt_id = v_booking.attempt_id
   for update;

  v_eligibility := public.booking_user_hide_eligibility_v1(v_booking.id);
  v_effective_status := v_eligibility->>'effectiveStatus';

  if p_action = 'hide' then
    if v_booking.hidden_from_user then
      return jsonb_build_object(
        'ok', false, 'code', 'ALREADY_HIDDEN',
        'hiddenFromUser', true
      );
    end if;
    if coalesce((v_eligibility->>'eligibleToHide')::boolean, false) = false then
      return jsonb_build_object(
        'ok', false,
        'code', coalesce(v_eligibility->>'code', 'NOT_ELIGIBLE'),
        'context', v_eligibility
      );
    end if;

    -- Serialize with recipient claiming. Once a visible delivery has entered
    -- its external send window, hiding waits for that attempt to finish rather
    -- than claiming success while an email may still leave the process.
    perform 1
      from public.booking_notification_outbox outbox
     where outbox.booking_id = v_booking.id
       and outbox.state in ('pending', 'processing')
     order by outbox.id
     for update;
    if exists (
      select 1
        from public.booking_notification_deliveries delivery
        join public.booking_notification_outbox outbox
          on outbox.id = delivery.outbox_id
       where outbox.booking_id = v_booking.id
         and delivery.state = 'processing'
         and not delivery.is_hidden_copy
    ) then
      return jsonb_build_object(
        'ok', false,
        'code', 'NOTIFICATION_DELIVERY_IN_PROGRESS'
      );
    end if;

    update public.flight_bookings
       set hidden_from_user = true,
           hidden_by_user_id = p_actor_user_id,
           hidden_at = clock_timestamp(),
           hidden_reason = btrim(p_reason)
     where id = v_booking.id;

    update public.booking_notification_deliveries delivery
       set state = 'suppressed',
           suppression_reason = 'booking_hidden_from_user',
           completed_at = clock_timestamp(),
           claimed_at = null,
           claim_token = null,
           last_error = null
      from public.booking_notification_outbox outbox
     where outbox.id = delivery.outbox_id
       and outbox.booking_id = v_booking.id
       and delivery.state in ('pending', 'retry', 'failed')
       and not delivery.is_hidden_copy;

    update public.booking_notification_outbox outbox
       set state = 'suppressed',
           delivery_policy = 'suppress',
           suppression_reason = 'booking_hidden_from_user',
           completed_at = clock_timestamp(),
           claimed_at = null,
           claim_token = null,
           last_error = null
     where outbox.booking_id = v_booking.id
       and outbox.state in ('pending', 'processing');
    get diagnostics v_suppressed_outboxes = row_count;
    v_hidden_after := true;
  else
    if not v_booking.hidden_from_user then
      return jsonb_build_object(
        'ok', false, 'code', 'ALREADY_VISIBLE',
        'hiddenFromUser', false
      );
    end if;
    update public.flight_bookings
       set hidden_from_user = false,
           hidden_by_user_id = null,
           hidden_at = null,
           hidden_reason = null
     where id = v_booking.id;
    v_hidden_after := false;
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'replay', false,
    'bookingId', v_booking.id,
    'bookingReference', v_booking.public_ref,
    'action', p_action,
    'hiddenFromUser', v_hidden_after,
    'effectiveStatus', v_effective_status,
    'suppressedNotificationOutboxes', v_suppressed_outboxes
  );

  insert into public.booking_user_visibility_events (
    booking_id, request_key, action, hidden_after, actor_user_id,
    actor_role, reason, effective_status, eligibility_snapshot, result
  ) values (
    v_booking.id, p_request_key, p_action, v_hidden_after, p_actor_user_id,
    v_actor_role, btrim(p_reason), v_effective_status, v_eligibility, v_result
  );

  insert into public.security_audit_events (
    actor_user_id, actor_role, action, target_type, target_id,
    outcome, metadata
  ) values (
    p_actor_user_id, v_actor_role,
    case when p_action = 'hide'
      then 'flight_booking.hide_from_user'
      else 'flight_booking.restore_to_user'
    end,
    'flight_booking', v_booking.id::text, 'succeeded',
    jsonb_build_object(
      'requestKey', p_request_key,
      'bookingReference', v_booking.public_ref,
      'effectiveStatus', v_effective_status,
      'hiddenAfter', v_hidden_after,
      'suppressedNotificationOutboxes', v_suppressed_outboxes,
      'walletMutation', false,
      'supplierMutation', false,
      'lifecycleMutation', false
    )
  );

  return v_result;
end;
$$;

-- Terminally suppresses one already-created occurrence when its booking is
-- hidden. The event and outbox row remain durable; Restore never requeues it.
create or replace function public.suppress_claimed_booking_notification_for_hidden_user_v1(
  p_outbox_id uuid,
  p_claim_token uuid
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking_id uuid;
  v_booking public.flight_bookings;
  v_outbox public.booking_notification_outbox;
begin
  select outbox.booking_id into v_booking_id
    from public.booking_notification_outbox outbox
   where outbox.id = p_outbox_id;
  if not found then return false; end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = v_booking_id
   for update;
  if not found
     or v_booking.audience <> 'agency'
     or not v_booking.hidden_from_user then
    return false;
  end if;

  select outbox.* into v_outbox
    from public.booking_notification_outbox outbox
   where outbox.id = p_outbox_id
   for update;
  if v_outbox.state = 'suppressed'
     and v_outbox.suppression_reason = 'booking_hidden_from_user' then
    return true;
  end if;
  if v_outbox.state <> 'processing'
     or v_outbox.claim_token is distinct from p_claim_token then
    return false;
  end if;

  update public.booking_notification_deliveries delivery
     set state = 'suppressed',
         suppression_reason = 'booking_hidden_from_user',
         completed_at = clock_timestamp(),
         claimed_at = null,
         claim_token = null,
         last_error = null
   where delivery.outbox_id = p_outbox_id
     and delivery.state in ('pending', 'retry', 'failed')
     and not delivery.is_hidden_copy;

  update public.booking_notification_outbox outbox
     set state = 'suppressed',
         delivery_policy = 'suppress',
         suppression_reason = 'booking_hidden_from_user',
         recipients_expanded_at = coalesce(
           outbox.recipients_expanded_at, clock_timestamp()
         ),
         completed_at = clock_timestamp(),
         claimed_at = null,
         claim_token = null,
         last_error = null
   where outbox.id = p_outbox_id;
  return true;
end;
$$;

-- An occurrence created during a hidden interval must stay suppressed even if
-- it is not claimed until after Restore. Preserve the outbox as evidence while
-- making its delivery decision terminal at creation time.
create or replace function public.suppress_hidden_booking_notification_outbox_on_insert_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_hidden boolean := false;
begin
  select booking.audience = 'agency' and booking.hidden_from_user
    into v_hidden
    from public.flight_bookings booking
   where booking.id = new.booking_id
   for key share;
  if coalesce(v_hidden, false) then
    new.delivery_policy := 'suppress';
    new.state := 'suppressed';
    new.suppression_reason := 'booking_hidden_from_user';
    new.completed_at := clock_timestamp();
    new.claimed_at := null;
    new.claim_token := null;
  end if;
  return new;
end;
$$;

drop trigger if exists booking_notification_outbox_hidden_user_suppression_v1
  on public.booking_notification_outbox;
create trigger booking_notification_outbox_hidden_user_suppression_v1
  before insert on public.booking_notification_outbox
  for each row execute function
    public.suppress_hidden_booking_notification_outbox_on_insert_v1();

-- Replace the visible-recipient claim with a booking-row-serialized version.
-- This closes the race between Hide and the start of an external email send:
-- either the delivery claim wins and Hide asks staff to retry, or Hide wins and
-- the occurrence is suppressed without returning a recipient to the worker.
create or replace function public.claim_booking_notification_deliveries_v1(
  p_outbox_id uuid,
  p_outbox_claim_token uuid,
  p_limit integer default 25
)
returns table (
  delivery_id uuid,
  recipient_kind text,
  recipient_address text,
  recipient_address_hash text,
  is_hidden_copy boolean,
  rendered_content jsonb,
  delivery_claim_token uuid,
  attempt_count integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking_id uuid;
  v_booking public.flight_bookings;
  v_outbox public.booking_notification_outbox;
begin
  select outbox.booking_id into v_booking_id
    from public.booking_notification_outbox outbox
   where outbox.id = p_outbox_id;
  if not found then
    raise exception 'notification outbox not found' using errcode = 'P0002';
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = v_booking_id
   for update;
  if not found then
    raise exception 'notification booking not found' using errcode = 'P0002';
  end if;

  select outbox.* into v_outbox
    from public.booking_notification_outbox outbox
   where outbox.id = p_outbox_id
   for update;

  if v_booking.audience = 'agency' and v_booking.hidden_from_user then
    update public.booking_notification_deliveries delivery
       set state = 'suppressed',
           suppression_reason = 'booking_hidden_from_user',
           completed_at = clock_timestamp(),
           claimed_at = null,
           claim_token = null,
           last_error = null
     where delivery.outbox_id = p_outbox_id
       and delivery.state in ('pending', 'retry', 'failed')
       and not delivery.is_hidden_copy;
    update public.booking_notification_outbox outbox
       set state = 'suppressed',
           delivery_policy = 'suppress',
           suppression_reason = 'booking_hidden_from_user',
           recipients_expanded_at = coalesce(
             outbox.recipients_expanded_at, clock_timestamp()
           ),
           completed_at = clock_timestamp(),
           claimed_at = null,
           claim_token = null,
           last_error = null
     where outbox.id = p_outbox_id;
    return;
  end if;

  if v_outbox.state <> 'processing'
     or v_outbox.claim_token is distinct from p_outbox_claim_token
     or v_outbox.recipients_expanded_at is null then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;

  return query
  with candidates as (
    select candidate.id
      from public.booking_notification_deliveries candidate
     where candidate.outbox_id = p_outbox_id
       and candidate.state in ('pending', 'retry')
       and candidate.next_attempt_at <= clock_timestamp()
       and candidate.attempt_count < candidate.max_attempts
       and not candidate.is_hidden_copy
     order by candidate.next_attempt_at, candidate.created_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 25), 100))
  ), claimed as (
    update public.booking_notification_deliveries target
       set state = 'processing',
           claimed_at = clock_timestamp(),
           claim_token = gen_random_uuid(),
           last_attempt_at = clock_timestamp(),
           attempt_count = target.attempt_count + 1,
           last_error = null
      from candidates
     where target.id = candidates.id
     returning target.*
  )
  select
    claimed.id, claimed.recipient_kind, claimed.recipient_address,
    claimed.recipient_address_hash, claimed.is_hidden_copy,
    claimed.rendered_content, claimed.claim_token, claimed.attempt_count
  from claimed
  order by claimed.created_at, claimed.id;
end;
$$;

