comment on function public.decide_ticket_management_quote_v1(
  uuid, uuid, text, text, integer, text, text
) is
  'Customer decision boundary for credit/none quotations. Debit approval remains blocked until request-scoped wallet Hold support is added.';

comment on column public.ticket_management_quotes.supplier_gross_amount is
  'Selected-ticket supplier Gross Fare audit fact. Never used to calculate customer Refund or VOID wallet amounts.';
comment on column public.ticket_management_quotes.supplier_payable_amount is
  'Selected-ticket Supplier Payable audit/economic fact. Never used as the customer entitlement base.';
comment on column public.ticket_management_quotes.user_payable_entitlement_amount is
  'Authoritative selected-ticket User Payable entitlement. Refund/VOID customer calculations and entitlement consumption use this amount.';
comment on column public.ticket_management_quotes.airline_fee is
  'Airline/supplier fee applicable to the action; deducted from User Payable for Refund and added for Reissue.';
comment on column public.ticket_management_quotes.service_fee is
  'Kaliganj Travels service fee, explicitly separate from supplier amounts and airline fees.';
comment on column public.ticket_management_quotes.customer_amount is
  'Final immutable customer wallet credit/debit approved by the customer.';


-- SOURCE: 0121_ticket_management_entitlements.sql
-- Ticket Management passenger/ticket financial entitlement protection.
--
-- Existing booking User Payable fare snapshots are expanded by passenger
-- type/count and converted directly to minor units. They must sum exactly to
-- the authoritative captured amount; proportional Gross-based scaling is
-- forbidden.
-- Bootstrap fails closed when passenger, ticket, fare, or legacy refund facts
-- cannot be proved. This migration performs no wallet movement.

create table public.ticket_management_ticket_entitlements (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null
    references public.flight_bookings(id) on delete restrict,
  predecessor_entitlement_id uuid
    references public.ticket_management_ticket_entitlements(id) on delete restrict,
  passenger_index integer not null check (passenger_index >= 0),
  passenger_snapshot jsonb not null
    check (jsonb_typeof(passenger_snapshot) = 'object'),
  passenger_name text not null
    check (char_length(btrim(passenger_name)) between 1 and 300),
  passenger_type text not null
    check (passenger_type in ('ADT', 'CHD', 'CNN', 'INF', 'INS')),
  original_ticket_number text not null
    check (char_length(btrim(original_ticket_number)) between 1 and 80),
  active_ticket_number text not null
    check (char_length(btrim(active_ticket_number)) between 1 and 80),
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  entitlement_amount bigint not null check (entitlement_amount > 0),
  consumed_amount bigint not null default 0
    check (consumed_amount >= 0 and consumed_amount <= entitlement_amount),
  user_payable_source_minor bigint not null check (user_payable_source_minor > 0),
  allocation_source text not null
    check (allocation_source in ('authoritative-user-payable', 'reissue-lineage')),
  allocation_hash text not null check (allocation_hash ~ '^[a-f0-9]{64}$'),
  state text not null default 'active'
    check (state in ('active', 'refunded', 'voided', 'reissued')),
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  constraint ticket_management_entitlement_terminal_consumption_check
    check (
      state = 'active'
      or consumed_amount = entitlement_amount
    )
);

create unique index ticket_management_root_entitlement_passenger_key
  on public.ticket_management_ticket_entitlements(booking_id, passenger_index)
  where predecessor_entitlement_id is null;
create unique index ticket_management_active_ticket_key
  on public.ticket_management_ticket_entitlements(booking_id, active_ticket_number)
  where state = 'active';
create index ticket_management_entitlements_booking_idx
  on public.ticket_management_ticket_entitlements(booking_id, passenger_index, id);

create trigger ticket_management_entitlements_touch_updated_at
  before update on public.ticket_management_ticket_entitlements
  for each row execute function public.touch_updated_at();

create table public.ticket_management_request_selections (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null
    references public.ticket_management_requests(id) on delete restrict,
  entitlement_id uuid not null
    references public.ticket_management_ticket_entitlements(id) on delete restrict,
  passenger_index integer not null check (passenger_index >= 0),
  passenger_snapshot jsonb not null
    check (jsonb_typeof(passenger_snapshot) = 'object'),
  passenger_name text not null,
  passenger_type text not null
    check (passenger_type in ('ADT', 'CHD', 'CNN', 'INF', 'INS')),
  ticket_number_snapshot text not null,
  entitlement_amount_snapshot bigint not null check (entitlement_amount_snapshot > 0),
  consumed_amount_snapshot bigint not null check (consumed_amount_snapshot >= 0),
  coupon_scope jsonb not null default '[]'::jsonb
    check (jsonb_typeof(coupon_scope) = 'array'),
  created_at timestamptz not null default clock_timestamp(),
  unique (request_id, entitlement_id),
  unique (request_id, passenger_index)
);

create index ticket_management_selections_entitlement_idx
  on public.ticket_management_request_selections(entitlement_id, request_id);

create table public.ticket_management_entitlement_claims (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null
    references public.ticket_management_requests(id) on delete restrict,
  entitlement_id uuid not null
    references public.ticket_management_ticket_entitlements(id) on delete restrict,
  state text not null default 'active'
    check (state in ('active', 'released', 'consumed')),
  claimed_at timestamptz not null default clock_timestamp(),
  released_at timestamptz,
  consumed_at timestamptz,
  release_reason text,
  unique (request_id, entitlement_id),
  constraint ticket_management_claim_timestamp_check
    check (
      (state = 'active' and released_at is null and consumed_at is null)
      or (state = 'released' and released_at is not null and consumed_at is null)
      or (state = 'consumed' and consumed_at is not null and released_at is null)
    )
);

create unique index ticket_management_one_active_entitlement_claim
  on public.ticket_management_entitlement_claims(entitlement_id)
  where state = 'active';
create index ticket_management_claims_request_idx
  on public.ticket_management_entitlement_claims(request_id, state, id);

alter table public.ticket_management_requests
  add column selection_hash text
    check (selection_hash is null or selection_hash ~ '^[a-f0-9]{64}$');

alter table public.ticket_management_quotes
  add column selection_hash text
    check (selection_hash is null or selection_hash ~ '^[a-f0-9]{64}$');

create or replace function public.prevent_ticket_management_selection_mutation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'ticket management request selections are immutable'
    using errcode = '55000';
end;
$$;

create trigger ticket_management_selections_deny_update_delete
  before update or delete on public.ticket_management_request_selections
  for each row execute function public.prevent_ticket_management_selection_mutation_v1();

create or replace function public.ticket_management_ensure_booking_entitlements_v1(
  p_booking_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_count integer;
  v_total bigint;
  v_allocation_hash text;
begin
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'BOOKING_NOT_FOUND');
  end if;

  select count(*), coalesce(sum(entitlement.entitlement_amount), 0)
    into v_count, v_total
    from public.ticket_management_ticket_entitlements entitlement
   where entitlement.booking_id = p_booking_id
     and entitlement.predecessor_entitlement_id is null;
  if v_count > 0 then
    return jsonb_build_object('ok', true, 'replay', true, 'count', v_count);
  end if;

  if v_booking.captured_amount <= 0
     or v_booking.refunded_amount <> 0
     or v_booking.import_source in ('IMP_EXP', 'MANUAL')
     or jsonb_typeof(v_booking.passengers->'travellers') <> 'array'
     or jsonb_array_length(v_booking.passengers->'travellers') = 0
     or jsonb_typeof(v_booking.ticket_numbers) <> 'array'
     or jsonb_array_length(v_booking.ticket_numbers)
          <> jsonb_array_length(v_booking.passengers->'travellers')
     or jsonb_typeof(v_booking.fares) <> 'array'
     or jsonb_array_length(v_booking.fares) = 0 then
    return jsonb_build_object('ok', false, 'code', 'AUTHORITATIVE_USER_PAYABLE_ALLOCATION_UNAVAILABLE');
  end if;
  if exists (
    select 1
      from jsonb_array_elements(v_booking.ticket_numbers) ticket(value)
     where jsonb_typeof(ticket.value) <> 'string'
        or nullif(btrim(ticket.value #>> '{}'), '') is null
        or char_length(btrim(ticket.value #>> '{}')) > 80
  ) or (
    select count(distinct upper(btrim(ticket.value #>> '{}')))
      from jsonb_array_elements(v_booking.ticket_numbers) ticket(value)
  ) <> jsonb_array_length(v_booking.ticket_numbers) then
    return jsonb_build_object('ok', false, 'code', 'ENTITLEMENT_TICKETS_UNPROVEN');
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_booking.fares) fare(value)
     where fare.value->>'passengerType' not in ('ADT', 'CHD', 'CNN', 'INF', 'INS')
        or jsonb_typeof(fare.value->'count') <> 'number'
        or (fare.value->>'count')::numeric <> trunc((fare.value->>'count')::numeric)
        or (fare.value->>'count')::integer <= 0
        or jsonb_typeof(fare.value->'totalPrice') <> 'number'
        or (fare.value->>'totalPrice')::numeric <= 0
  ) then
    return jsonb_build_object('ok', false, 'code', 'ENTITLEMENT_FARES_UNPROVEN');
  end if;

  v_allocation_hash := encode(sha256(convert_to(
    concat_ws('|', p_booking_id::text, v_booking.currency,
      v_booking.captured_amount::text,
      (v_booking.passengers->'travellers')::text,
      v_booking.ticket_numbers::text, v_booking.fares::text),
    'UTF8'
  )), 'hex');

  with traveller_base as (
    select
      traveller.ordinality::integer - 1 as passenger_index,
      traveller.value as passenger_snapshot,
      traveller.value->>'passengerType' as passenger_type,
      upper(btrim(v_booking.ticket_numbers ->> (traveller.ordinality::integer - 1)))
        as ticket_number
    from jsonb_array_elements(v_booking.passengers->'travellers')
      with ordinality traveller(value, ordinality)
  ), travellers as (
    select base.*,
      row_number() over (
        partition by base.passenger_type order by base.passenger_index
      ) - 1 as type_occurrence
    from traveller_base base
  ), fare_rows as (
    select
      fare.ordinality,
      fare.value->>'passengerType' as passenger_type,
      (fare.value->>'count')::integer as passenger_count,
      (fare.value->>'totalPrice')::numeric as total_price
    from jsonb_array_elements(v_booking.fares)
      with ordinality fare(value, ordinality)
  ), user_payable_slots as (
    select
      fare.passenger_type,
      row_number() over (
        partition by fare.passenger_type
        order by fare.ordinality, slot.number
      ) - 1 as type_occurrence,
      (fare.total_price * 100 / fare.passenger_count) as user_payable_minor
    from fare_rows fare
    cross join lateral generate_series(1, fare.passenger_count) slot(number)
  ), authoritative as (
    select traveller.*, slot.user_payable_minor
    from travellers traveller
    join user_payable_slots slot
      on slot.passenger_type = traveller.passenger_type
     and slot.type_occurrence = traveller.type_occurrence
    where slot.user_payable_minor > 0
      and slot.user_payable_minor = trunc(slot.user_payable_minor)
  )
  insert into public.ticket_management_ticket_entitlements (
    booking_id, passenger_index, passenger_snapshot, passenger_name,
    passenger_type, original_ticket_number, active_ticket_number,
    currency, entitlement_amount, user_payable_source_minor,
    allocation_source, allocation_hash
  )
  select
    p_booking_id, authoritative.passenger_index, authoritative.passenger_snapshot,
    btrim(concat_ws(' ', authoritative.passenger_snapshot->>'title',
      authoritative.passenger_snapshot->>'firstName', authoritative.passenger_snapshot->>'lastName')),
    authoritative.passenger_type, authoritative.ticket_number, authoritative.ticket_number,
    upper(v_booking.currency),
    authoritative.user_payable_minor::bigint,
    authoritative.user_payable_minor::bigint,
    'authoritative-user-payable', v_allocation_hash
  from authoritative
  order by authoritative.passenger_index;

  get diagnostics v_count = row_count;
  if v_count <> jsonb_array_length(v_booking.passengers->'travellers') then
    raise exception 'passenger fare allocation is incomplete'
      using errcode = '23514';
  end if;
  select sum(entitlement.entitlement_amount) into v_total
    from public.ticket_management_ticket_entitlements entitlement
   where entitlement.booking_id = p_booking_id
     and entitlement.predecessor_entitlement_id is null;
  if v_total <> v_booking.captured_amount then
    raise exception 'authoritative passenger User Payable does not equal captured amount'
      using errcode = '23514';
  end if;
  return jsonb_build_object('ok', true, 'replay', false, 'count', v_count);
end;
$$;

create or replace function public.create_ticket_management_request_v2(
  p_booking_id uuid,
  p_action text,
  p_actor_user_id text,
  p_request_key text,
  p_request_payload_hash text,
  p_passenger_indexes integer[],
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
  v_bootstrap jsonb;
  v_request public.ticket_management_requests;
  v_index_count integer;
  v_selected_count integer;
  v_selection_hash text;
begin
  if p_passenger_indexes is null or cardinality(p_passenger_indexes) = 0
     or exists (select 1 from unnest(p_passenger_indexes) value where value < 0)
     or cardinality(p_passenger_indexes) <>
        (select count(distinct value) from unnest(p_passenger_indexes) value) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_PASSENGER_SELECTION');
  end if;

  v_result := public.create_ticket_management_request_v1(
    p_booking_id, p_action, p_actor_user_id, p_request_key,
    p_request_payload_hash, p_note
  );
  if not coalesce((v_result->>'ok')::boolean, false) then return v_result; end if;

  select request.* into strict v_request
    from public.ticket_management_requests request
   where request.id = (v_result->>'requestId')::uuid
   for update;
  v_bootstrap := public.ticket_management_ensure_booking_entitlements_v1(p_booking_id);
  if not coalesce((v_bootstrap->>'ok')::boolean, false) then
    raise exception '%', v_bootstrap->>'code' using errcode = 'P0001';
  end if;

  select count(*) into v_index_count
    from public.ticket_management_ticket_entitlements entitlement
   where entitlement.booking_id = p_booking_id
     and entitlement.passenger_index = any(p_passenger_indexes)
     and entitlement.state = 'active'
     and entitlement.consumed_amount < entitlement.entitlement_amount;
  if v_index_count <> cardinality(p_passenger_indexes) then
    raise exception 'selected passenger entitlement is unavailable'
      using errcode = 'P0001';
  end if;

  select encode(sha256(convert_to(
      string_agg(value::text, ',' order by value), 'UTF8'
    )), 'hex')
    into v_selection_hash
    from unnest(p_passenger_indexes) value;
  select count(*) into v_selected_count
    from public.ticket_management_request_selections selection
   where selection.request_id = v_request.id;
  if v_selected_count > 0 then
    if v_request.selection_hash is distinct from v_selection_hash
       or v_selected_count <> cardinality(p_passenger_indexes) then
      return jsonb_build_object('ok', false, 'code', 'REQUEST_IDEMPOTENCY_CONFLICT');
    end if;
    return v_result || jsonb_build_object(
      'selectionHash', v_selection_hash, 'selectedPassengerCount', v_selected_count
    );
  end if;
  if exists (
    select 1
      from public.ticket_management_entitlement_claims claim
      join public.ticket_management_ticket_entitlements entitlement
        on entitlement.id = claim.entitlement_id
     where entitlement.booking_id = p_booking_id
       and entitlement.passenger_index = any(p_passenger_indexes)
       and claim.state = 'active'
  ) then
    raise exception 'selected passenger entitlement is already claimed'
      using errcode = 'P0001';
  end if;

  insert into public.ticket_management_request_selections (
    request_id, entitlement_id, passenger_index, passenger_snapshot,
    passenger_name, passenger_type, ticket_number_snapshot,
    entitlement_amount_snapshot, consumed_amount_snapshot
  )
  select
    v_request.id, entitlement.id, entitlement.passenger_index,
    entitlement.passenger_snapshot, entitlement.passenger_name,
    entitlement.passenger_type, entitlement.active_ticket_number,
    entitlement.entitlement_amount, entitlement.consumed_amount
  from public.ticket_management_ticket_entitlements entitlement
  where entitlement.booking_id = p_booking_id
    and entitlement.state = 'active'
    and entitlement.consumed_amount < entitlement.entitlement_amount
    and entitlement.passenger_index = any(p_passenger_indexes)
  order by entitlement.passenger_index;

  insert into public.ticket_management_entitlement_claims (request_id, entitlement_id)
  select selection.request_id, selection.entitlement_id
    from public.ticket_management_request_selections selection
   where selection.request_id = v_request.id;
  update public.ticket_management_requests
     set selection_hash = v_selection_hash
   where id = v_request.id;

  return v_result || jsonb_build_object(
    'selectionHash', v_selection_hash,
    'selectedPassengerCount', cardinality(p_passenger_indexes)
  );
end;
$$;

create or replace function public.ticket_management_release_terminal_claims_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status in ('rejected', 'expired')
     and old.status is distinct from new.status then
    update public.ticket_management_entitlement_claims
       set state = 'released', released_at = clock_timestamp(),
           release_reason = new.terminal_outcome
     where request_id = new.id and state = 'active';
  end if;
  return new;
end;
$$;

create trigger ticket_management_requests_release_terminal_claims
  after update of status on public.ticket_management_requests
  for each row execute function public.ticket_management_release_terminal_claims_v1();

create or replace function public.ticket_management_validate_quote_selection_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request public.ticket_management_requests;
  v_remaining bigint;
  v_count integer;
begin
  select request.* into strict v_request
    from public.ticket_management_requests request
   where request.id = new.request_id
   for update;
  if v_request.selection_hash is null then
    raise exception 'request has no frozen passenger selection' using errcode = '23514';
  end if;
  perform entitlement.id
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
   where selection.request_id = new.request_id
   order by entitlement.id
   for update of entitlement;
  select count(*), coalesce(sum(
      entitlement.entitlement_amount - entitlement.consumed_amount
    ), 0)
    into v_count, v_remaining
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
    join public.ticket_management_entitlement_claims claim
      on claim.request_id = selection.request_id
     and claim.entitlement_id = selection.entitlement_id
   where selection.request_id = new.request_id
     and entitlement.state = 'active'
     and claim.state = 'active';
  if v_count = 0 or v_count <> (
    select count(*) from public.ticket_management_request_selections selection
     where selection.request_id = new.request_id
  ) then
    raise exception 'request passenger entitlement is no longer active'
      using errcode = '23514';
  end if;
  if v_request.action in ('refund', 'void')
     and (new.user_payable_entitlement_amount <= 0
       or new.user_payable_entitlement_amount <> v_remaining) then
    raise exception 'quotation User Payable must equal selected remaining entitlement'
      using errcode = '23514';
  end if;
  if v_request.action = 'reissue'
     and new.user_payable_entitlement_amount <> 0 then
    raise exception 'reissue quotation User Payable entitlement must be zero'
      using errcode = '23514';
  end if;
  new.selection_hash := v_request.selection_hash;
  return new;
end;
$$;

create trigger ticket_management_quotes_validate_selection
  before insert on public.ticket_management_quotes
  for each row execute function public.ticket_management_validate_quote_selection_v1();

alter table public.ticket_management_ticket_entitlements enable row level security;
alter table public.ticket_management_request_selections enable row level security;
alter table public.ticket_management_entitlement_claims enable row level security;

revoke all on public.ticket_management_ticket_entitlements from public, anon, authenticated;
revoke all on public.ticket_management_request_selections from public, anon, authenticated;
revoke all on public.ticket_management_entitlement_claims from public, anon, authenticated;
grant select, insert, update on public.ticket_management_ticket_entitlements to service_role;
grant select, insert on public.ticket_management_request_selections to service_role;
grant select, insert, update on public.ticket_management_entitlement_claims to service_role;

revoke execute on function public.create_ticket_management_request_v1(
  uuid, text, text, text, text, text
) from service_role;
revoke all on function public.ticket_management_ensure_booking_entitlements_v1(uuid)
  from public, anon, authenticated, service_role;
revoke all on function public.prevent_ticket_management_selection_mutation_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.ticket_management_release_terminal_claims_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.ticket_management_validate_quote_selection_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.create_ticket_management_request_v2(
  uuid, text, text, text, text, integer[], text
) from public, anon, authenticated;
grant execute on function public.create_ticket_management_request_v2(
  uuid, text, text, text, text, integer[], text
) to service_role;

comment on function public.create_ticket_management_request_v2(
  uuid, text, text, text, text, integer[], text
) is
  'Creates an owner-authorized Ticket Management request with immutable passenger/ticket selection and an exclusive active entitlement claim. No wallet movement.';


-- SOURCE: 0122_ticket_management_wallet_substrate.sql
-- Request-scoped Ticket Management Hold/Capture/Release substrate.
--
-- This extends, but does not reuse or alter, the original booking reservation.
-- Debit quotation approval and its Hold are atomic. Final Capture/Release is
-- deliberately left to the action-specific settlement migrations.

alter table public.wallet_reservations
  add column ticket_management_request_id uuid
    references public.ticket_management_requests(id) on delete restrict;

alter table public.wallet_reservations
  drop constraint if exists wallet_reservations_check;
alter table public.wallet_reservations
  add constraint wallet_reservations_exactly_one_subject_check
  check (
    (booking_id is not null)::integer
    + (booking_attempt_id is not null)::integer
    + (ticket_management_request_id is not null)::integer = 1
  );

create unique index wallet_reservations_ticket_management_request_key
  on public.wallet_reservations(ticket_management_request_id)
  where ticket_management_request_id is not null;

alter table public.wallet_ledger_entries
  add column ticket_management_request_id uuid
    references public.ticket_management_requests(id) on delete restrict,
  add column ticket_management_quote_id uuid
    references public.ticket_management_quotes(id) on delete restrict;

alter table public.wallet_ledger_entries
  drop constraint if exists wallet_ledger_entries_transaction_type_check;
alter table public.wallet_ledger_entries
  add constraint wallet_ledger_entries_transaction_type_check
  check (transaction_type in (
    'deposit', 'booking_hold', 'booking_confirm', 'hold_release', 'refund',
    'manual_credit', 'manual_debit', 'adjustment', 'reversal',
    'superadmin_resolution_credit',
    'superadmin_resolution_debit',
    'superadmin_resolution_hold_release',
    'superadmin_resolution_hold_capture',
    'ticket_management_hold',
    'ticket_management_capture',
    'ticket_management_release',
    'ticket_management_void_credit'
  ));

create index wallet_ledger_ticket_management_request_idx
  on public.wallet_ledger_entries(ticket_management_request_id, created_at desc, id)
  where ticket_management_request_id is not null;

alter table public.ticket_management_requests
  add column active_wallet_reservation_id uuid
    references public.wallet_reservations(id) on delete restrict,
  add column hold_ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  add column capture_ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  add column release_ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  add column credit_ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  add constraint ticket_management_requests_wallet_result_check
    check (
      capture_ledger_entry_id is null or release_ledger_entry_id is null
    );

create or replace function public.decide_ticket_management_quote_v2(
  p_request_id uuid,
  p_quote_id uuid,
  p_decision text,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor public.app_users;
  v_request public.ticket_management_requests;
  v_quote public.ticket_management_quotes;
  v_existing public.ticket_management_customer_decisions;
  v_decision public.ticket_management_customer_decisions;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_reservation public.wallet_reservations;
  v_ledger public.wallet_ledger_entries;
  v_available_before bigint;
  v_hold_before bigint;
  v_version integer;
begin
  if p_decision <> 'approved' then
    return public.decide_ticket_management_quote_v1(
      p_request_id, p_quote_id, p_decision, p_actor_user_id,
      p_expected_version, p_request_key, p_note
    );
  end if;
  select quote.* into v_quote
    from public.ticket_management_quotes quote
   where quote.id = p_quote_id and quote.request_id = p_request_id;
  if not found or v_quote.direction <> 'debit' then
    return public.decide_ticket_management_quote_v1(
      p_request_id, p_quote_id, p_decision, p_actor_user_id,
      p_expected_version, p_request_key, p_note
    );
  end if;
  if p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_request_key), '') is null then
    raise exception 'invalid Ticket Management customer decision' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select decision.* into v_existing
    from public.ticket_management_customer_decisions decision
   where decision.request_key = p_request_key for update;
  if found then
    if v_existing.request_id is distinct from p_request_id
       or v_existing.quote_id is distinct from p_quote_id
       or v_existing.decision <> 'approved'
       or v_existing.decided_by_user_id is distinct from p_actor_user_id then
      return jsonb_build_object('ok', false, 'code', 'DECISION_IDEMPOTENCY_CONFLICT');
    end if;
    select request.* into v_request from public.ticket_management_requests request
     where request.id = p_request_id;
    return jsonb_build_object(
      'ok', true, 'replay', true, 'requestId', p_request_id,
      'decisionId', v_existing.id, 'status', v_request.status,
      'version', v_request.version,
      'reservationId', v_request.active_wallet_reservation_id,
      'ledgerEntryId', v_request.hold_ledger_entry_id
    );
  end if;

  select actor.* into v_actor from public.app_users actor
   where actor.clerk_id = p_actor_user_id;
  if not found or v_actor.role not in ('customer', 'b2b', 'b2b_sub') then
    return jsonb_build_object('ok', false, 'code', 'CUSTOMER_DECISION_FORBIDDEN');
  end if;
  select request.* into v_request
    from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  if v_request.version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_VERSION_CONFLICT', 'version', v_request.version);
  end if;
  if v_request.status <> 'awaiting-confirmation'
     or v_request.active_quote_id is distinct from p_quote_id then
    return jsonb_build_object('ok', false, 'code', 'QUOTE_NOT_ACTIONABLE');
  end if;
  if not (
    (v_actor.role = 'customer' and v_request.booking_owner_type = 'user'
      and v_request.booking_owner_key = p_actor_user_id)
    or (v_actor.role in ('b2b', 'b2b_sub')
      and v_request.booking_owner_type = 'agency'
      and v_actor.agency_code = v_request.booking_owner_key)
  ) then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_OWNER_FORBIDDEN');
  end if;
  select quote.* into v_quote
    from public.ticket_management_quotes quote
   where quote.id = p_quote_id and quote.request_id = p_request_id
   for update;
  if v_quote.confirmation_deadline_at <= clock_timestamp() then
    update public.ticket_management_requests
       set status = 'expired', terminal_outcome = 'confirmation-expired',
           expired_at = clock_timestamp(), status_changed_at = clock_timestamp(),
           version = version + 1
     where id = v_request.id returning version into v_version;
    perform public.ticket_management_append_event_v1(
      v_request.id, 'confirmation-expired', 'awaiting-confirmation',
      'expired', v_version, 'system:ticket-management', 'system',
      'ticket-expire:' || v_request.id || ':' || v_quote.id,
      'Customer confirmation deadline passed',
      jsonb_build_object('quoteId', v_quote.id, 'deadline', v_quote.confirmation_deadline_at)
    );
    return jsonb_build_object('ok', false, 'code', 'QUOTE_EXPIRED',
      'requestId', v_request.id, 'status', 'expired', 'version', v_version);
  end if;

  perform entitlement.id
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
   where selection.request_id = v_request.id
   order by entitlement.id for update of entitlement;
  if exists (
    select 1 from public.ticket_management_entitlement_claims claim
     where claim.request_id = v_request.id and claim.state <> 'active'
  ) then
    return jsonb_build_object('ok', false, 'code', 'ENTITLEMENT_CLAIM_INACTIVE');
  end if;
  if exists (
    select 1 from public.wallet_reservations reservation
     where reservation.ticket_management_request_id = v_request.id
       and reservation.state = 'active'
  ) then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_RESERVATION_CONFLICT');
  end if;

  select wallet.* into v_wallet
    from public.wallets wallet
    join public.wallet_accounts account on account.wallet_id = wallet.id
   where account.id = v_request.charged_wallet_account_id
   for update of wallet;
  if not found or v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'OWNER_WALLET_UNAVAILABLE');
  end if;
  select account.* into v_account
    from public.wallet_accounts account
   where account.id = v_request.charged_wallet_account_id
   for update;
  if not found or v_account.currency <> v_request.currency
     or v_account.currency <> v_quote.currency then
    return jsonb_build_object('ok', false, 'code', 'OWNER_WALLET_CURRENCY_CONFLICT');
  end if;
  if v_account.available_balance < v_quote.customer_amount then
    return jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_AVAILABLE_BALANCE');
  end if;

  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts
     set available_balance = available_balance - v_quote.customer_amount,
         hold_balance = hold_balance + v_quote.customer_amount
   where id = v_account.id;
  insert into public.wallet_reservations (
    wallet_account_id, ticket_management_request_id, amount, currency,
    state, requested_by_user_id
  ) values (
    v_account.id, v_request.id, v_quote.customer_amount, v_quote.currency,
    'active', p_actor_user_id
  ) returning * into v_reservation;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, reservation_id, ticket_management_request_id,
    ticket_management_quote_id, idempotency_key, created_by_user_id,
    created_by_role, remarks, metadata
  ) values (
    v_account.id, 'ticket_management_hold', v_quote.customer_amount,
    v_quote.currency, v_available_before,
    v_available_before - v_quote.customer_amount,
    v_hold_before, v_hold_before + v_quote.customer_amount,
    v_request.booking_id, v_reservation.id, v_request.id, v_quote.id,
    p_request_key || ':hold', p_actor_user_id, v_actor.role,
    'Ticket Management customer-approved additional payment Hold',
    jsonb_build_object('action', v_request.action, 'quoteHash', v_quote.quote_hash)
  ) returning * into v_ledger;
  insert into public.ticket_management_customer_decisions (
    request_id, quote_id, decision, quote_version, quote_hash, request_key,
    decided_by_user_id, decided_by_role, note
  ) values (
    v_request.id, v_quote.id, 'approved', v_quote.quote_version,
    v_quote.quote_hash, p_request_key, p_actor_user_id, v_actor.role,
    nullif(btrim(p_note), '')
  ) returning * into v_decision;
  update public.ticket_management_requests
     set status = 'approved', approved_quote_id = v_quote.id,
         approved_at = clock_timestamp(), status_changed_at = clock_timestamp(),
         active_wallet_reservation_id = v_reservation.id,
         hold_ledger_entry_id = v_ledger.id, version = version + 1
   where id = v_request.id returning version into v_version;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'wallet-held', 'awaiting-confirmation', 'approved', v_version,
    p_actor_user_id, v_actor.role, p_request_key || ':hold:event', null,
    jsonb_build_object('quoteId', v_quote.id, 'reservationId', v_reservation.id,
      'ledgerEntryId', v_ledger.id, 'amount', v_quote.customer_amount)
  );
  perform public.ticket_management_append_event_v1(
    v_request.id, 'customer-approved', 'awaiting-confirmation', 'approved', v_version,
    p_actor_user_id, v_actor.role, p_request_key || ':event', p_note,
    jsonb_build_object('quoteId', v_quote.id, 'quoteHash', v_quote.quote_hash,
      'reservationId', v_reservation.id, 'ledgerEntryId', v_ledger.id)
  );
  return jsonb_build_object(
    'ok', true, 'replay', false, 'requestId', v_request.id,
    'decisionId', v_decision.id, 'status', 'approved', 'version', v_version,
    'reservationId', v_reservation.id, 'ledgerEntryId', v_ledger.id
  );
end;
$$;

create or replace function public.ticket_management_capture_hold_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_request_key text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request public.ticket_management_requests;
  v_quote public.ticket_management_quotes;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing public.wallet_ledger_entries;
  v_ledger public.wallet_ledger_entries;
  v_available_before bigint;
  v_hold_before bigint;
  v_version integer;
begin
  if nullif(btrim(p_request_key), '') is null then
    raise exception 'wallet capture request key is required' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select ledger.* into v_existing from public.wallet_ledger_entries ledger
   where ledger.idempotency_key = p_request_key;
  if found then
    if v_existing.transaction_type <> 'ticket_management_capture'
       or v_existing.ticket_management_request_id is distinct from p_request_id then
      return jsonb_build_object('ok', false, 'code', 'WALLET_IDEMPOTENCY_CONFLICT');
    end if;
    return jsonb_build_object('ok', true, 'replay', true,
      'ledgerEntryId', v_existing.id, 'requestId', p_request_id);
  end if;
  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_FORBIDDEN');
  end if;
  select request.* into v_request from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if not found or v_request.status <> 'approved'
     or v_request.active_assignee_user_id is distinct from p_actor_user_id
     or v_request.active_assignee_role is distinct from v_actor_role
     or v_request.approved_quote_id is null
     or v_request.active_wallet_reservation_id is null then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_NOT_AUTHORIZED');
  end if;
  select quote.* into strict v_quote from public.ticket_management_quotes quote
   where quote.id = v_request.approved_quote_id and quote.direction = 'debit';
  select reservation.* into v_reservation from public.wallet_reservations reservation
   where reservation.id = v_request.active_wallet_reservation_id
     and reservation.ticket_management_request_id = v_request.id
   for update;
  if not found or v_reservation.state <> 'active'
     or v_reservation.amount <> v_quote.customer_amount
     or v_reservation.wallet_account_id <> v_request.charged_wallet_account_id then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_HOLD_NOT_CAPTURABLE');
  end if;
  select wallet.* into v_wallet from public.wallets wallet
    join public.wallet_accounts account on account.wallet_id = wallet.id
   where account.id = v_request.charged_wallet_account_id for update of wallet;
  select account.* into strict v_account from public.wallet_accounts account
   where account.id = v_request.charged_wallet_account_id for update;
  if v_wallet.status <> 'active' or v_account.currency <> v_quote.currency
     or v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_HOLD_BALANCE_CONFLICT');
  end if;
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts set hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;
  update public.wallet_reservations
     set state = 'captured', captured_at = clock_timestamp(),
         issued_by_user_id = p_actor_user_id
   where id = v_reservation.id;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, reservation_id, ticket_management_request_id,
    ticket_management_quote_id, idempotency_key, created_by_user_id,
    created_by_role, remarks, metadata
  ) values (
    v_account.id, 'ticket_management_capture', v_reservation.amount,
    v_quote.currency, v_available_before, v_available_before,
    v_hold_before, v_hold_before - v_reservation.amount,
    v_request.booking_id, v_reservation.id, v_request.id, v_quote.id,
    p_request_key, p_actor_user_id, v_actor_role,
    'Ticket Management approved additional payment captured',
    jsonb_build_object('action', v_request.action, 'quoteHash', v_quote.quote_hash)
  ) returning * into v_ledger;
  update public.ticket_management_requests
     set capture_ledger_entry_id = v_ledger.id, version = version + 1
   where id = v_request.id returning version into v_version;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'wallet-captured', 'approved', 'approved', v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':event', null,
    jsonb_build_object('reservationId', v_reservation.id,
      'ledgerEntryId', v_ledger.id, 'amount', v_reservation.amount)
  );
  return jsonb_build_object('ok', true, 'replay', false,
    'requestId', v_request.id, 'ledgerEntryId', v_ledger.id,
    'reservationId', v_reservation.id, 'version', v_version);
end;
$$;

create or replace function public.ticket_management_release_hold_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_request_key text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request public.ticket_management_requests;
  v_quote public.ticket_management_quotes;
  v_reservation public.wallet_reservations;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing public.wallet_ledger_entries;
  v_ledger public.wallet_ledger_entries;
  v_available_before bigint;
  v_hold_before bigint;
  v_version integer;
begin
  if nullif(btrim(p_request_key), '') is null or nullif(btrim(p_reason), '') is null then
    raise exception 'wallet release request key and reason are required' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select ledger.* into v_existing from public.wallet_ledger_entries ledger
   where ledger.idempotency_key = p_request_key;
  if found then
    if v_existing.transaction_type <> 'ticket_management_release'
       or v_existing.ticket_management_request_id is distinct from p_request_id then
      return jsonb_build_object('ok', false, 'code', 'WALLET_IDEMPOTENCY_CONFLICT');
    end if;
    return jsonb_build_object('ok', true, 'replay', true,
      'ledgerEntryId', v_existing.id, 'requestId', p_request_id);
  end if;
  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_FORBIDDEN');
  end if;
  select request.* into v_request from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if not found or v_request.status <> 'approved'
     or v_request.active_assignee_user_id is distinct from p_actor_user_id
     or v_request.active_assignee_role is distinct from v_actor_role
     or v_request.active_wallet_reservation_id is null then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_NOT_AUTHORIZED');
  end if;
  select quote.* into strict v_quote from public.ticket_management_quotes quote
   where quote.id = v_request.approved_quote_id and quote.direction = 'debit';
  select reservation.* into v_reservation from public.wallet_reservations reservation
   where reservation.id = v_request.active_wallet_reservation_id
     and reservation.ticket_management_request_id = v_request.id for update;
  if not found or v_reservation.state <> 'active'
     or v_reservation.amount <> v_quote.customer_amount then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_HOLD_NOT_RELEASABLE');
  end if;
  select wallet.* into v_wallet from public.wallets wallet
    join public.wallet_accounts account on account.wallet_id = wallet.id
   where account.id = v_request.charged_wallet_account_id for update of wallet;
  select account.* into strict v_account from public.wallet_accounts account
   where account.id = v_request.charged_wallet_account_id for update;
  if v_wallet.status <> 'active' or v_account.currency <> v_quote.currency
     or v_account.hold_balance < v_reservation.amount then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_HOLD_BALANCE_CONFLICT');
  end if;
  v_available_before := v_account.available_balance;
  v_hold_before := v_account.hold_balance;
  update public.wallet_accounts
     set available_balance = available_balance + v_reservation.amount,
         hold_balance = hold_balance - v_reservation.amount
   where id = v_account.id;
  update public.wallet_reservations
     set state = 'released', released_at = clock_timestamp(),
         release_reason = p_reason, issued_by_user_id = p_actor_user_id
   where id = v_reservation.id;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    booking_id, reservation_id, ticket_management_request_id,
    ticket_management_quote_id, idempotency_key, created_by_user_id,
    created_by_role, remarks, metadata
  ) values (
    v_account.id, 'ticket_management_release', v_reservation.amount,
    v_quote.currency, v_available_before, v_available_before + v_reservation.amount,
    v_hold_before, v_hold_before - v_reservation.amount,
    v_request.booking_id, v_reservation.id, v_request.id, v_quote.id,
    p_request_key, p_actor_user_id, v_actor_role,
    'Ticket Management approved additional payment Hold released',
    jsonb_build_object('action', v_request.action, 'quoteHash', v_quote.quote_hash,
      'reason', p_reason)
  ) returning * into v_ledger;
  update public.ticket_management_requests
     set release_ledger_entry_id = v_ledger.id, version = version + 1
   where id = v_request.id returning version into v_version;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'wallet-released', 'approved', 'approved', v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':event', p_reason,
    jsonb_build_object('reservationId', v_reservation.id,
      'ledgerEntryId', v_ledger.id, 'amount', v_reservation.amount)
  );
  return jsonb_build_object('ok', true, 'replay', false,
    'requestId', v_request.id, 'ledgerEntryId', v_ledger.id,
    'reservationId', v_reservation.id, 'version', v_version);
end;
$$;

revoke execute on function public.decide_ticket_management_quote_v1(
  uuid, uuid, text, text, integer, text, text
) from service_role;
revoke all on function public.decide_ticket_management_quote_v2(
  uuid, uuid, text, text, integer, text, text
) from public, anon, authenticated;
grant execute on function public.decide_ticket_management_quote_v2(
  uuid, uuid, text, text, integer, text, text
) to service_role;
revoke all on function public.ticket_management_capture_hold_v1(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke all on function public.ticket_management_release_hold_v1(uuid, text, text, text)
  from public, anon, authenticated, service_role;

comment on function public.decide_ticket_management_quote_v2(
  uuid, uuid, text, text, integer, text, text
) is
  'Customer decision boundary. Debit approval atomically places a request-scoped Hold on the original booking owner wallet; all other decisions retain v1 semantics.';


-- SOURCE: 0123_ticket_management_refund_settlement.sql
-- Assigned Refund final settlement.
-- The selected User Payable ticket entitlement is consumed, while only the immutable
-- customer-approved net amount is credited to the original booking account.

create or replace function public.complete_ticket_management_refund_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request_hint public.ticket_management_requests;
  v_request public.ticket_management_requests;
  v_booking public.flight_bookings;
  v_quote public.ticket_management_quotes;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing_event public.ticket_management_request_events;
  v_ledger public.wallet_ledger_entries;
  v_selected_remaining bigint;
  v_version integer;
begin
  if p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_request_key), '') is null then
    raise exception 'invalid Refund settlement request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select event.* into v_existing_event
    from public.ticket_management_request_events event
   where event.idempotency_key = p_request_key || ':completed';
  if found then
    if v_existing_event.request_id is distinct from p_request_id then
      return jsonb_build_object('ok', false, 'code', 'SETTLEMENT_IDEMPOTENCY_CONFLICT');
    end if;
    select request.* into v_request from public.ticket_management_requests request
     where request.id = p_request_id;
    return jsonb_build_object('ok', true, 'replay', true,
      'requestId', p_request_id, 'status', v_request.status,
      'version', v_request.version, 'ledgerEntryId', v_request.credit_ledger_entry_id);
  end if;

  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_FORBIDDEN');
  end if;
  select request.* into v_request_hint from public.ticket_management_requests request
   where request.id = p_request_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  select booking.* into v_booking from public.flight_bookings booking
   where booking.id = v_request_hint.booking_id for update;
  select request.* into v_request from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if v_request.version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_VERSION_CONFLICT',
      'version', v_request.version);
  end if;
  if v_request.action <> 'refund' or v_request.status <> 'approved'
     or v_request.active_assignee_user_id is distinct from p_actor_user_id
     or v_request.active_assignee_role is distinct from v_actor_role
     or v_request.approved_quote_id is null then
    return jsonb_build_object('ok', false, 'code', 'REFUND_SETTLEMENT_NOT_AUTHORIZED');
  end if;
  select quote.* into v_quote from public.ticket_management_quotes quote
   where quote.id = v_request.approved_quote_id and quote.request_id = v_request.id
   for update;
  if not found or v_quote.direction not in ('credit', 'none')
     or v_quote.selection_hash is distinct from v_request.selection_hash then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_REFUND_QUOTE_INVALID');
  end if;
  if v_booking.charged_wallet_account_id is distinct from v_request.charged_wallet_account_id
     or v_booking.booking_owner_type is distinct from v_request.booking_owner_type
     or v_booking.booking_owner_key is distinct from v_request.booking_owner_key
     or upper(v_booking.currency) <> v_request.currency
     or v_booking.payment_state not in ('captured', 'partially-refunded') then
    return jsonb_build_object('ok', false, 'code', 'ORIGINAL_BOOKING_WALLET_CONFLICT');
  end if;

  perform entitlement.id
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
   where selection.request_id = v_request.id
   order by entitlement.id for update of entitlement;
  select coalesce(sum(entitlement.entitlement_amount - entitlement.consumed_amount), 0)
    into v_selected_remaining
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
    join public.ticket_management_entitlement_claims claim
      on claim.request_id = selection.request_id
     and claim.entitlement_id = selection.entitlement_id
   where selection.request_id = v_request.id
     and entitlement.state = 'active' and claim.state = 'active';
  if v_selected_remaining <> v_quote.user_payable_entitlement_amount then
    return jsonb_build_object('ok', false, 'code', 'REFUND_ENTITLEMENT_CONFLICT');
  end if;

  if v_quote.direction = 'credit' then
    select wallet.* into v_wallet from public.wallets wallet
      join public.wallet_accounts account on account.wallet_id = wallet.id
     where account.id = v_request.charged_wallet_account_id for update of wallet;
    select account.* into v_account from public.wallet_accounts account
     where account.id = v_request.charged_wallet_account_id for update;
    if not found or v_account.currency <> v_quote.currency then
      return jsonb_build_object('ok', false, 'code', 'ORIGINAL_WALLET_CURRENCY_CONFLICT');
    end if;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, reservation_id, ticket_management_request_id,
      ticket_management_quote_id, idempotency_key, created_by_user_id,
      created_by_role, remarks, metadata
    ) values (
      v_account.id, 'refund', v_quote.customer_amount, v_quote.currency,
      v_account.available_balance, v_account.available_balance + v_quote.customer_amount,
      v_account.hold_balance, v_account.hold_balance, v_booking.id, null,
      v_request.id, v_quote.id, p_request_key || ':refund',
      p_actor_user_id, v_actor_role,
      coalesce(nullif(btrim(p_note), ''), 'Ticket Management approved Refund credit'),
      jsonb_build_object('quoteHash', v_quote.quote_hash,
        'supplierGrossAmount', v_quote.supplier_gross_amount,
        'supplierPayableAmount', v_quote.supplier_payable_amount,
        'userPayableEntitlementConsumed', v_quote.user_payable_entitlement_amount,
        'netCustomerCredit', v_quote.customer_amount)
    ) returning * into v_ledger;
    update public.wallet_accounts
       set available_balance = available_balance + v_quote.customer_amount
     where id = v_account.id;
    update public.flight_bookings
       set refunded_amount = refunded_amount + v_quote.customer_amount,
           payment_state = case
             when refunded_amount + v_quote.customer_amount = captured_amount
               then 'refunded' else 'partially-refunded' end
     where id = v_booking.id;
  end if;

  update public.ticket_management_ticket_entitlements entitlement
     set consumed_amount = entitlement.entitlement_amount, state = 'refunded'
    from public.ticket_management_request_selections selection
   where selection.request_id = v_request.id
     and selection.entitlement_id = entitlement.id;
  update public.ticket_management_entitlement_claims
     set state = 'consumed', consumed_at = clock_timestamp()
   where request_id = v_request.id and state = 'active';
  update public.ticket_management_requests
     set status = 'completed', terminal_outcome = 'refunded',
         completed_at = clock_timestamp(), status_changed_at = clock_timestamp(),
         credit_ledger_entry_id = v_ledger.id, version = version + 1
   where id = v_request.id returning version into v_version;
  if v_ledger.id is not null then
    perform public.ticket_management_append_event_v1(
      v_request.id, 'wallet-credited', 'approved', 'completed', v_version,
      p_actor_user_id, v_actor_role, p_request_key || ':credit', p_note,
      jsonb_build_object('ledgerEntryId', v_ledger.id,
        'amount', v_quote.customer_amount,
        'userPayableEntitlementConsumed', v_quote.user_payable_entitlement_amount)
    );
  end if;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'completed', 'approved', 'completed', v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':completed', p_note,
    jsonb_build_object('outcome', 'refunded', 'quoteId', v_quote.id,
      'ledgerEntryId', v_ledger.id,
      'supplierGrossAmount', v_quote.supplier_gross_amount,
      'supplierPayableAmount', v_quote.supplier_payable_amount,
      'userPayableEntitlementConsumed', v_quote.user_payable_entitlement_amount,
      'netCustomerCredit', v_quote.customer_amount)
  );
  return jsonb_build_object('ok', true, 'replay', false,
    'requestId', v_request.id, 'status', 'completed', 'outcome', 'refunded',
    'version', v_version, 'ledgerEntryId', v_ledger.id,
    'creditedAmount', v_quote.customer_amount,
    'consumedEntitlementAmount', v_quote.user_payable_entitlement_amount);
end;
$$;

revoke all on function public.complete_ticket_management_refund_v1(
  uuid, text, integer, text, text
) from public, anon, authenticated;
grant execute on function public.complete_ticket_management_refund_v1(
  uuid, text, integer, text, text
) to service_role;

comment on function public.complete_ticket_management_refund_v1(
  uuid, text, integer, text, text
) is
  'Assigned Accounts/Admin/Superadmin Refund completion. Atomically consumes selected User Payable entitlement, credits only the immutable approved final customer amount to the original charged account, and completes the request.';


-- SOURCE: 0124_ticket_management_reissue_settlement.sql
-- Assigned Reissue completion and controlled failure/requotation.
--
-- A customer-approved additional payment is captured only after the manual
-- supplier/GDS operation succeeds. Only the fare-difference component becomes
-- additional future User Payable ticket entitlement; airline and Kaliganj Travels
-- service fees remain separately audited and non-refundable by default.

drop index public.wallet_reservations_ticket_management_request_key;
create unique index wallet_reservations_ticket_management_active_request_key
  on public.wallet_reservations(ticket_management_request_id)
  where ticket_management_request_id is not null and state = 'active';

create table public.ticket_management_reissue_quote_terms (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null
    references public.ticket_management_requests(id) on delete restrict,
  quote_id uuid not null unique
    references public.ticket_management_quotes(id) on delete restrict,
  allocation_hash text not null check (allocation_hash ~ '^[a-f0-9]{64}$'),
  fare_difference_amount bigint not null check (fare_difference_amount >= 0),
  created_at timestamptz not null default clock_timestamp(),
  unique (request_id, allocation_hash)
);

create table public.ticket_management_reissue_quote_allocations (
  id uuid primary key default gen_random_uuid(),
  terms_id uuid not null
    references public.ticket_management_reissue_quote_terms(id) on delete restrict,
  request_id uuid not null
    references public.ticket_management_requests(id) on delete restrict,
  quote_id uuid not null
    references public.ticket_management_quotes(id) on delete restrict,
  entitlement_id uuid not null
    references public.ticket_management_ticket_entitlements(id) on delete restrict,
  passenger_index integer not null check (passenger_index >= 0),
  fare_difference_amount bigint not null check (fare_difference_amount >= 0),
  created_at timestamptz not null default clock_timestamp(),
  unique (quote_id, entitlement_id),
  unique (quote_id, passenger_index)
);

create index ticket_management_reissue_quote_allocations_request_idx
  on public.ticket_management_reissue_quote_allocations(request_id, passenger_index, id);

create trigger ticket_management_reissue_quote_terms_deny_update_delete
  before update or delete on public.ticket_management_reissue_quote_terms
  for each row execute function public.prevent_ticket_management_audit_mutation_v1();
create trigger ticket_management_reissue_quote_allocations_deny_update_delete
  before update or delete on public.ticket_management_reissue_quote_allocations
  for each row execute function public.prevent_ticket_management_audit_mutation_v1();

create or replace function public.publish_ticket_management_reissue_quote_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_direction text,
  p_currency text,
  p_supplier_gross_amount bigint,
  p_supplier_payable_amount bigint,
  p_fare_difference bigint,
  p_airline_fee bigint,
  p_service_fee bigint,
  p_customer_amount bigint,
  p_confirmation_deadline_at timestamptz,
  p_fare_difference_allocations jsonb,
  p_details text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request public.ticket_management_requests;
  v_result jsonb;
  v_quote_id uuid;
  v_terms public.ticket_management_reissue_quote_terms;
  v_existing_terms public.ticket_management_reissue_quote_terms;
  v_normalized jsonb;
  v_allocation_hash text;
  v_count integer;
  v_selected_count integer;
  v_total bigint;
begin
  if p_fare_difference_allocations is null
     or jsonb_typeof(p_fare_difference_allocations) <> 'array'
     or jsonb_array_length(p_fare_difference_allocations) = 0 then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_FARE_ALLOCATION_REQUIRED');
  end if;
  if exists (
    select 1
      from jsonb_array_elements(p_fare_difference_allocations) item(value)
     where jsonb_typeof(item.value) <> 'object'
        or jsonb_typeof(item.value->'entitlementId') <> 'string'
        or (item.value->>'entitlementId')
             !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or jsonb_typeof(item.value->'fareDifferenceAmount') <> 'number'
        or (item.value->>'fareDifferenceAmount')::numeric < 0
        or (item.value->>'fareDifferenceAmount')::numeric
             <> trunc((item.value->>'fareDifferenceAmount')::numeric)
        or (item.value->>'fareDifferenceAmount')::numeric > 9223372036854775807
  ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_FARE_ALLOCATION_INVALID');
  end if;
  select jsonb_agg(jsonb_build_object(
      'entitlementId', lower(item.value->>'entitlementId'),
      'fareDifferenceAmount', (item.value->>'fareDifferenceAmount')::bigint
    ) order by lower(item.value->>'entitlementId')),
    count(*)::integer,
    sum((item.value->>'fareDifferenceAmount')::bigint)
    into v_normalized, v_count, v_total
    from jsonb_array_elements(p_fare_difference_allocations) item(value);
  if v_count <> (
      select count(distinct lower(item.value->>'entitlementId'))
        from jsonb_array_elements(p_fare_difference_allocations) item(value)
    ) or v_total <> p_fare_difference then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_FARE_ALLOCATION_TOTAL_MISMATCH');
  end if;
  v_allocation_hash := encode(sha256(convert_to(v_normalized::text, 'UTF8')), 'hex');

  select request.* into v_request
    from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  if v_request.action <> 'reissue' or v_request.status <> 'in-progress'
     or v_request.version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_REQUEST_NOT_QUOTABLE',
      'version', v_request.version);
  end if;
  select count(*)::integer into v_selected_count
    from public.ticket_management_request_selections selection
   where selection.request_id = v_request.id;
  if v_selected_count <> v_count
     or exists (
       select 1
         from jsonb_to_recordset(v_normalized)
           as allocation("entitlementId" text, "fareDifferenceAmount" bigint)
         left join public.ticket_management_request_selections selection
           on selection.request_id = v_request.id
          and selection.entitlement_id = allocation."entitlementId"::uuid
        where selection.id is null
     ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_FARE_ALLOCATION_SELECTION_MISMATCH');
  end if;

  v_result := public.publish_ticket_management_quote_v1(
    p_request_id, p_actor_user_id, p_expected_version, p_request_key,
    p_direction, p_currency, p_supplier_gross_amount, p_supplier_payable_amount,
    0, p_fare_difference, p_airline_fee, 0, p_service_fee,
    p_customer_amount, p_confirmation_deadline_at, p_details
  );
  if not coalesce((v_result->>'ok')::boolean, false) then return v_result; end if;
  v_quote_id := (v_result->>'quoteId')::uuid;
  select terms.* into v_existing_terms
    from public.ticket_management_reissue_quote_terms terms
   where terms.quote_id = v_quote_id;
  if found then
    if v_existing_terms.request_id is distinct from p_request_id
       or v_existing_terms.allocation_hash is distinct from v_allocation_hash
       or v_existing_terms.fare_difference_amount <> p_fare_difference then
      return jsonb_build_object('ok', false, 'code', 'REISSUE_QUOTE_IDEMPOTENCY_CONFLICT');
    end if;
    return v_result || jsonb_build_object(
      'allocationHash', v_allocation_hash,
      'allocatedPassengerCount', v_count
    );
  end if;
  insert into public.ticket_management_reissue_quote_terms (
    request_id, quote_id, allocation_hash, fare_difference_amount
  ) values (
    p_request_id, v_quote_id, v_allocation_hash, p_fare_difference
  ) returning * into v_terms;
  insert into public.ticket_management_reissue_quote_allocations (
    terms_id, request_id, quote_id, entitlement_id,
    passenger_index, fare_difference_amount
  )
  select v_terms.id, p_request_id, v_quote_id, selection.entitlement_id,
         selection.passenger_index, allocation."fareDifferenceAmount"
    from jsonb_to_recordset(v_normalized)
      as allocation("entitlementId" text, "fareDifferenceAmount" bigint)
    join public.ticket_management_request_selections selection
      on selection.request_id = p_request_id
     and selection.entitlement_id = allocation."entitlementId"::uuid;
  return v_result || jsonb_build_object(
    'allocationHash', v_allocation_hash,
    'allocatedPassengerCount', v_count
  );
end;
$$;

create or replace function public.ticket_management_require_reissue_quote_terms_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_action text;
  v_quote public.ticket_management_quotes;
  v_terms public.ticket_management_reissue_quote_terms;
  v_count integer;
  v_total bigint;
begin
  select request.action into strict v_action
    from public.ticket_management_requests request
   where request.id = new.request_id;
  if v_action <> 'reissue' or new.decision <> 'approved' then return new; end if;
  select quote.* into strict v_quote
    from public.ticket_management_quotes quote
   where quote.id = new.quote_id and quote.request_id = new.request_id;
  select terms.* into v_terms
    from public.ticket_management_reissue_quote_terms terms
   where terms.quote_id = new.quote_id;
  if not found then
    raise exception 'approved Reissue quote has no immutable passenger fare allocation'
      using errcode = '23514';
  end if;
  select count(*)::integer, coalesce(sum(allocation.fare_difference_amount), 0)
    into v_count, v_total
    from public.ticket_management_reissue_quote_allocations allocation
   where allocation.quote_id = new.quote_id;
  if v_count <> (
       select count(*) from public.ticket_management_request_selections selection
        where selection.request_id = new.request_id
     ) or v_total <> v_quote.fare_difference
     or v_total <> v_terms.fare_difference_amount then
    raise exception 'approved Reissue quote passenger fare allocation is incomplete'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger ticket_management_customer_decisions_require_reissue_terms
  before insert on public.ticket_management_customer_decisions
  for each row execute function public.ticket_management_require_reissue_quote_terms_v1();

create table public.ticket_management_reissue_completions (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null unique
    references public.ticket_management_requests(id) on delete restrict,
  quote_id uuid not null unique
    references public.ticket_management_quotes(id) on delete restrict,
  request_key text not null unique
    check (char_length(request_key) between 1 and 180),
  payload_hash text not null check (payload_hash ~ '^[a-f0-9]{64}$'),
  reissue_allocation_hash text not null check (reissue_allocation_hash ~ '^[a-f0-9]{64}$'),
  supplier_gross_amount bigint not null check (supplier_gross_amount > 0),
  supplier_payable_amount bigint not null check (supplier_payable_amount > 0),
  carried_user_payable_amount bigint not null check (carried_user_payable_amount > 0),
  fare_difference_amount bigint not null check (fare_difference_amount >= 0),
  airline_fee_amount bigint not null check (airline_fee_amount >= 0),
  service_fee_amount bigint not null check (service_fee_amount >= 0),
  customer_amount_captured bigint not null check (customer_amount_captured >= 0),
  capture_ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  finalized_by_user_id text not null,
  finalized_by_role text not null
    check (finalized_by_role in ('staff_account', 'admin', 'superadmin')),
  note text check (note is null or char_length(note) <= 2000),
  finalized_at timestamptz not null default clock_timestamp(),
  constraint ticket_management_reissue_completion_total_check
    check (
      customer_amount_captured
        = fare_difference_amount + airline_fee_amount + service_fee_amount
    ),
  constraint ticket_management_reissue_completion_capture_check
    check (
      (customer_amount_captured = 0 and capture_ledger_entry_id is null)
      or (customer_amount_captured > 0 and capture_ledger_entry_id is not null)
    )
);

create table public.ticket_management_reissue_lineages (
  id uuid primary key default gen_random_uuid(),
  completion_id uuid not null
    references public.ticket_management_reissue_completions(id) on delete restrict,
  request_id uuid not null
    references public.ticket_management_requests(id) on delete restrict,
  booking_id uuid not null
    references public.flight_bookings(id) on delete restrict,
  quote_id uuid not null
    references public.ticket_management_quotes(id) on delete restrict,
  predecessor_entitlement_id uuid not null unique
    references public.ticket_management_ticket_entitlements(id) on delete restrict,
  successor_entitlement_id uuid not null unique
    references public.ticket_management_ticket_entitlements(id) on delete restrict,
  passenger_index integer not null check (passenger_index >= 0),
  previous_ticket_number text not null
    check (char_length(btrim(previous_ticket_number)) between 1 and 80),
  new_ticket_number text not null
    check (char_length(btrim(new_ticket_number)) between 1 and 80),
  carried_user_payable_amount bigint not null check (carried_user_payable_amount > 0),
  fare_difference_amount bigint not null check (fare_difference_amount >= 0),
  successor_user_payable_entitlement_amount bigint not null
    check (successor_user_payable_entitlement_amount > 0),
  created_at timestamptz not null default clock_timestamp(),
  unique (request_id, passenger_index),
  unique (booking_id, new_ticket_number),
  constraint ticket_management_reissue_lineage_total_check
    check (
      successor_user_payable_entitlement_amount
        = carried_user_payable_amount + fare_difference_amount
    ),
  constraint ticket_management_reissue_lineage_ticket_change_check
    check (upper(btrim(previous_ticket_number)) <> upper(btrim(new_ticket_number)))
);

create index ticket_management_reissue_lineages_completion_idx
  on public.ticket_management_reissue_lineages(completion_id, passenger_index, id);
create index ticket_management_reissue_lineages_booking_idx
  on public.ticket_management_reissue_lineages(booking_id, passenger_index, id);

create trigger ticket_management_reissue_completions_deny_update_delete
  before update or delete on public.ticket_management_reissue_completions
  for each row execute function public.prevent_ticket_management_audit_mutation_v1();
create trigger ticket_management_reissue_lineages_deny_update_delete
  before update or delete on public.ticket_management_reissue_lineages
  for each row execute function public.prevent_ticket_management_audit_mutation_v1();

create or replace function public.complete_ticket_management_reissue_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_new_tickets jsonb,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request_hint public.ticket_management_requests;
  v_request public.ticket_management_requests;
  v_booking public.flight_bookings;
  v_quote public.ticket_management_quotes;
  v_reissue_terms public.ticket_management_reissue_quote_terms;
  v_existing public.ticket_management_reissue_completions;
  v_completion public.ticket_management_reissue_completions;
  v_entitlement public.ticket_management_ticket_entitlements;
  v_successor public.ticket_management_ticket_entitlements;
  v_capture_result jsonb;
  v_capture_ledger_id uuid;
  v_normalized_tickets jsonb;
  v_payload_hash text;
  v_mapping_count integer;
  v_selection_count integer;
  v_fare_difference_total bigint;
  v_carried_total bigint;
  v_ticket_numbers jsonb;
  v_item record;
  v_version integer;
begin
  if p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 180
     or p_new_tickets is null
     or jsonb_typeof(p_new_tickets) <> 'array'
     or jsonb_array_length(p_new_tickets) = 0
     or (p_note is not null and char_length(p_note) > 2000) then
    raise exception 'invalid Reissue completion request' using errcode = '22023';
  end if;
  if exists (
    select 1
      from jsonb_array_elements(p_new_tickets) item(value)
     where jsonb_typeof(item.value) <> 'object'
        or jsonb_typeof(item.value->'predecessorEntitlementId') <> 'string'
        or (item.value->>'predecessorEntitlementId')
             !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or jsonb_typeof(item.value->'newTicketNumber') <> 'string'
        or nullif(btrim(item.value->>'newTicketNumber'), '') is null
        or char_length(btrim(item.value->>'newTicketNumber')) > 80
        or jsonb_typeof(item.value->'fareDifferenceAmount') <> 'number'
        or (item.value->>'fareDifferenceAmount')::numeric < 0
        or (item.value->>'fareDifferenceAmount')::numeric
             <> trunc((item.value->>'fareDifferenceAmount')::numeric)
        or (item.value->>'fareDifferenceAmount')::numeric > 9223372036854775807
  ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_TICKET_MAPPING_INVALID');
  end if;

  select jsonb_agg(jsonb_build_object(
      'predecessorEntitlementId', lower(item.value->>'predecessorEntitlementId'),
      'newTicketNumber', upper(btrim(item.value->>'newTicketNumber')),
      'fareDifferenceAmount', (item.value->>'fareDifferenceAmount')::bigint
    ) order by lower(item.value->>'predecessorEntitlementId')),
    count(*)::integer,
    sum((item.value->>'fareDifferenceAmount')::bigint)
    into v_normalized_tickets, v_mapping_count, v_fare_difference_total
    from jsonb_array_elements(p_new_tickets) item(value);
  if v_mapping_count <> (
      select count(distinct lower(item.value->>'predecessorEntitlementId'))
        from jsonb_array_elements(p_new_tickets) item(value)
    ) or v_mapping_count <> (
      select count(distinct upper(btrim(item.value->>'newTicketNumber')))
        from jsonb_array_elements(p_new_tickets) item(value)
    ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_TICKET_MAPPING_DUPLICATE');
  end if;
  v_payload_hash := encode(sha256(convert_to(jsonb_build_object(
    'requestId', p_request_id,
    'tickets', v_normalized_tickets,
    'note', nullif(btrim(p_note), '')
  )::text, 'UTF8')), 'hex');

  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select completion.* into v_existing
    from public.ticket_management_reissue_completions completion
   where completion.request_key = p_request_key
   for update;
  if found then
    if v_existing.request_id is distinct from p_request_id
       or v_existing.payload_hash is distinct from v_payload_hash
       or v_existing.finalized_by_user_id is distinct from p_actor_user_id then
      return jsonb_build_object('ok', false, 'code', 'REISSUE_COMPLETION_IDEMPOTENCY_CONFLICT');
    end if;
    select request.* into v_request from public.ticket_management_requests request
     where request.id = p_request_id;
    return jsonb_build_object('ok', true, 'replay', true,
      'requestId', p_request_id, 'completionId', v_existing.id,
      'status', v_request.status, 'version', v_request.version,
      'ledgerEntryId', v_existing.capture_ledger_entry_id);
  end if;
  select completion.* into v_existing
    from public.ticket_management_reissue_completions completion
   where completion.request_id = p_request_id;
  if found then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_ALREADY_COMPLETED');
  end if;

  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_FORBIDDEN');
  end if;
  select request.* into v_request_hint from public.ticket_management_requests request
   where request.id = p_request_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  select booking.* into v_booking from public.flight_bookings booking
   where booking.id = v_request_hint.booking_id for update;
  select request.* into v_request from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if v_request.version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_VERSION_CONFLICT',
      'version', v_request.version);
  end if;
  if v_request.action <> 'reissue' or v_request.status <> 'approved'
     or v_request.active_assignee_user_id is distinct from p_actor_user_id
     or v_request.active_assignee_role is distinct from v_actor_role
     or v_request.approved_quote_id is null then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_SETTLEMENT_NOT_AUTHORIZED');
  end if;
  select quote.* into v_quote from public.ticket_management_quotes quote
   where quote.id = v_request.approved_quote_id and quote.request_id = v_request.id
   for update;
  if not found or v_quote.direction not in ('debit', 'none')
     or v_quote.selection_hash is distinct from v_request.selection_hash
     or v_quote.user_payable_entitlement_amount <> 0
     or v_quote.void_fee <> 0
     or v_quote.customer_amount
          <> v_quote.fare_difference + v_quote.airline_fee + v_quote.service_fee
     or v_quote.fare_difference <> v_fare_difference_total then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_REISSUE_QUOTE_INVALID');
  end if;
  select terms.* into v_reissue_terms
    from public.ticket_management_reissue_quote_terms terms
   where terms.quote_id = v_quote.id and terms.request_id = v_request.id;
  if not found or v_reissue_terms.fare_difference_amount <> v_quote.fare_difference then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_REISSUE_ALLOCATION_INVALID');
  end if;
  if v_booking.charged_wallet_account_id is distinct from v_request.charged_wallet_account_id
     or v_booking.booking_owner_type is distinct from v_request.booking_owner_type
     or v_booking.booking_owner_key is distinct from v_request.booking_owner_key
     or upper(v_booking.currency) <> v_request.currency
     or jsonb_typeof(v_booking.ticket_numbers) <> 'array' then
    return jsonb_build_object('ok', false, 'code', 'ORIGINAL_BOOKING_WALLET_CONFLICT');
  end if;

  perform entitlement.id
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
   where selection.request_id = v_request.id
   order by entitlement.id for update of entitlement;
  select count(*)::integer, coalesce(sum(entitlement.entitlement_amount), 0)
    into v_selection_count, v_carried_total
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
    join public.ticket_management_entitlement_claims claim
      on claim.request_id = selection.request_id
     and claim.entitlement_id = selection.entitlement_id
   where selection.request_id = v_request.id
     and entitlement.booking_id = v_request.booking_id
     and entitlement.state = 'active'
     and entitlement.consumed_amount = 0
     and claim.state = 'active';
  if v_selection_count = 0 or v_selection_count <> v_mapping_count
     or v_selection_count <> (
       select count(*) from public.ticket_management_request_selections selection
        where selection.request_id = v_request.id
     ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_ENTITLEMENT_CONFLICT');
  end if;
  if exists (
    select 1
      from jsonb_to_recordset(v_normalized_tickets)
        as mapping("predecessorEntitlementId" text, "newTicketNumber" text,
          "fareDifferenceAmount" bigint)
      left join public.ticket_management_request_selections selection
        on selection.request_id = v_request.id
       and selection.entitlement_id = mapping."predecessorEntitlementId"::uuid
     where selection.id is null
  ) or exists (
    select 1
      from public.ticket_management_request_selections selection
      left join jsonb_to_recordset(v_normalized_tickets)
        as mapping("predecessorEntitlementId" text, "newTicketNumber" text,
          "fareDifferenceAmount" bigint)
        on mapping."predecessorEntitlementId"::uuid = selection.entitlement_id
     where selection.request_id = v_request.id
       and mapping."predecessorEntitlementId" is null
  ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_TICKET_MAPPING_MISMATCH');
  end if;
  if exists (
    select 1
      from jsonb_to_recordset(v_normalized_tickets)
        as mapping("predecessorEntitlementId" text, "newTicketNumber" text,
          "fareDifferenceAmount" bigint)
      left join public.ticket_management_reissue_quote_allocations allocation
        on allocation.quote_id = v_quote.id
       and allocation.entitlement_id = mapping."predecessorEntitlementId"::uuid
     where allocation.id is null
        or allocation.fare_difference_amount <> mapping."fareDifferenceAmount"
  ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_TICKET_ALLOCATION_MISMATCH');
  end if;
  if exists (
    select 1
      from jsonb_to_recordset(v_normalized_tickets)
        as mapping("predecessorEntitlementId" text, "newTicketNumber" text,
          "fareDifferenceAmount" bigint)
      join public.ticket_management_ticket_entitlements predecessor
        on predecessor.id = mapping."predecessorEntitlementId"::uuid
      left join public.ticket_management_ticket_entitlements active_ticket
        on active_ticket.booking_id = v_request.booking_id
       and active_ticket.state = 'active'
       and upper(active_ticket.active_ticket_number) = mapping."newTicketNumber"
     where upper(predecessor.active_ticket_number) = mapping."newTicketNumber"
        or active_ticket.id is not null
        or predecessor.passenger_index >= jsonb_array_length(v_booking.ticket_numbers)
        or predecessor.entitlement_amount
             > 9223372036854775807 - mapping."fareDifferenceAmount"
  ) then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_SUCCESSOR_TICKET_CONFLICT');
  end if;

  if v_quote.direction = 'debit' then
    v_capture_result := public.ticket_management_capture_hold_v1(
      v_request.id, p_actor_user_id, p_request_key || ':capture'
    );
    if not coalesce((v_capture_result->>'ok')::boolean, false) then
      return v_capture_result;
    end if;
    v_capture_ledger_id := (v_capture_result->>'ledgerEntryId')::uuid;
  elsif v_request.active_wallet_reservation_id is not null then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_ZERO_TOTAL_RESERVATION_CONFLICT');
  end if;

  insert into public.ticket_management_reissue_completions (
    request_id, quote_id, request_key, payload_hash, reissue_allocation_hash,
    supplier_gross_amount, supplier_payable_amount,
    carried_user_payable_amount, fare_difference_amount,
    airline_fee_amount, service_fee_amount, customer_amount_captured,
    capture_ledger_entry_id, finalized_by_user_id, finalized_by_role, note
  ) values (
    v_request.id, v_quote.id, p_request_key, v_payload_hash,
    v_reissue_terms.allocation_hash,
    v_quote.supplier_gross_amount, v_quote.supplier_payable_amount,
    v_carried_total, v_quote.fare_difference,
    v_quote.airline_fee, v_quote.service_fee, v_quote.customer_amount,
    v_capture_ledger_id, p_actor_user_id, v_actor_role,
    nullif(btrim(p_note), '')
  ) returning * into v_completion;

  v_ticket_numbers := v_booking.ticket_numbers;
  for v_item in
    select mapping."predecessorEntitlementId"::uuid as predecessor_id,
           mapping."newTicketNumber" as new_ticket_number,
           mapping."fareDifferenceAmount" as fare_difference_amount
      from jsonb_to_recordset(v_normalized_tickets)
        as mapping("predecessorEntitlementId" text, "newTicketNumber" text,
          "fareDifferenceAmount" bigint)
     order by mapping."predecessorEntitlementId"
  loop
    select entitlement.* into strict v_entitlement
      from public.ticket_management_ticket_entitlements entitlement
     where entitlement.id = v_item.predecessor_id;
    update public.ticket_management_ticket_entitlements
       set consumed_amount = entitlement_amount, state = 'reissued'
     where id = v_entitlement.id;
    insert into public.ticket_management_ticket_entitlements (
      booking_id, predecessor_entitlement_id, passenger_index,
      passenger_snapshot, passenger_name, passenger_type,
      original_ticket_number, active_ticket_number, currency,
      entitlement_amount, consumed_amount, user_payable_source_minor,
      allocation_source, allocation_hash, state
    ) values (
      v_entitlement.booking_id, v_entitlement.id, v_entitlement.passenger_index,
      v_entitlement.passenger_snapshot, v_entitlement.passenger_name,
      v_entitlement.passenger_type, v_entitlement.original_ticket_number,
      v_item.new_ticket_number, v_entitlement.currency,
      v_entitlement.entitlement_amount + v_item.fare_difference_amount,
      0, v_entitlement.entitlement_amount + v_item.fare_difference_amount,
      'reissue-lineage', encode(sha256(convert_to(concat_ws('|',
        v_quote.quote_hash, v_entitlement.id::text, v_item.new_ticket_number,
        v_item.fare_difference_amount::text,
        (v_entitlement.entitlement_amount + v_item.fare_difference_amount)::text
      ), 'UTF8')), 'hex'), 'active'
    ) returning * into v_successor;
    insert into public.ticket_management_reissue_lineages (
      completion_id, request_id, booking_id, quote_id,
      predecessor_entitlement_id, successor_entitlement_id, passenger_index,
      previous_ticket_number, new_ticket_number,
      carried_user_payable_amount, fare_difference_amount,
      successor_user_payable_entitlement_amount
    ) values (
      v_completion.id, v_request.id, v_request.booking_id, v_quote.id,
      v_entitlement.id, v_successor.id, v_entitlement.passenger_index,
      v_entitlement.active_ticket_number, v_successor.active_ticket_number,
      v_entitlement.entitlement_amount, v_item.fare_difference_amount,
      v_successor.entitlement_amount
    );
    v_ticket_numbers := jsonb_set(
      v_ticket_numbers, array[v_entitlement.passenger_index::text],
      to_jsonb(v_successor.active_ticket_number), false
    );
  end loop;

  update public.flight_bookings
     set ticket_numbers = v_ticket_numbers,
         captured_amount = captured_amount + v_quote.customer_amount
   where id = v_booking.id;
  update public.ticket_management_entitlement_claims
     set state = 'consumed', consumed_at = clock_timestamp()
   where request_id = v_request.id and state = 'active';
  update public.ticket_management_requests
     set status = 'completed', terminal_outcome = 'reissued',
         completed_at = clock_timestamp(), status_changed_at = clock_timestamp(),
         version = version + 1
   where id = v_request.id returning version into v_version;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'completed', 'approved', 'completed', v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':completed', p_note,
    jsonb_build_object(
      'outcome', 'reissued', 'quoteId', v_quote.id,
      'completionId', v_completion.id,
      'captureLedgerEntryId', v_capture_ledger_id,
      'supplierGrossAmount', v_quote.supplier_gross_amount,
      'supplierPayableAmount', v_quote.supplier_payable_amount,
      'carriedUserPayableAmount', v_carried_total,
      'fareDifferenceAmount', v_quote.fare_difference,
      'airlineFeeAmount', v_quote.airline_fee,
      'serviceFeeAmount', v_quote.service_fee,
      'customerAmountCaptured', v_quote.customer_amount,
      'tickets', v_normalized_tickets
    )
  );
  return jsonb_build_object('ok', true, 'replay', false,
    'requestId', v_request.id, 'completionId', v_completion.id,
    'status', 'completed', 'outcome', 'reissued', 'version', v_version,
    'ledgerEntryId', v_capture_ledger_id,
    'capturedAmount', v_quote.customer_amount,
    'futureEntitlementIncrease', v_quote.fare_difference);
end;
$$;

create or replace function public.release_and_reopen_ticket_management_reissue_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request public.ticket_management_requests;
  v_quote public.ticket_management_quotes;
  v_existing_event public.ticket_management_request_events;
  v_release_result jsonb;
  v_release_ledger_id uuid;
  v_version integer;
begin
  if p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 180
     or nullif(btrim(p_reason), '') is null
     or char_length(p_reason) > 2000 then
    raise exception 'invalid Reissue release/reopen request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select event.* into v_existing_event
    from public.ticket_management_request_events event
   where event.idempotency_key = p_request_key || ':reopened';
  if found then
    if v_existing_event.request_id is distinct from p_request_id
       or v_existing_event.actor_user_id is distinct from p_actor_user_id
       or v_existing_event.note is distinct from nullif(btrim(p_reason), '') then
      return jsonb_build_object('ok', false, 'code', 'REISSUE_RELEASE_IDEMPOTENCY_CONFLICT');
    end if;
    return jsonb_build_object('ok', true, 'replay', true,
      'requestId', p_request_id, 'status', v_existing_event.to_status,
      'version', v_existing_event.request_version,
      'ledgerEntryId', v_existing_event.metadata->>'releaseLedgerEntryId');
  end if;
  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_FORBIDDEN');
  end if;
  select request.* into v_request from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  if v_request.version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_VERSION_CONFLICT',
      'version', v_request.version);
  end if;
  if v_request.action <> 'reissue' or v_request.status <> 'approved'
     or v_request.active_assignee_user_id is distinct from p_actor_user_id
     or v_request.active_assignee_role is distinct from v_actor_role
     or v_request.approved_quote_id is null then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_RELEASE_NOT_AUTHORIZED');
  end if;
  select quote.* into v_quote from public.ticket_management_quotes quote
   where quote.id = v_request.approved_quote_id and quote.request_id = v_request.id
   for update;
  if not found or v_quote.direction not in ('debit', 'none') then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_REISSUE_QUOTE_INVALID');
  end if;
  if v_quote.direction = 'debit' then
    v_release_result := public.ticket_management_release_hold_v1(
      v_request.id, p_actor_user_id, p_request_key || ':release', p_reason
    );
    if not coalesce((v_release_result->>'ok')::boolean, false) then
      return v_release_result;
    end if;
    v_release_ledger_id := (v_release_result->>'ledgerEntryId')::uuid;
  elsif v_request.active_wallet_reservation_id is not null then
    return jsonb_build_object('ok', false, 'code', 'REISSUE_ZERO_TOTAL_RESERVATION_CONFLICT');
  end if;

  update public.ticket_management_requests
     set status = 'in-progress', active_quote_id = null,
         approved_quote_id = null, approved_at = null,
         active_assignment_id = null, active_assignee_user_id = null,
         active_assignee_role = null, assigned_at = null,
         active_wallet_reservation_id = null,
         hold_ledger_entry_id = null, capture_ledger_entry_id = null,
         release_ledger_entry_id = null,
         status_changed_at = clock_timestamp(), version = version + 1
   where id = v_request.id returning version into v_version;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'requote-started', 'approved', 'in-progress', v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':reopened', p_reason,
    jsonb_build_object(
      'supersededQuoteId', v_quote.id,
      'supersededQuoteVersion', v_quote.quote_version,
      'supersededQuoteHash', v_quote.quote_hash,
      'previousAssignmentId', v_request.active_assignment_id,
      'releaseLedgerEntryId', v_release_ledger_id,
      'manualReissuePerformed', false
    )
  );
  return jsonb_build_object('ok', true, 'replay', false,
    'requestId', v_request.id, 'status', 'in-progress',
    'version', v_version, 'releasedAmount', v_quote.customer_amount,
    'ledgerEntryId', v_release_ledger_id,
    'supersededQuoteId', v_quote.id);
end;
$$;

alter table public.ticket_management_reissue_quote_terms enable row level security;
alter table public.ticket_management_reissue_quote_allocations enable row level security;
alter table public.ticket_management_reissue_completions enable row level security;
alter table public.ticket_management_reissue_lineages enable row level security;

revoke all on public.ticket_management_reissue_quote_terms
  from public, anon, authenticated;
revoke all on public.ticket_management_reissue_quote_allocations
  from public, anon, authenticated;
revoke all on public.ticket_management_reissue_completions
  from public, anon, authenticated;
revoke all on public.ticket_management_reissue_lineages
  from public, anon, authenticated;
grant select, insert on public.ticket_management_reissue_completions to service_role;
grant select, insert on public.ticket_management_reissue_lineages to service_role;
grant select on public.ticket_management_reissue_quote_terms to service_role;
grant select on public.ticket_management_reissue_quote_allocations to service_role;

revoke all on function public.publish_ticket_management_reissue_quote_v1(
  uuid, text, integer, text, text, text, bigint, bigint, bigint, bigint,
  bigint, bigint, timestamptz, jsonb, text
) from public, anon, authenticated;
grant execute on function public.publish_ticket_management_reissue_quote_v1(
  uuid, text, integer, text, text, text, bigint, bigint, bigint, bigint,
  bigint, bigint, timestamptz, jsonb, text
) to service_role;
revoke all on function public.ticket_management_require_reissue_quote_terms_v1()
  from public, anon, authenticated, service_role;

revoke all on function public.complete_ticket_management_reissue_v1(
  uuid, text, integer, text, jsonb, text
) from public, anon, authenticated;
grant execute on function public.complete_ticket_management_reissue_v1(
  uuid, text, integer, text, jsonb, text
) to service_role;
revoke all on function public.release_and_reopen_ticket_management_reissue_v1(
  uuid, text, integer, text, text
) from public, anon, authenticated;
grant execute on function public.release_and_reopen_ticket_management_reissue_v1(
  uuid, text, integer, text, text
) to service_role;

comment on function public.complete_ticket_management_reissue_v1(
  uuid, text, integer, text, jsonb, text
) is
  'Assigned Accounts/Admin/Superadmin Reissue completion. Atomically captures the exact approved Hold, consumes predecessor tickets, creates successor ticket lineage, and carries forward only prior User Payable plus approved fare difference.';
comment on function public.publish_ticket_management_reissue_quote_v1(
  uuid, text, integer, text, text, text, bigint, bigint, bigint, bigint,
  bigint, bigint, timestamptz, jsonb, text
) is
  'Reissue quotation boundary. Freezes an exact per-passenger fare-difference allocation so final settlement cannot redistribute future User Payable entitlement.';
comment on function public.release_and_reopen_ticket_management_reissue_v1(
  uuid, text, integer, text, text
) is
  'Assigned Accounts/Admin/Superadmin non-performance path. Atomically releases the exact Reissue Hold and returns the request to In Progress for a new quotation and customer approval.';


-- SOURCE: 0125_ticket_management_void_settlement.sql
-- Assigned VOID settlement.
--
-- Net-return VOID credits the immutable approved amount to the original booking
-- owner wallet. Payable VOID captures the request-scoped approved Hold. Both
-- paths consume selected User Payable ticket entitlement atomically and remain
-- independent from held-booking cancellation/release functions.

create table public.ticket_management_void_completions (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null unique
    references public.ticket_management_requests(id) on delete restrict,
  quote_id uuid not null unique
    references public.ticket_management_quotes(id) on delete restrict,
  request_key text not null unique
    check (char_length(request_key) between 1 and 180),
  payload_hash text not null check (payload_hash ~ '^[a-f0-9]{64}$'),
  direction text not null check (direction in ('credit', 'debit', 'none')),
  supplier_gross_amount bigint not null check (supplier_gross_amount > 0),
  supplier_payable_amount bigint not null check (supplier_payable_amount > 0),
  user_payable_entitlement_amount bigint not null
    check (user_payable_entitlement_amount > 0),
  airline_void_fee_amount bigint not null check (airline_void_fee_amount >= 0),
  service_fee_amount bigint not null check (service_fee_amount >= 0),
  customer_amount bigint not null check (customer_amount >= 0),
  credit_ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  capture_ledger_entry_id uuid
    references public.wallet_ledger_entries(id) on delete restrict,
  finalized_by_user_id text not null,
  finalized_by_role text not null
    check (finalized_by_role in ('staff_account', 'admin', 'superadmin')),
  note text check (note is null or char_length(note) <= 2000),
  finalized_at timestamptz not null default clock_timestamp(),
  constraint ticket_management_void_completion_amount_check
    check (
      (direction = 'credit'
        and user_payable_entitlement_amount
          > airline_void_fee_amount + service_fee_amount
        and customer_amount = user_payable_entitlement_amount
          - airline_void_fee_amount - service_fee_amount)
      or (direction = 'debit'
        and user_payable_entitlement_amount
          < airline_void_fee_amount + service_fee_amount
        and customer_amount = airline_void_fee_amount + service_fee_amount
          - user_payable_entitlement_amount)
      or (direction = 'none'
        and user_payable_entitlement_amount
          = airline_void_fee_amount + service_fee_amount
        and customer_amount = 0)
    ),
  constraint ticket_management_void_completion_ledger_check
    check (
      (direction = 'credit'
        and credit_ledger_entry_id is not null
        and capture_ledger_entry_id is null)
      or (direction = 'debit'
        and credit_ledger_entry_id is null
        and capture_ledger_entry_id is not null)
      or (direction = 'none'
        and credit_ledger_entry_id is null
        and capture_ledger_entry_id is null)
    )
);

create index ticket_management_void_completions_finalizer_idx
  on public.ticket_management_void_completions(
    finalized_by_user_id, finalized_at desc, id
  );

create trigger ticket_management_void_completions_deny_update_delete
  before update or delete on public.ticket_management_void_completions
  for each row execute function public.prevent_ticket_management_audit_mutation_v1();

create or replace function public.complete_ticket_management_void_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request_hint public.ticket_management_requests;
  v_request public.ticket_management_requests;
  v_booking public.flight_bookings;
  v_quote public.ticket_management_quotes;
  v_wallet public.wallets;
  v_account public.wallet_accounts;
  v_existing public.ticket_management_void_completions;
  v_completion public.ticket_management_void_completions;
  v_ledger public.wallet_ledger_entries;
  v_capture_result jsonb;
  v_capture_ledger_id uuid;
  v_payload_hash text;
  v_selected_remaining bigint;
  v_version integer;
begin
  if p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 180
     or (p_note is not null and char_length(p_note) > 2000) then
    raise exception 'invalid VOID settlement request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select completion.* into v_existing
    from public.ticket_management_void_completions completion
   where completion.request_key = p_request_key
   for update;
  if found then
    v_payload_hash := encode(sha256(convert_to(jsonb_build_object(
      'requestId', p_request_id, 'quoteId', v_existing.quote_id,
      'note', nullif(btrim(p_note), '')
    )::text, 'UTF8')), 'hex');
    if v_existing.request_id is distinct from p_request_id
       or v_existing.payload_hash is distinct from v_payload_hash
       or v_existing.finalized_by_user_id is distinct from p_actor_user_id then
      return jsonb_build_object('ok', false, 'code', 'VOID_COMPLETION_IDEMPOTENCY_CONFLICT');
    end if;
    select request.* into v_request from public.ticket_management_requests request
     where request.id = p_request_id;
    return jsonb_build_object('ok', true, 'replay', true,
      'requestId', p_request_id, 'completionId', v_existing.id,
      'status', v_request.status, 'version', v_request.version,
      'direction', v_existing.direction,
      'ledgerEntryId', coalesce(
        v_existing.credit_ledger_entry_id, v_existing.capture_ledger_entry_id
      ));
  end if;
  select completion.* into v_existing
    from public.ticket_management_void_completions completion
   where completion.request_id = p_request_id;
  if found then
    return jsonb_build_object('ok', false, 'code', 'VOID_ALREADY_COMPLETED');
  end if;

  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_FORBIDDEN');
  end if;
  select request.* into v_request_hint from public.ticket_management_requests request
   where request.id = p_request_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  select booking.* into v_booking from public.flight_bookings booking
   where booking.id = v_request_hint.booking_id for update;
  select request.* into v_request from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if v_request.version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_VERSION_CONFLICT',
      'version', v_request.version);
  end if;
  if v_request.action <> 'void' or v_request.status <> 'approved'
     or v_request.active_assignee_user_id is distinct from p_actor_user_id
     or v_request.active_assignee_role is distinct from v_actor_role
     or v_request.approved_quote_id is null then
    return jsonb_build_object('ok', false, 'code', 'VOID_SETTLEMENT_NOT_AUTHORIZED');
  end if;
  select quote.* into v_quote from public.ticket_management_quotes quote
   where quote.id = v_request.approved_quote_id and quote.request_id = v_request.id
   for update;
  if not found or v_quote.direction not in ('credit', 'debit', 'none')
     or v_quote.selection_hash is distinct from v_request.selection_hash
     or v_quote.fare_difference <> 0 or v_quote.airline_fee <> 0
     or (
       v_quote.direction = 'credit'
       and (
         v_quote.user_payable_entitlement_amount
           <= v_quote.void_fee + v_quote.service_fee
         or v_quote.customer_amount <> v_quote.user_payable_entitlement_amount
           - v_quote.void_fee - v_quote.service_fee
       )
     ) or (
       v_quote.direction = 'debit'
       and (
         v_quote.user_payable_entitlement_amount
           >= v_quote.void_fee + v_quote.service_fee
         or v_quote.customer_amount <> v_quote.void_fee + v_quote.service_fee
           - v_quote.user_payable_entitlement_amount
       )
     ) or (
       v_quote.direction = 'none'
       and (
         v_quote.user_payable_entitlement_amount
           <> v_quote.void_fee + v_quote.service_fee
         or v_quote.customer_amount <> 0
       )
     ) then
    return jsonb_build_object('ok', false, 'code', 'APPROVED_VOID_QUOTE_INVALID');
  end if;
  if v_booking.charged_wallet_account_id is distinct from v_request.charged_wallet_account_id
     or v_booking.booking_owner_type is distinct from v_request.booking_owner_type
     or v_booking.booking_owner_key is distinct from v_request.booking_owner_key
     or upper(v_booking.currency) <> v_request.currency
     or v_booking.payment_state not in ('captured', 'partially-refunded') then
    return jsonb_build_object('ok', false, 'code', 'ORIGINAL_BOOKING_WALLET_CONFLICT');
  end if;

  perform entitlement.id
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
   where selection.request_id = v_request.id
   order by entitlement.id for update of entitlement;
  select coalesce(sum(entitlement.entitlement_amount - entitlement.consumed_amount), 0)
    into v_selected_remaining
    from public.ticket_management_request_selections selection
    join public.ticket_management_ticket_entitlements entitlement
      on entitlement.id = selection.entitlement_id
    join public.ticket_management_entitlement_claims claim
      on claim.request_id = selection.request_id
     and claim.entitlement_id = selection.entitlement_id
   where selection.request_id = v_request.id
     and entitlement.state = 'active' and claim.state = 'active';
  if v_selected_remaining <> v_quote.user_payable_entitlement_amount then
    return jsonb_build_object('ok', false, 'code', 'VOID_ENTITLEMENT_CONFLICT');
  end if;

  if v_quote.direction = 'credit' then
    if v_request.active_wallet_reservation_id is not null then
      return jsonb_build_object('ok', false, 'code', 'VOID_CREDIT_RESERVATION_CONFLICT');
    end if;
    select wallet.* into v_wallet from public.wallets wallet
      join public.wallet_accounts account on account.wallet_id = wallet.id
     where account.id = v_request.charged_wallet_account_id for update of wallet;
    select account.* into v_account from public.wallet_accounts account
     where account.id = v_request.charged_wallet_account_id for update;
    if not found or v_account.currency <> v_quote.currency then
      return jsonb_build_object('ok', false, 'code', 'ORIGINAL_WALLET_CURRENCY_CONFLICT');
    end if;
    insert into public.wallet_ledger_entries (
      wallet_account_id, transaction_type, amount, currency,
      available_before, available_after, hold_before, hold_after,
      booking_id, reservation_id, ticket_management_request_id,
      ticket_management_quote_id, idempotency_key, created_by_user_id,
      created_by_role, remarks, metadata
    ) values (
      v_account.id, 'ticket_management_void_credit', v_quote.customer_amount,
      v_quote.currency, v_account.available_balance,
      v_account.available_balance + v_quote.customer_amount,
      v_account.hold_balance, v_account.hold_balance, v_booking.id, null,
      v_request.id, v_quote.id, p_request_key || ':credit',
      p_actor_user_id, v_actor_role,
      coalesce(nullif(btrim(p_note), ''), 'Ticket Management approved VOID credit'),
      jsonb_build_object('quoteHash', v_quote.quote_hash,
        'supplierGrossAmount', v_quote.supplier_gross_amount,
        'supplierPayableAmount', v_quote.supplier_payable_amount,
        'userPayableEntitlementConsumed', v_quote.user_payable_entitlement_amount,
        'airlineVoidFeeAmount', v_quote.void_fee,
        'serviceFeeAmount', v_quote.service_fee,
        'netCustomerCredit', v_quote.customer_amount)
    ) returning * into v_ledger;
    update public.wallet_accounts
       set available_balance = available_balance + v_quote.customer_amount
     where id = v_account.id;
    update public.flight_bookings
       set refunded_amount = refunded_amount + v_quote.customer_amount,
           payment_state = case
             when refunded_amount + v_quote.customer_amount = captured_amount
               then 'refunded' else 'partially-refunded' end
     where id = v_booking.id;
  elsif v_quote.direction = 'debit' then
    v_capture_result := public.ticket_management_capture_hold_v1(
      v_request.id, p_actor_user_id, p_request_key || ':capture'
    );
    if not coalesce((v_capture_result->>'ok')::boolean, false) then
      return v_capture_result;
    end if;
    v_capture_ledger_id := (v_capture_result->>'ledgerEntryId')::uuid;
    update public.flight_bookings
       set captured_amount = captured_amount + v_quote.customer_amount
     where id = v_booking.id;
  elsif v_request.active_wallet_reservation_id is not null then
    return jsonb_build_object('ok', false, 'code', 'VOID_ZERO_TOTAL_RESERVATION_CONFLICT');
  end if;

  v_payload_hash := encode(sha256(convert_to(jsonb_build_object(
    'requestId', v_request.id, 'quoteId', v_quote.id,
    'note', nullif(btrim(p_note), '')
  )::text, 'UTF8')), 'hex');
  insert into public.ticket_management_void_completions (
    request_id, quote_id, request_key, payload_hash, direction,
    supplier_gross_amount, supplier_payable_amount,
    user_payable_entitlement_amount, airline_void_fee_amount,
    service_fee_amount, customer_amount, credit_ledger_entry_id,
    capture_ledger_entry_id, finalized_by_user_id, finalized_by_role, note
  ) values (
    v_request.id, v_quote.id, p_request_key, v_payload_hash, v_quote.direction,
    v_quote.supplier_gross_amount, v_quote.supplier_payable_amount,
    v_quote.user_payable_entitlement_amount, v_quote.void_fee,
    v_quote.service_fee, v_quote.customer_amount, v_ledger.id,
    v_capture_ledger_id, p_actor_user_id, v_actor_role,
    nullif(btrim(p_note), '')
  ) returning * into v_completion;
  update public.ticket_management_ticket_entitlements entitlement
     set consumed_amount = entitlement.entitlement_amount, state = 'voided'
    from public.ticket_management_request_selections selection
   where selection.request_id = v_request.id
     and selection.entitlement_id = entitlement.id;
  update public.ticket_management_entitlement_claims
     set state = 'consumed', consumed_at = clock_timestamp()
   where request_id = v_request.id and state = 'active';
  update public.ticket_management_requests
     set status = 'completed', terminal_outcome = 'voided',
         completed_at = clock_timestamp(), status_changed_at = clock_timestamp(),
         credit_ledger_entry_id = v_ledger.id, version = version + 1
   where id = v_request.id returning version into v_version;
  if v_ledger.id is not null then
    perform public.ticket_management_append_event_v1(
      v_request.id, 'wallet-credited', 'approved', 'completed', v_version,
      p_actor_user_id, v_actor_role, p_request_key || ':wallet-credit', p_note,
      jsonb_build_object('ledgerEntryId', v_ledger.id,
        'amount', v_quote.customer_amount,
        'userPayableEntitlementConsumed', v_quote.user_payable_entitlement_amount)
    );
  end if;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'completed', 'approved', 'completed', v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':completed', p_note,
    jsonb_build_object('outcome', 'voided', 'quoteId', v_quote.id,
      'completionId', v_completion.id, 'direction', v_quote.direction,
      'ledgerEntryId', coalesce(v_ledger.id, v_capture_ledger_id),
      'supplierGrossAmount', v_quote.supplier_gross_amount,
      'supplierPayableAmount', v_quote.supplier_payable_amount,
      'userPayableEntitlementConsumed', v_quote.user_payable_entitlement_amount,
      'airlineVoidFeeAmount', v_quote.void_fee,
      'serviceFeeAmount', v_quote.service_fee,
      'customerAmount', v_quote.customer_amount)
  );
  return jsonb_build_object('ok', true, 'replay', false,
    'requestId', v_request.id, 'completionId', v_completion.id,
    'status', 'completed', 'outcome', 'voided', 'version', v_version,
    'direction', v_quote.direction,
    'ledgerEntryId', coalesce(v_ledger.id, v_capture_ledger_id),
    'customerAmount', v_quote.customer_amount,
    'consumedEntitlementAmount', v_quote.user_payable_entitlement_amount);
end;
$$;

create or replace function public.release_and_reopen_ticket_management_void_v1(
  p_request_id uuid,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request public.ticket_management_requests;
  v_quote public.ticket_management_quotes;
  v_existing_event public.ticket_management_request_events;
  v_release_result jsonb;
  v_release_ledger_id uuid;
  v_version integer;
begin
  if p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_request_key), '') is null
     or char_length(p_request_key) > 180
     or nullif(btrim(p_reason), '') is null
     or char_length(p_reason) > 2000 then
    raise exception 'invalid VOID release/reopen request' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_key, 0));
  select event.* into v_existing_event
    from public.ticket_management_request_events event
   where event.idempotency_key = p_request_key || ':reopened';
  if found then
    if v_existing_event.request_id is distinct from p_request_id
       or v_existing_event.actor_user_id is distinct from p_actor_user_id
       or v_existing_event.note is distinct from nullif(btrim(p_reason), '') then
      return jsonb_build_object('ok', false, 'code', 'VOID_RELEASE_IDEMPOTENCY_CONFLICT');
    end if;
    return jsonb_build_object('ok', true, 'replay', true,
      'requestId', p_request_id, 'status', v_existing_event.to_status,
      'version', v_existing_event.request_version,
      'ledgerEntryId', v_existing_event.metadata->>'releaseLedgerEntryId');
  end if;
  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_account', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'FINAL_SETTLEMENT_FORBIDDEN');
  end if;
  select request.* into v_request from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  if v_request.version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_VERSION_CONFLICT',
      'version', v_request.version);
  end if;
  if v_request.action <> 'void' or v_request.status <> 'approved'
     or v_request.active_assignee_user_id is distinct from p_actor_user_id
     or v_request.active_assignee_role is distinct from v_actor_role
     or v_request.approved_quote_id is null then
    return jsonb_build_object('ok', false, 'code', 'VOID_RELEASE_NOT_AUTHORIZED');
  end if;
  select quote.* into v_quote from public.ticket_management_quotes quote
   where quote.id = v_request.approved_quote_id and quote.request_id = v_request.id
   for update;
  if not found or v_quote.direction <> 'debit' then
    return jsonb_build_object('ok', false, 'code', 'VOID_HOLD_NOT_PRESENT');
  end if;
  v_release_result := public.ticket_management_release_hold_v1(
    v_request.id, p_actor_user_id, p_request_key || ':release', p_reason
  );
  if not coalesce((v_release_result->>'ok')::boolean, false) then
    return v_release_result;
  end if;
  v_release_ledger_id := (v_release_result->>'ledgerEntryId')::uuid;
  update public.ticket_management_requests
     set status = 'in-progress', active_quote_id = null,
         approved_quote_id = null, approved_at = null,
         active_assignment_id = null, active_assignee_user_id = null,
         active_assignee_role = null, assigned_at = null,
         active_wallet_reservation_id = null,
         hold_ledger_entry_id = null, capture_ledger_entry_id = null,
         release_ledger_entry_id = null,
         status_changed_at = clock_timestamp(), version = version + 1
   where id = v_request.id returning version into v_version;
  perform public.ticket_management_append_event_v1(
    v_request.id, 'requote-started', 'approved', 'in-progress', v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':reopened', p_reason,
    jsonb_build_object('supersededQuoteId', v_quote.id,
      'supersededQuoteVersion', v_quote.quote_version,
      'supersededQuoteHash', v_quote.quote_hash,
      'previousAssignmentId', v_request.active_assignment_id,
      'releaseLedgerEntryId', v_release_ledger_id,
      'manualVoidPerformed', false)
  );
  return jsonb_build_object('ok', true, 'replay', false,
    'requestId', v_request.id, 'status', 'in-progress',
    'version', v_version, 'releasedAmount', v_quote.customer_amount,
    'ledgerEntryId', v_release_ledger_id,
    'supersededQuoteId', v_quote.id);
end;
$$;

alter table public.ticket_management_void_completions enable row level security;
revoke all on public.ticket_management_void_completions
  from public, anon, authenticated;
grant select, insert on public.ticket_management_void_completions to service_role;

revoke all on function public.complete_ticket_management_void_v1(
  uuid, text, integer, text, text
) from public, anon, authenticated;
grant execute on function public.complete_ticket_management_void_v1(
  uuid, text, integer, text, text
) to service_role;
revoke all on function public.release_and_reopen_ticket_management_void_v1(
  uuid, text, integer, text, text
) from public, anon, authenticated;
grant execute on function public.release_and_reopen_ticket_management_void_v1(
  uuid, text, integer, text, text
) to service_role;

comment on function public.complete_ticket_management_void_v1(
  uuid, text, integer, text, text
) is
  'Assigned Accounts/Admin/Superadmin VOID completion. Atomically credits an approved net return or captures an approved additional-payment Hold on the original booking owner wallet, consumes ticket entitlement, and completes the request.';
comment on function public.release_and_reopen_ticket_management_void_v1(
  uuid, text, integer, text, text
) is
  'Assigned Accounts/Admin/Superadmin payable-VOID non-performance path. Atomically releases the request Hold and returns the request to In Progress for new quotation and customer approval.';


-- SOURCE: 0126_ticket_management_notification_outbox.sql
-- Transactional Ticket Management notification intents.
--
-- These rows are deliberately separate from booking-status notification
-- tables because Ticket Management statuses and audiences are a different
-- domain. This migration queues render-safe intents only; it does not send
-- email or expand real recipients.

create table public.ticket_management_notification_outbox (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null
    references public.ticket_management_request_events(id) on delete restrict,
  request_id uuid not null
    references public.ticket_management_requests(id) on delete restrict,
  audience text not null check (audience in ('customer', 'internal')),
  event_type text not null,
  occurrence_key text not null unique
    check (char_length(occurrence_key) between 1 and 255),
  snapshot jsonb not null check (jsonb_typeof(snapshot) = 'object'),
  state text not null default 'pending'
    check (state in ('pending', 'processing', 'processed', 'suppressed', 'dead-letter')),
  attempt_count integer not null default 0 check (attempt_count >= 0),
  available_at timestamptz not null default clock_timestamp(),
  claimed_at timestamptz,
  processed_at timestamptz,
  last_error text,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique (event_id, audience)
);

create index ticket_management_notification_pending_idx
  on public.ticket_management_notification_outbox(available_at, created_at, id)
  where state = 'pending';
create index ticket_management_notification_request_idx
  on public.ticket_management_notification_outbox(request_id, created_at, id);

create trigger ticket_management_notification_touch_updated_at
  before update on public.ticket_management_notification_outbox
  for each row execute function public.touch_updated_at();

create or replace function public.enqueue_ticket_management_notification_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_request public.ticket_management_requests;
  v_quote public.ticket_management_quotes;
  v_snapshot jsonb;
begin
  select request.* into strict v_request
    from public.ticket_management_requests request
   where request.id = new.request_id;
  if v_request.active_quote_id is not null or v_request.approved_quote_id is not null then
    select quote.* into v_quote
      from public.ticket_management_quotes quote
     where quote.id = coalesce(v_request.approved_quote_id, v_request.active_quote_id);
  end if;

  v_snapshot := jsonb_build_object(
    'version', 1,
    'requestPublicRef', v_request.public_ref,
    'action', v_request.action,
    'status', new.to_status,
    'eventType', new.event_type,
    'effectiveAt', new.effective_at,
    'currency', v_request.currency,
    'quote', case when v_quote.id is null then null else jsonb_build_object(
      'quoteVersion', v_quote.quote_version,
      'direction', v_quote.direction,
      'customerAmount', v_quote.customer_amount,
      'confirmationDeadlineAt', v_quote.confirmation_deadline_at
    ) end
  );

  if new.event_type in (
    'accepted', 'staff-rejected', 'quotation-published',
    'confirmation-expired', 'requote-started', 'completed'
  ) then
    insert into public.ticket_management_notification_outbox (
      event_id, request_id, audience, event_type, occurrence_key, snapshot
    ) values (
      new.id, new.request_id, 'customer', new.event_type,
      'ticket-management:' || new.id || ':customer', v_snapshot
    ) on conflict (event_id, audience) do nothing;
  end if;

  if new.event_type in (
    'requested', 'customer-approved', 'customer-rejected',
    'completed', 'financial-exception'
  ) then
    insert into public.ticket_management_notification_outbox (
      event_id, request_id, audience, event_type, occurrence_key, snapshot
    ) values (
      new.id, new.request_id, 'internal', new.event_type,
      'ticket-management:' || new.id || ':internal',
      v_snapshot || jsonb_build_object(
        'requestId', v_request.id,
        'activeAssigneeUserId', v_request.active_assignee_user_id,
        'activeAssigneeRole', v_request.active_assignee_role
      )
    ) on conflict (event_id, audience) do nothing;
  end if;
  return new;
end;
$$;

create trigger ticket_management_events_enqueue_notification
  after insert on public.ticket_management_request_events
  for each row execute function public.enqueue_ticket_management_notification_v1();

alter table public.ticket_management_notification_outbox enable row level security;
revoke all on public.ticket_management_notification_outbox
  from public, anon, authenticated;
grant select on public.ticket_management_notification_outbox to service_role;
revoke all on function public.enqueue_ticket_management_notification_v1()
  from public, anon, authenticated, service_role;

comment on table public.ticket_management_notification_outbox is
  'Transactional render-safe Ticket Management notification intents. Recipient expansion and delivery remain disabled until separately approved.';


-- SOURCE: 0127_generic_wallet_authorization_hardening.sql
-- Generic wallet authorization hardening.
--
-- Support may inspect wallet queues and reports through the application, but
-- only Accounts/Admin/Superadmin may create or review unrestricted manual
-- adjustments. The database mirror in app_users is the canonical role source;
-- caller-supplied role text is never accepted as authority.

create or replace function public.enforce_wallet_adjustment_request_actor_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
begin
  if tg_op = 'UPDATE' then
    if new.requested_by_user_id is distinct from old.requested_by_user_id
       or new.requested_by_role is distinct from old.requested_by_role then
      raise exception 'adjustment requester identity is immutable'
        using errcode = '55000';
    end if;
    return new;
  end if;

  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = new.requested_by_user_id;
  if v_actor_role not in ('superadmin', 'admin', 'staff_account') then
    raise exception 'WALLET_ADJUSTMENT_CREATE_FORBIDDEN'
      using errcode = '42501';
  end if;
  if new.requested_by_role is distinct from v_actor_role then
    raise exception 'WALLET_ACTOR_ROLE_MISMATCH'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists wallet_adjustment_request_actor_guard
  on public.wallet_adjustment_requests;
create trigger wallet_adjustment_request_actor_guard
  before insert or update of requested_by_user_id, requested_by_role
  on public.wallet_adjustment_requests
  for each row execute function public.enforce_wallet_adjustment_request_actor_v1();

create or replace function public.wallet_review_adjustment(
  p_request_id uuid,
  p_decision text,
  p_actor_user_id text,
  p_actor_role text,
  p_review_remarks text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request public.wallet_adjustment_requests;
  v_account public.wallet_accounts;
  v_wallet public.wallets;
  v_entry_id uuid;
  v_after bigint;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'invalid adjustment decision' using errcode = '22023';
  end if;
  if nullif(btrim(p_actor_user_id), '') is null then
    raise exception 'invalid adjustment actor' using errcode = '22023';
  end if;

  select app_user.role into v_actor_role
    from public.app_users app_user
   where app_user.clerk_id = p_actor_user_id;
  if v_actor_role not in ('superadmin', 'admin', 'staff_account') then
    return jsonb_build_object(
      'ok', false, 'code', 'WALLET_ADJUSTMENT_REVIEW_FORBIDDEN'
    );
  end if;
  if p_actor_role is distinct from v_actor_role then
    return jsonb_build_object(
      'ok', false, 'code', 'WALLET_ACTOR_ROLE_MISMATCH'
    );
  end if;

  select * into v_request from public.wallet_adjustment_requests
   where id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_request.status <> 'pending' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_REVIEWED');
  end if;
  if v_request.requested_by_user_id = p_actor_user_id then
    return jsonb_build_object('ok', false, 'code', 'SELF_APPROVAL_FORBIDDEN');
  end if;
  if p_decision = 'rejected' then
    update public.wallet_adjustment_requests set
      status = 'rejected', reviewed_by_user_id = p_actor_user_id,
      review_remarks = p_review_remarks, reviewed_at = now()
    where id = p_request_id;
    return jsonb_build_object('ok', true, 'status', 'rejected');
  end if;

  select w.* into strict v_wallet
    from public.wallets w
    join public.wallet_accounts wa on wa.wallet_id = w.id
   where wa.id = v_request.wallet_account_id
   for update of w;
  select * into strict v_account
    from public.wallet_accounts
   where id = v_request.wallet_account_id
   for update;
  if v_request.adjustment_type = 'debit' and v_wallet.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'WALLET_FROZEN');
  end if;
  if v_request.adjustment_type = 'debit'
     and v_account.available_balance < v_request.amount then
    return jsonb_build_object('ok', false, 'code', 'INSUFFICIENT_FUNDS',
      'available', v_account.available_balance, 'required', v_request.amount);
  end if;
  v_after := v_account.available_balance +
    case when v_request.adjustment_type = 'credit'
      then v_request.amount else -v_request.amount end;
  insert into public.wallet_ledger_entries (
    wallet_account_id, transaction_type, amount, currency,
    available_before, available_after, hold_before, hold_after,
    idempotency_key, created_by_user_id, created_by_role, remarks,
    metadata
  ) values (
    v_account.id,
    case when v_request.adjustment_type = 'credit'
      then 'manual_credit' else 'manual_debit' end,
    v_request.amount, v_request.currency,
    v_account.available_balance, v_after,
    v_account.hold_balance, v_account.hold_balance,
    'adjustment:' || v_request.id, p_actor_user_id, v_actor_role,
    v_request.reason,
    jsonb_build_object('requestedBy', v_request.requested_by_user_id)
  ) returning id into v_entry_id;
  update public.wallet_accounts set available_balance = v_after
   where id = v_account.id;
  update public.wallet_adjustment_requests set
    status = 'approved', reviewed_by_user_id = p_actor_user_id,
    review_remarks = p_review_remarks, reviewed_at = now(),
    ledger_entry_id = v_entry_id
  where id = p_request_id;
  return jsonb_build_object('ok', true, 'status', 'approved',
    'availableBalance', v_after);
end;
$$;

revoke all on function public.enforce_wallet_adjustment_request_actor_v1()
  from public, anon, authenticated;
grant execute on function public.enforce_wallet_adjustment_request_actor_v1()
  to service_role;

revoke all on function public.wallet_review_adjustment(
  uuid, text, text, text, text
) from public, anon, authenticated;
grant execute on function public.wallet_review_adjustment(
  uuid, text, text, text, text
