-- SOURCE: 0133_ticket_management_notification_recipient_hash.sql
-- PGlite-compatible recipient hashing for the Ticket Management outbox.
-- The value is an idempotency/deduplication key, not a password or security
-- credential. It keeps the raw email out of the unique-key lookup surface.

create or replace function public.expand_ticket_management_notification_recipients_v1(
  p_outbox_id uuid,
  p_claim_token uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_outbox public.ticket_management_notification_outbox;
  v_count integer;
begin
  select candidate.* into v_outbox
    from public.ticket_management_notification_outbox candidate
   where candidate.id = p_outbox_id
   for update;
  if not found or v_outbox.state <> 'processing'
     or v_outbox.claim_token is distinct from p_claim_token then
    raise exception 'notification outbox claim mismatch' using errcode = '40001';
  end if;

  if v_outbox.recipients_expanded_at is null then
    insert into public.ticket_management_notification_deliveries (
      outbox_id, recipient_kind, recipient_address, recipient_address_hash
    )
    select p_outbox_id, recipient.kind, recipient.address, md5(recipient.address)
      from (
        select distinct on (address) kind, address
          from (
            select 'requester'::text as kind, lower(btrim(app_user.email)) as address
              from public.ticket_management_requests request
              join public.app_users app_user
                on app_user.clerk_id = request.requested_by_user_id
             where request.id = v_outbox.request_id
               and v_outbox.audience = 'customer'
            union all
            select 'booking_user', lower(btrim(app_user.email))
              from public.ticket_management_requests request
              join public.flight_bookings booking on booking.id = request.booking_id
              join public.app_users app_user on app_user.clerk_id = booking.user_id
             where request.id = v_outbox.request_id
               and v_outbox.audience = 'customer'
            union all
            select 'booking_contact', lower(btrim(booking.passengers #>> '{contact,customerEmail}'))
              from public.ticket_management_requests request
              join public.flight_bookings booking on booking.id = request.booking_id
             where request.id = v_outbox.request_id
               and v_outbox.audience = 'customer'
            union all
            select 'internal_staff', lower(btrim(app_user.email))
              from public.app_users app_user
             where v_outbox.audience = 'internal'
               and app_user.role in ('staff_support', 'staff_account', 'admin', 'superadmin')
          ) candidates
         where address ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
           and char_length(address) <= 320
         order by address, kind
      ) recipient
    on conflict (outbox_id, recipient_address_hash) do nothing;

    select count(*)::integer into v_count
      from public.ticket_management_notification_deliveries delivery
     where delivery.outbox_id = p_outbox_id;
    if v_count = 0 then
      raise exception 'notification has no recipient' using errcode = '23514';
    end if;
    update public.ticket_management_notification_outbox
       set recipients_expanded_at = clock_timestamp()
     where id = p_outbox_id;
  end if;
  select count(*)::integer into v_count
    from public.ticket_management_notification_deliveries delivery
   where delivery.outbox_id = p_outbox_id;
  return v_count;
end;
$$;

comment on function public.expand_ticket_management_notification_recipients_v1(uuid, uuid) is
  'Expands one immutable audience recipient set. The normalized address hash is used solely for idempotent delivery deduplication.';


-- SOURCE: 0134_ticket_management_request_type.sql
-- Persist the Voluntary/Involuntary classification for every Ticket
-- Management request. Historical requests predate this field, so they retain
-- the safe default of voluntary rather than being inferred from free text.

alter table public.ticket_management_requests
  add column request_type text not null default 'voluntary'
    check (request_type in ('voluntary', 'involuntary'));

create index ticket_management_requests_action_type_status_idx
  on public.ticket_management_requests(action, request_type, status, created_at desc, id);

create or replace function public.create_ticket_management_request_v3(
  p_booking_id uuid,
  p_action text,
  p_actor_user_id text,
  p_request_key text,
  p_request_payload_hash text,
  p_passenger_indexes integer[],
  p_request_type text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
  v_request_type text := lower(btrim(coalesce(p_request_type, '')));
begin
  if v_request_type not in ('voluntary', 'involuntary') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST_TYPE');
  end if;

  v_result := public.create_ticket_management_request_v2(
    p_booking_id, p_action, p_actor_user_id, p_request_key,
    p_request_payload_hash, p_passenger_indexes, p_note
  );
  if not coalesce((v_result->>'ok')::boolean, false) then
    return v_result;
  end if;

  -- The v2 creation path performs all owner, entitlement, and idempotency
  -- checks. This update runs in the same transaction and writes the selected
  -- category before the request becomes visible to readers.
  update public.ticket_management_requests
     set request_type = v_request_type
   where id = (v_result->>'requestId')::uuid;

  return v_result || jsonb_build_object('requestType', v_request_type);
end;
$$;

revoke all on function public.create_ticket_management_request_v3(
  uuid, text, text, text, text, integer[], text, text
) from public, anon, authenticated;
grant execute on function public.create_ticket_management_request_v3(
  uuid, text, text, text, text, integer[], text, text
) to service_role;

comment on column public.ticket_management_requests.request_type is
  'Customer-declared Ticket Management category: voluntary or involuntary. Historical records default to voluntary and are not inferred from notes.';
comment on function public.create_ticket_management_request_v3(
  uuid, text, text, text, text, integer[], text, text
) is
  'Creates an owner-authorized Ticket Management request with a persisted Voluntary/Involuntary category.';


-- SOURCE: 0135_ticket_management_approved_final_status.sql
-- Keep the public lifecycle to the agreed seven stages:
-- Requested -> In Progress -> Quotation -> Approved | Rejected | Expired.
-- A successful wallet/ticket settlement is an immutable audit event and final
-- outcome of Approved; it must not move the request into a separate Completed
-- stage.

alter table public.ticket_management_requests
  drop constraint ticket_management_requests_terminal_state_check,
  drop constraint ticket_management_requests_action_outcome_check,
  drop constraint ticket_management_requests_status_timestamps_check;

alter table public.ticket_management_requests
  add constraint ticket_management_requests_terminal_state_check
    check (
      (status in ('approved', 'completed') and terminal_outcome in ('refunded', 'reissued', 'voided'))
      or (status = 'rejected' and terminal_outcome in ('staff-rejected', 'customer-rejected'))
      or (status = 'expired' and terminal_outcome = 'confirmation-expired')
      or (
        status in ('requested', 'in-progress', 'awaiting-confirmation', 'approved', 'completed')
        and terminal_outcome is null
      )
    ),
  add constraint ticket_management_requests_action_outcome_check
    check (
      terminal_outcome is null
      or (action = 'refund' and terminal_outcome = 'refunded')
      or (action = 'reissue' and terminal_outcome = 'reissued')
      or (action = 'void' and terminal_outcome = 'voided')
      or terminal_outcome in ('staff-rejected', 'customer-rejected', 'confirmation-expired')
    ),
  add constraint ticket_management_requests_status_timestamps_check
    check (
      (terminal_outcome not in ('refunded', 'reissued', 'voided') or completed_at is not null)
      and (status <> 'rejected' or rejected_at is not null)
      and (status <> 'expired' or expired_at is not null)
    );

-- Normalize historical settlements without changing their immutable completion
-- records, ledger entries, amounts, or event timestamps.
update public.ticket_management_requests
   set status = 'approved'
 where status = 'completed'
   and terminal_outcome in ('refunded', 'reissued', 'voided');

create or replace function public.complete_ticket_management_refund_v2(
  p_request_id uuid,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_prepared jsonb;
  v_result jsonb;
begin
  v_prepared := public.ticket_management_prepare_direct_settlement_v1(
    p_request_id, p_actor_user_id, p_expected_version, p_request_key
  );
  if not coalesce((v_prepared->>'ok')::boolean, false) then return v_prepared; end if;
  v_result := public.complete_ticket_management_refund_v1(
    p_request_id, p_actor_user_id,
    (v_prepared->>'settlementVersion')::integer,
    p_request_key, p_note
  );
  if not coalesce((v_result->>'ok')::boolean, false) then return v_result; end if;
  update public.ticket_management_requests
     set status = 'approved'
   where id = p_request_id
     and status = 'completed'
     and terminal_outcome = 'refunded';
  return v_result || jsonb_build_object('status', 'approved');
end;
$$;

