-- SOURCE: 0136_ticket_management_preserve_approved_settlement_time.sql
-- 0135 was already applied to normalize legacy Completed requests. Restore the
-- original settlement timestamp for those now-Approved terminal outcomes so
-- the Manage table continues to show the actual action time.

update public.ticket_management_requests
   set status_changed_at = completed_at
 where status = 'approved'
   and terminal_outcome in ('refunded', 'reissued', 'voided')
   and completed_at is not null;


-- SOURCE: 0137_ticket_management_action_reference_prefix.sql
-- Make Ticket Management references self-describing without changing their
-- unique UUID-derived suffix:
--   TMRR = Refund, TMRE = Reissue/Exchange, TMRV = VOID.

alter table public.ticket_management_requests
  drop constraint ticket_management_requests_public_ref_check;

alter table public.ticket_management_requests
  alter column public_ref drop default;

update public.ticket_management_requests
   set public_ref = case action
     when 'refund' then 'TMRR' || substring(public_ref from 4)
     when 'reissue' then 'TMRE' || substring(public_ref from 4)
     when 'void' then 'TMRV' || substring(public_ref from 4)
   end
 where public_ref ~ '^TMR[A-F0-9]{12}$';

alter table public.ticket_management_requests
  add constraint ticket_management_requests_public_ref_check
    check (public_ref ~ '^TMR[REV][A-F0-9]{12}$');

create or replace function public.assign_ticket_management_public_ref_v1()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  -- The old generic TMR default is treated as an automatic value and replaced.
  -- Explicit valid action-prefixed references remain available for controlled
  -- data imports.
  if new.public_ref is null or new.public_ref ~ '^TMR[A-F0-9]{12}$' then
    new.public_ref := case new.action
      when 'refund' then 'TMRR'
      when 'reissue' then 'TMRE'
      when 'void' then 'TMRV'
    end || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
  end if;
  return new;
end;
$$;

drop trigger if exists ticket_management_requests_assign_public_ref
  on public.ticket_management_requests;
create trigger ticket_management_requests_assign_public_ref
  before insert on public.ticket_management_requests
  for each row execute function public.assign_ticket_management_public_ref_v1();

comment on column public.ticket_management_requests.public_ref is
  'Action-specific Ticket Management reference: TMRR (Refund), TMRE (Reissue/Exchange), or TMRV (VOID), followed by 12 uppercase hexadecimal characters.';


-- SOURCE: 0138_flight_search_usage_controls.sql
-- Super Admin flight-search usage reporting and atomic daily API budgets.
--
-- `flight_search_history` is intentionally unsuitable for billing/usage: it
-- deduplicates repeated searches and records successful signed-in searches
-- only. This ledger stores one row for every validated request that reaches
-- the application controls, while `supplier_api_hit` distinguishes a website
-- request from an outbound supplier Search attempt.

create table if not exists public.flight_search_supplier_limits (
  supplier text primary key check (supplier in ('firsttrip', 'takeoff')),
  daily_limit integer check (daily_limit is null or daily_limit between 0 and 1000000),
  version integer not null default 1 check (version > 0),
  updated_by_user_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

insert into public.flight_search_supplier_limits (supplier, daily_limit)
values ('firsttrip', null), ('takeoff', null)
on conflict (supplier) do nothing;

create table if not exists public.flight_search_user_controls (
  user_id text primary key references public.app_users (clerk_id) on delete cascade,
  search_enabled boolean not null default true,
  daily_limit integer check (daily_limit is null or daily_limit between 1 and 1000000),
  version integer not null default 1 check (version > 0),
  updated_by_user_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.flight_search_daily_counters (
  scope_type text not null check (scope_type in ('supplier', 'user')),
  scope_key text not null check (char_length(scope_key) between 1 and 255),
  usage_date date not null,
  hit_count integer not null default 0 check (hit_count >= 0),
  updated_at timestamptz not null default now(),
  primary key (scope_type, scope_key, usage_date)
);

create table if not exists public.flight_search_usage_events (
  id uuid primary key default gen_random_uuid(),
  trace_id uuid not null unique,
  actor_user_id text references public.app_users (clerk_id) on delete set null,
  actor_key_hash text not null check (actor_key_hash ~ '^sha256:[0-9a-f]{64}$'),
  actor_role text,
  agency_code text,
  supplier_account text not null check (supplier_account in ('firsttrip', 'takeoff')),
  request_mode text not null check (request_mode in ('stream', 'json')),
  trip_type text not null check (trip_type in ('oneway', 'round', 'multicity')),
  routes jsonb not null check (jsonb_typeof(routes) = 'array'),
  adults smallint not null check (adults between 1 and 9),
  children smallint not null check (children between 0 and 8),
  infants smallint not null check (infants between 0 and 9),
  cabin_class smallint not null check (cabin_class between 1 and 5),
  outcome text not null default 'received' check (
    outcome in (
      'received', 'supplier_called', 'success', 'failed', 'rate_limited',
      'busy', 'user_disabled', 'user_daily_limit', 'supplier_daily_limit'
    )
  ),
  supplier_api_hit boolean not null default false,
  http_status smallint check (http_status is null or http_status between 100 and 599),
  error_code text check (error_code is null or char_length(error_code) between 1 and 80),
  itinerary_count integer check (itinerary_count is null or itinerary_count >= 0),
  partial boolean,
  total_ms integer check (total_ms is null or total_ms >= 0),
  supplier_ms integer check (supplier_ms is null or supplier_ms >= 0),
  usage_date date not null default (timezone('Asia/Dhaka', now())::date),
  created_at timestamptz not null default now(),
  completed_at timestamptz
);

create index if not exists flight_search_usage_events_created_idx
  on public.flight_search_usage_events (created_at desc, id);
create index if not exists flight_search_usage_events_user_created_idx
  on public.flight_search_usage_events (actor_user_id, created_at desc)
  where actor_user_id is not null;
create index if not exists flight_search_usage_events_supplier_created_idx
  on public.flight_search_usage_events (supplier_account, created_at desc);
create index if not exists flight_search_usage_events_supplier_hit_idx
  on public.flight_search_usage_events (usage_date, supplier_account, created_at desc)
  where supplier_api_hit;

alter table public.flight_search_supplier_limits enable row level security;
alter table public.flight_search_user_controls enable row level security;
alter table public.flight_search_daily_counters enable row level security;
alter table public.flight_search_usage_events enable row level security;

revoke all on table public.flight_search_supplier_limits,
  public.flight_search_user_controls,
  public.flight_search_daily_counters,
  public.flight_search_usage_events from anon, authenticated;
grant select, insert, update, delete on table public.flight_search_supplier_limits,
  public.flight_search_user_controls,
  public.flight_search_daily_counters,
  public.flight_search_usage_events to service_role;

-- Atomically reserves one outbound supplier Search attempt. Locks always use
-- supplier then user order, preventing two concurrent requests from crossing
-- either configured daily ceiling.
create or replace function public.claim_flight_search_supplier_hit_v1(
  p_event_id uuid,
  p_supplier text,
  p_user_id text
)
returns table (
  allowed boolean,
  result_code text,
  supplier_count integer,
  supplier_limit integer,
  user_count integer,
  user_limit integer
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_today date := timezone('Asia/Dhaka', clock_timestamp())::date;
  v_supplier_count integer := 0;
  v_supplier_limit integer;
  v_user_count integer := 0;
  v_user_limit integer;
  v_user_enabled boolean := true;
  v_code text;
begin
  if p_supplier not in ('firsttrip', 'takeoff') then
    raise exception 'unsupported supplier' using errcode = '22023';
  end if;

  insert into public.flight_search_daily_counters (
    scope_type, scope_key, usage_date, hit_count
  ) values ('supplier', p_supplier, v_today, 0)
  on conflict do nothing;

  select counter.hit_count into v_supplier_count
    from public.flight_search_daily_counters counter
   where counter.scope_type = 'supplier'
     and counter.scope_key = p_supplier
     and counter.usage_date = v_today
   for update;

  select limits.daily_limit into v_supplier_limit
    from public.flight_search_supplier_limits limits
   where limits.supplier = p_supplier;

  if p_user_id is not null then
    insert into public.flight_search_daily_counters (
      scope_type, scope_key, usage_date, hit_count
    ) values ('user', p_user_id, v_today, 0)
    on conflict do nothing;

    select counter.hit_count into v_user_count
      from public.flight_search_daily_counters counter
     where counter.scope_type = 'user'
       and counter.scope_key = p_user_id
       and counter.usage_date = v_today
     for update;

    select controls.search_enabled, controls.daily_limit
      into v_user_enabled, v_user_limit
      from public.flight_search_user_controls controls
     where controls.user_id = p_user_id;
    if not found then
      v_user_enabled := true;
      v_user_limit := null;
    end if;
  end if;

  v_code := case
    when p_user_id is not null and not v_user_enabled then 'USER_SEARCH_DISABLED'
    when p_user_id is not null and v_user_limit is not null
      and v_user_count >= v_user_limit then 'USER_DAILY_LIMIT_REACHED'
    when v_supplier_limit is not null and v_supplier_count >= v_supplier_limit
      then 'SUPPLIER_DAILY_LIMIT_REACHED'
    else 'ALLOWED'
  end;

  if v_code <> 'ALLOWED' then
    update public.flight_search_usage_events
       set outcome = case v_code
             when 'USER_SEARCH_DISABLED' then 'user_disabled'
             when 'USER_DAILY_LIMIT_REACHED' then 'user_daily_limit'
             else 'supplier_daily_limit'
           end,
           http_status = case when v_code = 'USER_SEARCH_DISABLED' then 403
                              when v_code = 'USER_DAILY_LIMIT_REACHED' then 429
                              else 503 end,
           error_code = v_code,
           completed_at = clock_timestamp()
     where id = p_event_id;
    return query select false, v_code, v_supplier_count, v_supplier_limit,
      v_user_count, v_user_limit;
    return;
  end if;

  update public.flight_search_daily_counters
     set hit_count = hit_count + 1,
         updated_at = clock_timestamp()
   where scope_type = 'supplier' and scope_key = p_supplier and usage_date = v_today;
  v_supplier_count := v_supplier_count + 1;

  if p_user_id is not null then
    update public.flight_search_daily_counters
       set hit_count = hit_count + 1,
           updated_at = clock_timestamp()
     where scope_type = 'user' and scope_key = p_user_id and usage_date = v_today;
    v_user_count := v_user_count + 1;
  end if;

  update public.flight_search_usage_events
     set supplier_api_hit = true,
         outcome = 'supplier_called'
   where id = p_event_id;

  return query select true, 'ALLOWED'::text, v_supplier_count, v_supplier_limit,
    v_user_count, v_user_limit;
end;
$$;

revoke all on function public.claim_flight_search_supplier_hit_v1(
  uuid, text, text
) from public, anon, authenticated;
grant execute on function public.claim_flight_search_supplier_hit_v1(
  uuid, text, text
) to service_role;

create or replace function public.flight_search_usage_totals_v1(
  p_from timestamptz,
  p_to timestamptz
)
returns table (
  request_count bigint,
  supplier_api_hit_count bigint,
  success_count bigint,
  failed_count bigint,
  blocked_count bigint,
  anonymous_count bigint,
  unique_user_count bigint,
  average_total_ms numeric
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select
    count(*)::bigint,
    count(*) filter (where event.supplier_api_hit)::bigint,
    count(*) filter (where event.outcome = 'success')::bigint,
    count(*) filter (where event.outcome = 'failed')::bigint,
    count(*) filter (where event.outcome in (
      'rate_limited', 'busy', 'user_disabled', 'user_daily_limit',
      'supplier_daily_limit'
    ))::bigint,
    count(*) filter (where event.actor_user_id is null)::bigint,
    count(distinct event.actor_user_id)::bigint,
    round(avg(event.total_ms), 2)
  from public.flight_search_usage_events event
  where event.created_at >= p_from and event.created_at < p_to;
$$;

create or replace function public.flight_search_usage_by_actor_v1(
  p_from timestamptz,
  p_to timestamptz
)
returns table (
  user_id text,
  display_name text,
  email text,
  role text,
  agency_code text,
  request_count bigint,
  supplier_api_hit_count bigint,
  success_count bigint,
  failed_count bigint,
  blocked_count bigint,
  last_search_at timestamptz,
  average_total_ms numeric,
  search_enabled boolean,
  daily_limit integer,
  control_version integer,
  today_hit_count integer
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with usage as (
    select
      event.actor_user_id,
      count(*)::bigint as request_count,
      count(*) filter (where event.supplier_api_hit)::bigint as hit_count,
      count(*) filter (where event.outcome = 'success')::bigint as success_count,
      count(*) filter (where event.outcome = 'failed')::bigint as failed_count,
      count(*) filter (where event.outcome in (
        'rate_limited', 'busy', 'user_disabled', 'user_daily_limit',
        'supplier_daily_limit'
      ))::bigint as blocked_count,
      max(event.created_at) as last_search_at,
      round(avg(event.total_ms), 2) as average_total_ms
    from public.flight_search_usage_events event
    where event.created_at >= p_from and event.created_at < p_to
    group by event.actor_user_id
  ), rows as (
    select
      usr.clerk_id as user_id,
      nullif(trim(concat_ws(' ', usr.first_name, usr.last_name)), '') as display_name,
      usr.email,
      usr.role,
      usr.agency_code,
      coalesce(usage.request_count, 0)::bigint as request_count,
      coalesce(usage.hit_count, 0)::bigint as hit_count,
      coalesce(usage.success_count, 0)::bigint as success_count,
      coalesce(usage.failed_count, 0)::bigint as failed_count,
      coalesce(usage.blocked_count, 0)::bigint as blocked_count,
      usage.last_search_at,
      usage.average_total_ms,
      coalesce(control.search_enabled, true) as search_enabled,
      control.daily_limit,
      coalesce(control.version, 0) as control_version,
      coalesce(counter.hit_count, 0) as today_hit_count
    from public.app_users usr
    left join usage on usage.actor_user_id = usr.clerk_id
    left join public.flight_search_user_controls control
      on control.user_id = usr.clerk_id
    left join public.flight_search_daily_counters counter
      on counter.scope_type = 'user'
     and counter.scope_key = usr.clerk_id
     and counter.usage_date = timezone('Asia/Dhaka', clock_timestamp())::date
    union all
    select
      null, 'Anonymous visitors', null, 'anonymous', null,
      usage.request_count, usage.hit_count, usage.success_count,
      usage.failed_count, usage.blocked_count, usage.last_search_at,
      usage.average_total_ms, true, null, 0, 0
    from usage where usage.actor_user_id is null
  )
  select * from rows
  order by request_count desc, last_search_at desc nulls last, user_id;
$$;

create or replace function public.flight_search_usage_by_supplier_v1(
  p_from timestamptz,
  p_to timestamptz
)
returns table (
  supplier text,
  request_count bigint,
  supplier_api_hit_count bigint,
  success_count bigint,
  failed_count bigint,
  blocked_count bigint,
  last_search_at timestamptz,
  daily_limit integer,
  limit_version integer,
  today_hit_count integer
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select
    limits.supplier,
    count(event.id)::bigint,
    count(event.id) filter (where event.supplier_api_hit)::bigint,
    count(event.id) filter (where event.outcome = 'success')::bigint,
    count(event.id) filter (where event.outcome = 'failed')::bigint,
    count(event.id) filter (where event.outcome = 'supplier_daily_limit')::bigint,
    max(event.created_at),
    limits.daily_limit,
    limits.version,
    coalesce(counter.hit_count, 0)
  from public.flight_search_supplier_limits limits
  left join public.flight_search_usage_events event
    on event.supplier_account = limits.supplier
   and event.created_at >= p_from and event.created_at < p_to
  left join public.flight_search_daily_counters counter
    on counter.scope_type = 'supplier'
   and counter.scope_key = limits.supplier
   and counter.usage_date = timezone('Asia/Dhaka', clock_timestamp())::date
  group by limits.supplier, limits.daily_limit, limits.version, counter.hit_count
  order by limits.supplier;
$$;

revoke all on function public.flight_search_usage_totals_v1(
  timestamptz, timestamptz
), public.flight_search_usage_by_actor_v1(
  timestamptz, timestamptz
), public.flight_search_usage_by_supplier_v1(
  timestamptz, timestamptz
) from public, anon, authenticated;
grant execute on function public.flight_search_usage_totals_v1(
  timestamptz, timestamptz
), public.flight_search_usage_by_actor_v1(
  timestamptz, timestamptz
), public.flight_search_usage_by_supplier_v1(
  timestamptz, timestamptz
) to service_role;

comment on table public.flight_search_usage_events is
  'One row per validated flight-search request; supplier_api_hit marks an outbound supplier Search attempt.';
comment on table public.flight_search_daily_counters is
  'Atomic Asia/Dhaka-day counters used to enforce supplier and signed-in-user Search budgets.';


-- SOURCE: 0139_flight_search_actor_routes_and_agencies.sql
-- Add agency-first identity and searched-route summaries to the Super Admin
-- flight-search report without changing the immutable v1 reporting contract.

create or replace function public.flight_search_usage_by_actor_v2(
  p_from timestamptz,
  p_to timestamptz
)
returns table (
  user_id text,
  display_name text,
  email text,
  role text,
  agency_code text,
  agency_name text,
  searched_routes jsonb,
  distinct_route_count bigint,
  request_count bigint,
  supplier_api_hit_count bigint,
  success_count bigint,
  failed_count bigint,
  blocked_count bigint,
  last_search_at timestamptz,
  average_total_ms numeric,
  search_enabled boolean,
  daily_limit integer,
  control_version integer,
  today_hit_count integer
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with usage as (
    select
      event.actor_user_id,
      count(*)::bigint as request_count,
      count(*) filter (where event.supplier_api_hit)::bigint as hit_count,
      count(*) filter (where event.outcome = 'success')::bigint as success_count,
      count(*) filter (where event.outcome = 'failed')::bigint as failed_count,
      count(*) filter (where event.outcome in (
        'rate_limited', 'busy', 'user_disabled', 'user_daily_limit',
        'supplier_daily_limit'
      ))::bigint as blocked_count,
      max(event.created_at) as last_search_at,
      round(avg(event.total_ms), 2) as average_total_ms
    from public.flight_search_usage_events event
    where event.created_at >= p_from and event.created_at < p_to
    group by event.actor_user_id
  ), event_routes as (
    select
      event.id,
      event.actor_user_id,
      string_agg(
        upper(segment.value ->> 'origin') || ' → ' ||
          upper(segment.value ->> 'destination'),
        ' / ' order by segment.ordinality
      ) as route_label
    from public.flight_search_usage_events event
    cross join lateral jsonb_array_elements(event.routes)
      with ordinality as segment(value, ordinality)
    where event.created_at >= p_from and event.created_at < p_to
      and nullif(trim(segment.value ->> 'origin'), '') is not null
      and nullif(trim(segment.value ->> 'destination'), '') is not null
    group by event.id, event.actor_user_id
  ), route_counts as (
    select
      event_routes.actor_user_id,
      event_routes.route_label,
      count(*)::bigint as request_count
    from event_routes
    group by event_routes.actor_user_id, event_routes.route_label
  ), ranked_routes as (
    select
      route_counts.*,
      row_number() over (
        partition by route_counts.actor_user_id
        order by route_counts.request_count desc, route_counts.route_label
      ) as route_rank,
      count(*) over (partition by route_counts.actor_user_id)::bigint
        as distinct_route_count
    from route_counts
  ), route_summary as (
    select
      ranked_routes.actor_user_id,
      jsonb_agg(
        jsonb_build_object(
          'route', ranked_routes.route_label,
          'requestCount', ranked_routes.request_count
        ) order by ranked_routes.request_count desc, ranked_routes.route_label
      ) filter (where ranked_routes.route_rank <= 50) as searched_routes,
      max(ranked_routes.distinct_route_count)::bigint as distinct_route_count
    from ranked_routes
    group by ranked_routes.actor_user_id
  ), rows as (
    select
      usr.clerk_id as user_id,
      nullif(trim(concat_ws(' ', usr.first_name, usr.last_name)), '') as display_name,
      usr.email,
      usr.role,
      usr.agency_code,
      case when usr.role in ('b2b', 'b2b_sub') then
        nullif(trim(agency_profile.agency_name), '')
      else null end as agency_name,
      coalesce(route_summary.searched_routes, '[]'::jsonb) as searched_routes,
      coalesce(route_summary.distinct_route_count, 0)::bigint as distinct_route_count,
      coalesce(usage.request_count, 0)::bigint as request_count,
      coalesce(usage.hit_count, 0)::bigint as hit_count,
      coalesce(usage.success_count, 0)::bigint as success_count,
      coalesce(usage.failed_count, 0)::bigint as failed_count,
      coalesce(usage.blocked_count, 0)::bigint as blocked_count,
      usage.last_search_at,
      usage.average_total_ms,
      coalesce(control.search_enabled, true) as search_enabled,
      control.daily_limit,
      coalesce(control.version, 0) as control_version,
      coalesce(counter.hit_count, 0) as today_hit_count
    from public.app_users usr
    left join usage on usage.actor_user_id = usr.clerk_id
    left join route_summary on route_summary.actor_user_id = usr.clerk_id
    left join public.agencies agency on agency.agency_code = usr.agency_code
    left join public.user_profiles agency_profile
      on agency_profile.clerk_id = coalesce(
        agency.owner_user_id,
        case when usr.role = 'b2b' then usr.clerk_id else null end
      )
    left join public.flight_search_user_controls control
      on control.user_id = usr.clerk_id
    left join public.flight_search_daily_counters counter
      on counter.scope_type = 'user'
     and counter.scope_key = usr.clerk_id
     and counter.usage_date = timezone('Asia/Dhaka', clock_timestamp())::date
    union all
    select
      null, 'Anonymous visitors', null, 'anonymous', null, null,
      coalesce(route_summary.searched_routes, '[]'::jsonb),
      coalesce(route_summary.distinct_route_count, 0)::bigint,
      usage.request_count, usage.hit_count, usage.success_count,
      usage.failed_count, usage.blocked_count, usage.last_search_at,
      usage.average_total_ms, true, null, 0, 0
    from usage
    left join route_summary on route_summary.actor_user_id is null
    where usage.actor_user_id is null
  )
  select * from rows
  order by request_count desc, last_search_at desc nulls last, user_id;
$$;

revoke all on function public.flight_search_usage_by_actor_v2(
  timestamptz, timestamptz
) from public, anon, authenticated;
grant execute on function public.flight_search_usage_by_actor_v2(
  timestamptz, timestamptz
) to service_role;

comment on function public.flight_search_usage_by_actor_v2(
  timestamptz, timestamptz
) is 'Super Admin actor usage report with agency identity and up to 50 searched routes per actor.';


-- SOURCE: 0140_flight_search_route_travel_dates.sql
-- Include the requested travel dates in each actor route summary. The overall
-- `last_search_at` remains the timestamp when the user performed a search.

create or replace function public.flight_search_usage_by_actor_v2(
  p_from timestamptz,
  p_to timestamptz
)
returns table (
  user_id text,
  display_name text,
  email text,
  role text,
  agency_code text,
  agency_name text,
  searched_routes jsonb,
  distinct_route_count bigint,
  request_count bigint,
  supplier_api_hit_count bigint,
  success_count bigint,
  failed_count bigint,
  blocked_count bigint,
  last_search_at timestamptz,
  average_total_ms numeric,
  search_enabled boolean,
  daily_limit integer,
  control_version integer,
  today_hit_count integer
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with usage as (
    select
      event.actor_user_id,
      count(*)::bigint as request_count,
      count(*) filter (where event.supplier_api_hit)::bigint as hit_count,
      count(*) filter (where event.outcome = 'success')::bigint as success_count,
      count(*) filter (where event.outcome = 'failed')::bigint as failed_count,
      count(*) filter (where event.outcome in (
        'rate_limited', 'busy', 'user_disabled', 'user_daily_limit',
        'supplier_daily_limit'
      ))::bigint as blocked_count,
      max(event.created_at) as last_search_at,
      round(avg(event.total_ms), 2) as average_total_ms
    from public.flight_search_usage_events event
    where event.created_at >= p_from and event.created_at < p_to
    group by event.actor_user_id
  ), event_routes as (
    select
      event.id,
      event.actor_user_id,
      string_agg(
        upper(segment.value ->> 'origin') || ' → ' ||
          upper(segment.value ->> 'destination'),
        ' / ' order by segment.ordinality
      ) as route_label,
      jsonb_agg(
        to_jsonb(segment.value ->> 'departureDate')
        order by segment.ordinality
      ) as departure_dates,
      max(event.created_at) as last_searched_at
    from public.flight_search_usage_events event
    cross join lateral jsonb_array_elements(event.routes)
      with ordinality as segment(value, ordinality)
    where event.created_at >= p_from and event.created_at < p_to
      and nullif(trim(segment.value ->> 'origin'), '') is not null
      and nullif(trim(segment.value ->> 'destination'), '') is not null
    group by event.id, event.actor_user_id
  ), route_counts as (
    select
      event_routes.actor_user_id,
      event_routes.route_label,
      event_routes.departure_dates,
      count(*)::bigint as request_count,
      max(event_routes.last_searched_at) as last_searched_at
    from event_routes
    group by event_routes.actor_user_id, event_routes.route_label,
      event_routes.departure_dates
  ), ranked_routes as (
    select
      route_counts.*,
      row_number() over (
        partition by route_counts.actor_user_id
        order by route_counts.request_count desc,
          route_counts.last_searched_at desc,
          route_counts.route_label,
          route_counts.departure_dates::text
      ) as route_rank,
      count(*) over (partition by route_counts.actor_user_id)::bigint
        as distinct_route_count
    from route_counts
  ), route_summary as (
    select
      ranked_routes.actor_user_id,
      jsonb_agg(
        jsonb_build_object(
          'route', ranked_routes.route_label,
          'departureDates', ranked_routes.departure_dates,
          'requestCount', ranked_routes.request_count,
          'lastSearchedAt', ranked_routes.last_searched_at
        ) order by ranked_routes.request_count desc,
          ranked_routes.last_searched_at desc,
          ranked_routes.route_label,
          ranked_routes.departure_dates::text
      ) filter (where ranked_routes.route_rank <= 50) as searched_routes,
      max(ranked_routes.distinct_route_count)::bigint as distinct_route_count
    from ranked_routes
    group by ranked_routes.actor_user_id
  ), rows as (
    select
      usr.clerk_id as user_id,
      nullif(trim(concat_ws(' ', usr.first_name, usr.last_name)), '') as display_name,
      usr.email,
      usr.role,
      usr.agency_code,
      case when usr.role in ('b2b', 'b2b_sub') then
        nullif(trim(agency_profile.agency_name), '')
      else null end as agency_name,
      coalesce(route_summary.searched_routes, '[]'::jsonb) as searched_routes,
      coalesce(route_summary.distinct_route_count, 0)::bigint as distinct_route_count,
      coalesce(usage.request_count, 0)::bigint as request_count,
      coalesce(usage.hit_count, 0)::bigint as hit_count,
      coalesce(usage.success_count, 0)::bigint as success_count,
      coalesce(usage.failed_count, 0)::bigint as failed_count,
      coalesce(usage.blocked_count, 0)::bigint as blocked_count,
      usage.last_search_at,
      usage.average_total_ms,
      coalesce(control.search_enabled, true) as search_enabled,
      control.daily_limit,
      coalesce(control.version, 0) as control_version,
      coalesce(counter.hit_count, 0) as today_hit_count
    from public.app_users usr
    left join usage on usage.actor_user_id = usr.clerk_id
    left join route_summary on route_summary.actor_user_id = usr.clerk_id
    left join public.agencies agency on agency.agency_code = usr.agency_code
    left join public.user_profiles agency_profile
      on agency_profile.clerk_id = coalesce(
        agency.owner_user_id,
        case when usr.role = 'b2b' then usr.clerk_id else null end
      )
    left join public.flight_search_user_controls control
      on control.user_id = usr.clerk_id
    left join public.flight_search_daily_counters counter
      on counter.scope_type = 'user'
     and counter.scope_key = usr.clerk_id
     and counter.usage_date = timezone('Asia/Dhaka', clock_timestamp())::date
    union all
    select
      null, 'Anonymous visitors', null, 'anonymous', null, null,
      coalesce(route_summary.searched_routes, '[]'::jsonb),
      coalesce(route_summary.distinct_route_count, 0)::bigint,
      usage.request_count, usage.hit_count, usage.success_count,
      usage.failed_count, usage.blocked_count, usage.last_search_at,
      usage.average_total_ms, true, null, 0, 0
    from usage
    left join route_summary on route_summary.actor_user_id is null
    where usage.actor_user_id is null
  )
  select * from rows
  order by request_count desc, last_search_at desc nulls last, user_id;
$$;

comment on function public.flight_search_usage_by_actor_v2(
  timestamptz, timestamptz
) is 'Super Admin actor usage report with agency identity, searched routes, and requested travel dates.';


-- SOURCE: 0141_triplover_supplier_account.sql
-- Add Triplover's direct credential account alongside FirstTrip and TakeOff.
-- The integration name remains `triplover`; `supplier_account` selects the
-- immutable credential and host set used by a search and its booking.

alter table public.flight_search_quotes
  drop constraint if exists flight_search_quotes_supplier_account_check;
alter table public.flight_search_quotes
  add constraint flight_search_quotes_supplier_account_check
  check (supplier_account is null or supplier_account in ('firsttrip', 'takeoff', 'triplover'));

alter table public.booking_attempts
  drop constraint if exists booking_attempts_supplier_account_check;
alter table public.booking_attempts
  add constraint booking_attempts_supplier_account_check
  check (supplier_account is null or supplier_account in ('firsttrip', 'takeoff', 'triplover'));

alter table public.flight_bookings
  drop constraint if exists flight_bookings_supplier_account_check;
alter table public.flight_bookings
  add constraint flight_bookings_supplier_account_check
  check (supplier_account is null or supplier_account in ('firsttrip', 'takeoff', 'triplover'));

alter table public.supplier_operational_settings
  drop constraint if exists supplier_operational_settings_active_supplier_check;
alter table public.supplier_operational_settings
  add constraint supplier_operational_settings_active_supplier_check
  check (active_supplier in ('firsttrip', 'takeoff', 'triplover'));

alter table public.flight_search_supplier_limits
  drop constraint if exists flight_search_supplier_limits_supplier_check;
alter table public.flight_search_supplier_limits
  add constraint flight_search_supplier_limits_supplier_check
  check (supplier in ('firsttrip', 'takeoff', 'triplover'));

insert into public.flight_search_supplier_limits (supplier, daily_limit)
values ('triplover', null)
on conflict (supplier) do nothing;

alter table public.flight_search_usage_events
  drop constraint if exists flight_search_usage_events_supplier_account_check;
alter table public.flight_search_usage_events
  add constraint flight_search_usage_events_supplier_account_check
  check (supplier_account in ('firsttrip', 'takeoff', 'triplover'));

-- Keep the atomic supplier/user daily-budget claim aligned with the expanded
-- supplier constraint.
create or replace function public.claim_flight_search_supplier_hit_v1(
  p_event_id uuid,
  p_supplier text,
  p_user_id text
)
returns table (
  allowed boolean,
  result_code text,
  supplier_count integer,
  supplier_limit integer,
  user_count integer,
  user_limit integer
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_today date := timezone('Asia/Dhaka', clock_timestamp())::date;
  v_supplier_count integer := 0;
  v_supplier_limit integer;
  v_user_count integer := 0;
  v_user_limit integer;
  v_user_enabled boolean := true;
  v_code text;
begin
  if p_supplier not in ('firsttrip', 'takeoff', 'triplover') then
    raise exception 'unsupported supplier' using errcode = '22023';
  end if;

  insert into public.flight_search_daily_counters (
    scope_type, scope_key, usage_date, hit_count
  ) values ('supplier', p_supplier, v_today, 0)
  on conflict do nothing;

  select counter.hit_count into v_supplier_count
    from public.flight_search_daily_counters counter
   where counter.scope_type = 'supplier'
     and counter.scope_key = p_supplier
     and counter.usage_date = v_today
   for update;

  select limits.daily_limit into v_supplier_limit
    from public.flight_search_supplier_limits limits
   where limits.supplier = p_supplier;

  if p_user_id is not null then
    insert into public.flight_search_daily_counters (
      scope_type, scope_key, usage_date, hit_count
    ) values ('user', p_user_id, v_today, 0)
    on conflict do nothing;

    select counter.hit_count into v_user_count
      from public.flight_search_daily_counters counter
     where counter.scope_type = 'user'
       and counter.scope_key = p_user_id
       and counter.usage_date = v_today
     for update;

    select controls.search_enabled, controls.daily_limit
      into v_user_enabled, v_user_limit
      from public.flight_search_user_controls controls
     where controls.user_id = p_user_id;
    if not found then
      v_user_enabled := true;
      v_user_limit := null;
    end if;
  end if;

  v_code := case
    when p_user_id is not null and not v_user_enabled then 'USER_SEARCH_DISABLED'
    when p_user_id is not null and v_user_limit is not null
      and v_user_count >= v_user_limit then 'USER_DAILY_LIMIT_REACHED'
    when v_supplier_limit is not null and v_supplier_count >= v_supplier_limit
      then 'SUPPLIER_DAILY_LIMIT_REACHED'
    else 'ALLOWED'
  end;

  if v_code <> 'ALLOWED' then
    update public.flight_search_usage_events
       set outcome = case v_code
             when 'USER_SEARCH_DISABLED' then 'user_disabled'
             when 'USER_DAILY_LIMIT_REACHED' then 'user_daily_limit'
             else 'supplier_daily_limit'
           end,
           http_status = case when v_code = 'USER_SEARCH_DISABLED' then 403
                              when v_code = 'USER_DAILY_LIMIT_REACHED' then 429
                              else 503 end,
           error_code = v_code,
           completed_at = clock_timestamp()
     where id = p_event_id;
    return query select false, v_code, v_supplier_count, v_supplier_limit,
      v_user_count, v_user_limit;
    return;
  end if;

  update public.flight_search_daily_counters
     set hit_count = hit_count + 1,
         updated_at = clock_timestamp()
   where scope_type = 'supplier' and scope_key = p_supplier and usage_date = v_today;
  v_supplier_count := v_supplier_count + 1;

  if p_user_id is not null then
    update public.flight_search_daily_counters
       set hit_count = hit_count + 1,
           updated_at = clock_timestamp()
     where scope_type = 'user' and scope_key = p_user_id and usage_date = v_today;
    v_user_count := v_user_count + 1;
  end if;

  update public.flight_search_usage_events
     set supplier_api_hit = true,
         outcome = 'supplier_called'
   where id = p_event_id;

  return query select true, 'ALLOWED'::text, v_supplier_count, v_supplier_limit,
    v_user_count, v_user_limit;
end;
$$;

-- Direct Triplover holds use the same bounded read-only PNR refresh workflow.
create or replace function public.enqueue_booking_pnr_refresh_job_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_carrier_group text;
begin
  if new.legacy_operational
     or lower(coalesce(new.supplier, '')) <> 'triplover'
     or new.status <> 'on-hold'
     or new.direct_ticketing
     or new.import_source is not null
     or coalesce(new.supplier_account, '') not in ('firsttrip', 'takeoff', 'triplover')
     or nullif(btrim(coalesce(new.pnr, '')), '') is null
     or nullif(btrim(coalesce(new.booking_code_ref, '')), '') is null
     or nullif(btrim(new.supplier_refs->>'uniqueTransId'), '') is null
     or nullif(btrim(new.supplier_refs->>'itemCodeRef'), '') is null
     or nullif(btrim(new.supplier_refs->>'priceCodeRef'), '') is null then
    return new;
  end if;

  v_carrier_group := case upper(btrim(coalesce(new.itinerary->>'carrierCode', '')))
    when 'BS' then 'bs_immediate'
    else 'non_bs_delayed'
  end;
  insert into public.booking_pnr_refresh_jobs (
    booking_id, carrier_group, next_attempt_at
  ) values (
    new.id,
    v_carrier_group,
    public.booking_pnr_refresh_initial_due_at_v1(v_carrier_group, new.created_at)
  ) on conflict (booking_id) do nothing;
  return new;
end;
$$;

create or replace function public.claim_due_booking_pnr_refresh_job_v1(
  p_worker_id text
)
returns table (
  job_id uuid,
  booking_id uuid,
  supplier_account text,
  supplier_refs jsonb,
  pnr text,
  booking_ref_number text,
  booking_code_ref text,
  carrier_code text,
  deadline_not_before timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
begin
  if nullif(btrim(p_worker_id), '') is null or char_length(p_worker_id) > 255 then
    raise exception 'PNR refresh worker identity is required' using errcode = '22023';
  end if;

  update public.booking_pnr_refresh_jobs
     set state = 'pending', claimed_at = null, claimed_by = null,
         last_error_code = coalesce(last_error_code, 'WORKER_LEASE_EXPIRED')
   where state = 'running'
     and claimed_at < clock_timestamp() - interval '3 minutes';

  update public.booking_pnr_refresh_jobs job
     set state = 'skipped', completed_at = clock_timestamp(),
         completion_reason = 'booking_not_refreshable',
         claimed_at = null, claimed_by = null
    from public.flight_bookings booking
   where booking.id = job.booking_id
     and job.state = 'pending'
     and job.next_attempt_at <= clock_timestamp()
     and (
       booking.legacy_operational
       or lower(coalesce(booking.supplier, '')) <> 'triplover'
       or booking.status <> 'on-hold'
       or booking.operation_kind is not null
       or booking.import_source is not null
       or coalesce(booking.supplier_account, '') not in ('firsttrip', 'takeoff', 'triplover')
       or nullif(btrim(coalesce(booking.pnr, '')), '') is null
       or nullif(btrim(coalesce(booking.booking_code_ref, '')), '') is null
       or nullif(btrim(booking.supplier_refs->>'uniqueTransId'), '') is null
       or nullif(btrim(booking.supplier_refs->>'itemCodeRef'), '') is null
       or nullif(btrim(booking.supplier_refs->>'priceCodeRef'), '') is null
     );

  return query
  with candidate as (
    select job.id
      from public.booking_pnr_refresh_jobs job
      join public.flight_bookings booking on booking.id = job.booking_id
     where job.state = 'pending'
       and job.next_attempt_at <= clock_timestamp()
       and not booking.legacy_operational
       and lower(coalesce(booking.supplier, '')) = 'triplover'
       and booking.status = 'on-hold'
       and booking.operation_kind is null
       and booking.import_source is null
       and booking.supplier_account in ('firsttrip', 'takeoff', 'triplover')
     order by job.next_attempt_at, job.id
     limit 1
     for update of job skip locked
  ), claimed as (
    update public.booking_pnr_refresh_jobs job
       set state = 'running', claimed_at = clock_timestamp(), claimed_by = p_worker_id
      from candidate
     where job.id = candidate.id
    returning job.id, job.booking_id
  )
  select
    claimed.id,
    booking.id,
    booking.supplier_account,
    booking.supplier_refs,
    booking.pnr,
    booking.booking_ref_number,
    booking.booking_code_ref,
    booking.itinerary->>'carrierCode',
    coalesce(booking.submission_started_at, booking.created_at)
  from claimed
  join public.flight_bookings booking on booking.id = claimed.booking_id;
end;
$$;

comment on table public.supplier_operational_settings is
  'Singleton Super Admin control for the active FirstTrip, TakeOff, or direct Triplover credential account and booking/ticketing gates.';


-- SOURCE: 0142_triplover_supplier_reference_import.sql
-- Extend Supplier API Import to Triplover's own TLL transaction references.
-- The original import migration predates the direct Triplover credential
-- account, so both its persisted authorization checks and its two atomic RPCs
-- must be widened together.

alter table public.supplier_reference_charge_authorizations
  drop constraint if exists supplier_reference_charge_account_check;
alter table public.supplier_reference_charge_authorizations
  add constraint supplier_reference_charge_account_check
  check (supplier_account in ('firsttrip', 'takeoff', 'triplover'));

alter table public.supplier_reference_charge_authorizations
  drop constraint if exists supplier_reference_charge_reference_check;
alter table public.supplier_reference_charge_authorizations
  add constraint supplier_reference_charge_reference_check
  check (supplier_reference ~ '^(FST|TOT|TLL)[0-9]{18}$');

do $migration$
declare
  v_signature text;
  v_definition text;
  v_updated text;
begin
  foreach v_signature in array array[
    'public.authorize_supplier_reference_charge_v1(text,text,bigint,bigint,jsonb,text)',
    'public.create_supplier_reference_booking_v1(text,text,bigint,bigint,jsonb,text,uuid,text)'
  ] loop
    select pg_get_functiondef(to_regprocedure(v_signature))
      into v_definition;

    if v_definition is null then
      raise exception 'required Supplier API Import function is missing: %',
        v_signature;
    end if;

    v_updated := replace(
      v_definition,
      'v_supplier_account not in (''firsttrip'', ''takeoff'')',
      'v_supplier_account not in (''firsttrip'', ''takeoff'', ''triplover'')'
    );
    v_updated := replace(
      v_updated,
      'or (v_supplier_account = ''takeoff''
       and v_supplier_reference !~ ''^TOT[0-9]{18}$'')',
      'or (v_supplier_account = ''takeoff''
       and v_supplier_reference !~ ''^TOT[0-9]{18}$'')
     or (v_supplier_account = ''triplover''
       and v_supplier_reference !~ ''^TLL[0-9]{18}$'')'
    );

    if v_updated = v_definition
       or position(
         'v_supplier_account not in (''firsttrip'', ''takeoff'', ''triplover'')'
         in v_updated
       ) = 0
       or position(
         'v_supplier_reference !~ ''^TLL[0-9]{18}$'''
         in v_updated
       ) = 0 then
      raise exception 'could not safely extend Supplier API Import function: %',
        v_signature;
    end if;

    execute v_updated;
  end loop;
end;
$migration$;

comment on function public.authorize_supplier_reference_charge_v1(
  text, text, bigint, bigint, jsonb, text
) is
  'Records a five-minute, one-use, exact-payload authorization for FirstTrip, TakeOff, or Triplover supplier-reference imports after checking the assigned owner wallet. It never mutates wallet money or creates a booking.';

comment on function public.create_supplier_reference_booking_v1(
  text, text, bigint, bigint, jsonb, text, uuid, text
) is
  'Atomically creates an ordinary Triplover API-backed booking from real FirstTrip, TakeOff, or Triplover references. Held and terminal historical imports make no wallet movement; explicit confirmed Import & Charge consumes one fresh authorization and writes the captured reservation and immutable ledger in the same transaction.';


-- SOURCE: 0143_ticket_management_single_active_action_request.sql
-- Permit only one open request for a booking/action pair. Exact retries keep
-- their original request identity, while rejected, expired, and fully-settled
-- requests no longer block a later Refund, Reissue, or VOID request.

create index if not exists ticket_management_requests_open_action_lookup_idx
  on public.ticket_management_requests(booking_id, action, created_at desc, id)
  where status in ('requested', 'in-progress', 'awaiting-confirmation')
     or (status = 'approved' and terminal_outcome is null);

create or replace function public.ticket_management_enforce_single_open_action_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status in ('requested', 'in-progress', 'awaiting-confirmation')
     or (new.status = 'approved' and new.terminal_outcome is null) then
    perform pg_advisory_xact_lock(hashtextextended(
      concat_ws(':', 'ticket-management-open-action-v1',
        new.booking_id::text, new.action),
      0
    ));
    if exists (
      select 1
        from public.ticket_management_requests request
       where request.booking_id = new.booking_id
         and request.action = new.action
         and request.id <> new.id
         and (
           request.status in ('requested', 'in-progress', 'awaiting-confirmation')
           or (request.status = 'approved' and request.terminal_outcome is null)
         )
    ) then
      raise exception 'ticket management action already has an active request'
        using errcode = '23505';
    end if;
  end if;
  return new;
end;
$$;

create trigger ticket_management_requests_single_open_action
  before insert or update of booking_id, action, status, terminal_outcome
  on public.ticket_management_requests
  for each row execute function public.ticket_management_enforce_single_open_action_v1();

create or replace function public.create_ticket_management_request_v3(
  p_booking_id uuid,
  p_action text,
  p_actor_user_id text,
  p_request_key text,
  p_request_payload_hash text,
  p_passenger_indexes integer[],
  p_request_type text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
  v_request_type text := lower(btrim(coalesce(p_request_type, '')));
  v_active public.ticket_management_requests;
begin
  if v_request_type not in ('voluntary', 'involuntary') then
    return jsonb_build_object('ok', false, 'code', 'INVALID_REQUEST_TYPE');
  end if;

  -- Serialize new identities for the same booking/action. The lower-level
  -- request-key lock still owns exact replay and payload-conflict handling.
  perform pg_advisory_xact_lock(hashtextextended(
    concat_ws(':', 'ticket-management-open-action-v1',
      coalesce(p_booking_id::text, ''), coalesce(p_action, '')),
    0
  ));

  select request.* into v_active
    from public.ticket_management_requests request
   where request.booking_id = p_booking_id
     and request.action = p_action
     and request.request_key <> p_request_key
     and (
       request.status in ('requested', 'in-progress', 'awaiting-confirmation')
       or (request.status = 'approved' and request.terminal_outcome is null)
     )
   order by request.created_at desc, request.id desc
   limit 1;
  if found then
    return jsonb_build_object(
      'ok', false,
      'code', 'ACTIVE_REQUEST_EXISTS',
      'requestId', v_active.id,
      'publicReference', v_active.public_ref,
      'status', v_active.status,
      'version', v_active.version
    );
  end if;

  v_result := public.create_ticket_management_request_v2(
    p_booking_id, p_action, p_actor_user_id, p_request_key,
    p_request_payload_hash, p_passenger_indexes, p_note
  );
  if not coalesce((v_result->>'ok')::boolean, false) then
    return v_result;
  end if;

  update public.ticket_management_requests
     set request_type = v_request_type
   where id = (v_result->>'requestId')::uuid;

  return v_result || jsonb_build_object('requestType', v_request_type);
end;
$$;

revoke all on function public.create_ticket_management_request_v3(
  uuid, text, text, text, text, integer[], text, text
) from public, anon, authenticated;
grant execute on function public.create_ticket_management_request_v3(
  uuid, text, text, text, text, integer[], text, text
) to service_role;

comment on function public.create_ticket_management_request_v3(
  uuid, text, text, text, text, integer[], text, text
) is
  'Creates an owner-authorized request and rejects a second open request for the same booking and Refund, Reissue, or VOID action; exact request-key retries remain idempotent.';


-- SOURCE: 0144_ticket_management_staff_rejection_until_approval.sql
-- Support/Admin may reject an operational request at any point before the
-- customer approves its quotation. Rejection remains terminal, releases the
-- selected ticket claims through the existing status trigger, and preserves
-- any published quotation as immutable audit history.

create or replace function public.review_ticket_management_request_v1(
  p_request_id uuid,
  p_decision text,
  p_actor_user_id text,
  p_expected_version integer,
  p_request_key text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role text;
  v_request public.ticket_management_requests;
  v_existing_event public.ticket_management_request_events;
  v_from_status text;
  v_status text;
  v_outcome text;
  v_event_type text;
  v_version integer;
begin
  if p_decision not in ('accept', 'reject')
     or p_expected_version is null or p_expected_version < 1
     or nullif(btrim(p_request_key), '') is null then
    raise exception 'invalid Ticket Management review' using errcode = '22023';
  end if;
  v_event_type := case when p_decision = 'accept' then 'accepted' else 'staff-rejected' end;

  select role into v_actor_role from public.app_users where clerk_id = p_actor_user_id;
  if v_actor_role not in ('staff_support', 'admin', 'superadmin') then
    return jsonb_build_object('ok', false, 'code', 'OPERATION_FORBIDDEN');
  end if;
  select event.* into v_existing_event
    from public.ticket_management_request_events event
   where event.idempotency_key = p_request_key || ':event';
  if found then
    if v_existing_event.request_id is distinct from p_request_id
       or v_existing_event.event_type is distinct from v_event_type then
      return jsonb_build_object('ok', false, 'code', 'REVIEW_IDEMPOTENCY_CONFLICT');
    end if;
    return jsonb_build_object(
      'ok', true, 'replay', true, 'requestId', p_request_id,
      'status', v_existing_event.to_status,
      'version', v_existing_event.request_version
    );
  end if;

  select request.* into v_request
    from public.ticket_management_requests request
   where request.id = p_request_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_FOUND'); end if;
  if v_request.version <> p_expected_version then
    return jsonb_build_object(
      'ok', false, 'code', 'REQUEST_VERSION_CONFLICT', 'version', v_request.version
    );
  end if;
  if p_decision = 'accept' and v_request.status <> 'requested' then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_REVIEWABLE');
  end if;
  if p_decision = 'reject'
     and v_request.status not in ('requested', 'in-progress', 'awaiting-confirmation') then
    return jsonb_build_object('ok', false, 'code', 'REQUEST_NOT_REJECTABLE');
  end if;

  v_from_status := v_request.status;
  if p_decision = 'accept' then
    v_status := 'in-progress';
    v_outcome := null;
    update public.ticket_management_requests
       set status = v_status, terminal_outcome = null,
           accepted_by_user_id = p_actor_user_id,
           accepted_at = clock_timestamp(), status_changed_at = clock_timestamp(),
           version = version + 1
     where id = v_request.id returning version into v_version;
  else
    v_status := 'rejected';
    v_outcome := 'staff-rejected';
    update public.ticket_management_requests
       set status = v_status, terminal_outcome = v_outcome,
           rejected_at = clock_timestamp(), status_changed_at = clock_timestamp(),
           version = version + 1
     where id = v_request.id returning version into v_version;
  end if;

  perform public.ticket_management_append_event_v1(
    v_request.id, v_event_type, v_from_status, v_status, v_version,
    p_actor_user_id, v_actor_role, p_request_key || ':event', p_note,
    jsonb_build_object('decision', p_decision)
  );
  return jsonb_build_object(
    'ok', true, 'replay', false, 'requestId', v_request.id,
    'status', v_status, 'version', v_version
  );
end;
$$;

revoke all on function public.review_ticket_management_request_v1(
  uuid, text, text, integer, text, text
) from public, anon, authenticated;
grant execute on function public.review_ticket_management_request_v1(
  uuid, text, text, integer, text, text
) to service_role;

comment on function public.review_ticket_management_request_v1(
  uuid, text, text, integer, text, text
) is
  'Accepts a newly requested item or lets Support/Admin reject it until customer quotation approval; terminal rejection releases ticket claims through the request status trigger.';


-- SOURCE: 0145_ticket_management_route_selection.sql
-- Persist the itinerary routes selected for Refund, Reissue, and VOID.
-- Route snapshots are immutable so staff always review the exact scope the
-- customer submitted, even if the booking snapshot changes later.

create table public.ticket_management_request_routes (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null
    references public.ticket_management_requests(id) on delete restrict,
  route_index integer not null check (route_index >= 0),
  route_snapshot jsonb not null
    check (jsonb_typeof(route_snapshot) = 'object'),
  route_label text not null
    check (char_length(btrim(route_label)) between 1 and 80),
  origin_code text not null
    check (char_length(btrim(origin_code)) between 1 and 12),
  destination_code text not null
    check (char_length(btrim(destination_code)) between 1 and 12),
  departure_at text,
  created_at timestamptz not null default clock_timestamp(),
  unique (request_id, route_index)
);

create index ticket_management_request_routes_request_idx
  on public.ticket_management_request_routes(request_id, route_index);

alter table public.ticket_management_requests
  add column route_selection_hash text
    check (route_selection_hash is null or route_selection_hash ~ '^[a-f0-9]{64}$');

create or replace function public.prevent_ticket_management_route_mutation_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  raise exception 'ticket management request routes are immutable'
    using errcode = '55000';
end;
$$;

create trigger ticket_management_request_routes_deny_update_delete
  before update or delete on public.ticket_management_request_routes
  for each row execute function public.prevent_ticket_management_route_mutation_v1();

alter table public.ticket_management_request_routes enable row level security;
revoke all on public.ticket_management_request_routes from public, anon, authenticated;
grant select, insert on public.ticket_management_request_routes to service_role;

create or replace function public.create_ticket_management_request_v4(
  p_booking_id uuid,
  p_action text,
  p_actor_user_id text,
  p_request_key text,
  p_request_payload_hash text,
  p_passenger_indexes integer[],
  p_route_indexes integer[],
  p_request_type text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result jsonb;
  v_booking public.flight_bookings;
  v_request public.ticket_management_requests;
  v_itinerary_routes jsonb;
  v_route_count integer;
  v_selected_count integer;
  v_existing_count integer;
  v_route_selection_hash text;
begin
  if p_route_indexes is null or cardinality(p_route_indexes) = 0 then
    return jsonb_build_object('ok', false, 'code', 'ROUTE_SELECTION_REQUIRED');
  end if;
  if exists (select 1 from unnest(p_route_indexes) route_index where route_index < 0) then
    return jsonb_build_object('ok', false, 'code', 'INVALID_ROUTE_SELECTION');
  end if;
  if (select count(*) from unnest(p_route_indexes)) <>
     (select count(distinct route_index) from unnest(p_route_indexes) route_index) then
    return jsonb_build_object('ok', false, 'code', 'DUPLICATE_ROUTE_SELECTION');
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id;

  -- Let v3 retain authority for missing/unauthorized bookings. For a real
  -- booking, fail before request creation when its selected route is invalid.
  if found then
    v_itinerary_routes := v_booking.itinerary->'legs';
    if v_itinerary_routes is null or jsonb_typeof(v_itinerary_routes) <> 'array'
       or jsonb_array_length(v_itinerary_routes) = 0 then
      return jsonb_build_object('ok', false, 'code', 'ROUTES_UNAVAILABLE');
    end if;
    v_route_count := jsonb_array_length(v_itinerary_routes);
    if exists (
      select 1 from unnest(p_route_indexes) route_index
       where route_index >= v_route_count
    ) then
      return jsonb_build_object('ok', false, 'code', 'INVALID_ROUTE_SELECTION');
    end if;
  end if;

  v_result := public.create_ticket_management_request_v3(
    p_booking_id, p_action, p_actor_user_id, p_request_key,
    p_request_payload_hash, p_passenger_indexes, p_request_type, p_note
  );
  if not coalesce((v_result->>'ok')::boolean, false) then
    return v_result;
  end if;

  select request.* into v_request
    from public.ticket_management_requests request
   where request.id = (v_result->>'requestId')::uuid
   for update;

  v_route_selection_hash := encode(sha256(convert_to(
    concat_ws('|', p_booking_id::text, p_action,
      (select string_agg(route_index::text, ',' order by route_index)
         from unnest(p_route_indexes) route_index)),
    'UTF8'
  )), 'hex');

  select count(*) into v_existing_count
    from public.ticket_management_request_routes route
   where route.request_id = v_request.id;
  if v_existing_count > 0 then
    if v_request.route_selection_hash is distinct from v_route_selection_hash
       or v_existing_count <> cardinality(p_route_indexes) then
      return jsonb_build_object('ok', false, 'code', 'REQUEST_KEY_REUSED');
    end if;
    return v_result || jsonb_build_object(
      'selectedRouteCount', v_existing_count,
      'routeSelectionHash', v_route_selection_hash
    );
  end if;

  insert into public.ticket_management_request_routes (
    request_id, route_index, route_snapshot, route_label,
    origin_code, destination_code, departure_at
  )
  select
    v_request.id,
    leg.ordinality::integer - 1,
    leg.value,
    case when v_route_count > 1
      then 'Route ' || leg.ordinality::text
      else 'Route'
    end,
    upper(btrim(leg.value->>'from')),
    upper(btrim(leg.value->>'to')),
    nullif(btrim(leg.value->>'departure'), '')
  from jsonb_array_elements(v_itinerary_routes)
    with ordinality leg(value, ordinality)
  where (leg.ordinality::integer - 1) = any(p_route_indexes)
    and jsonb_typeof(leg.value) = 'object'
    and nullif(btrim(leg.value->>'from'), '') is not null
    and nullif(btrim(leg.value->>'to'), '') is not null
  order by leg.ordinality;

  get diagnostics v_selected_count = row_count;
  if v_selected_count <> cardinality(p_route_indexes) then
    raise exception 'selected route is unavailable' using errcode = '23514';
  end if;

  update public.ticket_management_requests
     set route_selection_hash = v_route_selection_hash
   where id = v_request.id;

  return v_result || jsonb_build_object(
    'selectedRouteCount', v_selected_count,
    'routeSelectionHash', v_route_selection_hash
  );
end;
$$;

revoke all on function public.create_ticket_management_request_v4(
  uuid, text, text, text, text, integer[], integer[], text, text
) from public, anon, authenticated;
grant execute on function public.create_ticket_management_request_v4(
  uuid, text, text, text, text, integer[], integer[], text, text
) to service_role;

revoke all on function public.prevent_ticket_management_route_mutation_v1()
  from public, anon, authenticated;
grant execute on function public.prevent_ticket_management_route_mutation_v1()
  to service_role;

comment on table public.ticket_management_request_routes is
  'Immutable booking-itinerary route snapshots selected by the customer for a Ticket Management request.';
comment on column public.ticket_management_requests.route_selection_hash is
  'SHA-256 binding the request to its selected itinerary route indexes.';
comment on function public.create_ticket_management_request_v4(
  uuid, text, text, text, text, integer[], integer[], text, text
) is
  'Creates an owner-authorized Refund, Reissue, or VOID request with immutable passenger and route selections.';


-- SOURCE: 0146_ticket_management_void_same_day_cutoff.sql
-- VOID requests may only be created from the issue instant until 23:30 on
-- that same Asia/Dhaka calendar day. The trigger protects every insert path,
-- including future service-side callers that do not pass through the web API.

create or replace function public.ticket_management_void_request_window_open_v1(
  p_issued_at timestamptz,
  p_now timestamptz default clock_timestamp()
)
returns boolean
language sql
immutable
set search_path = public
as $$
  select p_issued_at is not null
    and p_now >= p_issued_at
    and (p_now at time zone 'Asia/Dhaka')::date =
        (p_issued_at at time zone 'Asia/Dhaka')::date
    and (p_now at time zone 'Asia/Dhaka')::time < time '23:30:00';
$$;

create or replace function public.enforce_ticket_management_void_request_window_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_issued_at timestamptz;
begin
  if new.action <> 'void' then
    return new;
  end if;

  select booking.issued_at
    into v_issued_at
    from public.flight_bookings booking
   where booking.id = new.booking_id;

  if not public.ticket_management_void_request_window_open_v1(
    v_issued_at,
    clock_timestamp()
  ) then
    raise exception 'VOID_REQUEST_WINDOW_CLOSED' using errcode = '23514';
  end if;

  return new;
end;
$$;

create trigger ticket_management_requests_void_window_guard
  before insert on public.ticket_management_requests
  for each row execute function public.enforce_ticket_management_void_request_window_v1();

revoke all on function public.ticket_management_void_request_window_open_v1(
  timestamptz, timestamptz
) from public, anon, authenticated;
revoke all on function public.enforce_ticket_management_void_request_window_v1()
  from public, anon, authenticated;

grant execute on function public.ticket_management_void_request_window_open_v1(
  timestamptz, timestamptz
) to service_role;
grant execute on function public.enforce_ticket_management_void_request_window_v1()
  to service_role;

comment on function public.ticket_management_void_request_window_open_v1(
  timestamptz, timestamptz
) is
  'True only from ticket issuance until, but excluding, 23:30 Asia/Dhaka on the same local calendar date.';


-- SOURCE: 0147_ticket_management_action_visibility.sql
-- Keep the server-side request boundary aligned with the booking action UI.
-- Only confirmed tickets can create requests. Instant-issued and imported
-- tickets expose Reissue only; Refund and VOID remain unavailable.

create or replace function public.ticket_management_action_available_for_booking_v1(
  p_action text,
  p_status text,
  p_direct_ticketing boolean,
  p_import_source text,
  p_booking_origin text
)
returns boolean
language sql
immutable
set search_path = public
as $$
  select p_action in ('refund', 'reissue', 'void')
    and p_status = 'confirmed'
    and (
      p_action = 'reissue'
      or not (
        coalesce(p_direct_ticketing, false)
        or coalesce(p_import_source, '') in ('IMP_EXP', 'MANUAL')
        or coalesce(p_booking_origin, '') = 'supplier_reference_import'
      )
    );
$$;

create or replace function public.enforce_ticket_management_action_availability_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
begin
  select booking.*
    into v_booking
    from public.flight_bookings booking
   where booking.id = new.booking_id;

  if found and not public.ticket_management_action_available_for_booking_v1(
    new.action,
    v_booking.status,
    v_booking.direct_ticketing,
    v_booking.import_source,
    v_booking.booking_origin
  ) then
    raise exception 'TICKET_MANAGEMENT_ACTION_UNAVAILABLE'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create trigger ticket_management_requests_action_availability_guard
  before insert on public.ticket_management_requests
  for each row execute function public.enforce_ticket_management_action_availability_v1();

revoke all on function public.ticket_management_action_available_for_booking_v1(
  text, text, boolean, text, text
) from public, anon, authenticated;
revoke all on function public.enforce_ticket_management_action_availability_v1()
  from public, anon, authenticated;

grant execute on function public.ticket_management_action_available_for_booking_v1(
  text, text, boolean, text, text
) to service_role;
grant execute on function public.enforce_ticket_management_action_availability_v1()
  to service_role;

comment on function public.ticket_management_action_available_for_booking_v1(
  text, text, boolean, text, text
) is
  'Allows all request actions for standard confirmed tickets, Reissue only for instant/imported confirmed tickets, and no actions for other statuses.';


-- SOURCE: 0148_booking_issued_sms.sql
-- Durable B2B partner SMS delivery for newly issued tickets.
--
-- One row is created in the same transaction as each future Confirmed
-- lifecycle occurrence. Historical rows are deliberately not backfilled: a
-- deployment must never surprise customers with old ticket confirmations.

create table public.booking_issued_sms_deliveries (
  id                     uuid primary key default gen_random_uuid(),
  lifecycle_event_id     bigint not null unique
                           references public.booking_status_events (id)
                           on delete restrict,
  booking_id             uuid not null
                           references public.flight_bookings (id)
                           on delete restrict,
  occurrence_id          uuid not null,
  recipient_number       text,
  recipient_number_hash  text,
  content_snapshot       jsonb not null,
  state                  text not null default 'pending',
  available_at           timestamptz not null default now(),
  claimed_at             timestamptz,
  claim_token            uuid,
  attempt_count          integer not null default 0,
  max_attempts           integer not null default 8,
  sent_at                timestamptz,
  completed_at           timestamptz,
  provider_message_id    text,
  last_error             text,
  suppression_reason     text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint booking_issued_sms_state_check check (state in (
    'pending', 'processing', 'retry', 'sent', 'suppressed', 'dead_letter'
  )),
  constraint booking_issued_sms_recipient_check check (
    (state = 'suppressed' and recipient_number is null
      and recipient_number_hash is null)
    or (recipient_number ~ '^[1-9][0-9]{7,14}$'
      and recipient_number_hash ~ '^[a-f0-9]{64}$')
  ),
  constraint booking_issued_sms_attempt_check check (
    attempt_count >= 0 and max_attempts between 1 and 20
  )
);

create trigger booking_issued_sms_touch_updated_at
  before update on public.booking_issued_sms_deliveries
  for each row execute function public.touch_updated_at();

create index booking_issued_sms_claim_idx
  on public.booking_issued_sms_deliveries (available_at, created_at, id)
  where state in ('pending', 'retry');

create index booking_issued_sms_booking_idx
  on public.booking_issued_sms_deliveries (booking_id, created_at desc);

create or replace function public.enqueue_booking_issued_sms_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_phone text;
  v_number text;
  v_state text := 'pending';
  v_suppression_reason text;
  v_pnr text;
  v_passenger_name text;
begin
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = new.booking_id;
  if not found then
    raise exception 'issued SMS booking not found' using errcode = '23503';
  end if;

  if v_booking.audience = 'agency' and v_booking.agency_code is not null then
    select regexp_replace(coalesce(profile.agency_mobile, ''), '[^0-9]', '', 'g')
      into v_phone
      from public.agencies agency
      join public.user_profiles profile
        on profile.clerk_id = agency.owner_user_id
     where agency.agency_code = v_booking.agency_code;
  end if;
  v_phone := coalesce(v_phone, '');

  if left(v_phone, 2) = '00' then
    v_number := substr(v_phone, 3);
  elsif left(v_phone, 3) = '880' then
    v_number := v_phone;
  elsif left(v_phone, 2) = '01' then
    v_number := '880' || substr(v_phone, 2);
  elsif char_length(v_phone) = 10 and left(v_phone, 1) = '1' then
    v_number := '880' || v_phone;
  else
    v_number := v_phone;
  end if;

  if coalesce(new.event_snapshot->>'notificationDisposition', '') = 'audit_only'
     or new.supplier_operation = 'MigrationBaseline' then
    v_state := 'suppressed';
    v_suppression_reason := 'historical_or_audit_only';
  elsif v_booking.audience <> 'agency' then
    v_state := 'suppressed';
    v_suppression_reason := 'b2b_partner_only';
  elsif v_booking.hidden_from_user then
    v_state := 'suppressed';
    v_suppression_reason := 'booking_hidden_from_user';
  elsif coalesce(v_number, '') !~ '^[1-9][0-9]{7,14}$' then
    v_state := 'suppressed';
    v_suppression_reason := 'missing_or_invalid_b2b_partner_phone';
  end if;

  if jsonb_typeof(v_booking.airlines_pnr) = 'array' then
    v_pnr := nullif(btrim(v_booking.airlines_pnr->>0), '');
  end if;
  v_pnr := coalesce(
    v_pnr,
    nullif(btrim(v_booking.pnr), ''),
    nullif(btrim(v_booking.booking_ref_number), ''),
    '--'
  );
  v_passenger_name := btrim(concat_ws(' ',
    nullif(btrim(v_booking.passengers #>> '{travellers,0,firstName}'), ''),
    nullif(btrim(v_booking.passengers #>> '{travellers,0,lastName}'), '')
  ));

  insert into public.booking_issued_sms_deliveries (
    lifecycle_event_id, booking_id, occurrence_id,
    recipient_number, recipient_number_hash, content_snapshot,
    state, suppression_reason, completed_at
  ) values (
    new.id, new.booking_id, new.occurrence_id,
    case when v_state = 'suppressed' then null else v_number end,
    case when v_state = 'suppressed' then null
      else encode(digest(v_number, 'sha256'), 'hex') end,
    jsonb_build_object(
      'version', 1,
      'bookingReference', v_booking.public_ref,
      'pnr', v_pnr,
      'passengerName', v_passenger_name,
      'airlineCode', coalesce(v_booking.itinerary->>'carrierCode', ''),
      'airlineName', coalesce(v_booking.itinerary->>'carrierName', ''),
      'itinerary', coalesce(v_booking.itinerary, 'null'::jsonb),
      'currency', v_booking.currency,
      'grossAmount', v_booking.pricing_snapshot->'grossPrice'
    ),
    v_state, v_suppression_reason,
    case when v_state = 'suppressed' then clock_timestamp() else null end
  )
  on conflict (lifecycle_event_id) do nothing;
  return new;
end;
$$;

create trigger booking_status_events_enqueue_issued_sms
  after insert on public.booking_status_events
  for each row
  when (new.to_lifecycle_status = 'confirmed')
  execute function public.enqueue_booking_issued_sms_v1();

-- Serialize Hide with SMS claim. If claim won, Hide reports the same retryable
-- conflict used for in-flight email. If Hide won, the pending SMS is retained
-- as suppressed evidence and Restore never sends it later.
create or replace function public.guard_and_suppress_hidden_booking_sms_v1()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if coalesce(old.hidden_from_user, false) = false
     and coalesce(new.hidden_from_user, false) = true then
    if exists (
      select 1 from public.booking_issued_sms_deliveries delivery
       where delivery.booking_id = new.id
         and delivery.state = 'processing'
    ) then
      raise exception 'NOTIFICATION_DELIVERY_IN_PROGRESS'
        using errcode = '55000';
    end if;
    update public.booking_issued_sms_deliveries delivery
       set state = 'suppressed',
           recipient_number = null,
           recipient_number_hash = null,
           suppression_reason = 'booking_hidden_from_user',
           completed_at = clock_timestamp(),
           claimed_at = null,
           claim_token = null,
           last_error = null
     where delivery.booking_id = new.id
       and delivery.state in ('pending', 'retry');
  end if;
  return new;
end;
$$;

create trigger flight_bookings_guard_and_suppress_hidden_sms
  before update of hidden_from_user on public.flight_bookings
  for each row execute function public.guard_and_suppress_hidden_booking_sms_v1();

create or replace function public.claim_booking_issued_sms_v1(
  p_limit integer default 10,
  p_booking_id uuid default null
)
returns table (
  delivery_id uuid,
  booking_id uuid,
  occurrence_id uuid,
  recipient_number text,
  recipient_number_hash text,
  content_snapshot jsonb,
  delivery_claim_token uuid,
  attempt_count integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_candidate record;
  v_booking public.flight_bookings;
  v_delivery public.booking_issued_sms_deliveries;
  v_returned integer := 0;
begin
  for v_candidate in
    select candidate.id, candidate.booking_id
      from public.booking_issued_sms_deliveries candidate
     where candidate.state in ('pending', 'retry')
       and candidate.available_at <= clock_timestamp()
       and candidate.attempt_count < candidate.max_attempts
       and (p_booking_id is null or candidate.booking_id = p_booking_id)
     order by candidate.available_at, candidate.created_at, candidate.id
     limit greatest(1, least(coalesce(p_limit, 10), 50)) * 4
  loop
    select booking.* into v_booking
      from public.flight_bookings booking
     where booking.id = v_candidate.booking_id
     for update;
    if not found then
      continue;
    end if;

    select candidate.* into v_delivery
      from public.booking_issued_sms_deliveries candidate
     where candidate.id = v_candidate.id
     for update;
    if not found
       or v_delivery.state not in ('pending', 'retry')
       or v_delivery.available_at > clock_timestamp()
       or v_delivery.attempt_count >= v_delivery.max_attempts then
      continue;
    end if;

    if v_booking.audience = 'agency' and v_booking.hidden_from_user then
      update public.booking_issued_sms_deliveries delivery
         set state = 'suppressed', recipient_number = null,
             recipient_number_hash = null,
             suppression_reason = 'booking_hidden_from_user',
             completed_at = clock_timestamp(), claimed_at = null,
             claim_token = null, last_error = null
       where delivery.id = v_delivery.id;
      continue;
    end if;

    update public.booking_issued_sms_deliveries delivery
       set state = 'processing', claimed_at = clock_timestamp(),
           claim_token = gen_random_uuid(),
           attempt_count = delivery.attempt_count + 1,
           last_error = null
     where delivery.id = v_delivery.id
     returning delivery.* into v_delivery;

    delivery_id := v_delivery.id;
    booking_id := v_delivery.booking_id;
    occurrence_id := v_delivery.occurrence_id;
    recipient_number := v_delivery.recipient_number;
    recipient_number_hash := v_delivery.recipient_number_hash;
    content_snapshot := v_delivery.content_snapshot;
    delivery_claim_token := v_delivery.claim_token;
    attempt_count := v_delivery.attempt_count;
    return next;

    v_returned := v_returned + 1;
    exit when v_returned >= greatest(1, least(coalesce(p_limit, 10), 50));
  end loop;
end;
$$;

create or replace function public.mark_booking_issued_sms_sent_v1(
  p_delivery_id uuid,
  p_claim_token uuid,
  p_provider_message_id text default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.booking_issued_sms_deliveries delivery
     set state = 'sent', sent_at = clock_timestamp(),
         completed_at = clock_timestamp(), claimed_at = null,
         claim_token = null,
         provider_message_id = nullif(left(p_provider_message_id, 500), ''),
         last_error = null
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_claim_token;
  return found;
end;
$$;

create or replace function public.fail_booking_issued_sms_v1(
  p_delivery_id uuid,
  p_claim_token uuid,
  p_error text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_state text;
begin
  update public.booking_issued_sms_deliveries delivery
     set state = case when delivery.attempt_count >= delivery.max_attempts
           then 'dead_letter' else 'retry' end,
         available_at = case when delivery.attempt_count >= delivery.max_attempts
           then delivery.available_at
           else clock_timestamp()
             + make_interval(mins => least(delivery.attempt_count * 5, 60)) end,
         completed_at = case when delivery.attempt_count >= delivery.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = left(coalesce(p_error, 'SMS delivery failed.'), 1000)
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_claim_token
  returning delivery.state into v_state;
  if not found then
    raise exception 'issued SMS claim mismatch' using errcode = '40001';
  end if;
  return v_state;
end;
$$;

create or replace function public.recover_stale_booking_issued_sms_claims_v1(
  p_limit integer default 100
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare v_count integer;
begin
  with stale as (
    select candidate.id
      from public.booking_issued_sms_deliveries candidate
     where candidate.state = 'processing'
       and candidate.claimed_at < clock_timestamp() - interval '10 minutes'
     order by candidate.claimed_at, candidate.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.booking_issued_sms_deliveries delivery
     set state = case when delivery.attempt_count >= delivery.max_attempts
           then 'dead_letter' else 'retry' end,
         available_at = clock_timestamp(),
         completed_at = case when delivery.attempt_count >= delivery.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = 'Stale SMS delivery claim recovered.'
    from stale
   where delivery.id = stale.id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

