-- SOURCE: 0150_booking_manual_sms_editable_recipient.sql
-- Editable manual SMS copy and up to three distinct Bangladesh recipients.

alter table public.booking_manual_sms_deliveries
  add column message_text text;

alter table public.booking_manual_sms_deliveries
  add constraint booking_manual_sms_message_check check (
    message_text is null or char_length(btrim(message_text)) between 1 and 480
  );

create or replace function public.normalize_booking_sms_number_v1(p_phone text)
returns text
language plpgsql
immutable
set search_path = public
as $$
declare
  v_phone text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  v_number text;
begin
  if left(v_phone, 2) = '00' then
    v_number := substr(v_phone, 3);
  elsif left(v_phone, 3) = '880' then
    v_number := v_phone;
  elsif left(v_phone, 2) = '01' then
    v_number := '880' || substr(v_phone, 2);
  elsif char_length(v_phone) = 10 and left(v_phone, 1) = '1' then
    v_number := '880' || v_phone;
  else
    v_number := v_phone;
  end if;
  if coalesce(v_number, '') !~ '^8801[3-9][0-9]{8}$' then
    raise exception 'BOOKING_SMS_RECIPIENT_UNAVAILABLE' using errcode = 'P0001';
  end if;
  return v_number;
end;
$$;

create or replace function public.read_booking_manual_sms_status_v2(
  p_booking_id uuid
)
returns table (
  recipient_number text,
  sent_count integer,
  reserved_count integer,
  remaining_sends integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_phone text;
  v_suggested_number text := '';
begin
  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id;
  if not found
     or v_booking.audience <> 'agency'
     or v_booking.agency_code is null
     or v_booking.hidden_from_user then
    raise exception 'BOOKING_SMS_UNAVAILABLE' using errcode = 'P0001';
  end if;
  if v_booking.status <> 'confirmed' then
    raise exception 'BOOKING_SMS_NOT_CONFIRMED' using errcode = 'P0001';
  end if;

  select profile.agency_mobile into v_phone
    from public.agencies agency
    join public.user_profiles profile on profile.clerk_id = agency.owner_user_id
   where agency.agency_code = v_booking.agency_code;
  begin
    v_suggested_number := public.normalize_booking_sms_number_v1(v_phone);
  exception when others then
    v_suggested_number := '';
  end;

  select
    count(*) filter (where delivery.state = 'sent')::integer,
    count(*) filter (where delivery.state in ('sent', 'processing'))::integer
    into sent_count, reserved_count
    from public.booking_manual_sms_deliveries delivery
   where delivery.booking_id = p_booking_id;
  if v_suggested_number <> '' and exists (
    select 1 from public.booking_manual_sms_deliveries delivery
     where delivery.booking_id = p_booking_id
       and delivery.recipient_number = v_suggested_number
       and delivery.state in ('sent', 'processing')
  ) then
    v_suggested_number := '';
  end if;
  recipient_number := v_suggested_number;
  remaining_sends := greatest(0, 3 - reserved_count);
  return next;
end;
$$;

create or replace function public.claim_booking_manual_sms_send_v2(
  p_booking_id uuid,
  p_actor_user_id text,
  p_request_id uuid,
  p_recipient_number text,
  p_message_text text
)
returns table (
  delivery_id uuid,
  recipient_number text,
  message_text text,
  claim_token uuid,
  claim_state text,
  sent_count integer,
  reserved_count integer,
  remaining_sends integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking public.flight_bookings;
  v_delivery public.booking_manual_sms_deliveries;
  v_number text;
  v_message text := btrim(coalesce(p_message_text, ''));
begin
  if nullif(btrim(p_actor_user_id), '') is null then
    raise exception 'BOOKING_SMS_UNAVAILABLE' using errcode = 'P0001';
  end if;
  if char_length(v_message) not between 1 and 480 then
    raise exception 'BOOKING_SMS_MESSAGE_INVALID' using errcode = 'P0001';
  end if;

  select booking.* into v_booking
    from public.flight_bookings booking
   where booking.id = p_booking_id
   for update;
  if not found then
    raise exception 'BOOKING_SMS_UNAVAILABLE' using errcode = 'P0001';
  end if;
  if v_booking.audience <> 'agency'
     or v_booking.agency_code is null
     or v_booking.hidden_from_user then
    raise exception 'BOOKING_SMS_UNAVAILABLE' using errcode = 'P0001';
  end if;
  if v_booking.status <> 'confirmed' then
    raise exception 'BOOKING_SMS_NOT_CONFIRMED' using errcode = 'P0001';
  end if;
  v_number := public.normalize_booking_sms_number_v1(p_recipient_number);

  select delivery.* into v_delivery
    from public.booking_manual_sms_deliveries delivery
   where delivery.booking_id = p_booking_id
     and delivery.request_id = p_request_id;

  select
    count(*) filter (where delivery.state = 'sent')::integer,
    count(*) filter (where delivery.state in ('sent', 'processing'))::integer
    into sent_count, reserved_count
    from public.booking_manual_sms_deliveries delivery
   where delivery.booking_id = p_booking_id;

  if v_delivery.id is not null and v_delivery.state = 'sent' then
    delivery_id := v_delivery.id;
    recipient_number := v_delivery.recipient_number;
    message_text := coalesce(v_delivery.message_text, v_message);
    claim_token := coalesce(v_delivery.claim_token, gen_random_uuid());
    claim_state := 'sent';
    remaining_sends := greatest(0, 3 - reserved_count);
    return next;
    return;
  elsif v_delivery.id is not null and v_delivery.state = 'processing' then
    delivery_id := v_delivery.id;
    recipient_number := v_delivery.recipient_number;
    message_text := coalesce(v_delivery.message_text, v_message);
    claim_token := v_delivery.claim_token;
    claim_state := 'processing';
    remaining_sends := greatest(0, 3 - reserved_count);
    return next;
    return;
  end if;

  if exists (
    select 1 from public.booking_manual_sms_deliveries delivery
     where delivery.booking_id = p_booking_id
       and delivery.recipient_number = v_number
       and delivery.state in ('sent', 'processing')
       and delivery.request_id <> p_request_id
  ) then
    raise exception 'BOOKING_SMS_RECIPIENT_ALREADY_USED' using errcode = 'P0001';
  end if;
  if reserved_count >= 3 then
    raise exception 'BOOKING_SMS_LIMIT_REACHED' using errcode = 'P0001';
  end if;

  if v_delivery.id is not null then
    update public.booking_manual_sms_deliveries delivery
       set actor_user_id = p_actor_user_id,
           recipient_number = v_number,
           recipient_number_hash = encode(digest(v_number, 'sha256'), 'hex'),
           content_snapshot = jsonb_build_object('version', 2, 'message', v_message),
           message_text = v_message,
           state = 'processing', claim_token = gen_random_uuid(),
           attempt_count = delivery.attempt_count + 1,
           sent_at = null, completed_at = null,
           provider_message_id = null, last_error = null
     where delivery.id = v_delivery.id
     returning delivery.* into v_delivery;
  else
    insert into public.booking_manual_sms_deliveries (
      booking_id, actor_user_id, request_id,
      recipient_number, recipient_number_hash,
      content_snapshot, message_text, state, claim_token
    ) values (
      p_booking_id, p_actor_user_id, p_request_id,
      v_number, encode(digest(v_number, 'sha256'), 'hex'),
      jsonb_build_object('version', 2, 'message', v_message),
      v_message, 'processing', gen_random_uuid()
    ) returning * into v_delivery;
  end if;

  delivery_id := v_delivery.id;
  recipient_number := v_delivery.recipient_number;
  message_text := v_delivery.message_text;
  claim_token := v_delivery.claim_token;
  claim_state := 'claimed';
  reserved_count := reserved_count + 1;
  remaining_sends := greatest(0, 3 - reserved_count);
  return next;
end;
$$;

revoke all on function public.normalize_booking_sms_number_v1(text),
  public.read_booking_manual_sms_status_v2(uuid),
  public.claim_booking_manual_sms_send_v2(uuid,text,uuid,text,text)
  from public, anon, authenticated;
grant execute on function public.normalize_booking_sms_number_v1(text),
  public.read_booking_manual_sms_status_v2(uuid),
  public.claim_booking_manual_sms_send_v2(uuid,text,uuid,text,text)
  to service_role;

comment on column public.booking_manual_sms_deliveries.message_text is
  'The exact user-reviewed message submitted to BulkSMSBD for this attempt.';


-- SOURCE: 0151_booking_sms_pgcrypto_search_path.sql
-- Supabase installs pgcrypto in `extensions`, while PGlite/local installations
-- may expose it in `public`. Keep both schemas in the runtime lookup path for
-- the three SMS functions that hash recipient numbers.

alter function public.enqueue_booking_issued_sms_v1()
  set search_path = public, extensions;

alter function public.claim_booking_manual_sms_send_v1(uuid,text,uuid,jsonb)
  set search_path = public, extensions;

alter function public.claim_booking_manual_sms_send_v2(uuid,text,uuid,text,text)
  set search_path = public, extensions;


-- SOURCE: 0152_deposit_approved_sms.sql
-- Durable confirmation SMS for approved B2B wallet deposit requests.
-- The intent is inserted by the same transaction that credits the wallet.

create table public.deposit_approved_sms_deliveries (
  id                     uuid primary key default gen_random_uuid(),
  deposit_request_id     uuid not null unique
                           references public.wallet_deposit_requests (id)
                           on delete restrict,
  recipient_number       text,
  recipient_number_hash  text,
  content_snapshot       jsonb not null,
  state                  text not null default 'pending',
  available_at           timestamptz not null default now(),
  claimed_at             timestamptz,
  claim_token            uuid,
  attempt_count          integer not null default 0,
  max_attempts           integer not null default 8,
  sent_at                timestamptz,
  completed_at           timestamptz,
  provider_message_id    text,
  last_error             text,
  suppression_reason     text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint deposit_approved_sms_state_check check (state in (
    'pending', 'processing', 'retry', 'sent', 'suppressed', 'dead_letter'
  )),
  constraint deposit_approved_sms_recipient_check check (
    (state = 'suppressed' and recipient_number is null
      and recipient_number_hash is null)
    or (recipient_number ~ '^[1-9][0-9]{7,14}$'
      and recipient_number_hash ~ '^[a-f0-9]{64}$')
  ),
  constraint deposit_approved_sms_snapshot_check check (
    jsonb_typeof(content_snapshot) = 'object'
  ),
  constraint deposit_approved_sms_attempt_check check (
    attempt_count >= 0 and max_attempts between 1 and 20
  )
);

create trigger deposit_approved_sms_touch_updated_at
  before update on public.deposit_approved_sms_deliveries
  for each row execute function public.touch_updated_at();

create index deposit_approved_sms_claim_idx
  on public.deposit_approved_sms_deliveries (available_at, created_at, id)
  where state in ('pending', 'retry');

create or replace function public.enqueue_deposit_approved_sms_v1()
returns trigger
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_owner_type text;
  v_owner_key text;
  v_phone text;
  v_number text;
  v_state text := 'pending';
  v_suppression_reason text;
begin
  select wallet.owner_type, wallet.owner_key
    into v_owner_type, v_owner_key
    from public.wallet_accounts account
    join public.wallets wallet on wallet.id = account.wallet_id
   where account.id = new.wallet_account_id;

  if v_owner_type = 'agency' then
    select regexp_replace(coalesce(profile.agency_mobile, ''), '[^0-9]', '', 'g')
      into v_phone
      from public.agencies agency
      join public.user_profiles profile on profile.clerk_id = agency.owner_user_id
     where agency.agency_code = v_owner_key;
  end if;
  v_phone := coalesce(v_phone, '');

  if left(v_phone, 2) = '00' then
    v_number := substr(v_phone, 3);
  elsif left(v_phone, 3) = '880' then
    v_number := v_phone;
  elsif left(v_phone, 2) = '01' then
    v_number := '880' || substr(v_phone, 2);
  elsif char_length(v_phone) = 10 and left(v_phone, 1) = '1' then
    v_number := '880' || v_phone;
  else
    v_number := v_phone;
  end if;

  if v_owner_type <> 'agency' then
    v_state := 'suppressed';
    v_suppression_reason := 'b2b_partner_only';
  elsif coalesce(v_number, '') !~ '^[1-9][0-9]{7,14}$' then
    v_state := 'suppressed';
    v_suppression_reason := 'missing_or_invalid_b2b_partner_phone';
  end if;

  insert into public.deposit_approved_sms_deliveries (
    deposit_request_id, recipient_number, recipient_number_hash,
    content_snapshot, state, suppression_reason, completed_at
  ) values (
    new.id,
    case when v_state = 'suppressed' then null else v_number end,
    case when v_state = 'suppressed' then null
      else encode(digest(v_number, 'sha256'), 'hex') end,
    jsonb_build_object(
      'version', 1,
      'requestReference', new.public_ref,
      'currency', new.currency,
      'amountMinor', new.amount
    ),
    v_state,
    v_suppression_reason,
    case when v_state = 'suppressed' then clock_timestamp() else null end
  )
  on conflict (deposit_request_id) do nothing;
  return new;
end;
$$;

create trigger wallet_deposit_requests_enqueue_approved_sms
  after update of status on public.wallet_deposit_requests
  for each row
  when (new.status = 'approved' and old.status is distinct from new.status)
  execute function public.enqueue_deposit_approved_sms_v1();

create or replace function public.claim_deposit_approved_sms_v1(
  p_limit integer default 10,
  p_deposit_request_id uuid default null
)
returns table (
  delivery_id uuid,
  deposit_request_id uuid,
  recipient_number text,
  recipient_number_hash text,
  content_snapshot jsonb,
  delivery_claim_token uuid,
  attempt_count integer
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with candidates as (
    select delivery.id
      from public.deposit_approved_sms_deliveries delivery
     where delivery.state in ('pending', 'retry')
       and delivery.available_at <= clock_timestamp()
       and delivery.attempt_count < delivery.max_attempts
       and (p_deposit_request_id is null
         or delivery.deposit_request_id = p_deposit_request_id)
     order by delivery.available_at, delivery.created_at, delivery.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 10), 50))
  ), claimed as (
    update public.deposit_approved_sms_deliveries delivery
       set state = 'processing', claimed_at = clock_timestamp(),
           claim_token = gen_random_uuid(),
           attempt_count = delivery.attempt_count + 1,
           last_error = null
      from candidates
     where delivery.id = candidates.id
    returning delivery.*
  )
  select claimed.id, claimed.deposit_request_id,
         claimed.recipient_number, claimed.recipient_number_hash,
         claimed.content_snapshot, claimed.claim_token,
         claimed.attempt_count
    from claimed
   order by claimed.created_at, claimed.id;
end;
$$;

create or replace function public.mark_deposit_approved_sms_sent_v1(
  p_delivery_id uuid,
  p_claim_token uuid,
  p_provider_message_id text default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.deposit_approved_sms_deliveries delivery
     set state = 'sent', sent_at = clock_timestamp(),
         completed_at = clock_timestamp(), claimed_at = null,
         claim_token = null,
         provider_message_id = nullif(left(p_provider_message_id, 500), ''),
         last_error = null
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_claim_token;
  return found;
end;
$$;

create or replace function public.fail_deposit_approved_sms_v1(
  p_delivery_id uuid,
  p_claim_token uuid,
  p_error text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_state text;
begin
  update public.deposit_approved_sms_deliveries delivery
     set state = case when delivery.attempt_count >= delivery.max_attempts
           then 'dead_letter' else 'retry' end,
         available_at = case when delivery.attempt_count >= delivery.max_attempts
           then delivery.available_at
           else clock_timestamp()
             + make_interval(mins => least(delivery.attempt_count * 5, 60)) end,
         completed_at = case when delivery.attempt_count >= delivery.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = left(coalesce(p_error, 'SMS delivery failed.'), 1000)
   where delivery.id = p_delivery_id
     and delivery.state = 'processing'
     and delivery.claim_token = p_claim_token
  returning delivery.state into v_state;
  if not found then
    raise exception 'deposit approval SMS claim mismatch' using errcode = '40001';
  end if;
  return v_state;
end;
$$;

create or replace function public.recover_stale_deposit_approved_sms_claims_v1(
  p_limit integer default 100
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare v_count integer;
begin
  with stale as (
    select delivery.id
      from public.deposit_approved_sms_deliveries delivery
     where delivery.state = 'processing'
       and delivery.claimed_at < clock_timestamp() - interval '10 minutes'
     order by delivery.claimed_at, delivery.id
     for update skip locked
     limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.deposit_approved_sms_deliveries delivery
     set state = case when delivery.attempt_count >= delivery.max_attempts
           then 'dead_letter' else 'retry' end,
         available_at = clock_timestamp(),
         completed_at = case when delivery.attempt_count >= delivery.max_attempts
           then clock_timestamp() else null end,
         claimed_at = null,
         claim_token = null,
         last_error = 'Stale SMS delivery claim recovered.'
    from stale
   where delivery.id = stale.id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

alter table public.deposit_approved_sms_deliveries enable row level security;
revoke all on table public.deposit_approved_sms_deliveries
  from public, anon, authenticated, service_role;
grant select, insert, update on table public.deposit_approved_sms_deliveries
  to service_role;

revoke all on function public.enqueue_deposit_approved_sms_v1()
  from public, anon, authenticated, service_role;
revoke all on function public.claim_deposit_approved_sms_v1(integer,uuid),
  public.mark_deposit_approved_sms_sent_v1(uuid,uuid,text),
  public.fail_deposit_approved_sms_v1(uuid,uuid,text),
  public.recover_stale_deposit_approved_sms_claims_v1(integer)
  from public, anon, authenticated;
grant execute on function public.claim_deposit_approved_sms_v1(integer,uuid),
  public.mark_deposit_approved_sms_sent_v1(uuid,uuid,text),
  public.fail_deposit_approved_sms_v1(uuid,uuid,text),
  public.recover_stale_deposit_approved_sms_claims_v1(integer)
  to service_role;

comment on table public.deposit_approved_sms_deliveries is
  'One durable, retryable B2B partner SMS intent for each approved deposit request.';


-- SOURCE: 0153_deposit_request_admin_sms.sql
-- Durable new-deposit alerts for explicitly configured new-company recipients.
-- No recipients are seeded; future requests create one delivery per enabled number.

create table public.deposit_request_admin_sms_deliveries (
  id                     uuid primary key default gen_random_uuid(),
  deposit_request_id     uuid not null
                           references public.wallet_deposit_requests (id)
                           on delete restrict,
  recipient_number       text not null,
  recipient_number_hash  text not null,
  content_snapshot       jsonb not null,
  state                  text not null default 'pending',
  available_at           timestamptz not null default now(),
  claimed_at             timestamptz,
  claim_token            uuid,
  attempt_count          integer not null default 0,
  max_attempts           integer not null default 8,
  sent_at                timestamptz,
  completed_at           timestamptz,
  provider_message_id    text,
  last_error             text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint deposit_request_admin_sms_recipient_unique
    unique (deposit_request_id, recipient_number_hash),
  constraint deposit_request_admin_sms_state_check check (state in (
    'pending', 'processing', 'retry', 'sent', 'dead_letter'
  )),
  constraint deposit_request_admin_sms_recipient_check check (
    recipient_number ~ '^[1-9][0-9]{7,14}$'
    and recipient_number_hash ~ '^[a-f0-9]{64}$'
  ),
  constraint deposit_request_admin_sms_snapshot_check check (
    jsonb_typeof(content_snapshot) = 'object'
  ),
  constraint deposit_request_admin_sms_attempt_check check (
    attempt_count >= 0 and max_attempts between 1 and 20
  )
);

create trigger deposit_request_admin_sms_touch_updated_at
  before update on public.deposit_request_admin_sms_deliveries
  for each row execute function public.touch_updated_at();

create index deposit_request_admin_sms_claim_idx
  on public.deposit_request_admin_sms_deliveries (available_at, created_at, id)
  where state in ('pending', 'retry');

create or replace function public.enqueue_deposit_request_admin_sms_v1()
returns trigger
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_owner_type text;
  v_owner_key text;
  v_agency_name text;
  v_bank_name text;
  v_branch_name text;
  v_mfs_name text;
  v_payment_method text;
  v_number text;
  v_snapshot jsonb;
begin
  select wallet.owner_type, wallet.owner_key
    into v_owner_type, v_owner_key
    from public.wallet_accounts account
    join public.wallets wallet on wallet.id = account.wallet_id
   where account.id = new.wallet_account_id;

  -- This notification identifies an agency, so personal/B2C wallets are not
  -- sent to the static admin recipients.
  if v_owner_type is distinct from 'agency' then
    return new;
  end if;

  select coalesce(nullif(btrim(profile.agency_name), ''), v_owner_key)
    into v_agency_name
    from public.agencies agency
    left join public.user_profiles profile on profile.clerk_id = agency.owner_user_id
   where agency.agency_code = v_owner_key;
  v_agency_name := coalesce(v_agency_name, v_owner_key, 'Unknown Agency');

  if new.company_bank_account_id is not null then
    select nullif(btrim(account.bank_name), '') into v_bank_name
      from public.wallet_company_bank_accounts account
     where account.id = new.company_bank_account_id;
  end if;
  if new.branch_id is not null then
    select nullif(btrim(branch.name), '') into v_branch_name
      from public.wallet_payment_branches branch
     where branch.id = new.branch_id;
  end if;
  if new.mfs_account_id is not null then
    select nullif(btrim(account.mfs_name), '') into v_mfs_name
      from public.wallet_company_mfs_accounts account
     where account.id = new.mfs_account_id;
  end if;

  v_payment_method := case new.method
    when 'cash' then concat_ws(' - ', 'Cash', v_branch_name)
    when 'bank' then concat_ws(' - ', 'Bank Deposit', v_bank_name)
    when 'bank_transfer' then concat_ws(' - ', 'Bank Transfer', v_bank_name)
    when 'mobile' then coalesce(nullif(btrim(new.mfs_provider), ''), v_mfs_name,
      'Mobile Financial Service')
    when 'cheque' then concat_ws(' - ', 'Cheque',
      coalesce(nullif(btrim(new.cheque_issued_bank), ''), v_bank_name))
    else initcap(replace(new.method, '_', ' '))
  end;

  v_snapshot := jsonb_build_object(
    'version', 1,
    'requestReference', new.public_ref,
    'agencyName', v_agency_name,
    'paymentMethod', v_payment_method,
    'currency', new.currency,
    'amountMinor', coalesce(new.gross_amount, new.amount)
  );

  for v_number in select phone from public.company_admin_sms_recipients where enabled loop
    insert into public.deposit_request_admin_sms_deliveries (
      deposit_request_id, recipient_number, recipient_number_hash,
      content_snapshot
    ) values (
      new.id, v_number, encode(digest(v_number, 'sha256'), 'hex'), v_snapshot
    )
    on conflict (deposit_request_id, recipient_number_hash) do nothing;
  end loop;
  return new;
end;
$$;

create trigger wallet_deposit_requests_enqueue_admin_sms
  after insert on public.wallet_deposit_requests
  for each row execute function public.enqueue_deposit_request_admin_sms_v1();

create or replace function public.claim_deposit_request_admin_sms_v1(
  p_limit integer default 10,
  p_deposit_request_id uuid default null
)
returns table (
  delivery_id uuid,
  deposit_request_id uuid,
  recipient_number text,
  recipient_number_hash text,
